open Ast

module StringMap = Map.Make (String)
module LabelSet = Set.Make (String)
module IntSet = Set.Make (Int)

module PlaceOrd = struct
  type t = Tcg.place

  let compare = Stdlib.compare
end

module PlaceSet = Set.Make (PlaceOrd)
module PlaceMap = Map.Make (PlaceOrd)
module IntMap = Map.Make (Int)

module InstrKeyOrd = struct
  type t = string * int

  let compare = Stdlib.compare
end

module InstrKeySet = Set.Make (InstrKeyOrd)

type const_cell =
  | Known of int64
  | Unknown

type const_env = const_cell StringMap.t list

type inline_func = {
  params : string list;
  body_stmts : stmt list;
  cost : int;
  param_uses : int StringMap.t;
}

let truth n = n <> 0L

let bool_int b = if b then 1L else 0L

let int32_modulus = 0x1_0000_0000L
let int32_sign_bit = 0x8000_0000L
let int32_mask = 0xFFFF_FFFFL
let int32_signed_max = 2147483647L

let i32 value =
  let masked = Int64.logand value int32_mask in
  if masked >= int32_sign_bit then Int64.sub masked int32_modulus else masked

let has_prefix prefix text =
  let prefix_len = String.length prefix in
  String.length text >= prefix_len && String.sub text 0 prefix_len = prefix

let empty_env = [ StringMap.empty ]

let push_scope env = StringMap.empty :: env

let add_binding env name value =
  match env with
  | scope :: rest -> StringMap.add name value scope :: rest
  | [] -> [ StringMap.singleton name value ]

let add_const env name value = add_binding env name (Known value)

let add_shadow env name = add_binding env name Unknown

let find_const env name =
  let rec loop = function
    | [] -> None
    | scope :: rest -> (
        match StringMap.find_opt name scope with
        | Some (Known v) -> Some v
        | Some Unknown -> None
        | None -> loop rest)
  in
  loop env

let fold_binop op a b =
  let a = i32 a in
  let b = i32 b in
  match op with
  | Add -> Some (i32 Int64.(add a b))
  | Sub -> Some (i32 Int64.(sub a b))
  | Mul -> Some (i32 Int64.(mul a b))
  | Div -> if b = 0L then None else Some (i32 Int64.(div a b))
  | Mod -> if b = 0L then None else Some (i32 Int64.(rem a b))
  | Lt -> Some (bool_int (a < b))
  | Gt -> Some (bool_int (a > b))
  | Le -> Some (bool_int (a <= b))
  | Ge -> Some (bool_int (a >= b))
  | Eq -> Some (bool_int (a = b))
  | Ne -> Some (bool_int (a <> b))
  | LAnd -> Some (bool_int (truth a && truth b))
  | LOr -> Some (bool_int (truth a || truth b))

let rec expr_has_call = function
  | Int _ | Var _ -> false
  | Call _ -> true
  | Unary (_, e) -> expr_has_call e
  | Binary (_, lhs, rhs) -> expr_has_call lhs || expr_has_call rhs

let expr_is_pure expr = not (expr_has_call expr)

let rec expr_cost = function
  | Int _ | Var _ -> 1
  | Call (_, args) ->
      1 + List.fold_left (fun acc arg -> acc + expr_cost arg) 0 args
  | Unary (_, e) -> 1 + expr_cost e
  | Binary (_, lhs, rhs) -> 1 + expr_cost lhs + expr_cost rhs

let rec expr_var_uses counts = function
  | Int _ -> counts
  | Var name ->
      let count = Option.value ~default:0 (StringMap.find_opt name counts) in
      StringMap.add name (count + 1) counts
  | Call (_, args) -> List.fold_left expr_var_uses counts args
  | Unary (_, e) -> expr_var_uses counts e
  | Binary (_, lhs, rhs) -> expr_var_uses (expr_var_uses counts lhs) rhs

let rec stmt_cost = function
  | Block stmts -> 1 + List.fold_left (fun acc stmt -> acc + stmt_cost stmt) 0 stmts
  | Empty -> 0
  | Expr expr -> 1 + expr_cost expr
  | Assign (_, expr) -> 1 + expr_cost expr
  | Decl d -> 1 + expr_cost d.init
  | If (cond, t, e) ->
      let else_cost =
        match e with
        | Some else_stmt -> stmt_cost else_stmt
        | None -> 0
      in
      1 + expr_cost cond + stmt_cost t + else_cost
  | While (cond, body) -> 1 + expr_cost cond + stmt_cost body
  | Break | Continue -> 1
  | Return None -> 1
  | Return (Some expr) -> 1 + expr_cost expr

let rec stmt_var_uses counts = function
  | Block stmts -> List.fold_left stmt_var_uses counts stmts
  | Empty | Break | Continue | Return None -> counts
  | Expr expr -> expr_var_uses counts expr
  | Assign (_, expr) -> expr_var_uses counts expr
  | Decl d -> expr_var_uses counts d.init
  | If (cond, t, e) ->
      let counts = expr_var_uses counts cond in
      let counts = stmt_var_uses counts t in
      begin
        match e with
        | Some else_stmt -> stmt_var_uses counts else_stmt
        | None -> counts
      end
  | While (cond, body) -> stmt_var_uses (expr_var_uses counts cond) body
  | Return (Some expr) -> expr_var_uses counts expr

let stmt_list_cost stmts =
  List.fold_left (fun acc stmt -> acc + stmt_cost stmt) 0 stmts

let stmt_list_var_uses counts stmts =
  List.fold_left stmt_var_uses counts stmts

let rec inline_stmt_template_supported = function
  | Block stmts -> List.for_all inline_stmt_template_supported stmts
  | Empty -> true
  | Expr _ | Assign _ | Decl _ | Return (Some _) -> true
  | If (_, t, e) ->
      let else_supported =
        match e with
        | Some else_stmt -> inline_stmt_template_supported else_stmt
        | None -> true
      in
      inline_stmt_template_supported t && else_supported
  | While _ | Break | Continue -> false
  | Return None -> false

let inline_expr_limit = 28
let inline_expr_depth_limit = 6

type inline_scope_env = expr StringMap.t list

type inline_stmt_result =
  | InlineContinue of inline_scope_env
  | InlineReturn of expr

let empty_inline_scope = [ StringMap.empty ]

let push_inline_scope env = StringMap.empty :: env

let pop_inline_scope = function
  | _ :: rest -> rest
  | [] -> []

let add_inline_binding env name value =
  match env with
  | scope :: rest -> StringMap.add name value scope :: rest
  | [] -> [ StringMap.singleton name value ]

let rec find_inline_binding env name =
  match env with
  | [] -> None
  | scope :: rest -> (
      match StringMap.find_opt name scope with
      | Some value -> Some value
      | None -> find_inline_binding rest name)

let rec set_inline_binding env name value =
  match env with
  | [] -> None
  | scope :: rest ->
      if StringMap.mem name scope then Some (StringMap.add name value scope :: rest)
      else Option.map (fun rest -> scope :: rest) (set_inline_binding rest name value)

let rec subst_inline_expr_scoped env = function
  | Int _ as e -> e
  | Var name -> (
      match find_inline_binding env name with
      | Some value -> value
      | None -> Var name)
  | Call (name, args) -> Call (name, List.map (subst_inline_expr_scoped env) args)
  | Unary (op, e) -> Unary (op, subst_inline_expr_scoped env e)
  | Binary (op, lhs, rhs) ->
      Binary (op, subst_inline_expr_scoped env lhs, subst_inline_expr_scoped env rhs)

let rec inline_expr func_env depth = function
  | Int _ as e -> e
  | Var _ as e -> e
  | Call (name, args) ->
      let args = List.map (inline_expr func_env depth) args in
      if depth = 0 then Call (name, args)
      else
        (match StringMap.find_opt name func_env with
        | Some def
          when List.length def.params = List.length args
               && List.for_all2
                    (fun param arg ->
                      let uses = Option.value ~default:0 (StringMap.find_opt param def.param_uses) in
                      not (expr_has_call arg) || uses <= 1)
                    def.params args ->
             let subst_scope =
               List.fold_left2
                 (fun env param arg -> add_inline_binding env param arg)
                 empty_inline_scope def.params args
             in
            (match eval_inline_stmt_list func_env (depth - 1) subst_scope def.body_stmts with
            | Some (InlineReturn body) -> inline_expr func_env (depth - 1) body
            | Some (InlineContinue _) | None -> Call (name, args))
        | Some _ | None -> Call (name, args))
  | Unary (op, e) -> Unary (op, inline_expr func_env depth e)
  | Binary (op, lhs, rhs) ->
      Binary (op, inline_expr func_env depth lhs, inline_expr func_env depth rhs)

and inline_pure_expr_scoped func_env depth env expr =
  let expr = subst_inline_expr_scoped env expr in
  let expr = inline_expr func_env depth expr in
  if expr_has_call expr then None else Some expr

and eval_inline_stmt_list func_env depth env = function
  | [] -> Some (InlineContinue env)
  | Empty :: rest -> eval_inline_stmt_list func_env depth env rest
  | Expr expr :: rest -> (
      match inline_pure_expr_scoped func_env depth env expr with
      | Some _ -> eval_inline_stmt_list func_env depth env rest
      | None -> None)
  | Decl d :: rest -> (
      match inline_pure_expr_scoped func_env depth env d.init with
      | Some init ->
          eval_inline_stmt_list func_env depth (add_inline_binding env d.ident.name init) rest
      | None -> None)
  | Assign (name, expr) :: rest -> (
      match inline_pure_expr_scoped func_env depth env expr with
      | Some value -> (
          match set_inline_binding env name value with
          | Some env -> eval_inline_stmt_list func_env depth env rest
          | None -> None)
      | None -> None)
  | Block stmts :: rest -> (
      match eval_inline_stmt_list func_env depth (push_inline_scope env) stmts with
      | Some (InlineContinue inner_env) ->
          eval_inline_stmt_list func_env depth (pop_inline_scope inner_env) rest
      | Some (InlineReturn expr) -> Some (InlineReturn expr)
      | None -> None)
  | If (cond, then_stmt, else_stmt) :: rest -> (
      match inline_pure_expr_scoped func_env depth env cond with
      | Some (Int value) when truth value -> eval_inline_stmt_list func_env depth env (then_stmt :: rest)
      | Some (Int _) -> (
          match else_stmt with
          | Some else_stmt -> eval_inline_stmt_list func_env depth env (else_stmt :: rest)
          | None -> eval_inline_stmt_list func_env depth env rest)
      | Some _ | None -> None)
  | While _ :: _ -> None
  | Break :: _ | Continue :: _ -> None
  | Return (Some expr) :: _ ->
      Option.map (fun expr -> InlineReturn expr) (inline_pure_expr_scoped func_env depth env expr)
  | Return None :: _ -> None

let inline_def_of_func (f : Ast.func) =
  match f.ret with
  | TInt when List.for_all inline_stmt_template_supported f.body ->
      let cost = stmt_list_cost f.body in
      if cost <= inline_expr_limit then
        Some
          {
            params = List.map (fun (param : Ast.ident) -> param.name) f.params;
            body_stmts = f.body;
            cost;
            param_uses = stmt_list_var_uses StringMap.empty f.body;
          }
      else None
  | TInt | TVoid -> None

let rec fold_expr env = function
  | Int _ as e -> e
  | Var name -> (
      match find_const env name with
      | Some v -> Int v
      | None -> Var name)
  | Call (name, args) -> Call (name, List.map (fold_expr env) args)
  | Unary (op, e) -> (
      let e' = fold_expr env e in
      match (op, e') with
      | UPlus, Int v -> Int (i32 v)
      | UMinus, Int v -> Int (i32 (Int64.neg (i32 v)))
      | UNot, Int v -> Int (bool_int (not (truth (i32 v))))
      | _ -> Unary (op, e'))
  | Binary (LAnd, a, b) -> (
      let a' = fold_expr env a in
      match a' with
      | Int 0L -> Int 0L
      | Int _ -> (
          match fold_expr env b with
          | Int v -> Int (bool_int (truth v))
          | b' -> Binary (LAnd, a', b'))
      | _ -> Binary (LAnd, a', fold_expr env b))
  | Binary (LOr, a, b) -> (
      let a' = fold_expr env a in
      match a' with
      | Int v when truth v -> Int 1L
      | Int _ -> (
          match fold_expr env b with
          | Int v -> Int (bool_int (truth v))
          | b' -> Binary (LOr, a', b'))
      | _ -> Binary (LOr, a', fold_expr env b))
  | Binary (op, a, b) -> (
      let a' = fold_expr env a in
      let b' = fold_expr env b in
      match (a', b') with
      | Int av, Int bv -> (
          match fold_binop op av bv with
          | Some v -> Int v
          | None -> Binary (op, a', b'))
      | _ -> (
          match op with
          | Add when a' = Int 0L -> b'
          | Add when b' = Int 0L -> a'
          | Sub when b' = Int 0L -> a'
          | Sub when expr_is_pure a' && a' = b' -> Int 0L
          | Mul when (a' = Int 0L && expr_is_pure b') || (b' = Int 0L && expr_is_pure a') ->
              Int 0L
          | Mul when a' = Int 1L -> b'
          | Mul when b' = Int 1L -> a'
          | Div when b' = Int 1L -> a'
          | Mod when b' = Int 1L && expr_is_pure a' -> Int 0L
          | Eq when expr_is_pure a' && a' = b' -> Int 1L
          | Ne when expr_is_pure a' && a' = b' -> Int 0L
          | Lt when expr_is_pure a' && a' = b' -> Int 0L
          | Gt when expr_is_pure a' && a' = b' -> Int 0L
          | Le when expr_is_pure a' && a' = b' -> Int 1L
          | Ge when expr_is_pure a' && a' = b' -> Int 1L
          | _ -> Binary (op, a', b')))

let rewrite_expr_ast func_env env expr =
  fold_expr env (inline_expr func_env inline_expr_depth_limit expr)

let const_of_expr = function
  | Int v -> Some v
  | _ -> None

let rec terminates = function
  | Return _ | Break | Continue -> true
  | Block stmts -> List.exists terminates stmts
  | If (_, t, Some e) -> terminates t && terminates e
  | _ -> false

let fold_decl env d =
  let init = fold_expr env d.init in
  let env' =
    if d.is_const then
      match const_of_expr init with
      | Some v -> add_const env d.ident.name v
      | None -> add_shadow env d.ident.name
    else add_shadow env d.ident.name
  in
  ({ d with init }, env')

let fold_decl_with_inline func_env env d =
  let init = rewrite_expr_ast func_env env d.init in
  let env' =
    if d.is_const then
      match const_of_expr init with
      | Some v -> add_const env d.ident.name v
      | None -> add_shadow env d.ident.name
    else add_shadow env d.ident.name
  in
  ({ d with init }, env')

let rec fold_stmt env = function
  | Block stmts ->
      let stmts', _ = fold_stmt_list (push_scope env) stmts in
      (Block stmts', env)
  | Empty -> (Empty, env)
  | Expr e -> (Expr (fold_expr env e), env)
  | Assign (name, e) -> (Assign (name, fold_expr env e), env)
  | Decl d ->
      let d', env' = fold_decl env d in
      (Decl d', env')
  | If (cond, t, e) -> (
      match fold_expr env cond with
      | Int v when truth v ->
          let t', _ = fold_stmt env t in
          (t', env)
      | Int _ -> (
          match e with
          | None -> (Empty, env)
          | Some else_s ->
              let else_s', _ = fold_stmt env else_s in
              (else_s', env))
      | cond' ->
          let t', _ = fold_stmt env t in
          let e' = Option.map (fun s -> fst (fold_stmt env s)) e in
          (If (cond', t', e'), env))
  | While (cond, body) -> (
      match fold_expr env cond with
      | Int 0L -> (Empty, env)
      | cond' ->
          let body', _ = fold_stmt env body in
          (While (cond', body'), env))
  | Break -> (Break, env)
  | Continue -> (Continue, env)
  | Return e -> (Return (Option.map (fold_expr env) e), env)

and fold_stmt_list env stmts =
  let rec loop env acc = function
    | [] -> (List.rev acc, env)
    | s :: rest ->
        let s', env' = fold_stmt env s in
        let acc' = s' :: acc in
        if terminates s' then (List.rev acc', env') else loop env' acc' rest
  in
  loop env [] stmts

let build_inline_func_env program =
  List.fold_left
    (fun env -> function
      | FuncDef f -> (
          match inline_def_of_func f with
          | Some def -> StringMap.add f.name.name def env
          | None -> env)
      | TopDecl _ -> env)
    StringMap.empty program

let optimize_ast_once program =
  let base_func_env = build_inline_func_env program in
  let rec fold_stmt_inline func_env env = function
    | Block stmts ->
        let stmts', _ = fold_stmt_list_inline func_env (push_scope env) stmts in
        (Block stmts', env)
    | Empty -> (Empty, env)
    | Expr e -> (Expr (rewrite_expr_ast func_env env e), env)
    | Assign (name, e) -> (Assign (name, rewrite_expr_ast func_env env e), env)
    | Decl d ->
        let d', env' = fold_decl_with_inline func_env env d in
        (Decl d', env')
    | If (cond, t, e) -> (
        match rewrite_expr_ast func_env env cond with
        | Int v when truth v ->
            let t', _ = fold_stmt_inline func_env env t in
            (t', env)
        | Int _ -> (
            match e with
            | None -> (Empty, env)
            | Some else_s ->
                let else_s', _ = fold_stmt_inline func_env env else_s in
                (else_s', env))
        | cond' ->
            let t', _ = fold_stmt_inline func_env env t in
            let e' = Option.map (fun s -> fst (fold_stmt_inline func_env env s)) e in
            (If (cond', t', e'), env))
    | While (cond, body) -> (
        match rewrite_expr_ast func_env env cond with
        | Int 0L -> (Empty, env)
        | cond' ->
            let body', _ = fold_stmt_inline func_env env body in
            (While (cond', body'), env))
    | Break -> (Break, env)
    | Continue -> (Continue, env)
    | Return e -> (Return (Option.map (rewrite_expr_ast func_env env) e), env)

  and fold_stmt_list_inline func_env env stmts =
    let rec loop env acc = function
      | [] -> (List.rev acc, env)
      | s :: rest ->
          let s', env' = fold_stmt_inline func_env env s in
          let acc' = s' :: acc in
          if terminates s' then (List.rev acc', env') else loop env' acc' rest
    in
    loop env [] stmts
  in
  let rec loop env func_env acc = function
    | [] -> List.rev acc
    | TopDecl d :: rest ->
        let d', env' = fold_decl_with_inline func_env env d in
        loop env' func_env (TopDecl d' :: acc) rest
    | FuncDef f :: rest ->
        let params_shadow_consts =
          List.fold_left
            (fun env (p : Ast.ident) -> add_shadow env p.name)
            (push_scope env) f.params
        in
        let body, _ = fold_stmt_list_inline func_env params_shadow_consts f.body in
        let f = { f with body } in
        let func_env =
          match inline_def_of_func f with
          | Some def -> StringMap.add f.name.name def func_env
          | None -> func_env
        in
        loop env func_env (FuncDef f :: acc) rest
  in
  loop empty_env base_func_env [] program

let optimize_ast_impl program =
  let rec iterate fuel current =
    let next = optimize_ast_once current in
    if fuel = 0 || next = current then next else iterate (fuel - 1) next
  in
  iterate 2 program

(* Public AST optimizer entry point used by [Driver].  Keep this explicit in
   step20 so backend-only additions cannot accidentally hide or replace the
   driver-facing symbol. *)
let optimize_ast program = optimize_ast_impl program

let fold_unop op v =
  let v = i32 v in
  match op with
  | UPlus -> Some v
  | UMinus -> Some (i32 (Int64.neg v))
  | UNot -> Some (bool_int (not (truth v)))

let add_operand_temps acc = function
  | Tcg.Temp temp -> IntSet.add temp acc
  | Tcg.Imm _ -> acc

let local_places places =
  PlaceSet.filter
    (function
      | Tcg.Local _ -> true
      | Tcg.Global _ -> false)
    places

let place_is_global = function
  | Tcg.Global _ -> true
  | Tcg.Local _ -> false

let global_places places = PlaceSet.filter place_is_global places

let globals_in_func (f : Cfg.func) =
  List.fold_left
    (fun acc (block : Cfg.block) ->
      List.fold_left
        (fun acc instr ->
          match instr with
          | Tcg.Load (_, Tcg.Global label)
          | Tcg.Store (Tcg.Global label, _) ->
              PlaceSet.add (Tcg.Global label) acc
          | _ -> acc)
        acc block.body)
    PlaceSet.empty f.blocks

let locals_in_func (f : Cfg.func) =
  List.fold_left
    (fun acc (block : Cfg.block) ->
      List.fold_left
        (fun acc instr ->
          match instr with
          | Tcg.Load (_, (Tcg.Local _ as place))
          | Tcg.Store ((Tcg.Local _ as place), _) ->
              PlaceSet.add place acc
          | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> acc)
        acc block.body)
    PlaceSet.empty f.blocks

let stored_globals_in_func (f : Cfg.func) =
  List.fold_left
    (fun acc (block : Cfg.block) ->
      List.fold_left
        (fun acc instr ->
          match instr with
          | Tcg.Store (Tcg.Global label, _) -> PlaceSet.add (Tcg.Global label) acc
          | _ -> acc)
        acc block.body)
    PlaceSet.empty f.blocks

type func_effect_summary = {
  read_globals : PlaceSet.t;
  written_globals : PlaceSet.t;
}

let worst_case_effect_summary globals =
  { read_globals = globals; written_globals = globals }

let call_effect_summary summaries globals callee =
  match Hashtbl.find_opt summaries callee with
  | Some summary -> summary
  | None -> worst_case_effect_summary globals

let call_read_globals summaries globals callee =
  (call_effect_summary summaries globals callee).read_globals

let call_written_globals summaries globals callee =
  (call_effect_summary summaries globals callee).written_globals

let call_touched_globals summaries globals callee =
  PlaceSet.union
    (call_read_globals summaries globals callee)
    (call_written_globals summaries globals callee)

let equal_func_effect_summary a b =
  PlaceSet.equal a.read_globals b.read_globals
  && PlaceSet.equal a.written_globals b.written_globals

let summarize_func summaries globals (f : Cfg.func) =
  List.fold_left
    (fun summary (block : Cfg.block) ->
      List.fold_left
        (fun summary instr ->
          match instr with
          | Tcg.Load (_, (Tcg.Global _ as place)) ->
              { summary with read_globals = PlaceSet.add place summary.read_globals }
          | Tcg.Store ((Tcg.Global _ as place), _) ->
              { summary with written_globals = PlaceSet.add place summary.written_globals }
          | Tcg.Call (_, callee, _) ->
              let callee_summary = call_effect_summary summaries globals callee in
              {
                read_globals = PlaceSet.union summary.read_globals callee_summary.read_globals;
                written_globals =
                  PlaceSet.union summary.written_globals callee_summary.written_globals;
              }
          | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ -> summary)
        summary block.body)
    { read_globals = PlaceSet.empty; written_globals = PlaceSet.empty }
    f.blocks

let compute_func_summaries globals funcs =
  let summaries = Hashtbl.create (max 8 (List.length funcs)) in
  let empty_summary = { read_globals = PlaceSet.empty; written_globals = PlaceSet.empty } in
  List.iter (fun (f : Cfg.func) -> Hashtbl.replace summaries f.label empty_summary) funcs;
  let changed = ref true in
  while !changed do
    changed := false;
    List.iter
      (fun (f : Cfg.func) ->
        let summary = summarize_func summaries globals f in
        let prev =
          match Hashtbl.find_opt summaries f.label with
          | Some prev -> prev
          | None -> empty_summary
        in
        if not (equal_func_effect_summary summary prev) then (
          Hashtbl.replace summaries f.label summary;
          changed := true))
      funcs
  done;
  summaries

let operand_is_zero = function
  | Tcg.Imm 0L -> true
  | Tcg.Temp _ | Tcg.Imm _ -> false

let operand_is_one = function
  | Tcg.Imm 1L -> true
  | Tcg.Temp _ | Tcg.Imm _ -> false

let operand_is_minus_one = function
  | Tcg.Imm (-1L) -> true
  | Tcg.Temp _ | Tcg.Imm _ -> false

let operand_equal a b = a = b

let simplify_simple_instr = function
  | Tcg.Un (dst, op, src) -> (
      match src with
      | Tcg.Imm value -> (
          match fold_unop op value with
          | Some folded -> Tcg.Move (dst, Tcg.Imm folded)
          | None -> Tcg.Un (dst, op, src))
      | _ -> (
          match op with
          | UPlus -> Tcg.Move (dst, src)
          | _ -> Tcg.Un (dst, op, src)))
  | Tcg.Bin (dst, op, lhs, rhs) -> (
      match (lhs, rhs) with
      | Tcg.Imm a, Tcg.Imm b -> (
          match fold_binop op a b with
          | Some folded -> Tcg.Move (dst, Tcg.Imm folded)
          | None -> Tcg.Bin (dst, op, lhs, rhs))
      | _ -> (
          match op with
          | Add when operand_is_zero lhs -> Tcg.Move (dst, rhs)
          | Add when operand_is_zero rhs -> Tcg.Move (dst, lhs)
          | Sub when operand_is_zero rhs -> Tcg.Move (dst, lhs)
          | Sub when operand_equal lhs rhs -> Tcg.Move (dst, Tcg.Imm 0L)
          | Sub when operand_is_zero lhs -> Tcg.Un (dst, UMinus, rhs)
          | Mul when operand_is_zero lhs || operand_is_zero rhs -> Tcg.Move (dst, Tcg.Imm 0L)
          | Mul when operand_is_one lhs -> Tcg.Move (dst, rhs)
          | Mul when operand_is_one rhs -> Tcg.Move (dst, lhs)
          | Mul when operand_is_minus_one lhs -> Tcg.Un (dst, UMinus, rhs)
          | Mul when operand_is_minus_one rhs -> Tcg.Un (dst, UMinus, lhs)
          | Div when operand_is_one rhs -> Tcg.Move (dst, lhs)
          | Mod when operand_is_one rhs -> Tcg.Move (dst, Tcg.Imm 0L)
          | Eq when operand_equal lhs rhs -> Tcg.Move (dst, Tcg.Imm 1L)
          | Ne when operand_equal lhs rhs -> Tcg.Move (dst, Tcg.Imm 0L)
          | Lt when operand_equal lhs rhs -> Tcg.Move (dst, Tcg.Imm 0L)
          | Gt when operand_equal lhs rhs -> Tcg.Move (dst, Tcg.Imm 0L)
          | Le when operand_equal lhs rhs -> Tcg.Move (dst, Tcg.Imm 1L)
          | Ge when operand_equal lhs rhs -> Tcg.Move (dst, Tcg.Imm 1L)
          | _ -> Tcg.Bin (dst, op, lhs, rhs)))
  | instr -> instr

let is_compare_binop = function
  | Lt | Gt | Le | Ge | Eq | Ne -> true
  | Add | Sub | Mul | Div | Mod | LAnd | LOr -> false

let is_commutative_binop = function
  | Add | Mul | Eq | Ne -> true
  | Sub | Div | Mod | Lt | Gt | Le | Ge | LAnd | LOr -> false

let linear_i32_add a b =
  i32 Int64.(add (i32 a) (i32 b))

let linear_i32_mul a b =
  i32 Int64.(mul (i32 a) (i32 b))

(* -------------------------------------------------------------------------- *)
(* item6: one canonical scalar identity shared by GVN, algebra and loop/SCEV  *)
(* -------------------------------------------------------------------------- *)

type canonical_scalar_key =
  int64 * (canonical_scalar_atom * int64) list

and canonical_scalar_atom =
  | CanonicalOperandAtom of Tcg.operand
  | CanonicalPlaceAtom of Tcg.place
  | CanonicalUnaryAtom of unop * canonical_scalar_key
  | CanonicalBinaryAtom of
      binop * canonical_scalar_key * canonical_scalar_key

module CanonicalScalarAtomOrd = struct
  type t = canonical_scalar_atom
  let compare = Stdlib.compare
end

module CanonicalScalarAtomMap =
  Map.Make (CanonicalScalarAtomOrd)

type canonical_scalar_form = {
  canonical_scalar_const : int64;
  canonical_scalar_atoms :
    int64 CanonicalScalarAtomMap.t;
}

let canonical_scalar_zero =
  {
    canonical_scalar_const = 0L;
    canonical_scalar_atoms =
      CanonicalScalarAtomMap.empty;
  }

let canonical_scalar_const value =
  {
    canonical_scalar_const = i32 value;
    canonical_scalar_atoms =
      CanonicalScalarAtomMap.empty;
  }

let canonical_scalar_add_atom atoms atom coeff =
  let coeff = i32 coeff in
  if coeff = 0L then
    atoms
  else
    let old =
      Option.value
        ~default:0L
        (CanonicalScalarAtomMap.find_opt atom atoms)
    in
    let coeff = linear_i32_add old coeff in
    if coeff = 0L then
      CanonicalScalarAtomMap.remove atom atoms
    else
      CanonicalScalarAtomMap.add atom coeff atoms

let canonical_scalar_atom_form atom =
  {
    canonical_scalar_const = 0L;
    canonical_scalar_atoms =
      CanonicalScalarAtomMap.singleton atom 1L;
  }

let canonical_scalar_operand operand =
  match operand with
  | Tcg.Imm value ->
      canonical_scalar_const value
  | Tcg.Temp _ ->
      canonical_scalar_atom_form
        (CanonicalOperandAtom operand)

let canonical_scalar_place place =
  canonical_scalar_atom_form
    (CanonicalPlaceAtom place)

let canonical_scalar_add lhs rhs =
  {
    canonical_scalar_const =
      linear_i32_add
        lhs.canonical_scalar_const
        rhs.canonical_scalar_const;
    canonical_scalar_atoms =
      CanonicalScalarAtomMap.fold
        (fun atom coeff atoms ->
          canonical_scalar_add_atom
            atoms atom coeff)
        rhs.canonical_scalar_atoms
        lhs.canonical_scalar_atoms;
  }

let canonical_scalar_scale factor form =
  let factor = i32 factor in
  if factor = 0L then
    canonical_scalar_zero
  else
    {
      canonical_scalar_const =
        linear_i32_mul
          factor form.canonical_scalar_const;
      canonical_scalar_atoms =
        CanonicalScalarAtomMap.fold
          (fun atom coeff atoms ->
            canonical_scalar_add_atom
              atoms atom
              (linear_i32_mul factor coeff))
          form.canonical_scalar_atoms
          CanonicalScalarAtomMap.empty;
    }

let canonical_scalar_sub lhs rhs =
  canonical_scalar_add
    lhs
    (canonical_scalar_scale (-1L) rhs)

let canonical_scalar_key_of_form form =
  ( i32 form.canonical_scalar_const,
    CanonicalScalarAtomMap.bindings
      form.canonical_scalar_atoms )

let canonical_scalar_is_constant form =
  CanonicalScalarAtomMap.is_empty
    form.canonical_scalar_atoms

let canonical_scalar_order_pair lhs rhs =
  let lhs_key = canonical_scalar_key_of_form lhs in
  let rhs_key = canonical_scalar_key_of_form rhs in
  if Stdlib.compare lhs_key rhs_key <= 0 then
    (lhs_key, rhs_key)
  else
    (rhs_key, lhs_key)

let canonical_scalar_mul lhs rhs =
  if canonical_scalar_is_constant lhs then
    canonical_scalar_scale
      lhs.canonical_scalar_const rhs
  else if canonical_scalar_is_constant rhs then
    canonical_scalar_scale
      rhs.canonical_scalar_const lhs
  else
    let lhs_key, rhs_key =
      canonical_scalar_order_pair lhs rhs
    in
    canonical_scalar_atom_form
      (CanonicalBinaryAtom
         (Mul, lhs_key, rhs_key))

let canonical_scalar_un op inner =
  match op with
  | UPlus ->
      inner
  | UMinus ->
      canonical_scalar_scale (-1L) inner
  | UNot ->
      canonical_scalar_atom_form
        (CanonicalUnaryAtom
           (op, canonical_scalar_key_of_form inner))

let canonical_scalar_opaque_bin op lhs rhs =
  let lhs_key = canonical_scalar_key_of_form lhs in
  let rhs_key = canonical_scalar_key_of_form rhs in
  let lhs_key, rhs_key =
    if is_commutative_binop op
       && Stdlib.compare lhs_key rhs_key > 0
    then
      (rhs_key, lhs_key)
    else
      (lhs_key, rhs_key)
  in
  canonical_scalar_atom_form
    (CanonicalBinaryAtom
       (op, lhs_key, rhs_key))

let canonical_scalar_bin op lhs rhs =
  match op with
  | Add ->
      canonical_scalar_add lhs rhs
  | Sub ->
      canonical_scalar_sub lhs rhs
  | Mul ->
      canonical_scalar_mul lhs rhs
  | Div | Mod | Lt | Gt | Le | Ge
  | Eq | Ne | LAnd | LOr ->
      canonical_scalar_opaque_bin op lhs rhs

let canonical_scalar_key_equal lhs rhs =
  canonical_scalar_key_of_form lhs
  = canonical_scalar_key_of_form rhs

let rec string_of_canonical_scalar_key
    (const, terms) =
  let string_of_atom = function
    | CanonicalOperandAtom (Tcg.Imm value) ->
        Printf.sprintf "imm:%Ld" value
    | CanonicalOperandAtom (Tcg.Temp temp) ->
        Printf.sprintf "t%d" temp
    | CanonicalPlaceAtom place ->
        Printf.sprintf "place:%s"
          (match place with
           | Tcg.Local id ->
               Printf.sprintf "local:%d" id
           | Tcg.Global name ->
               Printf.sprintf "global:%s" name)
    | CanonicalUnaryAtom (op, inner) ->
        Printf.sprintf "un:%d[%s]"
          (Hashtbl.hash op)
          (string_of_canonical_scalar_key inner)
    | CanonicalBinaryAtom (op, lhs, rhs) ->
        Printf.sprintf "bin:%d[%s][%s]"
          (Hashtbl.hash op)
          (string_of_canonical_scalar_key lhs)
          (string_of_canonical_scalar_key rhs)
  in
  let rendered_terms =
    terms
    |> List.map
         (fun (atom, coeff) ->
           Printf.sprintf "%Ld*%s"
             coeff (string_of_atom atom))
    |> String.concat ","
  in
  Printf.sprintf "{c=%Ld;%s}"
    const rendered_terms

let rec canonical_scalar_key_has_temp
    temp (_const, terms) =
  List.exists
    (fun (atom, _) ->
      canonical_scalar_atom_has_temp temp atom)
    terms

and canonical_scalar_atom_has_temp temp = function
  | CanonicalOperandAtom (Tcg.Temp other) ->
      temp = other
  | CanonicalOperandAtom (Tcg.Imm _) ->
      false
  | CanonicalPlaceAtom _ ->
      false
  | CanonicalUnaryAtom (_, inner) ->
      canonical_scalar_key_has_temp temp inner
  | CanonicalBinaryAtom (_, lhs, rhs) ->
      canonical_scalar_key_has_temp temp lhs
      || canonical_scalar_key_has_temp temp rhs

type linear_key = canonical_scalar_key

type expr_key =
  | KeyUn of unop * Tcg.operand
  | KeyBin of binop * Tcg.operand * Tcg.operand
  | KeyLinear of linear_key
  | KeyLoad of Tcg.place

module ExprKeyOrd = struct
  type t = expr_key
  let compare = Stdlib.compare
end

module ExprKeyMap = Map.Make (ExprKeyOrd)

type avail_map = Tcg.operand ExprKeyMap.t

let empty_avail = ExprKeyMap.empty

type alias_map = Tcg.operand IntMap.t

let empty_alias = IntMap.empty

let normalize_bin_operands op lhs rhs =
  if not (is_commutative_binop op) then
    (lhs, rhs)
  else
    match (lhs, rhs) with
    | Tcg.Imm _, Tcg.Temp _ ->
        (rhs, lhs)
    | Tcg.Temp _, Tcg.Imm _ ->
        (lhs, rhs)
    | _ when Stdlib.compare lhs rhs > 0 ->
        (rhs, lhs)
    | _ ->
        (lhs, rhs)

type linear_form = canonical_scalar_form

type linear_analyzer =
  Tcg.operand -> linear_form

let linear_atom temp =
  canonical_scalar_operand
    (Tcg.Temp temp)

let linear_key_of_form =
  canonical_scalar_key_of_form

let make_linear_analyzer
    (f : Cfg.func) : linear_analyzer =
  (* The analyzer follows only unique definitions.  A multi-def temp is a
     program-point-sensitive value, so it remains an opaque scalar atom.

     All arithmetic identity is now represented by [canonical_scalar_form],
     the same key later used by loop/SCEV and counted-summary semantics. *)
  let def_instrs =
    Hashtbl.create (max 16 f.temp_count)
  in
  let multi_defs = ref IntSet.empty in
  let record_def temp instr =
    if Hashtbl.mem def_instrs temp then
      multi_defs := IntSet.add temp !multi_defs
    else
      Hashtbl.add def_instrs temp instr
  in
  List.iter
    (fun (block : Cfg.block) ->
      List.iter
        (fun instr ->
          match instr with
          | Tcg.Move (dst, _)
          | Tcg.Un (dst, _, _)
          | Tcg.Bin (dst, _, _, _)
          | Tcg.Load (dst, _) ->
              record_def dst instr
          | Tcg.Call (Some dst, _, _) ->
              record_def dst instr
          | Tcg.Store _
          | Tcg.Call (None, _, _) ->
              ())
        block.body)
    f.blocks;
  let multi_defs = !multi_defs in
  let memo =
    Hashtbl.create (max 16 f.temp_count)
  in
  let rec of_operand seen = function
    | Tcg.Imm value ->
        canonical_scalar_const value
    | Tcg.Temp temp ->
        if
          IntSet.mem temp multi_defs
          || IntSet.mem temp seen
        then
          linear_atom temp
        else
          match Hashtbl.find_opt memo temp with
          | Some form ->
              form
          | None ->
              let seen =
                IntSet.add temp seen
              in
              let form =
                match Hashtbl.find_opt
                        def_instrs temp
                with
                | Some (Tcg.Move (_, src))
                | Some (Tcg.Un (_, UPlus, src)) ->
                    of_operand seen src
                | Some (Tcg.Un (_, UMinus, src)) ->
                    canonical_scalar_un
                      UMinus
                      (of_operand seen src)
                | Some
                    (Tcg.Bin
                       (_, ((Add | Sub | Mul) as op),
                        lhs, rhs)) ->
                    canonical_scalar_bin
                      op
                      (of_operand seen lhs)
                      (of_operand seen rhs)
                | Some (Tcg.Un _)
                | Some (Tcg.Bin _)
                | Some (Tcg.Load _)
                | Some (Tcg.Store _)
                | Some (Tcg.Call _)
                | None ->
                    linear_atom temp
              in
              Hashtbl.replace memo temp form;
              form
  in
  fun operand ->
    of_operand IntSet.empty operand

let linear_form_of_un analyze op src =
  match op with
  | UPlus | UMinus ->
      Some
        (canonical_scalar_un
           op (analyze src))
  | UNot ->
      None

let linear_form_of_bin
    analyze op lhs rhs =
  match op with
  | Add | Sub | Mul ->
      Some
        (canonical_scalar_bin
           op
           (analyze lhs)
           (analyze rhs))
  | Div | Mod | Lt | Gt | Le | Ge
  | Eq | Ne | LAnd | LOr ->
      None

let linear_expr_key_of_un analysis op src =
  Option.map
    (fun form ->
      KeyLinear
        (linear_key_of_form form))
    (linear_form_of_un analysis op src)

let linear_expr_key_of_bin
    analysis op lhs rhs =
  Option.map
    (fun form ->
      KeyLinear
        (linear_key_of_form form))
    (linear_form_of_bin
       analysis op lhs rhs)

let reify_linear_one_instr dst form =
  let const =
    i32 form.canonical_scalar_const
  in
  let temp_terms =
    List.fold_right
      (fun (atom, coeff) acc ->
        match (atom, acc) with
        | CanonicalOperandAtom
            (Tcg.Temp temp),
          Some terms ->
            Some ((temp, coeff) :: terms)
        | CanonicalOperandAtom
            (Tcg.Imm _),
          _
        | CanonicalPlaceAtom _, _
        | CanonicalUnaryAtom _, _
        | CanonicalBinaryAtom _, _
        | _, None ->
            None)
      (CanonicalScalarAtomMap.bindings
         form.canonical_scalar_atoms)
      (Some [])
  in
  match temp_terms with
  | None ->
      None
  | Some terms -> (
      match terms with
      | [] ->
          Some
            (Tcg.Move
               (dst, Tcg.Imm const))
      | [ (temp, coeff) ] ->
          let coeff = i32 coeff in
          if coeff = 1L then
            if const = 0L then
              Some
                (Tcg.Move
                   (dst, Tcg.Temp temp))
            else
              Some
                (Tcg.Bin
                   ( dst,
                     Add,
                     Tcg.Temp temp,
                     Tcg.Imm const ))
          else if coeff = -1L then
            if const = 0L then
              Some
                (Tcg.Un
                   ( dst,
                     UMinus,
                     Tcg.Temp temp ))
            else
              Some
                (Tcg.Bin
                   ( dst,
                     Sub,
                     Tcg.Imm const,
                     Tcg.Temp temp ))
          else if const = 0L then
            Some
              (Tcg.Bin
                 ( dst,
                   Mul,
                   Tcg.Temp temp,
                   Tcg.Imm coeff ))
          else
            None
      | [ (temp1, coeff1);
          (temp2, coeff2) ]
        when const = 0L ->
          let coeff1 = i32 coeff1 in
          let coeff2 = i32 coeff2 in
          if
            coeff1 = 1L
            && coeff2 = 1L
          then
            Some
              (Tcg.Bin
                 ( dst,
                   Add,
                   Tcg.Temp temp1,
                   Tcg.Temp temp2 ))
          else if
            coeff1 = 1L
            && coeff2 = -1L
          then
            Some
              (Tcg.Bin
                 ( dst,
                   Sub,
                   Tcg.Temp temp1,
                   Tcg.Temp temp2 ))
          else if
            coeff1 = -1L
            && coeff2 = 1L
          then
            Some
              (Tcg.Bin
                 ( dst,
                   Sub,
                   Tcg.Temp temp2,
                   Tcg.Temp temp1 ))
          else
            None
      | _ ->
          None)


let simplify_cfg_func (f : Cfg.func) =
  let simplify_instr instr =
    match simplify_simple_instr instr with
    | Tcg.Move (dst, Tcg.Temp src) when dst = src -> None
    | Tcg.Bin (dst, op, lhs, rhs) ->
        let lhs, rhs = normalize_bin_operands op lhs rhs in
        Some (Tcg.Bin (dst, op, lhs, rhs))
    | instr -> Some instr
  in
  let simplify_term = function
    | Cfg.BranchCompare (_, _, _, if_true, if_false) when if_true = if_false -> Cfg.Jump if_true
    | Cfg.BranchZero (_, if_zero, if_nonzero) when if_zero = if_nonzero -> Cfg.Jump if_zero
    | Cfg.BranchNonZero (_, if_nonzero, if_zero) when if_zero = if_nonzero -> Cfg.Jump if_zero
    | term -> term
  in
  let blocks =
    List.map
      (fun (block : Cfg.block) ->
        let body = List.filter_map simplify_instr block.body in
        let term = simplify_term block.term in
        { block with body; term; succs = Cfg.successors term })
      f.blocks
  in
  Cfg.rebuild_edges { f with blocks }

let meet_avail a b =
  ExprKeyMap.merge
    (fun _ va vb ->
      match (va, vb) with
      | Some a, Some b when a = b -> Some a
      | _ -> None)
    a b

let kill_place_loads killed avail =
  ExprKeyMap.filter
    (fun key _ ->
      match key with
      | KeyLoad place -> not (PlaceSet.mem place killed)
      | KeyUn _ | KeyBin _ | KeyLinear _ -> true)
    avail

let operand_has_temp temp = function
  | Tcg.Temp other -> other = temp
  | Tcg.Imm _ -> false

let expr_key_has_temp temp = function
  | KeyUn (_, src) ->
      operand_has_temp temp src
  | KeyBin (_, lhs, rhs) ->
      operand_has_temp temp lhs
      || operand_has_temp temp rhs
  | KeyLinear key ->
      canonical_scalar_key_has_temp temp key
  | KeyLoad _ ->
      false

let avail_value_has_temp temp = function
  | Tcg.Temp other -> other = temp
  | Tcg.Imm _ -> false

let alias_value_has_temp temp = function
  | Tcg.Temp other -> other = temp
  | Tcg.Imm _ -> false

let equal_avail_map = ExprKeyMap.equal ( = )

let equal_alias_map = IntMap.equal ( = )

let meet_alias_map a b =
  IntMap.merge
    (fun _ va vb ->
      match (va, vb) with
      | Some a, Some b when a = b -> Some a
      | _ -> None)
    a b

let kill_temp_alias temp aliases =
  IntMap.filter
    (fun key value -> key <> temp && not (alias_value_has_temp temp value))
    aliases

let rec resolve_alias_operand aliases seen = function
  | Tcg.Imm _ as operand -> operand
  | Tcg.Temp temp ->
      if IntSet.mem temp seen then Tcg.Temp temp
      else
        match IntMap.find_opt temp aliases with
        | Some src -> resolve_alias_operand aliases (IntSet.add temp seen) src
        | None -> Tcg.Temp temp

let set_alias_fact aliases dst operand =
  if operand = Tcg.Temp dst then aliases else IntMap.add dst operand aliases

let retarget_alias_leader temp aliases =
  let members =
    IntMap.fold
      (fun alias value acc ->
        match value with
        | Tcg.Temp leader when leader = temp -> alias :: acc
        | Tcg.Temp _ | Tcg.Imm _ -> acc)
      aliases []
  in
  match members with
  | [] -> (aliases, None)
  | first :: rest ->
      let replacement = List.fold_left min first rest in
      let aliases =
        List.fold_left
          (fun aliases alias ->
            if alias = replacement then IntMap.remove alias aliases
            else IntMap.add alias (Tcg.Temp replacement) aliases)
          aliases members
      in
      (aliases, Some (Tcg.Temp replacement))

let kill_temp_gvn temp aliases avail =
  let aliases, replacement = retarget_alias_leader temp aliases in
  let avail = ExprKeyMap.filter (fun key _ -> not (expr_key_has_temp temp key)) avail in
  let avail =
    match replacement with
    | Some operand -> ExprKeyMap.map (fun value -> if value = Tcg.Temp temp then operand else value) avail
    | None -> ExprKeyMap.filter (fun _ value -> not (avail_value_has_temp temp value)) avail
  in
  (kill_temp_alias temp aliases, avail)

type gvn_state = {
  avail : avail_map;
  aliases : alias_map;
}

let empty_gvn_state = { avail = empty_avail; aliases = empty_alias }

let equal_gvn_state a b =
  equal_avail_map a.avail b.avail && equal_alias_map a.aliases b.aliases

let meet_gvn_state a b =
  { avail = meet_avail a.avail b.avail; aliases = meet_alias_map a.aliases b.aliases }

let transfer_gvn_instr ?linear summaries globals state instr =
  match instr with
  | Tcg.Move (dst, src) ->
      let src = resolve_alias_operand state.aliases IntSet.empty src in
      let instr = simplify_simple_instr (Tcg.Move (dst, src)) in
      let aliases, avail = kill_temp_gvn dst state.aliases state.avail in
      let aliases =
        match instr with
        | Tcg.Move (_, src) -> set_alias_fact aliases dst src
        | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> aliases
      in
      (instr, { avail; aliases })
  | Tcg.Un (dst, op, src) ->
      let src = resolve_alias_operand state.aliases IntSet.empty src in
      let instr = simplify_simple_instr (Tcg.Un (dst, op, src)) in
      let aliases, avail = kill_temp_gvn dst state.aliases state.avail in
      begin
        match instr with
        | Tcg.Move (_, src) -> (instr, { avail; aliases = set_alias_fact aliases dst src })
        | Tcg.Un (_, op, src) ->
            let key =
              match linear with
              | Some analysis -> (
                  match linear_expr_key_of_un analysis op src with
                  | Some key when not (expr_key_has_temp dst key) -> key
                  | Some _ | None -> KeyUn (op, src))
              | None -> KeyUn (op, src)
            in
            begin
              match ExprKeyMap.find_opt key avail with
              | Some value ->
                  ( Tcg.Move (dst, value),
                    { avail; aliases = set_alias_fact aliases dst value } )
              | None ->
                  (instr, { avail = ExprKeyMap.add key (Tcg.Temp dst) avail; aliases })
            end
        | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> (instr, { avail; aliases })
      end
  | Tcg.Bin (dst, op, lhs, rhs) ->
      let lhs = resolve_alias_operand state.aliases IntSet.empty lhs in
      let rhs = resolve_alias_operand state.aliases IntSet.empty rhs in
      let instr = simplify_simple_instr (Tcg.Bin (dst, op, lhs, rhs)) in
      let aliases, avail = kill_temp_gvn dst state.aliases state.avail in
      begin
        match instr with
        | Tcg.Move (_, src) -> (instr, { avail; aliases = set_alias_fact aliases dst src })
        | Tcg.Bin (_, op, lhs, rhs) ->
            let lhs, rhs = normalize_bin_operands op lhs rhs in
            let key =
              match linear with
              | Some analysis -> (
                  match linear_expr_key_of_bin analysis op lhs rhs with
                  | Some key when not (expr_key_has_temp dst key) -> key
                  | Some _ | None -> KeyBin (op, lhs, rhs))
              | None -> KeyBin (op, lhs, rhs)
            in
            begin
              match ExprKeyMap.find_opt key avail with
              | Some value ->
                  ( Tcg.Move (dst, value),
                    { avail; aliases = set_alias_fact aliases dst value } )
              | None ->
                  ( Tcg.Bin (dst, op, lhs, rhs),
                    { avail = ExprKeyMap.add key (Tcg.Temp dst) avail; aliases } )
            end
        | Tcg.Un _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> (instr, { avail; aliases })
      end
  | Tcg.Load (dst, place) ->
      let aliases, avail = kill_temp_gvn dst state.aliases state.avail in
      let key = KeyLoad place in
      begin
        match ExprKeyMap.find_opt key avail with
        | Some value ->
            (Tcg.Move (dst, value), { avail; aliases = set_alias_fact aliases dst value })
        | None ->
            (Tcg.Load (dst, place), { avail = ExprKeyMap.add key (Tcg.Temp dst) avail; aliases })
      end
  | Tcg.Store (place, value) ->
      let value = resolve_alias_operand state.aliases IntSet.empty value in
      let avail = ExprKeyMap.remove (KeyLoad place) state.avail in
      (Tcg.Store (place, value), { state with avail = ExprKeyMap.add (KeyLoad place) value avail })
  | Tcg.Call (dst, callee, args) ->
      let args = List.map (resolve_alias_operand state.aliases IntSet.empty) args in
      let aliases, avail =
        match dst with
        | Some temp -> kill_temp_gvn temp state.aliases state.avail
        | None -> (state.aliases, state.avail)
      in
      let avail = kill_place_loads (call_written_globals summaries globals callee) avail in
      (Tcg.Call (dst, callee, args), { avail; aliases })

type cp_fact =
  | CpUndef
  | CpConst of int64
  | CpNac

type cp_state = {
  temps : cp_fact IntMap.t;
  places : cp_fact PlaceMap.t;
}

let equal_cp_state a b =
  IntMap.equal ( = ) a.temps b.temps && PlaceMap.equal ( = ) a.places b.places

let equal_operand_map = IntMap.equal ( = )
let equal_place_operand_map = PlaceMap.equal ( = )

let empty_cp_state = { temps = IntMap.empty; places = PlaceMap.empty }

let fact_of_opt = function
  | Some fact -> fact
  | None -> CpUndef

let opt_of_fact = function
  | CpUndef -> None
  | fact -> Some fact

let meet_fact a b =
  match (a, b) with
  | CpUndef, x | x, CpUndef -> x
  | CpConst a, CpConst b when a = b -> CpConst a
  | CpConst _, CpConst _ -> CpNac
  | CpNac, _ | _, CpNac -> CpNac

let meet_int_map a b =
  IntMap.merge
    (fun _ va vb -> opt_of_fact (meet_fact (fact_of_opt va) (fact_of_opt vb)))
    a b

let meet_place_map a b =
  PlaceMap.merge
    (fun _ va vb -> opt_of_fact (meet_fact (fact_of_opt va) (fact_of_opt vb)))
    a b

let meet_cp_state a b =
  { temps = meet_int_map a.temps b.temps; places = meet_place_map a.places b.places }

let set_temp_fact state temp fact =
  {
    state with
    temps =
      (match fact with
      | CpUndef -> IntMap.remove temp state.temps
      | _ -> IntMap.add temp fact state.temps);
  }

let set_place_fact state place fact =
  {
    state with
    places =
      (match fact with
      | CpUndef -> PlaceMap.remove place state.places
      | _ -> PlaceMap.add place fact state.places);
  }

let get_temp_fact state temp = fact_of_opt (IntMap.find_opt temp state.temps)

let get_place_fact state place = fact_of_opt (PlaceMap.find_opt place state.places)

let eval_operand_fact state = function
  | Tcg.Imm value -> CpConst value
  | Tcg.Temp temp -> get_temp_fact state temp

let rewrite_operand_const state operand =
  match eval_operand_fact state operand with
  | CpConst value -> Tcg.Imm value
  | CpUndef | CpNac -> operand

let fold_fact_un op = function
  | CpConst value -> (
      match fold_unop op value with
      | Some folded -> CpConst folded
      | None -> CpNac)
  | CpUndef -> CpUndef
  | CpNac -> CpNac

let fold_fact_bin op a b =
  match (a, b) with
  | CpConst av, CpConst bv -> (
      match fold_binop op av bv with
      | Some folded -> CpConst folded
      | None -> CpNac)
  | CpNac, _ | _, CpNac -> CpNac
  | CpUndef, _ | _, CpUndef -> CpUndef

let kill_place_facts places state =
  PlaceSet.fold (fun place acc -> set_place_fact acc place CpNac) places state

let initial_cp_state global_init (f : Cfg.func) =
  let global_init =
    if f.name = "main" then global_init
    else PlaceMap.map (fun _ -> CpNac) global_init
  in
  let places =
    List.fold_left
      (fun places (param : Tcg.var) -> PlaceMap.add (Tcg.Local param.id) CpNac places)
      global_init f.params
  in
  { temps = IntMap.empty; places }

let fact_of_simple_instr state = function
  | Tcg.Move (_, src) -> eval_operand_fact state src
  | Tcg.Un (_, op, src) -> fold_fact_un op (eval_operand_fact state src)
  | Tcg.Bin (_, op, lhs, rhs) ->
      fold_fact_bin op (eval_operand_fact state lhs) (eval_operand_fact state rhs)
  | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> CpNac

let transfer_simple_instr summaries globals state instr =
  match instr with
  | Tcg.Move (dst, src) ->
      let src = rewrite_operand_const state src in
      let instr = simplify_simple_instr (Tcg.Move (dst, src)) in
      let fact = fact_of_simple_instr state instr in
      (instr, set_temp_fact state dst fact)
  | Tcg.Un (dst, op, src) ->
      let src = rewrite_operand_const state src in
      let instr = simplify_simple_instr (Tcg.Un (dst, op, src)) in
      let fact = fact_of_simple_instr state instr in
      (instr, set_temp_fact state dst fact)
  | Tcg.Bin (dst, op, lhs, rhs) ->
      let lhs = rewrite_operand_const state lhs in
      let rhs = rewrite_operand_const state rhs in
      let instr = simplify_simple_instr (Tcg.Bin (dst, op, lhs, rhs)) in
      let fact = fact_of_simple_instr state instr in
      (instr, set_temp_fact state dst fact)
  | Tcg.Load (dst, place) -> (
      let fact = get_place_fact state place in
      match fact with
      | CpConst value ->
          let instr = Tcg.Move (dst, Tcg.Imm value) in
          (instr, set_temp_fact state dst fact)
      | CpUndef | CpNac -> (Tcg.Load (dst, place), set_temp_fact state dst fact))
  | Tcg.Store (place, value) ->
      let value = rewrite_operand_const state value in
      let fact = eval_operand_fact state value in
      (Tcg.Store (place, value), set_place_fact state place fact)
  | Tcg.Call (dst, callee, args) ->
      let args = List.map (rewrite_operand_const state) args in
      let state = kill_place_facts (call_written_globals summaries globals callee) state in
      let state =
        match dst with
        | Some temp -> set_temp_fact state temp CpNac
        | None -> state
      in
      (Tcg.Call (dst, callee, args), state)

let transfer_terminator state (term : Cfg.terminator) =
  match term with
  | Cfg.Jump _ as term -> (term, state)
  | Cfg.BranchZero (cond, if_zero, if_nonzero) ->
      let cond = rewrite_operand_const state cond in
      let term =
        match eval_operand_fact state cond with
        | CpConst value -> Cfg.Jump (if value = 0L then if_zero else if_nonzero)
        | CpUndef | CpNac ->
            if if_zero = if_nonzero then Cfg.Jump if_zero
            else Cfg.BranchZero (cond, if_zero, if_nonzero)
      in
      (term, state)
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) ->
      let cond = rewrite_operand_const state cond in
      let term =
        match eval_operand_fact state cond with
        | CpConst value -> Cfg.Jump (if value <> 0L then if_nonzero else if_zero)
        | CpUndef | CpNac ->
            if if_zero = if_nonzero then Cfg.Jump if_zero
            else Cfg.BranchNonZero (cond, if_nonzero, if_zero)
      in
      (term, state)
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
      let lhs = rewrite_operand_const state lhs in
      let rhs = rewrite_operand_const state rhs in
      let term =
        match fold_fact_bin op (eval_operand_fact state lhs) (eval_operand_fact state rhs) with
        | CpConst value -> Cfg.Jump (if truth value then if_true else if_false)
        | CpUndef | CpNac ->
            if if_true = if_false then Cfg.Jump if_true
            else Cfg.BranchCompare (op, lhs, rhs, if_true, if_false)
      in
      (term, state)
  | Cfg.Return None -> (Cfg.Return None, state)
  | Cfg.Return (Some value) ->
      (Cfg.Return (Some (rewrite_operand_const state value)), state)

let run_transfer summaries globals state (block : Cfg.block) =
  let body_rev, state =
    List.fold_left
      (fun (acc, state) instr ->
        let instr, state = transfer_simple_instr summaries globals state instr in
        (instr :: acc, state))
      ([], state) block.body
  in
  let term, state = transfer_terminator state block.term in
  ({ block with body = List.rev body_rev; term; succs = Cfg.successors term }, state)

let executable_successors state (term : Cfg.terminator) =
  match term with
  | Cfg.Jump label -> [ label ]
  | Cfg.BranchZero (cond, if_zero, if_nonzero) ->
      if if_zero = if_nonzero then [ if_zero ]
      else
        begin
          match eval_operand_fact state cond with
          | CpConst value -> [ if value = 0L then if_zero else if_nonzero ]
          | CpNac -> [ if_zero; if_nonzero ]
          | CpUndef -> []
        end
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) ->
      if if_zero = if_nonzero then [ if_zero ]
      else
        begin
          match eval_operand_fact state cond with
          | CpConst value -> [ if value <> 0L then if_nonzero else if_zero ]
          | CpNac -> [ if_nonzero; if_zero ]
          | CpUndef -> []
        end
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
      if if_true = if_false then [ if_true ]
      else
        begin
          match fold_fact_bin op (eval_operand_fact state lhs) (eval_operand_fact state rhs) with
          | CpConst value -> [ if truth value then if_true else if_false ]
          | CpNac -> [ if_true; if_false ]
          | CpUndef -> []
        end
  | Cfg.Return _ -> []

let compute_const_states global_init summaries globals (f : Cfg.func) =
  let block_map = Hashtbl.create (List.length f.blocks) in
  List.iter (fun (block : Cfg.block) -> Hashtbl.replace block_map block.label block) f.blocks;
  let in_states = Hashtbl.create (List.length f.blocks) in
  let out_states = Hashtbl.create (List.length f.blocks) in
  let executable = ref (LabelSet.singleton f.entry) in
  let executable_edges = Hashtbl.create (max 8 (2 * List.length f.blocks)) in
  let entry_state = initial_cp_state global_init f in
  let meet_states = function
    | [] -> empty_cp_state
    | state :: rest -> List.fold_left meet_cp_state state rest
  in
  let changed = ref true in
  while !changed do
    changed := false;
    List.iter
      (fun (block : Cfg.block) ->
        if LabelSet.mem block.label !executable then (
          let pred_states =
            List.filter_map
              (fun pred ->
                if Hashtbl.mem executable_edges (pred, block.label) then
                  Hashtbl.find_opt out_states pred
                else None)
              block.preds
          in
          let in_state =
            if block.label = f.entry then meet_states (entry_state :: pred_states)
            else meet_states pred_states
          in
          let _, out_state = run_transfer summaries globals in_state block in
          let prev_in =
            match Hashtbl.find_opt in_states block.label with
            | Some state -> state
            | None -> empty_cp_state
          in
          let prev_out =
            match Hashtbl.find_opt out_states block.label with
            | Some state -> state
            | None -> empty_cp_state
          in
          if not (equal_cp_state in_state prev_in) then (
            Hashtbl.replace in_states block.label in_state;
            changed := true);
          if not (equal_cp_state out_state prev_out) then (
            Hashtbl.replace out_states block.label out_state;
            changed := true);
          List.iter
            (fun succ ->
              if Hashtbl.mem block_map succ
                 && not (Hashtbl.mem executable_edges (block.label, succ))
              then (
                Hashtbl.add executable_edges (block.label, succ) ();
                if not (LabelSet.mem succ !executable) then
                  executable := LabelSet.add succ !executable;
                changed := true))
            (executable_successors out_state block.term)))
      f.blocks
  done;
  (!executable, in_states)

let const_propagate_func global_init summaries globals (f : Cfg.func) =
  let executable, in_states = compute_const_states global_init summaries globals f in
  let blocks =
    List.filter_map
      (fun (block : Cfg.block) ->
        if LabelSet.mem block.label executable then
          let state =
            match Hashtbl.find_opt in_states block.label with
            | Some state -> state
            | None when block.label = f.entry -> initial_cp_state global_init f
            | None -> empty_cp_state
          in
          Some (fst (run_transfer summaries globals state block))
        else None)
      f.blocks
  in
  Cfg.rebuild_edges { f with blocks }

let run_gvn_transfer ?linear summaries globals state (block : Cfg.block) =
  let body_rev, state =
    List.fold_left
      (fun (acc, state) instr ->
        let instr, state = transfer_gvn_instr ?linear summaries globals state instr in
        (instr :: acc, state))
      ([], state) block.body
  in
  let term =
    match block.term with
    | Cfg.Jump _ as term -> term
    | Cfg.BranchZero (cond, if_zero, if_nonzero) ->
        let cond = resolve_alias_operand state.aliases IntSet.empty cond in
        begin
          match cond with
          | Tcg.Imm value -> Cfg.Jump (if value = 0L then if_zero else if_nonzero)
          | _ ->
              if if_zero = if_nonzero then Cfg.Jump if_zero
              else Cfg.BranchZero (cond, if_zero, if_nonzero)
        end
    | Cfg.BranchNonZero (cond, if_nonzero, if_zero) ->
        let cond = resolve_alias_operand state.aliases IntSet.empty cond in
        begin
          match cond with
          | Tcg.Imm value -> Cfg.Jump (if value <> 0L then if_nonzero else if_zero)
          | _ ->
              if if_zero = if_nonzero then Cfg.Jump if_zero
              else Cfg.BranchNonZero (cond, if_nonzero, if_zero)
        end
    | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
        let lhs = resolve_alias_operand state.aliases IntSet.empty lhs in
        let rhs = resolve_alias_operand state.aliases IntSet.empty rhs in
        begin
          match (lhs, rhs) with
          | Tcg.Imm a, Tcg.Imm b -> (
              match fold_binop op a b with
              | Some value -> Cfg.Jump (if truth value then if_true else if_false)
              | None -> Cfg.BranchCompare (op, lhs, rhs, if_true, if_false))
          | _ ->
              if if_true = if_false then Cfg.Jump if_true
              else Cfg.BranchCompare (op, lhs, rhs, if_true, if_false)
        end
    | Cfg.Return None -> Cfg.Return None
    | Cfg.Return (Some value) ->
        Cfg.Return (Some (resolve_alias_operand state.aliases IntSet.empty value))
  in
  ({ block with body = List.rev body_rev; term; succs = Cfg.successors term }, state)

let compute_gvn_states ?linear summaries globals (f : Cfg.func) =
  let in_states = Hashtbl.create (List.length f.blocks) in
  let out_states = Hashtbl.create (List.length f.blocks) in
  let find_state table label =
    match Hashtbl.find_opt table label with
    | Some state -> state
    | None -> empty_gvn_state
  in
  let meet_preds preds =
    match preds with
    | [] -> empty_gvn_state
    | pred :: rest ->
        List.fold_left
          (fun acc pred -> meet_gvn_state acc (find_state out_states pred))
          (find_state out_states pred) rest
  in
  let changed = ref true in
  while !changed do
    changed := false;
    List.iter
      (fun (block : Cfg.block) ->
        let in_state = meet_preds block.preds in
        let _, out_state = run_gvn_transfer ?linear summaries globals in_state block in
        let prev_in = find_state in_states block.label in
        let prev_out = find_state out_states block.label in
        if not (equal_gvn_state in_state prev_in) then (
          Hashtbl.replace in_states block.label in_state;
          changed := true);
        if not (equal_gvn_state out_state prev_out) then (
          Hashtbl.replace out_states block.label out_state;
          changed := true))
      f.blocks
  done;
  in_states

let gvn_func summaries globals (f : Cfg.func) =
  let linear = make_linear_analyzer f in
  let in_states = compute_gvn_states ~linear summaries globals f in
  let blocks =
    List.map
      (fun (block : Cfg.block) ->
        let state =
          match Hashtbl.find_opt in_states block.label with
          | Some state -> state
          | None -> empty_gvn_state
        in
        fst (run_gvn_transfer ~linear summaries globals state block))
      f.blocks
  in
  Cfg.rebuild_edges { f with blocks }

let gvn_rewrite_instrs summaries globals instrs =
  let rewritten_rev, _ =
    List.fold_left
      (fun (acc, state) instr ->
        let instr, state = transfer_gvn_instr summaries globals state instr in
        (instr :: acc, state))
      ([], empty_gvn_state) instrs
  in
  List.rev rewritten_rev

let rec resolve_jump block_map seen label =
  if LabelSet.mem label seen then label
  else
    match Hashtbl.find_opt block_map label with
    | Some (block : Cfg.block) -> (
        match (block.body, block.term) with
        | [], Cfg.Jump next when next <> label ->
            resolve_jump block_map (LabelSet.add label seen) next
        | _ -> label)
    | _ -> label

let rewrite_term block_map = function
  | Cfg.Jump label -> Cfg.Jump (resolve_jump block_map LabelSet.empty label)
  | Cfg.BranchZero (cond, if_zero, if_nonzero) ->
      Cfg.BranchZero
        ( cond,
          resolve_jump block_map LabelSet.empty if_zero,
          resolve_jump block_map LabelSet.empty if_nonzero )
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) ->
      Cfg.BranchNonZero
        ( cond,
          resolve_jump block_map LabelSet.empty if_nonzero,
          resolve_jump block_map LabelSet.empty if_zero )
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
      Cfg.BranchCompare
        ( op,
          lhs,
          rhs,
          resolve_jump block_map LabelSet.empty if_true,
          resolve_jump block_map LabelSet.empty if_false )
  | Cfg.Return value -> Cfg.Return value

let reachable_labels entry blocks =
  let block_map = Hashtbl.create (List.length blocks) in
  List.iter (fun (block : Cfg.block) -> Hashtbl.replace block_map block.label block) blocks;
  let rec visit seen label =
    if LabelSet.mem label seen then seen
    else
      let seen = LabelSet.add label seen in
      match Hashtbl.find_opt block_map label with
      | None -> seen
      | Some block -> List.fold_left visit seen block.succs
  in
  visit LabelSet.empty entry

let thread_and_prune_func (f : Cfg.func) =
  let block_map = Hashtbl.create (List.length f.blocks) in
  List.iter (fun (block : Cfg.block) -> Hashtbl.replace block_map block.label block) f.blocks;
  let threaded =
    List.map
      (fun (block : Cfg.block) ->
        let term = rewrite_term block_map block.term in
        { block with term; succs = Cfg.successors term })
      f.blocks
  in
  let threaded_func = Cfg.rebuild_edges { f with blocks = threaded } in
  let reachable = reachable_labels threaded_func.entry threaded_func.blocks in
  let blocks =
    List.filter (fun (block : Cfg.block) -> LabelSet.mem block.label reachable)
      threaded_func.blocks
  in
  Cfg.rebuild_edges { threaded_func with blocks }

let find_final_linear_merge_candidate (f : Cfg.func) =
  let block_map = Hashtbl.create (List.length f.blocks) in
  List.iter
    (fun (block : Cfg.block) -> Hashtbl.replace block_map block.label block)
    f.blocks;
  let rec find = function
    | [] -> None
    | (block : Cfg.block) :: rest -> (
        match block.term with
        | Cfg.Jump succ when succ <> block.label && succ <> f.entry -> (
            match Hashtbl.find_opt block_map succ with
            | Some (succ_block : Cfg.block)
              when block.succs = [ succ ] && succ_block.preds = [ block.label ] ->
                Some (block.label, succ)
            | Some _ | None -> find rest)
        | Cfg.Jump _
        | Cfg.BranchZero _
        | Cfg.BranchNonZero _
        | Cfg.BranchCompare _
        | Cfg.Return _ ->
            find rest)
  in
  find f.blocks

let merge_final_linear_pair (f : Cfg.func) pred_label succ_label =
  let block_map = Hashtbl.create (List.length f.blocks) in
  List.iter
    (fun (block : Cfg.block) -> Hashtbl.replace block_map block.label block)
    f.blocks;
  match
    ( Hashtbl.find_opt block_map pred_label,
      Hashtbl.find_opt block_map succ_label )
  with
  | Some (pred : Cfg.block), Some (succ : Cfg.block) ->
      let merged =
        {
          pred with
          body = pred.body @ succ.body;
          term = succ.term;
          succs = Cfg.successors succ.term;
        }
      in
      let blocks =
        List.filter_map
          (fun (block : Cfg.block) ->
            if block.label = succ_label then None
            else if block.label = pred_label then Some merged
            else Some block)
          f.blocks
      in
      Cfg.rebuild_edges { f with blocks }
  | _ -> f

let cfg_missing_targets (f : Cfg.func) =
  let labels =
    List.fold_left
      (fun acc (block : Cfg.block) -> LabelSet.add block.label acc)
      LabelSet.empty f.blocks
  in
  List.fold_left
    (fun missing (block : Cfg.block) ->
      List.fold_left
        (fun missing target ->
          if LabelSet.mem target labels then missing
          else LabelSet.add target missing)
        missing (Cfg.successors block.term))
    LabelSet.empty f.blocks

let cfg_targets_valid (f : Cfg.func) =
  LabelSet.is_empty (cfg_missing_targets f)

let debug_cfg_validation stage (f : Cfg.func) =
  if Sys.getenv_opt "TOYC_DEBUG_CFG_VALIDATE" <> None then
    let missing = cfg_missing_targets f |> LabelSet.elements in
    if missing <> [] then
      Printf.eprintf "cfg-invalid func=%s stage=%s missing=%s\n%!"
        f.name stage (String.concat "," missing)

let final_linear_merge_func (f : Cfg.func) =
  let before_blocks = List.length f.blocks in
  let rec loop merged current =
    match find_final_linear_merge_candidate current with
    | None -> (merged, current)
    | Some (pred, succ) ->
        let next = merge_final_linear_pair current pred succ in
        if not (cfg_targets_valid next) then begin
          debug_cfg_validation
            (Printf.sprintf "final-merge:%s->%s" pred succ) next;
          (merged, current)
        end else if List.length next.blocks >= List.length current.blocks then
          (merged, current)
        else loop (merged + 1) next
  in
  let merged, result = loop 0 f in
  if Sys.getenv_opt "TOYC_DEBUG_CFG_MERGE" <> None then
    Printf.eprintf
      "cfg-final-merge func=%s blocks=%d->%d merged=%d\n%!"
      f.name before_blocks (List.length result.blocks) merged;
  result

let live_out_t live_in_t (block : Cfg.block) =
  List.fold_left
    (fun acc succ ->
      let succ_live =
        match Hashtbl.find_opt live_in_t succ with
        | Some live -> live
        | None -> IntSet.empty
      in
      IntSet.union acc succ_live)
    IntSet.empty block.succs

let scan_simple_instr ?removable_calls summaries globals instr live_t live_p =
  match instr with
  | Tcg.Move (dst, src) ->
      if IntSet.mem dst live_t then
        ( Some instr,
          add_operand_temps (IntSet.remove dst live_t) src,
          live_p )
      else (None, live_t, live_p)
  | Tcg.Un (dst, _, src) ->
      if IntSet.mem dst live_t then
        ( Some instr,
          add_operand_temps (IntSet.remove dst live_t) src,
          live_p )
      else (None, live_t, live_p)
  | Tcg.Bin (dst, _, lhs, rhs) ->
      if IntSet.mem dst live_t then
        ( Some instr,
          add_operand_temps (add_operand_temps (IntSet.remove dst live_t) lhs) rhs,
          live_p )
      else (None, live_t, live_p)
  | Tcg.Load (dst, place) ->
      if IntSet.mem dst live_t then
        (Some instr, IntSet.remove dst live_t, PlaceSet.add place live_p)
      else (None, live_t, live_p)
  | Tcg.Store (place, value) ->
      if PlaceSet.mem place live_p then
        ( Some instr,
          add_operand_temps live_t value,
          PlaceSet.remove place live_p )
      else (None, live_t, live_p)
  | Tcg.Call (dst, callee, args) ->
      let result_dead =
        match dst with
        | None -> true
        | Some temp -> not (IntSet.mem temp live_t)
      in
      let removable =
        match removable_calls with
        | None -> false
        | Some table -> (
            match Hashtbl.find_opt table callee with
            | Some true -> true
            | Some false | None -> false)
      in
      if result_dead && removable then
        (* The call is proven side-effect-free and terminating, and its result
           is dead.  Removing it also means its argument computations need not
           be kept alive solely for this call. *)
        let live_t =
          match dst with
          | Some temp -> IntSet.remove temp live_t
          | None -> live_t
        in
        (None, live_t, live_p)
      else
        let kept_dst =
          match dst with
          | Some temp when IntSet.mem temp live_t -> Some temp
          | _ -> None
        in
        let live_t =
          List.fold_left add_operand_temps
            (match dst with
             | Some temp -> IntSet.remove temp live_t
             | None -> live_t)
            args
        in
        let written_globals = call_written_globals summaries globals callee in
        let read_globals = call_read_globals summaries globals callee in
        let live_p =
          PlaceSet.union
            (local_places live_p)
            (PlaceSet.union (PlaceSet.diff (global_places live_p) written_globals) read_globals)
        in
        (Some (Tcg.Call (kept_dst, callee, args)), live_t, live_p)

let scan_terminator ?return_globals globals (term : Cfg.terminator) live_t live_p =
  let return_globals =
    match return_globals with
    | Some return_globals -> return_globals
    | None -> globals
  in
  match term with
  | Cfg.Jump _ -> (term, live_t, live_p)
  | Cfg.BranchZero (cond, _, _) ->
      (term, add_operand_temps live_t cond, live_p)
  | Cfg.BranchNonZero (cond, _, _) ->
      (term, add_operand_temps live_t cond, live_p)
  | Cfg.BranchCompare (_, lhs, rhs, _, _) ->
      (term, add_operand_temps (add_operand_temps live_t lhs) rhs, live_p)
  | Cfg.Return None -> (term, live_t, PlaceSet.union live_p return_globals)
  | Cfg.Return (Some value) ->
      ( term,
        add_operand_temps live_t value,
        PlaceSet.union live_p return_globals )

let scan_block ?return_globals ?removable_calls summaries globals (block : Cfg.block) live_t_out live_p_out =
  let term, live_t, live_p =
    scan_terminator ?return_globals globals block.term live_t_out live_p_out
  in
  let body_rev, live_t, live_p =
    List.fold_left
      (fun (acc, live_t, live_p) instr ->
        let kept, live_t, live_p = scan_simple_instr ?removable_calls summaries globals instr live_t live_p in
        let acc =
          match kept with
          | Some instr -> instr :: acc
          | None -> acc
        in
        (acc, live_t, live_p))
      ([], live_t, live_p) (List.rev block.body)
  in
  ({ block with body = body_rev; term }, live_t, live_p)

let table_find_or_empty table key empty =
  match Hashtbl.find_opt table key with
  | Some value -> value
  | None -> empty

type liveness_cache = {
  generation : int;
  entry_label : string;
  temp_count : int;
  blocks_key : Cfg.block list;
  live_in_t_cache : (string, IntSet.t) Hashtbl.t;
  live_in_p_cache : (string, PlaceSet.t) Hashtbl.t;
}

type dominator_cache = {
  generation : int;
  entry_label : string;
  temp_count : int;
  blocks_key : Cfg.block list;
  doms_cache : (string, LabelSet.t) Hashtbl.t;
}

let analysis_cache_generation = ref 0
let last_liveness_cache : liveness_cache option ref = ref None
let last_dominator_cache : dominator_cache option ref = ref None

let compute_liveness summaries globals (f : Cfg.func) =
  match !last_liveness_cache with
  | Some cache
    when !analysis_cache_generation <> 0
         && cache.generation = !analysis_cache_generation
         && cache.entry_label = f.entry
         && cache.temp_count = f.temp_count
         && cache.blocks_key = f.blocks ->
      (cache.live_in_t_cache, cache.live_in_p_cache)
  | Some _ | None ->
      let live_in_t = Hashtbl.create (List.length f.blocks) in
      let live_in_p = Hashtbl.create (List.length f.blocks) in
      let blocks = List.rev f.blocks in
      let changed = ref true in
      while !changed do
        changed := false;
        List.iter
          (fun (block : Cfg.block) ->
            let live_t_out =
              List.fold_left
                (fun acc succ ->
                  IntSet.union acc (table_find_or_empty live_in_t succ IntSet.empty))
                IntSet.empty block.succs
            in
            let live_p_out =
              List.fold_left
                (fun acc succ ->
                  PlaceSet.union acc (table_find_or_empty live_in_p succ PlaceSet.empty))
                PlaceSet.empty block.succs
            in
            let _, live_t_in, live_p_in = scan_block summaries globals block live_t_out live_p_out in
            if
              not (IntSet.equal live_t_in (table_find_or_empty live_in_t block.label IntSet.empty))
            then (
              Hashtbl.replace live_in_t block.label live_t_in;
              changed := true);
            if
              not
                (PlaceSet.equal live_p_in
                   (table_find_or_empty live_in_p block.label PlaceSet.empty))
            then (
              Hashtbl.replace live_in_p block.label live_p_in;
              changed := true))
          blocks
      done;
      if !analysis_cache_generation <> 0 then
        last_liveness_cache :=
          Some
            {
              generation = !analysis_cache_generation;
              entry_label = f.entry;
              temp_count = f.temp_count;
              blocks_key = f.blocks;
              live_in_t_cache = live_in_t;
              live_in_p_cache = live_in_p;
            };
      (live_in_t, live_in_p)

(* DCE sometimes knows that only a subset of globals must be observable when a
   function returns.  Keep the normal cached liveness above conservative for
   every other optimization, and use this uncached variant only for the
   context-sensitive dead-store analysis. *)
let compute_liveness_with_return_globals ?removable_calls summaries globals return_globals (f : Cfg.func) =
  let live_in_t = Hashtbl.create (List.length f.blocks) in
  let live_in_p = Hashtbl.create (List.length f.blocks) in
  let blocks = List.rev f.blocks in
  let changed = ref true in
  while !changed do
    changed := false;
    List.iter
      (fun (block : Cfg.block) ->
        let live_t_out =
          List.fold_left
            (fun acc succ ->
              IntSet.union acc (table_find_or_empty live_in_t succ IntSet.empty))
            IntSet.empty block.succs
        in
        let live_p_out =
          List.fold_left
            (fun acc succ ->
              PlaceSet.union acc (table_find_or_empty live_in_p succ PlaceSet.empty))
            PlaceSet.empty block.succs
        in
        let _, live_t_in, live_p_in =
          scan_block ~return_globals ?removable_calls summaries globals block live_t_out live_p_out
        in
        if
          not
            (IntSet.equal live_t_in
               (table_find_or_empty live_in_t block.label IntSet.empty))
        then (
          Hashtbl.replace live_in_t block.label live_t_in;
          changed := true);
        if
          not
            (PlaceSet.equal live_p_in
               (table_find_or_empty live_in_p block.label PlaceSet.empty))
        then (
          Hashtbl.replace live_in_p block.label live_p_in;
          changed := true))
      blocks
  done;
  (live_in_t, live_in_p)

let direct_callees_of_func (f : Cfg.func) =
  List.fold_left
    (fun acc (block : Cfg.block) ->
      List.fold_left
        (fun acc instr ->
          match instr with
          | Tcg.Call (_, callee, _) -> LabelSet.add callee acc
          | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ -> acc)
        acc block.body)
    LabelSet.empty f.blocks

let reachable_func_labels (funcs : Cfg.func list) =
  let by_label = Hashtbl.create (max 8 (List.length funcs)) in
  List.iter (fun (f : Cfg.func) -> Hashtbl.replace by_label f.label f) funcs;
  let rec find_main_label = function
    | [] -> None
    | (f : Cfg.func) :: rest ->
        if f.name = "main" then Some f.label else find_main_label rest
  in
  let main_label = find_main_label funcs in
  match main_label with
  | None -> LabelSet.empty
  | Some main_label ->
      let rec visit work seen =
        match work with
        | [] -> seen
        | label :: rest ->
            if LabelSet.mem label seen then visit rest seen
            else
              let seen = LabelSet.add label seen in
              let rest =
                match Hashtbl.find_opt by_label label with
                | None -> rest
                | Some f ->
                    LabelSet.fold
                      (fun callee acc ->
                        if Hashtbl.mem by_label callee then callee :: acc else acc)
                      (direct_callees_of_func f) rest
              in
              visit rest seen
      in
      visit [ main_label ] LabelSet.empty

let collect_call_global_demands summaries globals return_globals (f : Cfg.func) =
  let live_in_t, live_in_p =
    compute_liveness_with_return_globals summaries globals return_globals f
  in
  let demands = Hashtbl.create 8 in
  let add_demand callee needed =
    if not (PlaceSet.is_empty needed) then
      let prev =
        match Hashtbl.find_opt demands callee with
        | Some prev -> prev
        | None -> PlaceSet.empty
      in
      Hashtbl.replace demands callee (PlaceSet.union prev needed)
  in
  List.iter
    (fun (block : Cfg.block) ->
      let live_t_out =
        List.fold_left
          (fun acc succ ->
            IntSet.union acc (table_find_or_empty live_in_t succ IntSet.empty))
          IntSet.empty block.succs
      in
      let live_p_out =
        List.fold_left
          (fun acc succ ->
            PlaceSet.union acc (table_find_or_empty live_in_p succ PlaceSet.empty))
          PlaceSet.empty block.succs
      in
      let _, live_t, live_p =
        scan_terminator ~return_globals globals block.term live_t_out live_p_out
      in
      ignore
        (List.fold_left
           (fun (live_t, live_p) instr ->
             begin
               match instr with
               | Tcg.Call (_, callee, _) ->
                   let needed =
                     PlaceSet.inter
                       (global_places live_p)
                       (call_written_globals summaries globals callee)
                   in
                   add_demand callee needed
               | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ -> ()
             end;
             let _, live_t, live_p =
               scan_simple_instr summaries globals instr live_t live_p
             in
             (live_t, live_p))
           (live_t, live_p) (List.rev block.body)))
    f.blocks;
  demands

let compute_return_global_demands summaries globals (funcs : Cfg.func list) =
  let reachable = reachable_func_labels funcs in
  let demands = Hashtbl.create (max 8 (List.length funcs)) in
  List.iter
    (fun (f : Cfg.func) ->
      Hashtbl.replace demands f.label
        (if LabelSet.mem f.label reachable then PlaceSet.empty else globals))
    funcs;
  let changed = ref true in
  while !changed do
    changed := false;
    List.iter
      (fun (f : Cfg.func) ->
        if LabelSet.mem f.label reachable then
          let return_globals =
            match Hashtbl.find_opt demands f.label with
            | Some globals -> globals
            | None -> PlaceSet.empty
          in
          let call_demands =
            collect_call_global_demands summaries globals return_globals f
          in
          Hashtbl.iter
            (fun callee needed ->
              if LabelSet.mem callee reachable then
                let prev =
                  match Hashtbl.find_opt demands callee with
                  | Some prev -> prev
                  | None -> PlaceSet.empty
                in
                let next = PlaceSet.union prev needed in
                if not (PlaceSet.equal prev next) then (
                  Hashtbl.replace demands callee next;
                  changed := true))
            call_demands)
      funcs
  done;
  if Sys.getenv_opt "TOYC_DEBUG_GLOBAL_DSE" <> None then
    List.iter
      (fun (f : Cfg.func) ->
        let required =
          match Hashtbl.find_opt demands f.label with
          | Some required -> required
          | None -> globals
        in
        Printf.eprintf
          "global-dse-demand func=%s reachable=%b return_globals=%d/%d\n%!"
          f.name (LabelSet.mem f.label reachable)
          (PlaceSet.cardinal required) (PlaceSet.cardinal globals))
      funcs;
  demands

let collect_local_ids (f : Cfg.func) =
  List.fold_left
    (fun acc (var : Tcg.var) -> IntSet.add var.id acc)
    IntSet.empty (f.params @ f.locals)

let all_present values =
  let rec loop acc = function
    | [] -> Some (List.rev acc)
    | Some value :: rest -> loop (value :: acc) rest
    | None :: _ -> None
  in
  loop [] values

let all_same_operand = function
  | [] -> None
  | value :: rest ->
      if List.for_all (fun other -> other = value) rest then Some value else None

let get_or_create_phi_temp phi_temps fresh_temp key =
  match Hashtbl.find_opt phi_temps key with
  | Some temp -> temp
  | None ->
      let temp = fresh_temp () in
      Hashtbl.add phi_temps key temp;
      temp

let merge_incoming_operand preds lookup make_phi =
  match preds with
  | [] -> None
  | _ -> (
      match all_present (List.map lookup preds) with
      | Some values -> (
          match all_same_operand values with
          | Some value -> Some value
          | None -> Some (Tcg.Temp (make_phi ())))
      | None -> None)

(* mem2reg needs a slightly more optimistic merge at loop headers.
   During the first dataflow iterations a backedge may not have an out-value
   yet even though it will acquire one once the loop phi exists.  Treat a
   mixture of present and temporarily-missing predecessors as a provisional
   phi so the fixed point can bootstrap.  A later validation step still
   rejects the candidate if any predecessor remains genuinely undefined. *)
let merge_incoming_operand_mem2reg preds lookup make_phi =
  match preds with
  | [] -> None
  | _ ->
      let incoming = List.map lookup preds in
      begin
        match all_present incoming with
        | Some values -> (
            match all_same_operand values with
            | Some value -> Some value
            | None -> Some (Tcg.Temp (make_phi ())))
        | None ->
            if List.exists Option.is_some incoming then
              Some (Tcg.Temp (make_phi ()))
            else None
      end

let solve_forward_envs blocks ~empty_env ~equal_env ~compute_in_env ~transfer_env =
  let in_envs = Hashtbl.create (List.length blocks) in
  let out_envs = Hashtbl.create (List.length blocks) in
  let get_env table label = table_find_or_empty table label empty_env in
  let get_out label = get_env out_envs label in
  let changed = ref true in
  while !changed do
    changed := false;
    List.iter
      (fun (block : Cfg.block) ->
        let in_env = compute_in_env get_out block in
        let out_env = transfer_env in_env block in
        if not (equal_env in_env (get_env in_envs block.label)) then (
          Hashtbl.replace in_envs block.label in_env;
          changed := true);
        if not (equal_env out_env (get_env out_envs block.label)) then (
          Hashtbl.replace out_envs block.label out_env;
          changed := true))
      blocks
  done;
  (in_envs, out_envs, get_env)

let defs_temp = function
  | Tcg.Move (dst, _)
  | Tcg.Un (dst, _, _)
  | Tcg.Bin (dst, _, _, _)
  | Tcg.Load (dst, _) ->
      Some dst
  | Tcg.Store _ | Tcg.Call (None, _, _) -> None
  | Tcg.Call (Some dst, _, _) -> Some dst

let add_instr_use_temps live = function
  | Tcg.Move (_, src)
  | Tcg.Un (_, _, src) ->
      add_operand_temps live src
  | Tcg.Bin (_, _, lhs, rhs) ->
      add_operand_temps (add_operand_temps live lhs) rhs
  | Tcg.Load _ -> live
  | Tcg.Store (_, value) -> add_operand_temps live value
  | Tcg.Call (_, _, args) -> List.fold_left add_operand_temps live args

let add_term_use_temps live = function
  | Cfg.Jump _ | Cfg.Return None -> live
  | Cfg.BranchZero (cond, _, _)
  | Cfg.BranchNonZero (cond, _, _)
  | Cfg.Return (Some cond) ->
      add_operand_temps live cond
  | Cfg.BranchCompare (_, lhs, rhs, _, _) ->
      add_operand_temps (add_operand_temps live lhs) rhs

let rewrite_operand_temp rename = function
  | Tcg.Imm _ as operand -> operand
  | Tcg.Temp temp -> Tcg.Temp (rename temp)

let rewrite_instr_temps rename = function
  | Tcg.Move (dst, src) ->
      Tcg.Move (rename dst, rewrite_operand_temp rename src)
  | Tcg.Un (dst, op, src) ->
      Tcg.Un (rename dst, op, rewrite_operand_temp rename src)
  | Tcg.Bin (dst, op, lhs, rhs) ->
      Tcg.Bin
        ( rename dst,
          op,
          rewrite_operand_temp rename lhs,
          rewrite_operand_temp rename rhs )
  | Tcg.Load (dst, place) -> Tcg.Load (rename dst, place)
  | Tcg.Store (place, value) -> Tcg.Store (place, rewrite_operand_temp rename value)
  | Tcg.Call (dst, callee, args) ->
      Tcg.Call
        ( Option.map rename dst,
          callee,
          List.map (rewrite_operand_temp rename) args )

let rewrite_term_temps rename = function
  | Cfg.Jump _ as term -> term
  | Cfg.BranchZero (cond, if_zero, if_nonzero) ->
      Cfg.BranchZero (rewrite_operand_temp rename cond, if_zero, if_nonzero)
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) ->
      Cfg.BranchNonZero (rewrite_operand_temp rename cond, if_nonzero, if_zero)
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
      Cfg.BranchCompare
        ( op,
          rewrite_operand_temp rename lhs,
          rewrite_operand_temp rename rhs,
          if_true,
          if_false )
  | Cfg.Return None -> Cfg.Return None
  | Cfg.Return (Some value) -> Cfg.Return (Some (rewrite_operand_temp rename value))

let copy_coalesce_func summaries globals (f : Cfg.func) =
  let debug_coalesce = Sys.getenv_opt "TOYC_DEBUG_COALESCE" <> None in
  if f.temp_count <= 1 then begin
    if debug_coalesce then
      Printf.eprintf
        "coalesce func=%s candidates=0 merged=0 removed_moves=0 temps=%d->%d\n%!"
        f.name f.temp_count f.temp_count;
    f
  end else
    let live_in_t, _ = compute_liveness summaries globals f in
    let interference = Array.make f.temp_count IntSet.empty in
    let add_edge a b =
      if a <> b && a >= 0 && b >= 0 && a < f.temp_count && b < f.temp_count then begin
        interference.(a) <- IntSet.add b interference.(a);
        interference.(b) <- IntSet.add a interference.(b)
      end
    in
    let candidates_rev = ref [] in
    List.iter
      (fun (block : Cfg.block) ->
        let live = ref (add_term_use_temps (live_out_t live_in_t block) block.term) in
        List.iter
          (fun instr ->
            begin
              match instr with
              | Tcg.Move (dst, Tcg.Temp src) when dst <> src ->
                  candidates_rev := (dst, src) :: !candidates_rev;
                  IntSet.iter
                    (fun temp -> if temp <> src then add_edge dst temp)
                    !live
              | _ -> (
                  match defs_temp instr with
                  | Some dst -> IntSet.iter (add_edge dst) !live
                  | None -> ())
            end;
            begin
              match defs_temp instr with
              | Some dst -> live := IntSet.remove dst !live
              | None -> ()
            end;
            live := add_instr_use_temps !live instr)
          (List.rev block.body))
      f.blocks;
    let parent = Array.init f.temp_count (fun temp -> temp) in
    let members = Array.init f.temp_count (fun temp -> IntSet.singleton temp) in
    let rec find temp =
      let p = parent.(temp) in
      if p = temp then temp
      else begin
        let root = find p in
        parent.(temp) <- root;
        root
      end
    in
    let components_interfere a b =
      let ra = find a in
      let rb = find b in
      if ra = rb then false
      else
        IntSet.fold
          (fun member found ->
            found
            || IntSet.fold
                 (fun neighbor found -> found || find neighbor = rb)
                 interference.(member) false)
          members.(ra) false
    in
    let merge a b =
      let ra = find a in
      let rb = find b in
      if ra = rb || components_interfere ra rb then false
      else begin
        let keep, drop = if ra <= rb then (ra, rb) else (rb, ra) in
        parent.(drop) <- keep;
        members.(keep) <- IntSet.union members.(keep) members.(drop);
        members.(drop) <- IntSet.empty;
        true
      end
    in
    let merged = ref 0 in
    List.iter
      (fun (dst, src) ->
        if dst >= 0 && src >= 0 && dst < f.temp_count && src < f.temp_count && merge dst src then
          incr merged)
      (List.rev !candidates_rev);
    if !merged = 0 then begin
      if debug_coalesce then
        Printf.eprintf
          "coalesce func=%s candidates=%d merged=0 removed_moves=0 temps=%d->%d\n%!"
          f.name (List.length !candidates_rev) f.temp_count f.temp_count;
      f
    end else
      let rename temp =
        if temp >= 0 && temp < f.temp_count then find temp else temp
      in
      let removed_moves = ref 0 in
      let rewrite_block (block : Cfg.block) =
        let body =
          List.filter_map
            (fun instr ->
              let instr = simplify_simple_instr (rewrite_instr_temps rename instr) in
              match instr with
              | Tcg.Move (dst, Tcg.Temp src) when dst = src ->
                  incr removed_moves;
                  None
              | _ -> Some instr)
            block.body
        in
        let term = rewrite_term_temps rename block.term in
        { block with body; term; succs = Cfg.successors term }
      in
      let blocks = List.map rewrite_block f.blocks in
      let rewritten = Cfg.rebuild_edges { f with blocks } in
      let used = ref IntSet.empty in
      let note_operand = function
        | Tcg.Temp temp -> used := IntSet.add temp !used
        | Tcg.Imm _ -> ()
      in
      let note_instr instr =
        begin
          match defs_temp instr with
          | Some temp -> used := IntSet.add temp !used
          | None -> ()
        end;
        match instr with
        | Tcg.Move (_, src)
        | Tcg.Un (_, _, src) -> note_operand src
        | Tcg.Bin (_, _, lhs, rhs) -> note_operand lhs; note_operand rhs
        | Tcg.Load _ -> ()
        | Tcg.Store (_, value) -> note_operand value
        | Tcg.Call (_, _, args) -> List.iter note_operand args
      in
      let note_term = function
        | Cfg.Jump _ | Cfg.Return None -> ()
        | Cfg.BranchZero (cond, _, _)
        | Cfg.BranchNonZero (cond, _, _)
        | Cfg.Return (Some cond) -> note_operand cond
        | Cfg.BranchCompare (_, lhs, rhs, _, _) -> note_operand lhs; note_operand rhs
      in
      List.iter
        (fun (block : Cfg.block) ->
          List.iter note_instr block.body;
          note_term block.term)
        rewritten.blocks;
      let dense = Hashtbl.create (IntSet.cardinal !used) in
      IntSet.elements !used
      |> List.iteri (fun next old -> Hashtbl.add dense old next);
      let dense_rename temp = Option.value ~default:temp (Hashtbl.find_opt dense temp) in
      let blocks =
        List.map
          (fun (block : Cfg.block) ->
            let body = List.map (rewrite_instr_temps dense_rename) block.body in
            let term = rewrite_term_temps dense_rename block.term in
            { block with body; term; succs = Cfg.successors term })
          rewritten.blocks
      in
      if debug_coalesce then
        Printf.eprintf
          "coalesce func=%s candidates=%d merged=%d removed_moves=%d temps=%d->%d\n%!"
          f.name (List.length !candidates_rev) !merged !removed_moves f.temp_count
          (IntSet.cardinal !used);
      Cfg.rebuild_edges
        { rewritten with temp_count = IntSet.cardinal !used; blocks }

let rewrite_term_target pred target redirects =
  match Hashtbl.find_opt redirects (pred, target) with
  | Some redirected -> redirected
  | None -> target

let redirect_successors pred redirects = function
  | Cfg.Jump label -> Cfg.Jump (rewrite_term_target pred label redirects)
  | Cfg.BranchZero (cond, if_zero, if_nonzero) ->
      Cfg.BranchZero
        ( cond,
          rewrite_term_target pred if_zero redirects,
          rewrite_term_target pred if_nonzero redirects )
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) ->
      Cfg.BranchNonZero
        ( cond,
          rewrite_term_target pred if_nonzero redirects,
          rewrite_term_target pred if_zero redirects )
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
      Cfg.BranchCompare
        ( op,
          lhs,
          rhs,
          rewrite_term_target pred if_true redirects,
          rewrite_term_target pred if_false redirects )
  | Cfg.Return value -> Cfg.Return value

let build_parallel_copies fresh_temp copies =
  let rec remove_first target = function
    | [] -> []
    | copy :: rest ->
        if copy = target then rest else copy :: remove_first target rest
  in
  let rec schedule acc copies =
    let copies = List.filter (fun (dst, src) -> src <> Tcg.Temp dst) copies in
    match copies with
    | [] -> List.rev acc
    | _ ->
        let source_temps =
          List.fold_left
            (fun temps (_, src) ->
              match src with
              | Tcg.Temp temp -> IntSet.add temp temps
              | Tcg.Imm _ -> temps)
            IntSet.empty copies
        in
        begin
          match
            List.find_opt
              (fun (dst, _) -> not (IntSet.mem dst source_temps))
              copies
          with
          | Some ((dst, src) as copy) ->
              let instr = simplify_simple_instr (Tcg.Move (dst, src)) in
              schedule (instr :: acc) (remove_first copy copies)
          | None ->
              begin
                match copies with
                | (_, Tcg.Temp src_temp) :: _ ->
                    let snap_temp = fresh_temp () in
                    let snapshot =
                      simplify_simple_instr (Tcg.Move (snap_temp, Tcg.Temp src_temp))
                    in
                    let replacement = Tcg.Temp snap_temp in
                    let copies =
                      List.map
                        (fun (dst, src) ->
                          if src = Tcg.Temp src_temp then (dst, replacement)
                          else (dst, src))
                        copies
                    in
                    schedule (snapshot :: acc) copies
                | (_, Tcg.Imm _) :: _ ->
                    failwith "internal parallel-copy cycle"
                | [] -> List.rev acc
              end
        end
  in
  schedule [] copies

let place_edge_copies fresh_edge_label blocks edge_copies =
  let block_map = Hashtbl.create (List.length blocks) in
  List.iter
    (fun (block : Cfg.block) -> Hashtbl.replace block_map block.label block)
    blocks;
  let prepended_copies = Hashtbl.create 16 in
  let appended_copies = Hashtbl.create 16 in
  let redirects = Hashtbl.create 16 in
  let edge_blocks_rev = ref [] in
  let only_edge labels target =
    labels <> [] && List.for_all (fun label -> label = target) labels
  in
  List.iter
    (fun (pred, succ, body) ->
      match Hashtbl.find_opt block_map pred with
      | Some block when only_edge block.succs succ ->
          Hashtbl.replace appended_copies pred body
      | _ ->
          let succ_preds =
            match Hashtbl.find_opt block_map succ with
            | Some block -> block.preds
            | None -> []
          in
          if only_edge succ_preds pred then
            Hashtbl.replace prepended_copies succ body
          else
            let edge_label = fresh_edge_label () in
            Hashtbl.add redirects (pred, succ) edge_label;
            edge_blocks_rev :=
              {
                Cfg.label = edge_label;
                body;
                term = Cfg.Jump succ;
                preds = [];
                succs = [ succ ];
              }
              :: !edge_blocks_rev)
    edge_copies;
  List.map
    (fun (block : Cfg.block) ->
      let prefix =
        Option.value ~default:[] (Hashtbl.find_opt prepended_copies block.label)
      in
      let suffix =
        Option.value ~default:[] (Hashtbl.find_opt appended_copies block.label)
      in
      let term = redirect_successors block.label redirects block.term in
      {
        block with
        body = prefix @ block.body @ suffix;
        term;
        succs = Cfg.successors term;
      })
    blocks
  @ List.rev !edge_blocks_rev

let mem2reg_func ?(optimistic_loop_phi = false) (f : Cfg.func) =
  let all_candidates = collect_local_ids f in
  let rec attempt (current : Cfg.func) candidates =
    if IntSet.is_empty candidates then current
    else begin
      let next_temp = ref current.temp_count in
      let fresh_temp () =
        let temp = !next_temp in
        incr next_temp;
        temp
      in
      let seed_env =
        List.fold_left
          (fun env (param : Tcg.var) ->
            if IntSet.mem param.id candidates then
              let temp = fresh_temp () in
              IntMap.add param.id (Tcg.Temp temp) env
            else env)
          IntMap.empty current.params
      in
      let phi_temps = Hashtbl.create (max 8 (List.length current.blocks)) in
      let get_phi_temp label local_id =
        get_or_create_phi_temp phi_temps fresh_temp (label, local_id)
      in
      (* Local live-in analysis for mem2reg phi placement.

         A source-level local declared inside an enclosing loop can be
         reinitialized before every use in that enclosing iteration.  Such a
         local is not live into the outer header and must not receive a phi
         there.  The old optimistic merge created provisional phis solely from
         "some predecessor has a value", which made an inner-loop IV such as
         [j] appear to need a value on the function-entry edge and therefore
         fail validation.

         Compute ordinary backward liveness for Local ids:
           use[b] = loads before the first store in b
           def[b] = locals stored in b
           in[b]  = use[b] U (out[b] - def[b])
           out[b] = U in[succ]

         Phi/merge state is needed only for locals live at block entry. *)
      let local_use = Hashtbl.create (List.length current.blocks) in
      let local_def = Hashtbl.create (List.length current.blocks) in
      List.iter
        (fun (block : Cfg.block) ->
          let defs = ref IntSet.empty in
          let uses = ref IntSet.empty in
          List.iter
            (function
              | Tcg.Load (_, Tcg.Local id) when IntSet.mem id candidates ->
                  if not (IntSet.mem id !defs) then
                    uses := IntSet.add id !uses
              | Tcg.Store (Tcg.Local id, _) when IntSet.mem id candidates ->
                  defs := IntSet.add id !defs
              | Tcg.Move _
              | Tcg.Un _
              | Tcg.Bin _
              | Tcg.Load _
              | Tcg.Store _
              | Tcg.Call _ ->
                  ())
            block.body;
          Hashtbl.replace local_use block.label !uses;
          Hashtbl.replace local_def block.label !defs)
        current.blocks;
      let local_live_in = Hashtbl.create (List.length current.blocks) in
      let local_live_out = Hashtbl.create (List.length current.blocks) in
      let get_local_set table label =
        Option.value ~default:IntSet.empty (Hashtbl.find_opt table label)
      in
      let live_changed = ref true in
      while !live_changed do
        live_changed := false;
        List.iter
          (fun (block : Cfg.block) ->
            let out_set =
              List.fold_left
                (fun acc succ ->
                  IntSet.union acc (get_local_set local_live_in succ))
                IntSet.empty block.succs
            in
            let use_set = get_local_set local_use block.label in
            let def_set = get_local_set local_def block.label in
            let in_set =
              IntSet.union
                use_set
                (IntSet.diff out_set def_set)
            in
            if not (IntSet.equal out_set (get_local_set local_live_out block.label)) then begin
              Hashtbl.replace local_live_out block.label out_set;
              live_changed := true
            end;
            if not (IntSet.equal in_set (get_local_set local_live_in block.label)) then begin
              Hashtbl.replace local_live_in block.label in_set;
              live_changed := true
            end)
          (List.rev current.blocks)
      done;
      let local_is_live_in label local_id =
        IntSet.mem local_id (get_local_set local_live_in label)
      in
      if Sys.getenv_opt "TOYC_DEBUG_MEM2REG_LOOP_PHI" <> None then
        List.iter
          (fun (block : Cfg.block) ->
            let live =
              get_local_set local_live_in block.label
              |> IntSet.elements
              |> List.map string_of_int
              |> String.concat ","
            in
            Printf.eprintf
              "mem2reg-livein func=%s label=%s locals={%s}\n%!"
              current.name block.label live)
          current.blocks;
      let compute_in_env get_out (block : Cfg.block) =
        if block.label = current.entry then seed_env
        else
          IntSet.fold
            (fun local_id env ->
              if not (local_is_live_in block.label local_id) then
                IntMap.remove local_id env
              else
                let merge =
                  if optimistic_loop_phi then merge_incoming_operand_mem2reg
                  else merge_incoming_operand
                in
                let keep_value =
                  merge block.preds
                    (fun pred -> IntMap.find_opt local_id (get_out pred))
                    (fun () -> get_phi_temp block.label local_id)
                in
                match keep_value with
                | Some value -> IntMap.add local_id value env
                | None -> IntMap.remove local_id env)
            candidates IntMap.empty
      in
      let transfer_env env (block : Cfg.block) =
        List.fold_left
          (fun env instr ->
            match instr with
            | Tcg.Store (Tcg.Local id, value) when IntSet.mem id candidates -> IntMap.add id value env
            | _ -> env)
          env block.body
      in
      let in_envs, out_envs, get_env =
        solve_forward_envs current.blocks ~empty_env:IntMap.empty
          ~equal_env:equal_operand_map ~compute_in_env ~transfer_env
      in
      let failed = ref IntSet.empty in
      List.iter
        (fun (block : Cfg.block) ->
          let env = ref (get_env in_envs block.label) in
          List.iter
            (fun instr ->
              match instr with
              | Tcg.Load (_, Tcg.Local id) when IntSet.mem id candidates ->
                  if not (IntMap.mem id !env) then failed := IntSet.add id !failed
              | Tcg.Store (Tcg.Local id, value) when IntSet.mem id candidates ->
                  env := IntMap.add id value !env
              | _ -> ())
            block.body;
          Hashtbl.iter
            (fun (phi_label, local_id) _ ->
              if phi_label = block.label
                 && local_is_live_in block.label local_id
              then
                match IntMap.find_opt local_id (get_env in_envs block.label) with
                | Some (Tcg.Temp _) ->
                    List.iter
                      (fun pred ->
                        if not (IntMap.mem local_id (get_env out_envs pred)) then
                          failed := IntSet.add local_id !failed)
                      block.preds
                | _ -> ())
            phi_temps)
        current.blocks;
      let succeeded = IntSet.diff candidates !failed in
      if Sys.getenv_opt "TOYC_DEBUG_MEM2REG_LOOP_PHI" <> None then
        Printf.eprintf
          "mem2reg-loop-phi func=%s mode=%s candidates=%d succeeded=%d failed=%d phis=%d\n%!"
          current.name
          (if optimistic_loop_phi then "optimistic" else "conservative")
          (IntSet.cardinal candidates)
          (IntSet.cardinal succeeded)
          (IntSet.cardinal !failed)
          (Hashtbl.length phi_temps);
      if IntSet.is_empty succeeded then current
      else
        let entry_seed_instrs =
          List.fold_left
            (fun acc (param : Tcg.var) ->
              if IntSet.mem param.id succeeded then
                match IntMap.find_opt param.id seed_env with
                | Some (Tcg.Temp temp) ->
                    simplify_simple_instr (Tcg.Load (temp, Tcg.Local param.id)) :: acc
                | Some (Tcg.Imm _) | None -> acc
              else acc)
            [] current.params
          |> List.rev
        in
        let rewrite_block (block : Cfg.block) =
          let rec rewrite env acc = function
            | [] -> List.rev acc
            | instr :: rest -> (
                match instr with
                | Tcg.Load (dst, Tcg.Local id) when IntSet.mem id succeeded -> (
                    match IntMap.find_opt id env with
                    | Some value ->
                        rewrite env (simplify_simple_instr (Tcg.Move (dst, value)) :: acc) rest
                    | None -> rewrite env (instr :: acc) rest)
                | Tcg.Store (Tcg.Local id, value) when IntSet.mem id succeeded ->
                    rewrite (IntMap.add id value env) acc rest
                | _ -> rewrite env (instr :: acc) rest)
          in
          let body =
            (if block.label = current.entry then entry_seed_instrs else [])
            @ rewrite (get_env in_envs block.label) [] block.body
          in
          { block with body }
        in
        let promoted_blocks = List.map rewrite_block current.blocks in
        let edge_id = ref 0 in
        let fresh_edge_label () =
          let id = !edge_id in
          incr edge_id;
          Printf.sprintf ".L%s_mem2reg_edge_%d" current.label id
        in
        let edge_copies_rev = ref [] in
        List.iter
          (fun (succ_block : Cfg.block) ->
            let phi_copies =
              IntSet.fold
                (fun local_id acc ->
                  match Hashtbl.find_opt phi_temps (succ_block.label, local_id) with
                  | Some phi_temp -> (
                      (* A provisional phi may have been created during an
                         intermediate solver iteration and later become
                         unnecessary.  Emit edge copies only when the final
                         fixed-point in-env actually uses this phi. *)
                      match IntMap.find_opt local_id (get_env in_envs succ_block.label) with
                      | Some (Tcg.Temp temp) when temp = phi_temp ->
                          (local_id, phi_temp) :: acc
                      | Some _ | None -> acc)
                  | None -> acc)
                succeeded []
            in
            if phi_copies <> [] then
              List.iter
                (fun pred ->
                  let pred_out = get_env out_envs pred in
                  let copies =
                    List.fold_left
                      (fun acc (local_id, phi_temp) ->
                        match IntMap.find_opt local_id pred_out with
                        | Some source when source <> Tcg.Temp phi_temp ->
                            (phi_temp, source) :: acc
                        | Some _ | None -> acc)
                      [] phi_copies
                  in
                  match build_parallel_copies fresh_temp (List.rev copies) with
                  | [] -> ()
                  | body ->
                      edge_copies_rev :=
                        (pred, succ_block.label, body) :: !edge_copies_rev)
                succ_block.preds)
          promoted_blocks;
        let blocks =
          place_edge_copies fresh_edge_label promoted_blocks (List.rev !edge_copies_rev)
        in
        let promoted = Cfg.rebuild_edges { current with temp_count = !next_temp; blocks } in
        if IntSet.is_empty !failed then promoted else attempt promoted !failed
    end
  in
  attempt f all_candidates

let promote_globals_func summaries globals (f : Cfg.func) =
  let stored_candidates = stored_globals_in_func f in
  let readonly_candidates = PlaceSet.diff (globals_in_func f) stored_candidates in
  let all_candidates = PlaceSet.union stored_candidates readonly_candidates in
  let rec attempt candidates =
    if PlaceSet.is_empty candidates then f
    else begin
      let writeback_candidates = PlaceSet.inter stored_candidates candidates in
      let preload_candidates = candidates in
      let next_temp = ref f.temp_count in
      let fresh_temp () =
        let temp = !next_temp in
        incr next_temp;
        temp
      in
      let phi_temps = Hashtbl.create (max 8 (List.length f.blocks)) in
      let entry_preloads_rev = ref [] in
      let entry_env =
        PlaceSet.fold
          (fun place env ->
            let temp = fresh_temp () in
            entry_preloads_rev :=
              simplify_simple_instr (Tcg.Load (temp, place)) :: !entry_preloads_rev;
            PlaceMap.add place (Tcg.Temp temp) env)
          preload_candidates PlaceMap.empty
      in
      let entry_preloads = List.rev !entry_preloads_rev in
      let kill_env_places places env =
        PlaceSet.fold (fun place env -> PlaceMap.remove place env) places env
      in
      let flush_env_places places env =
        PlaceSet.elements places
        |> List.filter_map (fun place ->
               match PlaceMap.find_opt place env with
               | Some value -> Some (Tcg.Store (place, value))
               | None -> None)
      in
      let get_phi_temp label place =
        get_or_create_phi_temp phi_temps fresh_temp (label, place)
      in
      let compute_in_env get_out (block : Cfg.block) =
        if block.label = f.entry then entry_env
        else
          PlaceSet.fold
            (fun place env ->
              let keep_value =
                merge_incoming_operand block.preds
                  (fun pred -> PlaceMap.find_opt place (get_out pred))
                  (fun () -> get_phi_temp block.label place)
              in
              match keep_value with
              | Some value -> PlaceMap.add place value env
              | None -> PlaceMap.remove place env)
            candidates PlaceMap.empty
      in
      let transfer_env env (block : Cfg.block) =
        List.fold_left
          (fun env instr ->
            match instr with
            | Tcg.Load (dst, place) when PlaceSet.mem place candidates ->
                PlaceMap.add place (Tcg.Temp dst) env
            | Tcg.Store (place, value) when PlaceSet.mem place candidates -> PlaceMap.add place value env
            | Tcg.Call (_, callee, _) ->
                kill_env_places
                  (PlaceSet.inter candidates (call_written_globals summaries globals callee))
                  env
            | _ -> env)
          env block.body
      in
      let in_envs, out_envs, get_env =
        solve_forward_envs f.blocks ~empty_env:PlaceMap.empty
          ~equal_env:equal_place_operand_map ~compute_in_env ~transfer_env
      in
      let failed = ref PlaceSet.empty in
      List.iter
        (fun (block : Cfg.block) ->
          if block.label <> f.entry then
            PlaceSet.iter
              (fun place ->
                if PlaceSet.mem place writeback_candidates then
                  let incoming =
                    List.map
                      (fun pred -> PlaceMap.find_opt place (get_env out_envs pred))
                      block.preds
                  in
                  match all_present incoming with
                  | Some _ -> ()
                  | None ->
                      if List.exists Option.is_some incoming then
                        failed := PlaceSet.add place !failed)
              candidates;
          let env = ref (get_env in_envs block.label) in
          List.iter
            (fun instr ->
              match instr with
                | Tcg.Load (dst, place) when PlaceSet.mem place candidates ->
                    env := PlaceMap.add place (Tcg.Temp dst) !env
                | Tcg.Store (place, value) when PlaceSet.mem place candidates ->
                    env := PlaceMap.add place value !env
                | Tcg.Call (_, callee, _) ->
                    env :=
                      kill_env_places
                        (PlaceSet.inter candidates (call_written_globals summaries globals callee))
                        !env
                | _ -> ())
            block.body;
          Hashtbl.iter
            (fun (phi_label, place) _ ->
              if phi_label = block.label then
                match PlaceMap.find_opt place (get_env in_envs block.label) with
                | Some (Tcg.Temp _) ->
                    List.iter
                      (fun pred ->
                        if not (PlaceMap.mem place (get_env out_envs pred)) then
                          failed := PlaceSet.add place !failed)
                      block.preds
                | _ -> ())
            phi_temps)
        f.blocks;
      if not (PlaceSet.is_empty !failed) then attempt (PlaceSet.diff candidates !failed)
      else
        let flush_env env =
          PlaceSet.elements writeback_candidates
          |> List.filter_map (fun place ->
                 match PlaceMap.find_opt place env with
                 | Some value -> Some (Tcg.Store (place, value))
                 | None -> None)
        in
        let rewrite_block (block : Cfg.block) =
          let rec rewrite env acc = function
            | [] -> (env, List.rev acc)
            | instr :: rest -> (
                match instr with
                | Tcg.Load (dst, place) when PlaceSet.mem place candidates -> (
                    match PlaceMap.find_opt place env with
                    | Some value ->
                        rewrite env (simplify_simple_instr (Tcg.Move (dst, value)) :: acc) rest
                    | None ->
                        rewrite (PlaceMap.add place (Tcg.Temp dst) env) (instr :: acc) rest)
                | Tcg.Store (place, value) when PlaceSet.mem place candidates ->
                    rewrite (PlaceMap.add place value env) acc rest
                | Tcg.Call (_, callee, _) as instr ->
                    let call_flushes =
                      PlaceSet.inter
                        writeback_candidates
                        (call_touched_globals summaries globals callee)
                    in
                    let call_kills =
                      PlaceSet.inter candidates (call_written_globals summaries globals callee)
                    in
                    let flushed = flush_env_places call_flushes env in
                    let acc = List.rev_append (flushed @ [ instr ]) acc in
                    rewrite (kill_env_places call_kills env) acc rest
                | _ -> rewrite env (instr :: acc) rest)
          in
          let env_out, body = rewrite (get_env in_envs block.label) [] block.body in
          let body =
            let body =
              if block.label = f.entry && entry_preloads <> [] then entry_preloads @ body else body
            in
            match block.term with
            | Cfg.Return _ -> body @ flush_env env_out
            | _ -> body
          in
          { block with body }
        in
        let promoted_blocks = List.map rewrite_block f.blocks in
        let edge_id = ref 0 in
        let fresh_edge_label () =
          let id = !edge_id in
          incr edge_id;
          Printf.sprintf ".L%s_gprom_edge_%d" f.label id
        in
        let edge_copies_rev = ref [] in
        List.iter
          (fun (succ_block : Cfg.block) ->
            let phi_copies =
              PlaceSet.fold
                (fun place acc ->
                  match Hashtbl.find_opt phi_temps (succ_block.label, place) with
                  | Some phi_temp -> (place, phi_temp) :: acc
                  | None -> acc)
                candidates []
            in
            if phi_copies <> [] then
              List.iter
                (fun pred ->
                  let pred_out = get_env out_envs pred in
                  let copies =
                    List.fold_left
                      (fun acc (place, phi_temp) ->
                        match PlaceMap.find_opt place pred_out with
                        | Some source when source <> Tcg.Temp phi_temp -> (phi_temp, source) :: acc
                        | Some _ | None -> acc)
                      [] phi_copies
                  in
                  match build_parallel_copies fresh_temp (List.rev copies) with
                  | [] -> ()
                  | body ->
                      edge_copies_rev :=
                        (pred, succ_block.label, body) :: !edge_copies_rev)
                succ_block.preds)
          promoted_blocks;
        let blocks =
          place_edge_copies fresh_edge_label promoted_blocks (List.rev !edge_copies_rev)
        in
        Cfg.rebuild_edges { f with temp_count = !next_temp; blocks }
    end
  in
  attempt all_candidates

let compute_dominators (f : Cfg.func) =
  match !last_dominator_cache with
  | Some cache
    when !analysis_cache_generation <> 0
         && cache.generation = !analysis_cache_generation
         && cache.entry_label = f.entry
         && cache.temp_count = f.temp_count
         && cache.blocks_key = f.blocks ->
      cache.doms_cache
  | Some _ | None ->
      let reachable = reachable_labels f.entry f.blocks in
      let reachable_blocks =
        List.filter (fun (block : Cfg.block) -> LabelSet.mem block.label reachable) f.blocks
      in
      let all_labels =
        List.fold_left
          (fun acc (block : Cfg.block) -> LabelSet.add block.label acc)
          LabelSet.empty reachable_blocks
      in
      let doms = Hashtbl.create (List.length reachable_blocks) in
      List.iter
        (fun (block : Cfg.block) ->
          Hashtbl.add doms block.label
            (if block.label = f.entry then LabelSet.singleton block.label else all_labels))
        reachable_blocks;
      let changed = ref true in
      while !changed do
        changed := false;
        List.iter
          (fun (block : Cfg.block) ->
            if block.label <> f.entry then
              let pred_doms =
                List.filter (fun pred -> LabelSet.mem pred reachable) block.preds
                |> List.map (fun pred -> table_find_or_empty doms pred all_labels)
              in
              let merged =
                match pred_doms with
                | [] -> all_labels
                | first :: rest -> List.fold_left LabelSet.inter first rest
              in
              let next_dom = LabelSet.add block.label merged in
              if
                not (LabelSet.equal next_dom (table_find_or_empty doms block.label LabelSet.empty))
              then (
                Hashtbl.replace doms block.label next_dom;
                changed := true))
          reachable_blocks
      done;
      if !analysis_cache_generation <> 0 then
        last_dominator_cache :=
          Some
            {
              generation = !analysis_cache_generation;
              entry_label = f.entry;
              temp_count = f.temp_count;
              blocks_key = f.blocks;
              doms_cache = doms;
            };
      doms

type licm_candidate =
  | LicmPure of Tcg.temp * Tcg.operand list
  | LicmLoad of Tcg.temp * Tcg.place

type loop_effects = {
  modified_places : PlaceSet.t;
  has_call : bool;
}

let licm_candidate_info = function
  | Tcg.Move (dst, src) -> Some (LicmPure (dst, [ src ]))
  | Tcg.Un (dst, _, src) -> Some (LicmPure (dst, [ src ]))
  | Tcg.Bin (dst, _, lhs, rhs) -> Some (LicmPure (dst, [ lhs; rhs ]))
  | Tcg.Load (dst, place) -> Some (LicmLoad (dst, place))
  | Tcg.Store _ | Tcg.Call _ -> None

let collect_loop_effects summaries globals loop blocks =
  List.fold_left
    (fun effects (block : Cfg.block) ->
      if not (LabelSet.mem block.label loop) then effects
      else
        List.fold_left
          (fun effects instr ->
            match instr with
            | Tcg.Store (place, _) ->
                { effects with modified_places = PlaceSet.add place effects.modified_places }
            | Tcg.Call (_, callee, _) ->
                {
                  modified_places =
                    PlaceSet.union effects.modified_places
                      (call_written_globals summaries globals callee);
                  has_call = true;
                }
            | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ -> effects)
          effects block.body)
    { modified_places = PlaceSet.empty; has_call = false }
    blocks

let rewrite_term_successor term ~from_label ~to_label =
  let rewrite label = if label = from_label then to_label else label in
  match term with
  | Cfg.Jump label -> Cfg.Jump (rewrite label)
  | Cfg.BranchZero (cond, if_zero, if_nonzero) ->
      Cfg.BranchZero (cond, rewrite if_zero, rewrite if_nonzero)
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) ->
      Cfg.BranchNonZero (cond, rewrite if_nonzero, rewrite if_zero)
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
      Cfg.BranchCompare (op, lhs, rhs, rewrite if_true, rewrite if_false)
  | Cfg.Return _ as term -> term

let loop_defined_temps loop get_block =
  LabelSet.fold
    (fun label acc ->
      let block : Cfg.block = get_block label in
      List.fold_left
        (fun acc instr ->
          match defs_temp instr with
          | Some temp -> IntSet.add temp acc
          | None -> acc)
        acc block.body)
    loop IntSet.empty

let get_block_exn block_map label =
  match Hashtbl.find_opt block_map label with
  | Some block -> block
  | None -> failwith ("internal missing block: " ^ label)

let natural_loop block_map header pred =
  let rec visit work seen =
    match work with
    | [] -> seen
    | label :: rest ->
        if LabelSet.mem label seen then visit rest seen
        else
          let seen = LabelSet.add label seen in
          match Hashtbl.find_opt block_map label with
          | Some (block : Cfg.block) -> visit (List.rev_append block.preds rest) seen
          | None -> visit rest seen
  in
  visit [ pred ] (LabelSet.singleton header)
let discover_natural_loops (f : Cfg.func) =
  let block_map = Hashtbl.create (List.length f.blocks) in
  List.iter
    (fun (block : Cfg.block) -> Hashtbl.add block_map block.label block)
    f.blocks;
  let doms = compute_dominators f in
  let backedges =
    List.fold_left
      (fun acc (block : Cfg.block) ->
        List.fold_left
          (fun acc succ ->
            if LabelSet.mem succ (table_find_or_empty doms block.label LabelSet.empty) then
              (block.label, succ) :: acc
            else acc)
          acc block.succs)
      [] f.blocks
  in
  let loops = Hashtbl.create 8 in
  List.iter
    (fun (pred, header) ->
      let loop = natural_loop block_map header pred in
      let merged = LabelSet.union loop (table_find_or_empty loops header LabelSet.empty) in
      Hashtbl.replace loops header merged)
    backedges;
  let headers =
    Hashtbl.fold
      (fun header loop acc ->
        (header, LabelSet.cardinal loop) :: acc)
      loops
      []
    |> List.sort
         (fun (header_a, size_a) (header_b, size_b) ->
           let by_size = compare size_a size_b in
           if by_size <> 0 then by_size
           else String.compare header_a header_b)
    |> List.map fst
  in
  (block_map, loops, headers)

(* -------------------------------------------------------------------------- *)
(* item2.1: LoopForest / canonical loop metadata                              *)
(*                                                                            *)
(* [discover_natural_loops] intentionally remains the low-level compatibility  *)
(* API used by older passes.  LoopForest adds the hierarchy and structural     *)
(* facts that nested-loop reasoning needs without changing those old clients.   *)
(*                                                                            *)
(* Important distinction:                                                     *)
(*   blocks            = the complete natural-loop region, including children; *)
(*   exclusive_blocks  = blocks executed at this loop level, excluding all     *)
(*                       immediate child-loop regions (and therefore their      *)
(*                       descendants).                                         *)
(*                                                                            *)
(* This is the key fact missing from the old global direct-AddRec recognizer:   *)
(* a static self-update inside a child loop is not a once-per-parent-iteration  *)
(* update.                                                                      *)
(* -------------------------------------------------------------------------- *)

type loop_forest_info = {
  loop_info_header : Tcg.label;
  loop_info_blocks : LabelSet.t;
  loop_info_parent : Tcg.label option;
  loop_info_children : Tcg.label list;
  loop_info_depth : int;
  loop_info_exclusive_blocks : LabelSet.t;
  loop_info_preheader : Tcg.label option;
  loop_info_latches : Tcg.label list;
  loop_info_exit_edges : (Tcg.label * Tcg.label) list;
  loop_info_exit_targets : Tcg.label list;
}

type loop_forest = {
  loop_forest_block_map : (Tcg.label, Cfg.block) Hashtbl.t;
  loop_forest_loops : (Tcg.label, LabelSet.t) Hashtbl.t;
  loop_forest_headers : Tcg.label list;
  loop_forest_infos : (Tcg.label, loop_forest_info) Hashtbl.t;
  loop_forest_roots : Tcg.label list;
}

(* item2.6: a stable LoopSimplify view derived from LoopForest.

   This is intentionally metadata + validation first.  We do not force a
   single latch yet: merging latches changes program points and is exactly the
   kind of transformation that can invalidate recurrence phase facts.  Older
   passes may keep handling multi-latch loops, while new consumers can request
   [loop_simplify_ready] or stronger individual invariants explicitly. *)
type loop_simplify_info = {
  loop_simplify_header : Tcg.label;
  loop_simplify_preheader : Tcg.label option;
  loop_simplify_latches : Tcg.label list;
  loop_simplify_exit_edges : (Tcg.label * Tcg.label) list;
  loop_simplify_exit_targets : Tcg.label list;
  loop_simplify_exit_control_blocks : Tcg.label list;
  loop_simplify_unique_preheader : bool;
  loop_simplify_has_latch : bool;
  loop_simplify_single_latch : bool;
  loop_simplify_dedicated_exits : bool;
  loop_simplify_single_exit_control : bool;
  loop_simplify_control_block : Tcg.label option;
  loop_simplify_ready : bool;
}

type loop_simplify_report = {
  loop_simplify_forest : loop_forest;
  loop_simplify_infos :
    (Tcg.label, loop_simplify_info) Hashtbl.t;
  loop_simplify_all_ready : bool;
}

let strict_labelset_subset a b =
  LabelSet.subset a b && not (LabelSet.equal a b)

let build_loop_forest (f : Cfg.func) =
  let block_map, loops, headers =
    discover_natural_loops f
  in
  let parent_of = Hashtbl.create (max 8 (List.length headers)) in
  List.iter
    (fun header ->
      let blocks =
        table_find_or_empty loops header LabelSet.empty
      in
      let parent =
        headers
        |> List.filter_map
             (fun candidate_header ->
               if candidate_header = header then None
               else
                 let candidate_blocks =
                   table_find_or_empty
                     loops candidate_header LabelSet.empty
                 in
                 if
                   strict_labelset_subset
                     blocks candidate_blocks
                 then
                   Some
                     ( candidate_header,
                       LabelSet.cardinal candidate_blocks )
                 else
                   None)
        |> List.sort
             (fun (ha, sa) (hb, sb) ->
               let by_size = compare sa sb in
               if by_size <> 0 then by_size
               else String.compare ha hb)
        |> function
        | (parent, _) :: _ -> Some parent
        | [] -> None
      in
      Hashtbl.replace parent_of header parent)
    headers;
  let children_of =
    Hashtbl.create (max 8 (List.length headers))
  in
  List.iter
    (fun header ->
      Hashtbl.replace children_of header [])
    headers;
  List.iter
    (fun header ->
      match Hashtbl.find_opt parent_of header with
      | Some (Some parent) ->
          let old =
            Option.value
              ~default:[]
              (Hashtbl.find_opt children_of parent)
          in
          Hashtbl.replace
            children_of parent (header :: old)
      | Some None
      | None ->
          ())
    headers;
  let depth_memo =
    Hashtbl.create (max 8 (List.length headers))
  in
  let rec depth_of seen header =
    match Hashtbl.find_opt depth_memo header with
    | Some depth ->
        depth
    | None ->
        if LabelSet.mem header seen then 0
        else
          let depth =
            match Hashtbl.find_opt parent_of header with
            | Some (Some parent) ->
                1
                + depth_of
                    (LabelSet.add header seen)
                    parent
            | Some None
            | None ->
                0
          in
          Hashtbl.replace depth_memo header depth;
          depth
  in
  let infos =
    Hashtbl.create (max 8 (List.length headers))
  in
  List.iter
    (fun header ->
      let blocks =
        table_find_or_empty loops header LabelSet.empty
      in
      let children =
        Option.value
          ~default:[]
          (Hashtbl.find_opt children_of header)
        |> List.sort String.compare
      in
      let exclusive_blocks =
        List.fold_left
          (fun exclusive child ->
            LabelSet.diff
              exclusive
              (table_find_or_empty
                 loops child LabelSet.empty))
          blocks children
      in
      let header_block =
        get_block_exn block_map header
      in
      let outside_preds =
        List.filter
          (fun pred ->
            not (LabelSet.mem pred blocks))
          header_block.preds
      in
      let preheader =
        match outside_preds with
        | [ pred ] ->
            let pred_block =
              get_block_exn block_map pred
            in
            if pred_block.succs = [ header ]
            then Some pred
            else None
        | []
        | _ :: _ :: _ ->
            None
      in
      let latches =
        header_block.preds
        |> List.filter
             (fun pred -> LabelSet.mem pred blocks)
        |> List.sort_uniq String.compare
      in
      let exit_edges =
        LabelSet.fold
          (fun label edges ->
            let block =
              get_block_exn block_map label
            in
            List.fold_left
              (fun edges succ ->
                if LabelSet.mem succ blocks then
                  edges
                else
                  (label, succ) :: edges)
              edges block.succs)
          blocks []
        |> List.sort_uniq compare
      in
      let exit_targets =
        exit_edges
        |> List.map snd
        |> List.sort_uniq String.compare
      in
      let parent =
        match Hashtbl.find_opt parent_of header with
        | Some parent -> parent
        | None -> None
      in
      let info =
        {
          loop_info_header = header;
          loop_info_blocks = blocks;
          loop_info_parent = parent;
          loop_info_children = children;
          loop_info_depth =
            depth_of LabelSet.empty header;
          loop_info_exclusive_blocks =
            exclusive_blocks;
          loop_info_preheader = preheader;
          loop_info_latches = latches;
          loop_info_exit_edges = exit_edges;
          loop_info_exit_targets = exit_targets;
        }
      in
      Hashtbl.replace infos header info)
    headers;
  let roots =
    headers
    |> List.filter
         (fun header ->
           match Hashtbl.find_opt parent_of header with
           | Some None
           | None ->
               true
           | Some (Some _) ->
               false)
    |> List.sort String.compare
  in
  {
    loop_forest_block_map = block_map;
    loop_forest_loops = loops;
    loop_forest_headers = headers;
    loop_forest_infos = infos;
    loop_forest_roots = roots;
  }

let build_loop_simplify_report_from_forest
    (forest : loop_forest) =
  let infos =
    Hashtbl.create
      (max 8 (List.length forest.loop_forest_headers))
  in
  let all_ready = ref true in
  List.iter
    (fun header ->
      match
        Hashtbl.find_opt forest.loop_forest_infos header
      with
      | None ->
          all_ready := false
      | Some loop_info ->
          let blocks = loop_info.loop_info_blocks in
          let block_map = forest.loop_forest_block_map in
          let dedicated_exits =
            List.for_all
              (fun exit_target ->
                let exit_block =
                  get_block_exn block_map exit_target
                in
                exit_block.preds <> []
                && List.for_all
                     (fun pred ->
                       LabelSet.mem pred blocks)
                     exit_block.preds)
              loop_info.loop_info_exit_targets
          in
          let exit_control_blocks =
            loop_info.loop_info_exit_edges
            |> List.map fst
            |> List.sort_uniq String.compare
          in
          let control_block =
            match exit_control_blocks with
            | [ label ] -> Some label
            | []
            | _ :: _ :: _ ->
                None
          in
          let unique_preheader =
            Option.is_some loop_info.loop_info_preheader
          in
          let has_latch =
            loop_info.loop_info_latches <> []
          in
          let single_latch =
            match loop_info.loop_info_latches with
            | [ _ ] -> true
            | []
            | _ :: _ :: _ ->
                false
          in
          let single_exit_control =
            Option.is_some control_block
          in
          (* "ready" is deliberately the safe common denominator needed by
             recurrence/summary clients:
               - a unique dedicated preheader,
               - at least one backedge/latch,
               - dedicated exits.

             A single latch and a single exiting control block are exposed as
             stronger optional invariants, not required globally. *)
          let ready =
            unique_preheader
            && has_latch
            && dedicated_exits
          in
          if not ready then all_ready := false;
          Hashtbl.replace infos header
            {
              loop_simplify_header = header;
              loop_simplify_preheader =
                loop_info.loop_info_preheader;
              loop_simplify_latches =
                loop_info.loop_info_latches;
              loop_simplify_exit_edges =
                loop_info.loop_info_exit_edges;
              loop_simplify_exit_targets =
                loop_info.loop_info_exit_targets;
              loop_simplify_exit_control_blocks =
                exit_control_blocks;
              loop_simplify_unique_preheader =
                unique_preheader;
              loop_simplify_has_latch = has_latch;
              loop_simplify_single_latch = single_latch;
              loop_simplify_dedicated_exits =
                dedicated_exits;
              loop_simplify_single_exit_control =
                single_exit_control;
              loop_simplify_control_block = control_block;
              loop_simplify_ready = ready;
            })
    forest.loop_forest_headers;
  {
    loop_simplify_forest = forest;
    loop_simplify_infos = infos;
    loop_simplify_all_ready = !all_ready;
  }

let build_loop_simplify_report (f : Cfg.func) =
  build_loop_simplify_report_from_forest
    (build_loop_forest f)

let string_of_optional_label = function
  | Some label -> label
  | None -> "<none>"

let debug_loop_simplify_report
    (f : Cfg.func)
    (report : loop_simplify_report) =
  if
    Sys.getenv_opt "TOYC_DEBUG_LOOP_SIMPLIFY"
    <> None
  then begin
    List.iter
      (fun header ->
        match
          Hashtbl.find_opt
            report.loop_simplify_infos header
        with
        | None ->
            Printf.eprintf
              "loop-simplify func=%s header=%s status=missing-info\n%!"
              f.name header
        | Some info ->
            Printf.eprintf
              "loop-simplify func=%s header=%s ready=%b preheader=%s latches={%s} single-latch=%b dedicated-exits=%b exit-controls={%s} single-exit-control=%b control=%s exits={%s}\n%!"
              f.name
              header
              info.loop_simplify_ready
              (string_of_optional_label
                 info.loop_simplify_preheader)
              (String.concat ","
                 info.loop_simplify_latches)
              info.loop_simplify_single_latch
              info.loop_simplify_dedicated_exits
              (String.concat ","
                 info.loop_simplify_exit_control_blocks)
              info.loop_simplify_single_exit_control
              (string_of_optional_label
                 info.loop_simplify_control_block)
              (info.loop_simplify_exit_edges
               |> List.map
                    (fun (src, dst) ->
                      src ^ "->" ^ dst)
               |> String.concat ","))
      report.loop_simplify_forest.loop_forest_headers;
    Printf.eprintf
      "loop-simplify-summary func=%s loops=%d all-ready=%b\n%!"
      f.name
      (List.length
         report.loop_simplify_forest.loop_forest_headers)
      report.loop_simplify_all_ready
  end

let loop_simplify_info_opt
    (report : loop_simplify_report)
    header =
  Hashtbl.find_opt report.loop_simplify_infos header

let loop_simplify_ready
    (report : loop_simplify_report)
    header =
  match loop_simplify_info_opt report header with
  | Some info -> info.loop_simplify_ready
  | None -> false

let debug_loop_forest (f : Cfg.func) =
  if Sys.getenv_opt "TOYC_DEBUG_LOOP_FOREST" <> None then begin
    let forest = build_loop_forest f in
    List.iter
      (fun header ->
        match
          Hashtbl.find_opt
            forest.loop_forest_infos header
        with
        | None ->
            ()
        | Some info ->
            Printf.eprintf
              "loop-forest func=%s header=%s depth=%d parent=%s children={%s} blocks=%d exclusive=%d preheader=%s latches={%s} exits={%s}\n%!"
              f.name
              header
              info.loop_info_depth
              (match info.loop_info_parent with
               | Some parent -> parent
               | None -> "<root>")
              (String.concat ","
                 info.loop_info_children)
              (LabelSet.cardinal
                 info.loop_info_blocks)
              (LabelSet.cardinal
                 info.loop_info_exclusive_blocks)
              (match info.loop_info_preheader with
               | Some preheader -> preheader
               | None -> "<none>")
              (String.concat ","
                 info.loop_info_latches)
              (info.loop_info_exit_edges
               |> List.map
                    (fun (src, dst) ->
                      src ^ "->" ^ dst)
               |> String.concat ","))
      forest.loop_forest_headers
  end


let tailrec_elim_func (f : Cfg.func) =
  let tail_loop_label = f.entry in
  let next_temp = ref f.temp_count in
  let fresh_temp () =
    let temp = !next_temp in
    incr next_temp;
    temp
  in
  let tail_call_args_of_block (block : Cfg.block) =
    match block.term with
    | Cfg.Return (Some ret_operand) ->
        let rec peel current = function
          | [] -> None
          | instr :: rest -> (
              match (instr, current) with
              | Tcg.Move (dst, src), Tcg.Temp temp when dst = temp -> peel src rest
              | Tcg.Call (Some dst, callee, args), Tcg.Temp temp
                when dst = temp && callee = f.label ->
                  Some (List.rev rest, args)
              | _ -> None)
        in
        peel ret_operand (List.rev block.body)
    | Cfg.Return None | Cfg.Jump _ | Cfg.BranchZero _ | Cfg.BranchNonZero _ | Cfg.BranchCompare _ ->
        None
  in
  let build_parallel_param_stores args =
    if List.length args <> List.length f.params then None
    else
      let snapshots_rev = ref [] in
      let stores_rev = ref [] in
      List.iter2
        (fun (param : Tcg.var) arg ->
          let arg =
            match arg with
            | Tcg.Imm _ -> arg
            | Tcg.Temp temp ->
                let snap = fresh_temp () in
                snapshots_rev :=
                  simplify_simple_instr (Tcg.Move (snap, Tcg.Temp temp)) :: !snapshots_rev;
                Tcg.Temp snap
          in
          stores_rev := Tcg.Store (Tcg.Local param.id, arg) :: !stores_rev)
        f.params args;
      Some (List.rev !snapshots_rev @ List.rev !stores_rev)
  in
  let changed = ref false in
  let blocks =
    List.map
      (fun (block : Cfg.block) ->
        match tail_call_args_of_block block with
        | None -> block
        | Some (prefix, args) -> (
            match build_parallel_param_stores args with
            | None -> block
            | Some stores ->
                changed := true;
                let term = Cfg.Jump tail_loop_label in
                { block with body = prefix @ stores; term; succs = Cfg.successors term }))
      f.blocks
  in
  if !changed then
    let existing_labels =
      List.fold_left
        (fun seen (block : Cfg.block) -> LabelSet.add block.label seen)
        LabelSet.empty blocks
    in
    let rec fresh_entry index =
      let label = Printf.sprintf ".L%s_tail_entry_%d" f.label index in
      if LabelSet.mem label existing_labels then fresh_entry (index + 1) else label
    in
    let new_entry = fresh_entry 0 in
    let entry_block =
      {
        Cfg.label = new_entry;
        body = [];
        term = Cfg.Jump tail_loop_label;
        preds = [];
        succs = [ tail_loop_label ];
      }
    in
    let blocks =
      List.fold_right
        (fun (block : Cfg.block) acc ->
          if block.label = tail_loop_label then entry_block :: block :: acc
          else block :: acc)
        blocks []
    in
    Cfg.rebuild_edges { f with entry = new_entry; temp_count = !next_temp; blocks }
  else f

let loop_canonicalize_func summaries globals (f : Cfg.func) =
  let next_preheader_id = ref 0 in
  let fresh_preheader_label () =
    let id = !next_preheader_id in
    incr next_preheader_id;
    Printf.sprintf ".L%s_canon_pre_%d" f.label id
  in
  let next_exit_id = ref 0 in
  let fresh_exit_label () =
    let id = !next_exit_id in
    incr next_exit_id;
    Printf.sprintf ".L%s_canon_exit_%d" f.label id
  in
  let next_prep_id = ref 0 in
  let fresh_prep_label () =
    let id = !next_prep_id in
    incr next_prep_id;
    Printf.sprintf ".L%s_canon_cmp_%d" f.label id
  in
  let rec apply (current : Cfg.func) =
    let live_in_t, live_in_p = compute_liveness summaries globals current in
    let _, loops, headers = discover_natural_loops current in
    if headers = [] then current
    else
      let current_blocks = Hashtbl.create (List.length current.blocks + (3 * List.length headers)) in
      List.iter
        (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block)
        current.blocks;
      let block_order = ref (List.map (fun (block : Cfg.block) -> block.label) current.blocks) in
      let current_entry = ref current.entry in
      let get_block = get_block_exn current_blocks in
      let update_block (block : Cfg.block) =
        Hashtbl.replace current_blocks block.label block
      in
      let insert_before label new_labels =
        block_order :=
          List.concat_map
            (fun current_label ->
              if current_label = label then List.rev_append new_labels [ current_label ]
              else [ current_label ])
            !block_order
      in
      let pure_prep_instr = function
        | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ -> true
        | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> false
      in
      let branch_targets = function
        | Cfg.BranchZero (_, if_zero, if_nonzero) -> Some (if_zero, if_nonzero)
        | Cfg.BranchNonZero (_, if_nonzero, if_zero) -> Some (if_nonzero, if_zero)
        | Cfg.BranchCompare (_, _, _, if_true, if_false) -> Some (if_true, if_false)
        | Cfg.Jump _ | Cfg.Return _ -> None
      in
      let branch_with_targets term if_true if_false =
        match term with
        | Cfg.BranchZero (cond, _, _) -> Cfg.BranchZero (cond, if_true, if_false)
        | Cfg.BranchNonZero (cond, _, _) -> Cfg.BranchNonZero (cond, if_true, if_false)
        | Cfg.BranchCompare (op, lhs, rhs, _, _) ->
            Cfg.BranchCompare (op, lhs, rhs, if_true, if_false)
        | Cfg.Jump _ | Cfg.Return _ -> term
      in
      let prune_jump_body (block : Cfg.block) next_label =
        let live_t =
          match Hashtbl.find_opt live_in_t next_label with
          | Some live -> live
          | None -> IntSet.empty
        in
        let live_p =
          match Hashtbl.find_opt live_in_p next_label with
          | Some live -> live
          | None -> PlaceSet.empty
        in
        let kept_rev, _, _ =
          List.fold_left
            (fun (acc, live_t, live_p) instr ->
              let kept, live_t, live_p = scan_simple_instr summaries globals instr live_t live_p in
              let acc =
                match kept with
                | Some instr -> instr :: acc
                | None -> acc
              in
              (acc, live_t, live_p))
            ([], live_t, live_p) (List.rev block.body)
        in
        List.rev kept_rev
      in
      let rec equivalent_linear_jump_chains seen_pairs a b =
        if a = b then Some a
        else if List.mem (a, b) seen_pairs || List.mem (b, a) seen_pairs then None
        else
          let a_block : Cfg.block = get_block a in
          let b_block : Cfg.block = get_block b in
          match (a_block.term, b_block.term) with
          | Cfg.Jump next_a, Cfg.Jump next_b ->
              let a_body = prune_jump_body a_block next_a in
              let b_body = prune_jump_body b_block next_b in
              if a_body <> b_body then None
              else if next_a = next_b then Some a
              else equivalent_linear_jump_chains ((a, b) :: seen_pairs) next_a next_b
          | _ -> None
      in
      let is_small_pure_control_body body =
        List.length body <= 4 && List.for_all pure_prep_instr body
      in
      let changed = ref false in
      List.iter
        (fun header ->
          let loop = table_find_or_empty loops header LabelSet.empty in
          let header_block : Cfg.block = get_block header in
          let outside_preds = List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds in
          let need_preheader =
            outside_preds <> []
            &&
            (List.length outside_preds > 1
            || List.exists
                 (fun pred ->
                   let pred_block : Cfg.block = get_block pred in
                   pred_block.succs <> [ header ])
                 outside_preds)
          in
          if need_preheader then begin
            changed := true;
            let preheader_label = fresh_preheader_label () in
            let redirects = Hashtbl.create (List.length outside_preds) in
            List.iter
              (fun pred -> Hashtbl.add redirects (pred, header) preheader_label)
              outside_preds;
            List.iter
              (fun pred ->
                let pred_block : Cfg.block = get_block pred in
                let term = redirect_successors pred redirects pred_block.term in
                update_block { pred_block with term; succs = Cfg.successors term })
              outside_preds;
            Hashtbl.add current_blocks preheader_label
              {
                Cfg.label = preheader_label;
                body = [];
                term = Cfg.Jump header;
                preds = [];
                succs = [ header ];
              };
            insert_before header [ preheader_label ];
            if header = !current_entry then current_entry := preheader_label
          end;
          let exit_labels =
            LabelSet.fold
              (fun label exits ->
                let block : Cfg.block = get_block label in
                List.fold_left
                  (fun exits succ -> if LabelSet.mem succ loop then exits else LabelSet.add succ exits)
                  exits block.succs)
              loop LabelSet.empty
          in
          LabelSet.iter
            (fun exit_label ->
              let exit_block : Cfg.block = get_block exit_label in
              let loop_preds = List.filter (fun pred -> LabelSet.mem pred loop) exit_block.preds in
              let outside_exit_preds =
                List.filter (fun pred -> not (LabelSet.mem pred loop)) exit_block.preds
              in
              if loop_preds <> [] && outside_exit_preds <> [] then begin
                changed := true;
                let dedicated_label = fresh_exit_label () in
                let redirects = Hashtbl.create (List.length loop_preds) in
                List.iter
                  (fun pred -> Hashtbl.add redirects (pred, exit_label) dedicated_label)
                  loop_preds;
                List.iter
                  (fun pred ->
                    let pred_block : Cfg.block = get_block pred in
                    let term = redirect_successors pred redirects pred_block.term in
                    update_block { pred_block with term; succs = Cfg.successors term })
                  loop_preds;
                Hashtbl.add current_blocks dedicated_label
                  {
                    Cfg.label = dedicated_label;
                    body = [];
                    term = Cfg.Jump exit_label;
                    preds = [];
                    succs = [ exit_label ];
                  };
                insert_before exit_label [ dedicated_label ]
              end)
            exit_labels;
          LabelSet.iter
            (fun label ->
              let block : Cfg.block = get_block label in
              let exits_loop =
                match branch_targets block.term with
                | Some (a, b) -> LabelSet.mem a loop <> LabelSet.mem b loop
                | None -> false
              in
              if
                label <> header
                && exits_loop
                && block.preds <> []
                && block.body <> []
                && is_small_pure_control_body block.body
              then begin
                changed := true;
                let prep_label = fresh_prep_label () in
                let redirects = Hashtbl.create (List.length block.preds) in
                List.iter
                  (fun pred -> Hashtbl.add redirects (pred, label) prep_label)
                  block.preds;
                List.iter
                  (fun pred ->
                    let pred_block : Cfg.block = get_block pred in
                    let term = redirect_successors pred redirects pred_block.term in
                    update_block { pred_block with term; succs = Cfg.successors term })
                  block.preds;
                Hashtbl.add current_blocks prep_label
                  {
                    Cfg.label = prep_label;
                    body = block.body;
                    term = Cfg.Jump label;
                    preds = [];
                    succs = [ label ];
                  };
               insert_before label [ prep_label ];
                update_block { block with body = [] };
                if label = !current_entry then current_entry := prep_label
              end)
            loop;
          LabelSet.iter
            (fun label ->
              let block : Cfg.block = get_block label in
              match branch_targets block.term with
              | Some (a, b)
                when LabelSet.mem a loop
                     && LabelSet.mem b loop
                     && a <> b -> (
                  match equivalent_linear_jump_chains [] a b with
                  | Some representative ->
                      changed := true;
                      let term = branch_with_targets block.term representative representative in
                      update_block { block with term; succs = Cfg.successors term }
                  | None -> ())
              | Some _ | None -> ())
            loop)
        headers;
      if !changed then
        let blocks = List.map get_block !block_order in
        let rebuilt = Cfg.rebuild_edges { current with entry = !current_entry; blocks } in
        let cleaned = thread_and_prune_func rebuilt in
        if cleaned = current then current else apply cleaned
      else current
  in
  apply f

let eliminate_dead_loops_func summaries globals (f : Cfg.func) =
  let debug_dead_loops = Sys.getenv_opt "TOYC_DEBUG_DEAD_LOOPS" <> None in
  let debugf fmt = Printf.ksprintf (fun s -> if debug_dead_loops then prerr_endline s) fmt in
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let live_in_t, live_in_p = compute_liveness summaries globals f in
    let current_blocks = Hashtbl.create (List.length f.blocks) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let current_entry = ref f.entry in
    let removed = ref LabelSet.empty in
    let changed = ref false in
    let original_block_labels =
      List.map (fun (block : Cfg.block) -> block.label) f.blocks
    in
    let original_block_set =
      List.fold_left
        (fun acc label -> LabelSet.add label acc)
        LabelSet.empty
        original_block_labels
    in
    let current_block_list () =
      let original_blocks =
        List.filter_map
          (fun label -> Hashtbl.find_opt current_blocks label)
          original_block_labels
      in
      let extra_blocks =
        Hashtbl.fold
          (fun label block acc ->
            if LabelSet.mem label original_block_set then acc
            else block :: acc)
          current_blocks
          []
        |> List.sort
             (fun (a : Cfg.block) (b : Cfg.block) ->
               String.compare a.label b.label)
      in
      original_blocks @ extra_blocks
    in
    let get_block = get_block_exn current_blocks in
    let block_exists label = Hashtbl.mem current_blocks label && not (LabelSet.mem label !removed) in
    List.iter
      (fun header ->
        if block_exists header then
          let loop = table_find_or_empty loops header LabelSet.empty in
          if not (LabelSet.exists (fun label -> LabelSet.mem label !removed) loop) then
            let header_block : Cfg.block = Hashtbl.find current_blocks header in
            let outside_preds =
              List.filter (fun pred -> not (LabelSet.mem pred loop) && block_exists pred) header_block.preds
            in
            let exit_labels =
              LabelSet.fold
                (fun label exits ->
                  match Hashtbl.find_opt current_blocks label with
                  | None -> exits
                  | Some (block : Cfg.block) ->
                      List.fold_left
                        (fun exits succ ->
                          if LabelSet.mem succ loop then exits else LabelSet.add succ exits)
                        exits block.succs)
                loop LabelSet.empty
            in
            match LabelSet.elements exit_labels with
            | [ exit_label ] when outside_preds <> [] || header = !current_entry ->
                let blocks_snapshot = current_block_list () in
                let effects = collect_loop_effects summaries globals loop blocks_snapshot in
                let modified_locals =
                  PlaceSet.filter (fun place -> not (place_is_global place)) effects.modified_places
                in
                let live_t_exit = table_find_or_empty live_in_t exit_label IntSet.empty in
                let live_p_exit = table_find_or_empty live_in_p exit_label PlaceSet.empty in
                let defined_temps = loop_defined_temps loop get_block in
                let has_global_store = PlaceSet.exists place_is_global effects.modified_places in
                if
                  not effects.has_call
                  && not has_global_store
                  && IntSet.is_empty (IntSet.inter defined_temps live_t_exit)
                  && PlaceSet.is_empty (PlaceSet.inter modified_locals live_p_exit)
                then begin
                  debugf "dead-loop-remove func=%s header=%s exit=%s entry=%s preds=%d loop_size=%d"
                    f.name header exit_label !current_entry (List.length outside_preds)
                    (LabelSet.cardinal loop);
                  changed := true;
                  List.iter
                    (fun pred ->
                      match Hashtbl.find_opt current_blocks pred with
                      | None -> ()
                      | Some (block : Cfg.block) ->
                          let term =
                            rewrite_term_successor block.term ~from_label:header ~to_label:exit_label
                          in
                          Hashtbl.replace current_blocks pred
                            { block with term; succs = Cfg.successors term })
                    outside_preds;
                  if header = !current_entry then current_entry := exit_label;
                  removed := LabelSet.union !removed loop
                end
            | _ -> ())
      headers;
    if !changed then
      let blocks =
        f.blocks
        |> List.filter (fun (block : Cfg.block) -> not (LabelSet.mem block.label !removed))
        |> List.map (fun (block : Cfg.block) ->
               match Hashtbl.find_opt current_blocks block.label with
               | Some block -> block
               | None -> block)
      in
      let threaded = Cfg.rebuild_edges { f with entry = !current_entry; blocks } in
      let reachable = reachable_labels threaded.entry threaded.blocks in
      let blocks =
        List.filter (fun (block : Cfg.block) -> LabelSet.mem block.label reachable) threaded.blocks
      in
      Cfg.rebuild_edges { threaded with blocks }
    else f

let load_place_invariant effects place =
  not (PlaceSet.mem place effects.modified_places)

type basic_induction_var = {
  phi_temp : Tcg.temp;
  outside_inputs : (Tcg.label * Tcg.operand) list;
  backedge_preds : Tcg.label list;
  step : int64;
  origin : [ `Syntactic | `Semantic ];
}

let string_of_basic_iv_origin = function
  | `Syntactic -> "syntactic"
  | `Semantic -> "semantic"

(* step112: a deliberately small symbolic loop-value language.

   Keep this separate from [basic_induction_var]: counted-loop reasoning still
   wants a statically known signed step, while strength reduction only needs
   the recurrence identity to hold.  In particular, [i += step_parameter]
   is useful even when the sign/value of [step_parameter] is unknown. *)
type loop_inv_expr =
  | LveConst of int64
  | LveOperand of Tcg.operand
  | LveNeg of loop_inv_expr
  | LveAdd of loop_inv_expr * loop_inv_expr
  | LveMul of loop_inv_expr * loop_inv_expr

type logical_phi_backedge_case = {
  logical_header_pred : Tcg.label;
  logical_def_label : Tcg.label;
  logical_source : Tcg.operand;
  logical_chain : Cfg.block list;
}

type logical_loop_phi = {
  logical_phi_temp : Tcg.temp;
  logical_outside_inputs : (Tcg.label * Tcg.operand) list;
  logical_backedge_preds : Tcg.label list;
  logical_backedge_cases : logical_phi_backedge_case list;
}

type loop_addrec = {
  addrec_phi_temp : Tcg.temp;
  addrec_outside_inputs : (Tcg.label * Tcg.operand) list;
  addrec_backedge_preds : Tcg.label list;
  addrec_step : loop_inv_expr;
}

type derived_expr_key =
  | DerivedScaled of int64
  | DerivedAdd of Tcg.operand * int64
  | DerivedSubBase of int64 * Tcg.operand
  | DerivedBaseMinus of Tcg.operand * int64

let temp_def_instrs_of_blocks temp_count blocks =
  let defs = Hashtbl.create (max 8 temp_count) in
  List.iter
    (fun (block : Cfg.block) ->
      List.iter
        (fun instr ->
          match defs_temp instr with
          | Some temp when not (Hashtbl.mem defs temp) -> Hashtbl.add defs temp instr
          | Some _ | None -> ())
        block.body)
    blocks;
  defs

let temp_def_instrs_map (f : Cfg.func) = temp_def_instrs_of_blocks f.temp_count f.blocks

let multi_def_temps_of_blocks temp_count blocks =
  let seen = Hashtbl.create (max 8 temp_count) in
  let multi_defs = ref IntSet.empty in
  List.iter
    (fun (block : Cfg.block) ->
      List.iter
        (fun instr ->
          match defs_temp instr with
          | Some temp ->
              if Hashtbl.mem seen temp then multi_defs := IntSet.add temp !multi_defs
              else Hashtbl.add seen temp ()
          | None -> ())
        block.body)
    blocks;
  !multi_defs

let analyze_temp_defs_of_blocks ?loop temp_count blocks =
  let loop_defs = ref IntSet.empty in
  let def_blocks = Hashtbl.create (max 8 temp_count) in
  let def_instrs = Hashtbl.create (max 8 temp_count) in
  let multi_defs = ref IntSet.empty in
  List.iter
    (fun (block : Cfg.block) ->
      let in_loop =
        match loop with
        | Some loop -> LabelSet.mem block.label loop
        | None -> false
      in
      List.iter
        (fun instr ->
          match defs_temp instr with
          | Some temp ->
              if in_loop then loop_defs := IntSet.add temp !loop_defs;
              Hashtbl.replace def_blocks temp block.label;
              if Hashtbl.mem def_instrs temp then
                multi_defs := IntSet.add temp !multi_defs
              else Hashtbl.add def_instrs temp instr
          | None -> ())
        block.body)
    blocks;
  (!loop_defs, def_blocks, def_instrs, !multi_defs)

let last_def_of_temp (block : Cfg.block) temp =
  let rec loop = function
    | [] -> None
    | instr :: rest -> (
        match defs_temp instr with
        | Some dst when dst = temp -> Some instr
        | Some _ | None -> loop rest)
  in
  loop (List.rev block.body)

let resolve_block_operand (block : Cfg.block) operand =
  let move_defs = Hashtbl.create (List.length block.body) in
  List.iter
    (function
      | Tcg.Move (dst, src) -> Hashtbl.replace move_defs dst src
      | _ -> ())
    block.body;
  let rec resolve seen = function
    | Tcg.Imm _ as operand -> operand
    | Tcg.Temp temp as operand ->
        if IntSet.mem temp seen then operand
        else
          match Hashtbl.find_opt move_defs temp with
          | Some src -> resolve (IntSet.add temp seen) src
          | None -> operand
  in
  resolve IntSet.empty operand

let trivial_phi_bridge_to succ_label (block : Cfg.block) =
  List.length block.preds = 1
  && block.succs = [ succ_label ]
  &&
  match block.term with
  | Cfg.Jump target when target = succ_label ->
      List.for_all
        (function
          | Tcg.Move _ -> true
          | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> false)
        block.body
  | Cfg.Jump _ | Cfg.BranchZero _ | Cfg.BranchNonZero _ | Cfg.BranchCompare _ | Cfg.Return _ ->
      false

let incoming_phi_chain get_block succ_label pred_label =
  let _ = succ_label in
  let rec walk seen label acc =
    if LabelSet.mem label seen then List.rev acc
    else
      let block : Cfg.block = get_block label in
      let acc = block :: acc in
      match block.preds with
      | [ prev ] ->
          let prev_block : Cfg.block = get_block prev in
          if trivial_phi_bridge_to label prev_block then
            walk (LabelSet.add label seen) prev acc
          else List.rev acc
      | _ -> List.rev acc
  in
  walk LabelSet.empty pred_label []

(* Counted-loop seed recovery.
   After mem2reg/guard canonicalization a loop often looks like

       entry:  i = 0; acc = 0; if (...) goto edge_in else exit
       edge_in: goto body
       body:   ...

   The natural-loop header sees [edge_in] as its outside predecessor, while
   [incoming_phi_chain] intentionally stops before [entry] because [entry]
   branches.  For counted-loop induction/reduction analysis that loses the
   unconditionally executed seed definitions.

   Starting from an already selected outside edge, it is safe to walk
   backwards through UNIQUE predecessor links outside the loop: every block
   reached this way necessarily executed before control arrived at that edge.
   We keep the chain in the same newest-to-oldest order used by
   [last_def_of_temp_on_chain]. *)
let extend_counted_outside_seed_chain get_block loop chain =
  let debug = Sys.getenv_opt "TOYC_DEBUG_COUNTED_SEEDS" <> None in
  let rec last_block = function
    | [] -> None
    | [ block ] -> Some block
    | _ :: rest -> last_block rest
  in
  let rec grow seen acc =
    match last_block acc with
    | None -> acc
    | Some (oldest : Cfg.block) -> (
        match oldest.preds with
        | [ prev ]
          when not (LabelSet.mem prev loop)
               && not (LabelSet.mem prev seen) ->
            let prev_block : Cfg.block = get_block prev in
            if debug then
              Printf.eprintf
                "counted-seed-extend from=%s prev=%s\n%!"
                oldest.label prev;
            grow
              (LabelSet.add prev seen)
              (acc @ [ prev_block ])
        | _ -> acc)
  in
  let seen =
    List.fold_left
      (fun acc (block : Cfg.block) -> LabelSet.add block.label acc)
      LabelSet.empty chain
  in
  grow seen chain

let incoming_update_chain get_block succ_label pred_label =
  let rec walk seen label acc =
    if LabelSet.mem label seen || label = succ_label then List.rev acc
    else
      let block : Cfg.block = get_block label in
      let acc = block :: acc in
      match block.preds with
      | [ prev ] -> walk (LabelSet.add label seen) prev acc
      | _ -> List.rev acc
  in
  walk LabelSet.empty pred_label []

let resolve_chain_operand chain operand =
  (* [chain] is ordered newest block -> older block.  Inside each block scan
     newest instruction -> older instruction.

     The previous implementation remembered only Move definitions.  That is
     unsound when a temp is redefined later by a non-Move:

         t22 = move t39;
         ...
         t22 = add t22, t37;
         t41 = move t22;

     Looking up t22 must stop at the later Add.  Ignoring that Add allowed the
     resolver to "see through" it and incorrectly use the stale
     [t22 = move t39], collapsing the real recurrence into t39 -> t39.

     Record the first (therefore newest) definition of every temp.  Only when
     that newest definition itself is a Move may it participate in alias
     resolution. *)
  let move_defs = Hashtbl.create 8 in
  let seen_defs = Hashtbl.create 8 in
  let record_def dst move_src =
    if not (Hashtbl.mem seen_defs dst) then begin
      Hashtbl.add seen_defs dst ();
      match move_src with
      | Some src -> Hashtbl.add move_defs dst src
      | None -> ()
    end
  in
  List.iter
    (fun (block : Cfg.block) ->
      List.iter
        (function
          | Tcg.Move (dst, src) ->
              record_def dst (Some src)
          | Tcg.Un (dst, _, _)
          | Tcg.Bin (dst, _, _, _)
          | Tcg.Load (dst, _) ->
              record_def dst None
          | Tcg.Store _
          | Tcg.Call (None, _, _) ->
              ()
          | Tcg.Call (Some dst, _, _) ->
              record_def dst None)
        (List.rev block.body))
    chain;
  let rec resolve seen = function
    | Tcg.Imm _ as operand -> operand
    | Tcg.Temp temp as operand ->
        if IntSet.mem temp seen then operand
        else
          match Hashtbl.find_opt move_defs temp with
          | Some src -> resolve (IntSet.add temp seen) src
          | None -> operand
  in
  resolve IntSet.empty operand

let flatten_chain_block chain =
  let body =
    chain
    |> List.rev
    |> List.concat_map (fun (block : Cfg.block) -> block.body)
  in
  { Cfg.label = "<chain>"; body; term = Cfg.Return None; preds = []; succs = [] }

let move_dests_in_chain chain =
  List.fold_left
    (fun seen (block : Cfg.block) ->
      List.fold_left
        (fun seen instr ->
          match instr with
          | Tcg.Move (dst, _) -> IntSet.add dst seen
          | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> seen)
        seen block.body)
    IntSet.empty chain

let last_move_of_temp_on_chain chain temp =
  let rec block_loop = function
    | [] -> None
    | (block : Cfg.block) :: rest -> (
        let rec instr_loop = function
          | [] -> block_loop rest
          | instr :: instrs -> (
              match instr with
              | Tcg.Move (dst, src) when dst = temp -> Some src
              | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ ->
                  instr_loop instrs)
        in
        instr_loop (List.rev block.body))
  in
  block_loop chain

let last_def_of_temp_on_chain chain temp =
  let rec block_loop = function
    | [] -> None
    | (block : Cfg.block) :: rest -> (
        match last_def_of_temp block temp with
        | Some _ as found -> found
        | None -> block_loop rest)
  in
  block_loop chain

let last_def_of_temp_on_chain_with_block chain temp =
  let rec block_loop = function
    | [] -> None
    | (block : Cfg.block) :: rest -> (
        match last_def_of_temp block temp with
        | Some instr -> Some (block, instr, rest)
        | None -> block_loop rest)
  in
  block_loop chain

let rec chain_rest_from_label chain label =
  match chain with
  | [] -> None
  | (block : Cfg.block) :: rest ->
      if block.label = label then Some (block, rest) else chain_rest_from_label rest label

let def_instr_on_chain_or_global chain multi_defs def_instrs temp =
  if IntSet.mem temp multi_defs then last_def_of_temp_on_chain chain temp
  else Hashtbl.find_opt def_instrs temp

let def_instr_in_block_or_global (block : Cfg.block) multi_defs def_instrs temp =
  if IntSet.mem temp multi_defs then last_def_of_temp block temp
  else Hashtbl.find_opt def_instrs temp

let resolves_to_induction_temp_on_chain chain multi_defs def_instrs phi_temp operand =
  let rec loop seen = function
    | Tcg.Imm _ -> false
    | Tcg.Temp temp ->
        if temp = phi_temp then true
        else if IntSet.mem temp seen then false
        else
          match def_instr_on_chain_or_global chain multi_defs def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) ->
              loop (IntSet.add temp seen) src
          | Some _ | None -> false
  in
  loop IntSet.empty operand

let resolves_to_induction_temp_in_block block multi_defs def_instrs phi_temp operand =
  let rec loop seen = function
    | Tcg.Imm _ -> false
    | Tcg.Temp temp ->
        if temp = phi_temp then true
        else if IntSet.mem temp seen then false
        else
          match def_instr_in_block_or_global block multi_defs def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) ->
              loop (IntSet.add temp seen) src
          | Some _ | None -> false
  in
  loop IntSet.empty operand

let operand_static_int64_on_chain chain loop_defs multi_defs def_instrs operand =
  let rec loop seen = function
    | Tcg.Imm value -> Some value
    | Tcg.Temp temp ->
        if IntSet.mem temp seen || IntSet.mem temp loop_defs then None
        else
          match def_instr_on_chain_or_global chain multi_defs def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) ->
              loop (IntSet.add temp seen) src
          | Some (Tcg.Un (_, op, src)) ->
              Option.bind (loop (IntSet.add temp seen) src) (fold_unop op)
          | Some (Tcg.Bin (_, op, lhs, rhs)) -> (
              match (loop (IntSet.add temp seen) lhs, loop (IntSet.add temp seen) rhs) with
              | Some lhs, Some rhs -> fold_binop op lhs rhs
              | _ -> None)
          | Some (Tcg.Load _ | Tcg.Store _ | Tcg.Call _) | None -> None
  in
  loop IntSet.empty operand

let induction_step_of_instr_on_chain chain loop_defs multi_defs def_instrs phi_temp = function
  | Tcg.Bin (_, Add, lhs, rhs)
    when resolves_to_induction_temp_on_chain chain multi_defs def_instrs phi_temp lhs ->
      operand_static_int64_on_chain chain loop_defs multi_defs def_instrs rhs
  | Tcg.Bin (_, Add, lhs, rhs)
    when resolves_to_induction_temp_on_chain chain multi_defs def_instrs phi_temp rhs ->
      operand_static_int64_on_chain chain loop_defs multi_defs def_instrs lhs
  | Tcg.Bin (_, Sub, lhs, rhs)
    when resolves_to_induction_temp_on_chain chain multi_defs def_instrs phi_temp lhs ->
      Option.map Int64.neg
        (operand_static_int64_on_chain chain loop_defs multi_defs def_instrs rhs)
  | _ -> None

let pure_cfg_prep_instr = function
  | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ -> true
  | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> false

let resolves_to_temp multi_defs def_instrs target operand =
  let rec loop seen = function
    | Tcg.Imm _ -> false
    | Tcg.Temp temp ->
        if temp = target then true
        else if IntSet.mem temp seen || IntSet.mem temp multi_defs then false
        else
          match Hashtbl.find_opt def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) ->
              loop (IntSet.add temp seen) src
          | Some _ | None -> false
  in
  loop IntSet.empty operand

let resolves_to_induction_temp multi_defs def_instrs phi_temp operand =
  let rec loop seen = function
    | Tcg.Imm _ -> false
    | Tcg.Temp temp ->
        if temp = phi_temp then true
        else if IntSet.mem temp seen || IntSet.mem temp multi_defs then false
        else
          match Hashtbl.find_opt def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) ->
              loop (IntSet.add temp seen) src
          | Some _ | None -> false
  in
  loop IntSet.empty operand

let operand_static_int64 loop_defs multi_defs def_instrs operand =
  let rec loop seen = function
    | Tcg.Imm value -> Some value
    | Tcg.Temp temp ->
        if IntSet.mem temp seen || IntSet.mem temp multi_defs || IntSet.mem temp loop_defs then None
        else
          match Hashtbl.find_opt def_instrs temp with
          | Some (Tcg.Move (_, src)) -> loop (IntSet.add temp seen) src
          | Some (Tcg.Un (_, op, src)) -> Option.bind (loop (IntSet.add temp seen) src) (fold_unop op)
          | Some (Tcg.Bin (_, op, lhs, rhs)) -> (
              match (loop (IntSet.add temp seen) lhs, loop (IntSet.add temp seen) rhs) with
              | Some lhs, Some rhs -> fold_binop op lhs rhs
              | _ -> None)
          | Some (Tcg.Load _ | Tcg.Store _ | Tcg.Call _) | None -> None
  in
  loop IntSet.empty operand

let induction_step_of_instr loop_defs multi_defs def_instrs phi_temp = function
  | Tcg.Bin (_, Add, lhs, rhs) when resolves_to_induction_temp multi_defs def_instrs phi_temp lhs ->
      operand_static_int64 loop_defs multi_defs def_instrs rhs
  | Tcg.Bin (_, Add, lhs, rhs) when resolves_to_induction_temp multi_defs def_instrs phi_temp rhs ->
      operand_static_int64 loop_defs multi_defs def_instrs lhs
  | Tcg.Bin (_, Sub, lhs, rhs) when resolves_to_induction_temp multi_defs def_instrs phi_temp lhs ->
      Option.map Int64.neg (operand_static_int64 loop_defs multi_defs def_instrs rhs)
  | _ -> None

let mul_factor_of_instr multi_defs def_instrs phi_temp = function
  | Tcg.Bin (dst, Mul, lhs, Tcg.Imm factor)
    when resolves_to_induction_temp multi_defs def_instrs phi_temp lhs ->
      Some (dst, factor)
  | Tcg.Bin (dst, Mul, Tcg.Imm factor, rhs)
    when resolves_to_induction_temp multi_defs def_instrs phi_temp rhs ->
      Some (dst, factor)
  | _ -> None

let delta_instr dst base delta =
  if delta >= 0L then simplify_simple_instr (Tcg.Bin (dst, Add, Tcg.Temp base, Tcg.Imm delta))
  else simplify_simple_instr (Tcg.Bin (dst, Sub, Tcg.Temp base, Tcg.Imm Int64.(neg delta)))

let build_derived_backedge_update derived_phi delta =
  if delta = 0L then [] else [ delta_instr derived_phi derived_phi delta ]

let build_scaled_value dst source factor =
  match factor with
  | 0L -> [ Tcg.Move (dst, Tcg.Imm 0L) ]
  | 1L -> [ Tcg.Move (dst, source) ]
  | -1L -> [ simplify_simple_instr (Tcg.Bin (dst, Sub, Tcg.Imm 0L, source)) ]
  | _ -> [ simplify_simple_instr (Tcg.Bin (dst, Mul, source, Tcg.Imm factor)) ]

let build_derived_init key dst source =
  match key with
  | DerivedScaled factor -> build_scaled_value dst source factor
  | DerivedAdd (base, factor) ->
      build_scaled_value dst source factor
      @ [ simplify_simple_instr (Tcg.Bin (dst, Add, Tcg.Temp dst, base)) ]
  | DerivedSubBase (factor, base) ->
      build_scaled_value dst source factor
      @ [ simplify_simple_instr (Tcg.Bin (dst, Sub, Tcg.Temp dst, base)) ]
  | DerivedBaseMinus (base, factor) ->
      build_scaled_value dst source factor
      @ [ simplify_simple_instr (Tcg.Bin (dst, Sub, base, Tcg.Temp dst)) ]

let derived_key_temp_base = function
  | DerivedAdd (Tcg.Temp _, _)
  | DerivedSubBase (_, Tcg.Temp _)
  | DerivedBaseMinus (Tcg.Temp _, _) ->
      true
  | DerivedScaled _ | DerivedAdd _ | DerivedSubBase _ | DerivedBaseMinus _ -> false

let rec scaled_factor_of_operand multi_defs def_instrs phi_temp operand =
  match operand with
  | Tcg.Imm _ -> None
  | Tcg.Temp temp ->
      if temp = phi_temp then Some 1L
      else if IntSet.mem temp multi_defs then None
      else
        match Hashtbl.find_opt def_instrs temp with
        | Some (Tcg.Move (_, src))
        | Some (Tcg.Un (_, UPlus, src)) ->
            scaled_factor_of_operand multi_defs def_instrs phi_temp src
        | Some (Tcg.Un (_, UMinus, src))
          when resolves_to_induction_temp multi_defs def_instrs phi_temp src ->
            Some (-1L)
        | Some (Tcg.Bin (_, Sub, Tcg.Imm 0L, src))
          when resolves_to_induction_temp multi_defs def_instrs phi_temp src ->
            Some (-1L)
        | Some instr -> (
            match mul_factor_of_instr multi_defs def_instrs phi_temp instr with
            | Some (_, factor) -> Some factor
            | None -> None)
        | None -> None

let useful_derived_key = function
  | DerivedScaled factor -> factor <> 0L && factor <> 1L && factor <> -1L
  | DerivedAdd (_, factor)
  | DerivedSubBase (factor, _)
  | DerivedBaseMinus (_, factor) ->
      factor <> 0L

let worthwhile_derived_key key uses =
  if not (useful_derived_key key) then false
  else
    match key with
    | DerivedScaled factor -> factor <> 1L && factor <> -1L
    | DerivedAdd (_, factor)
    | DerivedSubBase (factor, _)
    | DerivedBaseMinus (_, factor) ->
        if factor <> 1L && factor <> -1L then true
        else List.length uses >= 2 || derived_key_temp_base key

let delta_of_derived_key step = function
  | DerivedScaled factor
  | DerivedAdd (_, factor)
  | DerivedSubBase (factor, _) ->
      Int64.mul step factor
  | DerivedBaseMinus (_, factor) -> Int64.neg (Int64.mul step factor)

let collect_loop_stable_phis header loop get_block def_blocks multi_defs def_instrs =
  let _ = def_blocks in
  let header_block : Cfg.block = get_block header in
  let pred_count = List.length header_block.preds in
  let pred_chains =
    List.map (fun pred -> (pred, incoming_phi_chain get_block header pred)) header_block.preds
  in
  let counts = Hashtbl.create (max 8 pred_count) in
  List.iter
    (fun (_, chain) ->
      IntSet.iter
        (fun dst ->
          let count = Option.value ~default:0 (Hashtbl.find_opt counts dst) in
          Hashtbl.replace counts dst (count + 1))
        (move_dests_in_chain chain))
    pred_chains;
  let phi_temps =
    Hashtbl.fold
      (fun temp count acc -> if count = pred_count then temp :: acc else acc)
      counts []
  in
  let backedge_preds = List.filter (fun pred -> LabelSet.mem pred loop) header_block.preds in
  List.fold_left
    (fun acc phi_temp ->
      let stable =
        backedge_preds <> []
        &&
        List.for_all
          (fun pred ->
            let chain =
              match List.assoc_opt pred pred_chains with
              | Some chain -> chain
              | None -> [ get_block pred ]
            in
            match last_move_of_temp_on_chain chain phi_temp with
            | Some src ->
                resolves_to_induction_temp
                  multi_defs def_instrs phi_temp (resolve_chain_operand chain src)
            | None -> false)
          backedge_preds
      in
      if stable then IntSet.add phi_temp acc else acc)
    IntSet.empty phi_temps

let collect_header_phi_temps header get_block =
  let header_block : Cfg.block = get_block header in
  let pred_count = List.length header_block.preds in
  let counts = Hashtbl.create (max 8 pred_count) in
  List.iter
    (fun pred ->
      IntSet.iter
        (fun dst ->
          let count = Option.value ~default:0 (Hashtbl.find_opt counts dst) in
          Hashtbl.replace counts dst (count + 1))
        (move_dests_in_chain (incoming_phi_chain get_block header pred)))
    header_block.preds;
  Hashtbl.fold
    (fun temp count acc -> if count = pred_count then IntSet.add temp acc else acc)
    counts IntSet.empty

let operand_loop_invariant
    loop_defs
    loop_stable_phis
    multi_defs
    def_instrs
    ready_temps
    operand
  =
  let rec resolve seen = function
    | Tcg.Imm _ -> true
    | Tcg.Temp temp ->
        if IntSet.mem temp ready_temps || IntSet.mem temp loop_stable_phis then true
        else if not (IntSet.mem temp loop_defs) then true
        else if IntSet.mem temp seen || IntSet.mem temp multi_defs then false
        else
          match Hashtbl.find_opt def_instrs temp with
          | Some (Tcg.Move (_, src)) -> resolve (IntSet.add temp seen) src
          | Some _ | None -> false
  in
  resolve IntSet.empty operand

let licm_invariant_candidate
    loop_defs
    loop_stable_phis
    multi_defs
    def_instrs
    ready_temps
    effects
    instr
  =
  match licm_candidate_info instr with
  | Some (LicmPure (dst, _)) when IntSet.mem dst multi_defs -> None
  | Some (LicmPure (dst, operands))
    when
      List.for_all
        (operand_loop_invariant
           loop_defs
           loop_stable_phis
           multi_defs
           def_instrs
           ready_temps)
        operands ->
      Some dst
  | Some (LicmLoad (dst, _)) when IntSet.mem dst multi_defs -> None
  | Some (LicmLoad (dst, place)) when load_place_invariant effects place -> Some dst
  | Some _ | None -> None

let derived_expr_of_instr loop_defs loop_stable_phis multi_defs def_instrs phi_temp = function
  | Tcg.Bin (dst, _, _, _) when dst = phi_temp -> None
  | Tcg.Bin (dst, Mul, lhs, Tcg.Imm factor)
    when resolves_to_induction_temp multi_defs def_instrs phi_temp lhs ->
      Some (dst, DerivedScaled factor)
  | Tcg.Bin (dst, Mul, Tcg.Imm factor, rhs)
    when resolves_to_induction_temp multi_defs def_instrs phi_temp rhs ->
      Some (dst, DerivedScaled factor)
  | Tcg.Bin (dst, Add, lhs, rhs) -> (
      match
        ( scaled_factor_of_operand multi_defs def_instrs phi_temp lhs,
          operand_loop_invariant
            loop_defs loop_stable_phis multi_defs def_instrs IntSet.empty rhs,
          scaled_factor_of_operand multi_defs def_instrs phi_temp rhs,
          operand_loop_invariant
            loop_defs loop_stable_phis multi_defs def_instrs IntSet.empty lhs )
      with
      | Some factor, true, _, _ -> Some (dst, DerivedAdd (rhs, factor))
      | _, _, Some factor, true -> Some (dst, DerivedAdd (lhs, factor))
      | _ -> None)
  | Tcg.Bin (dst, Sub, lhs, rhs) -> (
      match
        ( scaled_factor_of_operand multi_defs def_instrs phi_temp lhs,
          operand_loop_invariant
            loop_defs loop_stable_phis multi_defs def_instrs IntSet.empty rhs,
          scaled_factor_of_operand multi_defs def_instrs phi_temp rhs,
          operand_loop_invariant
            loop_defs loop_stable_phis multi_defs def_instrs IntSet.empty lhs )
      with
      | Some factor, true, _, _ -> Some (dst, DerivedSubBase (factor, rhs))
      | _, _, Some factor, true -> Some (dst, DerivedBaseMinus (lhs, factor))
      | _ -> None)
  | _ -> None

let collect_basic_induction_vars header loop get_block loop_defs multi_defs def_instrs =
  let header_block : Cfg.block = get_block header in
  let pred_count = List.length header_block.preds in
  let pred_chains =
    List.map (fun pred -> (pred, incoming_phi_chain get_block header pred)) header_block.preds
  in
  let chain_for_pred pred =
    match List.assoc_opt pred pred_chains with
    | Some chain -> chain
    | None -> [ get_block pred ]
  in
  let outside_seed_chain_for_pred pred =
    let chain = chain_for_pred pred in
    if LabelSet.mem pred loop then chain
    else extend_counted_outside_seed_chain get_block loop chain
  in
  let step_of_chain_source phi_temp chain src =
    let resolved = resolve_chain_operand chain src in
    match resolved with
    | Tcg.Imm _ -> None
    | Tcg.Temp temp -> (
        match def_instr_on_chain_or_global chain multi_defs def_instrs temp with
        | Some instr ->
            induction_step_of_instr_on_chain chain loop_defs multi_defs def_instrs phi_temp instr
        | None -> None)
  in
  let step_of_chain_def phi_temp chain =
    match last_def_of_temp_on_chain chain phi_temp with
    | Some (Tcg.Move (_, src)) -> step_of_chain_source phi_temp chain src
    | Some instr -> induction_step_of_instr_on_chain chain loop_defs multi_defs def_instrs phi_temp instr
    | None -> None
  in
  let counts = Hashtbl.create (max 8 pred_count) in
  List.iter
    (fun (_, chain) ->
      IntSet.iter
        (fun dst ->
          let count = Option.value ~default:0 (Hashtbl.find_opt counts dst) in
          Hashtbl.replace counts dst (count + 1))
        (move_dests_in_chain chain))
    pred_chains;
  let phi_temps =
    Hashtbl.fold
      (fun temp count acc -> if count = pred_count then temp :: acc else acc)
      counts []
  in
  let outside_preds =
    List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds
  in
  let backedge_preds = List.filter (fun pred -> LabelSet.mem pred loop) header_block.preds in
  if outside_preds = [] || backedge_preds = [] then []
  else
    let phi_vars =
      List.filter_map
        (fun phi_temp ->
          let incoming =
            List.filter_map
              (fun (pred, chain) ->
                match last_move_of_temp_on_chain chain phi_temp with
                | Some src -> Some (pred, resolve_chain_operand chain src)
                | None -> None)
              pred_chains
          in
          if List.length incoming <> pred_count then None
          else
            let steps =
              List.filter_map
                (fun pred ->
                  match List.assoc_opt pred incoming with
                  | Some src -> step_of_chain_source phi_temp (chain_for_pred pred) src
                  | None -> None)
                backedge_preds
            in
            match steps with
            | [] -> None
            | step :: rest when List.length steps = List.length backedge_preds ->
                if List.for_all (Int64.equal step) rest then
                  Some
                    {
                      phi_temp;
                      outside_inputs =
                        List.filter (fun (pred, _) -> List.mem pred outside_preds) incoming;
                      backedge_preds;
                      step;
                      origin = `Syntactic;
                    }
                else None
            | _ -> None)
        phi_temps
    in
    let seen_phi_temps =
      List.fold_left (fun acc iv -> IntSet.add iv.phi_temp acc) IntSet.empty phi_vars
    in
    let self_update_candidates =
      List.fold_left
        (fun acc pred ->
          List.fold_left
            (fun acc (block : Cfg.block) ->
              List.fold_left
                (fun acc instr ->
                  match defs_temp instr with
                  | Some dst when not (IntSet.mem dst seen_phi_temps) -> (
                      match
                        induction_step_of_instr_on_chain
                          (chain_for_pred pred)
                          loop_defs
                          multi_defs
                          def_instrs
                          dst
                          instr
                      with
                      | Some _ -> IntSet.add dst acc
                      | None -> acc)
                  | Some _ | None -> acc)
                acc block.body)
            acc (chain_for_pred pred))
        IntSet.empty backedge_preds
    in
    let self_vars =
      IntSet.fold
        (fun phi_temp acc ->
          let outside_inputs =
            List.filter_map
              (fun pred ->
                match
                  last_def_of_temp_on_chain
                    (outside_seed_chain_for_pred pred)
                    phi_temp
                with
                | Some _ -> Some (pred, Tcg.Temp phi_temp)
                | None -> None)
              outside_preds
          in
          let steps =
            List.filter_map
              (fun pred ->
                step_of_chain_def phi_temp (chain_for_pred pred))
              backedge_preds
          in
          match steps with
          | [] -> acc
          | step :: rest when List.length steps = List.length backedge_preds ->
              if
                List.length outside_inputs = List.length outside_preds
                && List.for_all (Int64.equal step) rest
              then begin
                if Sys.getenv_opt "TOYC_DEBUG_COUNTED_SEEDS" <> None then
                  Printf.eprintf
                    "counted-seed-self-iv header=%s temp=%d step=%Ld outside=%d
%!"
                    header phi_temp step (List.length outside_inputs);
                {
                  phi_temp;
                  outside_inputs;
                  backedge_preds;
                  step;
                  origin = `Syntactic;
                }
                :: acc
              end
              else acc
          | _ -> acc)
        self_update_candidates []
    in
    phi_vars @ self_vars

(* -------------------------------------------------------------------------- *)
(* step112: Loop Value Evolution (SCEV-lite)                                  *)
(* -------------------------------------------------------------------------- *)

let rec normalize_loop_inv_expr expr =
  let order_pair a b = if Stdlib.compare a b <= 0 then (a, b) else (b, a) in
  match expr with
  | LveConst value -> LveConst (i32 value)
  | LveOperand (Tcg.Imm value) -> LveConst (i32 value)
  | LveOperand operand -> LveOperand operand
  | LveNeg inner -> (
      match normalize_loop_inv_expr inner with
      | LveConst value -> LveConst (i32 Int64.(neg value))
      | LveNeg inner -> inner
      | inner -> LveNeg inner)
  | LveAdd (lhs, rhs) ->
      let lhs = normalize_loop_inv_expr lhs in
      let rhs = normalize_loop_inv_expr rhs in
      begin
        match (lhs, rhs) with
        | LveConst 0L, other | other, LveConst 0L -> other
        | LveConst a, LveConst b -> LveConst (i32 Int64.(add a b))
        | _ ->
            let lhs, rhs = order_pair lhs rhs in
            LveAdd (lhs, rhs)
      end
  | LveMul (lhs, rhs) ->
      let lhs = normalize_loop_inv_expr lhs in
      let rhs = normalize_loop_inv_expr rhs in
      begin
        match (lhs, rhs) with
        | LveConst 0L, _ | _, LveConst 0L -> LveConst 0L
        | LveConst 1L, other | other, LveConst 1L -> other
        | LveConst (-1L), other | other, LveConst (-1L) ->
            normalize_loop_inv_expr (LveNeg other)
        | LveConst a, LveConst b -> LveConst (i32 Int64.(mul a b))
        | _ ->
            let lhs, rhs = order_pair lhs rhs in
            LveMul (lhs, rhs)
      end

let rec canonical_scalar_form_of_loop_inv_expr expr =
  match normalize_loop_inv_expr expr with
  | LveConst value ->
      canonical_scalar_const value
  | LveOperand operand ->
      canonical_scalar_operand operand
  | LveNeg inner ->
      canonical_scalar_un
        UMinus
        (canonical_scalar_form_of_loop_inv_expr
           inner)
  | LveAdd (lhs, rhs) ->
      canonical_scalar_add
        (canonical_scalar_form_of_loop_inv_expr
           lhs)
        (canonical_scalar_form_of_loop_inv_expr
           rhs)
  | LveMul (lhs, rhs) ->
      canonical_scalar_mul
        (canonical_scalar_form_of_loop_inv_expr
           lhs)
        (canonical_scalar_form_of_loop_inv_expr
           rhs)

let loop_inv_linear_key expr =
  canonical_scalar_key_of_form
    (canonical_scalar_form_of_loop_inv_expr
       expr)

let loop_inv_expr_equal lhs rhs =
  canonical_scalar_key_equal
    (canonical_scalar_form_of_loop_inv_expr lhs)
    (canonical_scalar_form_of_loop_inv_expr rhs)

let rec loop_inv_expr_temps expr =
  match normalize_loop_inv_expr expr with
  | LveConst _ -> IntSet.empty
  | LveOperand (Tcg.Imm _) -> IntSet.empty
  | LveOperand (Tcg.Temp temp) -> IntSet.singleton temp
  | LveNeg inner -> loop_inv_expr_temps inner
  | LveAdd (lhs, rhs) | LveMul (lhs, rhs) ->
      IntSet.union (loop_inv_expr_temps lhs) (loop_inv_expr_temps rhs)

let string_of_lve_operand = function
  | Tcg.Imm value -> Printf.sprintf "%Ld" value
  | Tcg.Temp temp -> Printf.sprintf "t%d" temp

let rec string_of_loop_inv_expr = function
  | LveConst value -> Printf.sprintf "%Ld" value
  | LveOperand operand -> string_of_lve_operand operand
  | LveNeg inner -> Printf.sprintf "-(%s)" (string_of_loop_inv_expr inner)
  | LveAdd (lhs, rhs) ->
      Printf.sprintf "(%s+%s)" (string_of_loop_inv_expr lhs) (string_of_loop_inv_expr rhs)
  | LveMul (lhs, rhs) ->
      Printf.sprintf "(%s*%s)" (string_of_loop_inv_expr lhs) (string_of_loop_inv_expr rhs)

(* Canonicalize a loop-invariant operand through its unique definition.

   This is intentionally analysis-only: no IR is rewritten here.  The goal is
   to give semantically identical invariant values the same symbolic identity.

   Typical example after lowering/mem2reg:

       t10 = step
       ...
       t13 = step

   The old LVE represented the two path deltas as [t10] and [t13] and rejected
   the AddRec.  Following unique Move/UPlus chains makes both become the same
   root value.

   We also fold simple expressions made entirely from invariant values.  This
   gives the LVE layer a useful canonical form for future symbolic recurrences
   such as [step + 4] and [step * k]. *)
let lve_invariant_expr_of_operand
    loop_defs multi_defs def_instrs operand =
  let rec canonical seen operand =
    match operand with
    | Tcg.Imm value -> Some (LveConst value)
    | Tcg.Temp temp ->
        if IntSet.mem temp loop_defs then None
        else if IntSet.mem temp seen then Some (LveOperand operand)
        else if IntSet.mem temp multi_defs then
          (* Multiple reaching definitions outside the current natural loop are
             not globally interchangeable without path information. *)
          Some (LveOperand operand)
        else
          let seen = IntSet.add temp seen in
          match Hashtbl.find_opt def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) -> (
              match canonical seen src with
              | Some expr -> Some expr
              | None -> Some (LveOperand operand))
          | Some (Tcg.Un (_, UMinus, src)) -> (
              match canonical seen src with
              | Some expr -> Some (normalize_loop_inv_expr (LveNeg expr))
              | None -> Some (LveOperand operand))
          | Some (Tcg.Bin (_, Add, lhs, rhs)) -> (
              match (canonical seen lhs, canonical seen rhs) with
              | Some lhs, Some rhs ->
                  Some (normalize_loop_inv_expr (LveAdd (lhs, rhs)))
              | _ -> Some (LveOperand operand))
          | Some (Tcg.Bin (_, Sub, lhs, rhs)) -> (
              match (canonical seen lhs, canonical seen rhs) with
              | Some lhs, Some rhs ->
                  Some
                    (normalize_loop_inv_expr
                       (LveAdd (lhs, LveNeg rhs)))
              | _ -> Some (LveOperand operand))
          | Some (Tcg.Bin (_, Mul, lhs, rhs)) -> (
              match (canonical seen lhs, canonical seen rhs) with
              | Some lhs, Some rhs ->
                  Some (normalize_loop_inv_expr (LveMul (lhs, rhs)))
              | _ -> Some (LveOperand operand))
          | Some (Tcg.Un _)
          | Some (Tcg.Bin _)
          | Some (Tcg.Load _)
          | Some (Tcg.Store _)
          | Some (Tcg.Call _)
          | None -> Some (LveOperand operand)
  in
  let result = canonical IntSet.empty operand in
  (if Sys.getenv_opt "TOYC_DEBUG_LVE" <> None then
     match (operand, result) with
     | Tcg.Temp temp, Some expr
       when expr <> LveOperand operand ->
         Printf.eprintf
           "lve-inv-canon t%d -> %s\n%!"
           temp (string_of_loop_inv_expr expr)
     | _ -> ());
  result

(* A path-sensitive reaching-value query used by the logical-PHI view.

   Unlike fix2, this query does NOT require all predecessor paths to end in the
   same source operand.  It returns one case per reaching Move definition,
   together with the concrete backwards chain used to reach that definition.

   This matters for shapes such as:

       if (...) {
         t1 = i + step;
         phi = t1;
       } else {
         t2 = i + step;
         phi = t2;
       }
       latch:
         goto header

   [t1] and [t2] are different operands, but both paths have the same semantic
   delta from [i].  The AddRec analysis below compares the derived deltas, not
   the temporary names. *)
type lve_reaching_move_case = {
  reaching_source : Tcg.operand;
  reaching_def_label : Tcg.label;
  reaching_chain : Cfg.block list;
}

let reaching_move_cases_on_edge get_block ~stop_label ~pred_label temp =
  let rec search seen chain label =
    if label = stop_label || LabelSet.mem label seen then None
    else
      let block : Cfg.block = get_block label in
      let chain = chain @ [ block ] in
      match last_def_of_temp block temp with
      | Some (Tcg.Move (dst, src)) when dst = temp ->
          Some
            [
              {
                reaching_source = src;
                reaching_def_label = label;
                reaching_chain = chain;
              };
            ]
      | Some _ ->
          (* A non-Move nearest definition is not a mem2reg-style edge copy. *)
          None
      | None ->
          let seen = LabelSet.add label seen in
          let preds =
            List.filter (fun pred -> pred <> stop_label) block.preds
          in
          begin
            match preds with
            | [] -> None
            | _ ->
                let reached = List.map (search seen chain) preds in
                if List.exists Option.is_none reached then None
                else
                  let cases = List.concat_map (Option.value ~default:[]) reached in
                  if cases = [] then None else Some cases
          end
  in
  search LabelSet.empty [] pred_label

let dedup_reaching_move_cases cases =
  List.fold_left
    (fun acc case ->
      if
        List.exists
          (fun existing ->
            existing.reaching_def_label = case.reaching_def_label
            && existing.reaching_source = case.reaching_source)
          acc
      then acc
      else case :: acc)
    [] cases
  |> List.rev

(* Recover the PHI semantics that mem2reg lowered into edge copies.

   A temp is a logical-PHI candidate when every header incoming edge can be
   traced backwards to one or more unambiguous Move definitions of that temp.
   Different paths are allowed to use different source temporaries.  The
   recurrence proof, not PHI recovery, is responsible for showing that all
   backedge paths have the same evolution. *)
let recover_logical_loop_phis header loop get_block multi_defs =
  let header_block : Cfg.block = get_block header in
  let preds = header_block.preds in
  let outside_preds =
    List.filter (fun pred -> not (LabelSet.mem pred loop)) preds
  in
  let backedge_preds =
    List.filter (fun pred -> LabelSet.mem pred loop) preds
  in
  if preds = [] || outside_preds = [] || backedge_preds = [] then []
  else
    IntSet.elements multi_defs
    |> List.filter_map (fun phi_temp ->
           let incoming =
             List.filter_map
               (fun pred ->
                 match
                   reaching_move_cases_on_edge
                     get_block ~stop_label:header ~pred_label:pred phi_temp
                 with
                 | Some cases ->
                     Some (pred, dedup_reaching_move_cases cases)
                 | None -> None)
               preds
           in
           if List.length incoming <> List.length preds then None
           else
             let all_def_labels =
               List.fold_left
                 (fun labels (_, cases) ->
                   List.fold_left
                     (fun labels case ->
                       LabelSet.add case.reaching_def_label labels)
                     labels cases)
                 LabelSet.empty incoming
             in
             if LabelSet.cardinal all_def_labels < 2 then None
             else
               let outside_inputs =
                 List.map
                   (fun pred -> (pred, Tcg.Temp phi_temp))
                   outside_preds
               in
               let backedge_cases =
                 List.concat_map
                   (fun (pred, cases) ->
                     if List.mem pred backedge_preds then
                       List.map
                         (fun case ->
                           {
                             logical_header_pred = pred;
                             logical_def_label = case.reaching_def_label;
                             logical_source = case.reaching_source;
                             logical_chain = case.reaching_chain;
                           })
                         cases
                     else [])
                   incoming
               in
               if backedge_cases = [] then None
               else begin
                 if Sys.getenv_opt "TOYC_DEBUG_LVE" <> None then
                   Printf.eprintf
                     "lve-phi header=%s phi=t%d outside=%d backedges=%d paths=%d defs=%d\n%!"
                     header phi_temp
                     (List.length outside_inputs)
                     (List.length backedge_preds)
                     (List.length backedge_cases)
                     (LabelSet.cardinal all_def_labels);
                 Some
                   {
                     logical_phi_temp = phi_temp;
                     logical_outside_inputs = outside_inputs;
                     logical_backedge_preds = backedge_preds;
                     logical_backedge_cases = backedge_cases;
                   }
               end)

(* Return the additive delta in [value = phi + delta].  The important
   distinction from the old induction matcher is that [delta] is a symbolic
   loop-invariant expression rather than an int64. *)
let lve_delta_from_phi chain loop_defs multi_defs def_instrs phi_temp operand =
  let rec delta seen operand =
    match operand with
    | Tcg.Imm _ -> None
    | Tcg.Temp temp when temp = phi_temp -> Some (LveConst 0L)
    | Tcg.Temp temp ->
        if IntSet.mem temp seen then None
        else
          let seen = IntSet.add temp seen in
          match def_instr_on_chain_or_global chain multi_defs def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) -> delta seen src
          | Some (Tcg.Bin (_, Add, lhs, rhs)) -> (
              match (delta seen lhs, lve_invariant_expr_of_operand loop_defs multi_defs def_instrs rhs) with
              | Some lhs_delta, Some rhs_inv ->
                  Some (normalize_loop_inv_expr (LveAdd (lhs_delta, rhs_inv)))
              | _ -> (
                  match (lve_invariant_expr_of_operand loop_defs multi_defs def_instrs lhs, delta seen rhs) with
                  | Some lhs_inv, Some rhs_delta ->
                      Some (normalize_loop_inv_expr (LveAdd (lhs_inv, rhs_delta)))
                  | _ -> None))
          | Some (Tcg.Bin (_, Sub, lhs, rhs)) -> (
              match (delta seen lhs, lve_invariant_expr_of_operand loop_defs multi_defs def_instrs rhs) with
              | Some lhs_delta, Some rhs_inv ->
                  Some
                    (normalize_loop_inv_expr
                       (LveAdd (lhs_delta, LveNeg rhs_inv)))
              | _ -> None)
          | Some (Tcg.Un _)
          | Some (Tcg.Bin _)
          | Some (Tcg.Load _)
          | Some (Tcg.Store _)
          | Some (Tcg.Call _)
          | None -> None
  in
  delta IntSet.empty operand |> Option.map normalize_loop_inv_expr

(* A backedge edge-copy may itself read another logical PHI.

   Example after mem2reg:

       then:  next_phi = i + step
       else:  next_phi = step + i
       join:  i_phi = next_phi
       ... -> header

   The physical reaching definition of [i_phi] is only [i_phi <- next_phi], so
   the first level has one path.  But [next_phi] is multi-defined.  Recursively
   expand that source at the point where [i_phi] reads it, then derive a delta
   independently for every resulting path.

   This is the missing piece that turns path-specific PHI recovery into
   path-specific *value evolution*, rather than merely path-specific edge-copy
   recovery. *)
let lve_delta_cases_from_backedge
    get_block loop_defs multi_defs def_instrs phi_temp
    (case : logical_phi_backedge_case) =
  let rec expand seen_merge_temps def_label chain source =
    match
      lve_delta_from_phi
        chain loop_defs multi_defs def_instrs phi_temp source
    with
    | Some step -> Some [ normalize_loop_inv_expr step ]
    | None -> (
        match source with
        | Tcg.Temp temp
          when temp <> phi_temp
               && IntSet.mem temp multi_defs
               && not (IntSet.mem temp seen_merge_temps) ->
            let block : Cfg.block = get_block def_label in
            let preds = block.preds in
            if preds = [] then None
            else
              let seen_merge_temps = IntSet.add temp seen_merge_temps in
              let reached_per_pred =
                List.map
                  (fun pred ->
                    reaching_move_cases_on_edge
                      get_block ~stop_label:def_label ~pred_label:pred temp)
                  preds
              in
              if List.exists Option.is_none reached_per_pred then None
              else
                let reached =
                  reached_per_pred
                  |> List.concat_map (Option.value ~default:[])
                  |> dedup_reaching_move_cases
                in
                if reached = [] then None
                else
                  let expanded =
                    List.map
                      (fun reached_case ->
                        expand
                          seen_merge_temps
                          reached_case.reaching_def_label
                          reached_case.reaching_chain
                          reached_case.reaching_source)
                      reached
                  in
                  if List.exists Option.is_none expanded then None
                  else
                    Some
                      (expanded
                       |> List.concat_map (Option.value ~default:[])
                       |> List.map normalize_loop_inv_expr)
        | Tcg.Imm _ | Tcg.Temp _ -> None)
  in
  let result =
    expand IntSet.empty case.logical_def_label case.logical_chain
      case.logical_source
  in
  (if Sys.getenv_opt "TOYC_DEBUG_LVE" <> None then
     match result with
     | Some steps when List.length steps > 1 ->
         Printf.eprintf
           "lve-delta-expand header-pred=%s phi=t%d source=%s paths=%d deltas={%s}\n%!"
           case.logical_header_pred phi_temp
           (string_of_lve_operand case.logical_source)
           (List.length steps)
           (String.concat "," (List.map string_of_loop_inv_expr steps))
     | Some _ | None -> ());
  result

let symbolic_induction_step_of_instr_on_chain
    chain loop_defs multi_defs def_instrs phi_temp = function
  | Tcg.Bin (_, Add, lhs, rhs)
    when
      resolves_to_induction_temp_on_chain
        chain multi_defs def_instrs phi_temp lhs ->
      lve_invariant_expr_of_operand
        loop_defs multi_defs def_instrs rhs
      |> Option.map normalize_loop_inv_expr
  | Tcg.Bin (_, Add, lhs, rhs)
    when
      resolves_to_induction_temp_on_chain
        chain multi_defs def_instrs phi_temp rhs ->
      lve_invariant_expr_of_operand
        loop_defs multi_defs def_instrs lhs
      |> Option.map normalize_loop_inv_expr
  | Tcg.Bin (_, Sub, lhs, rhs)
    when
      resolves_to_induction_temp_on_chain
        chain multi_defs def_instrs phi_temp lhs ->
      lve_invariant_expr_of_operand
        loop_defs multi_defs def_instrs rhs
      |> Option.map (fun step ->
             normalize_loop_inv_expr (LveNeg step))
  | Tcg.Move _
  | Tcg.Un _
  | Tcg.Bin _
  | Tcg.Load _
  | Tcg.Store _
  | Tcg.Call _ ->
      None

(* item2.4: prove that a physical update executes exactly once for every
   completed logical iteration of [header]'s natural loop.

   Soundness conditions are deliberately structural and conservative:
     1. the temp has exactly one definition inside this loop;
     2. every path from the current header to every latch/backedge predecessor
        must pass through the update block;
     3. after removing edges that start the next iteration (edges to [header]),
        the update block cannot reach itself.

   Condition (3) is the crucial nested-loop fence.  An update located inside a
   child loop lies on an internal cycle and is therefore rejected as a direct
   AddRec of the parent loop. *)

let reachable_in_loop
    loop get_block
    ~start ~target
    ~blocked
    ~drop_edges_to_header
    header =
  if LabelSet.mem start blocked then false
  else
    let rec visit work seen =
      match work with
      | [] ->
          false
      | label :: rest ->
          if label = target then true
          else if
            LabelSet.mem label seen
            || LabelSet.mem label blocked
          then
            visit rest seen
          else
            let seen = LabelSet.add label seen in
            let block : Cfg.block =
              get_block label
            in
            let succs =
              block.succs
              |> List.filter
                   (fun succ ->
                     LabelSet.mem succ loop
                     && not
                          (drop_edges_to_header
                           && succ = header)
                     && not
                          (LabelSet.mem succ blocked))
            in
            visit
              (List.rev_append succs rest)
              seen
    in
    visit [ start ] LabelSet.empty

let loop_has_dedicated_preheader_from_cfg
    header loop get_block =
  let header_block : Cfg.block =
    get_block header
  in
  match
    List.filter
      (fun pred ->
        not (LabelSet.mem pred loop))
      header_block.preds
  with
  | [ pred ] ->
      let pred_block : Cfg.block =
        get_block pred
      in
      pred_block.succs = [ header ]
  | []
  | _ :: _ :: _ ->
      false

let loop_has_dedicated_exits_from_cfg
    loop get_block =
  let exit_targets =
    LabelSet.fold
      (fun label targets ->
        let block : Cfg.block =
          get_block label
        in
        List.fold_left
          (fun targets succ ->
            if LabelSet.mem succ loop then targets
            else LabelSet.add succ targets)
          targets block.succs)
      loop LabelSet.empty
  in
  LabelSet.for_all
    (fun target ->
      let exit_block : Cfg.block =
        get_block target
      in
      exit_block.preds <> []
      && List.for_all
           (fun pred ->
             LabelSet.mem pred loop)
           exit_block.preds)
    exit_targets

let direct_update_exactly_once_proof
    header loop get_block phi_temp =
  if
    not
      (loop_has_dedicated_preheader_from_cfg
         header loop get_block)
  then
    Error "loop-not-simplified-preheader"
  else if
    not
      (loop_has_dedicated_exits_from_cfg
         loop get_block)
  then
    Error "loop-not-simplified-exits"
  else
  let header_block : Cfg.block =
    get_block header
  in
  let latches =
    header_block.preds
    |> List.filter
         (fun pred -> LabelSet.mem pred loop)
    |> List.sort_uniq String.compare
  in
  let def_sites =
    LabelSet.fold
      (fun label sites ->
        let block : Cfg.block =
          get_block label
        in
        List.fold_left
          (fun sites instr ->
            match defs_temp instr with
            | Some dst when dst = phi_temp ->
                label :: sites
            | Some _
            | None ->
                sites)
          sites block.body)
      loop []
  in
  match def_sites with
  | [ update_label ] ->
      if latches = [] then
        Error "no-latch"
      else
        let must_execute =
          if update_label = header then true
          else
            let blocked =
              LabelSet.singleton update_label
            in
            List.for_all
              (fun latch ->
                not
                  (reachable_in_loop
                     loop get_block
                     ~start:header
                     ~target:latch
                     ~blocked
                     ~drop_edges_to_header:false
                     header))
              latches
        in
        if not must_execute then
          Error "update-not-on-every-backedge-path"
        else
          let update_block : Cfg.block =
            get_block update_label
          in
          let repeats_within_iteration =
            List.exists
              (fun succ ->
                LabelSet.mem succ loop
                && succ <> header
                && reachable_in_loop
                     loop get_block
                     ~start:succ
                     ~target:update_label
                     ~blocked:LabelSet.empty
                     ~drop_edges_to_header:true
                     header)
              update_block.succs
          in
          if repeats_within_iteration then
            Error "update-in-internal-cycle"
          else
            Ok update_label
  | [] ->
      Error "no-loop-definition"
  | _ :: _ :: _ ->
      Error "multiple-loop-definitions"


let analyze_direct_self_addrecs
    header loop get_block loop_defs multi_defs def_instrs
    excluded_temps =
  let header_block : Cfg.block = get_block header in
  let outside_preds =
    List.filter
      (fun pred -> not (LabelSet.mem pred loop))
      header_block.preds
  in
  let backedge_preds =
    List.filter
      (fun pred -> LabelSet.mem pred loop)
      header_block.preds
  in
  if outside_preds = [] || backedge_preds = [] then []
  else
    let backedge_chains =
      List.map
        (fun pred ->
          ( pred,
            incoming_update_chain
              get_block header pred ))
        backedge_preds
    in
    let chain_for_backedge pred =
      match List.assoc_opt pred backedge_chains with
      | Some chain ->
          chain
      | None ->
          [ get_block pred ]
    in
    let outside_seed_chain pred =
      incoming_phi_chain get_block header pred
      |> extend_counted_outside_seed_chain
           get_block loop
    in
    let step_of_chain_source phi_temp chain src =
      let resolved =
        resolve_chain_operand chain src
      in
      match resolved with
      | Tcg.Imm _ ->
          None
      | Tcg.Temp temp -> (
          match
            def_instr_on_chain_or_global
              chain multi_defs def_instrs temp
          with
          | Some instr ->
              symbolic_induction_step_of_instr_on_chain
                chain loop_defs multi_defs def_instrs
                phi_temp instr
          | None ->
              None)
    in
    let step_of_chain_def phi_temp chain =
      match
        last_def_of_temp_on_chain chain phi_temp
      with
      | Some (Tcg.Move (_, src)) ->
          step_of_chain_source phi_temp chain src
      | Some instr ->
          symbolic_induction_step_of_instr_on_chain
            chain loop_defs multi_defs def_instrs
            phi_temp instr
      | None ->
          None
    in
    let candidates =
      List.fold_left
        (fun candidates (_, chain) ->
          List.fold_left
            (fun candidates (block : Cfg.block) ->
              List.fold_left
                (fun candidates instr ->
                  match defs_temp instr with
                  | Some dst
                    when
                      not (IntSet.mem dst excluded_temps)
                      &&
                      Option.is_some
                        (symbolic_induction_step_of_instr_on_chain
                           chain loop_defs multi_defs
                           def_instrs dst instr) ->
                      IntSet.add dst candidates
                  | Some _
                  | None ->
                      candidates)
                candidates
                block.body)
            candidates
            chain)
        IntSet.empty
        backedge_chains
    in
    IntSet.fold
      (fun phi_temp addrecs ->
        let outside_inputs =
          List.filter_map
            (fun pred ->
              let chain = outside_seed_chain pred in
              match
                last_def_of_temp_on_chain
                  chain phi_temp
              with
              | Some _ ->
                  Some (pred, Tcg.Temp phi_temp)
              | None ->
                  None)
            outside_preds
        in
        let steps =
          List.filter_map
            (fun pred ->
              let chain = chain_for_backedge pred in
              Option.map
                (fun step -> (pred, step))
                (step_of_chain_def phi_temp chain))
            backedge_preds
        in
        match steps with
        | []
        | _ when
            List.length outside_inputs
            <> List.length outside_preds
            || List.length steps
               <> List.length backedge_preds ->
            addrecs
        | (_, first_step) :: rest
          when
            List.for_all
              (fun (_, step) ->
                loop_inv_expr_equal first_step step)
              rest ->
            let addrec =
              {
                addrec_phi_temp = phi_temp;
                addrec_outside_inputs = outside_inputs;
                addrec_backedge_preds = backedge_preds;
                addrec_step =
                  normalize_loop_inv_expr first_step;
              }
            in
            if
              Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED"
              <> None
            then
              Printf.eprintf
                "scev-direct-addrec header=%s phi=t%d step=%s outside=%d backedges=%d\n%!"
                header phi_temp
                (string_of_loop_inv_expr
                   addrec.addrec_step)
                (List.length outside_inputs)
                (List.length backedge_preds);
            addrec :: addrecs
        | _ ->
            addrecs)
      candidates
      []

let analyze_loop_addrecs
    header loop get_block loop_defs multi_defs def_instrs =
  let logical_addrecs =
    recover_logical_loop_phis
      header loop get_block multi_defs
    |> List.filter_map
         (fun (phi : logical_loop_phi) ->
           let recovered =
             List.map
               (fun case ->
                 ( case,
                   lve_delta_cases_from_backedge
                     get_block loop_defs multi_defs
                     def_instrs
                     phi.logical_phi_temp case ))
               phi.logical_backedge_cases
           in
           let all_recovered =
             List.for_all
               (fun (_, steps) ->
                 match steps with
                 | Some (_ :: _) ->
                     true
                 | Some []
                 | None ->
                     false)
               recovered
           in
           let steps =
             recovered
             |> List.concat_map
                  (fun (case, maybe_steps) ->
                    match maybe_steps with
                    | None ->
                        []
                    | Some path_steps ->
                        List.map
                          (fun step ->
                            ( case.logical_header_pred,
                              case.logical_def_label,
                              normalize_loop_inv_expr
                                step ))
                          path_steps)
           in
           match steps with
           | [] ->
               None
           | (_, _, step) :: rest
             when
               all_recovered
               && List.for_all
                    (fun (_, _, other) ->
                      loop_inv_expr_equal step other)
                    rest ->
               let addrec =
                 {
                   addrec_phi_temp =
                     phi.logical_phi_temp;
                   addrec_outside_inputs =
                     phi.logical_outside_inputs;
                   addrec_backedge_preds =
                     phi.logical_backedge_preds;
                   addrec_step =
                     normalize_loop_inv_expr step;
                 }
               in
               if
                 Sys.getenv_opt "TOYC_DEBUG_LVE"
                 <> None
               then
                 Printf.eprintf
                   "lve-addrec header=%s phi=t%d step=%s outside=%d backedges=%d physical-paths=%d value-paths=%d\n%!"
                   header
                   addrec.addrec_phi_temp
                   (string_of_loop_inv_expr
                      addrec.addrec_step)
                   (List.length
                      addrec.addrec_outside_inputs)
                   (List.length
                      addrec.addrec_backedge_preds)
                   (List.length
                      phi.logical_backedge_cases)
                   (List.length steps);
               Some addrec
           | _ ->
               (if
                  Sys.getenv_opt "TOYC_DEBUG_LVE"
                  <> None
                then
                  let rendered =
                    steps
                    |> List.map
                         (fun
                           ( pred,
                             def_label,
                             step ) ->
                           Printf.sprintf
                             "%s/%s:%s"
                             pred def_label
                             (string_of_loop_inv_expr
                                step))
                    |> String.concat ","
                  in
                  Printf.eprintf
                    "lve-addrec-reject header=%s phi=t%d paths={%s} recovered=%b value-paths=%d physical-paths=%d\n%!"
                    header
                    phi.logical_phi_temp
                    rendered
                    all_recovered
                    (List.length steps)
                    (List.length
                       phi.logical_backedge_cases));
               None)
  in
  let logical_temps =
    List.fold_left
      (fun temps (addrec : loop_addrec) ->
        IntSet.add addrec.addrec_phi_temp temps)
      IntSet.empty
      logical_addrecs
  in
  let direct_addrecs =
    analyze_direct_self_addrecs
      header loop get_block
      loop_defs multi_defs def_instrs
      logical_temps
  in
  (* Global direct-self AddRec recovery is deliberately fenced off by
     default.

     Unlike recovered logical/edge-copy recurrences, a physical
       t = t + invariant
     instruction does not by itself prove that the update executes exactly
     once per logical iteration of every enclosing natural loop.  In
     particular, the same static instruction may execute repeatedly inside a
     nested subloop.  Treating such a temp as a global AddRec can therefore
     make the semantic step smaller than the true per-iteration delta and can
     poison later loop summaries.

     Keep the recognizer available for diagnostics/experimentation, but only
     logical AddRecs feed the general RecurrenceFacts layer by default.
     Runtime-summary rotated-loop recovery remains a separate, locally gated
     mechanism. *)
  if
    Sys.getenv_opt "TOYC_EXPERIMENTAL_GLOBAL_DIRECT_ADDREC"
    <> None
  then begin
    if
      Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED"
      <> None
      && direct_addrecs <> []
    then
      Printf.eprintf
        "scev-global-direct-addrec-mode header=%s mode=enabled candidates=%d\n%!"
        header (List.length direct_addrecs);
    logical_addrecs @ direct_addrecs
  end
  else begin
    if
      Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED"
      <> None
      && direct_addrecs <> []
    then
      Printf.eprintf
        "scev-global-direct-addrec-mode header=%s mode=fenced candidates=%d\n%!"
        header (List.length direct_addrecs);
    logical_addrecs
  end


(* -------------------------------------------------------------------------- *)
(* step136: unified scalar recurrence layer (SCEV-lite facade)                *)
(*                                                                            *)
(* The optimizer historically has two partially-overlapping induction views:  *)
(*   - [basic_induction_var], whose step must be an int64;                     *)
(*   - [loop_addrec], whose step may be a symbolic loop-invariant expression.  *)
(*                                                                            *)
(* This layer gives consumers one semantic vocabulary for scalar values.       *)
(* It is deliberately analysis-only in v1 and reuses the already path-sensitive*)
(* logical-PHI/AddRec recovery above.                                          *)
(*                                                                            *)
(* Canonical meaning:                                                         *)
(*   ScalarAddRec base               = base(k)                                 *)
(*   ScalarAffine {base;scale;bias}  = scale * base(k) + bias                  *)
(*                                                                            *)
(* Therefore i, i+c, i-c and a*i+b all share one representation.  A symbolic  *)
(* update such as [row += cols] is an AddRec whose [addrec_step] is the         *)
(* invariant expression [cols].                                               *)
(* -------------------------------------------------------------------------- *)

type scalar_recurrence =
  | ScalarConst of int64
  | ScalarInvariant of loop_inv_expr
  | ScalarAddRec of loop_addrec
  | ScalarAffine of {
      scalar_base : loop_addrec;
      scalar_scale : loop_inv_expr;
      scalar_bias : loop_inv_expr;
    }

let scalar_inv_zero = LveConst 0L
let scalar_inv_one = LveConst 1L

let loop_inv_expr_const_opt expr =
  match normalize_loop_inv_expr expr with
  | LveConst value -> Some value
  | LveOperand _
  | LveNeg _
  | LveAdd _
  | LveMul _ ->
      None

let scalar_recurrence_scale_bias = function
  | ScalarAddRec base ->
      Some (base, scalar_inv_one, scalar_inv_zero)
  | ScalarAffine { scalar_base; scalar_scale; scalar_bias } ->
      Some
        ( scalar_base,
          normalize_loop_inv_expr scalar_scale,
          normalize_loop_inv_expr scalar_bias )
  | ScalarConst _ | ScalarInvariant _ ->
      None

let rec normalize_scalar_recurrence = function
  | ScalarConst value -> ScalarConst (i32 value)
  | ScalarInvariant expr -> (
      match normalize_loop_inv_expr expr with
      | LveConst value -> ScalarConst value
      | expr -> ScalarInvariant expr)
  | ScalarAddRec base ->
      ScalarAddRec
        { base with addrec_step = normalize_loop_inv_expr base.addrec_step }
  | ScalarAffine { scalar_base; scalar_scale; scalar_bias } ->
      let scalar_base =
        { scalar_base with
          addrec_step = normalize_loop_inv_expr scalar_base.addrec_step }
      in
      let scalar_scale = normalize_loop_inv_expr scalar_scale in
      let scalar_bias = normalize_loop_inv_expr scalar_bias in
      begin
        match scalar_scale with
        | LveConst 0L ->
            normalize_scalar_recurrence (ScalarInvariant scalar_bias)
        | LveConst 1L when scalar_bias = LveConst 0L ->
            ScalarAddRec scalar_base
        | _ ->
            ScalarAffine { scalar_base; scalar_scale; scalar_bias }
      end

let scalar_recurrence_invariant_expr = function
  | ScalarConst value -> Some (LveConst value)
  | ScalarInvariant expr -> Some (normalize_loop_inv_expr expr)
  | ScalarAddRec _ | ScalarAffine _ -> None

let scalar_recurrence_affine base scale bias =
  normalize_scalar_recurrence
    (ScalarAffine
       {
         scalar_base = base;
         scalar_scale = normalize_loop_inv_expr scale;
         scalar_bias = normalize_loop_inv_expr bias;
       })

let scalar_recurrence_neg = function
  | ScalarConst value -> ScalarConst (i32 Int64.(neg value))
  | ScalarInvariant expr ->
      normalize_scalar_recurrence (ScalarInvariant (LveNeg expr))
  | ScalarAddRec base ->
      scalar_recurrence_affine base (LveConst (-1L)) (LveConst 0L)
  | ScalarAffine { scalar_base; scalar_scale; scalar_bias } ->
      scalar_recurrence_affine
        scalar_base
        (LveNeg scalar_scale)
        (LveNeg scalar_bias)

let scalar_same_base lhs rhs =
  lhs.addrec_phi_temp = rhs.addrec_phi_temp
  && loop_inv_expr_equal lhs.addrec_step rhs.addrec_step

let scalar_recurrence_add_invariant recurrence invariant =
  match scalar_recurrence_scale_bias recurrence with
  | Some (base, scale, bias) ->
      Some
        (scalar_recurrence_affine
           base scale
           (normalize_loop_inv_expr (LveAdd (bias, invariant))))
  | None -> None

let scalar_recurrence_add lhs rhs =
  let lhs = normalize_scalar_recurrence lhs in
  let rhs = normalize_scalar_recurrence rhs in
  match (lhs, rhs) with
  | ScalarConst lhs, ScalarConst rhs ->
      Some (ScalarConst (i32 Int64.(add lhs rhs)))
  | ScalarConst value, ((ScalarAddRec _ | ScalarAffine _) as recurrence)
  | ((ScalarAddRec _ | ScalarAffine _) as recurrence), ScalarConst value ->
      scalar_recurrence_add_invariant recurrence (LveConst value)
  | ScalarConst value, ScalarInvariant invariant
  | ScalarInvariant invariant, ScalarConst value ->
      Some
        (normalize_scalar_recurrence
           (ScalarInvariant
              (normalize_loop_inv_expr
                 (LveAdd (LveConst value, invariant)))))
  | ScalarInvariant lhs, ScalarInvariant rhs ->
      Some
        (normalize_scalar_recurrence
           (ScalarInvariant
              (normalize_loop_inv_expr (LveAdd (lhs, rhs)))))
  | ((ScalarAddRec _ | ScalarAffine _) as recurrence),
    ScalarInvariant invariant
  | ScalarInvariant invariant,
    ((ScalarAddRec _ | ScalarAffine _) as recurrence) ->
      scalar_recurrence_add_invariant recurrence invariant
  | (ScalarAddRec _ | ScalarAffine _),
    (ScalarAddRec _ | ScalarAffine _) ->
      begin
        match
          ( scalar_recurrence_scale_bias lhs,
            scalar_recurrence_scale_bias rhs )
        with
        | Some (lhs_base, lhs_scale, lhs_bias),
          Some (rhs_base, rhs_scale, rhs_bias)
          when scalar_same_base lhs_base rhs_base ->
            Some
              (scalar_recurrence_affine
                 lhs_base
                 (normalize_loop_inv_expr (LveAdd (lhs_scale, rhs_scale)))
                 (normalize_loop_inv_expr (LveAdd (lhs_bias, rhs_bias))))
        | _ -> None
      end

let scalar_recurrence_sub lhs rhs =
  scalar_recurrence_add lhs (scalar_recurrence_neg rhs)

let scalar_recurrence_mul lhs rhs =
  let lhs = normalize_scalar_recurrence lhs in
  let rhs = normalize_scalar_recurrence rhs in
  match
    ( scalar_recurrence_invariant_expr lhs,
      scalar_recurrence_invariant_expr rhs )
  with
  | Some lhs, Some rhs ->
      Some
        (normalize_scalar_recurrence
           (ScalarInvariant
              (normalize_loop_inv_expr (LveMul (lhs, rhs)))))
  | Some invariant, None
  | None, Some invariant ->
      let recurrence = if Option.is_some (scalar_recurrence_invariant_expr lhs)
        then rhs else lhs
      in
      begin
        match scalar_recurrence_scale_bias recurrence with
        | Some (base, scale, bias) ->
            Some
              (scalar_recurrence_affine
                 base
                 (normalize_loop_inv_expr (LveMul (scale, invariant)))
                 (normalize_loop_inv_expr (LveMul (bias, invariant))))
        | None -> None
      end
  | None, None ->
      (* v1 deliberately excludes products of two varying recurrences. *)
      None

let string_of_scalar_recurrence recurrence =
  match normalize_scalar_recurrence recurrence with
  | ScalarConst value ->
      Printf.sprintf "Const(%Ld)" value
  | ScalarInvariant expr ->
      Printf.sprintf "Invariant(%s)" (string_of_loop_inv_expr expr)
  | ScalarAddRec base ->
      Printf.sprintf
        "AddRec(phi=t%d,step=%s)"
        base.addrec_phi_temp
        (string_of_loop_inv_expr base.addrec_step)
  | ScalarAffine { scalar_base; scalar_scale; scalar_bias } ->
      Printf.sprintf
        "Affine(phi=t%d,step=%s,scale=%s,bias=%s)"
        scalar_base.addrec_phi_temp
        (string_of_loop_inv_expr scalar_base.addrec_step)
        (string_of_loop_inv_expr scalar_scale)
        (string_of_loop_inv_expr scalar_bias)

let scalar_addrec_table addrecs =
  let table = Hashtbl.create (max 8 (List.length addrecs)) in
  List.iter
    (fun (addrec : loop_addrec) ->
      Hashtbl.replace table addrec.addrec_phi_temp addrec)
    addrecs;
  table

let scalar_recurrence_of_operand
    loop_defs
    multi_defs
    def_instrs
    addrecs
    (block : Cfg.block)
    operand
  =
  let addrec_by_temp = scalar_addrec_table addrecs in
  let rec analyze seen operand =
    let operand = resolve_block_operand block operand in
    match operand with
    | Tcg.Imm value -> Some (ScalarConst value)
    | Tcg.Temp temp -> (
        match Hashtbl.find_opt addrec_by_temp temp with
        | Some addrec -> Some (ScalarAddRec addrec)
        | None ->
            if not (IntSet.mem temp loop_defs) then
              Option.map
                (fun expr -> normalize_scalar_recurrence (ScalarInvariant expr))
                (lve_invariant_expr_of_operand
                   loop_defs multi_defs def_instrs operand)
            else if IntSet.mem temp seen || IntSet.mem temp multi_defs then
              None
            else
              let seen = IntSet.add temp seen in
              match
                last_def_of_temp block temp,
                Hashtbl.find_opt def_instrs temp
              with
              | Some instr, _
              | None, Some instr ->
                  analyze_instr seen instr
              | None, None ->
                  None)
  and analyze_instr seen = function
    | Tcg.Move (_, src)
    | Tcg.Un (_, UPlus, src) ->
        analyze seen src
    | Tcg.Un (_, UMinus, src) ->
        Option.map scalar_recurrence_neg (analyze seen src)
    | Tcg.Bin (_, Add, lhs, rhs) ->
        Option.bind (analyze seen lhs) (fun lhs ->
            Option.bind (analyze seen rhs) (scalar_recurrence_add lhs))
    | Tcg.Bin (_, Sub, lhs, rhs) ->
        Option.bind (analyze seen lhs) (fun lhs ->
            Option.bind (analyze seen rhs) (scalar_recurrence_sub lhs))
    | Tcg.Bin (_, Mul, lhs, rhs) ->
        Option.bind (analyze seen lhs) (fun lhs ->
            Option.bind (analyze seen rhs) (scalar_recurrence_mul lhs))
    | Tcg.Un (_, UNot, _)
    | Tcg.Bin (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
    | Tcg.Load _
    | Tcg.Store _
    | Tcg.Call _ ->
        None
  in
  analyze IntSet.empty operand
  |> Option.map normalize_scalar_recurrence

let scalar_recurrence_of_instr
    loop_defs
    multi_defs
    def_instrs
    addrecs
    (block : Cfg.block)
    instr
  =
  let analyze =
    scalar_recurrence_of_operand
      loop_defs multi_defs def_instrs addrecs block
  in
  let with_dst dst recurrence =
    Option.map (fun recurrence -> (dst, normalize_scalar_recurrence recurrence)) recurrence
  in
  match instr with
  | Tcg.Move (dst, src)
  | Tcg.Un (dst, UPlus, src) ->
      with_dst dst (analyze src)
  | Tcg.Un (dst, UMinus, src) ->
      with_dst dst (Option.map scalar_recurrence_neg (analyze src))
  | Tcg.Bin (dst, Add, lhs, rhs) ->
      with_dst dst
        (Option.bind (analyze lhs) (fun lhs ->
             Option.bind (analyze rhs) (scalar_recurrence_add lhs)))
  | Tcg.Bin (dst, Sub, lhs, rhs) ->
      with_dst dst
        (Option.bind (analyze lhs) (fun lhs ->
             Option.bind (analyze rhs) (scalar_recurrence_sub lhs)))
  | Tcg.Bin (dst, Mul, lhs, rhs) ->
      with_dst dst
        (Option.bind (analyze lhs) (fun lhs ->
             Option.bind (analyze rhs) (scalar_recurrence_mul lhs)))
  | Tcg.Un (_, UNot, _)
  | Tcg.Bin (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
  | Tcg.Load _
  | Tcg.Store _
  | Tcg.Call _ ->
      None


(* -------------------------------------------------------------------------- *)
(* Phase-aware recurrence facts                                                *)
(*                                                                            *)
(* [ScalarAddRec] denotes the value at logical loop-iteration entry.  A bare   *)
(* recurrence is therefore not sufficient to describe a value at an arbitrary *)
(* program point: after the physical update, the same IV temp denotes the next *)
(* AddRec value.  The old optimizer handled this independently in several      *)
(* control/reduction matchers.  Keep the semantic layer analysis-only for now, *)
(* but make program point part of the query itself.                             *)
(* -------------------------------------------------------------------------- *)

type recurrence_program_point =
  | RecurrenceBlockEntry of Tcg.label
  | RecurrenceBeforeInstr of Tcg.label * int
  | RecurrenceAfterInstr of Tcg.label * int
  | RecurrenceBlockExit of Tcg.label

type recurrence_phase_state =
  | RecurrencePhaseUnseen
  | RecurrencePhaseKnown of int
  | RecurrencePhaseConflict

type recurrence_def_site = {
  recurrence_def_label : Tcg.label;
  recurrence_def_index : int;
}

type recurrence_facts = {
  recurrence_header : Tcg.label;
  recurrence_loop : LabelSet.t;
  recurrence_get_block : Tcg.label -> Cfg.block;
  recurrence_loop_defs : IntSet.t;
  recurrence_multi_defs : IntSet.t;
  recurrence_invariant_of_operand :
    Tcg.operand -> loop_inv_expr option;
  recurrence_phase_transfer :
    loop_addrec ->
    Cfg.block ->
    recurrence_phase_state ->
    int ->
    recurrence_phase_state;
  recurrence_addrecs : loop_addrec list;
  recurrence_addrec_by_temp : (Tcg.temp, loop_addrec) Hashtbl.t;
  recurrence_unique_def_sites :
    (Tcg.temp, recurrence_def_site) Hashtbl.t;
  recurrence_loop_doms :
    (Tcg.label, LabelSet.t) Hashtbl.t;
  recurrence_entry_phases :
    ((Tcg.temp * Tcg.label), recurrence_phase_state) Hashtbl.t;
}

let scalar_recurrence_equal lhs rhs =
  let lhs = normalize_scalar_recurrence lhs in
  let rhs = normalize_scalar_recurrence rhs in
  match (lhs, rhs) with
  | ScalarConst lhs, ScalarConst rhs ->
      i32 lhs = i32 rhs
  | ScalarInvariant lhs, ScalarInvariant rhs ->
      loop_inv_expr_equal lhs rhs
  | (ScalarAddRec _ | ScalarAffine _),
    (ScalarAddRec _ | ScalarAffine _) -> (
      match
        ( scalar_recurrence_scale_bias lhs,
          scalar_recurrence_scale_bias rhs )
      with
      | Some (lhs_base, lhs_scale, lhs_bias),
        Some (rhs_base, rhs_scale, rhs_bias) ->
          scalar_same_base lhs_base rhs_base
          && loop_inv_expr_equal lhs_scale rhs_scale
          && loop_inv_expr_equal lhs_bias rhs_bias
      | _ -> false)
  | ScalarConst _, ScalarInvariant invariant
  | ScalarInvariant invariant, ScalarConst _ -> (
      match normalize_loop_inv_expr invariant with
      | LveConst _ ->
          normalize_scalar_recurrence lhs =
          normalize_scalar_recurrence rhs
      | LveOperand _
      | LveNeg _
      | LveAdd _
      | LveMul _ ->
          false)
  | (ScalarConst _ | ScalarInvariant _),
    (ScalarAddRec _ | ScalarAffine _)
  | (ScalarAddRec _ | ScalarAffine _),
    (ScalarConst _ | ScalarInvariant _) ->
      false

let scalar_recurrence_shift_addrec (base : loop_addrec) phase =
  if phase = 0 then ScalarAddRec base
  else
    let phase_expr = LveConst (Int64.of_int phase) in
    scalar_recurrence_affine
      base scalar_inv_one
      (normalize_loop_inv_expr
         (LveMul (base.addrec_step, phase_expr)))

let recurrence_phase_state_equal lhs rhs =
  match (lhs, rhs) with
  | RecurrencePhaseUnseen, RecurrencePhaseUnseen
  | RecurrencePhaseConflict, RecurrencePhaseConflict ->
      true
  | RecurrencePhaseKnown lhs, RecurrencePhaseKnown rhs ->
      lhs = rhs
  | RecurrencePhaseUnseen, _
  | RecurrencePhaseConflict, _
  | RecurrencePhaseKnown _, _ ->
      false

let merge_recurrence_phase_state lhs rhs =
  match (lhs, rhs) with
  | RecurrencePhaseConflict, _
  | _, RecurrencePhaseConflict ->
      RecurrencePhaseConflict
  | RecurrencePhaseUnseen, state
  | state, RecurrencePhaseUnseen ->
      state
  | RecurrencePhaseKnown lhs, RecurrencePhaseKnown rhs ->
      if lhs = rhs then RecurrencePhaseKnown lhs
      else RecurrencePhaseConflict

let recurrence_loop_dominators header loop get_block =
  let labels = LabelSet.elements loop in
  let all_labels =
    List.fold_left
      (fun labels label -> LabelSet.add label labels)
      LabelSet.empty labels
  in
  let doms = Hashtbl.create (max 8 (List.length labels)) in
  List.iter
    (fun label ->
      Hashtbl.replace doms label
        (if label = header then LabelSet.singleton header
         else all_labels))
    labels;
  let changed = ref true in
  while !changed do
    changed := false;
    List.iter
      (fun label ->
        if label <> header then
          let block : Cfg.block = get_block label in
          let preds =
            List.filter (fun pred -> LabelSet.mem pred loop) block.preds
          in
          let merged =
            match preds with
            | [] -> LabelSet.empty
            | pred :: rest ->
                List.fold_left
                  (fun acc pred ->
                    LabelSet.inter acc
                      (table_find_or_empty doms pred all_labels))
                  (table_find_or_empty doms pred all_labels)
                  rest
          in
          let next = LabelSet.add label merged in
          let old =
            table_find_or_empty doms label all_labels
          in
          if not (LabelSet.equal old next) then begin
            Hashtbl.replace doms label next;
            changed := true
          end)
      labels
  done;
  doms

let recurrence_unique_def_sites loop get_block multi_defs =
  let sites = Hashtbl.create 32 in
  LabelSet.iter
    (fun label ->
      let block : Cfg.block = get_block label in
      List.iteri
        (fun index instr ->
          match defs_temp instr with
          | Some temp when not (IntSet.mem temp multi_defs) ->
              Hashtbl.replace sites temp
                {
                  recurrence_def_label = label;
                  recurrence_def_index = index;
                }
          | Some _ | None -> ())
        block.body)
    loop;
  sites

let recurrence_local_instr
    loop_defs
    multi_defs
    def_instrs
    addrec
    phase
    env
    instr =
  let analyze_operand = function
    | Tcg.Imm value ->
        Some (ScalarConst value)
    | Tcg.Temp temp ->
        if temp = addrec.addrec_phi_temp then
          Some (scalar_recurrence_shift_addrec addrec phase)
        else
          match Hashtbl.find_opt env temp with
          | Some recurrence -> Some recurrence
          | None ->
              if not (IntSet.mem temp loop_defs) then
                Option.map
                  (fun expr ->
                    normalize_scalar_recurrence
                      (ScalarInvariant expr))
                  (lve_invariant_expr_of_operand
                     loop_defs multi_defs def_instrs
                     (Tcg.Temp temp))
              else
                None
  in
  let with_unary f operand =
    Option.map f (analyze_operand operand)
  in
  let with_binary f lhs rhs =
    Option.bind (analyze_operand lhs) (fun lhs ->
      Option.bind (analyze_operand rhs) (f lhs))
  in
  match instr with
  | Tcg.Move (_, src)
  | Tcg.Un (_, UPlus, src) ->
      analyze_operand src
  | Tcg.Un (_, UMinus, src) ->
      with_unary scalar_recurrence_neg src
  | Tcg.Bin (_, Add, lhs, rhs) ->
      with_binary scalar_recurrence_add lhs rhs
  | Tcg.Bin (_, Sub, lhs, rhs) ->
      with_binary scalar_recurrence_sub lhs rhs
  | Tcg.Bin (_, Mul, lhs, rhs) ->
      with_binary scalar_recurrence_mul lhs rhs
  | Tcg.Un (_, UNot, _)
  | Tcg.Bin
      (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
  | Tcg.Load _
  | Tcg.Store _
  | Tcg.Call _ ->
      None

let recurrence_transfer_phase
    loop_defs multi_defs def_instrs addrec
    (block : Cfg.block) entry_state stop_count =
  match entry_state with
  | RecurrencePhaseUnseen ->
      RecurrencePhaseUnseen
  | RecurrencePhaseConflict ->
      RecurrencePhaseConflict
  | RecurrencePhaseKnown entry_phase ->
      let phase = ref entry_phase in
      let conflict = ref false in
      let env = Hashtbl.create (max 8 (List.length block.body)) in
      let limit =
        min (max 0 stop_count) (List.length block.body)
      in
      block.body
      |> List.iteri (fun index instr ->
             if index < limit && not !conflict then begin
               let recurrence =
                 recurrence_local_instr
                   loop_defs multi_defs def_instrs
                   addrec !phase env instr
               in
               match defs_temp instr with
               | None -> ()
               | Some dst when dst = addrec.addrec_phi_temp -> (
                   let current =
                     scalar_recurrence_shift_addrec addrec !phase
                   in
                   let next =
                     scalar_recurrence_shift_addrec addrec (!phase + 1)
                   in
                   match recurrence with
                   | Some recurrence
                     when scalar_recurrence_equal recurrence current ->
                       ()
                   | Some recurrence
                     when scalar_recurrence_equal recurrence next ->
                       incr phase
                   | Some _ | None ->
                       conflict := true;
                   Hashtbl.remove env dst)
               | Some dst ->
                   begin
                     match recurrence with
                     | Some recurrence ->
                         Hashtbl.replace env dst recurrence
                     | None ->
                         Hashtbl.remove env dst
                   end
             end);
      if !conflict then RecurrencePhaseConflict
      else RecurrencePhaseKnown !phase

let recurrence_build_entry_phases
    header loop get_block loop_defs multi_defs def_instrs addrecs =
  let phases = Hashtbl.create 64 in
  let labels = LabelSet.elements loop in
  List.iter
    (fun (addrec : loop_addrec) ->
      List.iter
        (fun label ->
          Hashtbl.replace phases
            (addrec.addrec_phi_temp, label)
            (if label = header then RecurrencePhaseKnown 0
             else RecurrencePhaseUnseen))
        labels;
      let changed = ref true in
      while !changed do
        changed := false;
        List.iter
          (fun label ->
            if label <> header then begin
              let block : Cfg.block = get_block label in
              let preds =
                List.filter
                  (fun pred -> LabelSet.mem pred loop)
                  block.preds
              in
              let next =
                List.fold_left
                  (fun merged pred ->
                    let pred_block : Cfg.block = get_block pred in
                    let pred_entry =
                      Option.value
                        ~default:RecurrencePhaseUnseen
                        (Hashtbl.find_opt phases
                           (addrec.addrec_phi_temp, pred))
                    in
                    let pred_exit =
                      recurrence_transfer_phase
                        loop_defs multi_defs def_instrs
                        addrec pred_block pred_entry
                        (List.length pred_block.body)
                    in
                    merge_recurrence_phase_state
                      merged pred_exit)
                  RecurrencePhaseUnseen preds
              in
              let key = (addrec.addrec_phi_temp, label) in
              let old =
                Option.value
                  ~default:RecurrencePhaseUnseen
                  (Hashtbl.find_opt phases key)
              in
              if not (recurrence_phase_state_equal old next) then begin
                Hashtbl.replace phases key next;
                changed := true
              end
            end)
          labels
      done)
    addrecs;
  phases

let build_recurrence_facts
    header loop get_block loop_defs multi_defs def_instrs addrecs =
  {
    recurrence_header = header;
    recurrence_loop = loop;
    recurrence_get_block = get_block;
    recurrence_loop_defs = loop_defs;
    recurrence_multi_defs = multi_defs;
    recurrence_invariant_of_operand =
      lve_invariant_expr_of_operand
        loop_defs multi_defs def_instrs;
    recurrence_phase_transfer =
      recurrence_transfer_phase
        loop_defs multi_defs def_instrs;
    recurrence_addrecs = addrecs;
    recurrence_addrec_by_temp = scalar_addrec_table addrecs;
    recurrence_unique_def_sites =
      recurrence_unique_def_sites loop get_block multi_defs;
    recurrence_loop_doms =
      recurrence_loop_dominators header loop get_block;
    recurrence_entry_phases =
      recurrence_build_entry_phases
        header loop get_block loop_defs multi_defs
        def_instrs addrecs;
  }

let recurrence_point_label = function
  | RecurrenceBlockEntry label
  | RecurrenceBeforeInstr (label, _)
  | RecurrenceAfterInstr (label, _)
  | RecurrenceBlockExit label ->
      label

let recurrence_point_visible_count facts = function
  | RecurrenceBlockEntry _ ->
      Some 0
  | RecurrenceBeforeInstr (label, index) ->
      let block : Cfg.block = facts.recurrence_get_block label in
      if index < 0 || index > List.length block.body then None
      else Some index
  | RecurrenceAfterInstr (label, index) ->
      let block : Cfg.block = facts.recurrence_get_block label in
      if index < 0 || index >= List.length block.body then None
      else Some (index + 1)
  | RecurrenceBlockExit label ->
      let block : Cfg.block = facts.recurrence_get_block label in
      Some (List.length block.body)

let recurrence_phase_at facts (addrec : loop_addrec) point =
  let label = recurrence_point_label point in
  match recurrence_point_visible_count facts point with
  | None ->
      RecurrencePhaseConflict
  | Some visible_count ->
      let block : Cfg.block =
        facts.recurrence_get_block label
      in
      let entry =
        Option.value
          ~default:RecurrencePhaseUnseen
          (Hashtbl.find_opt facts.recurrence_entry_phases
             (addrec.addrec_phi_temp, label))
      in
      facts.recurrence_phase_transfer
        addrec block entry visible_count

let recurrence_def_visible_at facts point site =
  let use_label = recurrence_point_label point in
  match recurrence_point_visible_count facts point with
  | None -> false
  | Some visible_count ->
      if site.recurrence_def_label = use_label then
        site.recurrence_def_index < visible_count
      else
        LabelSet.mem site.recurrence_def_label
          (table_find_or_empty
             facts.recurrence_loop_doms
             use_label LabelSet.empty)

let recurrence_at facts point operand =
  let rec analyze seen point operand =
    match operand with
    | Tcg.Imm value ->
        Some (ScalarConst value)
    | Tcg.Temp temp as operand -> (
        match Hashtbl.find_opt facts.recurrence_addrec_by_temp temp with
        | Some addrec -> (
            match recurrence_phase_at facts addrec point with
            | RecurrencePhaseKnown phase ->
                Some
                  (scalar_recurrence_shift_addrec
                     addrec phase)
            | RecurrencePhaseUnseen
            | RecurrencePhaseConflict ->
                None)
        | None ->
            if not (IntSet.mem temp facts.recurrence_loop_defs) then
              Option.map
                (fun expr ->
                  normalize_scalar_recurrence
                    (ScalarInvariant expr))
                (facts.recurrence_invariant_of_operand operand)
            else if
              IntSet.mem temp seen
              || IntSet.mem temp facts.recurrence_multi_defs
            then
              None
            else
              match
                Hashtbl.find_opt
                  facts.recurrence_unique_def_sites temp
              with
              | Some site
                when recurrence_def_visible_at
                       facts point site ->
                  let def_block : Cfg.block =
                    facts.recurrence_get_block
                      site.recurrence_def_label
                  in
                  begin
                    match
                      List.nth_opt def_block.body
                        site.recurrence_def_index
                    with
                    | Some instr ->
                        analyze_instr
                          (IntSet.add temp seen)
                          (RecurrenceBeforeInstr
                             ( site.recurrence_def_label,
                               site.recurrence_def_index ))
                          instr
                    | None ->
                        None
                  end
              | Some _ | None ->
                  None)
  and analyze_instr seen point = function
    | Tcg.Move (_, src)
    | Tcg.Un (_, UPlus, src) ->
        analyze seen point src
    | Tcg.Un (_, UMinus, src) ->
        Option.map scalar_recurrence_neg
          (analyze seen point src)
    | Tcg.Bin (_, Add, lhs, rhs) ->
        Option.bind (analyze seen point lhs) (fun lhs ->
          Option.bind
            (analyze seen point rhs)
            (scalar_recurrence_add lhs))
    | Tcg.Bin (_, Sub, lhs, rhs) ->
        Option.bind (analyze seen point lhs) (fun lhs ->
          Option.bind
            (analyze seen point rhs)
            (scalar_recurrence_sub lhs))
    | Tcg.Bin (_, Mul, lhs, rhs) ->
        Option.bind (analyze seen point lhs) (fun lhs ->
          Option.bind
            (analyze seen point rhs)
            (scalar_recurrence_mul lhs))
    | Tcg.Un (_, UNot, _)
    | Tcg.Bin
        (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
    | Tcg.Load _
    | Tcg.Store _
    | Tcg.Call _ ->
        None
  in
  analyze IntSet.empty point operand
  |> Option.map normalize_scalar_recurrence

let recurrence_invariant_at facts point operand =
  Option.bind
    (recurrence_at facts point operand)
    scalar_recurrence_invariant_expr

let string_of_recurrence_phase_state = function
  | RecurrencePhaseUnseen -> "unseen"
  | RecurrencePhaseKnown phase ->
      Printf.sprintf "%d" phase
  | RecurrencePhaseConflict -> "conflict"

let debug_recurrence_facts facts =
  if Sys.getenv_opt "TOYC_DEBUG_RECURRENCE_AT" <> None then begin
    List.iter
      (fun (addrec : loop_addrec) ->
        LabelSet.iter
          (fun label ->
            let entry =
              recurrence_phase_at facts addrec
                (RecurrenceBlockEntry label)
            in
            let exit =
              recurrence_phase_at facts addrec
                (RecurrenceBlockExit label)
            in
            if
              entry <> RecurrencePhaseUnseen
              || exit <> RecurrencePhaseUnseen
            then
              Printf.eprintf
                "recurrence-phase header=%s phi=t%d block=%s entry=%s exit=%s\n%!"
                facts.recurrence_header
                addrec.addrec_phi_temp label
                (string_of_recurrence_phase_state entry)
                (string_of_recurrence_phase_state exit))
          facts.recurrence_loop)
      facts.recurrence_addrecs;

    LabelSet.iter
      (fun label ->
        let block : Cfg.block =
          facts.recurrence_get_block label
        in
        List.iteri
          (fun index instr ->
            match defs_temp instr with
            | None -> ()
            | Some dst -> (
                match
                  recurrence_at facts
                    (RecurrenceAfterInstr (label, index))
                    (Tcg.Temp dst)
                with
                | Some (ScalarAddRec _ as recurrence)
                | Some (ScalarAffine _ as recurrence) ->
                    Printf.eprintf
                      "recurrence-at-expr header=%s block=%s index=%d temp=t%d recurrence=%s\n%!"
                      facts.recurrence_header label index dst
                      (string_of_scalar_recurrence recurrence)
                | Some (ScalarConst _)
                | Some (ScalarInvariant _)
                | None ->
                    ()))
          block.body;
        let debug_term side operand =
          match
            recurrence_at facts
              (RecurrenceBlockExit label) operand
          with
          | Some (ScalarAddRec _ as recurrence)
          | Some (ScalarAffine _ as recurrence) ->
              Printf.eprintf
                "recurrence-at-control header=%s block=%s side=%s recurrence=%s\n%!"
                facts.recurrence_header label side
                (string_of_scalar_recurrence recurrence)
          | Some (ScalarConst _)
          | Some (ScalarInvariant _)
          | None ->
              ()
        in
        match block.term with
        | Cfg.BranchZero (operand, _, _)
        | Cfg.BranchNonZero (operand, _, _) ->
            debug_term "cond" operand
        | Cfg.BranchCompare (_, lhs, rhs, _, _) ->
            debug_term "lhs" lhs;
            debug_term "rhs" rhs
        | Cfg.Jump _
        | Cfg.Return _ ->
            ())
      facts.recurrence_loop
  end

let rec lve_runtime_scale_of_operand
    loop_defs multi_defs def_instrs phi_temp operand =
  let invariant operand =
    lve_invariant_expr_of_operand loop_defs multi_defs def_instrs operand
  in
  match operand with
  | Tcg.Imm _ -> None
  | Tcg.Temp temp ->
      if temp = phi_temp then Some scalar_inv_one
      else if IntSet.mem temp multi_defs then None
      else
        match Hashtbl.find_opt def_instrs temp with
        | Some (Tcg.Move (_, src))
        | Some (Tcg.Un (_, UPlus, src)) ->
            lve_runtime_scale_of_operand
              loop_defs multi_defs def_instrs phi_temp src
        | Some (Tcg.Un (_, UMinus, src)) ->
            Option.map
              (fun scale -> normalize_loop_inv_expr (LveNeg scale))
              (lve_runtime_scale_of_operand
                 loop_defs multi_defs def_instrs phi_temp src)
        | Some (Tcg.Bin (_, Mul, lhs, rhs)) -> (
            match
              ( lve_runtime_scale_of_operand
                  loop_defs multi_defs def_instrs phi_temp lhs,
                invariant rhs )
            with
            | Some scale, Some factor ->
                Some (normalize_loop_inv_expr (LveMul (scale, factor)))
            | _ -> (
                match
                  ( invariant lhs,
                    lve_runtime_scale_of_operand
                      loop_defs multi_defs def_instrs phi_temp rhs )
                with
                | Some factor, Some scale ->
                    Some (normalize_loop_inv_expr (LveMul (factor, scale)))
                | _ -> None))
        | Some _ | None ->
            None

let scalar_outside_inputs
    header loop get_block (addrec : loop_addrec) =
  let header_block : Cfg.block = get_block header in
  let outside_preds =
    List.filter
      (fun pred -> not (LabelSet.mem pred loop))
      header_block.preds
  in
  let seed_for_pred pred =
    match
      reaching_move_cases_on_edge
        get_block ~stop_label:header ~pred_label:pred
        addrec.addrec_phi_temp
    with
    | None -> None
    | Some cases ->
        let values =
          cases
          |> dedup_reaching_move_cases
          |> List.map (fun case ->
                 resolve_chain_operand
                   case.reaching_chain case.reaching_source)
          |> List.sort_uniq compare
        in
        begin
          match values with
          | [ value ] -> Some (pred, value)
          | [] | _ :: _ :: _ -> None
        end
  in
  let inputs = List.filter_map seed_for_pred outside_preds in
  if List.length inputs = List.length outside_preds then Some inputs
  else None

let recurrence_addrec_start_expr
    (facts : recurrence_facts)
    (addrec : loop_addrec) =
  let expr_of_operand = function
    | Tcg.Imm value ->
        Some (LveConst value)
    | Tcg.Temp _ as operand ->
        facts.recurrence_invariant_of_operand operand
        |> Option.map normalize_loop_inv_expr
  in
  match
    scalar_outside_inputs
      facts.recurrence_header
      facts.recurrence_loop
      facts.recurrence_get_block
      addrec
  with
  | Some ((_, first_operand) :: rest) ->
      Option.bind
        (expr_of_operand first_operand)
        (fun first ->
          let rec agree = function
            | [] ->
                Some first
            | (_, operand) :: tail -> (
                match expr_of_operand operand with
                | Some other
                  when loop_inv_expr_equal first other ->
                    agree tail
                | Some _ | None ->
                    None)
          in
          agree rest)
  | Some []
  | None ->
      None

let basic_iv_of_scalar_addrec
    header loop get_block (addrec : loop_addrec) =
  match loop_inv_expr_const_opt addrec.addrec_step with
  | None -> None
  | Some step -> (
      match scalar_outside_inputs header loop get_block addrec with
      | None -> None
      | Some outside_inputs ->
          Some
            {
              phi_temp = addrec.addrec_phi_temp;
              outside_inputs;
              backedge_preds = addrec.addrec_backedge_preds;
              step;
              origin = `Semantic;
            })


let debug_scalar_recurrence_loop
    header loop get_block loop_defs multi_defs def_instrs addrecs =
  let recurrence_debug =
    Sys.getenv_opt "TOYC_DEBUG_RECURRENCE_AT" <> None
  in
  if recurrence_debug then
    build_recurrence_facts
      header loop get_block loop_defs multi_defs def_instrs addrecs
    |> debug_recurrence_facts;
  if Sys.getenv_opt "TOYC_DEBUG_SCALAR_RECURRENCE" <> None then begin
    List.iter
      (fun (addrec : loop_addrec) ->
        let recurrence = ScalarAddRec addrec in
        let step_kind =
          match loop_inv_expr_const_opt addrec.addrec_step with
          | Some _ -> "constant"
          | None -> "symbolic"
        in
        Printf.eprintf
          "scalar-rec header=%s phi=t%d kind=%s recurrence=%s\n%!"
          header addrec.addrec_phi_temp step_kind
          (string_of_scalar_recurrence recurrence))
      addrecs;

    (* Probe every pure arithmetic destination once.  This is diagnostic only,
       but it verifies that the unified layer really sees i+c / a*i+b rather
       than merely rediscovering PHIs. *)
    LabelSet.iter
      (fun label ->
        let block : Cfg.block = get_block label in
        List.iter
          (fun instr ->
            match defs_temp instr with
            | Some dst -> (
                let recurrence =
                  match
                    scalar_recurrence_of_operand
                      loop_defs multi_defs def_instrs addrecs block
                      (Tcg.Temp dst)
                  with
                  | Some recurrence -> Some recurrence
                  | None ->
                      Option.map snd
                        (scalar_recurrence_of_instr
                           loop_defs multi_defs def_instrs addrecs block
                           instr)
                in
                match recurrence with
                | Some (ScalarAddRec _ as recurrence)
                | Some (ScalarAffine _ as recurrence) ->
                    Printf.eprintf
                      "scalar-expr header=%s block=%s temp=t%d recurrence=%s\n%!"
                      header block.label dst
                      (string_of_scalar_recurrence recurrence)
                | Some (ScalarConst _)
                | Some (ScalarInvariant _)
                | None ->
                    ())
            | None -> ())
          block.body)
      loop
  end


let lve_operand_available_before_preds doms def_blocks multi_defs preds = function
  | Tcg.Imm _ -> true
  | Tcg.Temp temp ->
      if IntSet.mem temp multi_defs then false
      else
        match Hashtbl.find_opt def_blocks temp with
        | None ->
            (* Temps without an explicit defining block are incoming values
               (for example function parameters).  They are available on every
               edge leading into the loop header. *)
            true
        | Some def_label ->
            List.for_all
              (fun pred ->
                LabelSet.mem def_label
                  (table_find_or_empty doms pred LabelSet.empty))
              preds

let lve_expr_available_before_preds doms def_blocks multi_defs preds expr =
  IntSet.for_all
    (fun temp ->
      lve_operand_available_before_preds
        doms def_blocks multi_defs preds (Tcg.Temp temp))
    (loop_inv_expr_temps expr)

let rec emit_loop_inv_expr fresh_temp dst expr =
  let expr = normalize_loop_inv_expr expr in
  let as_operand expr =
    match normalize_loop_inv_expr expr with
    | LveConst value -> ([], Tcg.Imm value)
    | LveOperand operand -> ([], operand)
    | complex ->
        let temp = fresh_temp () in
        (emit_loop_inv_expr fresh_temp temp complex, Tcg.Temp temp)
  in
  match expr with
  | LveConst value -> [ Tcg.Move (dst, Tcg.Imm value) ]
  | LveOperand operand -> [ Tcg.Move (dst, operand) ]
  | LveNeg inner ->
      let prep, operand = as_operand inner in
      prep @ [ simplify_simple_instr (Tcg.Un (dst, UMinus, operand)) ]
  | LveAdd (lhs, rhs) ->
      let lhs_prep, lhs = as_operand lhs in
      let rhs_prep, rhs = as_operand rhs in
      lhs_prep @ rhs_prep
      @ [ simplify_simple_instr (Tcg.Bin (dst, Add, lhs, rhs)) ]
  | LveMul (lhs, rhs) ->
      let lhs_prep, lhs = as_operand lhs in
      let rhs_prep, rhs = as_operand rhs in
      lhs_prep @ rhs_prep
      @ [ simplify_simple_instr (Tcg.Bin (dst, Mul, lhs, rhs)) ]

let lve_affine_candidate
    loop_defs multi_defs def_instrs addrecs (block : Cfg.block)
    (iv : loop_addrec) instr =
  let invariant operand =
    lve_invariant_expr_of_operand loop_defs multi_defs def_instrs operand
  in
  let direct =
    match instr with
    | Tcg.Move (dst, src)
    | Tcg.Un (dst, UPlus, src) -> (
        match
          lve_runtime_scale_of_operand
            loop_defs multi_defs def_instrs iv.addrec_phi_temp src
        with
        | Some scale -> Some (dst, scale, scalar_inv_zero)
        | None -> None)
    | Tcg.Un (dst, UMinus, src) -> (
        match
          lve_runtime_scale_of_operand
            loop_defs multi_defs def_instrs iv.addrec_phi_temp src
        with
        | Some scale ->
            Some
              ( dst,
                normalize_loop_inv_expr (LveNeg scale),
                scalar_inv_zero )
        | None -> None)
    | Tcg.Bin (dst, Mul, lhs, rhs) -> (
        match
          ( lve_runtime_scale_of_operand
              loop_defs multi_defs def_instrs iv.addrec_phi_temp lhs,
            invariant rhs )
        with
        | Some scale, Some factor ->
            Some
              ( dst,
                normalize_loop_inv_expr (LveMul (scale, factor)),
                scalar_inv_zero )
        | _ -> (
            match
              ( invariant lhs,
                lve_runtime_scale_of_operand
                  loop_defs multi_defs def_instrs iv.addrec_phi_temp rhs )
            with
            | Some factor, Some scale ->
                Some
                  ( dst,
                    normalize_loop_inv_expr (LveMul (factor, scale)),
                    scalar_inv_zero )
            | _ -> None))
    | Tcg.Bin (dst, Add, lhs, rhs) -> (
        match
          ( lve_runtime_scale_of_operand
              loop_defs multi_defs def_instrs iv.addrec_phi_temp lhs,
            invariant rhs )
        with
        | Some scale, Some bias ->
            Some (dst, normalize_loop_inv_expr scale, normalize_loop_inv_expr bias)
        | _ -> (
            match
              ( invariant lhs,
                lve_runtime_scale_of_operand
                  loop_defs multi_defs def_instrs iv.addrec_phi_temp rhs )
            with
            | Some bias, Some scale ->
                Some (dst, normalize_loop_inv_expr scale, normalize_loop_inv_expr bias)
            | _ -> None))
    | Tcg.Bin (dst, Sub, lhs, rhs) -> (
        match
          ( lve_runtime_scale_of_operand
              loop_defs multi_defs def_instrs iv.addrec_phi_temp lhs,
            invariant rhs )
        with
        | Some scale, Some bias ->
            Some
              ( dst,
                normalize_loop_inv_expr scale,
                normalize_loop_inv_expr (LveNeg bias) )
        | _ -> (
            match
              ( invariant lhs,
                lve_runtime_scale_of_operand
                  loop_defs multi_defs def_instrs iv.addrec_phi_temp rhs )
            with
            | Some bias, Some scale ->
                Some
                  ( dst,
                    normalize_loop_inv_expr (LveNeg scale),
                    normalize_loop_inv_expr bias )
            | _ -> None))
    | Tcg.Load _
    | Tcg.Store _
    | Tcg.Call _
    | Tcg.Bin (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
    | Tcg.Un (_, UNot, _) ->
        None
  in
  let recurrence =
    match direct with
    | Some (dst, scale, bias) ->
        Some (dst, scalar_recurrence_affine iv scale bias)
    | None ->
        begin
          match
            scalar_recurrence_of_instr
              loop_defs multi_defs def_instrs addrecs block instr
          with
          | Some (dst, recurrence) -> Some (dst, recurrence)
          | None ->
              begin
                match defs_temp instr with
                | None -> None
                | Some dst ->
                    Option.map
                      (fun recurrence -> (dst, recurrence))
                      (scalar_recurrence_of_operand
                         loop_defs multi_defs def_instrs addrecs block
                         (Tcg.Temp dst))
              end
        end
  in
  match recurrence with
  | Some (dst, recurrence) -> (
      match scalar_recurrence_scale_bias recurrence with
      | Some (base, scale, bias) when scalar_same_base base iv ->
          Some
            ( dst,
              normalize_loop_inv_expr scale,
              normalize_loop_inv_expr bias )
      | Some _ | None -> None)
  | None -> None

let lve_nontrivial_affine scale bias =
  let scale = normalize_loop_inv_expr scale in
  let bias = normalize_loop_inv_expr bias in
  not
    (loop_inv_expr_equal scale scalar_inv_one
    && loop_inv_expr_equal bias scalar_inv_zero)

let lve_useful_affine (iv : loop_addrec) scale bias =
  let scale = normalize_loop_inv_expr scale in
  let bias = normalize_loop_inv_expr bias in
  lve_nontrivial_affine scale bias
  &&
  (* Do not build a separate carrier for the trivial "next IV" mirror
     [i + step].  In practice this mostly duplicates the control update and
     can add pressure without removing the real hotspot expression. *)
  not
    (loop_inv_expr_equal scale scalar_inv_one
    && loop_inv_expr_equal bias iv.addrec_step)

type counted_loop_kind =
  | CountUpLt of Tcg.operand * int64
  | CountUpLe of Tcg.operand * int64
  | CountDownGt of Tcg.operand * int64
  | CountDownGe of Tcg.operand * int64
  | CountUpLtScaled of Tcg.operand * int64 * int64
  | CountUpLeScaled of Tcg.operand * int64 * int64
  | CountDownGtScaled of Tcg.operand * int64 * int64
  | CountDownGeScaled of Tcg.operand * int64 * int64

type normalized_limit =
  | LimitConst of int64
  | LimitOperand of Tcg.operand * int64

type counted_loop_info = {
  control_iv : basic_induction_var;
  control_label : Tcg.label;
  inside_label : Tcg.label;
  exit_label : Tcg.label;
  kind : counted_loop_kind;
}

let counted_kind_scale = function
  | CountUpLt (_, _)
  | CountUpLe (_, _)
  | CountDownGt (_, _)
  | CountDownGe (_, _) ->
      1L
  | CountUpLtScaled (_, scale, _)
  | CountUpLeScaled (_, scale, _)
  | CountDownGtScaled (_, scale, _)
  | CountDownGeScaled (_, scale, _) ->
      scale

let counted_kind_bias = function
  | CountUpLt (_, bias)
  | CountUpLe (_, bias)
  | CountDownGt (_, bias)
  | CountDownGe (_, bias) ->
      bias
  | CountUpLtScaled (_, _, bias)
  | CountUpLeScaled (_, _, bias)
  | CountDownGtScaled (_, _, bias)
  | CountDownGeScaled (_, _, bias) ->
      bias

let counted_kind_bound = function
  | CountUpLt (bound, _)
  | CountUpLe (bound, _)
  | CountDownGt (bound, _)
  | CountDownGe (bound, _) ->
      bound
  | CountUpLtScaled (bound, _, _)
  | CountUpLeScaled (bound, _, _)
  | CountDownGtScaled (bound, _, _)
  | CountDownGeScaled (bound, _, _) ->
      bound

let counted_kind_has_unit_scale kind = counted_kind_scale kind = 1L

type summary_expr =
  | SummaryOperand of Tcg.operand
  | SummaryPlace of Tcg.place
  | SummaryUn of unop * summary_expr
  | SummaryBin of binop * summary_expr * summary_expr

(* Counted-summary semantic equality uses the shared canonical scalar key. *)

type counted_reduction_step =
  | ReductionInvariant of summary_expr
  | ReductionAffine of {
      iv : basic_induction_var;
      coeff : summary_expr;
      bias : summary_expr;
    }
  | ReductionQuadratic of {
      iv : basic_induction_var;
      quad : summary_expr;
      triangle : summary_expr;
      coeff : summary_expr;
      bias : summary_expr;
    }
  | ReductionCubic of {
      iv : basic_induction_var;
      choose3 : summary_expr;
      triangle : summary_expr;
      coeff : summary_expr;
      bias : summary_expr;
    }
  | ReductionCarrierProgression of {
      carrier_temp : Tcg.temp;
      step_expr : summary_expr;
      carrier_subtract : bool;
      include_updated : bool;
    }

type counted_reduction_target =
  | ReductionTempTarget of Tcg.temp
  | ReductionPlaceTarget of Tcg.place

type counted_reduction = {
  target : counted_reduction_target;
  subtract : bool;
  step : counted_reduction_step;
  carrier_temp : Tcg.temp option;
  alias_temps : Tcg.temp list;
}

type counted_update =
  | CountedIv of basic_induction_var
  | CountedReduction of counted_reduction

let swap_compare = function
  | Lt -> Gt
  | Le -> Ge
  | Gt -> Lt
  | Ge -> Le
  | Eq -> Eq
  | Ne -> Ne
  | Add | Sub | Mul | Div | Mod | LAnd | LOr -> invalid_arg "swap_compare"

let invert_compare = function
  | Lt -> Ge
  | Le -> Gt
  | Gt -> Le
  | Ge -> Lt
  | Eq -> Ne
  | Ne -> Eq
  | Add | Sub | Mul | Div | Mod | LAnd | LOr -> invalid_arg "invert_compare"

let contains_substring text needle =
  let text_len = String.length text in
  let needle_len = String.length needle in
  let rec loop i =
    if i + needle_len > text_len then false
    else if String.sub text i needle_len = needle then true
    else loop (i + 1)
  in
  needle_len = 0 || loop 0

let is_unroll2_label label = contains_substring label "_unroll2_"
let is_unswitch_label label = contains_substring label "_unswitch_"
let is_rotate_guard_label label = contains_substring label "_rotate_guard_"

type loop_expr_range = {
  min_value : int64 option;
  max_value : int64 option;
}

let iv_bias_of_operand_in_block block multi_defs def_instrs phi_temp operand =
  let rec loop seen = function
    | Tcg.Imm _ -> None
    | Tcg.Temp temp as operand ->
        if
          resolves_to_induction_temp_in_block block multi_defs def_instrs phi_temp operand
          || resolves_to_induction_temp multi_defs def_instrs phi_temp operand
        then Some 0L
        else if IntSet.mem temp seen then None
        else
          match def_instr_in_block_or_global block multi_defs def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) ->
              loop (IntSet.add temp seen) src
          | Some (Tcg.Bin (_, Add, lhs, Tcg.Imm delta)) ->
              Option.map (fun bias -> Int64.add bias delta) (loop (IntSet.add temp seen) lhs)
          | Some (Tcg.Bin (_, Add, Tcg.Imm delta, rhs)) ->
              Option.map (fun bias -> Int64.add bias delta) (loop (IntSet.add temp seen) rhs)
          | Some (Tcg.Bin (_, Sub, lhs, Tcg.Imm delta)) ->
              Option.map (fun bias -> Int64.sub bias delta) (loop (IntSet.add temp seen) lhs)
          | Some _ | None -> None
  in
  loop IntSet.empty operand

let resolve_compare_operand_in_block block multi_defs def_instrs operand =
  let rec loop seen negate = function
    | Tcg.Imm _ -> None
    | Tcg.Temp temp ->
        if IntSet.mem temp seen then None
        else
          match def_instr_in_block_or_global block multi_defs def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) ->
              loop (IntSet.add temp seen) negate src
          | Some (Tcg.Un (_, UNot, src)) ->
              loop (IntSet.add temp seen) (not negate) src
          | Some (Tcg.Bin (_, op, lhs, rhs)) when is_compare_binop op ->
              Some ((if negate then invert_compare op else op), lhs, rhs)
          | Some _ | None -> None
  in
  loop IntSet.empty false operand

let range_of_counted_iv_expr kind expr_bias =
  match kind with
  | CountUpLt (Tcg.Imm bound, control_bias) ->
      {
        min_value = None;
        max_value = Some Int64.(sub (sub bound 1L) control_bias |> add expr_bias);
      }
  | CountUpLe (Tcg.Imm bound, control_bias) ->
      {
        min_value = None;
        max_value = Some Int64.(sub bound control_bias |> add expr_bias);
      }
  | CountDownGt (Tcg.Imm bound, control_bias) ->
      {
        min_value = Some Int64.(add (sub bound control_bias) expr_bias |> add 1L);
        max_value = None;
      }
  | CountDownGe (Tcg.Imm bound, control_bias) ->
      {
        min_value = Some Int64.(sub bound control_bias |> add expr_bias);
        max_value = None;
      }
  | CountUpLtScaled _
  | CountUpLeScaled _
  | CountDownGtScaled _
  | CountDownGeScaled _ ->
      (* Scaled controls are currently not admitted into range-based branch
         folding.  The previous formulas were both mathematically incomplete for
         some signed cases and, more importantly, unsound under ToyC's i32
         wrapping semantics.  Keep the range unknown unless we later add a full
         no-overflow proof. *)
      { min_value = None; max_value = None }
  | CountUpLt _
  | CountUpLe _
  | CountDownGt _
  | CountDownGe _ ->
      { min_value = None; max_value = None }

let compare_truth_from_range op range constant =
  match (range.min_value, range.max_value, op) with
  | _, Some max_value, Lt when max_value < constant -> Some true
  | Some min_value, _, Lt when min_value >= constant -> Some false
  | _, Some max_value, Le when max_value <= constant -> Some true
  | Some min_value, _, Le when min_value > constant -> Some false
  | Some min_value, _, Gt when min_value > constant -> Some true
  | _, Some max_value, Gt when max_value <= constant -> Some false
  | Some min_value, _, Ge when min_value >= constant -> Some true
  | _, Some max_value, Ge when max_value < constant -> Some false
  | Some min_value, Some max_value, Eq when min_value = constant && max_value = constant -> Some true
  | Some min_value, _, Eq when min_value > constant -> Some false
  | _, Some max_value, Eq when max_value < constant -> Some false
  | Some min_value, Some max_value, Ne when min_value = constant && max_value = constant -> Some false
  | Some min_value, _, Ne when min_value > constant -> Some true
  | _, Some max_value, Ne when max_value < constant -> Some true
  | _ -> None

let rewrite_term_labels rename = function
  | Cfg.Jump label -> Cfg.Jump (rename label)
  | Cfg.BranchZero (cond, if_zero, if_nonzero) ->
      Cfg.BranchZero (cond, rename if_zero, rename if_nonzero)
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) ->
      Cfg.BranchNonZero (cond, rename if_nonzero, rename if_zero)
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
      Cfg.BranchCompare (op, lhs, rhs, rename if_true, rename if_false)
  | Cfg.Return _ as term -> term

let rewrite_term rename_label rename_operand = function
  | Cfg.Jump label -> Cfg.Jump (rename_label label)
  | Cfg.BranchZero (cond, if_zero, if_nonzero) ->
      Cfg.BranchZero (rename_operand cond, rename_label if_zero, rename_label if_nonzero)
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) ->
      Cfg.BranchNonZero (rename_operand cond, rename_label if_nonzero, rename_label if_zero)
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
      Cfg.BranchCompare
        (op, rename_operand lhs, rename_operand rhs, rename_label if_true, rename_label if_false)
  | Cfg.Return None -> Cfg.Return None
  | Cfg.Return (Some value) -> Cfg.Return (Some (rename_operand value))

let branch_term_outcomes = function
  | Cfg.BranchZero (_, if_zero, if_nonzero) -> Some (if_zero, if_nonzero)
  | Cfg.BranchNonZero (_, if_nonzero, if_zero) -> Some (if_nonzero, if_zero)
  | Cfg.BranchCompare (_, _, _, if_true, if_false) -> Some (if_true, if_false)
  | Cfg.Jump _ | Cfg.Return _ -> None

let transparent_loop_connector (block : Cfg.block) =
  match block.term with
  | Cfg.Jump _ ->
      List.for_all
        (function
          | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ -> true
          | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> false)
        block.body
      && List.length block.body <= 4
  | Cfg.BranchZero _ | Cfg.BranchNonZero _ | Cfg.BranchCompare _ | Cfg.Return _ -> false

let branch_term_with_targets term if_true if_false =
  match term with
  | Cfg.BranchZero (cond, _, _) -> Cfg.BranchZero (cond, if_true, if_false)
  | Cfg.BranchNonZero (cond, _, _) -> Cfg.BranchNonZero (cond, if_true, if_false)
  | Cfg.BranchCompare (op, lhs, rhs, _, _) ->
      Cfg.BranchCompare (op, lhs, rhs, if_true, if_false)
  | Cfg.Jump _ | Cfg.Return _ -> term

let branch_compare_shape_in_block block multi_defs def_instrs = function
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) -> Some (op, lhs, rhs, if_true, if_false)
  | Cfg.BranchZero (cond, if_zero, if_nonzero) -> (
      match resolve_compare_operand_in_block block multi_defs def_instrs cond with
      | Some (op, lhs, rhs) -> Some (op, lhs, rhs, if_nonzero, if_zero)
      | None -> None)
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) -> (
      match resolve_compare_operand_in_block block multi_defs def_instrs cond with
      | Some (op, lhs, rhs) -> Some (op, lhs, rhs, if_nonzero, if_zero)
      | None -> None)
  | Cfg.Jump _ | Cfg.Return _ -> None

let resolve_operand_before_loop loop_defs multi_defs def_instrs operand =
  let rec resolve seen = function
    | Tcg.Imm _ as operand -> Some operand
    | Tcg.Temp temp as operand ->
        if not (IntSet.mem temp loop_defs) then Some operand
        else if IntSet.mem temp seen || IntSet.mem temp multi_defs then None
        else
          match Hashtbl.find_opt def_instrs temp with
          | Some (Tcg.Move (_, src)) -> resolve (IntSet.add temp seen) src
          | Some _ | None -> None
  in
  resolve IntSet.empty operand

let operand_available_before_loop loop_defs multi_defs def_instrs operand =
  Option.is_some (resolve_operand_before_loop loop_defs multi_defs def_instrs operand)

let rewrite_branch_term_before_loop loop_defs multi_defs def_instrs = function
  | Cfg.BranchZero (cond, if_zero, if_nonzero) -> (
      match resolve_operand_before_loop loop_defs multi_defs def_instrs cond with
      | Some cond -> Some (Cfg.BranchZero (cond, if_zero, if_nonzero))
      | None -> None)
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) -> (
      match resolve_operand_before_loop loop_defs multi_defs def_instrs cond with
      | Some cond -> Some (Cfg.BranchNonZero (cond, if_nonzero, if_zero))
      | None -> None)
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) -> (
      match
        ( resolve_operand_before_loop loop_defs multi_defs def_instrs lhs,
          resolve_operand_before_loop loop_defs multi_defs def_instrs rhs )
      with
      | Some lhs, Some rhs -> Some (Cfg.BranchCompare (op, lhs, rhs, if_true, if_false))
      | _ -> None)
  | Cfg.Jump _ | Cfg.Return _ -> None

let normalize_limit_operand loop_defs multi_defs def_instrs operand delta =
  match operand_static_int64 loop_defs multi_defs def_instrs operand with
  | Some constant -> Some (LimitConst Int64.(add constant delta))
  | None -> (
      match resolve_operand_before_loop loop_defs multi_defs def_instrs operand with
      | Some resolved -> Some (LimitOperand (resolved, delta))
      | None -> None)

type recurrence_control_candidate = {
  recurrence_control_base : loop_addrec;
  recurrence_control_scale : loop_inv_expr;
  recurrence_control_bias : loop_inv_expr;
  recurrence_control_bound_operand : Tcg.operand;
  recurrence_control_bound_expr : loop_inv_expr;
  recurrence_control_op : binop;
  recurrence_control_label : Tcg.label;
  recurrence_control_inside_label : Tcg.label;
  recurrence_control_exit_label : Tcg.label;
}

type symbolic_trip_spec = {
  symbolic_trip_start : loop_inv_expr;
  symbolic_trip_step : loop_inv_expr;
  symbolic_trip_scale : loop_inv_expr;
  symbolic_trip_bias : loop_inv_expr;
  symbolic_trip_bound : loop_inv_expr;
  symbolic_trip_op : binop;
}

let symbolic_trip_spec_of_candidate
    (facts : recurrence_facts)
    (candidate : recurrence_control_candidate) =
  Option.map
    (fun start ->
      {
        symbolic_trip_start =
          normalize_loop_inv_expr start;
        symbolic_trip_step =
          normalize_loop_inv_expr
            candidate.recurrence_control_base.addrec_step;
        symbolic_trip_scale =
          normalize_loop_inv_expr
            candidate.recurrence_control_scale;
        symbolic_trip_bias =
          normalize_loop_inv_expr
            candidate.recurrence_control_bias;
        symbolic_trip_bound =
          normalize_loop_inv_expr
            candidate.recurrence_control_bound_expr;
        symbolic_trip_op =
          candidate.recurrence_control_op;
      })
    (recurrence_addrec_start_expr
       facts candidate.recurrence_control_base)

let symbolic_trip_is_zero_start_lt
    (spec : symbolic_trip_spec) =
  spec.symbolic_trip_op = Lt
  && loop_inv_expr_equal
       spec.symbolic_trip_start
       scalar_inv_zero

let symbolic_trip_control_start
    (spec : symbolic_trip_spec) =
  normalize_loop_inv_expr
    (LveAdd
       ( LveMul
           ( spec.symbolic_trip_scale,
             spec.symbolic_trip_start ),
         spec.symbolic_trip_bias ))

let symbolic_trip_effective_step
    (spec : symbolic_trip_spec) =
  normalize_loop_inv_expr
    (LveMul
       ( spec.symbolic_trip_scale,
         spec.symbolic_trip_step ))

type symbolic_trip_proof_family =
  | SymbolicTripUnitLt
  | SymbolicTripPositiveAffineLt

let classify_symbolic_trip_proof_family
    (spec : symbolic_trip_spec) =
  if spec.symbolic_trip_op <> Lt then
    None
  else if
    symbolic_trip_is_zero_start_lt spec
    && loop_inv_expr_equal
         spec.symbolic_trip_scale scalar_inv_one
    && loop_inv_expr_equal
         spec.symbolic_trip_bias scalar_inv_zero
  then
    Some SymbolicTripUnitLt
  else
    Some SymbolicTripPositiveAffineLt

let string_of_symbolic_trip_proof_family = function
  | SymbolicTripUnitLt ->
      "unit-lt"
  | SymbolicTripPositiveAffineLt ->
      "positive-affine-lt"

(* Static proof for the elimination-only scaled-control path.

   This is deliberately narrower than runtime proof:
     start = 0
     op = <
     scale/step/bias/bound are all constants
     scale > 0, step > 0, bias >= 0
     effective_step = scale*step is positive and <= INT32_MAX
     if the loop enters, the final failing control value is <= INT32_MAX.

   The zero-trip case is still protected by the original loop guard in the
   counted elimination path, so [bound <= bias] is safe without evaluating
   the summary trip expression. *)
let static_positive_affine_lt_proof
    (spec : symbolic_trip_spec) =
  match
    ( loop_inv_expr_const_opt spec.symbolic_trip_start,
      loop_inv_expr_const_opt spec.symbolic_trip_step,
      loop_inv_expr_const_opt spec.symbolic_trip_scale,
      loop_inv_expr_const_opt spec.symbolic_trip_bias,
      loop_inv_expr_const_opt spec.symbolic_trip_bound,
      spec.symbolic_trip_op )
  with
  | Some 0L,
    Some step,
    Some scale,
    Some bias,
    Some bound,
    Lt
    when scale > 0L
         && step > 0L
         && bias >= 0L ->
      let effective_step =
        Int64.mul scale step
      in
      if
        effective_step <= 0L
        || effective_step > 2147483647L
      then
        None
      else if bound <= bias then
        Some 0L
      else
        let delta = Int64.sub bound bias in
        let q = Int64.div delta effective_step in
        let r = Int64.rem delta effective_step in
        let trip =
          if r = 0L then q else Int64.succ q
        in
        let max_trip =
          Int64.div
            (Int64.sub 2147483647L bias)
            effective_step
        in
        if trip <= max_trip then
          Some trip
        else
          None
  | _ ->
      None

let string_of_recurrence_compare = function
  | Lt -> "lt"
  | Le -> "le"
  | Gt -> "gt"
  | Ge -> "ge"
  | Eq -> "eq"
  | Ne -> "ne"
  | Add -> "add"
  | Sub -> "sub"
  | Mul -> "mul"
  | Div -> "div"
  | Mod -> "mod"
  | LAnd -> "land"
  | LOr -> "lor"

let find_recurrence_loop_control_candidate
    (facts : recurrence_facts)
    multi_defs
    def_instrs =
  let loop = facts.recurrence_loop in
  let match_one label varying bound =
    let point = RecurrenceBlockExit label in
    match
      ( recurrence_at facts point varying,
        recurrence_invariant_at facts point bound )
    with
    | Some
        ((ScalarAddRec _ | ScalarAffine _) as recurrence),
      Some bound_expr -> (
        match scalar_recurrence_scale_bias recurrence with
        | Some (base, scale, bias) ->
            Some
              ( base,
                normalize_loop_inv_expr scale,
                normalize_loop_inv_expr bias,
                normalize_loop_inv_expr bound_expr )
        | None ->
            None)
    | _ ->
        None
  in
  LabelSet.elements loop
  |> List.find_map (fun label ->
         let block : Cfg.block =
           facts.recurrence_get_block label
         in
         match
           branch_compare_shape_in_block
             block multi_defs def_instrs block.term
         with
         | Some (op, lhs, rhs, if_true, if_false)
           when
             LabelSet.mem if_true loop
             <> LabelSet.mem if_false loop ->
             let true_in = LabelSet.mem if_true loop in
             let continue_op, inside_label, exit_label =
               if true_in then
                 (op, if_true, if_false)
               else
                 (invert_compare op, if_false, if_true)
             in
             let matched =
               match match_one label lhs rhs with
               | Some (base, scale, bias, bound_expr) ->
                   Some
                     ( base,
                       scale,
                       bias,
                       rhs,
                       bound_expr,
                       continue_op )
               | None -> (
                   match match_one label rhs lhs with
                   | Some (base, scale, bias, bound_expr) ->
                       Some
                         ( base,
                           scale,
                           bias,
                           lhs,
                           bound_expr,
                           swap_compare continue_op )
                   | None ->
                       None)
             in
             Option.map
               (fun
                 ( base,
                   scale,
                   bias,
                   bound_operand,
                   bound_expr,
                   normalized_op ) ->
                 let candidate =
                   {
                     recurrence_control_base = base;
                     recurrence_control_scale = scale;
                     recurrence_control_bias = bias;
                     recurrence_control_bound_operand =
                       bound_operand;
                     recurrence_control_bound_expr =
                       bound_expr;
                     recurrence_control_op = normalized_op;
                     recurrence_control_label = label;
                     recurrence_control_inside_label =
                       inside_label;
                     recurrence_control_exit_label =
                       exit_label;
                   }
                 in
                 if
                   Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED"
                   <> None
                 then
                   Printf.eprintf
                     "scev-control-candidate header=%s control=%s phi=t%d start=%s step=%s scale=%s bias=%s op=%s bound=%s\n%!"
                     facts.recurrence_header
                     label
                     base.addrec_phi_temp
                     (match
                        recurrence_addrec_start_expr facts base
                      with
                      | Some start ->
                          string_of_loop_inv_expr start
                      | None ->
                          "<path-dependent>")
                     (string_of_loop_inv_expr
                        base.addrec_step)
                     (string_of_loop_inv_expr scale)
                     (string_of_loop_inv_expr bias)
                     (string_of_recurrence_compare
                        normalized_op)
                     (string_of_loop_inv_expr
                        bound_expr);
                 candidate)
               matched
         | Some _ | None ->
             None)

let proven_counted_control_of_recurrence_candidate
    header loop get_block facts
    (candidate : recurrence_control_candidate) =
  let build_kind step =
    match (step, candidate.recurrence_control_op) with
    | step, Lt when step > 0L ->
        Some
          (CountUpLt
             ( candidate.recurrence_control_bound_operand,
               0L ))
    | step, Le when step > 0L ->
        Some
          (CountUpLe
             ( candidate.recurrence_control_bound_operand,
               0L ))
    | step, Gt when step < 0L ->
        Some
          (CountDownGt
             ( candidate.recurrence_control_bound_operand,
               0L ))
    | step, Ge when step < 0L ->
        Some
          (CountDownGe
             ( candidate.recurrence_control_bound_operand,
               0L ))
    | _ ->
        None
  in
  match symbolic_trip_spec_of_candidate facts candidate with
  | None ->
      None
  | Some spec -> (
      match
        basic_iv_of_scalar_addrec
          header loop get_block
          candidate.recurrence_control_base
      with
      | None ->
          None
      | Some control_iv -> (
          match
            ( loop_inv_expr_const_opt
                spec.symbolic_trip_scale,
              loop_inv_expr_const_opt
                spec.symbolic_trip_bias )
          with
          | Some 1L, Some 0L ->
              Option.map
                (fun kind ->
                  {
                    control_iv;
                    control_label =
                      candidate.recurrence_control_label;
                    inside_label =
                      candidate.recurrence_control_inside_label;
                    exit_label =
                      candidate.recurrence_control_exit_label;
                    kind;
                  })
                (build_kind control_iv.step)
          | Some scale, Some bias
            when
              candidate.recurrence_control_op = Lt
              && scale > 0L
              && bias >= 0L
              && Option.is_some
                   (static_positive_affine_lt_proof spec) ->
              (match
                 candidate.recurrence_control_bound_operand
               with
               | Tcg.Imm _ ->
                   if
                     Sys.getenv_opt
                       "TOYC_DEBUG_SCEV_UNIFIED"
                     <> None
                   then
                     Printf.eprintf
                       "symbolic-trip-static-proof-hit header=%s family=positive-affine-lt phi=t%d start=%s step=%s scale=%Ld bias=%Ld bound=%s trip=%s\n%!"
                       header
                       control_iv.phi_temp
                       (string_of_loop_inv_expr
                          spec.symbolic_trip_start)
                       (string_of_loop_inv_expr
                          spec.symbolic_trip_step)
                       scale bias
                       (string_of_loop_inv_expr
                          spec.symbolic_trip_bound)
                       (match
                          static_positive_affine_lt_proof
                            spec
                        with
                        | Some trip ->
                            Int64.to_string trip
                        | None ->
                            "<none>");
                   Some
                     {
                       control_iv;
                       control_label =
                         candidate.recurrence_control_label;
                       inside_label =
                         candidate.recurrence_control_inside_label;
                       exit_label =
                         candidate.recurrence_control_exit_label;
                       kind =
                         CountUpLtScaled
                           ( candidate
                               .recurrence_control_bound_operand,
                             scale,
                             bias );
                     }
               | Tcg.Temp _ ->
                   None)
          | Some _, Some _
          | Some _, None
          | None, Some _
          | None, None ->
              None))

let classify_counted_loop_header
    control_label
    loop
    loop_defs
    loop_stable_phis
    multi_defs
    def_instrs
    ivs
    get_block
    (block : Cfg.block)
  =
  let term = block.term in
  let invariant operand =
    operand_loop_invariant
      loop_defs loop_stable_phis multi_defs def_instrs IntSet.empty operand
  in
  let match_known_iv operand =
    List.find_map
      (fun (iv : basic_induction_var) ->
        if
          resolves_to_induction_temp_in_block block multi_defs def_instrs iv.phi_temp operand
          || resolves_to_induction_temp multi_defs def_instrs iv.phi_temp operand
        then Some (iv, 0L)
        else None)
      ivs
  in
  let inloop_preds = List.filter (fun pred -> LabelSet.mem pred loop) block.preds in
  let snapshot_bias_in_block (iv : basic_induction_var) temp (pred_block : Cfg.block) =
    let rec scan trailing_step = function
      | [] -> None
      | instr :: rest ->
          let trailing_step =
            match defs_temp instr with
            | Some dst when dst = iv.phi_temp -> (
                match induction_step_of_instr loop_defs multi_defs def_instrs iv.phi_temp instr with
                | Some step -> Some step
                | None -> trailing_step)
            | Some _ | None -> trailing_step
          in
          match instr with
          | Tcg.Move (dst, src)
          | Tcg.Un (dst, UPlus, src)
            when dst = temp
                 && (resolves_to_induction_temp_in_block pred_block multi_defs def_instrs iv.phi_temp src
                    || resolves_to_induction_temp multi_defs def_instrs iv.phi_temp src) ->
              Some
                (match trailing_step with
                | Some step -> Int64.neg step
                | None -> 0L)
          | Tcg.Bin (dst, Add, lhs, Tcg.Imm delta)
            when dst = temp
                 && (resolves_to_induction_temp_in_block pred_block multi_defs def_instrs iv.phi_temp lhs
                    || resolves_to_induction_temp multi_defs def_instrs iv.phi_temp lhs) ->
              Some
                Int64.(
                  add delta
                    (match trailing_step with
                    | Some step -> neg step
                    | None -> 0L))
          | Tcg.Bin (dst, Add, Tcg.Imm delta, rhs)
            when dst = temp
                 && (resolves_to_induction_temp_in_block pred_block multi_defs def_instrs iv.phi_temp rhs
                    || resolves_to_induction_temp multi_defs def_instrs iv.phi_temp rhs) ->
              Some
                Int64.(
                  add delta
                    (match trailing_step with
                    | Some step -> neg step
                    | None -> 0L))
          | Tcg.Bin (dst, Sub, lhs, Tcg.Imm delta)
            when dst = temp
                 && (resolves_to_induction_temp_in_block pred_block multi_defs def_instrs iv.phi_temp lhs
                    || resolves_to_induction_temp multi_defs def_instrs iv.phi_temp lhs) ->
              Some
                Int64.(
                  sub
                    (match trailing_step with
                    | Some step -> neg step
                    | None -> 0L)
                    delta)
          | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ ->
              scan trailing_step rest
    in
    scan None (List.rev pred_block.body)
  in
  let match_snapshot_iv operand =
    match operand with
    | Tcg.Imm _ -> None
    | Tcg.Temp temp ->
        List.find_map
          (fun (iv : basic_induction_var) ->
            let biases =
              List.filter_map
                (fun pred ->
                  let chain = incoming_update_chain get_block control_label pred in
                  match chain with
                  | pred_block :: _ -> snapshot_bias_in_block iv temp pred_block
                  | [] -> None)
                inloop_preds
            in
            match biases with
            | [] -> None
            | bias :: rest
              when List.length biases = List.length inloop_preds
                   && List.for_all (Int64.equal bias) rest ->
                Some (iv, bias)
            | _ -> None)
          ivs
  in
  (* Prefer an explicit affine relation to a known IV before the older
     move/snapshot recognizers.  This matters for controls such as

         while (i + 1 < n)

     where a unique temporary holding [i + 1] must retain bias [+1].
     Treating that temporary merely as "resolves to the IV" loses the bias and
     overestimates the trip count by one.

     This resolver is deliberately conservative:
     - only unique defs are followed;
     - only Move/UPlus/Add/Sub by an immediate are accepted;
     - the chain must end at an actual IV phi temp;
     - ambiguous matches to multiple IVs are rejected. *)
  let explicit_affine_control_iv operand =
    let bias_for_iv (iv : basic_induction_var) =
      let rec walk seen = function
        | Tcg.Imm _ -> None
        | Tcg.Temp temp ->
            if temp = iv.phi_temp then Some 0L
            else if IntSet.mem temp seen || IntSet.mem temp multi_defs then None
            else
              match Hashtbl.find_opt def_instrs temp with
              | Some (Tcg.Move (_, src))
              | Some (Tcg.Un (_, UPlus, src)) ->
                  walk (IntSet.add temp seen) src
              | Some (Tcg.Bin (_, Add, lhs, Tcg.Imm delta)) ->
                  Option.map
                    (fun bias -> Int64.add bias delta)
                    (walk (IntSet.add temp seen) lhs)
              | Some (Tcg.Bin (_, Add, Tcg.Imm delta, rhs)) ->
                  Option.map
                    (fun bias -> Int64.add bias delta)
                    (walk (IntSet.add temp seen) rhs)
              | Some (Tcg.Bin (_, Sub, lhs, Tcg.Imm delta)) ->
                  Option.map
                    (fun bias -> Int64.sub bias delta)
                    (walk (IntSet.add temp seen) lhs)
              | Some _ | None -> None
      in
      walk IntSet.empty operand
    in
    let matches =
      List.filter_map
        (fun (iv : basic_induction_var) ->
          Option.map (fun bias -> (iv, bias)) (bias_for_iv iv))
        ivs
    in
    match matches with
    | [ match_ ] -> Some match_
    | [] | _ :: _ :: _ -> None
  in
  let rec control_iv_bias_of_operand seen = function
    | Tcg.Imm _ -> None
    | Tcg.Temp temp as operand -> (
        match explicit_affine_control_iv operand with
        | Some match_ -> Some match_
        | None -> (
            match match_known_iv operand with
            | Some match_ -> Some match_
            | None -> (
                match match_snapshot_iv operand with
                | Some match_ -> Some match_
                | None ->
                if IntSet.mem temp seen then None
                else
                  match def_instr_in_block_or_global block multi_defs def_instrs temp with
              | Some (Tcg.Move (_, src))
              | Some (Tcg.Un (_, UPlus, src)) ->
                  control_iv_bias_of_operand (IntSet.add temp seen) src
              | Some (Tcg.Bin (_, Add, lhs, Tcg.Imm delta)) -> (
                  match control_iv_bias_of_operand (IntSet.add temp seen) lhs with
                  | Some (iv, bias) -> Some (iv, Int64.add bias delta)
                  | None -> control_iv_bias_of_operand (IntSet.add temp seen) lhs)
              | Some (Tcg.Bin (_, Add, Tcg.Imm delta, rhs)) -> (
                  match control_iv_bias_of_operand (IntSet.add temp seen) rhs with
                  | Some (iv, bias) -> Some (iv, Int64.add bias delta)
                  | None -> control_iv_bias_of_operand (IntSet.add temp seen) rhs)
               | Some (Tcg.Bin (_, Sub, lhs, Tcg.Imm delta)) -> (
                   match control_iv_bias_of_operand (IntSet.add temp seen) lhs with
                   | Some (iv, bias) -> Some (iv, Int64.sub bias delta)
                   | None -> control_iv_bias_of_operand (IntSet.add temp seen) lhs)
               | Some _ | None -> None)))
  in
  (* step138: phase-aware affine control analysis.

     IMPORTANT: the scalar recurrence attached to a PHI is an iteration-entry
     recurrence.  A use in a split/latch/post-update block can be one or more
     updates later.  Therefore this analysis never uses a bare ScalarAddRec as
     a program-point fact.

     Instead, the existing position-sensitive [control_iv_bias_of_operand] is
     the leaf oracle.  It already accounts for snapshot temporaries and
     trailing IV updates on incoming chains.  Only after a leaf has been
     assigned a phase-correct

         iv + constant_bias

     do we propagate pure arithmetic in THIS control block to discover

         scale * iv + bias

     with loop-invariant scale/bias.

     v1 originally started as diagnostic-only.  We now allow it to feed the
     counted-loop matcher, but only when it collapses back to the mature
     representation:

         iv + constant_bias

     against a loop-invariant bound.  More general symbolic scales/biases are
     still left to the dedicated runtime symbolic summary pass. *)
  let invariant_expr_of_control_operand operand =
    lve_invariant_expr_of_operand
      loop_defs multi_defs def_instrs operand
    |> Option.map normalize_loop_inv_expr
  in
  let affine_add_bias (iv, scale, bias) delta =
    ( iv,
      scale,
      normalize_loop_inv_expr (LveAdd (bias, delta)) )
  in
  let affine_sub_bias (iv, scale, bias) delta =
    ( iv,
      scale,
      normalize_loop_inv_expr (LveAdd (bias, LveNeg delta)) )
  in
  let affine_scale (iv, scale, bias) factor =
    ( iv,
      normalize_loop_inv_expr (LveMul (scale, factor)),
      normalize_loop_inv_expr (LveMul (bias, factor)) )
  in
  let rec phase_affine_control_of_operand seen operand =
    (* First ask the mature matcher.  This is the only place where a
       cross-block/snapshot value is turned into an IV fact. *)
    match control_iv_bias_of_operand IntSet.empty operand with
    | Some (iv, bias) ->
        Some (iv, LveConst 1L, LveConst bias)
    | None -> (
        match operand with
        | Tcg.Imm _ -> None
        | Tcg.Temp temp ->
            if IntSet.mem temp seen || IntSet.mem temp multi_defs then None
            else
              (* Composite affine propagation is deliberately local to the
                 control block.  A nonlocal temp must first be recognized by
                 the phase-aware leaf oracle above. *)
              match last_def_of_temp block temp with
              | None -> None
              | Some instr ->
                  phase_affine_control_of_instr
                    (IntSet.add temp seen) instr)
  and phase_affine_control_of_instr seen = function
    | Tcg.Move (_, src)
    | Tcg.Un (_, UPlus, src) ->
        phase_affine_control_of_operand seen src
    | Tcg.Un (_, UMinus, src) ->
        Option.map
          (fun affine -> affine_scale affine (LveConst (-1L)))
          (phase_affine_control_of_operand seen src)
    | Tcg.Bin (_, Add, lhs, rhs) -> (
        match
          ( phase_affine_control_of_operand seen lhs,
            phase_affine_control_of_operand seen rhs,
            invariant_expr_of_control_operand lhs,
            invariant_expr_of_control_operand rhs )
        with
        | Some affine, None, _, Some invariant
        | None, Some affine, Some invariant, _ ->
            Some (affine_add_bias affine invariant)
        | _ -> None)
    | Tcg.Bin (_, Sub, lhs, rhs) -> (
        match
          ( phase_affine_control_of_operand seen lhs,
            phase_affine_control_of_operand seen rhs,
            invariant_expr_of_control_operand lhs,
            invariant_expr_of_control_operand rhs )
        with
        | Some affine, None, _, Some invariant ->
            Some (affine_sub_bias affine invariant)
        | None, Some affine, Some invariant, _ ->
            (* invariant - (a*iv+b) = (-a)*iv + (invariant-b) *)
            let iv, scale, bias =
              affine_scale affine (LveConst (-1L))
            in
            Some
              ( iv,
                scale,
                normalize_loop_inv_expr
                  (LveAdd (invariant, bias)) )
        | _ -> None)
    | Tcg.Bin (_, Mul, lhs, rhs) -> (
        match
          ( phase_affine_control_of_operand seen lhs,
            phase_affine_control_of_operand seen rhs,
            invariant_expr_of_control_operand lhs,
            invariant_expr_of_control_operand rhs )
        with
        | Some affine, None, _, Some invariant
        | None, Some affine, Some invariant, _ ->
            Some (affine_scale affine invariant)
        | _ -> None)
    | Tcg.Un (_, UNot, _)
    | Tcg.Bin
        (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
    | Tcg.Load _
    | Tcg.Store _
    | Tcg.Call _ ->
        None
  in
  let phase_affine_equal_old
      (iv : basic_induction_var) scale bias
      (old_iv : basic_induction_var) old_bias =
    iv.phi_temp = old_iv.phi_temp
    &&
    match
      ( normalize_loop_inv_expr scale,
        normalize_loop_inv_expr bias )
    with
    | LveConst 1L, LveConst bias_value ->
        i32 bias_value = i32 old_bias
    | _ -> false
  in
  let debug_phase_affine_operand side operand =
    if Sys.getenv_opt "TOYC_DEBUG_PHASE_AFFINE_CONTROL" <> None
       || Sys.getenv_opt "TOYC_DEBUG_PHASE_VALIDATE" <> None
    then
      let fresh =
        phase_affine_control_of_operand IntSet.empty operand
      in
      let old =
        control_iv_bias_of_operand IntSet.empty operand
      in
      match (old, fresh) with
      | None, None -> ()
      | Some (old_iv, old_bias), None ->
          if Sys.getenv_opt "TOYC_DEBUG_PHASE_VALIDATE" <> None then
            Printf.eprintf
              "phase-validate-missing label=%s side=%s old_phi=t%d old_bias=%Ld\n%!"
              control_label side old_iv.phi_temp old_bias
      | Some (old_iv, old_bias),
        Some (iv, scale, bias) ->
          let agrees =
            phase_affine_equal_old
              iv scale bias old_iv old_bias
          in
          if Sys.getenv_opt "TOYC_DEBUG_PHASE_VALIDATE" <> None then
            Printf.eprintf
              "phase-validate-%s label=%s side=%s old_phi=t%d old_bias=%Ld new_phi=t%d scale=%s bias=%s\n%!"
              (if agrees then "agree" else "disagree")
              control_label side
              old_iv.phi_temp old_bias
              iv.phi_temp
              (string_of_loop_inv_expr scale)
              (string_of_loop_inv_expr bias)
          else if Sys.getenv_opt "TOYC_DEBUG_PHASE_AFFINE_CONTROL" <> None then
            Printf.eprintf
              "phase-affine-control label=%s side=%s phi=t%d scale=%s bias=%s old=t%d+%Ld\n%!"
              control_label side iv.phi_temp
              (string_of_loop_inv_expr scale)
              (string_of_loop_inv_expr bias)
              old_iv.phi_temp old_bias
      | None, Some (iv, scale, bias) ->
          if Sys.getenv_opt "TOYC_DEBUG_PHASE_VALIDATE" <> None then
            Printf.eprintf
              "phase-validate-extension label=%s side=%s phi=t%d scale=%s bias=%s\n%!"
              control_label side iv.phi_temp
              (string_of_loop_inv_expr scale)
              (string_of_loop_inv_expr bias)
          else if Sys.getenv_opt "TOYC_DEBUG_PHASE_AFFINE_CONTROL" <> None then
            Printf.eprintf
              "phase-affine-control label=%s side=%s phi=t%d scale=%s bias=%s old=none\n%!"
              control_label side iv.phi_temp
              (string_of_loop_inv_expr scale)
              (string_of_loop_inv_expr bias)
  in
  begin
    match branch_compare_shape_in_block block multi_defs def_instrs term with
    | Some (_, lhs, rhs, _, _) ->
        debug_phase_affine_operand "lhs" lhs;
        debug_phase_affine_operand "rhs" rhs
    | None -> ()
  end;
  let phase_affine_const_control operand =
    match phase_affine_control_of_operand IntSet.empty operand with
    | Some (iv, scale, bias) -> (
        match
          ( loop_inv_expr_const_opt scale,
            loop_inv_expr_const_opt bias )
        with
        | Some scale_value, Some bias_value
          when scale_value > 0L
               && scale_value <= int32_signed_max
               && iv.step <> Int64.min_int ->
            let stride = Int64.abs iv.step in
            if stride <= 0L then None
            else
              let product = Int64.mul scale_value stride in
              if
                product <= 0L
                || product > int32_signed_max
                || Int64.div product stride <> scale_value
              then None
              else Some (iv, scale_value, bias_value)
        | _ -> None)
    | None -> None
  in
  let normalized_control_iv_affine operand =
    match phase_affine_const_control operand with
    | Some match_ -> Some match_
    | None -> (
        match control_iv_bias_of_operand IntSet.empty operand with
        | Some (iv, bias) -> Some (iv, 1L, bias)
        | None -> None)
  in
  let build_counted_kind step op bound scale bias =
    match (step, op, scale) with
    | step, Lt, 1L when step > 0L -> Some (CountUpLt (bound, bias))
    | step, Le, 1L when step > 0L -> Some (CountUpLe (bound, bias))
    | step, Gt, 1L when step < 0L -> Some (CountDownGt (bound, bias))
    | step, Ge, 1L when step < 0L -> Some (CountDownGe (bound, bias))
    | (step, (Lt | Le | Gt | Ge), _)
      when step <> 0L ->
        (* Conservatively keep counted-loop control on the proven unit-scale
           path only.  The temporary scaled variants are not safe under ToyC
           i32 wrapping unless we can prove the controlling expression never
           overflows for the whole loop. *)
        None
    | _ -> None
  in
  let match_control_iv op lhs rhs =
    match (normalized_control_iv_affine lhs, invariant rhs) with
    | Some (iv, scale, bias), true ->
        let step = iv.step in
        if step = 0L then None
        else Option.map (fun kind -> (iv, kind)) (build_counted_kind step op rhs scale bias)
    | _ -> (
        match (normalized_control_iv_affine rhs, invariant lhs) with
        | Some (iv, scale, bias), true ->
            let step = iv.step in
            if step = 0L then None
            else
              Option.map
                (fun kind -> (iv, kind))
                (build_counted_kind step (swap_compare op) lhs scale bias)
        | _ -> None)
  in
  let classify_targets op lhs rhs if_true if_false =
    let true_in = LabelSet.mem if_true loop in
    let false_in = LabelSet.mem if_false loop in
    if true_in = false_in then None
    else if true_in then
      Option.map
        (fun (control_iv, kind) ->
          { control_iv; control_label; inside_label = if_true; exit_label = if_false; kind })
        (match_control_iv op lhs rhs)
    else
      Option.map
        (fun (control_iv, kind) ->
          { control_iv; control_label; inside_label = if_false; exit_label = if_true; kind })
        (match_control_iv (invert_compare op) lhs rhs)
  in
  let rec resolve_compare_operand seen negate = function
    | Tcg.Imm _ -> None
    | Tcg.Temp temp ->
        if IntSet.mem temp seen then None
        else
          match def_instr_in_block_or_global block multi_defs def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) ->
              resolve_compare_operand (IntSet.add temp seen) negate src
          | Some (Tcg.Un (_, UNot, src)) ->
              resolve_compare_operand (IntSet.add temp seen) (not negate) src
          | Some (Tcg.Bin (_, op, lhs, rhs)) when is_compare_binop op ->
              Some ((if negate then invert_compare op else op), lhs, rhs)
          | Some _ | None -> None
  in
  match term with
  | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
      classify_targets op lhs rhs if_true if_false
  | Cfg.BranchZero (cond, if_zero, if_nonzero) -> (
      match resolve_compare_operand IntSet.empty false cond with
      | Some (op, lhs, rhs) -> classify_targets op lhs rhs if_nonzero if_zero
      | None -> None)
  | Cfg.BranchNonZero (cond, if_nonzero, if_zero) -> (
      match resolve_compare_operand IntSet.empty false cond with
      | Some (op, lhs, rhs) -> classify_targets op lhs rhs if_nonzero if_zero
      | None -> None)
  | Cfg.Jump _ | Cfg.Return _ -> None

let find_counted_loop_control
    loop
    loop_defs
    loop_stable_phis
    multi_defs
    def_instrs
    ivs
    get_block
  =
  LabelSet.elements loop
  |> List.find_map (fun label ->
         let block : Cfg.block = get_block label in
         match branch_term_outcomes block.term with
         | Some (a, b) when LabelSet.mem a loop <> LabelSet.mem b loop ->
              classify_counted_loop_header
                label
                loop
                loop_defs
                loop_stable_phis
                multi_defs
                def_instrs
                 ivs
                 get_block
                 block
          | Some _ | None -> None)

let merge_basic_induction_vars
    (primary : basic_induction_var list)
    (secondary : basic_induction_var list) =
  let seen =
    List.fold_left
      (fun seen (iv : basic_induction_var) -> IntSet.add iv.phi_temp seen)
      IntSet.empty primary
  in
  let extra =
    List.filter
      (fun (iv : basic_induction_var) -> not (IntSet.mem iv.phi_temp seen))
      secondary
  in
  primary @ extra

let proven_syntactic_induction_vars (ivs : basic_induction_var list) =
  List.filter (fun (iv : basic_induction_var) -> iv.origin = `Syntactic) ivs

type loop_recurrence_analysis = {
  loop_recurrence_syntactic_ivs : basic_induction_var list;
  loop_recurrence_semantic_ivs : basic_induction_var list;
  loop_recurrence_all_ivs : basic_induction_var list;
  loop_recurrence_addrecs : loop_addrec list;
  loop_recurrence_facts : recurrence_facts;
}

let induction_recurrence_views
    header loop get_block loop_defs multi_defs def_instrs =
  let syntactic =
    collect_basic_induction_vars
      header loop get_block loop_defs multi_defs def_instrs
  in
  let addrecs =
    analyze_loop_addrecs
      header loop get_block loop_defs multi_defs def_instrs
  in
  debug_scalar_recurrence_loop
    header loop get_block
    loop_defs multi_defs def_instrs addrecs;
  let semantic =
    addrecs
    |> List.filter_map
         (basic_iv_of_scalar_addrec
            header loop get_block)
  in
  let merged =
    merge_basic_induction_vars syntactic semantic
  in
  if
    Sys.getenv_opt "TOYC_DEBUG_SCALAR_RECURRENCE"
    <> None
  then begin
    let semantic_new =
      List.filter
        (fun (iv : basic_induction_var) ->
          iv.origin = `Semantic
          && not
               (List.exists
                  (fun (old : basic_induction_var) ->
                    old.phi_temp = iv.phi_temp)
                  syntactic))
        merged
    in
    Printf.eprintf
      "scalar-iv-compare header=%s old=%d semantic=%d merged=%d new=%d\n%!"
      header
      (List.length syntactic)
      (List.length semantic)
      (List.length merged)
      (List.length semantic_new);
    List.iter
      (fun (iv : basic_induction_var) ->
        Printf.eprintf
          "scalar-iv-new header=%s phi=t%d step=%Ld outside=%d backedges=%d origin=%s\n%!"
          header
          iv.phi_temp
          iv.step
          (List.length iv.outside_inputs)
          (List.length iv.backedge_preds)
          (string_of_basic_iv_origin iv.origin))
      semantic_new
  end;
  (syntactic, semantic, merged, addrecs)

let build_loop_recurrence_analysis
    header loop get_block
    loop_defs multi_defs def_instrs =
  let syntactic, semantic, merged, addrecs =
    induction_recurrence_views
      header loop get_block
      loop_defs multi_defs def_instrs
  in
  let facts =
    build_recurrence_facts
      header loop get_block
      loop_defs multi_defs def_instrs addrecs
  in
  if Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED" <> None then begin
    Printf.eprintf
      "scev-loop-analysis header=%s syntactic=%d semantic=%d addrecs=%d defs=%d multidefs=%d\n%!"
      header
      (List.length syntactic)
      (List.length semantic)
      (List.length addrecs)
      (IntSet.cardinal loop_defs)
      (IntSet.cardinal multi_defs);
    List.iter
      (fun (addrec : loop_addrec) ->
        Printf.eprintf
          "scev-addrec header=%s phi=t%d start=%s step=%s\n%!"
          header
          addrec.addrec_phi_temp
          (match recurrence_addrec_start_expr facts addrec with
           | Some start ->
               string_of_loop_inv_expr start
           | None ->
               "<path-dependent>")
          (string_of_loop_inv_expr addrec.addrec_step))
      addrecs
  end;
  {
    loop_recurrence_syntactic_ivs = syntactic;
    loop_recurrence_semantic_ivs = semantic;
    loop_recurrence_all_ivs = merged;
    loop_recurrence_addrecs = addrecs;
    loop_recurrence_facts = facts;
  }

let analyze_induction_vars
    header loop get_block loop_defs multi_defs def_instrs =
  let analysis =
    build_loop_recurrence_analysis
      header loop get_block
      loop_defs multi_defs def_instrs
  in
  analysis.loop_recurrence_all_ivs

let analyze_counted_control header loop get_block loop_defs loop_stable_phis multi_defs def_instrs =
  let ivs =
    analyze_induction_vars header loop get_block loop_defs multi_defs def_instrs
    |> proven_syntactic_induction_vars
  in
  ( ivs,
    find_counted_loop_control
      loop loop_defs loop_stable_phis multi_defs def_instrs ivs get_block )

let analyze_counted_loop
    header loop get_block temp_count blocks =
  let loop_defs, def_blocks, def_instrs, multi_defs =
    analyze_temp_defs_of_blocks
      ~loop temp_count blocks
  in
  let loop_stable_phis =
    collect_loop_stable_phis
      header loop get_block
      def_blocks multi_defs def_instrs
  in
  let recurrence_analysis =
    build_loop_recurrence_analysis
      header loop get_block
      loop_defs multi_defs def_instrs
  in
  let ivs =
    recurrence_analysis.loop_recurrence_syntactic_ivs
  in
  let control =
    find_counted_loop_control
      loop loop_defs loop_stable_phis
      multi_defs def_instrs ivs get_block
  in
  ( loop_defs,
    def_blocks,
    def_instrs,
    multi_defs,
    loop_stable_phis,
    ivs,
    control )

(* Elimination-only semantic control fallback.

   Mature counted-loop clients continue to use [analyze_counted_loop], whose IV
   list is syntactic-only for control purposes.  Nested elimination sometimes
   loses the physical edge-copy shape after an inner summary even though
   [analyze_loop_addrecs] can still recover the logical outer IV.

   For elimination only, when the mature control matcher fails:
     - query the control operands at the actual block-exit program point;
     - require a single AddRec/Affine with constant step;
     - require unit scale and constant bias;
     - require the opposite operand to be loop-invariant.

   The recovered semantic IV is kept only in [counted_loop_info.control_iv].
   It is NOT inserted into the reduction IV list. *)
let find_counted_loop_control_semantic
    header loop get_block
    multi_defs def_instrs
    facts =
  Option.bind
    (find_recurrence_loop_control_candidate
       facts multi_defs def_instrs)
    (proven_counted_control_of_recurrence_candidate
       header loop get_block facts)

let analyze_counted_loop_for_elimination
    header loop get_block temp_count blocks =
  let loop_defs, def_blocks, def_instrs, multi_defs =
    analyze_temp_defs_of_blocks
      ~loop temp_count blocks
  in
  let loop_stable_phis =
    collect_loop_stable_phis
      header loop get_block
      def_blocks multi_defs def_instrs
  in
  let recurrence_analysis =
    build_loop_recurrence_analysis
      header loop get_block
      loop_defs multi_defs def_instrs
  in
  let syntactic_ivs =
    recurrence_analysis.loop_recurrence_syntactic_ivs
  in
  let old_control =
    find_counted_loop_control
      loop loop_defs loop_stable_phis
      multi_defs def_instrs
      syntactic_ivs get_block
  in
  let control =
    match old_control with
    | Some _ ->
        old_control
    | None ->
        find_counted_loop_control_semantic
          header loop get_block
          multi_defs def_instrs
          recurrence_analysis.loop_recurrence_facts
  in
  (match control with
   | Some info
     when info.control_iv.origin = `Semantic
          && Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None ->
       Printf.eprintf
         "counted-semantic-control-hit header=%s phi=t%d step=%Ld\n%!"
         header info.control_iv.phi_temp info.control_iv.step
   | Some _
   | None ->
       ());
  ( loop_defs,
    def_blocks,
    def_instrs,
    multi_defs,
    loop_stable_phis,
    syntactic_ivs,
    control,
    recurrence_analysis.loop_recurrence_facts )

let linear_loop_path header loop get_block entry_label =
  let rec collapse_transparent_branch seen visiting label =
    if label = header || LabelSet.mem label seen then Some header
    else if LabelSet.mem label visiting || not (LabelSet.mem label loop) then None
    else
      let block : Cfg.block = get_block label in
      match block.term with
      | Cfg.Jump next when block.body = [] ->
          collapse_transparent_branch seen (LabelSet.add label visiting) next
      | _ -> None
  in
  let rec equivalent_linear_branch_path seen_pairs a b =
    if a = b then Some ([], LabelSet.empty, a)
    else if List.mem (a, b) seen_pairs || List.mem (b, a) seen_pairs then None
    else if not (LabelSet.mem a loop) || not (LabelSet.mem b loop) then None
    else
      let a_block : Cfg.block = get_block a in
      let b_block : Cfg.block = get_block b in
      if a_block.body <> b_block.body then None
      else
        match (a_block.term, b_block.term) with
        | Cfg.Jump next_a, Cfg.Jump next_b ->
            if next_a = next_b then
              Some ([ a_block ], LabelSet.of_list [ a; b ], next_a)
            else
              Option.map
                (fun (rep_path, seen_labels, next) ->
                  (a_block :: rep_path, LabelSet.add a (LabelSet.add b seen_labels), next))
                (equivalent_linear_branch_path ((a, b) :: seen_pairs) next_a next_b)
        | _ -> None
  in
  let rec walk seen acc label =
    if label = header then Some (List.rev acc, seen)
    else if not (LabelSet.mem label loop) || LabelSet.mem label seen then None
    else
      let block : Cfg.block = get_block label in
      match block.succs with
      | [ next ] -> walk (LabelSet.add label seen) (block :: acc) next
      | _ -> (
          match branch_term_outcomes block.term with
          | Some (a, b) -> (
              match equivalent_linear_branch_path [] a b with
              | Some (rep_path, branch_seen, next) ->
                  walk
                    (LabelSet.union (LabelSet.add label seen) branch_seen)
                    (List.rev_append rep_path acc)
                    next
              | None -> (
                  match block.body with
                  | [] -> (
                      match
                        ( collapse_transparent_branch seen (LabelSet.add label LabelSet.empty) a,
                          collapse_transparent_branch seen (LabelSet.add label LabelSet.empty) b )
                      with
                      | Some next_a, Some next_b when next_a = next_b ->
                          walk (LabelSet.add label seen) acc next_a
                      | _ -> None)
                  | _ -> None))
          | None -> None)
  in
  let rec transparent_connector_reaches seen visiting label =
    if label = header || LabelSet.mem label seen then true
    else if LabelSet.mem label visiting || not (LabelSet.mem label loop) then false
    else
      let block : Cfg.block = get_block label in
      match (block.body, block.term) with
      | [], Cfg.Jump next -> transparent_connector_reaches seen (LabelSet.add label visiting) next
      | _ -> false
  in
  match walk LabelSet.empty [] entry_label with
  | Some (path, seen) ->
      let leftovers = LabelSet.diff (LabelSet.remove header loop) seen in
      if
        LabelSet.is_empty leftovers
        || LabelSet.for_all (transparent_connector_reaches seen LabelSet.empty) leftovers
      then Some path
      else None
  | None -> None

let counted_loop_shape_supported header loop get_block entry_label =
  let rec collapse_empty_successor seen label =
    if label = header then Some header
    else if LabelSet.mem label seen || not (LabelSet.mem label loop) then None
    else
      let block : Cfg.block = get_block label in
      match (block.body, block.term) with
      | _, Cfg.Jump next when transparent_loop_connector block ->
          collapse_empty_successor (LabelSet.add label seen) next
      | [], _ -> (
          match branch_term_outcomes block.term with
          | Some (a, b) -> (
              match
                ( collapse_empty_successor (LabelSet.add label seen) a,
                  collapse_empty_successor (LabelSet.add label seen) b )
              with
              | Some next_a, Some next_b when next_a = next_b -> Some next_a
              | _ -> None)
          | None -> Some label)
      | _ -> Some label
  in
  let rec equivalent_linear_branches seen_pairs a b =
    if a = b then Some (LabelSet.empty, a)
    else if List.mem (a, b) seen_pairs || List.mem (b, a) seen_pairs then None
    else if not (LabelSet.mem a loop) || not (LabelSet.mem b loop) then None
    else
      let a_block : Cfg.block = get_block a in
      let b_block : Cfg.block = get_block b in
      if a_block.body <> b_block.body then None
      else
        match (a_block.term, b_block.term) with
        | Cfg.Jump next_a, Cfg.Jump next_b ->
            if next_a = next_b then
              Some (LabelSet.of_list [ a; b ], next_a)
            else
              Option.map
                (fun (seen_labels, next) ->
                  (LabelSet.add a (LabelSet.add b seen_labels), next))
                (equivalent_linear_branches ((a, b) :: seen_pairs) next_a next_b)
        | _ -> None
  in
  let rec walk seen label =
    if label = header then true
    else if LabelSet.mem label seen || not (LabelSet.mem label loop) then false
    else
      let seen = LabelSet.add label seen in
      let block : Cfg.block = get_block label in
      match block.succs with
      | [ next ] -> walk seen next
      | _ -> (
          match branch_term_outcomes block.term with
          | Some (a, b)
            when LabelSet.mem a loop && LabelSet.mem b loop -> (
              match equivalent_linear_branches [] a b with
              | Some (branch_seen, next) ->
                  let seen = LabelSet.union seen branch_seen in
                  walk seen next
              | None -> (
                  match
                    ( collapse_empty_successor seen a,
                      collapse_empty_successor seen b )
                  with
                  | Some next_a, Some next_b when next_a = next_b -> walk seen next_a
                  | _ -> false))
          | Some (a, b) when block.body = [] -> (
              match
                ( collapse_empty_successor seen a,
                  collapse_empty_successor seen b )
              with
              | Some next_a, Some next_b when next_a = next_b -> walk seen next_a
              | _ -> false)
          | Some _ | None -> false)
  in
  walk LabelSet.empty entry_label

let clamp_nonnegative_temp fresh_temp temp =
  let keep = fresh_temp () in
  let clamped = fresh_temp () in
  ( [ simplify_simple_instr (Tcg.Bin (keep, Ge, Tcg.Temp temp, Tcg.Imm 0L));
      simplify_simple_instr (Tcg.Bin (clamped, Mul, Tcg.Temp temp, Tcg.Temp keep)) ],
    clamped )

let build_floor_div fresh_temp numer_temp divisor =
  if divisor = 1L then ([], numer_temp)
  else
    let quotient = fresh_temp () in
    let remainder = fresh_temp () in
    let numer_neg = fresh_temp () in
    let rem_nz = fresh_temp () in
    let adjust = fresh_temp () in
    let floor = fresh_temp () in
    ( [ simplify_simple_instr
          (Tcg.Bin (quotient, Div, Tcg.Temp numer_temp, Tcg.Imm divisor));
        simplify_simple_instr
          (Tcg.Bin (remainder, Mod, Tcg.Temp numer_temp, Tcg.Imm divisor));
        simplify_simple_instr (Tcg.Bin (numer_neg, Lt, Tcg.Temp numer_temp, Tcg.Imm 0L));
        simplify_simple_instr (Tcg.Bin (rem_nz, Ne, Tcg.Temp remainder, Tcg.Imm 0L));
        simplify_simple_instr (Tcg.Bin (adjust, Mul, Tcg.Temp numer_neg, Tcg.Temp rem_nz));
        simplify_simple_instr (Tcg.Bin (floor, Sub, Tcg.Temp quotient, Tcg.Temp adjust)) ],
      floor )

let build_nonnegative_ceil_div fresh_temp numer_temp divisor =
  if divisor = 1L then clamp_nonnegative_temp fresh_temp numer_temp
  else
    let quotient = fresh_temp () in
    let remainder = fresh_temp () in
    let numer_pos = fresh_temp () in
    let rem_nz = fresh_temp () in
    let extra = fresh_temp () in
    let raw = fresh_temp () in
    let clamp_instrs, trip = clamp_nonnegative_temp fresh_temp raw in
    ( [ simplify_simple_instr
          (Tcg.Bin (quotient, Div, Tcg.Temp numer_temp, Tcg.Imm divisor));
        simplify_simple_instr
          (Tcg.Bin (remainder, Mod, Tcg.Temp numer_temp, Tcg.Imm divisor));
        simplify_simple_instr (Tcg.Bin (numer_pos, Gt, Tcg.Temp numer_temp, Tcg.Imm 0L));
        simplify_simple_instr (Tcg.Bin (rem_nz, Ne, Tcg.Temp remainder, Tcg.Imm 0L));
        simplify_simple_instr (Tcg.Bin (extra, Mul, Tcg.Temp numer_pos, Tcg.Temp rem_nz));
        simplify_simple_instr (Tcg.Bin (raw, Add, Tcg.Temp quotient, Tcg.Temp extra)) ]
      @ clamp_instrs,
      trip )

let build_nonnegative_inclusive_div fresh_temp numer_temp divisor =
  let floor_instrs, floor = build_floor_div fresh_temp numer_temp divisor in
  let raw = fresh_temp () in
  let clamp_instrs, trip = clamp_nonnegative_temp fresh_temp raw in
  ( floor_instrs
    @ [ simplify_simple_instr (Tcg.Bin (raw, Add, Tcg.Temp floor, Tcg.Imm 1L)) ]
    @ clamp_instrs,
    trip )

let build_trip_count_instrs fresh_temp phi_temp step kind =
  let adjust_bound bound bias =
    if bias = 0L then ([], bound)
    else
      match bound with
      | Tcg.Imm value -> ([], Tcg.Imm Int64.(sub value bias))
      | _ ->
          let adjusted = fresh_temp () in
          ([ simplify_simple_instr (Tcg.Bin (adjusted, Sub, bound, Tcg.Imm bias)) ], Tcg.Temp adjusted)
  in
  let scale_phi scale =
    if scale = 1L then ([], Tcg.Temp phi_temp)
    else
      let scaled = fresh_temp () in
      ( [ simplify_simple_instr
            (Tcg.Bin (scaled, Mul, Tcg.Temp phi_temp, Tcg.Imm scale)) ],
        Tcg.Temp scaled )
  in
  let stride = if step < 0L then Int64.neg step else step in
  let diff = fresh_temp () in
  match kind with
  | CountUpLt (bound, bias) ->
      let bound_instrs, bound = adjust_bound bound bias in
      let diff_instr = simplify_simple_instr (Tcg.Bin (diff, Sub, bound, Tcg.Temp phi_temp)) in
      let trip_instrs, trip = build_nonnegative_ceil_div fresh_temp diff stride in
      (bound_instrs @ (diff_instr :: trip_instrs), trip)
  | CountUpLe (bound, bias) ->
      let bound_instrs, bound = adjust_bound bound bias in
      let diff_instr = simplify_simple_instr (Tcg.Bin (diff, Sub, bound, Tcg.Temp phi_temp)) in
      let trip_instrs, trip = build_nonnegative_inclusive_div fresh_temp diff stride in
      (bound_instrs @ (diff_instr :: trip_instrs), trip)
  | CountDownGt (bound, bias) ->
      let bound_instrs, bound = adjust_bound bound bias in
      let diff_instr = simplify_simple_instr (Tcg.Bin (diff, Sub, Tcg.Temp phi_temp, bound)) in
      let trip_instrs, trip = build_nonnegative_ceil_div fresh_temp diff stride in
      (bound_instrs @ (diff_instr :: trip_instrs), trip)
  | CountDownGe (bound, bias) ->
      let bound_instrs, bound = adjust_bound bound bias in
      let diff_instr = simplify_simple_instr (Tcg.Bin (diff, Sub, Tcg.Temp phi_temp, bound)) in
      let trip_instrs, trip = build_nonnegative_inclusive_div fresh_temp diff stride in
      (bound_instrs @ (diff_instr :: trip_instrs), trip)
  | CountUpLtScaled (bound, scale, bias) ->
      let bound_instrs, bound = adjust_bound bound bias in
      let phi_instrs, scaled_phi = scale_phi scale in
      let diff_instr = simplify_simple_instr (Tcg.Bin (diff, Sub, bound, scaled_phi)) in
      let divisor = Int64.mul scale stride in
      let trip_instrs, trip = build_nonnegative_ceil_div fresh_temp diff divisor in
      (bound_instrs @ phi_instrs @ (diff_instr :: trip_instrs), trip)
  | CountUpLeScaled (bound, scale, bias) ->
      let bound_instrs, bound = adjust_bound bound bias in
      let phi_instrs, scaled_phi = scale_phi scale in
      let diff_instr = simplify_simple_instr (Tcg.Bin (diff, Sub, bound, scaled_phi)) in
      let divisor = Int64.mul scale stride in
      let trip_instrs, trip = build_nonnegative_inclusive_div fresh_temp diff divisor in
      (bound_instrs @ phi_instrs @ (diff_instr :: trip_instrs), trip)
  | CountDownGtScaled (bound, scale, bias) ->
      let bound_instrs, bound = adjust_bound bound bias in
      let phi_instrs, scaled_phi = scale_phi scale in
      let diff_instr = simplify_simple_instr (Tcg.Bin (diff, Sub, scaled_phi, bound)) in
      let divisor = Int64.mul scale stride in
      let trip_instrs, trip = build_nonnegative_ceil_div fresh_temp diff divisor in
      (bound_instrs @ phi_instrs @ (diff_instr :: trip_instrs), trip)
  | CountDownGeScaled (bound, scale, bias) ->
      let bound_instrs, bound = adjust_bound bound bias in
      let phi_instrs, scaled_phi = scale_phi scale in
      let diff_instr = simplify_simple_instr (Tcg.Bin (diff, Sub, scaled_phi, bound)) in
      let divisor = Int64.mul scale stride in
      let trip_instrs, trip = build_nonnegative_inclusive_div fresh_temp diff divisor in
      (bound_instrs @ phi_instrs @ (diff_instr :: trip_instrs), trip)

let int64_floor_div numer denom =
  let quotient = Int64.div numer denom in
  let remainder = Int64.rem numer denom in
  if numer < 0L && remainder <> 0L then Int64.pred quotient else quotient

let int64_nonnegative_ceil_div numer denom =
  if denom <= 0L then None
  else if numer <= 0L then Some 0L
  else
    let quotient = Int64.div numer denom in
    let remainder = Int64.rem numer denom in
    Some (if remainder = 0L then quotient else Int64.succ quotient)

let int64_nonnegative_inclusive_div numer denom =
  if denom <= 0L then None
  else
    let floor = int64_floor_div numer denom in
    Some (if floor < 0L then 0L else Int64.succ floor)

let exact_trip_count_of_symbolic_spec
    (spec : symbolic_trip_spec) =
  static_positive_affine_lt_proof spec

let constant_trip_count_of_kind resolve_operand init_value step = function
  | CountUpLt (bound, bias) -> (
      match resolve_operand bound with
      | Some bound ->
          int64_nonnegative_ceil_div Int64.(sub (sub bound bias) init_value) step
      | None -> None)
  | CountUpLe (bound, bias) -> (
      match resolve_operand bound with
      | Some bound ->
          int64_nonnegative_inclusive_div Int64.(sub (sub bound bias) init_value) step
      | None -> None)
  | CountDownGt (bound, bias) -> (
      match resolve_operand bound with
      | Some bound ->
          int64_nonnegative_ceil_div Int64.(sub init_value (sub bound bias)) (Int64.neg step)
      | None -> None)
  | CountDownGe (bound, bias) -> (
      match resolve_operand bound with
      | Some bound ->
          int64_nonnegative_inclusive_div Int64.(sub init_value (sub bound bias)) (Int64.neg step)
      | None -> None)
  | CountUpLtScaled (bound, scale, bias) -> (
      match resolve_operand bound with
      | Some bound ->
          int64_nonnegative_ceil_div
            Int64.(sub (sub bound bias) (mul scale init_value))
            Int64.(mul scale step)
      | None -> None)
  | CountUpLeScaled (bound, scale, bias) -> (
      match resolve_operand bound with
      | Some bound ->
          int64_nonnegative_inclusive_div
            Int64.(sub (sub bound bias) (mul scale init_value))
            Int64.(mul scale step)
      | None -> None)
  | CountDownGtScaled (bound, scale, bias) -> (
      match resolve_operand bound with
      | Some bound ->
          int64_nonnegative_ceil_div
            Int64.(sub (sub (mul scale init_value) bound) (neg bias))
            Int64.(mul scale (neg step))
      | None -> None)
  | CountDownGeScaled (bound, scale, bias) -> (
      match resolve_operand bound with
      | Some bound ->
          int64_nonnegative_inclusive_div
            Int64.(sub (sub (mul scale init_value) bound) (neg bias))
            Int64.(mul scale (neg step))
      | None -> None)

let build_iv_final_update fresh_temp trip_temp (iv : basic_induction_var) =
  match iv.step with
  | 0L -> []
  | 1L -> [ simplify_simple_instr (Tcg.Bin (iv.phi_temp, Add, Tcg.Temp iv.phi_temp, Tcg.Temp trip_temp)) ]
  | -1L -> [ simplify_simple_instr (Tcg.Bin (iv.phi_temp, Sub, Tcg.Temp iv.phi_temp, Tcg.Temp trip_temp)) ]
  | step ->
      let delta = fresh_temp () in
      [ simplify_simple_instr (Tcg.Bin (delta, Mul, Tcg.Temp trip_temp, Tcg.Imm step));
        simplify_simple_instr (Tcg.Bin (iv.phi_temp, Add, Tcg.Temp iv.phi_temp, Tcg.Temp delta)) ]

let counted_update_temp = function
  | CountedIv (iv : basic_induction_var) -> iv.phi_temp
  | CountedReduction { target = ReductionTempTarget temp; _ } -> temp
  | CountedReduction { target = ReductionPlaceTarget _; _ } -> invalid_arg "counted_update_temp"

(* A carrier-progression reduction can be order-sensitive when the
   carrier is itself a basic induction variable.  In non-SSA loop CFGs the
   same temporary may denote the value carried from the previous iteration
   at an early use and be redefined later in the block as [iv + step].
   Global def lookup is intentionally not enough to distinguish

       acc += i; i += 1        (sum old i)

   from

       i += 1; acc += i        (sum updated i).

   Until reduction analysis is instruction-order aware, reject this ambiguous
   shape instead of guessing [include_updated].  This is a correctness gate,
   not a performance heuristic. *)
let ambiguous_updated_iv_carrier_reduction
    multi_defs
    def_instrs
    (ivs : basic_induction_var list)
    (reduction : counted_reduction) =
  let iv_temps =
    List.fold_left
      (fun acc (iv : basic_induction_var) -> IntSet.add iv.phi_temp acc)
      IntSet.empty ivs
  in
  let rec operand_depends_on_iv seen = function
    | Tcg.Imm _ -> false
    | Tcg.Temp temp -> temp_depends_on_iv seen temp
  and temp_depends_on_iv seen temp =
    if IntSet.mem temp iv_temps then true
    else if IntSet.mem temp seen then false
    else if IntSet.mem temp multi_defs then false
    else
      let seen = IntSet.add temp seen in
      match Hashtbl.find_opt def_instrs temp with
      | Some (Tcg.Move (_, src))
      | Some (Tcg.Un (_, UPlus, src))
      | Some (Tcg.Un (_, UMinus, src))
      | Some (Tcg.Un (_, UNot, src)) ->
          operand_depends_on_iv seen src
      | Some (Tcg.Bin (_, _, lhs, rhs)) ->
          operand_depends_on_iv seen lhs
          || operand_depends_on_iv seen rhs
      | Some (Tcg.Load _)
      | Some (Tcg.Store _)
      | Some (Tcg.Call _)
      | None ->
          false
  in
  match reduction.step with
  | ReductionCarrierProgression { carrier_temp; include_updated = true; _ } ->
      temp_depends_on_iv IntSet.empty carrier_temp
  | ReductionInvariant _
  | ReductionAffine _
  | ReductionQuadratic _
  | ReductionCubic _
  | ReductionCarrierProgression { include_updated = false; _ } ->
      false

(* Resolve the old-vs-updated carrier ambiguity using the real execution
   order on every backedge path.

   [incoming_update_chain] is stored newest-to-oldest.  Reversing it and then
   concatenating block bodies gives the actual execution order from the loop
   header to the backedge.  For a temp reduction we chase the final target
   value backwards through Move/UPlus aliases to the arithmetic instruction
   that computes the reduction update.  We do the same for the carrier temp.

   If the reduction arithmetic executes BEFORE the carrier's Add/Sub update,
   the source program used the old carrier value:

       acc += i;   <-- reduction_pos
       i += 1;     <-- carrier_pos

   so [include_updated=false].

   If the carrier update executes first, [include_updated=true].

   We only use this to discharge the conservative ambiguity gate introduced
   after the step37 wrong-code.  If positions cannot be proven on every
   backedge, the gate remains active. *)
let progression_base_iv
    multi_defs
    def_instrs
    (ivs : basic_induction_var list)
    carrier_temp
    step_expr
    carrier_subtract =
  let expected_step =
    match step_expr with
    | SummaryOperand (Tcg.Imm step) ->
        Some (if carrier_subtract then Int64.neg step else step)
    | SummaryOperand (Tcg.Temp _)
    | SummaryPlace _
    | SummaryUn _
    | SummaryBin _ ->
        None
  in
  match expected_step with
  | None -> None
  | Some expected_step ->
      let iv_by_temp temp =
        List.find_opt
          (fun (iv : basic_induction_var) ->
            iv.phi_temp = temp && iv.step = expected_step)
          ivs
      in
      let rec find seen temp =
        match iv_by_temp temp with
        | Some iv -> Some iv
        | None ->
            if IntSet.mem temp seen || IntSet.mem temp multi_defs then None
            else
              let seen = IntSet.add temp seen in
              match Hashtbl.find_opt def_instrs temp with
              | Some (Tcg.Move (_, Tcg.Temp src))
              | Some (Tcg.Un (_, UPlus, Tcg.Temp src)) ->
                  find seen src
              | Some (Tcg.Bin (_, Add, lhs, rhs)) ->
                  let lhs_iv =
                    match lhs with
                    | Tcg.Temp src -> find seen src
                    | Tcg.Imm _ -> None
                  in
                  let rhs_iv =
                    match rhs with
                    | Tcg.Temp src -> find seen src
                    | Tcg.Imm _ -> None
                  in
                  (match (lhs_iv, rhs_iv) with
                  | Some iv, None
                  | None, Some iv ->
                      Some iv
                  | Some _, Some _
                  | None, None ->
                      None)
              | Some (Tcg.Bin (_, Sub, lhs, _rhs)) -> (
                  match lhs with
                  | Tcg.Temp src -> find seen src
                  | Tcg.Imm _ -> None)
              | Some (Tcg.Move _)
              | Some (Tcg.Un _)
              | Some (Tcg.Bin _)
              | Some (Tcg.Load _)
              | Some (Tcg.Store _)
              | Some (Tcg.Call _)
              | None ->
                  None
      in
      find IntSet.empty carrier_temp

let resolve_counted_carrier_order
    header
    loop
    get_block
    multi_defs
    def_instrs
    ivs
    (reduction : counted_reduction) =
  if
    not
      (ambiguous_updated_iv_carrier_reduction
         multi_defs def_instrs ivs reduction)
  then (reduction, true)
  else
    match (reduction.target, reduction.step) with
    | ( ReductionTempTarget target_temp,
        ReductionCarrierProgression
          { carrier_temp; step_expr; carrier_subtract; include_updated = true } ) ->
        let base_iv =
          progression_base_iv
            multi_defs def_instrs ivs carrier_temp step_expr carrier_subtract
        in
        let header_block : Cfg.block = get_block header in
        let backedge_preds =
          List.filter (fun pred -> LabelSet.mem pred loop) header_block.preds
        in
        let def_temp_of_instr = function
          | Tcg.Move (dst, _)
          | Tcg.Un (dst, _, _)
          | Tcg.Bin (dst, _, _, _)
          | Tcg.Load (dst, _) ->
              Some dst
          | Tcg.Call (Some dst, _, _) -> Some dst
          | Tcg.Call (None, _, _)
          | Tcg.Store _ ->
              None
        in
        let arithmetic_def_pos_on_chain chain temp =
          let executed =
            chain
            |> List.rev
            |> List.concat_map (fun (block : Cfg.block) -> block.body)
            |> List.mapi (fun pos instr -> (pos, instr))
          in
          let latest_def_before temp before =
            List.fold_left
              (fun found (pos, instr) ->
                if pos >= before then found
                else
                  match def_temp_of_instr instr with
                  | Some dst when dst = temp -> Some (pos, instr)
                  | Some _ | None -> found)
              None executed
          in
          let rec chase seen temp before =
            if IntSet.mem temp seen then None
            else
              match latest_def_before temp before with
              | None -> None
              | Some (pos, Tcg.Move (_, Tcg.Temp src))
              | Some (pos, Tcg.Un (_, UPlus, Tcg.Temp src)) ->
                  chase (IntSet.add temp seen) src pos
              | Some (pos, Tcg.Bin (_, (Add | Sub), _, _)) ->
                  Some pos
              | Some
                  ( _,
                    ( Tcg.Move _
                    | Tcg.Un _
                    | Tcg.Bin _
                    | Tcg.Load _
                    | Tcg.Store _
                    | Tcg.Call _ ) ) ->
                  None
          in
          chase IntSet.empty temp max_int
        in
        let order_for_pred pred =
          let chain = incoming_update_chain get_block header pred in
          match
            ( arithmetic_def_pos_on_chain chain target_temp,
              arithmetic_def_pos_on_chain chain carrier_temp )
          with
          | Some reduction_pos, Some carrier_pos
            when reduction_pos < carrier_pos ->
              Some (false, reduction_pos, carrier_pos)
          | Some reduction_pos, Some carrier_pos
            when carrier_pos < reduction_pos ->
              Some (true, reduction_pos, carrier_pos)
          | Some _, Some _ | None, _ | _, None ->
              None
        in
        let pred_orders = List.map order_for_pred backedge_preds in
        let agreed =
          match pred_orders with
          | [] -> None
          | Some (first, _, _) :: rest
            when List.for_all
                   (function
                     | Some (value, _, _) -> value = first
                     | None -> false)
                   rest ->
              Some first
          | Some _ :: _ | None :: _ -> None
        in
        (match (agreed, base_iv) with
        | None, _
        | _, None ->
            if Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None then
              Printf.eprintf
                "counted-order-unresolved header=%s target=%d carrier=%d preds=%d base_iv=%s\n%!"
                header target_temp carrier_temp (List.length backedge_preds)
                (match base_iv with
                | Some (iv : basic_induction_var) ->
                    Printf.sprintf "t%d" iv.phi_temp
                | None -> "<none>");
            (reduction, false)
        | Some include_updated, Some (base_iv : basic_induction_var) ->
            if Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None then
              List.iter2
                (fun pred order ->
                  match order with
                  | Some (_, reduction_pos, carrier_pos) ->
                      Printf.eprintf
                        "counted-order-resolved header=%s pred=%s target=%d carrier=%d base_iv=%d reduction_pos=%d carrier_pos=%d include_updated=%b\n%!"
                        header pred target_temp carrier_temp base_iv.phi_temp
                        reduction_pos carrier_pos include_updated
                  | None -> ())
                backedge_preds pred_orders;
            ( {
                reduction with
                step =
                  ReductionCarrierProgression
                    {
                      carrier_temp = base_iv.phi_temp;
                      step_expr;
                      carrier_subtract;
                      include_updated;
                    };
              },
              true ))
    | ( ReductionPlaceTarget _,
        ReductionCarrierProgression { include_updated = true; _ } )
    | ( _,
        ( ReductionInvariant _
        | ReductionAffine _
        | ReductionQuadratic _
        | ReductionCubic _
        | ReductionCarrierProgression { include_updated = false; _ } ) ) ->
        (reduction, false)

let resolve_counted_carrier_orders
    header loop get_block multi_defs def_instrs ivs reductions =
  let resolved =
    List.map
      (resolve_counted_carrier_order
         header loop get_block multi_defs def_instrs ivs)
      reductions
  in
  let reductions = List.map fst resolved in
  let unresolved =
    List.filter_map
      (fun (reduction, resolved) ->
        if resolved then None
        else if
          ambiguous_updated_iv_carrier_reduction
            multi_defs def_instrs ivs reduction
        then Some reduction
        else None)
      resolved
  in
  (reductions, unresolved)

let counted_update_place = function
  | CountedReduction { target = ReductionPlaceTarget place; _ } -> Some place
  | CountedIv _ | CountedReduction { target = ReductionTempTarget _; _ } -> None

let add_reduction_alias_temps acc (reduction : counted_reduction) =
  let acc =
    match reduction.carrier_temp with
    | Some temp -> IntSet.add temp acc
    | None -> acc
  in
  List.fold_left (fun acc temp -> IntSet.add temp acc) acc reduction.alias_temps

let place_carriers_of_reductions reductions =
  List.fold_left
    (fun acc (reduction : counted_reduction) ->
      match (reduction.target, reduction.carrier_temp) with
      | ReductionPlaceTarget place, Some temp -> PlaceMap.add place temp acc
      | ReductionTempTarget _, _ | ReductionPlaceTarget _, None -> acc)
    PlaceMap.empty reductions

let materialize_place_reduction_carriers fresh_temp reductions =
  let carriers = ref PlaceMap.empty in
  let preloads_rev = ref [] in
  let ensure_carrier place =
    match PlaceMap.find_opt place !carriers with
    | Some temp -> temp
    | None ->
        let temp = fresh_temp () in
        carriers := PlaceMap.add place temp !carriers;
        preloads_rev := simplify_simple_instr (Tcg.Load (temp, place)) :: !preloads_rev;
        temp
  in
  let reductions =
    List.map
      (fun (reduction : counted_reduction) ->
        match (reduction.target, reduction.carrier_temp) with
        | ReductionPlaceTarget place, None ->
            { reduction with carrier_temp = Some (ensure_carrier place) }
        | ReductionTempTarget _, _
        | ReductionPlaceTarget _, Some _ -> reduction)
      reductions
  in
  (reductions, List.rev !preloads_rev)

type linear_expr =
  | LinearInvariant of summary_expr
  | LinearAffine of {
      iv : basic_induction_var;
      coeff : summary_expr;
      bias : summary_expr;
    }
  | LinearQuadratic of {
      iv : basic_induction_var;
      quad : summary_expr;
      triangle : summary_expr;
      coeff : summary_expr;
      bias : summary_expr;
    }
  | LinearCubic of {
      iv : basic_induction_var;
      choose3 : summary_expr;
      triangle : summary_expr;
      coeff : summary_expr;
      bias : summary_expr;
    }

let zero_summary_expr = SummaryOperand (Tcg.Imm 0L)
let one_summary_expr = SummaryOperand (Tcg.Imm 1L)

let summary_expr_is_zero = function
  | SummaryOperand (Tcg.Imm 0L) -> true
  | SummaryOperand _ | SummaryPlace _ | SummaryUn _ | SummaryBin _ -> false

let summary_expr_is_one = function
  | SummaryOperand (Tcg.Imm 1L) -> true
  | SummaryOperand _ | SummaryPlace _ | SummaryUn _ | SummaryBin _ -> false

let summary_expr_is_minus_one = function
  | SummaryOperand (Tcg.Imm (-1L)) -> true
  | SummaryOperand _ | SummaryPlace _ | SummaryUn _ | SummaryBin _ -> false

let summary_expr_neg expr =
  if summary_expr_is_zero expr then expr else SummaryUn (UMinus, expr)

let summary_expr_add lhs rhs =
  if summary_expr_is_zero lhs then rhs
  else if summary_expr_is_zero rhs then lhs
  else SummaryBin (Add, lhs, rhs)

let summary_expr_sub lhs rhs =
  if summary_expr_is_zero rhs then lhs
  else if summary_expr_is_zero lhs then summary_expr_neg rhs
  else SummaryBin (Sub, lhs, rhs)

let summary_expr_mul lhs rhs =
  if summary_expr_is_zero lhs || summary_expr_is_zero rhs then zero_summary_expr
  else if summary_expr_is_one lhs then rhs
  else if summary_expr_is_one rhs then lhs
  else if summary_expr_is_minus_one lhs then summary_expr_neg rhs
  else if summary_expr_is_minus_one rhs then summary_expr_neg lhs
  else SummaryBin (Mul, lhs, rhs)

let summary_expr_const value =
  SummaryOperand (Tcg.Imm value)

let summary_expr_scale value expr =
  summary_expr_mul (summary_expr_const value) expr

let linear_affine iv coeff bias =
  if summary_expr_is_zero coeff then LinearInvariant bias
  else LinearAffine { iv; coeff; bias }

let linear_quadratic iv quad triangle coeff bias =
  if summary_expr_is_zero quad && summary_expr_is_zero triangle then
    linear_affine iv coeff bias
  else
    LinearQuadratic { iv; quad; triangle; coeff; bias }

let linear_cubic iv choose3 triangle coeff bias =
  if summary_expr_is_zero choose3 then
    linear_quadratic iv zero_summary_expr triangle coeff bias
  else
    LinearCubic { iv; choose3; triangle; coeff; bias }

let basic_iv_known_nonnegative_step1 (iv : basic_induction_var) =
  iv.step = 1L
  &&
  match iv.outside_inputs with
  | [] -> false
  | inputs ->
      List.for_all
        (fun (_, operand) ->
          match operand with
          | Tcg.Imm value -> value >= 0L
          | Tcg.Temp _ -> false)
        inputs


let linear_expr_neg = function
  | LinearInvariant expr ->
      LinearInvariant (summary_expr_neg expr)
  | LinearAffine { iv; coeff; bias } ->
      linear_affine iv (summary_expr_neg coeff) (summary_expr_neg bias)
  | LinearQuadratic { iv; quad; triangle; coeff; bias } ->
      linear_quadratic
        iv
        (summary_expr_neg quad)
        (summary_expr_neg triangle)
        (summary_expr_neg coeff)
        (summary_expr_neg bias)
  | LinearCubic { iv; choose3; triangle; coeff; bias } ->
      linear_cubic
        iv
        (summary_expr_neg choose3)
        (summary_expr_neg triangle)
        (summary_expr_neg coeff)
        (summary_expr_neg bias)

let linear_expr_add lhs rhs =
  let add_cubic_quadratic
      iv
      cubic_choose3
      cubic_triangle
      cubic_coeff
      cubic_bias
      quad_quad
      quad_triangle
      quad_coeff
      quad_bias
    =
    let q_triangle =
      summary_expr_add
        (summary_expr_scale 2L quad_quad)
        quad_triangle
    in
    let q_coeff =
      summary_expr_add quad_quad quad_coeff
    in
    linear_cubic
      iv
      cubic_choose3
      (summary_expr_add cubic_triangle q_triangle)
      (summary_expr_add cubic_coeff q_coeff)
      (summary_expr_add cubic_bias quad_bias)
  in
  match (lhs, rhs) with
  | LinearInvariant lhs, LinearInvariant rhs ->
      Some (LinearInvariant (summary_expr_add lhs rhs))

  | LinearAffine { iv; coeff; bias }, LinearInvariant rhs
  | LinearInvariant rhs, LinearAffine { iv; coeff; bias } ->
      Some (linear_affine iv coeff (summary_expr_add bias rhs))

  | LinearQuadratic { iv; quad; triangle; coeff; bias }, LinearInvariant rhs
  | LinearInvariant rhs, LinearQuadratic { iv; quad; triangle; coeff; bias } ->
      Some
        (linear_quadratic
           iv quad triangle coeff
           (summary_expr_add bias rhs))

  | LinearCubic { iv; choose3; triangle; coeff; bias }, LinearInvariant rhs
  | LinearInvariant rhs, LinearCubic { iv; choose3; triangle; coeff; bias } ->
      Some
        (linear_cubic
           iv choose3 triangle coeff
           (summary_expr_add bias rhs))

  | LinearAffine lhs, LinearAffine rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      Some
        (linear_affine
           lhs.iv
           (summary_expr_add lhs.coeff rhs.coeff)
           (summary_expr_add lhs.bias rhs.bias))

  | LinearQuadratic lhs, LinearAffine rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      Some
        (linear_quadratic
           lhs.iv
           lhs.quad
           lhs.triangle
           (summary_expr_add lhs.coeff rhs.coeff)
           (summary_expr_add lhs.bias rhs.bias))

  | LinearAffine lhs, LinearQuadratic rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      Some
        (linear_quadratic
           rhs.iv
           rhs.quad
           rhs.triangle
           (summary_expr_add lhs.coeff rhs.coeff)
           (summary_expr_add lhs.bias rhs.bias))

  | LinearQuadratic lhs, LinearQuadratic rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      Some
        (linear_quadratic
           lhs.iv
           (summary_expr_add lhs.quad rhs.quad)
           (summary_expr_add lhs.triangle rhs.triangle)
           (summary_expr_add lhs.coeff rhs.coeff)
           (summary_expr_add lhs.bias rhs.bias))

  | LinearCubic lhs, LinearAffine rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      Some
        (linear_cubic
           lhs.iv
           lhs.choose3
           lhs.triangle
           (summary_expr_add lhs.coeff rhs.coeff)
           (summary_expr_add lhs.bias rhs.bias))

  | LinearAffine lhs, LinearCubic rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      Some
        (linear_cubic
           rhs.iv
           rhs.choose3
           rhs.triangle
           (summary_expr_add lhs.coeff rhs.coeff)
           (summary_expr_add lhs.bias rhs.bias))

  | LinearCubic lhs, LinearQuadratic rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      Some
        (add_cubic_quadratic
           lhs.iv
           lhs.choose3
           lhs.triangle
           lhs.coeff
           lhs.bias
           rhs.quad
           rhs.triangle
           rhs.coeff
           rhs.bias)

  | LinearQuadratic lhs, LinearCubic rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      Some
        (add_cubic_quadratic
           rhs.iv
           rhs.choose3
           rhs.triangle
           rhs.coeff
           rhs.bias
           lhs.quad
           lhs.triangle
           lhs.coeff
           lhs.bias)

  | LinearCubic lhs, LinearCubic rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      Some
        (linear_cubic
           lhs.iv
           (summary_expr_add lhs.choose3 rhs.choose3)
           (summary_expr_add lhs.triangle rhs.triangle)
           (summary_expr_add lhs.coeff rhs.coeff)
           (summary_expr_add lhs.bias rhs.bias))

  | LinearAffine _, LinearAffine _
  | LinearAffine _, LinearQuadratic _
  | LinearQuadratic _, LinearAffine _
  | LinearQuadratic _, LinearQuadratic _
  | LinearAffine _, LinearCubic _
  | LinearCubic _, LinearAffine _
  | LinearQuadratic _, LinearCubic _
  | LinearCubic _, LinearQuadratic _
  | LinearCubic _, LinearCubic _ ->
      None

let linear_expr_sub lhs rhs =
  linear_expr_add lhs (linear_expr_neg rhs)

let linear_expr_mul_invariant factor = function
  | LinearInvariant expr ->
      Some (LinearInvariant (summary_expr_mul factor expr))
  | LinearAffine { iv; coeff; bias } ->
      Some
        (linear_affine
           iv
           (summary_expr_mul factor coeff)
           (summary_expr_mul factor bias))
  | LinearQuadratic { iv; quad; triangle; coeff; bias } ->
      Some
        (linear_quadratic
           iv
           (summary_expr_mul factor quad)
           (summary_expr_mul factor triangle)
           (summary_expr_mul factor coeff)
           (summary_expr_mul factor bias))
  | LinearCubic { iv; choose3; triangle; coeff; bias } ->
      Some
        (linear_cubic
           iv
           (summary_expr_mul factor choose3)
           (summary_expr_mul factor triangle)
           (summary_expr_mul factor coeff)
           (summary_expr_mul factor bias))

let linear_expr_mul_affine_quadratic
    affine_iv
    affine_coeff
    affine_bias
    quad_iv
    quad_quad
    quad_triangle
    quad_coeff
    quad_bias
  =
  if
    affine_iv.phi_temp <> quad_iv.phi_temp
    || not (basic_iv_known_nonnegative_step1 affine_iv)
  then
    None
  else
    let a = affine_coeff in
    let b = affine_bias in
    let q = quad_quad in
    let t = quad_triangle in
    let c = quad_coeff in
    let d = quad_bias in

    (* (a*i+b) * (q*i^2+t*T+c*i+d)

       i^3 = 6*C3 + 6*T + i
       i*T = 3*C3 + 2*T
       i^2 = 2*T + i
    *)
    let choose3 =
      summary_expr_mul
        a
        (summary_expr_add
           (summary_expr_scale 6L q)
           (summary_expr_scale 3L t))
    in

    let triangle_from_a =
      summary_expr_mul
        a
        (summary_expr_add
           (summary_expr_scale 6L q)
           (summary_expr_add
              (summary_expr_scale 2L t)
              (summary_expr_scale 2L c)))
    in
    let triangle_from_b =
      summary_expr_mul
        b
        (summary_expr_add
           (summary_expr_scale 2L q)
           t)
    in
    let triangle =
      summary_expr_add triangle_from_a triangle_from_b
    in

    let coeff_from_a =
      summary_expr_mul
        a
        (summary_expr_add
           q
           (summary_expr_add c d))
    in
    let coeff_from_b =
      summary_expr_mul
        b
        (summary_expr_add q c)
    in
    let coeff =
      summary_expr_add coeff_from_a coeff_from_b
    in

    let bias = summary_expr_mul b d in
    Some (linear_cubic affine_iv choose3 triangle coeff bias)

let linear_expr_mul lhs rhs =
  match (lhs, rhs) with
  | LinearInvariant lhs, rhs ->
      linear_expr_mul_invariant lhs rhs
  | lhs, LinearInvariant rhs ->
      linear_expr_mul_invariant rhs lhs

  | LinearAffine lhs, LinearAffine rhs
    when lhs.iv.phi_temp = rhs.iv.phi_temp ->
      let quad = summary_expr_mul lhs.coeff rhs.coeff in
      let coeff =
        summary_expr_add
          (summary_expr_mul lhs.coeff rhs.bias)
          (summary_expr_mul rhs.coeff lhs.bias)
      in
      let bias = summary_expr_mul lhs.bias rhs.bias in
      Some
        (linear_quadratic
           lhs.iv quad zero_summary_expr coeff bias)

  | LinearAffine affine, LinearQuadratic quad ->
      linear_expr_mul_affine_quadratic
        affine.iv affine.coeff affine.bias
        quad.iv quad.quad quad.triangle quad.coeff quad.bias
  | LinearQuadratic quad, LinearAffine affine ->
      linear_expr_mul_affine_quadratic
        affine.iv affine.coeff affine.bias
        quad.iv quad.quad quad.triangle quad.coeff quad.bias

  | LinearAffine _, LinearAffine _
  | LinearAffine _, LinearCubic _
  | LinearCubic _, LinearAffine _
  | LinearQuadratic _, LinearQuadratic _
  | LinearQuadratic _, LinearCubic _
  | LinearCubic _, LinearQuadratic _
  | LinearCubic _, LinearCubic _ ->
      None

let summary_expr_of_operand_with_bases
    base_temps
    invariant_loaded_places
    loop_defs
    def_blocks
    get_block
    loop_stable_phis
    multi_defs
    def_instrs
    (block : Cfg.block)
    operand
  =
  let invariant operand =
    operand_loop_invariant
      loop_defs loop_stable_phis multi_defs def_instrs IntSet.empty operand
  in
  let rec of_operand block seen = function
    | Tcg.Imm _ as operand -> Some (SummaryOperand operand)
    | Tcg.Temp temp as operand ->
        if IntSet.mem temp base_temps || invariant operand then Some (SummaryOperand operand)
        else if IntSet.mem temp seen || IntSet.mem temp multi_defs then None
        else
          match last_def_of_temp block temp with
          | Some instr -> of_instr block (IntSet.add temp seen) instr
          | None -> (
              match Hashtbl.find_opt def_instrs temp with
              | Some instr -> (
                  match Hashtbl.find_opt def_blocks temp with
                  | Some label -> of_instr (get_block label) (IntSet.add temp seen) instr
                  | None -> None)
              | None -> None)
  and of_instr block seen = function
    | Tcg.Move (_, src) -> of_operand block seen (resolve_block_operand block src)
    | Tcg.Load (_, place) when PlaceSet.mem place invariant_loaded_places ->
        Some (SummaryPlace place)
    | Tcg.Un (_, op, src) ->
        let src = resolve_block_operand block src in
        Option.map (fun src -> SummaryUn (op, src)) (of_operand block seen src)
    | Tcg.Bin (_, Add, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        Option.bind (of_operand block seen lhs) (fun lhs ->
            Option.map (fun rhs -> SummaryBin (Add, lhs, rhs)) (of_operand block seen rhs))
    | Tcg.Bin (_, Sub, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        Option.bind (of_operand block seen lhs) (fun lhs ->
            Option.map (fun rhs -> SummaryBin (Sub, lhs, rhs)) (of_operand block seen rhs))
    | Tcg.Bin (_, op, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        Option.bind (of_operand block seen lhs) (fun lhs ->
            Option.map (fun rhs -> SummaryBin (op, lhs, rhs)) (of_operand block seen rhs))
    | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> None
  in
  of_operand block IntSet.empty operand

let summary_expr_of_operand
    invariant_loaded_places
    loop_defs
    def_blocks
    get_block
    loop_stable_phis
    multi_defs
    def_instrs
    (block : Cfg.block)
    operand
  =
  summary_expr_of_operand_with_bases
    IntSet.empty
    invariant_loaded_places
    loop_defs
    def_blocks
    get_block
    loop_stable_phis
    multi_defs
    def_instrs
    block
    operand

let linear_expr_of_operand
    ?(allow_local_multidef = false)
    invariant_loaded_places
    loop_defs
    def_blocks
    get_block
    loop_stable_phis
    multi_defs
    def_instrs
    ivs
    (block : Cfg.block)
    operand
  =
  let direct_iv operand =
    let operand = resolve_block_operand block operand in
    List.find_opt
      (fun (iv : basic_induction_var) ->
        resolves_to_induction_temp multi_defs def_instrs iv.phi_temp operand)
      ivs
  in
  let direct_scaled operand =
    match direct_iv operand with
    | Some iv ->
        Some
          (LinearAffine
             { iv; coeff = one_summary_expr; bias = zero_summary_expr })
    | None -> None
  in
  let immediate_iv_init (iv : basic_induction_var) =
    match iv.outside_inputs with
    | [] -> None
    | inputs ->
        let values =
          List.map
            (fun (_, operand) ->
              match operand with
              | Tcg.Imm value -> Some value
              | Tcg.Temp _ -> None)
            inputs
        in
        if List.exists Option.is_none values then None
        else
          match
            values
            |> List.filter_map (fun value -> value)
            |> List.sort_uniq compare
          with
          | [ value ] -> Some value
          | _ -> None
  in
  let monotone_iv_range (iv : basic_induction_var) =
    match immediate_iv_init iv with
    | None -> None
    | Some init when iv.step > 0L ->
        Some { min_value = Some init; max_value = None }
    | Some init when iv.step < 0L ->
        Some { min_value = None; max_value = Some init }
    | Some init ->
        Some { min_value = Some init; max_value = Some init }
  in
  let compare_constant_from_iv op lhs rhs =
    let lhs = resolve_block_operand block lhs in
    let rhs = resolve_block_operand block rhs in
    let check op iv constant =
      Option.bind
        (monotone_iv_range iv)
        (fun range -> compare_truth_from_range op range constant)
    in
    match (direct_iv lhs, rhs, lhs, direct_iv rhs) with
    | Some iv, Tcg.Imm constant, _, _ ->
        check op iv constant
    | _, _, Tcg.Imm constant, Some iv ->
        check (swap_compare op) iv constant
    | _ ->
        None
  in
  let operand_def block operand =
    match resolve_block_operand block operand with
    | Tcg.Imm _ -> None
    | Tcg.Temp temp -> last_def_of_temp block temp
  in
  let operand_same block lhs rhs =
    resolve_block_operand block lhs = resolve_block_operand block rhs
  in
  let debug_triangle_enabled () =
    Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None
  in
  let debug_operand = function
    | Tcg.Imm value -> Int64.to_string value
    | Tcg.Temp temp -> Printf.sprintf "t%d" temp
  in
  let prefix_before_instr (block : Cfg.block) current_instr =
    let rec physical acc = function
      | [] -> None
      | instr :: rest ->
          if instr == current_instr then Some (List.rev acc)
          else physical (instr :: acc) rest
    in
    let rec structural acc best = function
      | [] -> best
      | instr :: rest ->
          let best =
            if instr = current_instr then Some (List.rev acc)
            else best
          in
          structural (instr :: acc) best rest
    in
    match physical [] block.body with
    | Some prefix -> prefix
    | None ->
        Option.value
          (structural [] None block.body)
          ~default:block.body
  in
  let debug_def block operand =
    match resolve_block_operand block operand with
    | Tcg.Imm value ->
        Printf.sprintf "imm(%Ld)" value
    | Tcg.Temp temp -> (
        match last_def_of_temp block temp with
        | None ->
            Printf.sprintf "t%d:<none>" temp
        | Some (Tcg.Move (_, src)) ->
            Printf.sprintf "t%d=move(%s)" temp (debug_operand src)
        | Some (Tcg.Un (_, op, src)) ->
            Printf.sprintf "t%d=un(%s,%s)"
              temp
              (match op with UPlus -> "+" | UMinus -> "-" | UNot -> "!")
              (debug_operand src)
        | Some (Tcg.Bin (_, op, lhs, rhs)) ->
            Printf.sprintf "t%d=%s(%s,%s)"
              temp
              (match op with
               | Add -> "add" | Sub -> "sub" | Mul -> "mul"
               | Div -> "div" | Mod -> "mod"
               | Lt -> "lt" | Le -> "le" | Gt -> "gt" | Ge -> "ge"
               | Eq -> "eq" | Ne -> "ne"
               | LAnd -> "land" | LOr -> "lor")
              (debug_operand lhs)
              (debug_operand rhs)
        | Some (Tcg.Load (_, place)) ->
            Printf.sprintf "t%d=load(%s)"
              temp
              (match place with
               | Tcg.Local id -> Printf.sprintf "local:%d" id
               | Tcg.Global name -> Printf.sprintf "global:%s" name)
        | Some (Tcg.Store _) ->
            Printf.sprintf "t%d=<store-impossible>" temp
        | Some (Tcg.Call (_, name, _)) ->
            Printf.sprintf "t%d=call(%s)" temp name)
  in

  (* Program-point-local invariant closure.

     [summary_expr_of_operand] is deliberately conservative about a temp that
     is multi-defined anywhere in the loop.  After an inner counted loop is
     summarized, however, the enclosing loop commonly contains temps such as

       outer-body:    t4 = 0
       inner-summary: t4 = bound * (bound >= 0)

     so [t4] is function/loop-wide multi-def even though, at the exact point
     inside [inner-summary], the prefix contains one unambiguous definition.

     When [allow_local_multidef] is enabled, follow only a definition visible
     in the supplied block prefix.  This proves pure arithmetic subtrees
     invariant at that program point without choosing an arbitrary reaching
     definition.  A multi-def temp with no local visible definition is still
     rejected, which keeps genuinely loop-carried values out of this closure. *)
  let point_local_invariant_summary block operand =
    let invariant operand =
      operand_loop_invariant
        loop_defs loop_stable_phis multi_defs def_instrs
        IntSet.empty operand
    in
    let rec of_operand block seen operand =
      match operand with
      | Tcg.Imm _ ->
          Some (SummaryOperand operand)
      | Tcg.Temp temp ->
          (* A real counted IV must remain affine, never become an invariant
             just because one update happens to be visible locally. *)
          if
            List.exists
              (fun (iv : basic_induction_var) ->
                iv.phi_temp = temp)
              ivs
          then
            None
          else if invariant operand then
            Some (SummaryOperand operand)
          else if IntSet.mem temp seen then
            None
          else
            let seen = IntSet.add temp seen in
            match last_def_of_temp block temp with
            | Some instr
              when
                allow_local_multidef
                || not (IntSet.mem temp multi_defs) ->
                of_instr block seen instr
            | Some _ ->
                None
            | None ->
                (* Crucial safety fence: do not use a function-wide/global
                   definition for a multi-def temp.  Without a definition in
                   this program-point prefix, its reaching value is ambiguous. *)
                if IntSet.mem temp multi_defs then
                  None
                else
                  match Hashtbl.find_opt def_instrs temp with
                  | Some instr -> (
                      match Hashtbl.find_opt def_blocks temp with
                      | Some label ->
                          of_instr (get_block label) seen instr
                      | None ->
                          None)
                  | None ->
                      None
    and of_instr block seen = function
      | Tcg.Move (_, src) ->
          of_operand block seen
            (resolve_block_operand block src)
      | Tcg.Load (_, place)
        when PlaceSet.mem place invariant_loaded_places ->
          Some (SummaryPlace place)
      | Tcg.Un (_, op, src) ->
          let src = resolve_block_operand block src in
          Option.map
            (fun expr -> SummaryUn (op, expr))
            (of_operand block seen src)
      | Tcg.Bin (_, op, lhs, rhs) ->
          let lhs = resolve_block_operand block lhs in
          let rhs = resolve_block_operand block rhs in
          Option.bind
            (of_operand block seen lhs)
            (fun lhs_expr ->
              Option.map
                (fun rhs_expr ->
                  SummaryBin (op, lhs_expr, rhs_expr))
                (of_operand block seen rhs))
      | Tcg.Load _
      | Tcg.Store _
      | Tcg.Call _ ->
          None
    in
    of_operand block IntSet.empty operand
  in
  let rec of_operand block seen operand =
    match direct_scaled operand with
    | Some expr -> Some expr
    | None -> (
        match generated_choose3 block seen operand with
        | Some expr -> Some expr
        | None -> (
            match generated_triangle block seen operand with
            | Some expr -> Some expr
            | None -> (
                let invariant_expr =
                  match
                    summary_expr_of_operand
                      invariant_loaded_places
                      loop_defs def_blocks get_block
                      loop_stable_phis multi_defs def_instrs
                      block operand
                  with
                  | Some expr ->
                      Some expr
                  | None when allow_local_multidef -> (
                      match
                        point_local_invariant_summary
                          block operand
                      with
                      | Some _ as result ->
                          if debug_triangle_enabled () then
                            Printf.eprintf
                              "counted-linear-local-invariant-hit block=%s operand=%s\n%!"
                              block.label
                              (debug_operand
                                 (resolve_block_operand
                                    block operand));
                          result
                      | None ->
                          None)
                  | None ->
                      None
                in
                match invariant_expr with
                | Some expr ->
                    Some (LinearInvariant expr)
                | None -> (
                match operand with
                | Tcg.Imm _ -> None
                | Tcg.Temp temp ->
                    if IntSet.mem temp seen then None
                    else
                      match last_def_of_temp block temp with
                      | Some instr
                        when allow_local_multidef
                             || not (IntSet.mem temp multi_defs) ->
                          let instr_block =
                            if
                              allow_local_multidef
                              && IntSet.mem temp multi_defs
                            then
                              let prefix =
                                prefix_before_instr block instr
                              in
                              let point_block =
                                { block with body = prefix }
                              in
                              if debug_triangle_enabled () then
                                Printf.eprintf
                                  "counted-poly-local-multidef block=%s temp=t%d def=%s prefix=%d/%d\n%!"
                                  block.label temp
                                  (debug_def block (Tcg.Temp temp))
                                  (List.length prefix)
                                  (List.length block.body);
                              point_block
                            else
                              block
                          in
                          of_instr
                            instr_block
                            (IntSet.add temp seen)
                            instr
                      | Some _ ->
                          None
                      | None ->
                          if IntSet.mem temp multi_defs then None
                          else (
                            match Hashtbl.find_opt def_instrs temp with
                            | Some instr -> (
                                match Hashtbl.find_opt def_blocks temp with
                                | Some label ->
                                    of_instr
                                      (get_block label)
                                      (IntSet.add temp seen)
                                      instr
                                | None -> None)
                            | None -> None)))))
  and generated_choose3 block seen operand =
    let resolved = resolve_block_operand block operand in

    let bin_of_operand op operand =
      match operand_def block operand with
      | Some (Tcg.Bin (_, actual, lhs, rhs)) when actual = op ->
          Some (lhs, rhs)
      | _ ->
          None
    in

    let match_commutative_bin op operand =
      bin_of_operand op operand
    in

    let match_sub_const operand constant =
      match bin_of_operand Sub operand with
      | Some (lhs, Tcg.Imm rhs) when rhs = constant ->
          Some lhs
      | _ ->
          None
    in

    let match_div_const operand constant =
      match bin_of_operand Div operand with
      | Some (lhs, Tcg.Imm rhs) when rhs = constant ->
          Some lhs
      | _ ->
          None
    in

    let match_mod_const operand constant =
      match bin_of_operand Mod operand with
      | Some (lhs, Tcg.Imm rhs) when rhs = constant ->
          Some lhs
      | _ ->
          None
    in

    let match_eq_const operand constant =
      match bin_of_operand Eq operand with
      | Some (lhs, Tcg.Imm rhs) when rhs = constant ->
          Some lhs
      | Some (Tcg.Imm lhs, rhs) when lhs = constant ->
          Some rhs
      | _ ->
          None
    in

    let match_select operand =
      (* Exact shape emitted by [build_select_operand_instrs]:

           diff   = if_true - if_false
           scaled = cond * diff
           dst    = if_false + scaled

         Add/Mul are accepted in either operand order. *)
      let try_add if_false scaled =
        match match_commutative_bin Mul scaled with
        | None -> None
        | Some (mul_a, mul_b) ->
            let try_mul cond diff =
              match bin_of_operand Sub diff with
              | Some (if_true, diff_false)
                when operand_same block if_false diff_false ->
                  Some (cond, if_true, if_false)
              | _ ->
                  None
            in
            (match try_mul mul_a mul_b with
             | Some _ as result -> result
             | None -> try_mul mul_b mul_a)
      in
      match match_commutative_bin Add operand with
      | None -> None
      | Some (lhs, rhs) -> (
          match try_add lhs rhs with
          | Some _ as result -> result
          | None -> try_add rhs lhs)
    in

    let match_divided_select expected_rem operand =
      match match_select operand with
      | Some (cond, if_true, if_false) -> (
          match
            ( match_eq_const cond expected_rem,
              match_div_const if_true 3L )
          with
          | Some rem3, Some divided_base
            when operand_same block divided_base if_false ->
              Some (rem3, if_false)
          | _ ->
              None)
      | None ->
          None
    in

    let match_a2 operand =
      match match_select operand with
      | Some (even_cond, if_true, if_false) -> (
          match
            ( match_eq_const even_cond 0L,
              match_div_const if_true 2L )
          with
          | Some rem2, Some n
            when operand_same block n if_false -> (
              match match_mod_const rem2 2L with
              | Some n2 when operand_same block n n2 ->
                  Some (even_cond, n)
              | _ ->
                  None)
          | _ ->
              None)
      | None ->
          None
    in

    let match_b2 operand =
      match match_select operand with
      | Some (even_cond, if_true, if_false) -> (
          match match_div_const if_false 2L with
          | Some b when operand_same block b if_true ->
              Some (even_cond, b)
          | _ ->
              None)
      | None ->
          None
    in

    let try_root ab c3 =
      match match_commutative_bin Mul ab with
      | None -> None
      | Some (ab_left, ab_right) ->
          let try_ab a3 b3 =
            match
              ( match_divided_select 0L a3,
                match_divided_select 1L b3,
                match_divided_select 2L c3 )
            with
            | ( Some (rem3_a, a2),
                Some (rem3_b, b2),
                Some (rem3_c, c) )
              when operand_same block rem3_a rem3_b
                   && operand_same block rem3_a rem3_c -> (
                match match_mod_const rem3_a 3L with
                | None -> None
                | Some n_from_rem3 -> (
                    match (match_a2 a2, match_b2 b2) with
                    | Some (even_a, n), Some (even_b, b)
                      when operand_same block even_a even_b
                           && operand_same block n n_from_rem3 -> (
                        match
                          ( match_eq_const even_a 0L,
                            match_sub_const b 1L,
                            match_sub_const c 2L )
                        with
                        | Some rem2, Some n_from_b, Some n_from_c -> (
                            match match_mod_const rem2 2L with
                            | Some n_from_rem2
                              when operand_same block n n_from_b
                                   && operand_same block n n_from_c
                                   && operand_same block n n_from_rem2 ->
                                let result =
                                  Option.bind
                                    (of_operand block seen n)
                                    (function
                                      | LinearAffine { iv; coeff; bias }
                                        when summary_expr_is_one coeff
                                             && summary_expr_is_zero bias
                                             && basic_iv_known_nonnegative_step1 iv ->
                                          Some
                                            (linear_cubic
                                               iv
                                               one_summary_expr
                                               zero_summary_expr
                                               zero_summary_expr
                                               zero_summary_expr)
                                      | LinearInvariant _
                                      | LinearAffine _
                                      | LinearQuadratic _
                                      | LinearCubic _ ->
                                          None)
                                in
                                if debug_triangle_enabled () then
                                  Printf.eprintf
                                    "counted-choose3-result target=%s base=%s matched=%b\n%!"
                                    (debug_operand resolved)
                                    (debug_operand n)
                                    (Option.is_some result);
                                result
                            | _ ->
                                None)
                        | _ ->
                            None)
                    | _ ->
                        None))
            | _ ->
                None
          in
          (match try_ab ab_left ab_right with
           | Some _ as result -> result
           | None -> try_ab ab_right ab_left)
    in

    match resolved with
    | Tcg.Imm _ ->
        None
    | Tcg.Temp temp ->
        if IntSet.mem temp seen then None
        else
          match match_commutative_bin Mul resolved with
          | Some (lhs, rhs) -> (
              match try_root lhs rhs with
              | Some _ as result -> result
              | None -> try_root rhs lhs)
          | None ->
              None

  and generated_triangle block seen operand =
    let resolved = resolve_block_operand block operand in
    let parse_orientation left right =
      if debug_triangle_enabled () then
        Printf.eprintf
          "counted-triangle-orient target=%s left=%s{%s} right=%s{%s}\n%!"
          (debug_operand resolved)
          (debug_operand left) (debug_def block left)
          (debug_operand right) (debug_def block right);
      match (operand_def block left, operand_def block right) with
      | ( Some (Tcg.Bin (_, Mul, left_a, left_b)),
          Some (Tcg.Bin (_, Mul, right_a, right_b)) ) ->
          let classify_left first second =
            match (operand_def block first, operand_def block second) with
            | ( Some (Tcg.Bin (_, Div, n_half, Tcg.Imm 2L)),
                Some (Tcg.Bin (_, Sub, n_minus, Tcg.Imm 1L)) ) ->
                Some (first, second, n_half, n_minus)
            | _ -> None
          in
          let classify_right first second =
            match (operand_def block first, operand_def block second) with
            | ( Some (Tcg.Bin (_, Mod, n_parity, Tcg.Imm 2L)),
                Some (Tcg.Bin (_, Div, n_minus_half, Tcg.Imm 2L)) ) ->
                Some (first, second, n_parity, n_minus_half)
            | _ -> None
          in
          let left_shape =
            match classify_left left_a left_b with
            | Some _ as result -> result
            | None -> classify_left left_b left_a
          in
          let right_shape =
            match classify_right right_a right_b with
            | Some _ as result -> result
            | None -> classify_right right_b right_a
          in
          (match (left_shape, right_shape) with
           | ( Some (half_n, n_minus_one_a, n_a, n_c),
               Some (parity, half_n_minus_one, n_b, n_minus_one_b) )
             when operand_same block n_a n_b
                  && operand_same block n_a n_c
                  && operand_same block n_minus_one_a n_minus_one_b ->
               if debug_triangle_enabled () then begin
                 Printf.eprintf
                   "counted-triangle-muls target=%s half=%s{%s} nminus=%s{%s} parity=%s{%s} halfminus=%s{%s}\n%!"
                   (debug_operand resolved)
                   (debug_operand half_n) (debug_def block half_n)
                   (debug_operand n_minus_one_a) (debug_def block n_minus_one_a)
                   (debug_operand parity) (debug_def block parity)
                   (debug_operand half_n_minus_one) (debug_def block half_n_minus_one);
                 Printf.eprintf
                   "counted-triangle-base target=%s n=%s{%s}\n%!"
                   (debug_operand resolved)
                   (debug_operand n_a) (debug_def block n_a)
               end;
               let result =
                 Option.bind
                   (of_operand block seen n_a)
                   (function
                     | LinearAffine { iv; coeff; bias }
                       when summary_expr_is_one coeff
                            && summary_expr_is_zero bias
                            && iv.step = 1L
                            && (match immediate_iv_init iv with
                                | Some init -> init >= 0L
                                | None -> false) ->
                         Some
                           (linear_quadratic
                              iv
                              zero_summary_expr
                              one_summary_expr
                              zero_summary_expr
                              zero_summary_expr)
                     | LinearInvariant _
                     | LinearAffine _
                     | LinearQuadratic _
                     | LinearCubic _ ->
                         None)
               in
               if debug_triangle_enabled () then
                 Printf.eprintf
                   "counted-triangle-result target=%s matched=%b\n%!"
                   (debug_operand resolved)
                   (Option.is_some result);
               result
           | _ ->
               if debug_triangle_enabled () then
                 Printf.eprintf
                   "counted-triangle-miss target=%s stage=inner-shape\n%!"
                   (debug_operand resolved);
               None)
      | _ ->
          if debug_triangle_enabled () then
            Printf.eprintf
              "counted-triangle-miss target=%s stage=mul-pair\n%!"
              (debug_operand resolved);
          None
    in
    match resolved with
    | Tcg.Imm _ -> None
    | Tcg.Temp temp ->
        if IntSet.mem temp seen then None
        else
          match last_def_of_temp block temp with
          | Some (Tcg.Bin (_, Add, lhs, rhs)) -> (
              if debug_triangle_enabled () then
                Printf.eprintf
                  "counted-triangle-try target=t%d def=add(%s,%s) block=%s\n%!"
                  temp (debug_operand lhs) (debug_operand rhs) block.label;
              match parse_orientation lhs rhs with
              | Some _ as result -> result
              | None -> parse_orientation rhs lhs)
          | Some _ ->
              None
          | None ->
              None
  and of_instr block seen = function
    | Tcg.Move (_, src) -> of_operand block seen (resolve_block_operand block src)
    | Tcg.Un (_, UMinus, src) ->
        let src = resolve_block_operand block src in
        Option.map linear_expr_neg (of_operand block seen src)
    | Tcg.Un _ -> None
    | Tcg.Bin (_, Add, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        Option.bind (of_operand block seen lhs) (fun lhs ->
            Option.bind (of_operand block seen rhs) (linear_expr_add lhs))
    | Tcg.Bin (_, Sub, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        Option.bind (of_operand block seen lhs) (fun lhs ->
            Option.bind (of_operand block seen rhs) (linear_expr_sub lhs))
    | Tcg.Bin (_, Mul, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        Option.bind (of_operand block seen lhs) (fun lhs_expr ->
            Option.bind (of_operand block seen rhs) (linear_expr_mul lhs_expr))
    | Tcg.Bin (_, op, lhs, rhs) when is_compare_binop op -> (
        match compare_constant_from_iv op lhs rhs with
        | Some true -> Some (LinearInvariant one_summary_expr)
        | Some false -> Some (LinearInvariant zero_summary_expr)
        | None -> None)
    | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> None
  in
  of_operand block IntSet.empty operand

let reduction_step_of_operand
    ?(allow_local_multidef = false)
    invariant_loaded_places
    loop_defs
    def_blocks
    get_block
    loop_stable_phis
    multi_defs
    def_instrs
    ivs
    (block : Cfg.block)
    operand
  =
  let parsed =
    linear_expr_of_operand
      ~allow_local_multidef
      invariant_loaded_places
      loop_defs def_blocks get_block loop_stable_phis multi_defs def_instrs ivs block operand
  in

  let debug_enabled =
    Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None
  in

  let string_of_operand = function
    | Tcg.Imm value -> Printf.sprintf "%Ld" value
    | Tcg.Temp temp -> Printf.sprintf "t%d" temp
  in

  let string_of_binop = function
    | Add -> "add"
    | Sub -> "sub"
    | Mul -> "mul"
    | Div -> "div"
    | Mod -> "mod"
    | Lt -> "lt"
    | Le -> "le"
    | Gt -> "gt"
    | Ge -> "ge"
    | Eq -> "eq"
    | Ne -> "ne"
    | LAnd -> "land"
    | LOr -> "lor"
  in

  let string_of_unop = function
    | UMinus -> "uminus"
    | UNot -> "unot"
    | UPlus -> "uplus"
  in

  let string_of_place = function
    | Tcg.Local id -> Printf.sprintf "local:%d" id
    | Tcg.Global name -> Printf.sprintf "global:%s" name
  in

  let rec dump_operand depth seen (dump_block : Cfg.block) operand =
    if depth > 7 then
      Printf.eprintf
        "counted-poly-tree depth=%d block=%s operand=%s kind=<depth-limit>\n%!"
        depth dump_block.label (string_of_operand operand)
    else
      let resolved = resolve_block_operand dump_block operand in
      match resolved with
      | Tcg.Imm value ->
          Printf.eprintf
            "counted-poly-tree depth=%d block=%s operand=%s resolved=%Ld kind=imm\n%!"
            depth dump_block.label (string_of_operand operand) value
      | Tcg.Temp temp ->
          if IntSet.mem temp seen then
            Printf.eprintf
              "counted-poly-tree depth=%d block=%s operand=%s resolved=t%d kind=cycle multi=%b\n%!"
              depth dump_block.label (string_of_operand operand) temp
              (IntSet.mem temp multi_defs)
          else
            let seen = IntSet.add temp seen in
            let def_with_block =
              match last_def_of_temp dump_block temp with
              | Some instr ->
                  Some (dump_block, instr)
              | None -> (
                  match
                    ( Hashtbl.find_opt def_blocks temp,
                      Hashtbl.find_opt def_instrs temp )
                  with
                  | Some label, Some instr ->
                      Some (get_block label, instr)
                  | _ ->
                      None)
            in
            match def_with_block with
            | None ->
                Printf.eprintf
                  "counted-poly-tree depth=%d block=%s operand=%s resolved=t%d kind=<no-def> multi=%b\n%!"
                  depth dump_block.label (string_of_operand operand) temp
                  (IntSet.mem temp multi_defs)
            | Some (def_block, instr) -> (
                match instr with
                | Tcg.Move (_, src) ->
                    Printf.eprintf
                      "counted-poly-tree depth=%d block=%s operand=%s resolved=t%d defblock=%s kind=move src=%s multi=%b\n%!"
                      depth dump_block.label (string_of_operand operand) temp
                      def_block.label (string_of_operand src)
                      (IntSet.mem temp multi_defs);
                    dump_operand (depth + 1) seen def_block src

                | Tcg.Un (_, op, src) ->
                    Printf.eprintf
                      "counted-poly-tree depth=%d block=%s operand=%s resolved=t%d defblock=%s kind=%s src=%s multi=%b\n%!"
                      depth dump_block.label (string_of_operand operand) temp
                      def_block.label (string_of_unop op)
                      (string_of_operand src)
                      (IntSet.mem temp multi_defs);
                    dump_operand (depth + 1) seen def_block src

                | Tcg.Bin (_, op, lhs, rhs) ->
                    Printf.eprintf
                      "counted-poly-tree depth=%d block=%s operand=%s resolved=t%d defblock=%s kind=%s lhs=%s rhs=%s multi=%b\n%!"
                      depth dump_block.label (string_of_operand operand) temp
                      def_block.label (string_of_binop op)
                      (string_of_operand lhs)
                      (string_of_operand rhs)
                      (IntSet.mem temp multi_defs);
                    dump_operand (depth + 1) seen def_block lhs;
                    dump_operand (depth + 1) seen def_block rhs

                | Tcg.Load (_, place) ->
                    Printf.eprintf
                      "counted-poly-tree depth=%d block=%s operand=%s resolved=t%d defblock=%s kind=load place=%s multi=%b\n%!"
                      depth dump_block.label (string_of_operand operand) temp
                      def_block.label (string_of_place place)
                      (IntSet.mem temp multi_defs)

                | Tcg.Store (place, value) ->
                    Printf.eprintf
                      "counted-poly-tree depth=%d block=%s operand=%s resolved=t%d defblock=%s kind=store place=%s value=%s multi=%b\n%!"
                      depth dump_block.label (string_of_operand operand) temp
                      def_block.label (string_of_place place)
                      (string_of_operand value)
                      (IntSet.mem temp multi_defs)

                | Tcg.Call (_, callee, args) ->
                    Printf.eprintf
                      "counted-poly-tree depth=%d block=%s operand=%s resolved=t%d defblock=%s kind=call callee=%s argc=%d multi=%b\n%!"
                      depth dump_block.label (string_of_operand operand) temp
                      def_block.label callee (List.length args)
                      (IntSet.mem temp multi_defs))
  in

  let result =
    match parsed with
    | Some (LinearInvariant expr) ->
        Some (ReductionInvariant expr)
    | Some (LinearAffine { iv; coeff; bias })
      when not (summary_expr_is_zero coeff) ->
        Some (ReductionAffine { iv; coeff; bias })
    | Some (LinearAffine _) ->
        None
    | Some (LinearQuadratic { iv; quad; triangle; coeff; bias })
      when not (summary_expr_is_zero quad && summary_expr_is_zero triangle) ->
        Some (ReductionQuadratic { iv; quad; triangle; coeff; bias })
    | Some (LinearQuadratic _) ->
        None
    | Some (LinearCubic { iv; choose3; triangle; coeff; bias })
      when not (summary_expr_is_zero choose3) ->
        Some (ReductionCubic { iv; choose3; triangle; coeff; bias })
    | Some (LinearCubic _) ->
        None
    | None ->
        None
  in

  if debug_enabled && Option.is_none result then begin
    Printf.eprintf
      "counted-poly-fail block=%s operand=%s parsed=%s\n%!"
      block.label
      (string_of_operand operand)
      (match parsed with
       | None -> "none"
       | Some (LinearInvariant _) -> "invariant-zero-or-unsupported"
       | Some (LinearAffine _) -> "affine-zero"
       | Some (LinearQuadratic _) -> "quadratic-zero"
       | Some (LinearCubic _) -> "cubic-zero");
    dump_operand 0 IntSet.empty block operand
  end;

  result

let reduction_update_of_temp
    invariant_loaded_places
    loop_defs
    def_blocks
    get_block
    loop_stable_phis
    multi_defs
    def_instrs
    ivs
    phi_temp
    (block : Cfg.block)
    temp
  =
  let invariant operand =
    operand_loop_invariant
      loop_defs loop_stable_phis multi_defs def_instrs IntSet.empty operand
  in
  let rec of_operand block seen = function
    | Tcg.Imm _ -> None
    | Tcg.Temp temp as operand ->
        if temp = phi_temp then None
        else if IntSet.mem temp seen || IntSet.mem temp multi_defs then None
        else
          match last_def_of_temp block temp with
          | Some instr -> of_instr block (IntSet.add temp seen) instr
          | None ->
              if invariant operand then None
              else
                match Hashtbl.find_opt def_instrs temp with
                | Some instr -> (
                    match Hashtbl.find_opt def_blocks temp with
                    | Some label -> of_instr (get_block label) (IntSet.add temp seen) instr
                    | None -> None)
                | None -> None
  and of_instr block seen = function
    | Tcg.Move (_, src) -> of_operand block seen (resolve_block_operand block src)
    | Tcg.Bin (_, Add, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        if resolves_to_induction_temp multi_defs def_instrs phi_temp lhs then
          Option.map
            (fun step ->
              {
                target = ReductionTempTarget phi_temp;
                subtract = false;
                step;
                carrier_temp = None;
                alias_temps = [];
              })
            (reduction_step_of_operand
               invariant_loaded_places
               loop_defs
               def_blocks
               get_block
               loop_stable_phis
               multi_defs
               def_instrs
               ivs
               block rhs)
        else if resolves_to_induction_temp multi_defs def_instrs phi_temp rhs then
          Option.map
            (fun step ->
              {
                target = ReductionTempTarget phi_temp;
                subtract = false;
                step;
                carrier_temp = None;
                alias_temps = [];
              })
            (reduction_step_of_operand
               invariant_loaded_places
               loop_defs
               def_blocks
               get_block
               loop_stable_phis
               multi_defs
               def_instrs
               ivs
               block lhs)
        else None
    | Tcg.Bin (_, Sub, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        if resolves_to_induction_temp multi_defs def_instrs phi_temp lhs then
          Option.map
            (fun step ->
              {
                target = ReductionTempTarget phi_temp;
                subtract = true;
                step;
                carrier_temp = None;
                alias_temps = [];
              })
            (reduction_step_of_operand
               invariant_loaded_places
               loop_defs
               def_blocks
               get_block
               loop_stable_phis
               multi_defs
               def_instrs
               ivs
               block rhs)
        else None
    | Tcg.Un _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ | Tcg.Bin _ -> None
  in
  match last_def_of_temp block temp with
  | Some (Tcg.Move (_, src)) -> of_operand block IntSet.empty (resolve_block_operand block src)
  | Some instr -> of_instr block IntSet.empty instr
  | None -> of_operand block IntSet.empty (Tcg.Temp temp)

let rec operand_resolves_to_place_value multi_defs place (block : Cfg.block) seen = function
  | Tcg.Imm _ -> false
  | Tcg.Temp _ as operand ->
      let operand = resolve_block_operand block operand in
      (match operand with
      | Tcg.Imm _ -> false
      | Tcg.Temp temp ->
          if IntSet.mem temp seen || IntSet.mem temp multi_defs then false
          else
            match last_def_of_temp block temp with
            | Some (Tcg.Load (_, loaded_place)) -> loaded_place = place
            | Some (Tcg.Move (_, src)) ->
                operand_resolves_to_place_value multi_defs place block (IntSet.add temp seen) src
            | Some _ | None -> false)

let last_store_of_place place (block : Cfg.block) =
  let last = ref None in
  List.iteri
    (fun index instr ->
      match instr with
      | Tcg.Store (stored_place, value) when stored_place = place -> last := Some (index, value)
      | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> ())
    block.body;
  !last

let reduction_update_of_place
    invariant_loaded_places
    loop_defs
    def_blocks
    get_block
    loop_stable_phis
    multi_defs
    def_instrs
    ivs
    place
    (block : Cfg.block)
  =
  let reduction_step_of_linear_expr = function
    | LinearInvariant expr ->
        if summary_expr_is_zero expr then None
        else Some (ReductionInvariant expr)
    | LinearAffine { iv; coeff; bias } ->
        if summary_expr_is_zero coeff then
          if summary_expr_is_zero bias then None
          else Some (ReductionInvariant bias)
        else
          Some (ReductionAffine { iv; coeff; bias })
    | LinearQuadratic { iv; quad; triangle; coeff; bias } ->
        if summary_expr_is_zero quad && summary_expr_is_zero triangle then
          if summary_expr_is_zero coeff then
            if summary_expr_is_zero bias then None
            else Some (ReductionInvariant bias)
          else
            Some (ReductionAffine { iv; coeff; bias })
        else
          Some (ReductionQuadratic { iv; quad; triangle; coeff; bias })
    | LinearCubic { iv; choose3; triangle; coeff; bias } ->
        if summary_expr_is_zero choose3 then
          if summary_expr_is_zero triangle then
            if summary_expr_is_zero coeff then
              if summary_expr_is_zero bias then None
              else Some (ReductionInvariant bias)
            else
              Some (ReductionAffine { iv; coeff; bias })
          else
            Some
              (ReductionQuadratic
                 {
                   iv;
                   quad = zero_summary_expr;
                   triangle;
                   coeff;
                   bias;
                 })
        else
          Some (ReductionCubic { iv; choose3; triangle; coeff; bias })
  in
  let nested_additive_place_step block lhs rhs =
    let add_deltas lhs rhs =
      match (lhs, rhs) with
      | None, None -> Some None
      | Some expr, None
      | None, Some expr ->
          Some (Some expr)
      | Some lhs, Some rhs ->
          Option.map
            (fun expr -> Some expr)
            (linear_expr_add lhs rhs)
    in
    let combine_parts lhs rhs =
      Option.bind lhs (fun (lhs_self, lhs_delta) ->
          Option.bind rhs (fun (rhs_self, rhs_delta) ->
              if lhs_self && rhs_self then None
              else
                Option.map
                  (fun delta -> (lhs_self || rhs_self, delta))
                  (add_deltas lhs_delta rhs_delta)))
    in
    let rec split seen operand =
      if
        operand_resolves_to_place_value
          multi_defs place block IntSet.empty operand
      then
        Some (true, None)
      else
        match
          linear_expr_of_operand
            invariant_loaded_places
            loop_defs
            def_blocks
            get_block
            loop_stable_phis
            multi_defs
            def_instrs
            ivs
            block
            operand
        with
        | Some expr -> Some (false, Some expr)
        | None -> (
            match operand with
            | Tcg.Imm _ -> None
            | Tcg.Temp current ->
                if
                  IntSet.mem current seen
                  || IntSet.mem current multi_defs
                then
                  None
                else
                  let seen = IntSet.add current seen in
                  match last_def_of_temp block current with
                  | Some (Tcg.Move (_, src))
                  | Some (Tcg.Un (_, UPlus, src)) ->
                      split seen src
                  | Some (Tcg.Bin (_, Add, def_lhs, def_rhs)) ->
                      combine_parts
                        (split seen def_lhs)
                        (split seen def_rhs)
                  | Some (Tcg.Un _)
                  | Some (Tcg.Bin _)
                  | Some (Tcg.Load _)
                  | Some (Tcg.Store _)
                  | Some (Tcg.Call _)
                  | None ->
                      None)
    in
    match
      combine_parts
        (split IntSet.empty lhs)
        (split IntSet.empty rhs)
    with
    | Some (true, Some delta) ->
        reduction_step_of_linear_expr delta
    | Some (true, None)
    | Some (false, _)
    | None ->
        None
  in
  let rec of_operand block seen = function
    | Tcg.Imm _ -> None
    | Tcg.Temp _ as operand ->
        let operand = resolve_block_operand block operand in
        (match operand with
        | Tcg.Imm _ -> None
        | Tcg.Temp temp ->
            if IntSet.mem temp seen || IntSet.mem temp multi_defs then None
            else
              match last_def_of_temp block temp with
              | Some (Tcg.Move (_, src)) -> of_operand block (IntSet.add temp seen) src
              | Some instr -> of_instr block (IntSet.add temp seen) instr
              | None -> None)
  and of_instr block seen = function
    | Tcg.Move (_, src) -> of_operand block seen (resolve_block_operand block src)
    | Tcg.Bin (_, Add, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        if operand_resolves_to_place_value multi_defs place block IntSet.empty lhs then
          Option.map
            (fun step ->
              {
                target = ReductionPlaceTarget place;
                subtract = false;
                step;
                carrier_temp = None;
                alias_temps = [];
              })
            (reduction_step_of_operand
               invariant_loaded_places
               loop_defs
               def_blocks
               get_block
               loop_stable_phis
               multi_defs
               def_instrs
               ivs
               block rhs)
        else if operand_resolves_to_place_value multi_defs place block IntSet.empty rhs then
          Option.map
            (fun step ->
              {
                target = ReductionPlaceTarget place;
                subtract = false;
                step;
                carrier_temp = None;
                alias_temps = [];
              })
            (reduction_step_of_operand
               invariant_loaded_places
               loop_defs
               def_blocks
               get_block
               loop_stable_phis
               multi_defs
               def_instrs
               ivs
               block lhs)
        else
          Option.map
            (fun step ->
              {
                target = ReductionPlaceTarget place;
                subtract = false;
                step;
                carrier_temp = None;
                alias_temps = [];
              })
            (nested_additive_place_step block lhs rhs)
    | Tcg.Bin (_, Sub, lhs, rhs) ->
        let lhs = resolve_block_operand block lhs in
        let rhs = resolve_block_operand block rhs in
        if operand_resolves_to_place_value multi_defs place block IntSet.empty lhs then
          Option.map
            (fun step ->
              {
                target = ReductionPlaceTarget place;
                subtract = true;
                step;
                carrier_temp = None;
                alias_temps = [];
              })
            (reduction_step_of_operand
               invariant_loaded_places
               loop_defs
               def_blocks
               get_block
               loop_stable_phis
               multi_defs
               def_instrs
               ivs
               block rhs)
        else None
    | Tcg.Un _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ | Tcg.Bin _ -> None
  in
  match last_store_of_place place block with
  | Some (store_index, value) ->
      let rec take_prefix index acc = function
        | [] -> List.rev acc
        | _ when index <= 0 -> List.rev acc
        | instr :: rest ->
            take_prefix (index - 1) (instr :: acc) rest
      in
      let point_block =
        { block with body = take_prefix store_index [] block.body }
      in
      of_operand point_block IntSet.empty value
  | None -> None

let collect_counted_reductions
    ?recurrence_facts
    header
    loop
    invariant_loaded_places
    loop_defs
    get_block
    def_blocks
    loop_stable_phis
    multi_defs
    def_instrs
    ivs
    excluded_temps
    live_temps
    live_places
  =
  let debug_counted_local = Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None in
  let string_of_temps set =
    IntSet.elements set |> List.map string_of_int |> String.concat ","
  in
  let string_of_operand = function
    | Tcg.Imm n -> Int64.to_string n
    | Tcg.Temp t -> Printf.sprintf "t%d" t
  in
  let string_of_binop = function
    | Add -> "add"
    | Sub -> "sub"
    | Mul -> "mul"
    | Div -> "div"
    | Mod -> "mod"
    | Lt -> "lt"
    | Le -> "le"
    | Gt -> "gt"
    | Ge -> "ge"
    | Eq -> "eq"
    | Ne -> "ne"
    | LAnd -> "land"
    | LOr -> "lor"
  in
  let string_of_unop = function
    | UMinus -> "uminus"
    | UNot -> "unot"
    | UPlus -> "uplus"
  in
  let string_of_place = function
    | Tcg.Local id -> Printf.sprintf "local:%d" id
    | Tcg.Global name -> Printf.sprintf "global:%s" name
  in
  let string_of_simple_instr = function
    | Tcg.Move (dst, src) ->
        Printf.sprintf "t%d=move(%s)" dst (string_of_operand src)
    | Tcg.Un (dst, op, src) ->
        Printf.sprintf "t%d=%s(%s)"
          dst (string_of_unop op) (string_of_operand src)
    | Tcg.Bin (dst, op, lhs, rhs) ->
        Printf.sprintf "t%d=%s(%s,%s)"
          dst
          (string_of_binop op)
          (string_of_operand lhs)
          (string_of_operand rhs)
    | Tcg.Load (dst, place) ->
        Printf.sprintf "t%d=load(%s)" dst (string_of_place place)
    | Tcg.Store (place, value) ->
        Printf.sprintf "store(%s,%s)"
          (string_of_place place)
          (string_of_operand value)
    | Tcg.Call (dst, callee, args) ->
        let dst =
          match dst with
          | None -> "_"
          | Some temp -> Printf.sprintf "t%d" temp
        in
        Printf.sprintf "%s=call(%s,%s)"
          dst
          callee
          (args |> List.map string_of_operand |> String.concat ",")
  in
  let debug_operand_def operand =
    match operand with
    | Tcg.Imm _ -> "imm"
    | Tcg.Temp temp -> (
        match Hashtbl.find_opt def_instrs temp with
        | Some (Tcg.Move (_, src)) -> Printf.sprintf "move(%s)" (string_of_operand src)
        | Some (Tcg.Un (_, op, src)) ->
            Printf.sprintf "%s(%s)" (string_of_unop op) (string_of_operand src)
        | Some (Tcg.Bin (_, op, lhs, rhs)) ->
            Printf.sprintf "%s(%s,%s)" (string_of_binop op) (string_of_operand lhs)
              (string_of_operand rhs)
        | Some (Tcg.Load _) -> "load"
        | Some (Tcg.Store _) -> "store"
        | Some (Tcg.Call _) -> "call"
        | None -> "none")
  in
  let logical_phis =
    recover_logical_loop_phis
      header loop get_block multi_defs
  in
  let recurrence_facts =
    match recurrence_facts with
    | Some facts ->
        facts
    | None ->
        let addrecs =
          analyze_loop_addrecs
            header loop get_block
            loop_defs multi_defs def_instrs
        in
        build_recurrence_facts
          header loop get_block
          loop_defs multi_defs def_instrs addrecs
  in
  let header_block : Cfg.block = get_block header in
  let outside_preds = List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds in
  let backedge_preds = List.filter (fun pred -> LabelSet.mem pred loop) header_block.preds in
  let phi_chain_for_pred pred = incoming_phi_chain get_block header pred in
  let outside_seed_chain_for_pred pred =
    extend_counted_outside_seed_chain
      get_block loop (phi_chain_for_pred pred)
  in
  let update_chain_for_pred pred =
    if LabelSet.mem pred loop then incoming_update_chain get_block header pred
    else phi_chain_for_pred pred
  in
  let resolve_on_update_chain block older_chain operand =
    resolve_chain_operand (block :: older_chain) (resolve_block_operand block operand)
  in
  let agree_all = function
    | [] -> None
    | first :: rest -> if List.for_all (( = ) first) rest then Some first else None
  in
  let anchor_iv =
    match List.filter (fun (iv : basic_induction_var) -> Int64.abs iv.step = 1L) ivs with
    | [ iv ] -> Some iv
    | _ -> None
  in
  let expand_chain_move_aliases chain initial =
    let rec saturate seen =
      let next =
        List.fold_left
          (fun seen (block : Cfg.block) ->
            List.fold_left
              (fun seen instr ->
                match instr with
                | Tcg.Move (dst, Tcg.Temp src)
                | Tcg.Un (dst, UPlus, Tcg.Temp src) when IntSet.mem src seen -> IntSet.add dst seen
                | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> seen)
              seen block.body)
          seen chain
      in
      if IntSet.equal next seen then seen else saturate next
    in
    saturate initial
  in
  let self_temps_on_chain seed_temp chain =
    let rec collect seen = function
      | [] -> seen
      | current :: rest when IntSet.mem current seen -> collect seen rest
      | current :: rest ->
          let seen = IntSet.add current seen in
          let pushed =
            match def_instr_on_chain_or_global chain multi_defs def_instrs current with
            | Some (Tcg.Move (_, Tcg.Temp src))
            | Some (Tcg.Un (_, UPlus, Tcg.Temp src)) ->
                src :: rest
            | Some _ | None -> rest
          in
          collect seen pushed
    in
    collect IntSet.empty [ seed_temp ] |> expand_chain_move_aliases chain
  in
  let direct_simple_invariant_reduction_of_temp_on_chain source_temp chain =
    let self_temps = self_temps_on_chain source_temp chain in
    let rec resolves_to_self block older_chain seen operand =
      let operand = resolve_on_update_chain block older_chain operand in
      match operand with
      | Tcg.Imm _ -> false
      | Tcg.Temp current ->
          if IntSet.mem current self_temps then true
          else if IntSet.mem current seen then false
          else
            match last_def_of_temp block current with
            | Some (Tcg.Move (_, src))
            | Some (Tcg.Un (_, UPlus, src)) ->
                resolves_to_self block older_chain (IntSet.add current seen) src
            | Some _ -> false
            | None -> (
                match last_def_of_temp_on_chain_with_block older_chain current with
                | Some (older_block, Tcg.Move (_, src), older_rest)
                | Some (older_block, Tcg.Un (_, UPlus, src), older_rest) ->
                    resolves_to_self older_block older_rest (IntSet.add current seen) src
                | Some _ | None -> false)
    in
    let rec of_operand block older_chain seen = function
      | Tcg.Imm _ -> None
      | Tcg.Temp _ as operand ->
          let operand = resolve_on_update_chain block older_chain operand in
          (match operand with
          | Tcg.Imm _ -> None
          | Tcg.Temp current ->
              if IntSet.mem current seen || IntSet.mem current multi_defs then None
              else
                match last_def_of_temp block current with
                | Some instr -> of_instr block older_chain (IntSet.add current seen) instr
                | None -> (
                    match last_def_of_temp_on_chain_with_block older_chain current with
                    | Some (older_block, instr, older_rest) ->
                        of_instr older_block older_rest (IntSet.add current seen) instr
                    | None -> None))
    and of_instr block older_chain seen = function
      | Tcg.Move (_, src) -> of_operand block older_chain seen (resolve_on_update_chain block older_chain src)
      | Tcg.Bin (_, Add, lhs, rhs) ->
          let lhs = resolve_on_update_chain block older_chain lhs in
          let rhs = resolve_on_update_chain block older_chain rhs in
          if resolves_to_self block older_chain IntSet.empty lhs then
            Option.bind
              (summary_expr_of_operand
                 invariant_loaded_places
                 loop_defs
                 def_blocks
                 get_block
                 loop_stable_phis
                 multi_defs
                 def_instrs
                 block
                 rhs)
              (function
                | SummaryOperand (Tcg.Imm 0L) -> None
                | step_expr ->
                    Some
                      {
                        target = ReductionTempTarget source_temp;
                        subtract = false;
                        step = ReductionInvariant step_expr;
                        carrier_temp = None;
                        alias_temps = [];
                      })
          else if resolves_to_self block older_chain IntSet.empty rhs then
            Option.bind
              (summary_expr_of_operand
                 invariant_loaded_places
                 loop_defs
                 def_blocks
                 get_block
                 loop_stable_phis
                 multi_defs
                 def_instrs
                 block
                 lhs)
              (function
                | SummaryOperand (Tcg.Imm 0L) -> None
                | step_expr ->
                    Some
                      {
                        target = ReductionTempTarget source_temp;
                        subtract = false;
                        step = ReductionInvariant step_expr;
                        carrier_temp = None;
                        alias_temps = [];
                      })
          else None
      | Tcg.Bin (_, Sub, lhs, rhs) ->
          let lhs = resolve_on_update_chain block older_chain lhs in
          let rhs = resolve_on_update_chain block older_chain rhs in
          if resolves_to_self block older_chain IntSet.empty lhs then
            Option.bind
              (summary_expr_of_operand
                 invariant_loaded_places
                 loop_defs
                 def_blocks
                 get_block
                 loop_stable_phis
                 multi_defs
                 def_instrs
                 block
                 rhs)
              (function
                | SummaryOperand (Tcg.Imm 0L) -> None
                | step_expr ->
                    Some
                      {
                        target = ReductionTempTarget source_temp;
                        subtract = true;
                        step = ReductionInvariant step_expr;
                        carrier_temp = None;
                        alias_temps = [];
                      })
          else None
      | Tcg.Un _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ | Tcg.Bin _ -> None
    in
    match last_def_of_temp_on_chain_with_block chain source_temp with
    | Some (block, Tcg.Move (_, src), older_chain) ->
        of_operand block older_chain IntSet.empty (resolve_on_update_chain block older_chain src)
    | Some (block, instr, older_chain) -> of_instr block older_chain IntSet.empty instr
    | None -> None
  in
  let carrier_progression_of_operand block older_chain operand =
    let rec of_operand block older_chain seen = function
      | Tcg.Imm _ -> None
      | Tcg.Temp _ as operand ->
          let operand = resolve_on_update_chain block older_chain operand in
          (match operand with
          | Tcg.Imm _ -> None
          | Tcg.Temp current ->
              if debug_counted_local then
                Printf.eprintf
                  "counted-carrier-of-operand header=%s current=t%d def=%s seen=%b\n%!"
                  header current (debug_operand_def (Tcg.Temp current)) (IntSet.mem current seen);
              if IntSet.mem current seen then None
              else
                match last_def_of_temp block current with
                | Some (Tcg.Move (_, src))
                | Some (Tcg.Un (_, UPlus, src)) ->
                    of_operand block older_chain (IntSet.add current seen) src
                | Some instr -> of_instr block older_chain (IntSet.add current seen) instr
                | None -> (
                    match last_def_of_temp_on_chain_with_block older_chain current with
                    | Some (older_block, Tcg.Move (_, src), older_rest)
                    | Some (older_block, Tcg.Un (_, UPlus, src), older_rest) ->
                        of_operand older_block older_rest (IntSet.add current seen) src
                    | Some (older_block, instr, older_rest) ->
                        of_instr older_block older_rest (IntSet.add current seen) instr
                    | None -> (
                        match older_chain with
                        | (join_block : Cfg.block) :: _
                          when List.length join_block.preds > 1 ->
                            let pred_results =
                              List.map
                                (fun pred ->
                                  let pred_chain = incoming_update_chain get_block join_block.label pred in
                                  match last_def_of_temp_on_chain_with_block pred_chain current with
                                  | Some (pred_block, Tcg.Move (_, src), pred_rest)
                                  | Some (pred_block, Tcg.Un (_, UPlus, src), pred_rest) ->
                                      of_operand pred_block pred_rest (IntSet.add current seen) src
                                  | Some (pred_block, instr, pred_rest) ->
                                      of_instr pred_block pred_rest (IntSet.add current seen) instr
                                  | None -> None)
                                join_block.preds
                            in
                            Option.value (agree_all pred_results) ~default:None
                        | _ -> (
                            match Hashtbl.find_opt def_instrs current with
                            | Some instr -> (
                                match Hashtbl.find_opt def_blocks current with
                                | Some label -> (
                                    match chain_rest_from_label older_chain label with
                                    | Some (def_block, older_rest) ->
                                        of_instr def_block older_rest (IntSet.add current seen) instr
                                    | None -> of_instr (get_block label) [] (IntSet.add current seen) instr)
                                | None -> None)
                            | None -> None))))
    and of_instr block _older_chain _seen = function
      | Tcg.Bin (_, Add, lhs, rhs) -> (
          let lhs = resolve_on_update_chain block older_chain lhs in
          let rhs = resolve_on_update_chain block older_chain rhs in
          if debug_counted_local then
            Printf.eprintf
              "counted-carrier-try header=%s add lhs=%s rhs=%s\n%!"
              header (string_of_operand lhs) (string_of_operand rhs);
          match (lhs, rhs) with
          | Tcg.Temp carrier_temp, _ when Option.is_some (summary_expr_of_operand
                                        invariant_loaded_places
                                        loop_defs
                                        def_blocks
                                        get_block
                                        loop_stable_phis
                                        multi_defs
                                        def_instrs
                                        block
                                        rhs) ->
              Option.map
                (fun step_expr -> (carrier_temp, step_expr, false, true))
                (summary_expr_of_operand
                   invariant_loaded_places
                   loop_defs
                   def_blocks
                   get_block
                   loop_stable_phis
                   multi_defs
                   def_instrs
                   block
                   rhs)
          | _, Tcg.Temp carrier_temp when Option.is_some (summary_expr_of_operand
                                        invariant_loaded_places
                                        loop_defs
                                        def_blocks
                                        get_block
                                        loop_stable_phis
                                        multi_defs
                                        def_instrs
                                        block
                                        lhs) ->
              Option.map
                (fun step_expr -> (carrier_temp, step_expr, false, true))
                (summary_expr_of_operand
                   invariant_loaded_places
                   loop_defs
                   def_blocks
                   get_block
                   loop_stable_phis
                   multi_defs
                   def_instrs
                   block
                   lhs)
          | _ ->
              if debug_counted_local then
                Printf.eprintf "counted-carrier-miss header=%s add\n%!" header;
              None)
      | Tcg.Bin (_, Sub, lhs, rhs) -> (
          let lhs = resolve_on_update_chain block older_chain lhs in
          let rhs = resolve_on_update_chain block older_chain rhs in
          if debug_counted_local then
            Printf.eprintf
              "counted-carrier-try header=%s sub lhs=%s rhs=%s\n%!"
              header (string_of_operand lhs) (string_of_operand rhs);
          match (lhs, rhs) with
          | Tcg.Temp carrier_temp, _ ->
              Option.map
                (fun step_expr -> (carrier_temp, step_expr, true, true))
                (summary_expr_of_operand
                   invariant_loaded_places
                   loop_defs
                   def_blocks
                   get_block
                   loop_stable_phis
                   multi_defs
                   def_instrs
                   block
                   rhs)
          | _ ->
              if debug_counted_local then
                Printf.eprintf "counted-carrier-miss header=%s sub\n%!" header;
              None)
      | Tcg.Move _ | Tcg.Un _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ | Tcg.Bin _ -> None
    in
    of_operand block older_chain IntSet.empty operand
  in
  let dependent_affine_step_of_operand block older_chain operand =
    match anchor_iv with
    | None -> None
    | Some anchor_iv -> (
        match resolve_on_update_chain block older_chain operand with
        | Tcg.Imm _ -> None
        | Tcg.Temp source_temp ->
            if IntSet.mem source_temp excluded_temps then None
            else if
              not
                (List.for_all
                   (fun pred -> Option.is_some (last_def_of_temp_on_chain (phi_chain_for_pred pred) source_temp))
                   outside_preds)
            then None
            else
              match direct_simple_invariant_reduction_of_temp_on_chain source_temp older_chain with
              | Some
                  {
                    target = ReductionTempTarget _;
                    subtract = source_subtract;
                    step = ReductionInvariant source_step;
                    _;
                  } ->
                  let coeff =
                    let coeff = if source_subtract then summary_expr_neg source_step else source_step in
                    if anchor_iv.step < 0L then summary_expr_neg coeff else coeff
                  in
                  let source_current = SummaryOperand (Tcg.Temp source_temp) in
                  let iv_current = SummaryOperand (Tcg.Temp anchor_iv.phi_temp) in
                  let bias = summary_expr_sub source_current (summary_expr_mul coeff iv_current) in
                  Some (anchor_iv, coeff, bias)
              | Some _ | None -> None)
  in

  (* A nested inner-summary may read an enclosing-loop carrier before that
     carrier is updated later on the same backedge:

       summary:  acc += carrier * inner_trip + ...
       latch:    carrier += invariant_step
                 iv      += 1

     Program-point operand resolution must NOT look through the later latch
     update.  However, proving the carrier's per-iteration recurrence does need
     to inspect that full backedge.

     Keep these roles separate:
       - [block]/the current prefix supplies the *current* carrier and IV values;
       - the full backedge chain is used only to prove
           carrier_next = carrier + invariant_step.

     Restrict this fallback to a single backedge.  Multi-backedge recurrence
     agreement remains handled by the existing path/logical-PHI machinery. *)
  let dependent_affine_step_from_full_backedge
      block operand =
    match backedge_preds with
    | [ pred ] -> (
        match
          dependent_affine_step_of_operand
            block
            (update_chain_for_pred pred)
            operand
        with
        | Some (iv, _, _) as result ->
            if
              Sys.getenv_opt
                "TOYC_DEBUG_RECURRENCE_REDUCTION"
              <> None
            then
              Printf.eprintf
                "recurrence-carrier-full-backedge-hit header=%s block=%s anchor=t%d pred=%s\n%!"
                header block.label iv.phi_temp pred;
            result
        | None ->
            None)
    | [] | _ :: _ :: _ ->
        None
  in
  let rec summary_expr_of_loop_inv_expr = function
    | LveConst value ->
        SummaryOperand (Tcg.Imm value)
    | LveOperand operand ->
        SummaryOperand operand
    | LveNeg inner ->
        SummaryUn
          (UMinus, summary_expr_of_loop_inv_expr inner)
    | LveAdd (lhs, rhs) ->
        SummaryBin
          ( Add,
            summary_expr_of_loop_inv_expr lhs,
            summary_expr_of_loop_inv_expr rhs )
    | LveMul (lhs, rhs) ->
        SummaryBin
          ( Mul,
            summary_expr_of_loop_inv_expr lhs,
            summary_expr_of_loop_inv_expr rhs )
  in
  let counted_iv_of_addrec (addrec : loop_addrec) =
    List.find_opt
      (fun (iv : basic_induction_var) ->
        iv.origin = `Syntactic
        && iv.phi_temp = addrec.addrec_phi_temp
        && loop_inv_expr_equal
             addrec.addrec_step
             (LveConst iv.step))
      ivs
  in
  let common_addrec_seed_expr (addrec : loop_addrec) =
    let expr_of_operand operand =
      lve_invariant_expr_of_operand
        loop_defs multi_defs def_instrs operand
      |> Option.map normalize_loop_inv_expr
    in
    (* [recover_logical_loop_phis] deliberately records logical outside
       inputs as [(pred, Temp phi_temp)] placeholders.  They describe the
       logical PHI identity, not the concrete entry-edge value.

       Resolve those placeholders through the actual incoming edge before
       asking whether the seed is loop-invariant.  This is the same
       edge-sensitive seed recovery already used when converting a semantic
       AddRec into a basic IV. *)
    match
      scalar_outside_inputs
        header loop get_block addrec
    with
    | None ->
        None
    | Some [] ->
        None
    | Some ((_, first_operand) :: rest) ->
        Option.bind
          (expr_of_operand first_operand)
          (fun first ->
            let rec agree = function
              | [] ->
                  Some first
              | (_, operand) :: tail -> (
                  match expr_of_operand operand with
                  | Some other
                    when loop_inv_expr_equal first other ->
                      agree tail
                  | Some _ | None ->
                      None)
            in
            agree rest)
  in

  (* Rebase a semantic AddRec onto the unique mature unit-step counted IV.

       anchor(k) = A0 + da*k,  da in {+1,-1}
       base(k)   = B0 + db*k
       value(k)  = scale*base(k) + bias

     therefore

       value = (scale*db*da) * anchor
             + scale*(B0 - db*da*A0) + bias

     [recurrence_at] may already have phase-shifted either recurrence; its
     affine bias is included below.  We additionally query the anchor at the
     same exact program point, so a phase mismatch/conflict is rejected rather
     than guessed. *)
  let rebase_scalar_recurrence_to_anchor point recurrence =
    match anchor_iv with
    | None ->
        None
    | Some anchor
      when Int64.abs anchor.step = 1L -> (
        match
          scalar_recurrence_scale_bias
            (normalize_scalar_recurrence recurrence),
          recurrence_at recurrence_facts point
            (Tcg.Temp anchor.phi_temp)
        with
        | Some (base, scale, bias),
          Some anchor_recurrence -> (
            match
              scalar_recurrence_scale_bias
                (normalize_scalar_recurrence anchor_recurrence)
            with
            | Some
                ( anchor_base,
                  anchor_scale,
                  anchor_bias )
              when
                loop_inv_expr_equal
                  anchor_scale scalar_inv_one
                && (match counted_iv_of_addrec anchor_base with
                    | Some counted ->
                        counted.phi_temp = anchor.phi_temp
                    | None ->
                        false) -> (
                match
                  ( common_addrec_seed_expr base,
                    common_addrec_seed_expr anchor_base )
                with
                | Some base_seed, Some anchor_seed ->
                    let direction = LveConst anchor.step in
                    let base_per_anchor =
                      normalize_loop_inv_expr
                        (LveMul
                           (base.addrec_step, direction))
                    in
                    let coeff =
                      normalize_loop_inv_expr
                        (LveMul (scale, base_per_anchor))
                    in
                    let anchor_effective_seed =
                      normalize_loop_inv_expr
                        (LveAdd (anchor_seed, anchor_bias))
                    in
                    let rebased_base_bias =
                      normalize_loop_inv_expr
                        (LveAdd
                           ( base_seed,
                             LveNeg
                               (LveMul
                                  ( base_per_anchor,
                                    anchor_effective_seed )) ))
                    in
                    let rebased_bias =
                      normalize_loop_inv_expr
                        (LveAdd
                           ( LveMul
                               (scale, rebased_base_bias),
                             bias ))
                    in
                    if
                      Sys.getenv_opt
                        "TOYC_DEBUG_RECURRENCE_REDUCTION"
                      <> None
                    then
                      Printf.eprintf
                        "recurrence-rebase-hit header=%s base=t%d anchor=t%d step=%s\n%!"
                        header
                        base.addrec_phi_temp
                        anchor.phi_temp
                        (string_of_loop_inv_expr
                           base.addrec_step);
                    Some
                      (LinearAffine
                         {
                           iv = anchor;
                           coeff =
                             summary_expr_of_loop_inv_expr coeff;
                           bias =
                             summary_expr_of_loop_inv_expr
                               rebased_bias;
                         })
                | _ ->
                    None)
            | Some _ | None ->
                None)
        | _ ->
            None)
    | Some _ ->
        None
  in

  let linear_expr_of_scalar_recurrence point recurrence =
    match normalize_scalar_recurrence recurrence with
    | ScalarConst value ->
        Some
          (LinearInvariant
             (SummaryOperand (Tcg.Imm (i32 value))))
    | ScalarInvariant expr ->
        Some
          (LinearInvariant
             (summary_expr_of_loop_inv_expr
                (normalize_loop_inv_expr expr)))
    | (ScalarAddRec _ | ScalarAffine _) as recurrence -> (
        match scalar_recurrence_scale_bias recurrence with
        | None ->
            None
        | Some (base, coeff, bias) -> (
            match counted_iv_of_addrec base with
            | Some iv ->
                Some
                  (LinearAffine
                     {
                       iv;
                       coeff =
                         summary_expr_of_loop_inv_expr
                           (normalize_loop_inv_expr coeff);
                       bias =
                         summary_expr_of_loop_inv_expr
                           (normalize_loop_inv_expr bias);
                     })
            | None ->
                rebase_scalar_recurrence_to_anchor
                  point recurrence))
  in
  let reduction_step_of_scalar_recurrence recurrence =
    match normalize_scalar_recurrence recurrence with
    | ScalarConst value ->
        if i32 value = 0L then None
        else
          Some
            (ReductionInvariant
               (SummaryOperand (Tcg.Imm (i32 value))))
    | ScalarInvariant expr ->
        let expr = normalize_loop_inv_expr expr in
        begin
          match expr with
          | LveConst value when i32 value = 0L ->
              None
          | LveConst _
          | LveOperand _
          | LveNeg _
          | LveAdd _
          | LveMul _ ->
              Some
                (ReductionInvariant
                   (summary_expr_of_loop_inv_expr expr))
        end
    | (ScalarAddRec _ | ScalarAffine _) as recurrence -> (
        match scalar_recurrence_scale_bias recurrence with
        | None -> None
        | Some (base, coeff, bias) ->
            Option.map
              (fun iv ->
                let coeff =
                  summary_expr_of_loop_inv_expr
                    (normalize_loop_inv_expr coeff)
                in
                let bias =
                  summary_expr_of_loop_inv_expr
                    (normalize_loop_inv_expr bias)
                in
                if
                  summary_expr_is_zero coeff
                  && summary_expr_is_zero bias
                then
                  ReductionInvariant zero_summary_expr
                else if summary_expr_is_zero coeff then
                  ReductionInvariant bias
                else
                  ReductionAffine { iv; coeff; bias })
              (counted_iv_of_addrec base))
  in
  let recurrence_point_before_prefix
      (block : Cfg.block) =
    let full_block : Cfg.block = get_block block.label in
    let visible_count =
      min
        (List.length block.body)
        (List.length full_block.body)
    in
    ( visible_count,
      RecurrenceBeforeInstr
        (block.label, visible_count) )
  in
  let semantic_linear_expr_at_point
      (block : Cfg.block) operand =
    let _, point = recurrence_point_before_prefix block in
    Option.bind
      (recurrence_at recurrence_facts point operand)
      (linear_expr_of_scalar_recurrence point)
  in

  (* Compose a freshly materialized inner-loop scalar transfer bottom-up.

     First reuse the mature polynomial parser (which now understands
     point-local invariant multi-def temps).  If one leaf is a symbolic AddRec,
     query it through [RecurrenceFacts], rebase it to the unique unit-step
     counted IV, then continue Add/Sub/Mul composition.

     Definitions are followed only through the visible prefix of the current
     block.  This prevents looking through a later update and changing the
     recurrence phase. *)
  let composed_linear_expr_at_point
      (start_block : Cfg.block) start_older_chain start_operand =
    let prefix_before_instr (block : Cfg.block) current_instr =
      let rec physical acc = function
        | [] -> None
        | instr :: rest ->
            if instr == current_instr then
              Some (List.rev acc)
            else
              physical (instr :: acc) rest
      in
      let rec structural acc best = function
        | [] -> best
        | instr :: rest ->
            let best =
              if instr = current_instr then
                Some (List.rev acc)
              else
                best
            in
            structural (instr :: acc) best rest
      in
      match physical [] block.body with
      | Some prefix ->
          prefix
      | None ->
          Option.value
            (structural [] None block.body)
            ~default:block.body
    in
    let rec analyze seen (block : Cfg.block) older_chain operand =
      match
        linear_expr_of_operand
          ~allow_local_multidef:true
          invariant_loaded_places
          loop_defs
          def_blocks
          get_block
          loop_stable_phis
          multi_defs
          def_instrs
          ivs
          block
          operand
      with
      | Some _ as result ->
          result
      | None -> (
          match semantic_linear_expr_at_point block operand with
          | Some _ as result ->
              result
          | None -> (
              match resolve_block_operand block operand with
              | Tcg.Imm _ ->
                  None
              | Tcg.Temp temp ->
                  if IntSet.mem temp seen then
                    None
                  else
                    match last_def_of_temp block temp with
                    | None -> (
                        let carrier =
                          match
                            dependent_affine_step_of_operand
                              block older_chain
                              (Tcg.Temp temp)
                          with
                          | Some _ as result ->
                              result
                          | None ->
                              dependent_affine_step_from_full_backedge
                                block
                                (Tcg.Temp temp)
                        in
                        match carrier with
                        | Some (iv, coeff, bias) ->
                            if
                              Sys.getenv_opt
                                "TOYC_DEBUG_RECURRENCE_REDUCTION"
                              <> None
                            then
                              Printf.eprintf
                                "recurrence-carrier-leaf-hit header=%s block=%s temp=t%d anchor=t%d\n%!"
                                header block.label temp iv.phi_temp;
                            Some
                              (LinearAffine
                                 { iv; coeff; bias })
                        | None ->
                            None)
                    | Some instr ->
                        let prefix =
                          prefix_before_instr block instr
                        in
                        let point_block =
                          { block with body = prefix }
                        in
                        let seen = IntSet.add temp seen in
                        match instr with
                        | Tcg.Move (_, src)
                        | Tcg.Un (_, UPlus, src) ->
                            analyze seen point_block older_chain src
                        | Tcg.Un (_, UMinus, src) ->
                            Option.map linear_expr_neg
                              (analyze seen point_block older_chain src)
                        | Tcg.Bin (_, Add, lhs, rhs) ->
                            Option.bind
                              (analyze seen point_block older_chain lhs)
                              (fun lhs_expr ->
                                Option.bind
                                  (analyze seen point_block older_chain rhs)
                                  (linear_expr_add lhs_expr))
                        | Tcg.Bin (_, Sub, lhs, rhs) ->
                            Option.bind
                              (analyze seen point_block older_chain lhs)
                              (fun lhs_expr ->
                                Option.bind
                                  (analyze seen point_block older_chain rhs)
                                  (linear_expr_sub lhs_expr))
                        | Tcg.Bin (_, Mul, lhs, rhs) ->
                            Option.bind
                              (analyze seen point_block older_chain lhs)
                              (fun lhs_expr ->
                                Option.bind
                                  (analyze seen point_block older_chain rhs)
                                  (linear_expr_mul lhs_expr))
                        | Tcg.Un (_, UNot, _)
                        | Tcg.Bin _
                        | Tcg.Load _
                        | Tcg.Store _
                        | Tcg.Call _ ->
                            None))
    in
    analyze IntSet.empty start_block start_older_chain start_operand
  in
  let semantic_reduction_step_at_point
      (block : Cfg.block) operand =
    let visible_count, point =
      recurrence_point_before_prefix block
    in
    match recurrence_at recurrence_facts point operand with
    | None -> None
    | Some recurrence -> (
        match
          reduction_step_of_scalar_recurrence recurrence
        with
        | None -> None
        | Some (ReductionInvariant expr)
          when summary_expr_is_zero expr ->
            None
        | Some _ as result ->
            if
              Sys.getenv_opt
                "TOYC_DEBUG_RECURRENCE_REDUCTION"
              <> None
            then
              Printf.eprintf
                "recurrence-reduction-hit kind=direct header=%s block=%s point=%d operand=%s recurrence=%s\n%!"
                header block.label visible_count
                (string_of_operand operand)
                (string_of_scalar_recurrence recurrence);
            result)
  in
  let reduction_update_of_temp_on_chain temp chain =
    let self_temps = self_temps_on_chain temp chain in
    let rec resolves_to_self block older_chain seen operand =
      let operand = resolve_on_update_chain block older_chain operand in
      match operand with
      | Tcg.Imm _ -> false
      | Tcg.Temp current ->
          if IntSet.mem current self_temps then true
          else if IntSet.mem current seen then false
          else
            match last_def_of_temp block current with
            | Some (Tcg.Move (_, src))
            | Some (Tcg.Un (_, UPlus, src)) ->
                resolves_to_self block older_chain (IntSet.add current seen) src
            | Some _ -> false
            | None -> (
                match last_def_of_temp_on_chain_with_block older_chain current with
                | Some (older_block, Tcg.Move (_, src), older_rest)
                | Some (older_block, Tcg.Un (_, UPlus, src), older_rest) ->
                    resolves_to_self older_block older_rest (IntSet.add current seen) src
                | Some _ | None -> false)
    in
    let rec peel_self_delta block older_chain seen = function
      | Tcg.Imm _ -> None
      | Tcg.Temp _ as operand -> (
          let operand = resolve_on_update_chain block older_chain operand in
          match operand with
          | Tcg.Imm _ -> None
          | Tcg.Temp current ->
              if IntSet.mem current seen then None
              else
                match last_def_of_temp block current with
                | Some (Tcg.Move (_, src))
                | Some (Tcg.Un (_, UPlus, src)) ->
                    peel_self_delta block older_chain (IntSet.add current seen) src
                | Some (Tcg.Bin (_, Add, lhs, rhs)) ->
                    let lhs = resolve_on_update_chain block older_chain lhs in
                    let rhs = resolve_on_update_chain block older_chain rhs in
                    if resolves_to_self block older_chain IntSet.empty lhs then Some rhs
                    else if resolves_to_self block older_chain IntSet.empty rhs then Some lhs
                    else None
                | Some instr -> (
                    match instr with
                    | Tcg.Move _ | Tcg.Un _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ | Tcg.Bin _ ->
                        None)
                | None -> (
                    match last_def_of_temp_on_chain_with_block older_chain current with
                    | Some (older_block, Tcg.Move (_, src), older_rest)
                    | Some (older_block, Tcg.Un (_, UPlus, src), older_rest) ->
                        peel_self_delta older_block older_rest (IntSet.add current seen) src
                    | Some (older_block, Tcg.Bin (_, Add, lhs, rhs), older_rest) ->
                        let lhs = resolve_on_update_chain older_block older_rest lhs in
                        let rhs = resolve_on_update_chain older_block older_rest rhs in
                        if resolves_to_self older_block older_rest IntSet.empty lhs then Some rhs
                        else if resolves_to_self older_block older_rest IntSet.empty rhs then Some lhs
                        else None
                    | Some _ -> None
                    | None -> (
                        match older_chain with
                        | (join_block : Cfg.block) :: _
                          when List.length join_block.preds > 1 -> (
                            let pred_results =
                              List.map
                                (fun pred ->
                                  let pred_chain = incoming_update_chain get_block join_block.label pred in
                                  match last_def_of_temp_on_chain_with_block pred_chain current with
                                  | Some (pred_block, Tcg.Move (_, src), pred_rest)
                                  | Some (pred_block, Tcg.Un (_, UPlus, src), pred_rest) ->
                                      peel_self_delta pred_block pred_rest (IntSet.add current seen) src
                                  | Some (pred_block, Tcg.Bin (_, Add, lhs, rhs), pred_rest) ->
                                      let lhs = resolve_on_update_chain pred_block pred_rest lhs in
                                      let rhs = resolve_on_update_chain pred_block pred_rest rhs in
                                      if resolves_to_self pred_block pred_rest IntSet.empty lhs then Some rhs
                                      else if resolves_to_self pred_block pred_rest IntSet.empty rhs then Some lhs
                                      else None
                                  | Some _ | None -> None)
                                join_block.preds
                            in
                            Option.value (agree_all pred_results) ~default:None)
                        | _ ->
                            (match Hashtbl.find_opt def_instrs current with
                            | Some (Tcg.Move (_, src))
                            | Some (Tcg.Un (_, UPlus, src)) -> (
                                match Hashtbl.find_opt def_blocks current with
                                | Some label -> (
                                    match chain_rest_from_label older_chain label with
                                    | Some (def_block, older_rest) ->
                                        peel_self_delta def_block older_rest (IntSet.add current seen) src
                                    | None ->
                                        peel_self_delta (get_block label) [] (IntSet.add current seen) src)
                                | None -> None)
                            | Some (Tcg.Bin (_, Add, lhs, rhs)) -> (
                                match Hashtbl.find_opt def_blocks current with
                                | Some label ->
                                    let def_block =
                                      match chain_rest_from_label older_chain label with
                                      | Some (def_block, _) -> def_block
                                      | None -> get_block label
                                    in
                                    let lhs = resolve_on_update_chain def_block [] lhs in
                                    let rhs = resolve_on_update_chain def_block [] rhs in
                                    if resolves_to_self def_block [] IntSet.empty lhs then Some rhs
                                    else if resolves_to_self def_block [] IntSet.empty rhs then Some lhs
                                    else None
                                | None -> None)
                            | Some _ | None -> None))))
    in
    let invariant operand =
      operand_loop_invariant
        loop_defs loop_stable_phis multi_defs def_instrs IntSet.empty operand
    in
  (* A direct use of an induction phi temp inside a reduction must be
       interpreted at the reduction's actual program point, not through the
       function-wide [def_instrs] table.

       Example:

           s = s + i;
           i = i + 1;

       After mem2reg the same phi temp may have a global unique-def entry
       [i = i + 1].  A context-insensitive linear-expression lookup can then
       "time travel" and classify the earlier [s += i] as [s += i + 1].

       Represent direct IV uses as carrier progressions instead.  The existing
       [resolve_counted_carrier_order] pass compares the real instruction
       positions of the reduction and IV update and selects old-vs-updated
       semantics safely. *)
    let direct_iv_progression_step = function
      | Tcg.Imm _ -> None
      | Tcg.Temp temp -> (
          match
            List.find_opt
              (fun (iv : basic_induction_var) -> iv.phi_temp = temp)
              ivs
          with
          | None -> None
          | Some (iv : basic_induction_var) ->
              let magnitude =
                if iv.step < 0L then Int64.neg iv.step else iv.step
              in
              if magnitude = 0L then None
              else
                Some
                  (ReductionCarrierProgression
                     {
                       carrier_temp = iv.phi_temp;
                       step_expr = SummaryOperand (Tcg.Imm magnitude);
                       carrier_subtract = iv.step < 0L;
                       (* Deliberately pessimistic here.  [true] makes the
                          existing ambiguity/order resolver inspect the actual
                          backedge instruction order before accepting it. *)
                       include_updated = true;
                     }))
    in
    (* Recognize a reduction whose self term is buried under a
       left-/right-associated Add tree.

         ((s + 2*i) + 3)
         (((s + invariant) + 3) + i)

       The old matcher only accepts an Add whose immediate lhs or rhs resolves
       directly to [s].  Frontend lowering commonly introduces temporaries, so
       the outer Add instead sees a temp whose definition contains [s].

       This helper recursively decomposes Add/Move/UPlus definitions at the
       *current program point*.  Exactly one subtree may contain the reduction
       self value; all other subtrees must form one invariant/affine linear
       expression. *)
    let reduction_step_of_linear_expr = function
      | LinearInvariant expr ->
          if summary_expr_is_zero expr then None
          else Some (ReductionInvariant expr)
      | LinearAffine { iv; coeff; bias } ->
          if summary_expr_is_zero coeff then
            if summary_expr_is_zero bias then None
            else Some (ReductionInvariant bias)
          else
            Some (ReductionAffine { iv; coeff; bias })
      | LinearQuadratic { iv; quad; triangle; coeff; bias } ->
          if summary_expr_is_zero quad && summary_expr_is_zero triangle then
            if summary_expr_is_zero coeff then
              if summary_expr_is_zero bias then None
              else Some (ReductionInvariant bias)
            else
              Some (ReductionAffine { iv; coeff; bias })
          else
            Some (ReductionQuadratic { iv; quad; triangle; coeff; bias })
      | LinearCubic { iv; choose3; triangle; coeff; bias } ->
          if summary_expr_is_zero choose3 then
            if summary_expr_is_zero triangle then
              if summary_expr_is_zero coeff then
                if summary_expr_is_zero bias then None
                else Some (ReductionInvariant bias)
              else
                Some (ReductionAffine { iv; coeff; bias })
            else
              Some
                (ReductionQuadratic
                   {
                     iv;
                     quad = zero_summary_expr;
                     triangle;
                     coeff;
                     bias;
                   })
          else
            Some (ReductionCubic { iv; choose3; triangle; coeff; bias })
    in
    let reduction_step_at_point block older_chain operand =
      match direct_iv_progression_step operand with
      | Some _ as step ->
          step
      | None -> (
          match
            reduction_step_of_operand
              ~allow_local_multidef:true
              invariant_loaded_places
              loop_defs
              def_blocks
              get_block
              loop_stable_phis
              multi_defs
              def_instrs
              ivs
              block
              operand
          with
          | Some _ as step ->
              step
          | None -> (
              match
                composed_linear_expr_at_point
                  block older_chain operand
              with
              | Some expr -> (
                  match reduction_step_of_linear_expr expr with
                  | Some _ as result ->
                      if
                        Sys.getenv_opt
                          "TOYC_DEBUG_RECURRENCE_REDUCTION"
                        <> None
                      then
                        Printf.eprintf
                          "recurrence-reduction-hit kind=nested-addrec-compose header=%s block=%s operand=%s\n%!"
                          header block.label
                          (string_of_operand operand);
                      result
                  | None ->
                      semantic_reduction_step_at_point
                        block operand)
              | None ->
                  semantic_reduction_step_at_point
                    block operand))
    in
    let generic_phi_delta_step_of_parts
        op block older_chain lhs rhs =
      let prefix_before_instr (block : Cfg.block) current_instr =
        let rec physical acc = function
          | [] -> None
          | instr :: rest ->
              if instr == current_instr then Some (List.rev acc)
              else physical (instr :: acc) rest
        in
        let rec structural acc best = function
          | [] -> best
          | instr :: rest ->
              let best =
                if instr = current_instr then Some (List.rev acc)
                else best
              in
              structural (instr :: acc) best rest
        in
        match physical [] block.body with
        | Some prefix -> prefix
        | None ->
            Option.value
              (structural [] None block.body)
              ~default:block.body
      in
      let add_deltas lhs rhs =
        match (lhs, rhs) with
        | None, None -> Some None
        | Some expr, None
        | None, Some expr ->
            Some (Some expr)
        | Some lhs, Some rhs ->
            Option.map
              (fun expr -> Some expr)
              (linear_expr_add lhs rhs)
      in
      let sub_deltas lhs rhs =
        add_deltas lhs (Option.map linear_expr_neg rhs)
      in
      let combine_add lhs rhs =
        Option.bind lhs (fun (lhs_self, lhs_delta) ->
          Option.bind rhs (fun (rhs_self, rhs_delta) ->
            if lhs_self && rhs_self then None
            else
              Option.map
                (fun delta -> (lhs_self || rhs_self, delta))
                (add_deltas lhs_delta rhs_delta)))
      in
      let combine_sub lhs rhs =
        Option.bind lhs (fun (lhs_self, lhs_delta) ->
          Option.bind rhs (fun (rhs_self, rhs_delta) ->
            (* [lhs - rhs] is a reduction only when the self term is on
               the lhs with coefficient +1.  A self term on the rhs would
               give coefficient -1 (or cancel another self), which is not
               [next = self + delta]. *)
            if rhs_self then None
            else
              Option.map
                (fun delta -> (lhs_self, delta))
                (sub_deltas lhs_delta rhs_delta)))
      in
      let rec split block older_chain seen operand =
        if resolves_to_self block older_chain IntSet.empty operand then
          Some (true, None)
        else
          match
            linear_expr_of_operand
              invariant_loaded_places
              loop_defs
              def_blocks
              get_block
              loop_stable_phis
              multi_defs
              def_instrs
              ivs
              block
              operand
          with
          | Some expr -> Some (false, Some expr)
          | None -> (
              match
                semantic_linear_expr_at_point
                  block operand
              with
              | Some expr ->
                  if
                    Sys.getenv_opt
                      "TOYC_DEBUG_RECURRENCE_REDUCTION"
                    <> None
                  then
                    Printf.eprintf
                      "recurrence-reduction-hit kind=phi-delta-leaf header=%s block=%s operand=%s\n%!"
                      header block.label
                      (string_of_operand operand);
                  Some (false, Some expr)
              | None -> (
                  match operand with
                  | Tcg.Imm _ -> None
                  | Tcg.Temp current ->
                      if IntSet.mem current seen then None
                      else
                        let continue def_block def_instr older_rest =
                          let prefix =
                            prefix_before_instr def_block def_instr
                          in
                          let point_block =
                            { def_block with body = prefix }
                          in
                          let seen = IntSet.add current seen in
                          match def_instr with
                          | Tcg.Move (_, src)
                          | Tcg.Un (_, UPlus, src) ->
                              split point_block older_rest seen src
                          | Tcg.Un (_, UMinus, src) -> (
                              match
                                split point_block older_rest seen src
                              with
                              | Some (false, delta) ->
                                  Some
                                    ( false,
                                      Option.map
                                        linear_expr_neg delta )
                              | Some (true, _)
                              | None ->
                                  None)
                          | Tcg.Bin (_, Add, def_lhs, def_rhs) ->
                              combine_add
                                (split
                                   point_block older_rest seen
                                   def_lhs)
                                (split
                                   point_block older_rest seen
                                   def_rhs)
                          | Tcg.Bin (_, Sub, def_lhs, def_rhs) ->
                              combine_sub
                                (split
                                   point_block older_rest seen
                                   def_lhs)
                                (split
                                   point_block older_rest seen
                                   def_rhs)
                          | Tcg.Un (_, UNot, _)
                          | Tcg.Bin _
                          | Tcg.Load _
                          | Tcg.Store _
                          | Tcg.Call _ ->
                              None
                        in
                        match last_def_of_temp block current with
                        | Some def_instr ->
                            continue block def_instr older_chain
                        | None -> (
                            match
                              last_def_of_temp_on_chain_with_block
                                older_chain current
                            with
                            | Some
                                ( older_block,
                                  def_instr,
                                  older_rest ) ->
                                continue
                                  older_block def_instr older_rest
                            | None -> None)))
      in
      let combined =
        match op with
        | Add ->
            combine_add
              (split block older_chain IntSet.empty lhs)
              (split block older_chain IntSet.empty rhs)
        | Sub ->
            combine_sub
              (split block older_chain IntSet.empty lhs)
              (split block older_chain IntSet.empty rhs)
        | Mul | Div | Mod
        | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr ->
            None
      in
      match combined with
      | Some (true, Some delta) -> (
          match reduction_step_of_linear_expr delta with
          | Some _ as result ->
              if
                Sys.getenv_opt
                  "TOYC_DEBUG_RECURRENCE_REDUCTION"
                <> None
              then
                Printf.eprintf
                  "recurrence-reduction-hit kind=phi-delta header=%s block=%s op=%s\n%!"
                  header block.label
                  (string_of_binop op);
              result
          | None -> None)
      | Some (true, None)
      | Some (false, _)
      | None ->
          None
    in
    let rec of_operand block older_chain seen = function
      | Tcg.Imm _ -> None
      | Tcg.Temp _ as operand ->
          let operand = resolve_on_update_chain block older_chain operand in
          match operand with
          | Tcg.Imm _ -> None
          | Tcg.Temp current ->
              if debug_counted_local then
                Printf.eprintf
                  "counted-point-follow header=%s target=%d current=t%d block=%s self_target=%b seen=%b multi=%b invariant=%b older=%d\n%!"
                  header temp current block.label
                  (current = temp)
                  (IntSet.mem current seen)
                  (IntSet.mem current multi_defs)
                  (invariant operand)
                  (List.length older_chain);
              if current = temp then (
                if debug_counted_local then
                  Printf.eprintf
                    "counted-point-stop header=%s target=%d current=t%d reason=self-target\n%!"
                    header temp current;
                None)
              else if IntSet.mem current seen then (
                if debug_counted_local then
                  Printf.eprintf
                    "counted-point-stop header=%s target=%d current=t%d reason=cycle\n%!"
                    header temp current;
                None)
              else
                match last_def_of_temp block current with
                | Some instr ->
                    if debug_counted_local && IntSet.mem current multi_defs then
                      Printf.eprintf
                        "counted-point-multidef header=%s target=%d current=%d source=block block=%s\n%!"
                        header temp current block.label;
                    of_instr block older_chain (IntSet.add current seen) instr
                | None -> (
                    match last_def_of_temp_on_chain_with_block older_chain current with
                    | Some (older_block, instr, older_rest) ->
                        if debug_counted_local && IntSet.mem current multi_defs then
                          Printf.eprintf
                            "counted-point-multidef header=%s target=%d current=%d source=chain block=%s\n%!"
                            header temp current older_block.label;
                        of_instr older_block older_rest (IntSet.add current seen) instr
                    | None ->
                        if invariant operand then (
                          if debug_counted_local then
                            Printf.eprintf
                              "counted-point-stop header=%s target=%d current=t%d reason=invariant\n%!"
                              header temp current;
                          None)
                        else if IntSet.mem current multi_defs then (
                          (* Point-sensitive predecessor recovery.

                             A temp may be multi-def over the whole loop while
                             still having one unambiguous reaching definition
                             at this exact program point.  This happens after
                             nested counted-loop summarization:

                                 summary: t47 = t46 + delta
                                 exit:    t46 = t47

                             [t47] also has initialization / earlier-scope defs,
                             so the function-wide table marks it multi-def.
                             However, if [block] has exactly one distinct
                             in-loop predecessor, every execution reaching
                             [block] passes through that same predecessor path.

                             Follow only that unique CFG path and reuse the
                             existing [incoming_update_chain] machinery.  Do
                             not fall back to an arbitrary function-wide def. *)
                          let unique_preds =
                            block.preds
                            |> List.sort_uniq String.compare
                          in
                          let pred_reaching_def =
                            match unique_preds with
                            | [ pred ] when LabelSet.mem pred loop ->
                                let pred_chain =
                                  incoming_update_chain
                                    get_block block.label pred
                                in
                                (match
                                   last_def_of_temp_on_chain_with_block
                                     pred_chain current
                                 with
                                 | Some
                                     ( pred_block,
                                       pred_instr,
                                       pred_rest ) ->
                                     Some
                                       ( pred_block,
                                         pred_instr,
                                         pred_rest )
                                 | None ->
                                     None)
                            | _ ->
                                None
                          in
                          match pred_reaching_def with
                          | Some (pred_block, pred_instr, pred_rest) ->
                              if debug_counted_local then
                                Printf.eprintf
                                  "counted-point-pred-def header=%s target=%d current=t%d block=%s def_block=%s def=%s\n%!"
                                  header temp current block.label
                                  pred_block.label
                                  (string_of_simple_instr pred_instr);
                              of_instr
                                pred_block
                                pred_rest
                                (IntSet.add current seen)
                                pred_instr
                          | None ->
                              if debug_counted_local then begin
                                let chain_labels =
                                  (block :: older_chain)
                                  |> List.map
                                       (fun (b : Cfg.block) -> b.label)
                                  |> String.concat " <- "
                                in
                                Printf.eprintf
                                  "counted-point-stop header=%s target=%d current=t%d reason=multidef-no-point-def chain=[%s]\n%!"
                                  header temp current chain_labels;

                                let defs = ref [] in
                                LabelSet.iter
                                  (fun label ->
                                    let def_block : Cfg.block =
                                      get_block label
                                    in
                                    List.iteri
                                      (fun index instr ->
                                        match defs_temp instr with
                                        | Some dst when dst = current ->
                                            defs :=
                                              ( label,
                                                index,
                                                string_of_simple_instr instr )
                                              :: !defs
                                        | Some _
                                        | None ->
                                            ())
                                      def_block.body)
                                  loop;
                                let defs =
                                  List.rev !defs
                                  |> List.map
                                       (fun (label, index, instr) ->
                                         Printf.sprintf "%s#%d:%s"
                                           label index instr)
                                  |> String.concat " | "
                                in
                                Printf.eprintf
                                  "counted-point-multidef-all header=%s target=%d current=t%d defs=[%s]\n%!"
                                  header temp current defs
                              end;
                              None)
                        else
                          match Hashtbl.find_opt def_instrs current with
                          | Some instr -> (
                              match Hashtbl.find_opt def_blocks current with
                              | Some label -> (
                                  match chain_rest_from_label older_chain label with
                                  | Some (def_block, older_rest) ->
                                      of_instr def_block older_rest (IntSet.add current seen) instr
                                  | None -> of_instr (get_block label) [] (IntSet.add current seen) instr)
                              | None -> None)
                          | None -> None)
    and of_instr block older_chain seen current_instr =
      (* Point-sensitive resolution for the reduction update.

         The old code resolved operands against the whole basic block.  That
         allows a Move occurring *after* the reduction instruction to rewrite
         the reduction's operand, effectively reading a future value.

         Keep only the prefix strictly before [current_instr], so operand
         resolution can see earlier definitions but never later ones. *)
      let prefix_before_current =
        let rec physical acc = function
          | [] -> None
          | instr :: rest ->
              if instr == current_instr then Some (List.rev acc)
              else physical (instr :: acc) rest
        in
        let rec structural acc best = function
          | [] -> best
          | instr :: rest ->
              let best =
                if instr = current_instr then Some (List.rev acc)
                else best
              in
              structural (instr :: acc) best rest
        in
        match physical [] block.body with
        | Some prefix -> prefix
        | None ->
            Option.value
              (structural [] None block.body)
              ~default:block.body
      in
      let point_block = { block with body = prefix_before_current } in
      let resolve_at_point operand =
        resolve_chain_operand (point_block :: older_chain) operand
      in
      let lagged_iv_affine_step operand =
        (* Exact same-block lagged-IV form:

             reduction uses lag;
             lag = iv;
             iv = iv +/- k;

           and program order is strictly:

             reduction < alias < iv update

           Then the logical lag value equals the physical IV minus one step:

             lag = iv - step

           Model it with the existing affine reduction machinery rather than
           the unsafe whole-block carrier resolver. *)
        match operand with
        | Tcg.Imm _ -> None
        | Tcg.Temp lag_temp ->
            let full_block : Cfg.block = get_block block.label in
            let indexed =
              List.mapi (fun pos instr -> (pos, instr)) full_block.body
            in
            let current_pos =
              match
                List.find_opt
                  (fun (_, instr) -> instr == current_instr)
                  indexed
              with
              | Some (pos, _) -> Some pos
              | None ->
                  let structural =
                    List.filter
                      (fun (_, instr) -> instr = current_instr)
                      indexed
                  in
                  (match structural with
                  | [ (pos, _) ] -> Some pos
                  | _ -> None)
            in
            let alias_source = function
              | Tcg.Move (dst, Tcg.Temp src)
              | Tcg.Un (dst, UPlus, Tcg.Temp src)
                when dst = lag_temp ->
                  Some src
              | Tcg.Move _
              | Tcg.Un _
              | Tcg.Bin _
              | Tcg.Load _
              | Tcg.Store _
              | Tcg.Call _ ->
                  None
            in
            let exact_iv_update (iv : basic_induction_var) = function
              | Tcg.Bin (dst, Add, Tcg.Temp src, Tcg.Imm amount)
              | Tcg.Bin (dst, Add, Tcg.Imm amount, Tcg.Temp src) ->
                  dst = iv.phi_temp
                  && src = iv.phi_temp
                  && amount = iv.step
              | Tcg.Bin (dst, Sub, Tcg.Temp src, Tcg.Imm amount) ->
                  dst = iv.phi_temp
                  && src = iv.phi_temp
                  && Int64.neg amount = iv.step
              | Tcg.Move _
              | Tcg.Un _
              | Tcg.Bin _
              | Tcg.Load _
              | Tcg.Store _
              | Tcg.Call _ ->
                  false
            in
            (match current_pos with
            | None -> None
            | Some reduction_pos ->
                let lag_defs_after =
                  List.filter
                    (fun (pos, instr) ->
                      pos > reduction_pos
                      &&
                      match defs_temp instr with
                      | Some dst -> dst = lag_temp
                      | None -> false)
                    indexed
                in
                (match lag_defs_after with
                | [ (alias_pos, alias_instr) ] -> (
                    match alias_source alias_instr with
                    | None -> None
                    | Some iv_temp -> (
                        match
                          List.find_opt
                            (fun (iv : basic_induction_var) ->
                              iv.phi_temp = iv_temp
                              && iv.step <> 0L
                              && List.mem
                                   full_block.label
                                   iv.backedge_preds)
                            ivs
                        with
                        | None -> None
                        | Some (iv : basic_induction_var) ->
                            let iv_defs_after_reduction =
                              List.filter
                                (fun (pos, instr) ->
                                  pos > reduction_pos
                                  &&
                                  match defs_temp instr with
                                  | Some dst -> dst = iv.phi_temp
                                  | None -> false)
                                indexed
                            in
                            (match iv_defs_after_reduction with
                            | [ (update_pos, update_instr) ]
                              when alias_pos < update_pos
                                   && exact_iv_update iv update_instr ->
                                if debug_counted_local then
                                  Printf.eprintf
                                    "counted-lagged-iv header=%s temp=%d lag=t%d iv=t%d reduction_pos=%d alias_pos=%d update_pos=%d step=%Ld\n%!"
                                    header temp lag_temp iv.phi_temp
                                    reduction_pos alias_pos update_pos iv.step;
                                Some
                                  (ReductionAffine
                                     {
                                       iv;
                                       coeff = one_summary_expr;
                                       bias =
                                         SummaryOperand
                                           (Tcg.Imm
                                              (Int64.neg iv.step));
                                     })
                            | _ -> None)))
                | _ -> None))
      in
      if debug_counted_local then
        Printf.eprintf
          "counted-point header=%s block=%s prefix=%d/%d\n%!"
          header block.label
          (List.length prefix_before_current)
          (List.length block.body);
      match current_instr with
      | Tcg.Move (dst, src) ->
          let resolved_src = resolve_at_point src in
          if debug_counted_local then begin
            Printf.eprintf
              "counted-point-move header=%s target=%d dst=t%d raw=%s resolved=%s self=%b block=%s prefix=%d/%d\n%!"
              header temp dst
              (string_of_operand src)
              (string_of_operand resolved_src)
              (resolves_to_self point_block older_chain IntSet.empty resolved_src)
              block.label
              (List.length prefix_before_current)
              (List.length block.body);
            (match resolved_src with
             | Tcg.Imm _ -> ()
             | Tcg.Temp current ->
                 let local_def =
                   last_def_of_temp point_block current
                 in
                 let chain_def =
                   last_def_of_temp_on_chain_with_block older_chain current
                 in
                 Printf.eprintf
                   "counted-point-move-def header=%s target=%d current=t%d local=%s chain=%s multi=%b seen=%b same_target=%b\n%!"
                   header temp current
                   (match local_def with
                    | None -> "<none>"
                    | Some instr -> string_of_simple_instr instr)
                   (match chain_def with
                    | None -> "<none>"
                    | Some (def_block, instr, _) ->
                        Printf.sprintf "%s:%s"
                          def_block.label
                          (string_of_simple_instr instr))
                   (IntSet.mem current multi_defs)
                   (IntSet.mem current seen)
                   (current = temp))
          end;
          of_operand point_block older_chain seen resolved_src
      | Tcg.Bin (_, Add, raw_lhs, raw_rhs) ->
          let lhs = resolve_at_point raw_lhs in
          let rhs = resolve_at_point raw_rhs in
          if debug_counted_local then
            Printf.eprintf
              "counted-point-add header=%s raw=(%s,%s) point=(%s,%s)\n%!"
              header
              (string_of_operand raw_lhs)
              (string_of_operand raw_rhs)
              (string_of_operand lhs)
              (string_of_operand rhs);
          if resolves_to_self point_block older_chain IntSet.empty lhs then (
            if debug_counted_local then
              Printf.eprintf
                "counted-self-hit header=%s temp=%d side=lhs other=%s self={%s}\n%!"
                header temp
                (Printf.sprintf "%s/%s"
                   (string_of_operand rhs)
                   (debug_operand_def rhs))
                (string_of_temps self_temps);
            match reduction_step_at_point point_block older_chain rhs with
            | Some step ->
                Some
                  {
                    target = ReductionTempTarget temp;
                    subtract = false;
                    step;
                    carrier_temp = None;
                    alias_temps = [];
                  }
            | None -> (
                match
                  dependent_affine_step_of_operand
                    point_block older_chain rhs
                with
                | Some (iv, coeff, bias) ->
                    Some
                      {
                        target = ReductionTempTarget temp;
                        subtract = false;
                        step = ReductionAffine { iv; coeff; bias };
                        carrier_temp = None;
                        alias_temps = [];
                      }
                | None -> (
                    match lagged_iv_affine_step rhs with
                    | Some step ->
                        Some
                          {
                            target = ReductionTempTarget temp;
                            subtract = false;
                            step;
                            carrier_temp = None;
                            alias_temps = [];
                          }
                    | None ->
                        let rhs =
                          match
                            peel_self_delta
                              point_block older_chain IntSet.empty rhs
                          with
                          | Some peeled -> peeled
                          | None -> rhs
                        in
                        if debug_counted_local then
                          Printf.eprintf
                            "counted-carrier-fallback header=%s temp=%d side=lhs peeled=%s\n%!"
                            header temp (string_of_operand rhs);
                        Option.map
                          (fun
                            ( carrier_temp,
                              step_expr,
                              carrier_subtract,
                              include_updated ) ->
                            {
                              target = ReductionTempTarget temp;
                              subtract = false;
                              step =
                                ReductionCarrierProgression
                                  {
                                    carrier_temp;
                                    step_expr;
                                    carrier_subtract;
                                    include_updated;
                                  };
                              carrier_temp = None;
                              alias_temps = [];
                            })
                          (carrier_progression_of_operand
                             point_block older_chain rhs))))
          else if
            resolves_to_self point_block older_chain IntSet.empty rhs
          then (
            if debug_counted_local then
              Printf.eprintf
                "counted-self-hit header=%s temp=%d side=rhs other=%s self={%s}\n%!"
                header temp
                (Printf.sprintf "%s/%s"
                   (string_of_operand lhs)
                   (debug_operand_def lhs))
                (string_of_temps self_temps);
            match reduction_step_at_point point_block older_chain lhs with
            | Some step ->
                Some
                  {
                    target = ReductionTempTarget temp;
                    subtract = false;
                    step;
                    carrier_temp = None;
                    alias_temps = [];
                  }
            | None -> (
                match
                  dependent_affine_step_of_operand
                    point_block older_chain lhs
                with
                | Some (iv, coeff, bias) ->
                    Some
                      {
                        target = ReductionTempTarget temp;
                        subtract = false;
                        step = ReductionAffine { iv; coeff; bias };
                        carrier_temp = None;
                        alias_temps = [];
                      }
                | None -> (
                    match lagged_iv_affine_step lhs with
                    | Some step ->
                        Some
                          {
                            target = ReductionTempTarget temp;
                            subtract = false;
                            step;
                            carrier_temp = None;
                            alias_temps = [];
                          }
                    | None ->
                        let lhs =
                          match
                            peel_self_delta
                              point_block older_chain IntSet.empty lhs
                          with
                          | Some peeled -> peeled
                          | None -> lhs
                        in
                        if debug_counted_local then
                          Printf.eprintf
                            "counted-carrier-fallback header=%s temp=%d side=rhs peeled=%s\n%!"
                            header temp (string_of_operand lhs);
                        Option.map
                          (fun
                            ( carrier_temp,
                              step_expr,
                              carrier_subtract,
                              include_updated ) ->
                            {
                              target = ReductionTempTarget temp;
                              subtract = false;
                              step =
                                ReductionCarrierProgression
                                  {
                                    carrier_temp;
                                    step_expr;
                                    carrier_subtract;
                                    include_updated;
                                  };
                              carrier_temp = None;
                              alias_temps = [];
                            })
                          (carrier_progression_of_operand
                             point_block older_chain lhs))))
          else (
            match
              generic_phi_delta_step_of_parts
                Add point_block older_chain lhs rhs
            with
            | Some step ->
                if debug_counted_local then
                  Printf.eprintf
                    "counted-phi-delta header=%s temp=%d op=add recognized=true\n%!"
                    header temp;
                Some
                  {
                    target = ReductionTempTarget temp;
                    subtract = false;
                    step;
                    carrier_temp = None;
                    alias_temps = [];
                  }
            | None -> None)
      | Tcg.Bin (_, Sub, raw_lhs, raw_rhs) ->
          let lhs = resolve_at_point raw_lhs in
          let rhs = resolve_at_point raw_rhs in
          if debug_counted_local then
            Printf.eprintf
              "counted-point-sub header=%s raw=(%s,%s) point=(%s,%s)\n%!"
              header
              (string_of_operand raw_lhs)
              (string_of_operand raw_rhs)
              (string_of_operand lhs)
              (string_of_operand rhs);
          if resolves_to_self point_block older_chain IntSet.empty lhs then (
            if debug_counted_local then
              Printf.eprintf
                "counted-self-hit header=%s temp=%d side=sub-lhs other=%s self={%s}\n%!"
                header temp
                (Printf.sprintf "%s/%s"
                   (string_of_operand rhs)
                   (debug_operand_def rhs))
                (string_of_temps self_temps);
            match reduction_step_at_point point_block older_chain rhs with
            | Some step ->
                Some
                  {
                    target = ReductionTempTarget temp;
                    subtract = true;
                    step;
                    carrier_temp = None;
                    alias_temps = [];
                  }
            | None -> (
                match
                  dependent_affine_step_of_operand
                    point_block older_chain rhs
                with
                | Some (iv, coeff, bias) ->
                    Some
                      {
                        target = ReductionTempTarget temp;
                        subtract = true;
                        step = ReductionAffine { iv; coeff; bias };
                        carrier_temp = None;
                        alias_temps = [];
                      }
                | None ->
                    let rhs =
                      match
                        peel_self_delta
                          point_block older_chain IntSet.empty rhs
                      with
                      | Some peeled -> peeled
                      | None -> rhs
                    in
                    if debug_counted_local then
                      Printf.eprintf
                        "counted-carrier-fallback header=%s temp=%d side=sub peeled=%s\n%!"
                        header temp (string_of_operand rhs);
                    Option.map
                      (fun
                        ( carrier_temp,
                          step_expr,
                          carrier_subtract,
                          include_updated ) ->
                        {
                          target = ReductionTempTarget temp;
                          subtract = true;
                          step =
                            ReductionCarrierProgression
                              {
                                carrier_temp;
                                step_expr;
                                carrier_subtract;
                                include_updated;
                              };
                          carrier_temp = None;
                          alias_temps = [];
                        })
                      (carrier_progression_of_operand
                         point_block older_chain rhs)))
          else (
            match
              generic_phi_delta_step_of_parts
                Sub point_block older_chain lhs rhs
            with
            | Some step ->
                if debug_counted_local then
                  Printf.eprintf
                    "counted-phi-delta header=%s temp=%d op=sub recognized=true\n%!"
                    header temp;
                Some
                  {
                    target = ReductionTempTarget temp;
                    subtract = false;
                    step;
                    carrier_temp = None;
                    alias_temps = [];
                  }
            | None -> None)
      | Tcg.Un _
      | Tcg.Load _
      | Tcg.Store _
      | Tcg.Call _
      | Tcg.Bin _ ->
          None
    in
    match last_def_of_temp_on_chain_with_block chain temp with
    | Some (block, instr, older_chain) ->
        of_instr block older_chain IntSet.empty instr
    | None -> None
  in
  let reduction_update_of_place_on_chain place chain =
    match chain with
    | [] -> None
    | _ ->
        let block = flatten_chain_block chain in
        reduction_update_of_place
          invariant_loaded_places
          loop_defs
          def_blocks
          get_block
          loop_stable_phis
          multi_defs
          def_instrs
          ivs
          place
          block
  in
  let rec last_store_value_of_place_on_chain place chain =
    match chain with
    | [] -> None
    | (block : Cfg.block) :: rest -> (
        match last_store_of_place place block with
        | Some (_, value) -> Some (resolve_chain_operand chain value)
        | None -> last_store_value_of_place_on_chain place rest)
  in
  let place_alias_temp_on_chain place chain temp =
    match last_store_value_of_place_on_chain place chain with
    | Some stored_value ->
        resolve_chain_operand chain (Tcg.Temp temp) = stored_value
    | None -> false
  in

  let rec summary_semantic_form_of_expr expr =
    match expr with
    | SummaryOperand (Tcg.Imm value) ->
        canonical_scalar_const value
    | SummaryOperand operand -> (
        match
          lve_invariant_expr_of_operand
            loop_defs multi_defs def_instrs operand
        with
        | Some invariant ->
            canonical_scalar_form_of_loop_inv_expr
              invariant
        | None ->
            canonical_scalar_operand operand)
    | SummaryPlace place ->
        canonical_scalar_place place
    | SummaryUn (op, inner) ->
        canonical_scalar_un
          op
          (summary_semantic_form_of_expr inner)
    | SummaryBin (op, lhs, rhs) ->
        canonical_scalar_bin
          op
          (summary_semantic_form_of_expr lhs)
          (summary_semantic_form_of_expr rhs)
  in
  let summary_semantic_key expr =
    canonical_scalar_key_of_form
      (summary_semantic_form_of_expr expr)
  in
  let summary_expr_semantic_equal lhs rhs =
    summary_semantic_key lhs
    = summary_semantic_key rhs
  in

  let basic_iv_semantic_equal
      (lhs : basic_induction_var)
      (rhs : basic_induction_var) =
    lhs.phi_temp = rhs.phi_temp
    && i32 lhs.step = i32 rhs.step
  in
  let counted_reduction_step_semantic_equal lhs rhs =
    match (lhs, rhs) with
    | ReductionInvariant lhs, ReductionInvariant rhs ->
        summary_expr_semantic_equal lhs rhs
    | ReductionAffine lhs, ReductionAffine rhs ->
        basic_iv_semantic_equal lhs.iv rhs.iv
        && summary_expr_semantic_equal lhs.coeff rhs.coeff
        && summary_expr_semantic_equal lhs.bias rhs.bias
    | ReductionQuadratic lhs, ReductionQuadratic rhs ->
        basic_iv_semantic_equal lhs.iv rhs.iv
        && summary_expr_semantic_equal lhs.quad rhs.quad
        && summary_expr_semantic_equal lhs.triangle rhs.triangle
        && summary_expr_semantic_equal lhs.coeff rhs.coeff
        && summary_expr_semantic_equal lhs.bias rhs.bias
    | ReductionCubic lhs, ReductionCubic rhs ->
        basic_iv_semantic_equal lhs.iv rhs.iv
        && summary_expr_semantic_equal lhs.choose3 rhs.choose3
        && summary_expr_semantic_equal lhs.triangle rhs.triangle
        && summary_expr_semantic_equal lhs.coeff rhs.coeff
        && summary_expr_semantic_equal lhs.bias rhs.bias
    | ReductionCarrierProgression lhs,
      ReductionCarrierProgression rhs ->
        lhs.carrier_temp = rhs.carrier_temp
        && lhs.carrier_subtract = rhs.carrier_subtract
        && lhs.include_updated = rhs.include_updated
        && summary_expr_semantic_equal
             lhs.step_expr rhs.step_expr
    | ReductionInvariant _, _
    | ReductionAffine _, _
    | ReductionQuadratic _, _
    | ReductionCubic _, _
    | ReductionCarrierProgression _, _ ->
        false
  in
  let counted_reduction_semantic_equal
      (lhs : counted_reduction)
      (rhs : counted_reduction) =
    lhs.target = rhs.target
    && lhs.subtract = rhs.subtract
    && counted_reduction_step_semantic_equal
         lhs.step rhs.step
    && lhs.carrier_temp = rhs.carrier_temp
    && List.sort_uniq compare lhs.alias_temps
       = List.sort_uniq compare rhs.alias_temps
  in
  let path_updates_agree updates =
    match updates with
    | [] -> None
    | first :: rest ->
        if
          List.for_all
            (counted_reduction_semantic_equal first)
            rest
        then begin
          if
            Sys.getenv_opt
              "TOYC_DEBUG_RECURRENCE_REDUCTION"
            <> None
            && List.exists (( <> ) first) rest
          then
            Printf.eprintf
              "recurrence-reduction-hit kind=path-effect-merge header=%s paths=%d\n%!"
              header (List.length updates);
          Some first
        end
        else
          None
  in
  let logical_phi_for_temp temp =
    List.find_opt
      (fun (phi : logical_loop_phi) ->
        phi.logical_phi_temp = temp)
      logical_phis
  in
  let logical_phi_covers_backedges (phi : logical_loop_phi) =
    let covered =
      phi.logical_backedge_cases
      |> List.map
           (fun case -> case.logical_header_pred)
      |> List.sort_uniq String.compare
    in
    let expected =
      backedge_preds |> List.sort_uniq String.compare
    in
    covered = expected
  in
  let last_def_index_of_temp
      (block : Cfg.block) temp =
    let result = ref None in
    List.iteri
      (fun index instr ->
        match defs_temp instr with
        | Some dst when dst = temp ->
            result := Some (index, instr)
        | Some _ | None -> ())
      block.body;
    !result
  in

  (* Analyze one logical backedge next-value as

       self_coeff * phi + delta

     at the actual program point where the edge-copy reads its source.
     [delta] is a ScalarRecurrence, so uses of another induction variable
     retain their program-point phase through [recurrence_at].

     Multiplication is accepted only when neither operand contains [phi].
     This deliberately keeps the target recurrence additive:
       phi + delta
     rather than trying to solve multiplicative recurrences. *)
  let scalar_phi_delta_case
      phi_temp
      consumer_temp
      (case : logical_phi_backedge_case) =
    let combine_add
        (lhs_coeff, lhs_delta)
        (rhs_coeff, rhs_delta) =
      Option.map
        (fun delta ->
          (lhs_coeff + rhs_coeff, delta))
        (scalar_recurrence_add lhs_delta rhs_delta)
    in
    let combine_sub
        (lhs_coeff, lhs_delta)
        (rhs_coeff, rhs_delta) =
      Option.map
        (fun delta ->
          (lhs_coeff - rhs_coeff, delta))
        (scalar_recurrence_sub lhs_delta rhs_delta)
    in
    let negate (coeff, delta) =
      (-coeff, scalar_recurrence_neg delta)
    in

    let rec analyze_operand
        chain point seen operand =
      match operand with
      | Tcg.Temp temp when temp = phi_temp ->
          Some (1, ScalarConst 0L)
      | Tcg.Imm value ->
          Some (0, ScalarConst value)
      | Tcg.Temp temp as operand ->
          if IntSet.mem temp seen then None
          else
            (* First ask the phase-aware recurrence database.  This handles
               proven IVs and their unique affine derived values without
               recursively reinterpreting them relative to the target phi. *)
            begin
              match recurrence_at recurrence_facts point operand with
              | Some recurrence ->
                  Some (0, recurrence)
              | None ->
                  let seen = IntSet.add temp seen in
                  begin
                    match
                      last_def_of_temp_on_chain_with_block
                        chain temp
                    with
                    | Some (def_block, instr, older_chain) -> (
                        match
                          last_def_index_of_temp
                            def_block temp
                        with
                        | Some (def_index, _)
                          when
                            def_block.label
                            <> recurrence_point_label point
                            ||
                            (match
                               recurrence_point_visible_count
                                 recurrence_facts point
                             with
                             | Some visible_count ->
                                 def_index < visible_count
                             | None ->
                                 false) ->
                            analyze_instr
                              (def_block :: older_chain)
                              (RecurrenceBeforeInstr
                                 (def_block.label,
                                  def_index))
                              seen instr
                        | Some _ | None ->
                            None)
                    | None ->
                        None
                  end
            end

    and analyze_instr chain point seen = function
      | Tcg.Move (_, src)
      | Tcg.Un (_, UPlus, src) ->
          analyze_operand chain point seen src
      | Tcg.Un (_, UMinus, src) ->
          Option.map negate
            (analyze_operand chain point seen src)
      | Tcg.Bin (_, Add, lhs, rhs) ->
          Option.bind
            (analyze_operand chain point seen lhs)
            (fun lhs ->
              Option.bind
                (analyze_operand chain point seen rhs)
                (combine_add lhs))
      | Tcg.Bin (_, Sub, lhs, rhs) ->
          Option.bind
            (analyze_operand chain point seen lhs)
            (fun lhs ->
              Option.bind
                (analyze_operand chain point seen rhs)
                (combine_sub lhs))
      | Tcg.Bin (_, Mul, lhs, rhs) ->
          Option.bind
            (analyze_operand chain point seen lhs)
            (fun (lhs_coeff, lhs_delta) ->
              Option.bind
                (analyze_operand chain point seen rhs)
                (fun (rhs_coeff, rhs_delta) ->
                  if lhs_coeff <> 0 || rhs_coeff <> 0 then
                    None
                  else
                    Option.map
                      (fun delta -> (0, delta))
                      (scalar_recurrence_mul
                         lhs_delta rhs_delta)))
      | Tcg.Un (_, UNot, _)
      | Tcg.Bin
          (_,
           (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne
           | LAnd | LOr),
           _, _)
      | Tcg.Load _
      | Tcg.Store _
      | Tcg.Call _ ->
          None
    in

    let def_block : Cfg.block =
      get_block case.logical_def_label
    in
    match
      last_def_index_of_temp
        def_block consumer_temp
    with
    | Some
        (copy_index,
         Tcg.Move (dst, source))
      when
        dst = consumer_temp
        && source = case.logical_source ->
        let point =
          RecurrenceBeforeInstr
            (def_block.label, copy_index)
        in
        Option.bind
          (analyze_operand
             case.logical_chain
             point IntSet.empty
             case.logical_source)
          (fun (self_coeff, delta) ->
            if self_coeff = 1 then
              Some
                (normalize_scalar_recurrence delta)
            else
              None)
    | Some _ | None ->
        None
  in

  (* A logical edge-copy may read a merge temp whose definitions live on
     several side paths.  If the direct scalar-delta analysis cannot resolve
     that multi-defined source, recursively expand the reaching Move cases and
     analyze each value path independently. *)
  let scalar_phi_delta_cases
      phi_temp
      (case : logical_phi_backedge_case) =
    let rec expand
        seen_merge_temps
        consumer_temp
        def_label
        chain
        source =
      let synthetic_case =
        {
          logical_header_pred =
            case.logical_header_pred;
          logical_def_label = def_label;
          logical_source = source;
          logical_chain = chain;
        }
      in
      match
        scalar_phi_delta_case
          phi_temp consumer_temp
          synthetic_case
      with
      | Some delta ->
          Some [ delta ]
      | None -> (
          match source with
          | Tcg.Temp temp
            when
              temp <> phi_temp
              && IntSet.mem temp multi_defs
              && not
                   (IntSet.mem temp
                      seen_merge_temps) ->
              let block : Cfg.block =
                get_block def_label
              in
              if block.preds = [] then None
              else
                let seen_merge_temps =
                  IntSet.add temp
                    seen_merge_temps
                in
                let reached_per_pred =
                  List.map
                    (fun pred ->
                      reaching_move_cases_on_edge
                        get_block
                        ~stop_label:def_label
                        ~pred_label:pred
                        temp)
                    block.preds
                in
                if
                  List.exists Option.is_none
                    reached_per_pred
                then
                  None
                else
                  let reached =
                    reached_per_pred
                    |> List.concat_map
                         (Option.value
                            ~default:[])
                    |> dedup_reaching_move_cases
                  in
                  if reached = [] then None
                  else
                    let expanded =
                      List.map
                        (fun reached_case ->
                          expand
                            seen_merge_temps
                            temp
                            reached_case
                              .reaching_def_label
                            reached_case
                              .reaching_chain
                            reached_case
                              .reaching_source)
                        reached
                    in
                    if
                      List.exists Option.is_none
                        expanded
                    then
                      None
                    else
                      Some
                        (expanded
                         |> List.concat_map
                              (Option.value
                                 ~default:[]))
          | Tcg.Imm _
          | Tcg.Temp _ ->
              None)
    in
    expand IntSet.empty phi_temp
      case.logical_def_label
      case.logical_chain
      case.logical_source
  in

  let scalar_delta_reduction_update temp =
    match logical_phi_for_temp temp with
    | None -> None
    | Some phi ->
        if
          not (logical_phi_covers_backedges phi)
          || phi.logical_backedge_cases = []
        then
          None
        else
          let recovered =
            List.map
              (fun case ->
                scalar_phi_delta_cases
                  temp case)
              phi.logical_backedge_cases
          in
          if
            List.exists Option.is_none recovered
          then
            None
          else
            let deltas =
              recovered
              |> List.concat_map
                   (Option.value ~default:[])
            in
            match deltas with
            | [] -> None
            | first :: rest
              when
                List.for_all
                  (scalar_recurrence_equal first)
                  rest -> (
                match
                  reduction_step_of_scalar_recurrence
                    first
                with
                | None -> None
                | Some
                    (ReductionInvariant expr)
                  when
                    summary_expr_is_zero expr ->
                    None
                | Some step ->
                    if
                      Sys.getenv_opt
                        "TOYC_DEBUG_RECURRENCE_REDUCTION"
                      <> None
                    then
                      Printf.eprintf
                        "recurrence-reduction-hit kind=scalar-backedge-delta header=%s temp=t%d logical-cases=%d value-paths=%d delta=%s\n%!"
                        header temp
                        (List.length
                           phi.logical_backedge_cases)
                        (List.length deltas)
                        (string_of_scalar_recurrence
                           first);
                    Some
                      {
                        target =
                          ReductionTempTarget temp;
                        subtract = false;
                        step;
                        carrier_temp = None;
                        alias_temps = [];
                      })
            | _ ->
                None
  in

  let logical_phi_reduction_update temp =
    match logical_phi_for_temp temp with
    | None -> None
    | Some phi ->
        if
          not (logical_phi_covers_backedges phi)
          || phi.logical_backedge_cases = []
        then
          None
        else
          let updates =
            List.filter_map
              (fun (case : logical_phi_backedge_case) ->
                reduction_update_of_temp_on_chain
                  temp case.logical_chain)
              phi.logical_backedge_cases
          in
          if
            List.length updates
            <> List.length phi.logical_backedge_cases
          then
            None
          else
            match path_updates_agree updates with
            | None -> None
            | Some update ->
                if
                  Sys.getenv_opt
                    "TOYC_DEBUG_RECURRENCE_REDUCTION"
                  <> None
                then
                  Printf.eprintf
                    "recurrence-reduction-hit kind=logical-phi-backedge header=%s temp=t%d header-preds=%d value-paths=%d\\n%!"
                    header temp
                    (List.length phi.logical_backedge_preds)
                    (List.length phi.logical_backedge_cases);
                Some update
  in
  if backedge_preds = [] then []
  else
      let temp_reductions =
        IntSet.fold
          (fun temp acc ->
            if IntSet.mem temp excluded_temps then acc
           else
             let common_self_temps =
               match backedge_preds with
               | [] -> IntSet.empty
               | pred :: rest ->
                   List.fold_left
                     (fun shared pred ->
                       IntSet.inter shared (self_temps_on_chain temp (update_chain_for_pred pred)))
                     (self_temps_on_chain temp (update_chain_for_pred pred))
                     rest
             in
             let has_outside_seed =
               IntSet.exists
                 (fun seed_temp ->
                   List.for_all
                     (fun pred ->
                       Option.is_some
                         (last_def_of_temp_on_chain
                            (outside_seed_chain_for_pred pred)
                            seed_temp))
                     outside_preds)
                 common_self_temps
             in
             if debug_counted_local then
               Printf.eprintf
                 "counted-temp-gate header=%s temp=%d seeds={%s} pass=%b\n%!"
                 header temp (string_of_temps common_self_temps) has_outside_seed;
             let old_update =
               if not has_outside_seed then None
               else
                 let updates =
                   List.filter_map
                     (fun pred ->
                       reduction_update_of_temp_on_chain
                         temp (update_chain_for_pred pred))
                     backedge_preds
                 in
                 if debug_counted_local then
                   Printf.eprintf
                     "counted-temp-updates header=%s temp=%d count=%d preds=%d\n%!"
                     header temp
                     (List.length updates)
                     (List.length backedge_preds);
                 if
                   List.length updates
                   <> List.length backedge_preds
                 then
                   None
                 else
                   path_updates_agree updates
             in
             match old_update with
             | Some update ->
                 update :: acc
             | None -> (
                 match scalar_delta_reduction_update temp with
                 | Some update ->
                     update :: acc
                 | None -> (
                     match
                       logical_phi_reduction_update temp
                     with
                     | Some update ->
                         update :: acc
                     | None ->
                         acc)))
         live_temps []
    in
    let place_reductions =
      PlaceSet.fold
        (fun place acc ->
          match place with
          | Tcg.Global _ -> acc
          | Tcg.Local _ ->
              let updates =
                List.filter_map
                  (fun pred -> reduction_update_of_place_on_chain place (update_chain_for_pred pred))
                  backedge_preds
              in
              if debug_counted_local then
                Printf.eprintf
                  "counted-place-updates header=%s place=%s count=%d preds=%d\n%!"
                  header
                  (match place with
                   | Tcg.Local slot -> Printf.sprintf "local:%d" slot
                   | Tcg.Global name -> Printf.sprintf "global:%s" name)
                  (List.length updates)
                  (List.length backedge_preds);
              if List.length updates <> List.length backedge_preds then
                acc
              else
                match path_updates_agree updates with
                | Some update -> update :: acc
                | None -> acc)
        live_places []
      |> List.map (fun reduction ->
             match reduction.target with
             | ReductionTempTarget _ -> reduction
             | ReductionPlaceTarget place ->
                 let alias_temps =
                   IntSet.elements live_temps
                   |> List.filter (fun temp -> not (IntSet.mem temp excluded_temps))
                   |> List.filter (fun temp ->
                          List.for_all
                            (fun pred -> place_alias_temp_on_chain place (update_chain_for_pred pred) temp)
                            backedge_preds)
                   |> List.sort_uniq compare
                 in
                 { reduction with alias_temps })
    in
    temp_reductions @ place_reductions

let collect_counted_place_mirrors
    header
    loop
    invariant_loaded_places
    loop_defs
    get_block
    def_blocks
    loop_stable_phis
    multi_defs
    def_instrs
    ivs
    live_places
    supported_temps
  =
  let header_block : Cfg.block = get_block header in
  let backedge_preds = List.filter (fun pred -> LabelSet.mem pred loop) header_block.preds in
  let update_chain_for_pred pred = incoming_update_chain get_block header pred in
  let canonical_temp_of_value block = function
    | Tcg.Imm _ -> None
    | Tcg.Temp temp when IntSet.mem temp supported_temps -> Some temp
    | Tcg.Temp temp ->
        let supported_alias =
          IntSet.elements supported_temps
          |> List.find_opt (fun target ->
                 target <> temp && resolves_to_temp multi_defs def_instrs target (Tcg.Temp temp))
        in
        match supported_alias with
        | Some target -> Some target
        | None ->
            List.find_map
          (fun (iv : basic_induction_var) ->
            if not (IntSet.mem iv.phi_temp supported_temps) then None
            else
              match
                reduction_update_of_temp
                  invariant_loaded_places
                  loop_defs
                  def_blocks
                  get_block
                  loop_stable_phis
                  multi_defs
                  def_instrs
                  ivs
                  iv.phi_temp
                  block
                  temp
              with
              | Some _ -> Some iv.phi_temp
              | None -> None)
          ivs
  in
  let last_store_value_of_place_on_chain place chain =
    let block = flatten_chain_block chain in
    match last_store_of_place place block with
    | Some (_, value) -> Some (resolve_chain_operand chain value, block)
    | None -> None
  in
  PlaceSet.elements live_places
  |> List.filter_map (fun place ->
         let mirrored_temps =
           List.filter_map
             (fun pred ->
               match last_store_value_of_place_on_chain place (update_chain_for_pred pred) with
               | Some (value, block) -> canonical_temp_of_value block value
               | None -> None)
             backedge_preds
         in
         match mirrored_temps with
          | [] -> None
          | first :: rest
            when List.length mirrored_temps = List.length backedge_preds
                 && List.for_all (( = ) first) rest
                 && IntSet.mem first supported_temps ->
              Some (place, first)
          | _ -> None)

let collect_reconstructible_live_temps
    invariant_loaded_places
    loop_defs
    get_block
    def_blocks
    loop_stable_phis
    multi_defs
    def_instrs
    supported_temps
    live_temps
  =
  let rec close supported order exprs =
    let newly_found_rev =
      IntSet.fold
        (fun temp acc ->
          if IntSet.mem temp supported || IntMap.mem temp exprs || IntSet.mem temp multi_defs then acc
          else
            match Hashtbl.find_opt def_blocks temp with
            | None -> acc
            | Some label -> (
                match
                  summary_expr_of_operand_with_bases
                    supported
                    invariant_loaded_places
                    loop_defs
                    def_blocks
                    get_block
                    loop_stable_phis
                    multi_defs
                    def_instrs
                    (get_block label)
                    (Tcg.Temp temp)
                with
                | Some expr -> (temp, expr) :: acc
                | None -> acc))
        live_temps []
    in
    match newly_found_rev with
    | [] -> (supported, List.rev order, exprs)
    | _ ->
        let supported, order, exprs =
          List.fold_left
            (fun (supported, order, exprs) (temp, expr) ->
              (IntSet.add temp supported, temp :: order, IntMap.add temp expr exprs))
            (supported, order, exprs) (List.rev newly_found_rev)
        in
        close supported order exprs
  in
  close supported_temps [] IntMap.empty

let build_select_operand_instrs fresh_temp cond if_true if_false =
  let diff = fresh_temp () in
  let scaled = fresh_temp () in
  let dst = fresh_temp () in
  ( [ simplify_simple_instr (Tcg.Bin (diff, Sub, if_true, if_false));
      simplify_simple_instr (Tcg.Bin (scaled, Mul, cond, Tcg.Temp diff));
      simplify_simple_instr (Tcg.Bin (dst, Add, if_false, Tcg.Temp scaled)) ],
    Tcg.Temp dst )

let build_triangle_number_operand_instrs fresh_temp n_operand =
  let n_minus_one = fresh_temp () in
  let half_n = fresh_temp () in
  let parity = fresh_temp () in
  let half_n_minus_one = fresh_temp () in
  let left = fresh_temp () in
  let right = fresh_temp () in
  let triangle = fresh_temp () in
  ( [ simplify_simple_instr (Tcg.Bin (n_minus_one, Sub, n_operand, Tcg.Imm 1L));
      simplify_simple_instr (Tcg.Bin (half_n, Div, n_operand, Tcg.Imm 2L));
      simplify_simple_instr (Tcg.Bin (parity, Mod, n_operand, Tcg.Imm 2L));
      simplify_simple_instr
        (Tcg.Bin (half_n_minus_one, Div, Tcg.Temp n_minus_one, Tcg.Imm 2L));
      simplify_simple_instr
        (Tcg.Bin (left, Mul, Tcg.Temp half_n, Tcg.Temp n_minus_one));
      simplify_simple_instr
        (Tcg.Bin (right, Mul, Tcg.Temp parity, Tcg.Temp half_n_minus_one));
      simplify_simple_instr
        (Tcg.Bin (triangle, Add, Tcg.Temp left, Tcg.Temp right)) ],
    triangle )

let build_triangle_number_instrs fresh_temp trip_temp =
  build_triangle_number_operand_instrs fresh_temp (Tcg.Temp trip_temp)

let build_choose3_operand_instrs fresh_temp n_operand =
  (* C(n,3) = n(n-1)(n-2)/6 for nonnegative n.

     Divide exact factors by 2 and 3 before any final multiplication, so
     modular 32-bit multiplication afterwards is equivalent to the source's
     repeated-addition result modulo 2^32. *)
  let b = fresh_temp () in
  let c = fresh_temp () in
  let rem2 = fresh_temp () in
  let even = fresh_temp () in
  let a_half = fresh_temp () in
  let b_half = fresh_temp () in
  let prefix =
    [ simplify_simple_instr (Tcg.Bin (b, Sub, n_operand, Tcg.Imm 1L));
      simplify_simple_instr (Tcg.Bin (c, Sub, n_operand, Tcg.Imm 2L));
      simplify_simple_instr (Tcg.Bin (rem2, Mod, n_operand, Tcg.Imm 2L));
      simplify_simple_instr
        (Tcg.Bin (even, Eq, Tcg.Temp rem2, Tcg.Imm 0L));
      simplify_simple_instr (Tcg.Bin (a_half, Div, n_operand, Tcg.Imm 2L));
      simplify_simple_instr
        (Tcg.Bin (b_half, Div, Tcg.Temp b, Tcg.Imm 2L)) ]
  in
  let a2_instrs, a2 =
    build_select_operand_instrs
      fresh_temp (Tcg.Temp even) (Tcg.Temp a_half) n_operand
  in
  let b2_instrs, b2 =
    build_select_operand_instrs
      fresh_temp (Tcg.Temp even) (Tcg.Temp b) (Tcg.Temp b_half)
  in
  let rem3 = fresh_temp () in
  let is0 = fresh_temp () in
  let is1 = fresh_temp () in
  let is2 = fresh_temp () in
  let a_div3 = fresh_temp () in
  let b_div3 = fresh_temp () in
  let c_div3 = fresh_temp () in
  let thirds =
    [ simplify_simple_instr (Tcg.Bin (rem3, Mod, n_operand, Tcg.Imm 3L));
      simplify_simple_instr
        (Tcg.Bin (is0, Eq, Tcg.Temp rem3, Tcg.Imm 0L));
      simplify_simple_instr
        (Tcg.Bin (is1, Eq, Tcg.Temp rem3, Tcg.Imm 1L));
      simplify_simple_instr
        (Tcg.Bin (is2, Eq, Tcg.Temp rem3, Tcg.Imm 2L));
      simplify_simple_instr (Tcg.Bin (a_div3, Div, a2, Tcg.Imm 3L));
      simplify_simple_instr (Tcg.Bin (b_div3, Div, b2, Tcg.Imm 3L));
      simplify_simple_instr
        (Tcg.Bin (c_div3, Div, Tcg.Temp c, Tcg.Imm 3L)) ]
  in
  let a3_instrs, a3 =
    build_select_operand_instrs
      fresh_temp (Tcg.Temp is0) (Tcg.Temp a_div3) a2
  in
  let b3_instrs, b3 =
    build_select_operand_instrs
      fresh_temp (Tcg.Temp is1) (Tcg.Temp b_div3) b2
  in
  let c3_instrs, c3 =
    build_select_operand_instrs
      fresh_temp (Tcg.Temp is2) (Tcg.Temp c_div3) (Tcg.Temp c)
  in
  let ab = fresh_temp () in
  let result = fresh_temp () in
  ( prefix
    @ a2_instrs
    @ b2_instrs
    @ thirds
    @ a3_instrs
    @ b3_instrs
    @ c3_instrs
    @ [ simplify_simple_instr (Tcg.Bin (ab, Mul, a3, b3));
        simplify_simple_instr (Tcg.Bin (result, Mul, Tcg.Temp ab, c3)) ],
    result )


let build_choose4_operand_instrs fresh_temp n_operand =
  let choose3_instrs, choose3 =
    build_choose3_operand_instrs fresh_temp n_operand
  in
  let n_minus_three = fresh_temp () in
  let rem4 = fresh_temp () in
  let is0 = fresh_temp () in
  let is2 = fresh_temp () in
  let choose3_div4 = fresh_temp () in
  let choose3_div2 = fresh_temp () in
  let nm3_div4 = fresh_temp () in
  let nm3_div2 = fresh_temp () in
  let prefix =
    [ simplify_simple_instr
        (Tcg.Bin (n_minus_three, Sub, n_operand, Tcg.Imm 3L));
      simplify_simple_instr
        (Tcg.Bin (rem4, Mod, Tcg.Temp choose3, Tcg.Imm 4L));
      simplify_simple_instr
        (Tcg.Bin (is0, Eq, Tcg.Temp rem4, Tcg.Imm 0L));
      simplify_simple_instr
        (Tcg.Bin (is2, Eq, Tcg.Temp rem4, Tcg.Imm 2L));
      simplify_simple_instr
        (Tcg.Bin (choose3_div4, Div, Tcg.Temp choose3, Tcg.Imm 4L));
      simplify_simple_instr
        (Tcg.Bin (choose3_div2, Div, Tcg.Temp choose3, Tcg.Imm 2L));
      simplify_simple_instr
        (Tcg.Bin (nm3_div4, Div, Tcg.Temp n_minus_three, Tcg.Imm 4L));
      simplify_simple_instr
        (Tcg.Bin (nm3_div2, Div, Tcg.Temp n_minus_three, Tcg.Imm 2L)) ]
  in

  let lhs_non0_instrs, lhs_non0 =
    build_select_operand_instrs
      fresh_temp
      (Tcg.Temp is2)
      (Tcg.Temp choose3_div2)
      (Tcg.Temp choose3)
  in
  let rhs_non0_instrs, rhs_non0 =
    build_select_operand_instrs
      fresh_temp
      (Tcg.Temp is2)
      (Tcg.Temp nm3_div2)
      (Tcg.Temp nm3_div4)
  in
  let lhs_instrs, lhs =
    build_select_operand_instrs
      fresh_temp
      (Tcg.Temp is0)
      (Tcg.Temp choose3_div4)
      lhs_non0
  in
  let rhs_instrs, rhs =
    build_select_operand_instrs
      fresh_temp
      (Tcg.Temp is0)
      (Tcg.Temp n_minus_three)
      rhs_non0
  in
  let result = fresh_temp () in
  ( choose3_instrs
    @ prefix
    @ lhs_non0_instrs
    @ rhs_non0_instrs
    @ lhs_instrs
    @ rhs_instrs
    @ [ simplify_simple_instr (Tcg.Bin (result, Mul, lhs, rhs)) ],
    result )


let rec emit_summary_expr_with_carriers place_carriers fresh_temp = function
  | SummaryOperand operand -> ([], operand)
  | SummaryPlace place -> (
      match PlaceMap.find_opt place place_carriers with
      | Some temp -> ([], Tcg.Temp temp)
      | None ->
          let dst = fresh_temp () in
          ([ simplify_simple_instr (Tcg.Load (dst, place)) ], Tcg.Temp dst))
  | SummaryUn (op, expr) ->
      let instrs, operand = emit_summary_expr_with_carriers place_carriers fresh_temp expr in
      let dst = fresh_temp () in
      (instrs @ [ simplify_simple_instr (Tcg.Un (dst, op, operand)) ], Tcg.Temp dst)
  | SummaryBin (op, lhs, rhs) ->
      let lhs_instrs, lhs_operand =
        emit_summary_expr_with_carriers place_carriers fresh_temp lhs
      in
      let rhs_instrs, rhs_operand =
        emit_summary_expr_with_carriers place_carriers fresh_temp rhs
      in
      let dst = fresh_temp () in
      ( lhs_instrs @ rhs_instrs
        @ [ simplify_simple_instr (Tcg.Bin (dst, op, lhs_operand, rhs_operand)) ],
        Tcg.Temp dst )

let build_invariant_reduction_delta place_carriers fresh_temp trip_temp step_expr =
  let step_instrs, step_operand =
    emit_summary_expr_with_carriers place_carriers fresh_temp step_expr
  in
  match step_operand with
  | Tcg.Imm 0L -> (step_instrs, None)
  | Tcg.Imm 1L -> (step_instrs, Some (Tcg.Temp trip_temp))
  | Tcg.Imm -1L ->
      let delta = fresh_temp () in
      ( step_instrs
        @ [ simplify_simple_instr (Tcg.Bin (delta, Sub, Tcg.Imm 0L, Tcg.Temp trip_temp)) ],
        Some (Tcg.Temp delta) )
  | _ ->
      let delta = fresh_temp () in
      ( step_instrs
        @ [ simplify_simple_instr (Tcg.Bin (delta, Mul, Tcg.Temp trip_temp, step_operand)) ],
        Some (Tcg.Temp delta) )

let build_affine_reduction_delta
    place_carriers
    fresh_temp
    trip_temp
    (iv : basic_induction_var)
    coeff
    bias
  =
  let coeff_instrs, coeff_operand =
    emit_summary_expr_with_carriers place_carriers fresh_temp coeff
  in
  let bias_instrs, bias_operand =
    emit_summary_expr_with_carriers place_carriers fresh_temp bias
  in
  let scaled_base = fresh_temp () in
  let base_instrs =
    coeff_instrs
    @ [ simplify_simple_instr (Tcg.Bin (scaled_base, Mul, Tcg.Temp iv.phi_temp, coeff_operand)) ]
    @ bias_instrs
  in
  let base_operand, base_adjust_instrs =
    match bias_operand with
    | Tcg.Imm 0L -> (Tcg.Temp scaled_base, [])
    | _ ->
        let base = fresh_temp () in
        ( Tcg.Temp base,
          [ simplify_simple_instr (Tcg.Bin (base, Add, Tcg.Temp scaled_base, bias_operand)) ] )
  in
  let delta_base = fresh_temp () in
  let delta_instrs =
    [ simplify_simple_instr (Tcg.Bin (delta_base, Mul, base_operand, Tcg.Temp trip_temp)) ]
  in
  if iv.step = 0L then
    (base_instrs @ base_adjust_instrs @ delta_instrs, Some (Tcg.Temp delta_base))
  else
    let triangle_instrs, triangle = build_triangle_number_instrs fresh_temp trip_temp in
    let coeff_step_operand, coeff_step_instrs =
      if iv.step = 1L then (coeff_operand, [])
      else if iv.step = -1L then
        let coeff_step = fresh_temp () in
        ( Tcg.Temp coeff_step,
          [ simplify_simple_instr (Tcg.Bin (coeff_step, Sub, Tcg.Imm 0L, coeff_operand)) ] )
      else
        let coeff_step = fresh_temp () in
        ( Tcg.Temp coeff_step,
          [ simplify_simple_instr (Tcg.Bin (coeff_step, Mul, coeff_operand, Tcg.Imm iv.step)) ] )
    in
    let series = fresh_temp () in
    let series_instrs =
      coeff_step_instrs
      @ [ simplify_simple_instr (Tcg.Bin (series, Mul, coeff_step_operand, Tcg.Temp triangle)) ]
    in
    let delta = fresh_temp () in
    let combine = simplify_simple_instr (Tcg.Bin (delta, Add, Tcg.Temp delta_base, Tcg.Temp series)) in
    ( base_instrs @ base_adjust_instrs @ delta_instrs @ triangle_instrs @ series_instrs @ [ combine ],
      Some (Tcg.Temp delta) )

let build_sum_squares_progression_instrs fresh_temp trip_temp (iv : basic_induction_var) =
  let triangle_instrs, triangle =
    build_triangle_number_instrs fresh_temp trip_temp
  in
  let choose3_instrs, choose3 =
    build_choose3_operand_instrs fresh_temp (Tcg.Temp trip_temp)
  in
  let twice_choose3 = fresh_temp () in
  let index_square_sum = fresh_temp () in
  let index_instrs =
    [ simplify_simple_instr
        (Tcg.Bin (twice_choose3, Mul, Tcg.Temp choose3, Tcg.Imm 2L));
      simplify_simple_instr
        (Tcg.Bin
           (index_square_sum, Add, Tcg.Temp twice_choose3, Tcg.Temp triangle)) ]
  in
  let base_square = fresh_temp () in
  let base_term = fresh_temp () in
  let base_instrs =
    [ simplify_simple_instr
        (Tcg.Bin
           (base_square, Mul, Tcg.Temp iv.phi_temp, Tcg.Temp iv.phi_temp));
      simplify_simple_instr
        (Tcg.Bin (base_term, Mul, Tcg.Temp base_square, Tcg.Temp trip_temp)) ]
  in
  let cross_operand, cross_instrs =
    if iv.step = 0L then
      (Tcg.Imm 0L, [])
    else
      let two_base = fresh_temp () in
      let scaled_base = fresh_temp () in
      let cross = fresh_temp () in
      ( Tcg.Temp cross,
        [ simplify_simple_instr
            (Tcg.Bin (two_base, Mul, Tcg.Temp iv.phi_temp, Tcg.Imm 2L));
          simplify_simple_instr
            (Tcg.Bin (scaled_base, Mul, Tcg.Temp two_base, Tcg.Imm iv.step));
          simplify_simple_instr
            (Tcg.Bin (cross, Mul, Tcg.Temp scaled_base, Tcg.Temp triangle)) ] )
  in
  let square_step_operand, square_step_instrs =
    if iv.step = 0L then
      (Tcg.Imm 0L, [])
    else if iv.step = 1L || iv.step = -1L then
      (Tcg.Temp index_square_sum, [])
    else
      let step_square = fresh_temp () in
      let scaled = fresh_temp () in
      ( Tcg.Temp scaled,
        [ simplify_simple_instr
            (Tcg.Bin (step_square, Mul, Tcg.Imm iv.step, Tcg.Imm iv.step));
          simplify_simple_instr
            (Tcg.Bin
               (scaled, Mul, Tcg.Temp step_square, Tcg.Temp index_square_sum)) ] )
  in
  let after_cross, cross_combine =
    match cross_operand with
    | Tcg.Imm 0L -> (Tcg.Temp base_term, [])
    | _ ->
        let dst = fresh_temp () in
        ( Tcg.Temp dst,
          [ simplify_simple_instr
              (Tcg.Bin (dst, Add, Tcg.Temp base_term, cross_operand)) ] )
  in
  let total, total_combine =
    match square_step_operand with
    | Tcg.Imm 0L -> (after_cross, [])
    | _ ->
        let dst = fresh_temp () in
        ( Tcg.Temp dst,
          [ simplify_simple_instr
              (Tcg.Bin (dst, Add, after_cross, square_step_operand)) ] )
  in
  ( triangle_instrs
    @ choose3_instrs
    @ index_instrs
    @ base_instrs
    @ cross_instrs
    @ square_step_instrs
    @ cross_combine
    @ total_combine,
    total )

let build_triangle_progression_sum_instrs fresh_temp trip_temp (iv : basic_induction_var) =
  (* For step=1:
       T(x+r) = T(x) + x*r + T(r)
     hence
       sum T(x+r)
         = N*T(x) + x*T(N) + C(N,3). *)
  if iv.step <> 1L then
    ([], None)
  else
    let base_triangle_instrs, base_triangle =
      build_triangle_number_operand_instrs
        fresh_temp (Tcg.Temp iv.phi_temp)
    in
    let trip_triangle_instrs, trip_triangle =
      build_triangle_number_instrs fresh_temp trip_temp
    in
    let choose3_instrs, choose3 =
      build_choose3_operand_instrs fresh_temp (Tcg.Temp trip_temp)
    in
    let base_sum = fresh_temp () in
    let cross = fresh_temp () in
    let first = fresh_temp () in
    let total = fresh_temp () in
    ( base_triangle_instrs
      @ trip_triangle_instrs
      @ choose3_instrs
      @ [ simplify_simple_instr
            (Tcg.Bin
               (base_sum, Mul, Tcg.Temp base_triangle, Tcg.Temp trip_temp));
          simplify_simple_instr
            (Tcg.Bin
               (cross, Mul, Tcg.Temp iv.phi_temp, Tcg.Temp trip_triangle));
          simplify_simple_instr
            (Tcg.Bin (first, Add, Tcg.Temp base_sum, Tcg.Temp cross));
          simplify_simple_instr
            (Tcg.Bin (total, Add, Tcg.Temp first, Tcg.Temp choose3)) ],
      Some (Tcg.Temp total) )


let build_choose3_progression_sum_instrs
    fresh_temp
    trip_temp
    (iv : basic_induction_var)
  =
  if not (basic_iv_known_nonnegative_step1 iv) then
    ([], None)
  else
    let final_value = fresh_temp () in
    let final_instr =
      simplify_simple_instr
        (Tcg.Bin
           (final_value, Add, Tcg.Temp iv.phi_temp, Tcg.Temp trip_temp))
    in
    let start_choose4_instrs, start_choose4 =
      build_choose4_operand_instrs fresh_temp (Tcg.Temp iv.phi_temp)
    in
    let final_choose4_instrs, final_choose4 =
      build_choose4_operand_instrs fresh_temp (Tcg.Temp final_value)
    in
    let sum = fresh_temp () in
    ( [ final_instr ]
      @ start_choose4_instrs
      @ final_choose4_instrs
      @ [ simplify_simple_instr
            (Tcg.Bin
               (sum, Sub, Tcg.Temp final_choose4, Tcg.Temp start_choose4)) ],
      Some (Tcg.Temp sum) )

let build_cubic_reduction_delta
    place_carriers
    fresh_temp
    trip_temp
    (iv : basic_induction_var)
    choose3
    triangle
    coeff
    bias
  =
  let scale_sum coeff_expr sum_operand =
    let coeff_instrs, coeff_operand =
      emit_summary_expr_with_carriers place_carriers fresh_temp coeff_expr
    in
    match coeff_operand with
    | Tcg.Imm 0L ->
        (coeff_instrs, None)
    | Tcg.Imm 1L ->
        (coeff_instrs, Some sum_operand)
    | _ ->
        let dst = fresh_temp () in
        ( coeff_instrs
          @ [ simplify_simple_instr
                (Tcg.Bin (dst, Mul, sum_operand, coeff_operand)) ],
          Some (Tcg.Temp dst) )
  in

  let choose3_sum_instrs, choose3_sum =
    if summary_expr_is_zero choose3 then
      ([], Some (Tcg.Imm 0L))
    else
      build_choose3_progression_sum_instrs fresh_temp trip_temp iv
  in

  let choose3_instrs, choose3_delta =
    match choose3_sum with
    | None ->
        (choose3_sum_instrs, None)
    | Some sum ->
        let scale_instrs, delta =
          scale_sum choose3 sum
        in
        (choose3_sum_instrs @ scale_instrs, delta)
  in

  let triangle_sum_instrs, triangle_sum =
    if summary_expr_is_zero triangle then
      ([], Some (Tcg.Imm 0L))
    else
      build_triangle_progression_sum_instrs fresh_temp trip_temp iv
  in

  let triangle_instrs, triangle_delta =
    match triangle_sum with
    | None ->
        (triangle_sum_instrs, None)
    | Some sum ->
        let scale_instrs, delta =
          scale_sum triangle sum
        in
        (triangle_sum_instrs @ scale_instrs, delta)
  in

  let affine_instrs, affine_delta =
    build_affine_reduction_delta
      place_carriers fresh_temp trip_temp iv coeff bias
  in

  let terms =
    [ choose3_delta; triangle_delta; affine_delta ]
    |> List.filter_map (fun value -> value)
    |> List.filter (function Tcg.Imm 0L -> false | _ -> true)
  in

  let rec combine instrs = function
    | [] ->
        (instrs, None)
    | [ term ] ->
        (instrs, Some term)
    | lhs :: rhs :: rest ->
        let dst = fresh_temp () in
        combine
          (instrs
           @ [ simplify_simple_instr
                 (Tcg.Bin (dst, Add, lhs, rhs)) ])
          (Tcg.Temp dst :: rest)
  in

  let combine_instrs, total =
    combine [] terms
  in
  ( choose3_instrs
    @ triangle_instrs
    @ affine_instrs
    @ combine_instrs,
    total )


let build_quadratic_reduction_delta
    place_carriers
    fresh_temp
    trip_temp
    (iv : basic_induction_var)
    quad
    triangle
    coeff
    bias
  =
  let scale_sum coeff_expr sum_operand =
    let coeff_instrs, coeff_operand =
      emit_summary_expr_with_carriers place_carriers fresh_temp coeff_expr
    in
    match coeff_operand with
    | Tcg.Imm 0L -> (coeff_instrs, None)
    | Tcg.Imm 1L -> (coeff_instrs, Some sum_operand)
    | _ ->
        let dst = fresh_temp () in
        ( coeff_instrs
          @ [ simplify_simple_instr
                (Tcg.Bin (dst, Mul, sum_operand, coeff_operand)) ],
          Some (Tcg.Temp dst) )
  in
  let square_instrs, square_sum =
    build_sum_squares_progression_instrs fresh_temp trip_temp iv
  in
  let quad_instrs, quad_delta =
    scale_sum quad square_sum
  in
  let triangle_sum_instrs, triangle_sum =
    if summary_expr_is_zero triangle then
      ([], Some (Tcg.Imm 0L))
    else
      build_triangle_progression_sum_instrs fresh_temp trip_temp iv
  in
  let triangle_instrs, triangle_delta =
    match triangle_sum with
    | None -> (triangle_sum_instrs, None)
    | Some sum ->
        let scale_instrs, delta = scale_sum triangle sum in
        (triangle_sum_instrs @ scale_instrs, delta)
  in
  let affine_instrs, affine_delta =
    build_affine_reduction_delta
      place_carriers fresh_temp trip_temp iv coeff bias
  in
  let terms =
    [ quad_delta; triangle_delta; affine_delta ]
    |> List.filter_map (fun value -> value)
    |> List.filter (function Tcg.Imm 0L -> false | _ -> true)
  in
  let rec combine instrs = function
    | [] -> (instrs, None)
    | [ term ] -> (instrs, Some term)
    | lhs :: rhs :: rest ->
        let dst = fresh_temp () in
        combine
          (instrs
           @ [ simplify_simple_instr (Tcg.Bin (dst, Add, lhs, rhs)) ])
          (Tcg.Temp dst :: rest)
  in
  let combine_instrs, total =
    combine [] terms
  in
  (square_instrs @ quad_instrs @ triangle_instrs @ affine_instrs @ combine_instrs, total)


let build_carrier_progression_reduction_delta
    place_carriers
    fresh_temp
    trip_temp
    carrier_temp
    step_expr
    carrier_subtract
    include_updated
  =
  let base_delta = fresh_temp () in
  let base_instrs =
    [ simplify_simple_instr (Tcg.Bin (base_delta, Mul, Tcg.Temp carrier_temp, Tcg.Temp trip_temp)) ]
  in
  let step_instrs, step_operand =
    emit_summary_expr_with_carriers place_carriers fresh_temp step_expr
  in
  match step_operand with
  | Tcg.Imm 0L -> (base_instrs @ step_instrs, Some (Tcg.Temp base_delta))
  | _ ->
      let triangle_instrs, triangle = build_triangle_number_instrs fresh_temp trip_temp in
      let series_count, series_count_instrs =
        if include_updated then
          let series_count = fresh_temp () in
          ( Tcg.Temp series_count,
            [ simplify_simple_instr
                (Tcg.Bin (series_count, Add, Tcg.Temp triangle, Tcg.Temp trip_temp)) ] )
        else (Tcg.Temp triangle, [])
      in
      let signed_step, signed_step_instrs =
        if carrier_subtract then
          let negated = fresh_temp () in
          ( Tcg.Temp negated,
            [ simplify_simple_instr (Tcg.Bin (negated, Sub, Tcg.Imm 0L, step_operand)) ] )
        else (step_operand, [])
      in
      let series_delta = fresh_temp () in
      let total_delta = fresh_temp () in
      ( base_instrs
        @ step_instrs
        @ triangle_instrs
        @ series_count_instrs
        @ signed_step_instrs
        @ [ simplify_simple_instr (Tcg.Bin (series_delta, Mul, series_count, signed_step));
            simplify_simple_instr (Tcg.Bin (total_delta, Add, Tcg.Temp base_delta, Tcg.Temp series_delta)) ],
        Some (Tcg.Temp total_delta) )

let build_reduction_final_update fresh_temp trip_temp place_carriers (reduction : counted_reduction)
  =
  let delta_instrs, delta_operand =
    match reduction.step with
    | ReductionInvariant step_expr ->
        build_invariant_reduction_delta place_carriers fresh_temp trip_temp step_expr
    | ReductionAffine { iv; coeff; bias } ->
        build_affine_reduction_delta place_carriers fresh_temp trip_temp iv coeff bias
    | ReductionQuadratic { iv; quad; triangle; coeff; bias } ->
        build_quadratic_reduction_delta
          place_carriers fresh_temp trip_temp iv quad triangle coeff bias
    | ReductionCubic { iv; choose3; triangle; coeff; bias } ->
        build_cubic_reduction_delta
          place_carriers fresh_temp trip_temp iv choose3 triangle coeff bias
    | ReductionCarrierProgression
        { carrier_temp; step_expr; carrier_subtract; include_updated } ->
        build_carrier_progression_reduction_delta
          place_carriers
          fresh_temp
          trip_temp
          carrier_temp
          step_expr
          carrier_subtract
          include_updated
  in
  match delta_operand with
  | None -> []
  | Some delta_operand ->
      (match reduction.target with
      | ReductionTempTarget phi_temp ->
          let update =
            if reduction.subtract then
              simplify_simple_instr
                (Tcg.Bin
                   (phi_temp, Sub, Tcg.Temp phi_temp, delta_operand))
            else
              simplify_simple_instr
                (Tcg.Bin
                   (phi_temp, Add, Tcg.Temp phi_temp, delta_operand))
           in
          let alias_updates =
            List.map
              (fun temp -> simplify_simple_instr (Tcg.Move (temp, Tcg.Temp phi_temp)))
              reduction.alias_temps
          in
          delta_instrs @ [ update ] @ alias_updates
      | ReductionPlaceTarget place ->
          let acc_temp, acc_instrs =
            match reduction.carrier_temp with
            | Some temp -> (temp, [])
            | None ->
                let temp = fresh_temp () in
                (temp, [ simplify_simple_instr (Tcg.Load (temp, place)) ])
          in
          let update =
            if reduction.subtract then
              simplify_simple_instr
                (Tcg.Bin
                   (acc_temp, Sub, Tcg.Temp acc_temp, delta_operand))
            else
              simplify_simple_instr
                (Tcg.Bin
                   (acc_temp, Add, Tcg.Temp acc_temp, delta_operand))
           in
          let alias_updates =
            List.map
              (fun temp -> simplify_simple_instr (Tcg.Move (temp, Tcg.Temp acc_temp)))
              (List.filter (fun temp -> temp <> acc_temp) reduction.alias_temps)
          in
           acc_instrs
           @ delta_instrs
           @ [ update; Tcg.Store (place, Tcg.Temp acc_temp) ]
           @ alias_updates)

let build_live_temp_reconstruction_updates fresh_temp place_carriers reconstruction_order reconstruction_exprs
  =
  reconstruction_order
  |> List.concat_map (fun temp ->
         match IntMap.find_opt temp reconstruction_exprs with
         | None -> []
         | Some expr ->
             let instrs, operand =
               emit_summary_expr_with_carriers place_carriers fresh_temp expr
             in
             (match operand with
             | Tcg.Temp src when src = temp -> instrs
             | _ -> instrs @ [ simplify_simple_instr (Tcg.Move (temp, operand)) ]))

let loop_instr_count loop blocks =
  List.fold_left
    (fun acc (block : Cfg.block) ->
      if LabelSet.mem block.label loop then acc + List.length block.body else acc)
    0 blocks

let loop_memory_ops_count loop blocks =
  let instr_cost = function
    | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> 1
    | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ -> 0
  in
  List.fold_left
    (fun acc (block : Cfg.block) ->
      if LabelSet.mem block.label loop then
        acc + List.fold_left (fun sum instr -> sum + instr_cost instr) 0 block.body
      else acc)
    0 blocks

let instr_uses_temp temp = function
  | Tcg.Move (_, src)
  | Tcg.Un (_, _, src) ->
      operand_has_temp temp src
  | Tcg.Bin (_, _, lhs, rhs) -> operand_has_temp temp lhs || operand_has_temp temp rhs
  | Tcg.Load _ -> false
  | Tcg.Store (_, value) -> operand_has_temp temp value
  | Tcg.Call (_, _, args) -> List.exists (operand_has_temp temp) args

let term_uses_temp temp = function
  | Cfg.Jump _ | Cfg.Return None -> false
  | Cfg.BranchZero (cond, _, _)
  | Cfg.BranchNonZero (cond, _, _)
  | Cfg.Return (Some cond) ->
      operand_has_temp temp cond
  | Cfg.BranchCompare (_, lhs, rhs, _, _) ->
      operand_has_temp temp lhs || operand_has_temp temp rhs

(* -------------------------------------------------------------------------- *)
(* item2.7a: LCSSA-lite live-out analysis (analysis only)                      *)
(*                                                                            *)
(* We deliberately do NOT rewrite CFG or insert carriers yet.  A temp is       *)
(* considered a loop live-out when:                                            *)
(*   1. it has at least one definition inside the natural loop; and             *)
(*   2. it is live-in to at least one loop exit target.                         *)
(*                                                                            *)
(* This uses the compiler's existing liveness solution instead of merely        *)
(* scanning for syntactic outside uses, so values redefined/killed before an    *)
(* outside use are not spuriously classified as loop live-outs.                 *)
(*                                                                            *)
(* Dedicated-exit information comes from LoopForest/LoopSimplify metadata.      *)
(* Multi-exit loops are analyzed and reported, but later carrier materialization *)
(* will initially be restricted to dedicated single-exit loops.                 *)
(* -------------------------------------------------------------------------- *)

type lcssa_lite_liveout = {
  lcssa_loop_header : Tcg.label;
  lcssa_loop_parent : Tcg.label option;
  lcssa_loop_depth : int;
  lcssa_temp : int;
  lcssa_def_blocks : Tcg.label list;
  lcssa_live_exit_targets : Tcg.label list;
  lcssa_outside_use_blocks : Tcg.label list;
  lcssa_single_exit_materializable : bool;
}

type lcssa_place_write_origin =
  | LcssaPlaceExclusive
  | LcssaPlaceChildOnly
  | LcssaPlaceMixed

type lcssa_lite_place_liveout = {
  lcssa_place_loop_header : Tcg.label;
  lcssa_place_loop_parent : Tcg.label option;
  lcssa_place_loop_depth : int;
  lcssa_place : Tcg.place;
  lcssa_store_blocks : Tcg.label list;
  lcssa_exclusive_store_blocks : Tcg.label list;
  lcssa_child_store_headers : Tcg.label list;
  lcssa_place_write_origin : lcssa_place_write_origin;
  lcssa_place_live_exit_targets : Tcg.label list;
  lcssa_outside_load_blocks : Tcg.label list;
  lcssa_single_exit_summary_candidate : bool;
  lcssa_direct_effect_candidate : bool;
  lcssa_child_effect_candidate : bool;
}

type lcssa_lite_loop_info = {
  lcssa_info_header : Tcg.label;
  lcssa_info_parent : Tcg.label option;
  lcssa_info_depth : int;
  lcssa_info_exit_targets : Tcg.label list;
  lcssa_info_dedicated_exits : bool;
  lcssa_info_temp_liveouts : lcssa_lite_liveout list;
  lcssa_info_place_liveouts : lcssa_lite_place_liveout list;
}

type lcssa_lite_report = {
  lcssa_forest : loop_forest;
  lcssa_infos : (Tcg.label, lcssa_lite_loop_info) Hashtbl.t;
  lcssa_total_temp_liveouts : int;
  lcssa_total_place_liveouts : int;
  lcssa_single_exit_temp_materializable_count : int;
  lcssa_single_exit_place_summary_count : int;
  lcssa_direct_place_effect_count : int;
  lcssa_child_place_effect_count : int;
}

let temps_defined_in_loop loop get_block =
  LabelSet.fold
    (fun label acc ->
      let block : Cfg.block = get_block label in
      List.fold_left
        (fun acc instr ->
          match defs_temp instr with
          | Some temp -> IntSet.add temp acc
          | None -> acc)
        acc block.body)
    loop IntSet.empty

let temp_def_blocks_in_loop temp loop get_block =
  LabelSet.fold
    (fun label blocks ->
      let block : Cfg.block = get_block label in
      if
        List.exists
          (fun instr -> defs_temp instr = Some temp)
          block.body
      then
        label :: blocks
      else
        blocks)
    loop []
  |> List.sort_uniq String.compare

let temp_outside_use_blocks temp loop (f : Cfg.func) =
  f.blocks
  |> List.filter_map
       (fun (block : Cfg.block) ->
         if LabelSet.mem block.label loop then None
         else if
           List.exists (instr_uses_temp temp) block.body
           || term_uses_temp temp block.term
         then
           Some block.label
         else
           None)
  |> List.sort_uniq String.compare

let local_places_stored_in_loop loop get_block =
  LabelSet.fold
    (fun label acc ->
      let block : Cfg.block = get_block label in
      List.fold_left
        (fun acc instr ->
          match instr with
          | Tcg.Store ((Tcg.Local _) as place, _) ->
              PlaceSet.add place acc
          | Tcg.Store (Tcg.Global _, _)
          | Tcg.Move _
          | Tcg.Un _
          | Tcg.Bin _
          | Tcg.Load _
          | Tcg.Call _ ->
              acc)
        acc block.body)
    loop PlaceSet.empty

let place_store_blocks_in_loop place loop get_block =
  LabelSet.fold
    (fun label blocks ->
      let block : Cfg.block = get_block label in
      if
        List.exists
          (function
            | Tcg.Store (stored, _) -> stored = place
            | Tcg.Move _
            | Tcg.Un _
            | Tcg.Bin _
            | Tcg.Load _
            | Tcg.Call _ ->
                false)
          block.body
      then label :: blocks
      else blocks)
    loop []
  |> List.sort_uniq String.compare

let place_outside_load_blocks place loop (f : Cfg.func) =
  f.blocks
  |> List.filter_map
       (fun (block : Cfg.block) ->
         if LabelSet.mem block.label loop then None
         else if
           List.exists
             (function
               | Tcg.Load (_, loaded) -> loaded = place
               | Tcg.Move _
               | Tcg.Un _
               | Tcg.Bin _
               | Tcg.Store _
               | Tcg.Call _ ->
                   false)
             block.body
         then Some block.label
         else None)
  |> List.sort_uniq String.compare

let lcssa_string_of_place = function
  | Tcg.Local id ->
      Printf.sprintf "local:%d" id
  | Tcg.Global label ->
      Printf.sprintf "global:%s" label

let lcssa_string_of_place_write_origin = function
  | LcssaPlaceExclusive -> "exclusive"
  | LcssaPlaceChildOnly -> "child-only"
  | LcssaPlaceMixed -> "mixed"

let child_loops_storing_place
    (forest : loop_forest)
    (info : loop_forest_info)
    place =
  info.loop_info_children
  |> List.filter
       (fun child_header ->
         let child_loop =
           table_find_or_empty
             forest.loop_forest_loops
             child_header LabelSet.empty
         in
         place_store_blocks_in_loop
           place child_loop
           (get_block_exn forest.loop_forest_block_map)
         <> [])
  |> List.sort_uniq String.compare

let dedicated_exit_targets_for_loop
    (forest : loop_forest)
    (info : loop_forest_info) =
  info.loop_info_exit_targets
  |> List.filter
       (fun exit_target ->
         let exit_block =
           get_block_exn
             forest.loop_forest_block_map
             exit_target
         in
         exit_block.preds <> []
         && List.for_all
              (fun pred ->
                LabelSet.mem
                  pred info.loop_info_blocks)
              exit_block.preds)

let build_lcssa_lite_report
    summaries globals
    (f : Cfg.func) =
  let forest = build_loop_forest f in
  let live_in_t, live_in_p =
    compute_liveness summaries globals f
  in
  let infos =
    Hashtbl.create
      (max 8 (List.length forest.loop_forest_headers))
  in
  let total_temp_liveouts = ref 0 in
  let total_place_liveouts = ref 0 in
  let temp_materializable = ref 0 in
  let place_summary_candidates = ref 0 in
  let direct_place_effects = ref 0 in
  let child_place_effects = ref 0 in
  List.iter
    (fun header ->
      match Hashtbl.find_opt forest.loop_forest_infos header with
      | None -> ()
      | Some loop_info ->
          let loop = loop_info.loop_info_blocks in
          let get_block =
            get_block_exn forest.loop_forest_block_map
          in
          let defined =
            temps_defined_in_loop loop get_block
          in
          let dedicated_exits =
            dedicated_exit_targets_for_loop forest loop_info
          in
          let dedicated_all =
            List.length dedicated_exits
            = List.length loop_info.loop_info_exit_targets
          in
          let single_exit =
            match dedicated_exits with
            | [ _ ] -> true
            | [] | _ :: _ :: _ -> false
          in
          let temp_liveouts =
            IntSet.fold
              (fun temp acc ->
                let live_exit_targets =
                  loop_info.loop_info_exit_targets
                  |> List.filter
                       (fun exit_target ->
                         IntSet.mem temp
                           (table_find_or_empty
                              live_in_t exit_target
                              IntSet.empty))
                in
                if live_exit_targets = [] then acc
                else
                  let item =
                    {
                      lcssa_loop_header = header;
                      lcssa_loop_parent =
                        loop_info.loop_info_parent;
                      lcssa_loop_depth =
                        loop_info.loop_info_depth;
                      lcssa_temp = temp;
                      lcssa_def_blocks =
                        temp_def_blocks_in_loop
                          temp loop get_block;
                      lcssa_live_exit_targets =
                        live_exit_targets;
                      lcssa_outside_use_blocks =
                        temp_outside_use_blocks
                          temp loop f;
                      lcssa_single_exit_materializable =
                        dedicated_all
                        && single_exit
                        && List.length live_exit_targets = 1;
                    }
                  in
                  incr total_temp_liveouts;
                  if item.lcssa_single_exit_materializable
                  then incr temp_materializable;
                  item :: acc)
              defined []
            |> List.rev
          in
          let stored_places =
            local_places_stored_in_loop loop get_block
          in
          let place_liveouts =
            PlaceSet.fold
              (fun place acc ->
                let live_exit_targets =
                  loop_info.loop_info_exit_targets
                  |> List.filter
                       (fun exit_target ->
                         PlaceSet.mem place
                           (table_find_or_empty
                              live_in_p exit_target
                              PlaceSet.empty))
                in
                if live_exit_targets = [] then acc
                else
                  let all_store_blocks =
                    place_store_blocks_in_loop
                      place loop get_block
                  in
                  let exclusive_store_blocks =
                    place_store_blocks_in_loop
                      place
                      loop_info.loop_info_exclusive_blocks
                      get_block
                  in
                  let child_store_headers =
                    child_loops_storing_place
                      forest loop_info place
                  in
                  let write_origin =
                    match
                      exclusive_store_blocks,
                      child_store_headers
                    with
                    | _ :: _, [] ->
                        LcssaPlaceExclusive
                    | [], _ :: _ ->
                        LcssaPlaceChildOnly
                    | _ :: _, _ :: _ ->
                        LcssaPlaceMixed
                    | [], [] ->
                        (* [place] came from [stored_places], so this should
                           only be reachable if loop metadata is stale.
                           Treat it conservatively as mixed/unknown rather
                           than enabling any direct summary. *)
                        LcssaPlaceMixed
                  in
                  let structural_summary_candidate =
                    dedicated_all
                    && single_exit
                    && List.length live_exit_targets = 1
                  in
                  let direct_effect_candidate =
                    structural_summary_candidate
                    && write_origin = LcssaPlaceExclusive
                  in
                  let child_effect_candidate =
                    structural_summary_candidate
                    && write_origin = LcssaPlaceChildOnly
                  in
                  let item =
                    {
                      lcssa_place_loop_header = header;
                      lcssa_place_loop_parent =
                        loop_info.loop_info_parent;
                      lcssa_place_loop_depth =
                        loop_info.loop_info_depth;
                      lcssa_place = place;
                      lcssa_store_blocks = all_store_blocks;
                      lcssa_exclusive_store_blocks =
                        exclusive_store_blocks;
                      lcssa_child_store_headers =
                        child_store_headers;
                      lcssa_place_write_origin =
                        write_origin;
                      lcssa_place_live_exit_targets =
                        live_exit_targets;
                      lcssa_outside_load_blocks =
                        place_outside_load_blocks
                          place loop f;
                      lcssa_single_exit_summary_candidate =
                        structural_summary_candidate;
                      lcssa_direct_effect_candidate =
                        direct_effect_candidate;
                      lcssa_child_effect_candidate =
                        child_effect_candidate;
                    }
                  in
                  incr total_place_liveouts;
                  if item.lcssa_single_exit_summary_candidate
                  then incr place_summary_candidates;
                  if item.lcssa_direct_effect_candidate
                  then incr direct_place_effects;
                  if item.lcssa_child_effect_candidate
                  then incr child_place_effects;
                  item :: acc)
              stored_places []
            |> List.rev
          in
          Hashtbl.replace infos header
            {
              lcssa_info_header = header;
              lcssa_info_parent =
                loop_info.loop_info_parent;
              lcssa_info_depth =
                loop_info.loop_info_depth;
              lcssa_info_exit_targets =
                loop_info.loop_info_exit_targets;
              lcssa_info_dedicated_exits =
                dedicated_all;
              lcssa_info_temp_liveouts = temp_liveouts;
              lcssa_info_place_liveouts = place_liveouts;
            })
    forest.loop_forest_headers;
  {
    lcssa_forest = forest;
    lcssa_infos = infos;
    lcssa_total_temp_liveouts = !total_temp_liveouts;
    lcssa_total_place_liveouts = !total_place_liveouts;
    lcssa_single_exit_temp_materializable_count =
      !temp_materializable;
    lcssa_single_exit_place_summary_count =
      !place_summary_candidates;
    lcssa_direct_place_effect_count =
      !direct_place_effects;
    lcssa_child_place_effect_count =
      !child_place_effects;
  }

(* -------------------------------------------------------------------------- *)
(* item2.7b: bottom-up child scalar-summary discovery (analysis only)           *)
(*                                                                            *)
(* This deliberately reuses the mature counted-loop/reduction machinery.        *)
(* We do not invent another arithmetic matcher here.  LCSSA provenance decides  *)
(* WHO owns a live-out write; counted-loop analysis decides WHAT the per-loop    *)
(* scalar effect is.                                                            *)
(*                                                                            *)
(* Direct summary:                                                             *)
(*   place is written exclusively at the current loop level, the loop has a     *)
(*   counted control, and [collect_counted_reductions] can prove a reduction    *)
(*   for that place.                                                            *)
(*                                                                            *)
(* Child link:                                                                 *)
(*   parent sees the place as child-only and names the immediate child whose    *)
(*   direct summary should be composed later.  No parent recurrence is built    *)
(*   yet.                                                                       *)
(* -------------------------------------------------------------------------- *)

type child_scalar_direct_summary = {
  child_summary_header : Tcg.label;
  child_summary_parent : Tcg.label option;
  child_summary_depth : int;
  child_summary_place : Tcg.place;
  child_summary_control : counted_loop_info;
  child_summary_reduction : counted_reduction;
}

type child_scalar_summary_link = {
  child_link_parent_header : Tcg.label;
  child_link_child_header : Tcg.label;
  child_link_place : Tcg.place;
  child_link_direct_summary_found : bool;
}

type child_scalar_trip_semantics = {
  child_trip_phi_temp : Tcg.temp;
  child_trip_step : int64;
  child_trip_kind : counted_loop_kind;
}

type child_scalar_invariant_transfer = {
  child_transfer_header : Tcg.label;
  child_transfer_parent : Tcg.label option;
  child_transfer_depth : int;
  child_transfer_place : Tcg.place;
  child_transfer_trip : child_scalar_trip_semantics;
  child_transfer_step_expr : summary_expr;
  child_transfer_subtract : bool;
}

type child_scalar_transfer_link = {
  child_transfer_link_parent : Tcg.label;
  child_transfer_link_child : Tcg.label;
  child_transfer_link_place : Tcg.place;
  child_transfer_link_resolved :
    child_scalar_invariant_transfer option;
}

type parent_child_composition_status =
  | ParentComposeReadyConstant
  | ParentComposeNeedsRuntimeGuard
  | ParentComposeReject of string

type parent_child_composition_proof = {
  parent_comp_parent_header : Tcg.label;
  parent_comp_child_header : Tcg.label;
  parent_comp_place : Tcg.place;
  parent_comp_child_start : loop_inv_expr option;
  parent_comp_child_bound : loop_inv_expr option;
  parent_comp_step_parent_invariant : bool;
  parent_comp_status : parent_child_composition_status;
}

type parent_child_runtime_guard_proof = {
  parent_runtime_parent_header : Tcg.label;
  parent_runtime_child_header : Tcg.label;
  parent_runtime_place : Tcg.place;
  parent_runtime_spec : symbolic_trip_spec;
  parent_runtime_family : symbolic_trip_proof_family;
  parent_runtime_guard_lhs : loop_inv_expr;
  parent_runtime_guard_rhs : loop_inv_expr;
  parent_runtime_fast_trip : loop_inv_expr;
  parent_runtime_step_expr : summary_expr;
  parent_runtime_subtract : bool;
}

type child_scalar_summary_report = {
  child_scalar_direct_summaries : child_scalar_direct_summary list;
  child_scalar_links : child_scalar_summary_link list;
  child_scalar_invariant_transfers :
    child_scalar_invariant_transfer list;
  child_scalar_transfer_links :
    child_scalar_transfer_link list;
  child_scalar_parent_composition_proofs :
    parent_child_composition_proof list;
  child_scalar_parent_runtime_guard_proofs :
    parent_child_runtime_guard_proof list;
}

let string_of_child_operand = function
  | Tcg.Imm value -> Int64.to_string value
  | Tcg.Temp temp -> Printf.sprintf "t%d" temp

let rec string_of_child_summary_expr = function
  | SummaryOperand operand ->
      string_of_child_operand operand
  | SummaryPlace place ->
      lcssa_string_of_place place
  | SummaryUn (op, expr) ->
      let op =
        match op with
        | UPlus -> "+"
        | UMinus -> "-"
        | UNot -> "!"
      in
      Printf.sprintf "%s(%s)"
        op (string_of_child_summary_expr expr)
  | SummaryBin (op, lhs, rhs) ->
      let op =
        match op with
        | Add -> "+"
        | Sub -> "-"
        | Mul -> "*"
        | Div -> "/"
        | Mod -> "%"
        | Lt -> "<"
        | Le -> "<="
        | Gt -> ">"
        | Ge -> ">="
        | Eq -> "=="
        | Ne -> "!="
        | LAnd -> "&&"
        | LOr -> "||"
      in
      Printf.sprintf "(%s%s%s)"
        (string_of_child_summary_expr lhs)
        op
        (string_of_child_summary_expr rhs)

let string_of_child_reduction_step = function
  | ReductionInvariant expr ->
      Printf.sprintf "invariant:%s"
        (string_of_child_summary_expr expr)
  | ReductionAffine { iv; coeff; bias } ->
      Printf.sprintf "affine:iv=t%d,coeff=%s,bias=%s"
        iv.phi_temp
        (string_of_child_summary_expr coeff)
        (string_of_child_summary_expr bias)
  | ReductionQuadratic
      { iv; quad; triangle; coeff; bias } ->
      Printf.sprintf
        "quadratic:iv=t%d,quad=%s,triangle=%s,coeff=%s,bias=%s"
        iv.phi_temp
        (string_of_child_summary_expr quad)
        (string_of_child_summary_expr triangle)
        (string_of_child_summary_expr coeff)
        (string_of_child_summary_expr bias)
  | ReductionCubic
      { iv; choose3; triangle; coeff; bias } ->
      Printf.sprintf
        "cubic:iv=t%d,choose3=%s,triangle=%s,coeff=%s,bias=%s"
        iv.phi_temp
        (string_of_child_summary_expr choose3)
        (string_of_child_summary_expr triangle)
        (string_of_child_summary_expr coeff)
        (string_of_child_summary_expr bias)
  | ReductionCarrierProgression
      { carrier_temp; step_expr; carrier_subtract;
        include_updated } ->
      Printf.sprintf
        "carrier:t%d,step=%s,subtract=%b,include-updated=%b"
        carrier_temp
        (string_of_child_summary_expr step_expr)
        carrier_subtract include_updated

let string_of_child_counted_kind = function
  | CountUpLt (bound, bias) ->
      Printf.sprintf "up-lt:bound=%s,bias=%Ld"
        (string_of_child_operand bound) bias
  | CountUpLe (bound, bias) ->
      Printf.sprintf "up-le:bound=%s,bias=%Ld"
        (string_of_child_operand bound) bias
  | CountDownGt (bound, bias) ->
      Printf.sprintf "down-gt:bound=%s,bias=%Ld"
        (string_of_child_operand bound) bias
  | CountDownGe (bound, bias) ->
      Printf.sprintf "down-ge:bound=%s,bias=%Ld"
        (string_of_child_operand bound) bias
  | CountUpLtScaled (bound, scale, bias) ->
      Printf.sprintf
        "up-lt-scaled:bound=%s,scale=%Ld,bias=%Ld"
        (string_of_child_operand bound) scale bias
  | CountUpLeScaled (bound, scale, bias) ->
      Printf.sprintf
        "up-le-scaled:bound=%s,scale=%Ld,bias=%Ld"
        (string_of_child_operand bound) scale bias
  | CountDownGtScaled (bound, scale, bias) ->
      Printf.sprintf
        "down-gt-scaled:bound=%s,scale=%Ld,bias=%Ld"
        (string_of_child_operand bound) scale bias
  | CountDownGeScaled (bound, scale, bias) ->
      Printf.sprintf
        "down-ge-scaled:bound=%s,scale=%Ld,bias=%Ld"
        (string_of_child_operand bound) scale bias

let child_trip_stride step =
  if step < 0L then Int64.neg step else step

let child_adjusted_bound_string bound bias =
  let bound = string_of_child_operand bound in
  if bias = 0L then bound
  else Printf.sprintf "(%s-%Ld)" bound bias

let string_of_child_trip_semantics
    (trip : child_scalar_trip_semantics) =
  let phi =
    Printf.sprintf "t%d" trip.child_trip_phi_temp
  in
  let stride = child_trip_stride trip.child_trip_step in
  let ceil_formula lhs rhs divisor =
    Printf.sprintf
      "max(0,ceil(((%s)-(%s))/%Ld))"
      lhs rhs divisor
  in
  let inclusive_formula lhs rhs divisor =
    Printf.sprintf
      "max(0,floor(((%s)-(%s))/%Ld)+1)"
      lhs rhs divisor
  in
  match trip.child_trip_kind with
  | CountUpLt (bound, bias) ->
      ceil_formula
        (child_adjusted_bound_string bound bias)
        phi stride
  | CountUpLe (bound, bias) ->
      inclusive_formula
        (child_adjusted_bound_string bound bias)
        phi stride
  | CountDownGt (bound, bias) ->
      ceil_formula
        phi
        (child_adjusted_bound_string bound bias)
        stride
  | CountDownGe (bound, bias) ->
      inclusive_formula
        phi
        (child_adjusted_bound_string bound bias)
        stride
  | CountUpLtScaled (bound, scale, bias) ->
      ceil_formula
        (child_adjusted_bound_string bound bias)
        (Printf.sprintf "(%Ld*%s)" scale phi)
        Int64.(mul scale stride)
  | CountUpLeScaled (bound, scale, bias) ->
      inclusive_formula
        (child_adjusted_bound_string bound bias)
        (Printf.sprintf "(%Ld*%s)" scale phi)
        Int64.(mul scale stride)
  | CountDownGtScaled (bound, scale, bias) ->
      ceil_formula
        (Printf.sprintf "(%Ld*%s)" scale phi)
        (child_adjusted_bound_string bound bias)
        Int64.(mul scale stride)
  | CountDownGeScaled (bound, scale, bias) ->
      inclusive_formula
        (Printf.sprintf "(%Ld*%s)" scale phi)
        (child_adjusted_bound_string bound bias)
        Int64.(mul scale stride)

let string_of_child_invariant_delta
    (transfer : child_scalar_invariant_transfer) =
  let trip =
    string_of_child_trip_semantics
      transfer.child_transfer_trip
  in
  let step =
    string_of_child_summary_expr
      transfer.child_transfer_step_expr
  in
  if step = "0" then "0"
  else if step = "1" then trip
  else if step = "-1" then
    Printf.sprintf "-(%s)" trip
  else
    Printf.sprintf "(%s*%s)" trip step

let parent_invariant_expr_of_operand
    loop_defs multi_defs def_instrs operand =
  let rec resolve seen operand =
    match operand with
    | Tcg.Imm value ->
        Some (LveConst value)
    | Tcg.Temp temp ->
        if IntSet.mem temp seen
           || IntSet.mem temp multi_defs
        then
          None
        else if not (IntSet.mem temp loop_defs) then
          lve_invariant_expr_of_operand
            loop_defs multi_defs def_instrs operand
          |> Option.map normalize_loop_inv_expr
        else
          let seen = IntSet.add temp seen in
          match Hashtbl.find_opt def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) ->
              resolve seen src
          | Some (Tcg.Un (_, UMinus, src)) ->
              Option.map
                (fun expr ->
                  normalize_loop_inv_expr (LveNeg expr))
                (resolve seen src)
          | Some (Tcg.Bin (_, Add, lhs, rhs)) -> (
              match resolve seen lhs, resolve seen rhs with
              | Some lhs, Some rhs ->
                  Some
                    (normalize_loop_inv_expr
                       (LveAdd (lhs, rhs)))
              | _ ->
                  None)
          | Some (Tcg.Bin (_, Sub, lhs, rhs)) -> (
              match resolve seen lhs, resolve seen rhs with
              | Some lhs, Some rhs ->
                  Some
                    (normalize_loop_inv_expr
                       (LveAdd (lhs, LveNeg rhs)))
              | _ ->
                  None)
          | Some (Tcg.Bin (_, Mul, lhs, rhs)) -> (
              match resolve seen lhs, resolve seen rhs with
              | Some lhs, Some rhs ->
                  Some
                    (normalize_loop_inv_expr
                       (LveMul (lhs, rhs)))
              | _ ->
                  None)
          | Some (Tcg.Un (_, UNot, _))
          | Some (Tcg.Bin (_, Div, _, _))
          | Some (Tcg.Bin (_, Mod, _, _))
          | Some (Tcg.Bin (_, Lt, _, _))
          | Some (Tcg.Bin (_, Le, _, _))
          | Some (Tcg.Bin (_, Gt, _, _))
          | Some (Tcg.Bin (_, Ge, _, _))
          | Some (Tcg.Bin (_, Eq, _, _))
          | Some (Tcg.Bin (_, Ne, _, _))
          | Some (Tcg.Bin (_, LAnd, _, _))
          | Some (Tcg.Bin (_, LOr, _, _))
          | Some (Tcg.Load _)
          | Some (Tcg.Store _)
          | Some (Tcg.Call _)
          | None ->
              None
  in
  resolve IntSet.empty operand

let common_parent_invariant_entry_expr
    loop_defs multi_defs def_instrs
    (iv : basic_induction_var) =
  match iv.outside_inputs with
  | [] ->
      None
  | (_, first_operand) :: rest ->
      Option.bind
        (parent_invariant_expr_of_operand
           loop_defs multi_defs def_instrs
           first_operand)
        (fun first ->
          let rec agree = function
            | [] ->
                Some first
            | (_, operand) :: tail -> (
                match
                  parent_invariant_expr_of_operand
                    loop_defs multi_defs def_instrs
                    operand
                with
                | Some other
                  when loop_inv_expr_equal first other ->
                    agree tail
                | Some _
                | None ->
                    None)
          in
          agree rest)

let counted_kind_bound_operand = function
  | CountUpLt (bound, _)
  | CountUpLe (bound, _)
  | CountDownGt (bound, _)
  | CountDownGe (bound, _)
  | CountUpLtScaled (bound, _, _)
  | CountUpLeScaled (bound, _, _)
  | CountDownGtScaled (bound, _, _)
  | CountDownGeScaled (bound, _, _) ->
      bound

let rec summary_expr_parent_invariant
    loop_defs multi_defs def_instrs effects = function
  | SummaryOperand operand ->
      Option.is_some
        (parent_invariant_expr_of_operand
           loop_defs multi_defs def_instrs operand)
  | SummaryPlace place ->
      load_place_invariant effects place
  | SummaryUn (_, expr) ->
      summary_expr_parent_invariant
        loop_defs multi_defs def_instrs effects expr
  | SummaryBin (_, lhs, rhs) ->
      summary_expr_parent_invariant
        loop_defs multi_defs def_instrs effects lhs
      &&
      summary_expr_parent_invariant
        loop_defs multi_defs def_instrs effects rhs

let loop_inv_expr_is_const expr =
  Option.is_some (loop_inv_expr_const_opt expr)

let string_of_parent_comp_status = function
  | ParentComposeReadyConstant ->
      "ready-constant"
  | ParentComposeNeedsRuntimeGuard ->
      "needs-runtime-guard"
  | ParentComposeReject reason ->
      "reject:" ^ reason

let string_of_parent_runtime_fast_delta
    (proof : parent_child_runtime_guard_proof) =
  let trip =
    string_of_loop_inv_expr proof.parent_runtime_fast_trip
  in
  let step =
    string_of_child_summary_expr proof.parent_runtime_step_expr
  in
  if step = "0" then "0"
  else if step = "1" then trip
  else if step = "-1" then
    Printf.sprintf "-(%s)" trip
  else
    Printf.sprintf "(%s*%s)" trip step

let reduction_targets_place place
    (reduction : counted_reduction) =
  match reduction.target with
  | ReductionPlaceTarget target ->
      target = place
  | ReductionTempTarget _ ->
      false

let direct_place_candidates_of_lcssa_info
    (info : lcssa_lite_loop_info) =
  info.lcssa_info_place_liveouts
  |> List.filter_map
       (fun item ->
         if item.lcssa_direct_effect_candidate then
           Some item.lcssa_place
         else
           None)
  |> List.sort_uniq compare

let build_child_scalar_summary_report
    summaries globals
    (f : Cfg.func)
    (lcssa_report : lcssa_lite_report) =
  let forest = lcssa_report.lcssa_forest in
  let get_block =
    get_block_exn forest.loop_forest_block_map
  in
  let blocks_snapshot = f.blocks in
  let direct_summaries_rev = ref [] in

  (* Bottom-up order matters conceptually even though this stage only
     discovers direct summaries: deepest loops are established first, so the
     link phase can reliably ask whether a child already has a summary. *)
  let headers_bottom_up =
    forest.loop_forest_headers
    |> List.filter_map
         (fun header ->
           match Hashtbl.find_opt
                   forest.loop_forest_infos header with
           | Some info ->
               Some (header, info.loop_info_depth)
           | None ->
               None)
    |> List.sort
         (fun (ha, da) (hb, db) ->
           let by_depth = compare db da in
           if by_depth <> 0 then by_depth
           else String.compare ha hb)
    |> List.map fst
  in

  List.iter
    (fun header ->
      match
        Hashtbl.find_opt lcssa_report.lcssa_infos header,
        Hashtbl.find_opt forest.loop_forest_infos header
      with
      | Some lcssa_info, Some loop_info ->
          let direct_places =
            direct_place_candidates_of_lcssa_info lcssa_info
          in
          if direct_places <> [] then begin
            let loop = loop_info.loop_info_blocks in
            let
              ( loop_defs,
                def_blocks,
                def_instrs,
                multi_defs,
                loop_stable_phis,
                ivs,
                control,
                recurrence_facts ) =
              analyze_counted_loop_for_elimination
                header loop get_block
                f.temp_count blocks_snapshot
            in
            match control with
            | None ->
                ()
            | Some control ->
                let effects =
                  collect_loop_effects
                    summaries globals loop blocks_snapshot
                in
                let invariant_loaded_places =
                  PlaceSet.diff
                    (local_places (locals_in_func f))
                    (local_places effects.modified_places)
                in
                let live_in_t, live_in_p =
                  compute_liveness summaries globals f
                in
                let live_t_exit =
                  table_find_or_empty
                    live_in_t control.exit_label IntSet.empty
                in
                let live_p_exit =
                  table_find_or_empty
                    live_in_p control.exit_label PlaceSet.empty
                in
                let loop_live_defs =
                  IntSet.inter loop_defs live_t_exit
                in
                let excluded_temps =
                  List.fold_left
                    (fun acc (iv : basic_induction_var) ->
                      IntSet.add iv.phi_temp acc)
                    IntSet.empty ivs
                in
                let requested_places =
                  List.fold_left
                    (fun acc place ->
                      if PlaceSet.mem place live_p_exit then
                        PlaceSet.add place acc
                      else
                        acc)
                    PlaceSet.empty direct_places
                in
                let reductions =
                  collect_counted_reductions
                    ~recurrence_facts
                    header
                    loop
                    invariant_loaded_places
                    loop_defs
                    get_block
                    def_blocks
                    loop_stable_phis
                    multi_defs
                    def_instrs
                    ivs
                    excluded_temps
                    loop_live_defs
                    requested_places
                in
                let reductions, _ =
                  resolve_counted_carrier_orders
                    header loop get_block
                    multi_defs def_instrs ivs reductions
                in
                List.iter
                  (fun place ->
                    match
                      List.find_opt
                        (reduction_targets_place place)
                        reductions
                    with
                    | None ->
                        ()
                    | Some reduction ->
                        direct_summaries_rev :=
                          {
                            child_summary_header = header;
                            child_summary_parent =
                              loop_info.loop_info_parent;
                            child_summary_depth =
                              loop_info.loop_info_depth;
                            child_summary_place = place;
                            child_summary_control = control;
                            child_summary_reduction = reduction;
                          }
                          :: !direct_summaries_rev)
                  direct_places
          end
      | _ ->
          ())
    headers_bottom_up;

  let direct_summaries =
    List.rev !direct_summaries_rev
  in
  let direct_summary_exists child_header place =
    List.exists
      (fun summary ->
        summary.child_summary_header = child_header
        && summary.child_summary_place = place)
      direct_summaries
  in
  let links =
    forest.loop_forest_headers
    |> List.concat_map
         (fun parent_header ->
           match
             Hashtbl.find_opt
               lcssa_report.lcssa_infos parent_header
           with
           | None ->
               []
           | Some info ->
               info.lcssa_info_place_liveouts
               |> List.concat_map
                    (fun item ->
                      if
                        not item.lcssa_child_effect_candidate
                      then
                        []
                      else
                        item.lcssa_child_store_headers
                        |> List.map
                             (fun child_header ->
                               {
                                 child_link_parent_header =
                                   parent_header;
                                 child_link_child_header =
                                   child_header;
                                 child_link_place =
                                   item.lcssa_place;
                                 child_link_direct_summary_found =
                                   direct_summary_exists
                                     child_header
                                     item.lcssa_place;
                               })))
  in
  let invariant_transfers =
    direct_summaries
    |> List.filter_map
         (fun summary ->
           match summary.child_summary_reduction.step with
           | ReductionInvariant step_expr ->
               Some
                 {
                   child_transfer_header =
                     summary.child_summary_header;
                   child_transfer_parent =
                     summary.child_summary_parent;
                   child_transfer_depth =
                     summary.child_summary_depth;
                   child_transfer_place =
                     summary.child_summary_place;
                   child_transfer_trip =
                     {
                       child_trip_phi_temp =
                         summary.child_summary_control.control_iv.phi_temp;
                       child_trip_step =
                         summary.child_summary_control.control_iv.step;
                       child_trip_kind =
                         summary.child_summary_control.kind;
                     };
                   child_transfer_step_expr = step_expr;
                   child_transfer_subtract =
                     summary.child_summary_reduction.subtract;
                 }
           | ReductionAffine _
           | ReductionQuadratic _
           | ReductionCubic _
           | ReductionCarrierProgression _ ->
               None)
  in
  let find_transfer child_header place =
    List.find_opt
      (fun transfer ->
        transfer.child_transfer_header = child_header
        && transfer.child_transfer_place = place)
      invariant_transfers
  in
  let transfer_links =
    links
    |> List.map
         (fun link ->
           {
             child_transfer_link_parent =
               link.child_link_parent_header;
             child_transfer_link_child =
               link.child_link_child_header;
             child_transfer_link_place =
               link.child_link_place;
             child_transfer_link_resolved =
               find_transfer
                 link.child_link_child_header
                 link.child_link_place;
           })
  in
  let parent_composition_proofs =
    transfer_links
    |> List.filter_map
         (fun link ->
           match
             link.child_transfer_link_resolved,
             Hashtbl.find_opt
               forest.loop_forest_infos
               link.child_transfer_link_parent
           with
           | Some transfer, Some parent_info ->
               let parent_loop =
                 parent_info.loop_info_blocks
               in
               let
                 ( parent_loop_defs,
                   _,
                   parent_def_instrs,
                   parent_multi_defs ) =
                 analyze_temp_defs_of_blocks
                   ~loop:parent_loop
                   f.temp_count f.blocks
               in
               let parent_effects =
                 collect_loop_effects
                   summaries globals
                   parent_loop f.blocks
               in
               let child_summary =
                 List.find_opt
                   (fun summary ->
                     summary.child_summary_header =
                       link.child_transfer_link_child
                     &&
                     summary.child_summary_place =
                       link.child_transfer_link_place)
                   direct_summaries
               in
               Option.map
                 (fun summary ->
                   let start_expr =
                     common_parent_invariant_entry_expr
                       parent_loop_defs
                       parent_multi_defs
                       parent_def_instrs
                       summary.child_summary_control.control_iv
                   in
                   let bound_expr =
                     parent_invariant_expr_of_operand
                       parent_loop_defs
                       parent_multi_defs
                       parent_def_instrs
                       (counted_kind_bound_operand
                          summary.child_summary_control.kind)
                   in
                   let step_parent_invariant =
                     summary_expr_parent_invariant
                       parent_loop_defs
                       parent_multi_defs
                       parent_def_instrs
                       parent_effects
                       transfer.child_transfer_step_expr
                   in
                   let status =
                     match
                       start_expr,
                       bound_expr,
                       step_parent_invariant
                     with
                     | None, _, _ ->
                         ParentComposeReject
                           "child-entry-start-not-parent-invariant"
                     | _, None, _ ->
                         ParentComposeReject
                           "child-bound-not-parent-invariant"
                     | _, _, false ->
                         ParentComposeReject
                           "reduction-step-not-parent-invariant"
                     | Some start, Some bound, true
                       when
                         loop_inv_expr_is_const start
                         && loop_inv_expr_is_const bound ->
                         ParentComposeReadyConstant
                     | Some _, Some _, true ->
                         ParentComposeNeedsRuntimeGuard
                   in
                   {
                     parent_comp_parent_header =
                       link.child_transfer_link_parent;
                     parent_comp_child_header =
                       link.child_transfer_link_child;
                     parent_comp_place =
                       link.child_transfer_link_place;
                     parent_comp_child_start = start_expr;
                     parent_comp_child_bound = bound_expr;
                     parent_comp_step_parent_invariant =
                       step_parent_invariant;
                     parent_comp_status = status;
                   })
                 child_summary
           | None, _
           | _, None ->
               None)
  in
  let runtime_guard_proofs =
    parent_composition_proofs
    |> List.filter_map
         (fun proof ->
           match
             proof.parent_comp_status,
             proof.parent_comp_child_start,
             proof.parent_comp_child_bound
           with
           | ParentComposeNeedsRuntimeGuard,
             Some start_expr,
             Some bound_expr ->
               let child_summary =
                 List.find_opt
                   (fun summary ->
                     summary.child_summary_header =
                       proof.parent_comp_child_header
                     &&
                     summary.child_summary_place =
                       proof.parent_comp_place)
                   direct_summaries
               in
               let transfer =
                 List.find_opt
                   (fun transfer ->
                     transfer.child_transfer_header =
                       proof.parent_comp_child_header
                     &&
                     transfer.child_transfer_place =
                       proof.parent_comp_place)
                   invariant_transfers
               in
               begin
                 match child_summary, transfer with
                 | Some summary, Some transfer -> (
                     match
                       summary.child_summary_control.kind,
                       loop_inv_expr_const_opt start_expr
                     with
                     | CountUpLt (_, bias),
                       Some start_const
                       when
                         bias = 0L
                         && start_const >= 0L
                         && summary.child_summary_control.control_iv.step = 1L
                         && proof.parent_comp_step_parent_invariant ->
                         let spec =
                           {
                             symbolic_trip_start =
                               normalize_loop_inv_expr start_expr;
                             symbolic_trip_step =
                               scalar_inv_one;
                             symbolic_trip_scale =
                               scalar_inv_one;
                             symbolic_trip_bias =
                               scalar_inv_zero;
                             symbolic_trip_bound =
                               normalize_loop_inv_expr bound_expr;
                             symbolic_trip_op = Lt;
                           }
                         in
                         begin
                           match
                             classify_symbolic_trip_proof_family spec
                           with
                           | None ->
                               None
                           | Some family ->
                               let fast_trip =
                                 normalize_loop_inv_expr
                                   (LveAdd
                                      ( bound_expr,
                                        LveNeg start_expr ))
                               in
                               Some
                                 {
                                   parent_runtime_parent_header =
                                     proof.parent_comp_parent_header;
                                   parent_runtime_child_header =
                                     proof.parent_comp_child_header;
                                   parent_runtime_place =
                                     proof.parent_comp_place;
                                   parent_runtime_spec = spec;
                                   parent_runtime_family = family;
                                   parent_runtime_guard_lhs =
                                     normalize_loop_inv_expr start_expr;
                                   parent_runtime_guard_rhs =
                                     normalize_loop_inv_expr bound_expr;
                                   parent_runtime_fast_trip =
                                     fast_trip;
                                   parent_runtime_step_expr =
                                     transfer.child_transfer_step_expr;
                                   parent_runtime_subtract =
                                     transfer.child_transfer_subtract;
                                 }
                         end
                     | CountUpLt _, _
                     | CountUpLe _, _
                     | CountDownGt _, _
                     | CountDownGe _, _
                     | CountUpLtScaled _, _
                     | CountUpLeScaled _, _
                     | CountDownGtScaled _, _
                     | CountDownGeScaled _, _ ->
                         None)
                 | None, _
                 | _, None ->
                     None
               end
           | ParentComposeReadyConstant, _, _
           | ParentComposeReject _, _, _
           | ParentComposeNeedsRuntimeGuard, None, _
           | ParentComposeNeedsRuntimeGuard, _, None ->
               None)
  in
  {
    child_scalar_direct_summaries =
      direct_summaries;
    child_scalar_links = links;
    child_scalar_invariant_transfers =
      invariant_transfers;
    child_scalar_transfer_links =
      transfer_links;
    child_scalar_parent_composition_proofs =
      parent_composition_proofs;
    child_scalar_parent_runtime_guard_proofs =
      runtime_guard_proofs;
  }

let debug_child_scalar_summary_report
    summaries globals
    (f : Cfg.func)
    (lcssa_report : lcssa_lite_report) =
  if
    Sys.getenv_opt "TOYC_DEBUG_LCSSA_LITE"
    <> None
  then begin
    let report =
      build_child_scalar_summary_report
        summaries globals f lcssa_report
    in
    List.iter
      (fun summary ->
        let reduction = summary.child_summary_reduction in
        Printf.eprintf
          "child-scalar-direct func=%s header=%s depth=%d parent=%s place=%s control-iv=t%d outside-inputs=%d iv-step=%Ld control=%s subtract=%b reduction=%s\n%!"
          f.name
          summary.child_summary_header
          summary.child_summary_depth
          (match summary.child_summary_parent with
           | Some parent -> parent
           | None -> "<root>")
          (lcssa_string_of_place
             summary.child_summary_place)
          summary.child_summary_control.control_iv.phi_temp
          (List.length
             summary.child_summary_control.control_iv.outside_inputs)
          summary.child_summary_control.control_iv.step
          (string_of_child_counted_kind
             summary.child_summary_control.kind)
          reduction.subtract
          (string_of_child_reduction_step
             reduction.step))
      report.child_scalar_direct_summaries;
    List.iter
      (fun link ->
        Printf.eprintf
          "child-scalar-link func=%s parent=%s child=%s place=%s direct-summary-found=%b\n%!"
          f.name
          link.child_link_parent_header
          link.child_link_child_header
          (lcssa_string_of_place link.child_link_place)
          link.child_link_direct_summary_found)
      report.child_scalar_links;
    List.iter
      (fun transfer ->
        let trip =
          string_of_child_trip_semantics
            transfer.child_transfer_trip
        in
        let delta =
          string_of_child_invariant_delta transfer
        in
        Printf.eprintf
          "child-scalar-transfer func=%s header=%s depth=%d parent=%s place=%s trip=%s step=%s delta=%s update=%s\n%!"
          f.name
          transfer.child_transfer_header
          transfer.child_transfer_depth
          (match transfer.child_transfer_parent with
           | Some parent -> parent
           | None -> "<root>")
          (lcssa_string_of_place
             transfer.child_transfer_place)
          trip
          (string_of_child_summary_expr
             transfer.child_transfer_step_expr)
          delta
          (if transfer.child_transfer_subtract
           then "place_out=place_in-delta"
           else "place_out=place_in+delta"))
      report.child_scalar_invariant_transfers;
    List.iter
      (fun link ->
        match link.child_transfer_link_resolved with
        | None ->
            Printf.eprintf
              "parent-child-transfer func=%s parent=%s child=%s place=%s resolved=false\n%!"
              f.name
              link.child_transfer_link_parent
              link.child_transfer_link_child
              (lcssa_string_of_place
                 link.child_transfer_link_place)
        | Some transfer ->
            Printf.eprintf
              "parent-child-transfer func=%s parent=%s child=%s place=%s resolved=true delta=%s update=%s\n%!"
              f.name
              link.child_transfer_link_parent
              link.child_transfer_link_child
              (lcssa_string_of_place
                 link.child_transfer_link_place)
              (string_of_child_invariant_delta transfer)
              (if transfer.child_transfer_subtract
               then "place_out=place_in-delta"
               else "place_out=place_in+delta"))
      report.child_scalar_transfer_links;
    List.iter
      (fun proof ->
        Printf.eprintf
          "parent-compose-proof func=%s parent=%s child=%s place=%s start=%s bound=%s step-parent-invariant=%b status=%s\n%!"
          f.name
          proof.parent_comp_parent_header
          proof.parent_comp_child_header
          (lcssa_string_of_place proof.parent_comp_place)
          (match proof.parent_comp_child_start with
           | Some expr -> string_of_loop_inv_expr expr
           | None -> "<unknown>")
          (match proof.parent_comp_child_bound with
           | Some expr -> string_of_loop_inv_expr expr
           | None -> "<unknown>")
          proof.parent_comp_step_parent_invariant
          (string_of_parent_comp_status
             proof.parent_comp_status))
      report.child_scalar_parent_composition_proofs;
    List.iter
      (fun proof ->
        Printf.eprintf
          "parent-runtime-guard-proof func=%s parent=%s child=%s place=%s family=%s guard=(%s<%s) fast-trip=%s slow-trip=0 fast-delta=%s fast-update=%s slow-update=identity\n%!"
          f.name
          proof.parent_runtime_parent_header
          proof.parent_runtime_child_header
          (lcssa_string_of_place proof.parent_runtime_place)
          (string_of_symbolic_trip_proof_family
             proof.parent_runtime_family)
          (string_of_loop_inv_expr
             proof.parent_runtime_guard_lhs)
          (string_of_loop_inv_expr
             proof.parent_runtime_guard_rhs)
          (string_of_loop_inv_expr
             proof.parent_runtime_fast_trip)
          (string_of_parent_runtime_fast_delta proof)
          (if proof.parent_runtime_subtract
           then "place_out=place_in-fast-delta"
           else "place_out=place_in+fast-delta"))
      report.child_scalar_parent_runtime_guard_proofs;
    Printf.eprintf
      "child-scalar-summary func=%s direct=%d links=%d resolved-links=%d invariant-transfers=%d resolved-transfers=%d parent-compose-proofs=%d runtime-guard-proofs=%d\n%!"
      f.name
      (List.length report.child_scalar_direct_summaries)
      (List.length report.child_scalar_links)
      (List.fold_left
         (fun count link ->
           if link.child_link_direct_summary_found
           then count + 1
           else count)
         0 report.child_scalar_links)
      (List.length report.child_scalar_invariant_transfers)
      (List.fold_left
         (fun count link ->
           match link.child_transfer_link_resolved with
           | Some _ -> count + 1
           | None -> count)
         0 report.child_scalar_transfer_links)
      (List.length
         report.child_scalar_parent_composition_proofs)
      (List.length
         report.child_scalar_parent_runtime_guard_proofs)
  end

let debug_lcssa_lite_report
    summaries globals
    (f : Cfg.func) =
  if Sys.getenv_opt "TOYC_DEBUG_LCSSA_LITE" <> None then begin
    let report =
      build_lcssa_lite_report summaries globals f
    in
    List.iter
      (fun header ->
        match Hashtbl.find_opt report.lcssa_infos header with
        | None -> ()
        | Some info ->
            Printf.eprintf
              "lcssa-lite-loop func=%s header=%s depth=%d parent=%s exits={%s} dedicated=%b temp-liveouts=%d place-liveouts=%d\n%!"
              f.name
              header
              info.lcssa_info_depth
              (match info.lcssa_info_parent with
               | Some parent -> parent
               | None -> "<root>")
              (String.concat "," info.lcssa_info_exit_targets)
              info.lcssa_info_dedicated_exits
              (List.length info.lcssa_info_temp_liveouts)
              (List.length info.lcssa_info_place_liveouts);
            List.iter
              (fun item ->
                Printf.eprintf
                  "lcssa-lite-temp-liveout func=%s header=%s depth=%d temp=t%d defs={%s} live-exits={%s} outside-uses={%s} materializable=%b\n%!"
                  f.name
                  item.lcssa_loop_header
                  item.lcssa_loop_depth
                  item.lcssa_temp
                  (String.concat "," item.lcssa_def_blocks)
                  (String.concat "," item.lcssa_live_exit_targets)
                  (String.concat "," item.lcssa_outside_use_blocks)
                  item.lcssa_single_exit_materializable)
              info.lcssa_info_temp_liveouts;
            List.iter
              (fun item ->
                Printf.eprintf
                  "lcssa-lite-place-liveout func=%s header=%s depth=%d place=%s origin=%s stores={%s} exclusive-stores={%s} child-writers={%s} live-exits={%s} outside-loads={%s} summary-candidate=%b direct-effect=%b child-effect=%b\n%!"
                  f.name
                  item.lcssa_place_loop_header
                  item.lcssa_place_loop_depth
                  (lcssa_string_of_place item.lcssa_place)
                  (lcssa_string_of_place_write_origin
                     item.lcssa_place_write_origin)
                  (String.concat "," item.lcssa_store_blocks)
                  (String.concat ","
                     item.lcssa_exclusive_store_blocks)
                  (String.concat ","
                     item.lcssa_child_store_headers)
                  (String.concat "," item.lcssa_place_live_exit_targets)
                  (String.concat "," item.lcssa_outside_load_blocks)
                  item.lcssa_single_exit_summary_candidate
                  item.lcssa_direct_effect_candidate
                  item.lcssa_child_effect_candidate)
              info.lcssa_info_place_liveouts)
      report.lcssa_forest.loop_forest_headers;
    Printf.eprintf
      "lcssa-lite-summary func=%s loops=%d temp-liveouts=%d place-liveouts=%d temp-materializable=%d place-summary-candidates=%d direct-place-effects=%d child-place-effects=%d\n%!"
      f.name
      (List.length report.lcssa_forest.loop_forest_headers)
      report.lcssa_total_temp_liveouts
      report.lcssa_total_place_liveouts
      report.lcssa_single_exit_temp_materializable_count
      report.lcssa_single_exit_place_summary_count
      report.lcssa_direct_place_effect_count
      report.lcssa_child_place_effect_count;
    debug_child_scalar_summary_report
      summaries globals f report
  end

let collect_direct_extractable_reductions loop get_block backedge_preds reductions =
  let last_def_index_for_temp temp (block : Cfg.block) =
    let last_index = ref None in
    List.iteri
      (fun index instr ->
        match defs_temp instr with
        | Some dst when dst = temp -> last_index := Some index
        | Some _ | None -> ())
      block.body;
    !last_index
  in
  List.filter_map
    (fun (reduction : counted_reduction) ->
      match reduction.target with
      | ReductionPlaceTarget _ -> None
      | ReductionTempTarget phi_temp ->
          let allowed_defs =
            List.fold_left
              (fun acc pred ->
                match acc with
                | None -> None
                | Some acc -> (
                    match last_def_index_for_temp phi_temp (get_block pred) with
                    | Some index ->
                        let instr = List.nth (get_block pred).body index in
                        if instr_uses_temp phi_temp instr then Some ((pred, index) :: acc)
                        else None
                    | None -> None))
              (Some []) backedge_preds
          in
          match allowed_defs with
          | None -> None
          | Some allowed_defs ->
              let allowed_index label = List.assoc_opt label allowed_defs in
              let ok = ref true in
              LabelSet.iter
                (fun label ->
                  let block : Cfg.block = get_block label in
                  List.iteri
                    (fun index instr ->
                      if
                        instr_uses_temp phi_temp instr
                        || defs_temp instr = Some phi_temp
                      then
                        match allowed_index label with
                        | Some allowed when allowed = index -> ()
                        | Some _ | None -> ok := false)
                    block.body;
                  if term_uses_temp phi_temp block.term then ok := false)
                loop;
               if !ok then Some (reduction, allowed_defs) else None)
    reductions

let split_reductions_min_instrs = 12
let split_reductions_min_pressure = 2

let extract_counted_reductions_func summaries globals (f : Cfg.func) =
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let current_blocks = Hashtbl.create (List.length f.blocks + (2 * List.length headers)) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let get_block = get_block_exn current_blocks in
    let update_block (block : Cfg.block) =
      Hashtbl.replace current_blocks block.label block
    in
    let original_block_labels =
      List.map (fun (block : Cfg.block) -> block.label) f.blocks
    in
    let original_block_set =
      List.fold_left
        (fun acc label -> LabelSet.add label acc)
        LabelSet.empty
        original_block_labels
    in
    let current_block_list () =
      let original_blocks =
        List.filter_map
          (fun label -> Hashtbl.find_opt current_blocks label)
          original_block_labels
      in
      let extra_blocks =
        Hashtbl.fold
          (fun label block acc ->
            if LabelSet.mem label original_block_set then acc
            else block :: acc)
          current_blocks
          []
        |> List.sort
             (fun (a : Cfg.block) (b : Cfg.block) ->
               String.compare a.label b.label)
      in
      original_blocks @ extra_blocks
    in
    let next_temp = ref f.temp_count in
    let fresh_temp () =
      let temp = !next_temp in
      incr next_temp;
      temp
    in
    let new_blocks_rev = ref [] in
    let preheader_id = ref 0 in
    let fresh_preheader_label () =
      let id = !preheader_id in
      incr preheader_id;
      Printf.sprintf ".L%s_split_preheader_%d" f.label id
    in
    let summary_id = ref 0 in
    let fresh_summary_label () =
      let id = !summary_id in
      incr summary_id;
      Printf.sprintf ".L%s_split_summary_%d" f.label id
    in
    let changed = ref false in
    let current_entry = ref f.entry in
    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        let header_block : Cfg.block = get_block header in
        let blocks_snapshot = current_block_list () in
        let
          ( loop_defs,
            def_blocks,
            def_instrs,
            multi_defs,
            loop_stable_phis,
            ivs,
            control,
            recurrence_facts ) =
          analyze_counted_loop_for_elimination
            header loop get_block !next_temp blocks_snapshot
        in
        let effects = collect_loop_effects summaries globals loop blocks_snapshot in
        let invariant_loaded_places =
          PlaceSet.diff
            (local_places (locals_in_func { f with entry = !current_entry; blocks = blocks_snapshot }))
            (local_places effects.modified_places)
        in
        let total_instrs = loop_instr_count loop blocks_snapshot in
        let memory_ops = loop_memory_ops_count loop blocks_snapshot in
        match control with
        | None -> ()
        | Some info -> (
            match counted_loop_shape_supported info.control_label loop get_block info.inside_label with
            | false -> ()
            | true ->
                let live_in_t, live_in_p =
                  compute_liveness summaries globals
                    { f with entry = !current_entry; blocks = blocks_snapshot }
                in
                let live_t_exit = table_find_or_empty live_in_t info.exit_label IntSet.empty in
                let live_p_exit = table_find_or_empty live_in_p info.exit_label PlaceSet.empty in
                let live_ivs =
                  let syntactic_live =
                    List.filter
                      (fun (iv : basic_induction_var) ->
                        iv.phi_temp = info.control_iv.phi_temp
                        || IntSet.mem iv.phi_temp live_t_exit)
                      ivs
                  in
                  if
                    List.exists
                      (fun (iv : basic_induction_var) ->
                        iv.phi_temp
                        = info.control_iv.phi_temp)
                      syntactic_live
                  then
                    syntactic_live
                  else
                    info.control_iv :: syntactic_live
                in
                let loop_live_defs = IntSet.inter loop_defs live_t_exit in
                let excluded_temps =
                  List.fold_left
                    (fun acc (iv : basic_induction_var) -> IntSet.add iv.phi_temp acc)
                    IntSet.empty live_ivs
                in
                let reductions =
                  collect_counted_reductions
                    ~recurrence_facts
                    header
                    loop
                    invariant_loaded_places
                    loop_defs
                    get_block
                    def_blocks
                    loop_stable_phis
                    multi_defs
                    def_instrs
                    ivs
                    excluded_temps
                    loop_live_defs
                    (PlaceSet.inter (local_places effects.modified_places) live_p_exit)
                in
                let reductions, ambiguous_iv_carrier_reductions =
                  resolve_counted_carrier_orders
                    header loop get_block multi_defs def_instrs ivs reductions
                in
                let all_updates =
                  (List.map (fun iv -> CountedIv iv) live_ivs)
                  @ List.map (fun reduction -> CountedReduction reduction) reductions
                in
                let supported_live_temps =
                  List.fold_left
                    (fun acc update ->
                      match update with
                      | CountedIv _ ->
                          IntSet.add (counted_update_temp update) acc
                      | CountedReduction ({ target = ReductionTempTarget _; _ } as reduction) ->
                          add_reduction_alias_temps
                            (IntSet.add (counted_update_temp update) acc)
                            reduction
                      | CountedReduction ({ target = ReductionPlaceTarget _; _ } as reduction) ->
                          add_reduction_alias_temps acc reduction)
                    IntSet.empty all_updates
                in
                let supported_live_temps =
                  IntSet.fold
                    (fun temp acc ->
                      if operand_available_before_loop loop_defs multi_defs def_instrs (Tcg.Temp temp) then
                        IntSet.add temp acc
                      else acc)
                    loop_live_defs supported_live_temps
                in
                let supported_live_temps =
                  IntSet.union supported_live_temps (IntSet.inter loop_live_defs loop_stable_phis)
                in
                let supported_live_temps, _, _ =
                  collect_reconstructible_live_temps
                    invariant_loaded_places
                    loop_defs
                    get_block
                    def_blocks
                    loop_stable_phis
                    multi_defs
                    def_instrs
                    supported_live_temps
                    loop_live_defs
                in
                let place_mirrors =
                  collect_counted_place_mirrors
                    header
                    loop
                    invariant_loaded_places
                    loop_defs
                    get_block
                    def_blocks
                    loop_stable_phis
                    multi_defs
                    def_instrs
                    ivs
                    (PlaceSet.inter (local_places effects.modified_places) live_p_exit)
                    supported_live_temps
                in
                let supported_live_places =
                  List.fold_left
                    (fun acc update ->
                      match counted_update_place update with
                      | Some place -> PlaceSet.add place acc
                      | None -> acc)
                    PlaceSet.empty all_updates
                  |> fun acc ->
                  List.fold_left (fun acc (place, _) -> PlaceSet.add place acc) acc place_mirrors
                in
                let loop_live_places =
                  PlaceSet.inter (local_places effects.modified_places) live_p_exit
                in
                if ambiguous_iv_carrier_reductions <> [] then begin
                  if Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None then
                    Printf.eprintf
                      "counted-extract-skip func=%s header=%s reason=ambiguous_iv_carrier_order\n%!"
                      f.name header
                end
                else if
                  IntSet.subset loop_live_defs supported_live_temps
                  && PlaceSet.subset loop_live_places supported_live_places
                then ()
                else
                  let extractable =
                    collect_direct_extractable_reductions
                    loop
                    get_block
                    info.control_iv.backedge_preds
                    reductions
                  in
                  let pressure_relief =
                    PlaceSet.cardinal loop_live_places
                    + IntSet.cardinal (IntSet.diff loop_live_defs supported_live_temps)
                    + List.length extractable
                  in
                  if extractable = [] then ()
                  else if total_instrs < split_reductions_min_instrs then ()
                  else if pressure_relief < split_reductions_min_pressure then ()
                  else if memory_ops = 0 && pressure_relief < 3 then ()
                  else
                    let outside_preds =
                      List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds
                    in
                    if outside_preds = [] && header <> !current_entry then ()
                    else
                      let removals = Hashtbl.create 8 in
                      List.iter
                        (fun (_, defs) ->
                          List.iter
                            (fun (label, index) ->
                              let current =
                                match Hashtbl.find_opt removals label with
                                | Some set -> set
                                | None -> IntSet.empty
                              in
                              Hashtbl.replace removals label (IntSet.add index current))
                            defs)
                        extractable;
                      let preheader_label =
                        match outside_preds with
                        | [ pred ] ->
                            let pred_block = get_block pred in
                            if pred_block.succs = [ header ] then pred else fresh_preheader_label ()
                        | [] -> fresh_preheader_label ()
                        | _ -> fresh_preheader_label ()
                      in
                      let created_preheader = not (Hashtbl.mem current_blocks preheader_label) in
                      if created_preheader then begin
                        let redirects = Hashtbl.create (List.length outside_preds) in
                        List.iter
                          (fun pred -> Hashtbl.add redirects (pred, header) preheader_label)
                          outside_preds;
                        List.iter
                          (fun pred ->
                            let pred_block = get_block pred in
                            let term = redirect_successors pred redirects pred_block.term in
                            update_block { pred_block with term; succs = Cfg.successors term })
                          outside_preds;
                        Hashtbl.add current_blocks preheader_label
                          {
                            Cfg.label = preheader_label;
                            body = [];
                            term = Cfg.Jump header;
                            preds = [];
                            succs = [ header ];
                          };
                        new_blocks_rev := preheader_label :: !new_blocks_rev;
                        if header = !current_entry then current_entry := preheader_label
                      end;
                      let trip_instrs, trip_temp =
                        build_trip_count_instrs
                          fresh_temp
                          info.control_iv.phi_temp
                          info.control_iv.step
                          info.kind
                      in
                      let extracted_reductions =
                        extractable |> List.map fst
                        |> materialize_place_reduction_carriers fresh_temp
                      in
                      let extracted_reductions, carrier_preloads = extracted_reductions in
                      let place_carriers = place_carriers_of_reductions extracted_reductions in
                      let preheader = get_block preheader_label in
                      update_block
                        {
                          preheader with
                          body = preheader.body @ trip_instrs @ carrier_preloads;
                        };
                      Hashtbl.iter
                        (fun label indexes ->
                          let block : Cfg.block = get_block label in
                          let body =
                            block.body
                            |> List.mapi (fun index instr -> (index, instr))
                            |> List.filter (fun (index, _) -> not (IntSet.mem index indexes))
                            |> List.map snd
                          in
                          update_block { block with body })
                        removals;
                      let summary_label = fresh_summary_label () in
                      let summary_body =
                        extracted_reductions
                        |> List.concat_map
                             (build_reduction_final_update fresh_temp trip_temp place_carriers)
                      in
                      let control_block = get_block info.control_label in
                      let term =
                        rewrite_term_successor control_block.term
                          ~from_label:info.exit_label ~to_label:summary_label
                      in
                      update_block { control_block with term; succs = Cfg.successors term };
                      Hashtbl.add current_blocks summary_label
                        {
                          Cfg.label = summary_label;
                          body = summary_body;
                          term = Cfg.Jump info.exit_label;
                          preds = [];
                          succs = [ info.exit_label ];
                        };
                      new_blocks_rev := summary_label :: !new_blocks_rev;
                      changed := true))
      headers;
    if !changed then
      let ordered_labels = List.map (fun (block : Cfg.block) -> block.label) f.blocks in
      let blocks = List.map get_block ordered_labels @ List.rev_map get_block !new_blocks_rev in
      Cfg.rebuild_edges { f with entry = !current_entry; temp_count = !next_temp; blocks }
    else f

let eliminate_counted_loops_func_once summaries globals (f : Cfg.func) =
  let debug_counted = Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None in
  let debugf fmt = Printf.ksprintf (fun s -> if debug_counted then prerr_endline s) fmt in
  let term_kind = function
    | Cfg.Jump _ -> "jump"
    | Cfg.BranchZero _ -> "branch_zero"
    | Cfg.BranchNonZero _ -> "branch_nonzero"
    | Cfg.BranchCompare _ -> "branch_compare"
    | Cfg.Return _ -> "return"
  in
  let instr_kind = function
    | Tcg.Move _ -> "move"
    | Tcg.Un _ -> "un"
    | Tcg.Bin _ -> "bin"
    | Tcg.Load _ -> "load"
    | Tcg.Store _ -> "store"
    | Tcg.Call _ -> "call"
  in
  let string_of_intset set =
    IntSet.elements set |> List.map string_of_int |> String.concat ","
  in
  let string_of_ivs ivs =
    ivs
    |> List.map (fun (iv : basic_induction_var) -> Printf.sprintf "%d:%Ld" iv.phi_temp iv.step)
    |> String.concat ";"
  in
  let string_of_place = function
    | Tcg.Local id -> Printf.sprintf "local:%d" id
    | Tcg.Global label -> Printf.sprintf "global:%s" label
  in
  let string_of_places set =
    PlaceSet.elements set |> List.map string_of_place |> String.concat ","
  in
  let string_of_place_mirrors mirrors =
    mirrors
    |> List.map (fun (place, temp) -> Printf.sprintf "%s->%d" (string_of_place place) temp)
    |> String.concat ","
  in
  let string_of_operand = function
    | Tcg.Imm value -> Int64.to_string value
    | Tcg.Temp temp -> Printf.sprintf "t%d" temp
  in
  let string_of_binop = function
    | Add -> "add"
    | Sub -> "sub"
    | Mul -> "mul"
    | Div -> "div"
    | Mod -> "mod"
    | Lt -> "lt"
    | Le -> "le"
    | Gt -> "gt"
    | Ge -> "ge"
    | Eq -> "eq"
    | Ne -> "ne"
    | LAnd -> "land"
    | LOr -> "lor"
  in
  let string_of_unop = function
    | UMinus -> "uminus"
    | UNot -> "unot"
    | UPlus -> "uplus"
  in
  let string_of_simple_instr = function
    | Tcg.Move (dst, src) ->
        Printf.sprintf "t%d=move(%s)" dst (string_of_operand src)
    | Tcg.Un (dst, op, src) ->
        Printf.sprintf "t%d=%s(%s)"
          dst (string_of_unop op) (string_of_operand src)
    | Tcg.Bin (dst, op, lhs, rhs) ->
        Printf.sprintf "t%d=%s(%s,%s)"
          dst
          (string_of_binop op)
          (string_of_operand lhs)
          (string_of_operand rhs)
    | Tcg.Load (dst, place) ->
        Printf.sprintf "t%d=load(%s)" dst (string_of_place place)
    | Tcg.Store (place, src) ->
        Printf.sprintf "store(%s,%s)"
          (string_of_place place) (string_of_operand src)
    | Tcg.Call (dst, name, args) ->
        Printf.sprintf "%s=call(%s;%s)"
          (match dst with
           | None -> "_"
           | Some temp -> Printf.sprintf "t%d" temp)
          name
          (String.concat "," (List.map string_of_operand args))
  in
  let string_of_term = function
    | Cfg.Jump label ->
        Printf.sprintf "jump(%s)" label
    | Cfg.BranchZero (operand, zero_label, nonzero_label) ->
        Printf.sprintf "branch_zero(%s,%s,%s)"
          (string_of_operand operand) zero_label nonzero_label
    | Cfg.BranchNonZero (operand, nonzero_label, zero_label) ->
        Printf.sprintf "branch_nonzero(%s,%s,%s)"
          (string_of_operand operand) nonzero_label zero_label
    | Cfg.BranchCompare (op, lhs, rhs, yes_label, no_label) ->
        Printf.sprintf "branch_cmp(%s,%s,%s,%s,%s)"
          (string_of_binop op)
          (string_of_operand lhs)
          (string_of_operand rhs)
          yes_label no_label
    | Cfg.Return value ->
        Printf.sprintf "return(%s)"
          (match value with
           | None -> ""
           | Some operand -> string_of_operand operand)
  in
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let current_blocks = Hashtbl.create (List.length f.blocks + List.length headers) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let get_block = get_block_exn current_blocks in
    let update_block (block : Cfg.block) =
      Hashtbl.replace current_blocks block.label block
    in
    let dump_nonlinear_shape header loop (info : counted_loop_info) =
      if debug_counted then begin
        debugf
          "counted-shape-dump func=%s header=%s control=%s inside=%s exit=%s iv=t%d step=%Ld loop=[%s]"
          f.name
          header
          info.control_label
          info.inside_label
          info.exit_label
          info.control_iv.phi_temp
          info.control_iv.step
          (String.concat "," (LabelSet.elements loop));
        LabelSet.elements loop
        |> List.iter (fun label ->
               let block : Cfg.block = get_block label in
               debugf
                 "counted-shape-block label=%s preds=[%s] succs=[%s] body=%d term=%s"
                 label
                 (String.concat "," block.preds)
                 (String.concat "," block.succs)
                 (List.length block.body)
                 (string_of_term block.term);
               List.iteri
                 (fun index instr ->
                   debugf
                     "counted-shape-instr block=%s index=%d %s"
                     label index (string_of_simple_instr instr))
                 block.body)
      end
    in
    let original_block_labels =
      List.map (fun (block : Cfg.block) -> block.label) f.blocks
    in
    let original_block_set =
      List.fold_left
        (fun acc label -> LabelSet.add label acc)
        LabelSet.empty
        original_block_labels
    in
    let current_block_list () =
      let original_blocks =
        List.filter_map
          (fun label -> Hashtbl.find_opt current_blocks label)
          original_block_labels
      in
      let extra_blocks =
        Hashtbl.fold
          (fun label block acc ->
            if LabelSet.mem label original_block_set then acc
            else block :: acc)
          current_blocks
          []
        |> List.sort
             (fun (a : Cfg.block) (b : Cfg.block) ->
               String.compare a.label b.label)
      in
      original_blocks @ extra_blocks
    in
    let next_temp = ref f.temp_count in
    let fresh_temp () =
      let temp = !next_temp in
      incr next_temp;
      temp
    in

    (* A counted summary may be executed on the original loop's zero-trip
       edge if:
         1. its trip count is masked by the original loop condition, and
         2. evaluating the summary with trip=0 cannot introduce a trap/call.

       Loads/stores are ordinary ToyC scalar memory accesses (no pointers or
       volatile I/O).  Arithmetic is safe except Div/Mod with a potentially
       zero divisor; calls are conservatively rejected. *)
    let zero_trip_safe_instr = function
      | Tcg.Call _ ->
          false
      | Tcg.Bin (_, Div, _, Tcg.Imm divisor)
      | Tcg.Bin (_, Mod, _, Tcg.Imm divisor) ->
          divisor <> 0L
      | Tcg.Bin (_, Div, _, Tcg.Temp _)
      | Tcg.Bin (_, Mod, _, Tcg.Temp _) ->
          false
      | Tcg.Move _
      | Tcg.Un _
      | Tcg.Bin _
      | Tcg.Load _
      | Tcg.Store _ ->
          true
    in

    let zero_trip_safe_body body =
      List.for_all zero_trip_safe_instr body
    in


    let summary_id = ref 0 in
    let fresh_summary_label () =
      let id = !summary_id in
      incr summary_id;
      Printf.sprintf ".L%s_counted_loop_%d" f.label id
    in
    let new_blocks_rev = ref [] in
    let changed = ref false in

    (* Special-case a strict monotone threshold diamond:

         while (i < bound) {
           if (i < K)
             x = x + i + A;
           else
             y = y + i + B;
           i = i + 1;
         }

       This is not an arbitrary nonlinear loop.  Since [i] increases
       monotonically by one and [K] is constant, the branch changes side at
       most once.  Let

         total = number of loop iterations
         prefix = min(total, max(K - i0, 0))

       Then the loop is exactly:

         x += sum_{k=0}^{prefix-1} (i0 + k + A)
         y += sum_{k=0}^{total-1}  (i0 + k + B)
              - sum_{k=0}^{prefix-1} (i0 + k + B)
         i += total

       The matcher below is intentionally narrow: five loop blocks, an empty
       branch block, two exact local-place reduction arms, one exact IV update
       join, positive unit IV step, and no calls/global writes. *)
    let try_eliminate_piecewise_threshold_loop
        header
        loop
        (info : counted_loop_info)
        effects
        loop_defs
        multi_defs
        def_instrs
      =
      let modified_globals = global_places effects.modified_places in
      let control_iv = info.control_iv in

      let add_is a b lhs rhs =
        (lhs = a && rhs = b) || (lhs = b && rhs = a)
      in

      let other_add_operand base lhs rhs =
        if lhs = base then Some rhs
        else if rhs = base then Some lhs
        else None
      in

      let match_arm label =
        let block : Cfg.block = get_block label in
        match (block.body, block.term) with
        (* Existing simple arm:
             acc = acc + iv + bias *)
        | ( [ Tcg.Load (loaded, (Tcg.Local _ as place));
              Tcg.Bin (mid, Add, lhs1, rhs1);
              Tcg.Bin (out_temp, Add, lhs2, rhs2);
              Tcg.Store (stored_place, Tcg.Temp stored_temp) ],
            Cfg.Jump join_label )
          when stored_place = place
               && stored_temp = out_temp
               && loaded <> control_iv.phi_temp
               && mid <> control_iv.phi_temp
               && out_temp <> control_iv.phi_temp
               && add_is
                    (Tcg.Temp loaded)
                    (Tcg.Temp control_iv.phi_temp)
                    lhs1 rhs1 -> (
            let bias =
              match (lhs2, rhs2) with
              | Tcg.Temp temp, Tcg.Imm bias when temp = mid -> Some bias
              | Tcg.Imm bias, Tcg.Temp temp when temp = mid -> Some bias
              | _ -> None
            in
            Option.map
              (fun bias ->
                (place, Tcg.Imm 0L, bias, join_label))
              bias)

        (* Same-accumulator nested piecewise arm:
             acc = acc + invariant + iv + bias

           The two additions before the bias may appear as either
             (acc + invariant) + iv
           or
             (acc + iv) + invariant.
           The invariant operand must be available before the inner loop. *)
        | ( [ Tcg.Load (loaded, (Tcg.Local _ as place));
              Tcg.Bin (mid1, Add, lhs1, rhs1);
              Tcg.Bin (mid2, Add, lhs2, rhs2);
              Tcg.Bin (out_temp, Add, lhs3, rhs3);
              Tcg.Store (stored_place, Tcg.Temp stored_temp) ],
            Cfg.Jump join_label )
          when stored_place = place
               && stored_temp = out_temp
               && loaded <> control_iv.phi_temp
               && mid1 <> control_iv.phi_temp
               && mid2 <> control_iv.phi_temp
               && out_temp <> control_iv.phi_temp -> (
            match
              ( other_add_operand (Tcg.Temp loaded) lhs1 rhs1,
                other_add_operand (Tcg.Temp mid1) lhs2 rhs2 )
            with
            | Some first_extra, Some second_extra ->
                let invariant =
                  if first_extra = Tcg.Temp control_iv.phi_temp then
                    Some second_extra
                  else if second_extra = Tcg.Temp control_iv.phi_temp then
                    Some first_extra
                  else
                    None
                in
                let bias =
                  match (lhs3, rhs3) with
                  | Tcg.Temp temp, Tcg.Imm bias when temp = mid2 ->
                      Some bias
                  | Tcg.Imm bias, Tcg.Temp temp when temp = mid2 ->
                      Some bias
                  | _ ->
                      None
                in
                (match (invariant, bias) with
                 | Some invariant, Some bias -> (
                     match
                       resolve_operand_before_loop
                         loop_defs multi_defs def_instrs invariant
                     with
                     | Some invariant
                       when invariant <> Tcg.Temp control_iv.phi_temp ->
                         Some
                           (place, invariant, bias, join_label)
                     | Some _
                     | None ->
                         None)
                 | Some _, None
                 | None, Some _
                 | None, None ->
                     None)
            | Some _, None
            | None, Some _
            | None, None ->
                None)
        | _ -> None
      in

      let exact_join_update join_label =
        let block : Cfg.block = get_block join_label in
        match (block.body, block.term) with
        | ( [ Tcg.Bin (next_temp, Add, Tcg.Temp src, Tcg.Imm 1L);
              Tcg.Move (dst, Tcg.Temp moved) ],
            Cfg.Jump next )
          when src = control_iv.phi_temp
               && dst = control_iv.phi_temp
               && moved = next_temp
               && next = header ->
            true
        | ( [ Tcg.Bin (next_temp, Add, Tcg.Imm 1L, Tcg.Temp src);
              Tcg.Move (dst, Tcg.Temp moved) ],
            Cfg.Jump next )
          when src = control_iv.phi_temp
               && dst = control_iv.phi_temp
               && moved = next_temp
               && next = header ->
            true
        | _ -> false
      in

      let control_kind_supported =
        match info.kind with
        | CountUpLt (_, 0L) -> true
        | CountUpLt _
        | CountUpLe _
        | CountDownGt _
        | CountDownGe _
        | CountUpLtScaled _
        | CountUpLeScaled _
        | CountDownGtScaled _
        | CountDownGeScaled _ ->
            false
      in

      let known_control_init () =
        match control_iv.outside_inputs with
        | [] -> None
        | inputs ->
            let values =
              List.map
                (fun (pred, operand) ->
                  let chain =
                    incoming_phi_chain get_block header pred
                    |> extend_counted_outside_seed_chain get_block loop
                  in
                  operand_static_int64_on_chain
                    chain
                    loop_defs
                    multi_defs
                    def_instrs
                    operand)
                inputs
            in
            if List.exists Option.is_none values then None
            else
              match
                values
                |> List.filter_map (fun value -> value)
                |> List.sort_uniq compare
              with
              | [ value ] -> Some value
              | _ -> None
      in

      let bounded_triangle_instrs trip_temp =
        let n_minus_one = fresh_temp () in
        let product = fresh_temp () in
        let triangle = fresh_temp () in
        ( [ simplify_simple_instr
              (Tcg.Bin
                 (n_minus_one, Sub, Tcg.Temp trip_temp, Tcg.Imm 1L));
            simplify_simple_instr
              (Tcg.Bin
                 (product, Mul, Tcg.Temp trip_temp, Tcg.Temp n_minus_one));
            simplify_simple_instr
              (Tcg.Bin
                 (triangle, Div, Tcg.Temp product, Tcg.Imm 2L)) ],
          triangle )
      in

      let affine_delta_from_triangle trip_temp triangle base =
        let base = i32 base in
        if base = 0L then ([], Tcg.Temp triangle)
        else if base = 1L then
          let delta = fresh_temp () in
          ( [ simplify_simple_instr
                (Tcg.Bin
                   (delta, Add, Tcg.Temp triangle, Tcg.Temp trip_temp)) ],
            Tcg.Temp delta )
        else if base = -1L then
          let delta = fresh_temp () in
          ( [ simplify_simple_instr
                (Tcg.Bin
                   (delta, Sub, Tcg.Temp triangle, Tcg.Temp trip_temp)) ],
            Tcg.Temp delta )
        else
          let scaled = fresh_temp () in
          let delta = fresh_temp () in
          ( [ simplify_simple_instr
                (Tcg.Bin
                   (scaled, Mul, Tcg.Temp trip_temp, Tcg.Imm base));
              simplify_simple_instr
                (Tcg.Bin
                   (delta, Add, Tcg.Temp scaled, Tcg.Temp triangle)) ],
            Tcg.Temp delta )
      in

      let adjust_delta_by_trip base_delta trip_temp amount =
        let amount = i32 amount in
        if amount = 0L then ([], base_delta)
        else if amount = 1L then
          let delta = fresh_temp () in
          ( [ simplify_simple_instr
                (Tcg.Bin
                   (delta, Add, base_delta, Tcg.Temp trip_temp)) ],
            Tcg.Temp delta )
        else if amount = -1L then
          let delta = fresh_temp () in
          ( [ simplify_simple_instr
                (Tcg.Bin
                   (delta, Sub, base_delta, Tcg.Temp trip_temp)) ],
            Tcg.Temp delta )
        else
          let scaled = fresh_temp () in
          let delta = fresh_temp () in
          ( [ simplify_simple_instr
                (Tcg.Bin
                   (scaled, Mul, Tcg.Temp trip_temp, Tcg.Imm amount));
              simplify_simple_instr
                (Tcg.Bin (delta, Add, base_delta, Tcg.Temp scaled)) ],
            Tcg.Temp delta )
      in

      let preload_two_places then_place else_place =
        let then_carrier = fresh_temp () in
        let else_carrier = fresh_temp () in
        ( [ simplify_simple_instr (Tcg.Load (then_carrier, then_place));
            simplify_simple_instr (Tcg.Load (else_carrier, else_place)) ],
          then_carrier,
          else_carrier )
      in

      if
        effects.has_call
        || not (PlaceSet.is_empty modified_globals)
        || control_iv.step <> 1L
        || not control_kind_supported
        || info.control_label <> header
        || LabelSet.cardinal loop <> 5
      then false
      else
        let control_block : Cfg.block = get_block info.control_label in
        let inside_block : Cfg.block = get_block info.inside_label in
        match (control_block.body, inside_block.body, inside_block.term) with
        | ( [],
            [],
            Cfg.BranchCompare
              (Lt, Tcg.Temp branch_iv, Tcg.Imm threshold, then_label, else_label) )
          when branch_iv = control_iv.phi_temp
               && then_label <> else_label
               && LabelSet.mem then_label loop
               && LabelSet.mem else_label loop -> (
            match (match_arm then_label, match_arm else_label) with
            | ( Some (then_place, then_invariant, then_bias, then_join),
                Some (else_place, else_invariant, else_bias, else_join) )
              when then_join = else_join
                   && LabelSet.mem then_join loop
                   && exact_join_update then_join
                   && List.mem then_join control_iv.backedge_preds ->
                (* Fast exact summary for the nested piecewise form

                     if (j < K)
                       s = s + A + j + Bt;
                     else
                       s = s + B + j + Be;

                   where both arms update the SAME scalar place, A/B are
                   invariant across the inner loop, j has step +1, and the
                   inner initial value and bound are statically known.

                   With:
                     N = total iterations
                     P = iterations taking the then arm
                     R = N - P

                   the whole loop contributes

                     sum(j)
                       + P * (A + Bt)
                       + R * (B + Be)

                   to s.  This is deliberately narrower than the generic
                   piecewise transform: no arbitrary branch effects and no
                   dynamic-bound algebra are admitted here. *)
                let same_place_static_summary () =
                  if then_place <> else_place then
                    None
                  else
                    match (known_control_init (), info.kind) with
                    | Some init_value, CountUpLt (bound_operand, 0L) -> (
                        match
                          operand_static_int64
                            loop_defs multi_defs def_instrs bound_operand
                        with
                        | Some bound_value when init_value < bound_value ->
                            let total_count =
                              Int64.sub bound_value init_value
                            in
                            let raw_prefix =
                              Int64.sub threshold init_value
                            in
                            let prefix_count =
                              if raw_prefix <= 0L then 0L
                              else if raw_prefix >= total_count then
                                total_count
                              else
                                raw_prefix
                            in
                            let else_count =
                              Int64.sub total_count prefix_count
                            in

                            (* All constant arithmetic is reduced to ToyC i32
                               semantics as it is combined.  Int64.mul itself
                               may wrap, but taking i32 afterwards preserves the
                               low 32 bits required by source arithmetic. *)
                            let mul_i32 a b =
                              i32 (Int64.mul a b)
                            in
                            let add_i32 a b =
                              i32 (Int64.add a b)
                            in
                            let triangle_count =
                              Int64.div
                                (Int64.mul
                                   total_count
                                   (Int64.sub total_count 1L))
                                2L
                            in
                            let j_sum =
                              add_i32
                                (mul_i32 total_count init_value)
                                (i32 triangle_count)
                            in
                            let branch_bias =
                              add_i32
                                (mul_i32 prefix_count then_bias)
                                (mul_i32 else_count else_bias)
                            in
                            let constant_delta =
                              add_i32 j_sum branch_bias
                            in

                            let scale_by_count count operand =
                              let count_i32 = i32 count in
                              if count_i32 = 0L then
                                ([], Tcg.Imm 0L)
                              else if count_i32 = 1L then
                                ([], operand)
                              else
                                let dst = fresh_temp () in
                                ( [ simplify_simple_instr
                                      (Tcg.Bin
                                         ( dst,
                                           Mul,
                                           operand,
                                           Tcg.Imm count_i32 )) ],
                                  Tcg.Temp dst )
                            in
                            let add_operands lhs rhs =
                              match (lhs, rhs) with
                              | Tcg.Imm 0L, operand
                              | operand, Tcg.Imm 0L ->
                                  ([], operand)
                              | Tcg.Imm lhs, Tcg.Imm rhs ->
                                  ([], Tcg.Imm (i32 (Int64.add lhs rhs)))
                              | _ ->
                                  let dst = fresh_temp () in
                                  ( [ simplify_simple_instr
                                        (Tcg.Bin
                                           (dst, Add, lhs, rhs)) ],
                                    Tcg.Temp dst )
                            in

                            let then_scale_instrs, then_scaled =
                              scale_by_count
                                prefix_count then_invariant
                            in
                            let else_scale_instrs, else_scaled =
                              scale_by_count
                                else_count else_invariant
                            in
                            let combine_branch_instrs, branch_scaled =
                              add_operands then_scaled else_scaled
                            in
                            let combine_const_instrs, delta =
                              add_operands
                                branch_scaled
                                (Tcg.Imm constant_delta)
                            in

                            let carrier = fresh_temp () in
                            let updated = fresh_temp () in
                            let updates =
                              then_scale_instrs
                              @ else_scale_instrs
                              @ combine_branch_instrs
                              @ combine_const_instrs
                              @ [ simplify_simple_instr
                                    (Tcg.Load (carrier, then_place));
                                  simplify_simple_instr
                                    (Tcg.Bin
                                       ( updated,
                                         Add,
                                         Tcg.Temp carrier,
                                         delta ));
                                  Tcg.Store
                                    (then_place, Tcg.Temp updated);
                                  (* For strict step-one [j < bound], the
                                     value observed after loop exit is exactly
                                     [bound]. *)
                                  simplify_simple_instr
                                    (Tcg.Move
                                       ( control_iv.phi_temp,
                                         Tcg.Imm (i32 bound_value) )) ]
                            in
                            Some updates
                        | Some _
                        | None ->
                            None)
                    | Some _, CountUpLt (_, _)
                    | Some _, CountUpLe _
                    | Some _, CountDownGt _
                    | Some _, CountDownGe _
                    | Some _, CountUpLtScaled _
                    | Some _, CountUpLeScaled _
                    | Some _, CountDownGtScaled _
                    | Some _, CountDownGeScaled _
                    | None, CountUpLt _
                    | None, CountUpLe _
                    | None, CountDownGt _
                    | None, CountDownGe _
                    | None, CountUpLtScaled _
                    | None, CountUpLeScaled _
                    | None, CountDownGtScaled _
                    | None, CountDownGeScaled _ ->
                        None
                in

                let generic_summary () =
                  let total_trip_instrs, total_trip =
                    build_trip_count_instrs
                      fresh_temp
                      control_iv.phi_temp
                      control_iv.step
                      info.kind
                  in

                  (* prefix_raw = max(K - i0, 0) *)
                  let prefix_diff = fresh_temp () in
                  let prefix_clamp_instrs, prefix_nonnegative =
                    clamp_nonnegative_temp fresh_temp prefix_diff
                  in

                  let min_delta = fresh_temp () in
                  let choose_prefix = fresh_temp () in
                  let selected_delta = fresh_temp () in
                  let prefix_trip = fresh_temp () in
                  let prefix_instrs =
                    [ simplify_simple_instr
                        (Tcg.Bin
                           ( prefix_diff,
                             Sub,
                             Tcg.Imm threshold,
                             Tcg.Temp control_iv.phi_temp )) ]
                    @ prefix_clamp_instrs
                    @ [ simplify_simple_instr
                          (Tcg.Bin
                             ( min_delta,
                               Sub,
                               Tcg.Temp prefix_nonnegative,
                               Tcg.Temp total_trip ));
                        simplify_simple_instr
                          (Tcg.Bin
                             ( choose_prefix,
                               Lt,
                               Tcg.Temp prefix_nonnegative,
                               Tcg.Temp total_trip ));
                        simplify_simple_instr
                          (Tcg.Bin
                             ( selected_delta,
                               Mul,
                               Tcg.Temp min_delta,
                               Tcg.Temp choose_prefix ));
                        simplify_simple_instr
                          (Tcg.Bin
                             ( prefix_trip,
                               Add,
                               Tcg.Temp total_trip,
                               Tcg.Temp selected_delta )) ]
                  in

                  let affine place bias subtract =
                    {
                      target = ReductionPlaceTarget place;
                      subtract;
                      step =
                        ReductionAffine
                          {
                            iv = control_iv;
                            coeff = one_summary_expr;
                            bias = SummaryOperand (Tcg.Imm bias);
                          };
                      carrier_temp = None;
                      alias_temps = [];
                    }
                  in
                  let then_reduction = affine then_place then_bias false in
                  let else_all_reduction = affine else_place else_bias false in
                  let else_prefix_reduction = affine else_place else_bias true in
                  let reductions, carrier_preloads =
                    materialize_place_reduction_carriers
                      fresh_temp
                      [ then_reduction;
                        else_all_reduction;
                        else_prefix_reduction ]
                  in
                  let place_carriers =
                    place_carriers_of_reductions reductions
                  in
                  let then_reduction, else_all_reduction, else_prefix_reduction =
                    match reductions with
                    | [ a; b; c ] -> (a, b, c)
                    | _ -> assert false
                  in
                  let updates =
                    carrier_preloads
                    @ build_reduction_final_update
                        fresh_temp
                        prefix_trip
                        place_carriers
                        then_reduction
                    @ build_reduction_final_update
                        fresh_temp
                        total_trip
                        place_carriers
                        else_all_reduction
                    @ build_reduction_final_update
                        fresh_temp
                        prefix_trip
                        place_carriers
                        else_prefix_reduction
                    @ build_iv_final_update
                        fresh_temp
                        total_trip
                        control_iv
                  in
                  (total_trip_instrs, prefix_instrs, updates, false)
                in

                let fast_summary init_value prefix_cap bound =
                  (* The summary block is reached only from the true edge of
                     [i < bound].  With a known nonnegative [i0], [bound-i0] is
                     strictly positive and cannot overflow signed i32, so the
                     generic nonnegative clamp is redundant here. *)
                  let total_trip = fresh_temp () in
                  let total_trip_instrs =
                    [ simplify_simple_instr
                        (Tcg.Bin
                           ( total_trip,
                             Sub,
                             bound,
                             Tcg.Temp control_iv.phi_temp )) ]
                  in

                  (* prefix = min(prefix_cap, total_trip). *)
                  let min_delta = fresh_temp () in
                  let choose_cap = fresh_temp () in
                  let selected_delta = fresh_temp () in
                  let prefix_trip = fresh_temp () in
                  let prefix_instrs =
                    [ simplify_simple_instr
                        (Tcg.Bin
                           ( min_delta,
                             Sub,
                             Tcg.Imm prefix_cap,
                             Tcg.Temp total_trip ));
                      simplify_simple_instr
                        (Tcg.Bin
                           ( choose_cap,
                             Lt,
                             Tcg.Imm prefix_cap,
                             Tcg.Temp total_trip ));
                      simplify_simple_instr
                        (Tcg.Bin
                           ( selected_delta,
                             Mul,
                             Tcg.Temp min_delta,
                             Tcg.Temp choose_cap ));
                      simplify_simple_instr
                        (Tcg.Bin
                           ( prefix_trip,
                             Add,
                             Tcg.Temp total_trip,
                             Tcg.Temp selected_delta )) ]
                  in

                  (* [prefix_trip <= prefix_cap <= 46340], hence
                     prefix*(prefix-1) cannot overflow signed i32 before /2. *)
                  let prefix_triangle_instrs, prefix_triangle =
                    bounded_triangle_instrs prefix_trip
                  in
                  let total_triangle_instrs, total_triangle =
                    build_triangle_number_instrs fresh_temp total_trip
                  in

                  let then_base = i32 Int64.(add init_value then_bias) in
                  let else_base = i32 Int64.(add init_value else_bias) in
                  let then_delta_instrs, then_delta =
                    affine_delta_from_triangle
                      prefix_trip prefix_triangle then_base
                  in
                  let else_all_instrs, else_all_delta =
                    affine_delta_from_triangle
                      total_trip total_triangle else_base
                  in

                  (* Both prefix sums share the same IV series:
                       else_prefix
                         = then_prefix
                           + prefix * (else_bias - then_bias). *)
                  let else_prefix_instrs, else_prefix_delta =
                    adjust_delta_by_trip
                      then_delta
                      prefix_trip
                      Int64.(sub else_bias then_bias)
                  in

                  let carrier_preloads, then_carrier, else_carrier =
                    preload_two_places then_place else_place
                  in
                  let then_update =
                    simplify_simple_instr
                      (Tcg.Bin
                         ( then_carrier,
                           Add,
                           Tcg.Temp then_carrier,
                           then_delta ))
                  in
                  let else_add_all =
                    simplify_simple_instr
                      (Tcg.Bin
                         ( else_carrier,
                           Add,
                           Tcg.Temp else_carrier,
                           else_all_delta ))
                  in
                  let else_remove_prefix =
                    simplify_simple_instr
                      (Tcg.Bin
                         ( else_carrier,
                           Sub,
                           Tcg.Temp else_carrier,
                           else_prefix_delta ))
                  in
                  let updates =
                    carrier_preloads
                    @ prefix_triangle_instrs
                    @ then_delta_instrs
                    @ total_triangle_instrs
                    @ else_all_instrs
                    @ else_prefix_instrs
                    @ [ then_update;
                        Tcg.Store (then_place, Tcg.Temp then_carrier);
                        else_add_all;
                        else_remove_prefix;
                        Tcg.Store (else_place, Tcg.Temp else_carrier) ]
                    @ build_iv_final_update
                        fresh_temp
                        total_trip
                        control_iv
                  in
                  (total_trip_instrs, prefix_instrs, updates, true)
                in

                let selected_summary =
                  match same_place_static_summary () with
                  | Some updates ->
                      Some ([], [], updates, true, "same-place-static")
                  | None
                    when then_invariant = Tcg.Imm 0L
                         && else_invariant = Tcg.Imm 0L ->
                      let total_trip_instrs, prefix_instrs, updates, fast_piecewise =
                        match (known_control_init (), info.kind) with
                        | Some init_value, CountUpLt (bound, 0L)
                          when then_place <> else_place
                               && init_value >= 0L
                               && threshold >= init_value ->
                            let prefix_cap =
                              Int64.sub threshold init_value
                            in
                            if prefix_cap <= 46_340L then
                              fast_summary init_value prefix_cap bound
                            else
                              generic_summary ()
                        | _ ->
                            generic_summary ()
                      in
                      Some
                        ( total_trip_instrs,
                          prefix_instrs,
                          updates,
                          fast_piecewise,
                          "legacy" )
                  | None ->
                      None
                in

                (match selected_summary with
                 | None ->
                     false
                 | Some
                     ( total_trip_instrs,
                       prefix_instrs,
                       updates,
                       fast_piecewise,
                       piecewise_mode ) ->
                let summary_label = fresh_summary_label () in
                let rewritten_term =
                  rewrite_term_successor
                    control_block.term
                    ~from_label:info.inside_label
                    ~to_label:summary_label
                in
                update_block
                  {
                    control_block with
                    term = rewritten_term;
                    succs = Cfg.successors rewritten_term;
                  };
                Hashtbl.add
                  current_blocks
                  summary_label
                  {
                    Cfg.label = summary_label;
                    body =
                      total_trip_instrs
                      @ prefix_instrs
                      @ updates;
                    term = Cfg.Jump info.exit_label;
                    preds = [];
                    succs = [ info.exit_label ];
                  };
                debugf
                  "counted-piecewise-apply func=%s header=%s summary=%s threshold=%Ld then=%s:%Ld else=%s:%Ld fast=%b mode=%s then_inv=%s else_inv=%s"
                  f.name
                  header
                  summary_label
                  threshold
                  (string_of_place then_place)
                  then_bias
                  (string_of_place else_place)
                  else_bias
                  fast_piecewise
                  piecewise_mode
                  (string_of_operand then_invariant)
                  (string_of_operand else_invariant);
                new_blocks_rev := summary_label :: !new_blocks_rev;
                changed := true;
                true)
            | _ -> false)
        | _ -> false
    in

    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        let header_block : Cfg.block = get_block header in
        let blocks_snapshot = current_block_list () in
        let
          ( loop_defs,
            def_blocks,
            def_instrs,
            multi_defs,
            loop_stable_phis,
            ivs,
            control,
            recurrence_facts ) =
          analyze_counted_loop_for_elimination
            header loop get_block !next_temp blocks_snapshot
        in
        let effects = collect_loop_effects summaries globals loop blocks_snapshot in
        let invariant_loaded_places =
          PlaceSet.diff
            (local_places (locals_in_func { f with blocks = blocks_snapshot }))
            (local_places effects.modified_places)
        in
        match control with
        | None ->
            debugf "counted-skip func=%s header=%s reason=classify term=%s ivs=%d preds=%d"
              f.name header (term_kind header_block.term) (List.length ivs)
              (List.length header_block.preds)
        | Some info -> (
            match counted_loop_shape_supported info.control_label loop get_block info.inside_label with
            | false ->
                if
                  not
                    (try_eliminate_piecewise_threshold_loop
                       header
                       loop
                       info
                       effects
                       loop_defs
                       multi_defs
                       def_instrs)
                then begin
                  debugf
                    "counted-skip func=%s header=%s reason=nonlinear_path"
                    f.name header;
                  dump_nonlinear_shape header loop info
                end
            | true ->
                let live_in_t, live_in_p =
                  compute_liveness summaries globals { f with blocks = blocks_snapshot }
                in
                let live_p_exit = table_find_or_empty live_in_p info.exit_label PlaceSet.empty in
                let modified_globals = global_places effects.modified_places in
                let loop_live_places =
                  PlaceSet.inter (local_places effects.modified_places) live_p_exit
                in
                let live_t_exit = table_find_or_empty live_in_t info.exit_label IntSet.empty in
                let live_ivs =
                  let syntactic_live =
                    List.filter
                      (fun (iv : basic_induction_var) ->
                        iv.phi_temp = info.control_iv.phi_temp
                        || IntSet.mem iv.phi_temp live_t_exit)
                      ivs
                  in
                  if
                    List.exists
                      (fun (iv : basic_induction_var) ->
                        iv.phi_temp = info.control_iv.phi_temp)
                      syntactic_live
                  then
                    syntactic_live
                  else
                    info.control_iv :: syntactic_live
                in
                let loop_live_defs =
                  IntSet.inter loop_defs live_t_exit
                in
                let excluded_temps =
                  List.fold_left
                    (fun acc (iv : basic_induction_var) -> IntSet.add iv.phi_temp acc)
                    IntSet.empty live_ivs
                in
                let reductions =
                  collect_counted_reductions
                    ~recurrence_facts
                    header
                    loop
                    invariant_loaded_places
                    loop_defs
                    get_block
                    def_blocks
                    loop_stable_phis
                    multi_defs
                    def_instrs
                    ivs
                    excluded_temps
                    loop_live_defs
                    loop_live_places
                in
                let reductions, ambiguous_iv_carrier_reductions =
                  resolve_counted_carrier_orders
                    header loop get_block multi_defs def_instrs ivs reductions
                in
                let all_updates =
                  (List.map (fun iv -> CountedIv iv) live_ivs)
                  @ List.map (fun reduction -> CountedReduction reduction) reductions
                in
                let supported_live_temps =
                  List.fold_left
                    (fun acc update ->
                      match update with
                      | CountedIv _ ->
                          IntSet.add (counted_update_temp update) acc
                      | CountedReduction ({ target = ReductionTempTarget _; _ } as reduction) ->
                          add_reduction_alias_temps
                            (IntSet.add (counted_update_temp update) acc)
                            reduction
                      | CountedReduction ({ target = ReductionPlaceTarget _; _ } as reduction) ->
                          add_reduction_alias_temps acc reduction)
                    IntSet.empty all_updates
                in
                let supported_live_temps =
                  IntSet.fold
                    (fun temp acc ->
                      if operand_available_before_loop loop_defs multi_defs def_instrs (Tcg.Temp temp) then
                        IntSet.add temp acc
                      else acc)
                    loop_live_defs supported_live_temps
                in
                let supported_live_temps =
                  IntSet.union supported_live_temps (IntSet.inter loop_live_defs loop_stable_phis)
                in
                let supported_live_temps, reconstruction_order, reconstruction_exprs =
                  collect_reconstructible_live_temps
                    invariant_loaded_places
                    loop_defs
                    get_block
                    def_blocks
                    loop_stable_phis
                    multi_defs
                    def_instrs
                    supported_live_temps
                    loop_live_defs
                in
                let place_mirrors =
                  collect_counted_place_mirrors
                    header
                    loop
                    invariant_loaded_places
                    loop_defs
                    get_block
                    def_blocks
                    loop_stable_phis
                    multi_defs
                    def_instrs
                    ivs
                    loop_live_places
                    supported_live_temps
                in
                if debug_counted then begin
                  let backedge_preds =
                    List.filter (fun pred -> LabelSet.mem pred loop) header_block.preds
                  in
                  let last_store_value_of_place_on_chain place chain =
                    let block = flatten_chain_block chain in
                    match last_store_of_place place block with
                    | Some (_, value) -> Some (resolve_chain_operand chain value)
                    | None -> None
                  in
                  PlaceSet.iter
                    (fun place ->
                      let stores =
                        backedge_preds
                        |> List.map (fun pred ->
                               let chain = incoming_update_chain get_block header pred in
                               let value =
                                 match last_store_value_of_place_on_chain place chain with
                                 | Some operand -> (
                                     match operand with
                                     | Tcg.Imm _ -> string_of_operand operand
                                     | Tcg.Temp temp ->
                                         let def_label =
                                           Option.value ~default:"<none>"
                                             (Hashtbl.find_opt def_blocks temp)
                                         in
                                         let def_kind =
                                           match Hashtbl.find_opt def_instrs temp with
                                           | Some instr -> instr_kind instr
                                           | None -> "none"
                                         in
                                         Printf.sprintf "%s@%s/%s" (string_of_operand operand)
                                           def_label def_kind)
                                 | None -> "<none>"
                               in
                               Printf.sprintf "%s:%s" pred value)
                        |> String.concat ";"
                      in
                      debugf "counted-place-detail func=%s header=%s place=%s stores=[%s]"
                        f.name header (string_of_place place) stores)
                    loop_live_places
                end;
                let supported_live_places =
                  List.fold_left
                    (fun acc update ->
                      match counted_update_place update with
                      | Some place -> PlaceSet.add place acc
                      | None -> acc)
                    PlaceSet.empty all_updates
                  |> fun acc ->
                  List.fold_left (fun acc (place, _) -> PlaceSet.add place acc) acc place_mirrors
                in
                debugf
                  "counted-candidate func=%s header=%s exit=%s ivs=[%s] live_defs={%s} live_places={%s} reductions=%d supported={%s} mirrors={%s}"
                  f.name header info.exit_label (string_of_ivs ivs)
                  (string_of_intset loop_live_defs)
                  (string_of_places loop_live_places)
                  (List.length reductions)
                  (string_of_intset supported_live_temps)
                  (string_of_place_mirrors place_mirrors);
                if ambiguous_iv_carrier_reductions <> [] then begin
                  if debug_counted then
                    List.iter
                      (fun (reduction : counted_reduction) ->
                        match reduction.step with
                        | ReductionCarrierProgression
                            { carrier_temp; include_updated; _ } ->
                            debugf
                              "counted-ambiguous-iv-carrier func=%s header=%s carrier=%d include_updated=%b depends_on_iv=true"
                              f.name header carrier_temp include_updated
                        | ReductionInvariant _
                        | ReductionAffine _
                        | ReductionQuadratic _
                        | ReductionCubic _ ->
                            ())
                      ambiguous_iv_carrier_reductions;
                  debugf
                    "counted-skip func=%s header=%s reason=ambiguous_iv_carrier_order"
                    f.name header
                end
                else if effects.has_call || not (PlaceSet.is_empty modified_globals) then
                  debugf "counted-skip func=%s header=%s reason=effects" f.name header
                else if not (IntSet.subset loop_live_defs supported_live_temps) then
                  let missing = IntSet.diff loop_live_defs supported_live_temps in
                  debugf "counted-skip func=%s header=%s reason=unsupported_live missing={%s}"
                    f.name header
                    (string_of_intset missing);
                  IntSet.iter
                    (fun temp ->
                      let def_label =
                        match Hashtbl.find_opt def_blocks temp with
                        | Some label -> label
                        | None -> "<none>"
                      in
                      let def_kind =
                        match Hashtbl.find_opt def_instrs temp with
                        | Some instr -> instr_kind instr
                        | None -> "none"
                      in
                      debugf
                        "counted-missing-temp func=%s header=%s temp=%d def_block=%s def_kind=%s"
                        f.name header temp def_label def_kind)
                    missing
                else if not (PlaceSet.subset loop_live_places supported_live_places) then
                  debugf
                    "counted-skip func=%s header=%s reason=unsupported_live_places missing={%s} supported_places={%s}"
                    f.name header
                    (string_of_places (PlaceSet.diff loop_live_places supported_live_places))
                    (string_of_places supported_live_places)
                else
                  let reductions, carrier_preloads =
                    materialize_place_reduction_carriers fresh_temp reductions
                  in
                  let place_carriers = place_carriers_of_reductions reductions in
                  let trip_instrs, trip_temp =
                    build_trip_count_instrs
                      fresh_temp
                      info.control_iv.phi_temp
                      info.control_iv.step
                      info.kind
                  in
                  let build_updates effective_trip =
                    carrier_preloads
                    @ List.concat_map
                        (build_reduction_final_update fresh_temp effective_trip place_carriers)
                        reductions
                    @ List.concat_map
                        (build_iv_final_update fresh_temp effective_trip)
                        live_ivs
                    @ build_live_temp_reconstruction_updates
                        fresh_temp
                        place_carriers
                        reconstruction_order
                        reconstruction_exprs
                    @ List.map
                        (fun (place, temp) -> Tcg.Store (place, Tcg.Temp temp))
                        place_mirrors
                  in
                  (* First build a probe body.  If every generated instruction is
                     safe to evaluate when the original loop executes zero
                     iterations, we can remove the residual loop guard by
                     masking [trip] with the original condition. *)
                  let probe_updates = build_updates trip_temp in
                  let probe_body = trip_instrs @ probe_updates in
                  let summary_label = fresh_summary_label () in
                  let control_block = get_block info.control_label in
                  (* Parameterized loops normally keep the original zero-trip
                     guard because computing a closed-form trip count on the
                     false edge can itself overflow (for example [bound-init]
                     with unrelated signed parameters).

                     There is one important safe case for nested summaries:
                       i = 0;
                       while (i < bound) { ...; i = i + 1; }

                     Here [CountUpLt(bound, 0)] with unit step and a proven
                     outside value of exactly zero computes
                       trip = max(bound, 0)
                     without a signed subtraction overflow.  If the generated
                     summary body is also zero-trip-safe, executing it on the
                     original false edge is neutral.  This removes the residual

                       guard -> counted_summary / bypass -> join

                     diamond produced by an eliminated inner loop, exposing a
                     straight-line scalar transfer to the enclosing loop.

                     Keep this deliberately narrow: no biased/scaled control,
                     no nonzero initial value, and no reconstruction/mirrors. *)
                  let zero_trip_control_init_is_zero =
                    match info.kind with
                    | CountUpLt (_, 0L)
                      when info.control_iv.step = 1L -> (
                        match info.control_iv.outside_inputs with
                        | [] ->
                            false
                        | inputs ->
                            List.for_all
                              (fun (pred, operand) ->
                                let chain =
                                  incoming_phi_chain get_block header pred
                                  |> extend_counted_outside_seed_chain
                                       get_block loop
                                in
                                match
                                  operand_static_int64_on_chain
                                    chain
                                    loop_defs
                                    multi_defs
                                    def_instrs
                                    operand
                                with
                                | Some 0L -> true
                                | Some _ | None -> false)
                              inputs)
                    | CountUpLt _
                    | CountUpLe _
                    | CountDownGt _
                    | CountDownGe _
                    | CountUpLtScaled _
                    | CountUpLeScaled _
                    | CountDownGtScaled _
                    | CountDownGeScaled _ ->
                        false
                  in
                  let zero_trip_state_simple =
                    reconstruction_order = []
                    && place_mirrors = []
                    && (f.params = [] || zero_trip_control_init_is_zero)
                  in
                  let zero_trip_elided =
                    zero_trip_state_simple
                    && zero_trip_safe_body probe_body
                  in
                  if
                    debug_counted
                    && zero_trip_elided
                    && f.params <> []
                    && zero_trip_control_init_is_zero
                  then
                    debugf
                      "counted-zero-trip-param-zero-init-elide func=%s header=%s summary=%s"
                      f.name header summary_label;
                  if
                    Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None
                    && zero_trip_safe_body probe_body
                    && not zero_trip_state_simple
                  then
                    Printf.eprintf
                      "counted-zero-trip-keep-guard func=%s header=%s params=%d reconstruction=%d mirrors=%d\n%!"
                      f.name header
                      (List.length f.params)
                      (List.length reconstruction_order)
                      (List.length place_mirrors);
                  let body, term =
                    if zero_trip_elided then
                      (* [build_trip_count_instrs] is defined from the exact
                         monotone counted-loop relation and clamps the computed
                         trip count to zero when the initial condition is false.
                         Therefore a safe summary already has neutral semantics
                         on the original zero-trip edge; no extra condition mask
                         is required. *)
                      (probe_body, Cfg.Jump summary_label)
                    else
                      let term =
                        rewrite_term_successor control_block.term
                          ~from_label:info.inside_label ~to_label:summary_label
                      in
                      (probe_body, term)
                  in
                  update_block { control_block with term; succs = Cfg.successors term };
                  Hashtbl.add current_blocks summary_label
                    {
                      Cfg.label = summary_label;
                      body;
                      term = Cfg.Jump info.exit_label;
                      preds = [];
                      succs = [ info.exit_label ];
                    };
                  if zero_trip_elided then
                    debugf
                      "counted-zero-trip-elide func=%s header=%s summary=%s masked=false"
                      f.name header summary_label;
                  debugf "counted-apply func=%s header=%s summary=%s updates=%d" f.name header
                    summary_label (List.length all_updates);
                  new_blocks_rev := summary_label :: !new_blocks_rev;
                  changed := true))
      headers;
    if !changed then
      let ordered_labels = List.map (fun (block : Cfg.block) -> block.label) f.blocks in
      let blocks = List.map get_block ordered_labels @ List.rev_map get_block !new_blocks_rev in
      Cfg.rebuild_edges { f with temp_count = !next_temp; blocks }
    else f


let eliminate_counted_loops_func global_init summaries globals (f : Cfg.func) =
  (* Nested counted-loop cascading.

     After an inner loop is summarized, enclosing source variables can still be
     represented as local load/store recurrences.  [analyze_induction_vars]
     intentionally works on temp/phi recurrences, so merely rediscovering the
     outer natural loop is not enough.

     Use optimistic mem2reg only as a bridge between successful counted-loop
     eliminations:

       inner counted summary
         -> CFG cleanup
         -> optimistic mem2reg / loop canonicalization
         -> try the next enclosing counted loop

     If the promoted view does NOT enable another counted-loop elimination, keep
     the cleaned pre-promotion CFG.  This avoids feeding promotion-only CFG
     changes into the rest of the normal rotate/split/unroll pipeline. *)
  let debug_enabled () =
    Sys.getenv_opt "TOYC_DEBUG_COUNTED_LOOPS" <> None
  in

  let cleanup current =
    current
    |> thread_and_prune_func
    |> simplify_cfg_func
  in

  let prepare_promoted_base current =
    current
    |> mem2reg_func ~optimistic_loop_phi:true
    |> loop_canonicalize_func summaries globals
    |> const_propagate_func global_init summaries globals
    |> thread_and_prune_func
    |> simplify_cfg_func
  in

  (* Bottom-up nested scalar-transfer bridge.

     A successful inner counted-loop summary is emitted as ordinary scalar
     arithmetic.  Optimistic mem2reg exposes the enclosing loop-carried locals,
     but that alone is not enough: the freshly emitted transfer may still be a
     temp tree such as

       t1 = trip * outer_iv
       t2 = trip * bias
       t3 = t1 + t2
       outer_acc = outer_acc + t3

     while the outer recurrence consumers are strongest on canonical
     Add/Sub/constant-Mul forms.

     Recanonicalize only the promoted *analysis bridge*.  If it does not enable
     another counted-loop elimination, [cascade] still returns the cleaned
     pre-promotion CFG, so these bridge-only rewrites do not perturb the normal
     optimizer pipeline on their own. *)
  let recanonicalize_promoted_view current =
    current
    |> gvn_func summaries globals
    |> copy_coalesce_func summaries globals
    |> const_propagate_func global_init summaries globals
    |> thread_and_prune_func
    |> simplify_cfg_func
    |> loop_canonicalize_func summaries globals
    |> thread_and_prune_func
    |> simplify_cfg_func
  in

  let rec cascade fuel current =
    if fuel <= 0 then current
    else
      let first =
        eliminate_counted_loops_func_once summaries globals current
      in
      if first = current then current
      else
        let cleaned = cleanup first in
        if debug_enabled () then
          Printf.eprintf
            "counted-cascade func=%s phase=clean remaining=%d blocks=%d->%d\n%!"
            f.name
            (fuel - 1)
            (List.length current.blocks)
            (List.length cleaned.blocks);

        if fuel <= 1 then cleaned
        else
          let promoted_base =
            prepare_promoted_base cleaned
          in
          let promoted =
            recanonicalize_promoted_view promoted_base
          in
          let second =
            eliminate_counted_loops_func_once summaries globals promoted
          in
          if debug_enabled () && second <> promoted then begin
            let without_recanon =
              eliminate_counted_loops_func_once
                summaries globals promoted_base
            in
            if without_recanon = promoted_base then
              Printf.eprintf
                "counted-nested-transfer-recanon-hit func=%s remaining=%d blocks=%d->%d\n%!"
                f.name
                (fuel - 2)
                (List.length promoted_base.blocks)
                (List.length promoted.blocks)
          end;
          if second = promoted then begin
            if debug_enabled () then
              Printf.eprintf
                "counted-cascade func=%s phase=promotion-const-no-followup remaining=%d locals-view-blocks=%d\n%!"
                f.name
                (fuel - 1)
                (List.length promoted.blocks);
            (* Promotion was useful only as an analysis bridge candidate, but it
               did not expose another eliminable counted loop.  Preserve the
               cleaned CFG from the successful first elimination. *)
            cleaned
          end else begin
            let second_cleaned = cleanup second in
            if debug_enabled () then
              Printf.eprintf
                "counted-cascade func=%s phase=promotion-const-followup remaining=%d blocks=%d->%d\n%!"
                f.name
                (fuel - 2)
                (List.length promoted.blocks)
                (List.length second_cleaned.blocks);
            cascade (fuel - 2) second_cleaned
          end
  in
  cascade 4 f

let full_unroll_counted_loops_func summaries globals (f : Cfg.func) =
  let full_unroll_max_trip = 8L in
  let full_unroll_max_blocks = 4 in
  let full_unroll_max_instrs = 28 in
  let full_unroll_max_control_body_instrs = 4 in
  let control_body_supported body =
    List.length body <= full_unroll_max_control_body_instrs
    && List.for_all pure_cfg_prep_instr body
  in
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let current_blocks = Hashtbl.create (List.length f.blocks + (8 * List.length headers)) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let block_order = ref (List.map (fun (block : Cfg.block) -> block.label) f.blocks) in
    let get_block = get_block_exn current_blocks in
    let current_block_list () = List.map get_block !block_order in
    let insert_after label new_labels =
      block_order :=
        List.concat_map
          (fun current -> if current = label then current :: new_labels else [ current ])
          !block_order
    in
    let next_id = ref 0 in
    let fresh_unroll_label iter index =
      let id = !next_id in
      Printf.sprintf ".L%s_full_unroll_%d_%d_%d" f.label id iter index
    in
    let changed = ref false in
    let current_entry = ref f.entry in
    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        let blocks_snapshot = current_block_list () in
        let (loop_defs, _, def_instrs, multi_defs, _, _, control) =
          analyze_counted_loop header loop get_block f.temp_count blocks_snapshot
        in
        let effects = collect_loop_effects summaries globals loop blocks_snapshot in
        match control with
        | None -> ()
        | Some info -> (
            let control_block : Cfg.block = get_block info.control_label in
            match linear_loop_path info.control_label loop get_block info.inside_label with
            | None -> ()
            | Some path ->
                let outside_preds =
                  let header_block : Cfg.block = get_block header in
                  List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds
                in
                let total_instrs =
                  List.length control_block.body
                  + List.fold_left
                      (fun acc (block : Cfg.block) -> acc + List.length block.body)
                      0 path
                in
                let modified_globals = global_places effects.modified_places in
                let resolve_const operand =
                  match resolve_operand_before_loop loop_defs multi_defs def_instrs operand with
                  | Some (Tcg.Imm value) -> Some value
                  | Some (Tcg.Temp _) | None -> None
                in
                let init_values =
                  info.control_iv.outside_inputs
                  |> List.filter_map (fun (_, operand) -> resolve_const operand)
                  |> List.sort_uniq compare
                in
                let trip_count =
                  match init_values with
                  | [ init_value ] ->
                      constant_trip_count_of_kind resolve_const init_value info.control_iv.step info.kind
                  | _ -> None
                in
                if
                  effects.has_call
                  || not (PlaceSet.is_empty modified_globals)
                  || not (control_body_supported control_block.body)
                  || path = []
                  || List.length path > full_unroll_max_blocks
                  || total_instrs > full_unroll_max_instrs
                  || (outside_preds = [] && header <> !current_entry)
                then ()
                else
                  match trip_count with
                  | Some trip when 0L <= trip && trip <= full_unroll_max_trip ->
                      let target_label =
                        if trip = 0L then info.exit_label
                        else
                          let trip_int = Int64.to_int trip in
                          let copies =
                            Array.init trip_int (fun iter ->
                                Array.of_list
                                  (List.mapi
                                     (fun index (block : Cfg.block) ->
                                       (block.label, fresh_unroll_label iter index))
                                     path))
                          in
                          incr next_id;
                          let rename copied_labels label =
                            Array.fold_left
                              (fun acc (original, renamed) ->
                                match acc with Some _ -> acc | None -> if original = label then Some renamed else None)
                              None copied_labels
                            |> Option.value ~default:label
                          in
                          let next_entry iter =
                            if iter + 1 < trip_int then snd copies.(iter + 1).(0) else info.exit_label
                          in
                          let new_labels = ref [] in
                          Array.iteri
                            (fun iter copied_labels ->
                              let copied_blocks =
                                List.mapi
                                  (fun index (block : Cfg.block) ->
                                    let label = snd copied_labels.(index) in
                                    let term =
                                      if index + 1 = List.length path then
                                        Cfg.Jump (next_entry iter)
                                      else rewrite_term_labels (rename copied_labels) block.term
                                    in
                                    let body =
                                      if index + 1 = List.length path then block.body @ control_block.body
                                      else block.body
                                    in
                                    { block with label; body; term; succs = Cfg.successors term })
                                  path
                              in
                              List.iter
                                (fun (block : Cfg.block) ->
                                  Hashtbl.add current_blocks block.label block;
                                  new_labels := block.label :: !new_labels)
                                copied_blocks)
                            copies;
                          let entry_label = snd copies.(0).(0) in
                          insert_after info.control_label (List.rev !new_labels);
                          changed := true;
                          entry_label
                      in
                      List.iter
                        (fun pred ->
                          let pred_block = get_block pred in
                          let term =
                            rewrite_term_successor pred_block.term ~from_label:header ~to_label:target_label
                          in
                          Hashtbl.replace current_blocks pred
                            { pred_block with term; succs = Cfg.successors term })
                        outside_preds;
                      if header = !current_entry then current_entry := target_label
                  | Some _ | None -> ()))
      headers;
    if !changed then
      let blocks = List.map get_block !block_order in
      Cfg.rebuild_edges { f with entry = !current_entry; blocks }
    else f

(* Full-unroll a small constant-trip loop even when its body contains
   calls and/or global side effects.

   The existing [full_unroll_counted_loops_func] intentionally rejects those
   loops.  That is useful for ordinary optimization, but it leaves an important
   case untouched:

       for a statically-known five iterations:
         call small_effectful_leaf(...);
         update globals;
         branch on the result;

   Unrolling is still semantics-preserving when:
   - the exact trip count is proven from the loop control IV;
   - the loop has one normal exit;
   - only the control block may leave the loop;
   - the control block's own body is small/pure (normally IV increment / compare
     preparation);
   - the trip count and total CFG size are small.

   For a proven positive trip count and a normal top-tested header, clone the
   loop BODY CFG for every iteration while deliberately omitting the redundant
   condition header.  Calls, stores, and internal branches are preserved.
   Original backedges enter the next cloned body directly; the last one exits. *)
let full_unroll_effectful_counted_loops_func summaries globals (f : Cfg.func) =
  let max_trip = 6L in
  let max_loop_blocks = 10 in
  let max_loop_instrs = 72 in
  let max_control_instrs = 5 in
  let debug =
    Sys.getenv_opt "TOYC_DEBUG_EFFECT_UNROLL" <> None
  in
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let current_blocks =
      Hashtbl.create (List.length f.blocks + (12 * List.length headers))
    in
    List.iter
      (fun (block : Cfg.block) ->
        Hashtbl.replace current_blocks block.label block)
      f.blocks;
    let block_order =
      ref (List.map (fun (block : Cfg.block) -> block.label) f.blocks)
    in
    let get_block = get_block_exn current_blocks in
    let current_block_list () = List.map get_block !block_order in
    let insert_after label new_labels =
      block_order :=
        List.concat_map
          (fun current ->
            if current = label then current :: new_labels else [ current ])
          !block_order
    in
    let next_id = ref 0 in
    let next_temp = ref f.temp_count in
    let fresh_temp () =
      let temp = !next_temp in
      incr next_temp;
      temp
    in
    let original_live_in_t, _ =
      compute_liveness summaries globals f
    in
    let fresh_label iter index =
      let id = !next_id in
      Printf.sprintf
        ".L%s_effect_full_unroll_%d_%d_%d"
        f.label id iter index
    in
    let changed = ref false in
    let current_entry = ref f.entry in

    List.iter
      (fun header ->
        if contains_substring header "_effect_full_unroll_" then ()
        else
          let loop = table_find_or_empty loops header LabelSet.empty in
          let blocks_snapshot = current_block_list () in
          let
            (loop_defs, _, def_instrs, multi_defs, _, _, control)
          =
            analyze_counted_loop
              header loop get_block !next_temp blocks_snapshot
          in
          match control with
          | None ->
              if debug then
                Printf.eprintf
                  "effect-full-unroll-skip func=%s header=%s reason=no_control blocks=%d\n%!"
                  f.name header (LabelSet.cardinal loop)
          | Some info ->
              let control_block : Cfg.block = get_block info.control_label in
              let control_body_ok =
                List.length control_block.body <= max_control_instrs
                && List.for_all pure_cfg_prep_instr control_block.body
              in
              let loop_labels =
                !block_order
                |> List.filter (fun label -> LabelSet.mem label loop)
              in
              let total_instrs =
                List.fold_left
                  (fun acc label ->
                    let block : Cfg.block = get_block label in
                    acc + List.length block.body)
                  0 loop_labels
              in
              let outside_preds =
                let header_block : Cfg.block = get_block header in
                List.filter
                  (fun pred -> not (LabelSet.mem pred loop))
                  header_block.preds
              in

              (* Require a single normal exit shape: blocks other than the
                 identified control block may not jump outside the loop. *)
              let exits_are_safe =
                List.for_all
                  (fun label ->
                    let block : Cfg.block = get_block label in
                    List.for_all
                      (fun succ ->
                        if LabelSet.mem succ loop then true
                        else
                          label = info.control_label
                          && succ = info.exit_label)
                      block.succs)
                  loop_labels
              in

              let resolve_const operand =
                match
                  resolve_operand_before_loop
                    loop_defs multi_defs def_instrs operand
                with
                | Some (Tcg.Imm value) -> Some value
                | Some (Tcg.Temp _) | None -> None
              in
              let init_values =
                info.control_iv.outside_inputs
                |> List.filter_map (fun (_, operand) -> resolve_const operand)
                |> List.sort_uniq compare
              in
              let trip_count =
                match init_values with
                | [ init_value ] ->
                    constant_trip_count_of_kind
                      resolve_const
                      init_value
                      info.control_iv.step
                      info.kind
                | _ -> None
              in

              if debug then begin
                let init_text =
                  match init_values with
                  | [] -> "[]"
                  | values ->
                      "["
                      ^ String.concat "," (List.map Int64.to_string values)
                      ^ "]"
                in
                let trip_text =
                  match trip_count with
                  | Some trip -> Int64.to_string trip
                  | None -> "<none>"
                in
                Printf.eprintf
                  "effect-full-unroll-candidate func=%s header=%s control=%s exit=%s blocks=%d instrs=%d control_instrs=%d control_ok=%b exits_ok=%b outside_preds=%d init=%s step=%Ld trip=%s\n%!"
                  f.name header info.control_label info.exit_label
                  (List.length loop_labels) total_instrs
                  (List.length control_block.body)
                  control_body_ok exits_are_safe (List.length outside_preds)
                  init_text info.control_iv.step trip_text
              end;
              let reject_reason =
                if info.control_label <> header then
                  Some "control_not_header"
                else if control_block.body <> [] then
                  Some "control_body_nonempty"
                else if not control_body_ok then Some "control_body"
                else if not exits_are_safe then Some "exit_shape"
                else if
                  info.inside_label = header
                  || not (LabelSet.mem info.inside_label loop)
                then
                  Some "bad_inside"
                else if loop_labels = [] then Some "empty_loop"
                else if List.length loop_labels > max_loop_blocks then
                  Some "too_many_blocks"
                else if total_instrs > max_loop_instrs then
                  Some "too_many_instrs"
                else if outside_preds = [] && header <> !current_entry then
                  Some "no_outside_pred"
                else None
              in
              match reject_reason with
              | Some reason ->
                  if debug then
                    Printf.eprintf
                      "effect-full-unroll-skip func=%s header=%s reason=%s\n%!"
                      f.name header reason
              | None ->
                match trip_count with
                | Some trip when 0L < trip && trip <= max_trip ->
                    let trip_int = Int64.to_int trip in

                    (* The exact positive trip count makes every visit to the
                       top-tested header redundant.  Clone only the actual loop
                       body CFG; internal branches/calls/stores stay intact. *)
                    let body_labels =
                      List.filter
                        (fun label -> label <> info.control_label)
                        loop_labels
                    in
                    let originals =
                      List.map
                        (fun label ->
                          let block : Cfg.block = get_block label in
                          (label, block))
                        body_labels
                    in

                    (* A full-unroll clone must not make one textual scratch
                       temp look live across every cloned call.

                       Rename only temps that are provably local to ONE loop
                       iteration:
                       - defined in the cloned body;
                       - not multiply defined in the original loop;
                       - not live on entry to the loop body (so not carried
                         from the previous iteration);
                       - not live at the loop exit;
                       - not the control IV itself.

                       This deliberately leaves accumulator/carrier/phi-like
                       temps untouched while separating short-lived values
                       such as load/add/call-argument preparation. *)
                    let body_defined_temps =
                      List.fold_left
                        (fun defs (_, (block : Cfg.block)) ->
                          List.fold_left
                            (fun defs instr ->
                              match defs_temp instr with
                              | Some temp -> IntSet.add temp defs
                              | None -> defs)
                            defs block.body)
                        IntSet.empty originals
                    in
                    let body_live_in =
                      table_find_or_empty
                        original_live_in_t
                        info.inside_label
                        IntSet.empty
                    in
                    let exit_live_in =
                      table_find_or_empty
                        original_live_in_t
                        info.exit_label
                        IntSet.empty
                    in
                    let iteration_local_temps =
                      let temps =
                        IntSet.diff body_defined_temps multi_defs
                      in
                      let temps =
                        IntSet.diff temps body_live_in
                      in
                      let temps =
                        IntSet.diff temps exit_live_in
                      in
                      IntSet.remove info.control_iv.phi_temp temps
                    in

                    if
                      originals = []
                      || not
                           (List.exists
                              (fun (label, _) ->
                                label = info.inside_label)
                              originals)
                    then begin
                      if debug then
                        Printf.eprintf
                          "effect-full-unroll-skip func=%s header=%s reason=no_body_after_header\n%!"
                          f.name header
                    end
                    else begin
                      let maps =
                        Array.init trip_int (fun iter ->
                          Array.of_list
                            (List.mapi
                               (fun index (label, _) ->
                                 (label, fresh_label iter index))
                               originals))
                      in
                      incr next_id;

                      let temp_maps =
                        Array.init trip_int (fun _iter ->
                          let map =
                            Hashtbl.create
                              (max 1
                                 (IntSet.cardinal
                                    iteration_local_temps))
                          in
                          IntSet.iter
                            (fun old_temp ->
                              Hashtbl.add
                                map old_temp (fresh_temp ()))
                            iteration_local_temps;
                          map)
                      in
                      let rename_temp_for_iter iter temp =
                        Option.value
                          ~default:temp
                          (Hashtbl.find_opt
                             temp_maps.(iter) temp)
                      in

                      if debug then
                        Printf.eprintf
                          "effect-full-unroll-renaming func=%s header=%s local_temps=%d fresh_temps=%d temp_count=%d->%d\n%!"
                          f.name header
                          (IntSet.cardinal iteration_local_temps)
                          (trip_int
                           * IntSet.cardinal
                               iteration_local_temps)
                          f.temp_count !next_temp;

                      let rename_with map label =
                        Array.fold_left
                          (fun found (old_label, new_label) ->
                            match found with
                            | Some _ -> found
                            | None ->
                                if old_label = label
                                then Some new_label
                                else None)
                          None map
                        |> Option.value ~default:label
                      in

                      let body_entry_of_iter iter =
                        rename_with maps.(iter) info.inside_label
                      in

                      let created_labels = ref [] in
                      Array.iteri
                        (fun iter map ->
                          List.iteri
                            (fun index
                                 (_old_label,
                                  (old_block : Cfg.block)) ->
                              let new_label = snd map.(index) in

                              (* Rename ordinary intra-iteration edges first.
                                 Since the header itself is not in [map], an
                                 original backedge to [header] is still spelled
                                 [header] after this rewrite. *)
                              let rename_temp =
                                rename_temp_for_iter iter
                              in
                              let body =
                                List.map
                                  (rewrite_instr_temps rename_temp)
                                  old_block.body
                              in
                              let term =
                                old_block.term
                                |> rewrite_term_temps rename_temp
                                |> rewrite_term_labels
                                     (rename_with map)
                              in

                              (* A proven backedge no longer re-tests the while
                                 condition.  It enters the next cloned body
                                 directly, or exits after the final iteration. *)
                              let backedge_target =
                                if iter + 1 < trip_int then
                                  body_entry_of_iter (iter + 1)
                                else
                                  info.exit_label
                              in
                              let term =
                                if
                                  List.exists
                                    (fun succ -> succ = header)
                                    old_block.succs
                                then
                                  rewrite_term_successor
                                    term
                                    ~from_label:header
                                    ~to_label:backedge_target
                                else term
                              in
                              let cloned =
                                {
                                  old_block with
                                  label = new_label;
                                  body;
                                  term;
                                  succs = Cfg.successors term;
                                }
                              in
                              Hashtbl.replace
                                current_blocks new_label cloned;
                              created_labels :=
                                new_label :: !created_labels)
                            originals)
                        maps;

                      let first_body = body_entry_of_iter 0 in
                      List.iter
                        (fun pred ->
                          let pred_block : Cfg.block = get_block pred in
                          let term =
                            rewrite_term_successor
                              pred_block.term
                              ~from_label:header
                              ~to_label:first_body
                          in
                          Hashtbl.replace
                            current_blocks pred
                            {
                              pred_block with
                              term;
                              succs = Cfg.successors term;
                            })
                        outside_preds;

                      if header = !current_entry then
                        current_entry := first_body;

                      insert_after
                        header
                        (List.rev !created_labels);
                      changed := true;

                      if debug then
                        Printf.eprintf
                          "effect-full-unroll func=%s header=%s trip=%Ld blocks=%d body_blocks=%d instrs=%d header_elided=true\n%!"
                          f.name header trip
                          (List.length loop_labels)
                          (List.length body_labels)
                          total_instrs
                    end
                | Some 0L ->
                    if debug then
                      Printf.eprintf
                        "effect-full-unroll-skip func=%s header=%s reason=zero_trip\n%!"
                        f.name header;
                    (* Leave zero-trip handling to the ordinary counted-loop
                       simplifier, which already has mature zero-trip logic. *)
                    ()
                | Some trip ->
                    if debug then
                      Printf.eprintf
                        "effect-full-unroll-skip func=%s header=%s reason=trip_too_large trip=%Ld max=%Ld\n%!"
                        f.name header trip max_trip
                | None ->
                    if debug then
                      Printf.eprintf
                        "effect-full-unroll-skip func=%s header=%s reason=unknown_trip\n%!"
                        f.name header)
      headers;

    if !changed then
      let blocks = List.map get_block !block_order in
      Cfg.rebuild_edges
        {
          f with
          entry = !current_entry;
          temp_count = !next_temp;
          blocks;
        }
    else f

let unroll_counted_loops_x2_func summaries globals (f : Cfg.func) =
  let debug_unroll_pair = Sys.getenv_opt "TOYC_DEBUG_UNROLL_PAIR" <> None in
  let unroll_single_path_max_blocks = 6 in
  let unroll_linear_path_max_blocks = 4 in
  let unroll_single_block_min_instrs = 4 in
  let unroll_multi_block_min_instrs = 6 in
  let unroll_single_block_max_instrs = 32 in
  let unroll_small_path_max_instrs = 24 in
  let unroll_large_path_max_instrs = 20 in
  let unroll_single_block_max_memory_ops = 8 in
  let unroll_small_path_max_memory_ops = 5 in
  let unroll_large_path_max_memory_ops = 4 in
  let unroll_single_block_max_defs = 12 in
  let unroll_multi_block_max_defs = 8 in
  let unroll_max_control_body_instrs = 4 in
  let unroll_max_extra_loop_carried_defs = 2 in
  let control_body_supported body =
    List.length body <= unroll_max_control_body_instrs
    && List.for_all pure_cfg_prep_instr body
  in
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let current_blocks = Hashtbl.create (List.length f.blocks + (2 * List.length headers)) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let block_order = ref (List.map (fun (block : Cfg.block) -> block.label) f.blocks) in
    let get_block = get_block_exn current_blocks in
    let update_block (block : Cfg.block) =
      Hashtbl.replace current_blocks block.label block
    in
    let current_block_list () = List.map get_block !block_order in
    let insert_after label new_labels =
      block_order :=
        List.concat_map
          (fun current -> if current = label then current :: new_labels else [ current ])
          !block_order
    in
    let unroll_id = ref 0 in
    let fresh_unroll_label index =
      let id = !unroll_id in
      Printf.sprintf ".L%s_unroll2_%d_%d" f.label id index
    in
    let changed = ref false in
    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        if is_unroll2_label header || LabelSet.exists is_unroll2_label loop then ()
        else
          let blocks_snapshot = current_block_list () in
          let live_in_t, _ =
            compute_liveness summaries globals { f with blocks = blocks_snapshot }
          in
          let (loop_defs, _, def_instrs, multi_defs, _, _, control) =
            analyze_counted_loop header loop get_block f.temp_count blocks_snapshot
          in
          let effects = collect_loop_effects summaries globals loop blocks_snapshot in
          match control with
          | None -> ()
          | Some info -> (
              let control_block : Cfg.block = get_block info.control_label in
              match linear_loop_path info.control_label loop get_block info.inside_label with
              | None -> ()
              | Some path ->
                  let path_blocks = List.length path in
                  let one_block_path = path_blocks <= 1 in
                  let path_max_blocks =
                    if one_block_path then unroll_single_path_max_blocks else unroll_linear_path_max_blocks
                  in
                  let min_instrs =
                    if one_block_path then unroll_single_block_min_instrs else unroll_multi_block_min_instrs
                  in
                  let max_instrs =
                    if one_block_path then unroll_single_block_max_instrs
                    else if path_blocks <= 2 then unroll_small_path_max_instrs
                    else unroll_large_path_max_instrs
                  in
                  let max_memory_ops =
                    if one_block_path then unroll_single_block_max_memory_ops
                    else if path_blocks <= 2 then unroll_small_path_max_memory_ops
                    else unroll_large_path_max_memory_ops
                  in
                  let body_live_in =
                    table_find_or_empty live_in_t info.inside_label IntSet.empty
                  in
                  let extra_loop_carried_defs =
                    IntSet.diff
                      (IntSet.inter loop_defs body_live_in)
                      (IntSet.singleton info.control_iv.phi_temp)
                  in
                  let has_redefined_candidate_temp =
                    let counts = Hashtbl.create 16 in
                    let note_instr instr =
                      match defs_temp instr with
                      | Some temp ->
                          let count = Option.value ~default:0 (Hashtbl.find_opt counts temp) in
                          Hashtbl.replace counts temp (count + 1)
                      | None -> ()
                    in
                    List.iter note_instr control_block.body;
                     List.iter
                       (fun (block : Cfg.block) -> List.iter note_instr block.body)
                       path;
                     Hashtbl.fold (fun _ count seen -> seen || count > 1) counts false
                   in
                  let total_instrs =
                    List.length control_block.body
                    + List.fold_left
                        (fun acc (block : Cfg.block) -> acc + List.length block.body)
                        0 path
                  in
                  let memory_ops =
                    List.fold_left
                      (fun acc (block : Cfg.block) ->
                        acc
                        + List.fold_left
                            (fun sum instr ->
                              sum
                              +
                              match instr with
                              | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> 1
                              | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ -> 0)
                            0 block.body)
                      0 path
                  in
                  let unique_defs =
                    let defs = Hashtbl.create 16 in
                    let note_instr instr =
                      match defs_temp instr with
                      | Some temp -> Hashtbl.replace defs temp ()
                      | None -> ()
                    in
                    List.iter note_instr control_block.body;
                    List.iter (fun (block : Cfg.block) -> List.iter note_instr block.body) path;
                    Hashtbl.length defs
                  in
                  (* A constant even trip count lets the x2 unroll execute the two
                     bodies as an inseparable pair.  The guard between the first
                     and second copies can then never exit.  Only use this fast
                     path when the pure control-preparation temps are private to
                     the guard; otherwise skipping that preparation could change
                     a value observed elsewhere. *)
                  let control_body_defs_are_guard_private =
                    let defs =
                      List.fold_left
                        (fun acc instr ->
                          match defs_temp instr with
                          | Some temp -> IntSet.add temp acc
                          | None -> acc)
                        IntSet.empty control_block.body
                    in
                    IntSet.for_all
                      (fun temp ->
                        List.for_all
                          (fun (block : Cfg.block) ->
                            if block.label = info.control_label then true
                            else
                              not
                                (List.exists (instr_uses_temp temp) block.body
                                || term_uses_temp temp block.term))
                          blocks_snapshot)
                      defs
                  in
                  let exact_trip_count =
                    let resolve_const operand =
                      match resolve_operand_before_loop loop_defs multi_defs def_instrs operand with
                      | Some (Tcg.Imm value) -> Some value
                      | Some (Tcg.Temp _) | None -> None
                    in
                    let init_values =
                      info.control_iv.outside_inputs
                      |> List.filter_map (fun (_, operand) -> resolve_const operand)
                      |> List.sort_uniq compare
                    in
                    match init_values with
                    | [ init_value ] ->
                        constant_trip_count_of_kind
                          resolve_const init_value info.control_iv.step info.kind
                    | _ -> None
                  in
                  let control_body_nontrapping =
                    List.for_all
                      (function
                        | Tcg.Bin (_, (Div | Mod), _, _) -> false
                        | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ -> true
                        | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> false)
                      control_block.body
                  in
                  let can_pair_without_mid_guard =
                    (* The "pair two iterations without the mid-guard" fast path is
                       currently unsound: hot_local_loop_mix proves that we can still
                       lose loop-carried latch updates and generate wrong-code.  Keep
                       x2 unrolling itself, but disable this shortcut until it is
                       rebuilt with explicit parallel-copy/latch-state handling. *)
                    false
                    && control_body_defs_are_guard_private
                    && control_body_nontrapping
                    &&
                    match exact_trip_count with
                    | Some trip -> trip >= 2L && Int64.rem trip 2L = 0L
                    | None -> false
                  in
                  let enough_benefit =
                    total_instrs >= min_instrs
                    && (memory_ops >= 2 || total_instrs >= (if one_block_path then 8 else 10))
                  in
                  if
                    effects.has_call
                    || not (control_body_supported control_block.body)
                    || path = []
                    || path_blocks > path_max_blocks
                    || total_instrs > max_instrs
                    || memory_ops > max_memory_ops
                    || unique_defs > (if one_block_path then unroll_single_block_max_defs else unroll_multi_block_max_defs)
                    || IntSet.cardinal extra_loop_carried_defs > unroll_max_extra_loop_carried_defs
                    || (PlaceSet.is_empty effects.modified_places && not enough_benefit)
                    || has_redefined_candidate_temp
                  then ()
                  else
                    let last_block = List.hd (List.rev path) in
                    if last_block.succs <> [ info.control_label ] then ()
                    else
                      let copied_labels =
                        List.mapi (fun index (block : Cfg.block) -> (block.label, fresh_unroll_label index)) path
                      in
                      incr unroll_id;
                      let rename label =
                        match List.assoc_opt label copied_labels with
                        | Some renamed -> renamed
                        | None -> label
                      in
                      let copied_blocks =
                        List.map
                          (fun (block : Cfg.block) ->
                            let label = rename block.label in
                            let term = rewrite_term_labels rename block.term in
                            { block with label; term; succs = Cfg.successors term })
                          path
                      in
                      let copied_entry =
                        match copied_blocks with
                        | first :: _ -> first.label
                        | [] -> failwith "internal empty unroll path"
                      in
                      if can_pair_without_mid_guard && debug_unroll_pair then
                        Printf.eprintf
                          "unroll2-pair func=%s header=%s trip=%s\n%!"
                          f.name header
                          (match exact_trip_count with
                          | Some trip -> Int64.to_string trip
                          | None -> "?");
                      let body, term =
                        if can_pair_without_mid_guard then
                          (last_block.body, Cfg.Jump copied_entry)
                        else
                          let term =
                            rewrite_term_successor control_block.term
                              ~from_label:info.inside_label ~to_label:copied_entry
                          in
                          (last_block.body @ control_block.body, term)
                      in
                      update_block
                        {
                          last_block with
                          body;
                          term;
                          succs = Cfg.successors term;
                        };
                      List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) copied_blocks;
                      insert_after last_block.label (List.map (fun (block : Cfg.block) -> block.label) copied_blocks);
                      changed := true))
      headers;
    if !changed then
      let blocks = List.map get_block !block_order in
      Cfg.rebuild_edges { f with blocks }
    else f

(* Final-only loop-bound materialization.  BranchCompare has no immediate
   RISC-V form, so codegen otherwise emits a fresh [li] every dynamic trip
   through the branch.  For small, call-free loops that came from our x2
   counted-loop unroller, keep one invariant bound temp in the existing direct
   preheader instead.  This pass deliberately runs after all iterative
   middle-end passes so constant propagation cannot fold the temp back into an
   immediate. *)
let hoist_unrolled_loop_branch_immediates_func summaries globals (f : Cfg.func) =
  let debug_bound_hoist = Sys.getenv_opt "TOYC_DEBUG_LOOP_BOUND_HOIST" <> None in
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let current_blocks = Hashtbl.create (List.length f.blocks) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let get_block = get_block_exn current_blocks in
    let update_block (block : Cfg.block) = Hashtbl.replace current_blocks block.label block in
    let next_temp = ref f.temp_count in
    let fresh_temp () =
      let temp = !next_temp in
      incr next_temp;
      temp
    in
    let changed = ref false in
    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        (* Restrict this to loops already selected by the profitable x2 unroller.
           That keeps the extra long-lived register away from unrelated loops. *)
        if not (LabelSet.exists is_unroll2_label loop) then ()
        else
          let blocks_snapshot = List.map get_block (List.map (fun (b : Cfg.block) -> b.label) f.blocks) in
          let effects = collect_loop_effects summaries globals loop blocks_snapshot in
          if effects.has_call then ()
          else
            let loop_temps =
              List.fold_left
                (fun acc (block : Cfg.block) ->
                  if not (LabelSet.mem block.label loop) then acc
                  else
                    let acc =
                      List.fold_left
                        (fun acc instr ->
                          let acc = add_instr_use_temps acc instr in
                          match defs_temp instr with
                          | Some temp -> IntSet.add temp acc
                          | None -> acc)
                        acc block.body
                    in
                    add_term_use_temps acc block.term)
                IntSet.empty blocks_snapshot
            in
            (* A hoisted bound lives for the whole loop instead of only at the
               exit compare.  Be deliberately stricter than the raw number of
               caller-saved homes: hidden loops near register-pressure limits can
               lose more to one new spill than they save by removing a repeated
               [li].  The proven hot_local_loop_mix case has pressure=5, so this
               cap preserves the observed 69 -> 65 win while declining denser
               loops. *)
            let loop_pressure = IntSet.cardinal loop_temps in
            let max_safe_bound_hoist_pressure = 5 in
            if loop_pressure > max_safe_bound_hoist_pressure then (
              if debug_bound_hoist then
                Printf.eprintf
                  "loop-bound-hoist-skip func=%s header=%s pressure=%d limit=%d\n%!"
                  f.name header loop_pressure max_safe_bound_hoist_pressure)
            else
              let candidates =
                blocks_snapshot
                |> List.filter_map (fun (block : Cfg.block) ->
                     if not (LabelSet.mem block.label loop) then None
                     else
                       match block.term with
                       | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) ->
                           let true_inside = LabelSet.mem if_true loop in
                           let false_inside = LabelSet.mem if_false loop in
                           if true_inside = false_inside then None
                           else (
                             match lhs, rhs with
                             | Tcg.Imm imm, Tcg.Temp _ when imm <> 0L ->
                                 Some (block.label, op, `Left imm, lhs, rhs, if_true, if_false)
                             | Tcg.Temp _, Tcg.Imm imm when imm <> 0L ->
                                 Some (block.label, op, `Right imm, lhs, rhs, if_true, if_false)
                             | _ -> None)
                       | Cfg.Jump _ | Cfg.BranchZero _ | Cfg.BranchNonZero _ | Cfg.Return _ -> None)
              in
              match candidates with
              | [ (branch_label, op, side, lhs, rhs, if_true, if_false) ] ->
                  let header_block = get_block header in
                  let outside_preds =
                    List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds
                  in
                  (* Final-only and deliberately conservative: use an existing
                     direct preheader only.  This avoids changing loop topology
                     after the optimizer has reached its fixed point. *)
                  (match outside_preds with
                  | [ preheader_label ] ->
                      let preheader = get_block preheader_label in
                      if preheader.succs <> [ header ] then ()
                      else
                        let bound =
                          match side with
                          | `Left imm | `Right imm -> imm
                        in
                        let bound_temp = fresh_temp () in
                        update_block
                          { preheader with body = preheader.body @ [ Tcg.Move (bound_temp, Tcg.Imm bound) ] };
                        let branch_block = get_block branch_label in
                        let term =
                          match side with
                          | `Left _ ->
                              Cfg.BranchCompare
                                (op, Tcg.Temp bound_temp, rhs, if_true, if_false)
                          | `Right _ ->
                              Cfg.BranchCompare
                                (op, lhs, Tcg.Temp bound_temp, if_true, if_false)
                        in
                        update_block { branch_block with term; succs = Cfg.successors term };
                        if debug_bound_hoist then
                          Printf.eprintf
                            "loop-bound-hoist func=%s header=%s branch=%s imm=%Ld temp=t%d pressure=%d\n%!"
                            f.name header branch_label bound bound_temp loop_pressure;
                        changed := true
                  | [] | _ :: _ :: _ -> ())
              | [] | _ :: _ :: _ -> ())
      headers;
    if !changed then
      let blocks =
        List.map (fun (block : Cfg.block) -> get_block block.label) f.blocks
      in
      Cfg.rebuild_edges { f with temp_count = !next_temp; blocks }
    else f

let classify_loop_rotate_targets loop (term : Cfg.terminator) =
  match branch_term_outcomes term with
  | Some (first_label, second_label) ->
      let first_inside = LabelSet.mem first_label loop in
      let second_inside = LabelSet.mem second_label loop in
      if first_inside && not second_inside then Some (first_label, second_label)
      else if second_inside && not first_inside then Some (second_label, first_label)
      else None
  | None -> None

let loop_rotate_func (f : Cfg.func) =
  let next_guard_id = ref 0 in
  let fresh_guard_label () =
    let id = !next_guard_id in
    incr next_guard_id;
    Printf.sprintf ".L%s_rotate_guard_%d" f.label id
  in
  let rec apply (current : Cfg.func) =
    let block_map, loops, headers = discover_natural_loops current in
    if headers = [] then current
    else
      match
        List.find_map
          (fun header ->
            let header_block : Cfg.block = Hashtbl.find block_map header in
            let loop = table_find_or_empty loops header LabelSet.empty in
            let outside_preds =
              List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds
            in
            let backedge_preds =
              List.filter (fun pred -> LabelSet.mem pred loop) header_block.preds
            in
            if
              header_block.body <> []
              || backedge_preds = []
              || (outside_preds = [] && header <> current.entry)
              || is_rotate_guard_label header
            then None
            else
              match classify_loop_rotate_targets loop header_block.term with
              | None -> None
              | Some (_inside_label, _exit_label) ->
                  let guard_label = fresh_guard_label () in
                  let guard_block =
                    {
                      Cfg.label = guard_label;
                      body = [];
                      term = header_block.term;
                      preds = [];
                      succs = Cfg.successors header_block.term;
                    }
                  in
                  let blocks =
                    let redirected_blocks =
                      List.map
                        (fun (block : Cfg.block) ->
                          if List.exists (fun pred -> pred = block.label) outside_preds then
                            let term =
                              rewrite_term_successor block.term ~from_label:header ~to_label:guard_label
                            in
                            { block with term; succs = Cfg.successors term }
                          else block)
                        current.blocks
                    in
                    List.fold_right
                      (fun (block : Cfg.block) acc ->
                        if block.label = header then guard_block :: block :: acc else block :: acc)
                      redirected_blocks []
                  in
                  let entry = if header = current.entry then guard_label else current.entry in
                  Some (Cfg.rebuild_edges { current with entry; blocks }))
          headers
      with
      | Some rotated -> apply rotated
      | None -> current
  in
  apply f

(* Dynamic loop strength reduction using the step112 LVE analysis.

   First target:
       p = i * k
       i.next = i + step
   where [step] and [k] may both be runtime loop-invariant values.

   We build a second recurrence:
       p.start = i.start * k
       p.step  = step * k
   and replace the per-iteration multiply with [p]. *)
let loop_evolution_strength_reduce_func (f : Cfg.func) =
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let doms = compute_dominators f in
    let _, def_blocks, def_instrs, multi_defs =
      analyze_temp_defs_of_blocks f.temp_count f.blocks
    in
    let current_blocks = Hashtbl.create (List.length f.blocks) in
    List.iter
      (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block)
      f.blocks;
    let get_block = get_block_exn current_blocks in
    let update_block (block : Cfg.block) =
      Hashtbl.replace current_blocks block.label block
    in
    let next_temp = ref f.temp_count in
    let fresh_temp () =
      let temp = !next_temp in
      incr next_temp;
      temp
    in
    let changed = ref false in
    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        let loop_defs = loop_defined_temps loop get_block in
        let addrecs =
          analyze_loop_addrecs
            header loop get_block loop_defs multi_defs def_instrs
        in
        List.iter
          (fun (iv : loop_addrec) ->
            let outside_preds = List.map fst iv.addrec_outside_inputs in
            if
              outside_preds <> []
              && lve_expr_available_before_preds
                   doms def_blocks multi_defs outside_preds iv.addrec_step
            then begin
              let derived_uses = Hashtbl.create 4 in
              List.iter
                (fun (block : Cfg.block) ->
                  if LabelSet.mem block.label loop then
                    List.iteri
                      (fun index instr ->
                        match
                          lve_affine_candidate
                            loop_defs multi_defs def_instrs addrecs block iv instr
                        with
                        | Some (dst, scale_expr, bias_expr)
                          when lve_useful_affine iv scale_expr bias_expr
                               && lve_expr_available_before_preds
                                    doms def_blocks multi_defs outside_preds scale_expr
                               && lve_expr_available_before_preds
                                    doms def_blocks multi_defs outside_preds bias_expr ->
                            let key =
                              ( normalize_loop_inv_expr scale_expr,
                                normalize_loop_inv_expr bias_expr )
                            in
                            let uses =
                              Option.value ~default:[] (Hashtbl.find_opt derived_uses key)
                            in
                            Hashtbl.replace derived_uses key
                              ((block.label, index, dst) :: uses)
                        | Some _ | None -> ())
                      (get_block block.label).body)
                f.blocks;
              Hashtbl.iter
                (fun (scale_expr, bias_expr) uses ->
                  if uses <> [] then begin
                    changed := true;
                    let derived_phi = fresh_temp () in
                    let derived_step = fresh_temp () in
                    let step_times_scale =
                      normalize_loop_inv_expr (LveMul (iv.addrec_step, scale_expr))
                    in
                    List.iter
                      (fun (pred, _source) ->
                        let pred_block = get_block pred in
                        let init_expr =
                          normalize_loop_inv_expr
                            (LveAdd
                               ( LveMul
                                   ( LveOperand (Tcg.Temp iv.addrec_phi_temp),
                                     scale_expr ),
                                 bias_expr ))
                        in
                        let body =
                          pred_block.body
                          @ emit_loop_inv_expr fresh_temp derived_phi init_expr
                          @ emit_loop_inv_expr fresh_temp derived_step step_times_scale
                        in
                        update_block { pred_block with body })
                      iv.addrec_outside_inputs;
                    List.iter
                      (fun pred ->
                        let pred_block = get_block pred in
                        let update =
                          simplify_simple_instr
                            (Tcg.Bin
                               ( derived_phi,
                                 Add,
                                 Tcg.Temp derived_phi,
                                 Tcg.Temp derived_step ))
                        in
                        update_block { pred_block with body = pred_block.body @ [ update ] })
                      iv.addrec_backedge_preds;
                    List.iter
                      (fun (block : Cfg.block) ->
                        if LabelSet.mem block.label loop then
                          let current = get_block block.label in
                          let replacements = Hashtbl.create (List.length uses) in
                          List.iter
                            (fun (label, index, dst) ->
                              if label = current.label then
                                Hashtbl.replace replacements index dst)
                            uses;
                          if Hashtbl.length replacements > 0 then
                            let body =
                              List.mapi
                                (fun index instr ->
                                  match Hashtbl.find_opt replacements index with
                                  | Some dst -> Tcg.Move (dst, Tcg.Temp derived_phi)
                                  | None -> instr)
                                current.body
                            in
                            update_block { current with body })
                      f.blocks;
                    if Sys.getenv_opt "TOYC_DEBUG_LVE" <> None then
                      Printf.eprintf
                        "lve-sr func=%s header=%s base=t%d scale=%s bias=%s step=%s uses=%d derived=t%d delta=t%d\n%!"
                        f.name header iv.addrec_phi_temp
                        (string_of_loop_inv_expr scale_expr)
                        (string_of_loop_inv_expr bias_expr)
                        (string_of_loop_inv_expr iv.addrec_step)
                        (List.length uses) derived_phi derived_step
                  end)
                derived_uses
            end)
          addrecs)
      headers;
    if !changed then
      let ordered_labels = List.map (fun (block : Cfg.block) -> block.label) f.blocks in
      let blocks = List.map get_block ordered_labels in
      Cfg.rebuild_edges { f with temp_count = !next_temp; blocks }
    else f

let strength_reduce_func (f : Cfg.func) =
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let _, def_blocks, def_instrs, multi_defs =
      analyze_temp_defs_of_blocks f.temp_count f.blocks
    in
    let current_blocks = Hashtbl.create (List.length f.blocks) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let get_block = get_block_exn current_blocks in
    let update_block (block : Cfg.block) =
      Hashtbl.replace current_blocks block.label block
    in
    let next_temp = ref f.temp_count in
    let fresh_temp () =
      let temp = !next_temp in
      incr next_temp;
      temp
    in
    let changed = ref false in
    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        let loop_defs = loop_defined_temps loop get_block in
        let loop_stable_phis =
          collect_loop_stable_phis header loop get_block def_blocks multi_defs def_instrs
        in
        let ivs =
          analyze_induction_vars header loop get_block loop_defs multi_defs def_instrs
          |> proven_syntactic_induction_vars
        in
        List.iter
          (fun (iv : basic_induction_var) ->
            let derived_uses = Hashtbl.create 4 in
            List.iter
              (fun (block : Cfg.block) ->
                if LabelSet.mem block.label loop then
                  List.iteri
                    (fun index instr ->
                      match
                        derived_expr_of_instr
                          loop_defs loop_stable_phis multi_defs def_instrs iv.phi_temp instr
                      with
                      | Some (dst, key) ->
                          let uses = Option.value ~default:[] (Hashtbl.find_opt derived_uses key) in
                          Hashtbl.replace derived_uses key ((block.label, index, dst) :: uses)
                      | None -> ())
                    (get_block block.label).body)
              f.blocks;
            Hashtbl.iter
               (fun key uses ->
                if worthwhile_derived_key key uses then begin
                  changed := true;
                  let derived_phi = fresh_temp () in
                  List.iter
                    (fun (pred, src) ->
                      let pred_block = get_block pred in
                      let body = pred_block.body @ build_derived_init key derived_phi src in
                      update_block { pred_block with body })
                    iv.outside_inputs;
                  let delta = delta_of_derived_key iv.step key in
                  List.iter
                    (fun pred ->
                      let pred_block = get_block pred in
                      let body = pred_block.body @ build_derived_backedge_update derived_phi delta in
                      update_block { pred_block with body })
                    iv.backedge_preds;
                  List.iter
                    (fun (block : Cfg.block) ->
                      if LabelSet.mem block.label loop then
                        let current = get_block block.label in
                        let replacements = Hashtbl.create (List.length uses) in
                        List.iter
                          (fun (label, index, dst) ->
                            if label = current.label then Hashtbl.replace replacements index dst)
                          uses;
                        if Hashtbl.length replacements > 0 then
                          let body =
                            List.mapi
                              (fun index instr ->
                                match Hashtbl.find_opt replacements index with
                                | Some dst -> Tcg.Move (dst, Tcg.Temp derived_phi)
                                | None -> instr)
                              current.body
                          in
                          update_block { current with body })
                    f.blocks
                end)
              derived_uses)
          ivs)
      headers;
    if !changed then
      let ordered_labels = List.map (fun (block : Cfg.block) -> block.label) f.blocks in
      let blocks = List.map get_block ordered_labels in
      Cfg.rebuild_edges { f with temp_count = !next_temp; blocks }
    else f

let temp_use_counts blocks =
  let counts = Hashtbl.create 32 in
  let add_operand = function
    | Tcg.Temp temp ->
        let count = Option.value ~default:0 (Hashtbl.find_opt counts temp) in
        Hashtbl.replace counts temp (count + 1)
    | Tcg.Imm _ -> ()
  in
  let add_instr_uses = function
    | Tcg.Move (_, src)
    | Tcg.Un (_, _, src) ->
        add_operand src
    | Tcg.Bin (_, _, lhs, rhs) ->
        add_operand lhs;
        add_operand rhs
    | Tcg.Load _ -> ()
    | Tcg.Store (_, value) -> add_operand value
    | Tcg.Call (_, _, args) -> List.iter add_operand args
  in
  let add_term_uses = function
    | Cfg.Jump _ | Cfg.Return None -> ()
    | Cfg.BranchZero (cond, _, _)
    | Cfg.BranchNonZero (cond, _, _)
    | Cfg.Return (Some cond) ->
        add_operand cond
    | Cfg.BranchCompare (_, lhs, rhs, _, _) ->
        add_operand lhs;
        add_operand rhs
  in
  List.iter
    (fun (block : Cfg.block) ->
      List.iter add_instr_uses block.body;
      add_term_uses block.term)
    blocks;
  counts

let algebra_canonicalize_func (f : Cfg.func) =
  let _, _, def_instrs, multi_defs =
    analyze_temp_defs_of_blocks f.temp_count f.blocks
  in
  let use_counts = temp_use_counts f.blocks in
  let use_count temp =
    Option.value ~default:0 (Hashtbl.find_opt use_counts temp)
  in
  let add_i32 a b = i32 Int64.(add (i32 a) (i32 b)) in
  let sub_i32 a b = i32 Int64.(sub (i32 a) (i32 b)) in
  let mul_i32 a b = i32 Int64.(mul (i32 a) (i32 b)) in
  let neg_i32 value = i32 Int64.(neg (i32 value)) in
  let rec affine_of_operand seen = function
    | Tcg.Imm _ -> None
    | Tcg.Temp temp as operand ->
        if IntSet.mem temp seen || IntSet.mem temp multi_defs || use_count temp <> 1 then
          Some (operand, 1, 0L, false)
        else
          let seen = IntSet.add temp seen in
          match Hashtbl.find_opt def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) -> (
              match affine_of_operand seen src with
              | Some (base, sign, bias, _) -> Some (base, sign, bias, true)
              | None -> Some (operand, 1, 0L, false))
          | Some (Tcg.Un (_, UMinus, src)) -> (
              match affine_of_operand seen src with
              | Some (base, sign, bias, _) ->
                  Some (base, -sign, neg_i32 bias, true)
              | None -> Some (operand, 1, 0L, false))
          | Some (Tcg.Bin (_, Add, lhs, Tcg.Imm c))
          | Some (Tcg.Bin (_, Add, Tcg.Imm c, lhs)) -> (
              match affine_of_operand seen lhs with
              | Some (base, sign, bias, _) ->
                  Some (base, sign, add_i32 bias c, true)
              | None -> Some (operand, 1, 0L, false))
          | Some (Tcg.Bin (_, Sub, lhs, Tcg.Imm c)) -> (
              match affine_of_operand seen lhs with
              | Some (base, sign, bias, _) ->
                  Some (base, sign, sub_i32 bias c, true)
              | None -> Some (operand, 1, 0L, false))
          | Some (Tcg.Bin (_, Sub, Tcg.Imm c, rhs)) -> (
              match affine_of_operand seen rhs with
              | Some (base, sign, bias, _) ->
                  Some (base, -sign, sub_i32 c bias, true)
              | None -> Some (operand, 1, 0L, false))
          | Some (Tcg.Un _)
          | Some (Tcg.Bin _)
          | Some (Tcg.Load _)
          | Some (Tcg.Store _)
          | Some (Tcg.Call _)
          | None ->
              Some (operand, 1, 0L, false)
  in
  let rec scale_of_operand seen = function
    | Tcg.Imm _ -> None
    | Tcg.Temp temp as operand ->
        if IntSet.mem temp seen || IntSet.mem temp multi_defs || use_count temp <> 1 then
          Some (operand, 1L, false)
        else
          let seen = IntSet.add temp seen in
          match Hashtbl.find_opt def_instrs temp with
          | Some (Tcg.Move (_, src))
          | Some (Tcg.Un (_, UPlus, src)) -> (
              match scale_of_operand seen src with
              | Some (base, factor, _) -> Some (base, factor, true)
              | None -> Some (operand, 1L, false))
          | Some (Tcg.Un (_, UMinus, src)) -> (
              match scale_of_operand seen src with
              | Some (base, factor, _) ->
                  Some (base, neg_i32 factor, true)
              | None -> Some (operand, 1L, false))
          | Some (Tcg.Bin (_, Mul, lhs, Tcg.Imm c))
          | Some (Tcg.Bin (_, Mul, Tcg.Imm c, lhs)) -> (
              match scale_of_operand seen lhs with
              | Some (base, factor, _) ->
                  Some (base, mul_i32 factor c, true)
              | None -> Some (operand, 1L, false))
          | Some (Tcg.Un _)
          | Some (Tcg.Bin _)
          | Some (Tcg.Load _)
          | Some (Tcg.Store _)
          | Some (Tcg.Call _)
          | None ->
              Some (operand, 1L, false)
  in
  let build_affine dst (base, sign, bias) =
    if sign = 1 then
      if bias = 0L then Tcg.Move (dst, base)
      else Tcg.Bin (dst, Add, base, Tcg.Imm bias)
    else if bias = 0L then
      Tcg.Un (dst, UMinus, base)
    else
      Tcg.Bin (dst, Sub, Tcg.Imm bias, base)
  in
  let build_scale dst base factor =
    if factor = 0L then Tcg.Move (dst, Tcg.Imm 0L)
    else if factor = 1L then Tcg.Move (dst, base)
    else if factor = -1L then Tcg.Un (dst, UMinus, base)
    else Tcg.Bin (dst, Mul, base, Tcg.Imm factor)
  in
  let unique_def_of_operand = function
    | Tcg.Temp temp when not (IntSet.mem temp multi_defs) ->
        Hashtbl.find_opt def_instrs temp
    | Tcg.Temp _ | Tcg.Imm _ -> None
  in
  let cancel_add_sub dst lhs rhs =
    (* i32 arithmetic is modulo 2^32, so these cancellations remain valid
       even when the intermediate addition/subtraction wraps.  Only follow
       unique temporary definitions; phi/multi-definition temporaries are
       deliberately excluded. *)
    match unique_def_of_operand lhs with
    | Some (Tcg.Bin (_, Add, a, b)) when operand_equal rhs a ->
        Some (Tcg.Move (dst, b))
    | Some (Tcg.Bin (_, Add, a, b)) when operand_equal rhs b ->
        Some (Tcg.Move (dst, a))
    | _ -> (
        match unique_def_of_operand rhs with
        | Some (Tcg.Bin (_, Sub, a, b)) when operand_equal lhs a ->
            Some (Tcg.Move (dst, b))
        | _ -> None)
  in
  let cancel_sub_add dst lhs rhs =
    let from_mid mid other =
      match unique_def_of_operand mid with
      | Some (Tcg.Bin (_, Sub, a, b)) when operand_equal other b ->
          Some (Tcg.Move (dst, a))
      | _ -> None
    in
    match from_mid lhs rhs with
    | Some _ as rewritten -> rewritten
    | None -> from_mid rhs lhs
  in
  let rewrites = ref 0 in
  let cancellation_rewrites = ref 0 in
  let rewrite_instr instr =
    let initial = simplify_simple_instr instr in
    let rewritten =
      match initial with
      | Tcg.Bin (dst, Add, lhs, rhs) -> (
          match cancel_sub_add dst lhs rhs with
          | Some rewritten ->
              incr cancellation_rewrites;
              rewritten
          | None ->
              let lhs, rhs =
                match (lhs, rhs) with
                | Tcg.Imm c, other -> (other, Tcg.Imm c)
                | _ -> (lhs, rhs)
              in
              begin match rhs with
              | Tcg.Imm c -> (
                  match affine_of_operand IntSet.empty lhs with
                  | Some (base, sign, bias, true) ->
                      build_affine dst (base, sign, add_i32 bias c)
                  | Some _ | None -> Tcg.Bin (dst, Add, lhs, rhs))
              | Tcg.Temp _ -> Tcg.Bin (dst, Add, lhs, rhs)
              end)
      | Tcg.Bin (dst, Sub, lhs, rhs) -> (
          match cancel_add_sub dst lhs rhs with
          | Some rewritten ->
              incr cancellation_rewrites;
              rewritten
          | None -> (
              match (lhs, rhs) with
              | lhs, Tcg.Imm c -> (
                  match affine_of_operand IntSet.empty lhs with
                  | Some (base, sign, bias, true) ->
                      build_affine dst (base, sign, sub_i32 bias c)
                  | Some _ | None -> initial)
              | Tcg.Imm c, rhs -> (
                  match affine_of_operand IntSet.empty rhs with
                  | Some (base, sign, bias, true) ->
                      build_affine dst (base, -sign, sub_i32 c bias)
                  | Some _ | None -> initial)
              | Tcg.Temp _, Tcg.Temp _ -> initial))
      | Tcg.Bin (dst, Mul, lhs, rhs) ->
          let lhs, rhs =
            match (lhs, rhs) with
            | Tcg.Imm c, other -> (other, Tcg.Imm c)
            | _ -> (lhs, rhs)
          in
          begin match rhs with
          | Tcg.Imm c -> (
              match scale_of_operand IntSet.empty lhs with
              | Some (base, factor, true) ->
                  build_scale dst base (mul_i32 factor c)
              | Some _ | None -> Tcg.Bin (dst, Mul, lhs, rhs))
          | Tcg.Temp _ -> Tcg.Bin (dst, Mul, lhs, rhs)
          end
      | Tcg.Un (dst, UMinus, src) -> (
          match affine_of_operand IntSet.empty src with
          | Some (base, sign, bias, true) ->
              build_affine dst (base, -sign, neg_i32 bias)
          | Some _ | None -> initial)
      | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ ->
          initial
    in
    let rewritten = simplify_simple_instr rewritten in
    if rewritten <> instr then incr rewrites;
    rewritten
  in
  let blocks =
    List.map
      (fun (block : Cfg.block) ->
        let body = List.map rewrite_instr block.body in
        { block with body })
      f.blocks
  in
  if Sys.getenv_opt "TOYC_DEBUG_ALGEBRA" <> None then
    Printf.eprintf
      "algebra func=%s rewrites=%d cancellations=%d\n%!"
      f.name !rewrites !cancellation_rewrites;
  if !rewrites = 0 then f else Cfg.rebuild_edges { f with blocks }

let general_linear_canonicalize_func (f : Cfg.func) =
  let analyze = make_linear_analyzer f in
  let rewrites = ref 0 in
  let rewrite_instr instr =
    let initial = simplify_simple_instr instr in
    let candidate =
      match initial with
      | Tcg.Un (dst, ((UPlus | UMinus) as op), src) -> (
          match linear_form_of_un analyze op src with
          | Some form -> (
              match reify_linear_one_instr dst form with
              | Some rewritten -> simplify_simple_instr rewritten
              | None -> initial)
          | None -> initial)
      | Tcg.Bin (dst, ((Add | Sub | Mul) as op), lhs, rhs) -> (
          match linear_form_of_bin analyze op lhs rhs with
          | Some form -> (
              match reify_linear_one_instr dst form with
              | Some rewritten -> simplify_simple_instr rewritten
              | None -> initial)
          | None -> initial)
      | Tcg.Move _
      | Tcg.Un _
      | Tcg.Bin _
      | Tcg.Load _
      | Tcg.Store _
      | Tcg.Call _ ->
          initial
    in
    if candidate <> instr then incr rewrites;
    candidate
  in
  let blocks =
    List.map
      (fun (block : Cfg.block) ->
        { block with body = List.map rewrite_instr block.body })
      f.blocks
  in
  if Sys.getenv_opt "TOYC_DEBUG_LINEAR" <> None then
    Printf.eprintf
      "linear-canon func=%s rewrites=%d\n%!"
      f.name !rewrites;
  if !rewrites = 0 then f
  else Cfg.rebuild_edges { f with blocks }



(* Factor a syntactically common multiplicative term across a single-use
   add/sub pair:

       p = a * b
       q = a * c
       r = p + q       ==>       q = b + c
                                  r = a * q

   and analogously for subtraction.

   The transformation is valid in ToyC's wrapping integer arithmetic because
   multiplication distributes over addition/subtraction modulo 2^32.  Keep it
   deliberately local and conservative:
   - both product temps must have a unique definition and a single use;
   - both product definitions must be in the same block before the consumer;
   - a temp used as the common factor (and the earlier residual operand) must
     not be redefined between the two products.

   DCE removes the now-dead earlier multiplication immediately afterwards in
   the normal pipeline. *)
let factor_common_mul_func (f : Cfg.func) =
  let canonical_scalar = make_linear_analyzer f in
  let canonical_operand_equal lhs rhs =
    canonical_scalar_key_equal
      (canonical_scalar lhs)
      (canonical_scalar rhs)
  in
  let use_counts = temp_use_counts f.blocks in
  let _, _, _, multi_defs =
    analyze_temp_defs_of_blocks f.temp_count f.blocks
  in
  let single_use temp =
    Option.value ~default:0 (Hashtbl.find_opt use_counts temp) = 1
  in
  let instr_def_temp = function
    | Tcg.Move (dst, _)
    | Tcg.Un (dst, _, _)
    | Tcg.Bin (dst, _, _, _)
    | Tcg.Load (dst, _)
    | Tcg.Call (Some dst, _, _) ->
        Some dst
    | Tcg.Store _
    | Tcg.Call (None, _, _) ->
        None
  in
  let changed = ref false in
  let rewrites = ref 0 in
  let semantic_common_rewrites = ref 0 in

  let rewrite_block (block : Cfg.block) =
    let body = Array.of_list block.body in
    let local_mul_defs = Hashtbl.create 16 in
    Array.iteri
      (fun index instr ->
        match instr with
        | Tcg.Bin (dst, Mul, lhs, rhs)
          when not (IntSet.mem dst multi_defs) ->
            Hashtbl.replace local_mul_defs dst (index, lhs, rhs)
        | _ -> ())
      body;

    let operand_stable_between operand first_index second_index =
      match operand with
      | Tcg.Imm _ -> true
      | Tcg.Temp temp ->
          let stable = ref true in
          for index = first_index + 1 to second_index - 1 do
            match instr_def_temp body.(index) with
            | Some dst when dst = temp -> stable := false
            | Some _ | None -> ()
          done;
          !stable
    in

    let common_factors (lhs1, rhs1) (lhs2, rhs2) =
      if canonical_operand_equal lhs1 lhs2 then
        Some (lhs1, rhs1, rhs2)
      else if canonical_operand_equal lhs1 rhs2 then
        Some (lhs1, rhs1, lhs2)
      else if canonical_operand_equal rhs1 lhs2 then
        Some (rhs1, lhs1, rhs2)
      else if canonical_operand_equal rhs1 rhs2 then
        Some (rhs1, lhs1, lhs2)
      else
        None
    in

    let replacements = Hashtbl.create 8 in
    Array.iteri
      (fun consumer_index instr ->
        let try_factor op lhs_temp rhs_temp dst =
          if
            lhs_temp = rhs_temp
            || IntSet.mem lhs_temp multi_defs
            || IntSet.mem rhs_temp multi_defs
            || not (single_use lhs_temp)
            || not (single_use rhs_temp)
          then
            ()
          else
            match
              ( Hashtbl.find_opt local_mul_defs lhs_temp,
                Hashtbl.find_opt local_mul_defs rhs_temp )
            with
            | ( Some (lhs_index, lhs_a, lhs_b),
                Some (rhs_index, rhs_a, rhs_b) )
              when lhs_index < consumer_index
                   && rhs_index < consumer_index
                   && lhs_index <> rhs_index -> (
                match common_factors (lhs_a, lhs_b) (rhs_a, rhs_b) with
                | None -> ()
                | Some (common, lhs_rest, rhs_rest) ->
                    let early_index, early_rest, late_index, late_temp =
                      if lhs_index < rhs_index then
                        (lhs_index, lhs_rest, rhs_index, rhs_temp)
                      else
                        (rhs_index, rhs_rest, lhs_index, lhs_temp)
                    in
                    if
                      operand_stable_between common early_index late_index
                      && operand_stable_between
                           early_rest early_index late_index
                    then begin
                      let raw_cross_common =
                        lhs_a = rhs_a
                        || lhs_a = rhs_b
                        || lhs_b = rhs_a
                        || lhs_b = rhs_b
                      in
                      if not raw_cross_common then
                        incr semantic_common_rewrites;
                      let residual =
                        simplify_simple_instr
                          (Tcg.Bin (late_temp, op, lhs_rest, rhs_rest))
                      in
                      let product =
                        simplify_simple_instr
                          (Tcg.Bin
                             (dst, Mul, common, Tcg.Temp late_temp))
                      in
                      Hashtbl.replace replacements late_index residual;
                      Hashtbl.replace replacements consumer_index product;
                      changed := true;
                      incr rewrites
                    end)
            | _ -> ()
        in
        match instr with
        | Tcg.Bin
            (dst, ((Add | Sub) as op), Tcg.Temp lhs_temp, Tcg.Temp rhs_temp) ->
            try_factor op lhs_temp rhs_temp dst
        | _ -> ())
      body;

    if Hashtbl.length replacements = 0 then block
    else
      let body =
        Array.to_list
          (Array.mapi
             (fun index instr ->
               match Hashtbl.find_opt replacements index with
               | Some replacement -> replacement
               | None -> instr)
             body)
      in
      { block with body }
  in

  let blocks = List.map rewrite_block f.blocks in
  if
    Sys.getenv_opt "TOYC_DEBUG_FACTOR_MUL" <> None
    && !rewrites > 0
  then
    Printf.eprintf
      "factor-mul func=%s rewrites=%d semantic-common=%d\n%!"
      f.name !rewrites !semantic_common_rewrites;
  if not !changed then f
  else Cfg.rebuild_edges { f with blocks }


type reassoc_first =
  | FirstVarPlusInv of Tcg.operand * Tcg.operand
  | FirstVarMinusInv of Tcg.operand * Tcg.operand
  | FirstInvMinusVar of Tcg.operand * Tcg.operand

type reassoc_second =
  | SecondMidPlusInv of Tcg.temp * Tcg.operand
  | SecondMidMinusInv of Tcg.temp * Tcg.operand
  | SecondInvMinusMid of Tcg.temp * Tcg.operand

let classify_reassoc_first invariant = function
  | Tcg.Bin (mid, Add, lhs, rhs) ->
      if invariant lhs && not (invariant rhs) then Some (mid, FirstVarPlusInv (rhs, lhs))
      else if not (invariant lhs) && invariant rhs then
        Some (mid, FirstVarPlusInv (lhs, rhs))
      else None
  | Tcg.Bin (mid, Sub, lhs, rhs) ->
      if not (invariant lhs) && invariant rhs then Some (mid, FirstVarMinusInv (lhs, rhs))
      else if invariant lhs && not (invariant rhs) then
        Some (mid, FirstInvMinusVar (lhs, rhs))
      else None
  | Tcg.Bin (_, (Mul | Div | Mod | Lt | Gt | Le | Ge | Eq | Ne | LAnd | LOr), _, _) ->
      None
  | Tcg.Move _ | Tcg.Un _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> None

let classify_reassoc_second mid invariant = function
  | Tcg.Bin (dst, Add, lhs, rhs) when lhs = Tcg.Temp mid && invariant rhs ->
      Some (SecondMidPlusInv (dst, rhs))
  | Tcg.Bin (dst, Add, lhs, rhs) when rhs = Tcg.Temp mid && invariant lhs ->
      Some (SecondMidPlusInv (dst, lhs))
  | Tcg.Bin (dst, Sub, lhs, rhs) when lhs = Tcg.Temp mid && invariant rhs ->
      Some (SecondMidMinusInv (dst, rhs))
  | Tcg.Bin (dst, Sub, lhs, rhs) when rhs = Tcg.Temp mid && invariant lhs ->
      Some (SecondInvMinusMid (dst, lhs))
  | Tcg.Bin (_, (Mul | Div | Mod | Lt | Gt | Le | Ge | Eq | Ne | LAnd | LOr), _, _) ->
      None
  | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> None

let build_reassoc_instrs mid first_shape second_shape =
  let inv_bin dst op lhs rhs = simplify_simple_instr (Tcg.Bin (dst, op, lhs, rhs)) in
  let add_mid dst variant = simplify_simple_instr (Tcg.Bin (dst, Add, variant, Tcg.Temp mid)) in
  let sub_mid_from dst variant =
    simplify_simple_instr (Tcg.Bin (dst, Sub, Tcg.Temp mid, variant))
  in
  let sub_variant_from dst variant =
    simplify_simple_instr (Tcg.Bin (dst, Sub, variant, Tcg.Temp mid))
  in
  match (first_shape, second_shape) with
  | FirstVarPlusInv (variant, inv1), SecondMidPlusInv (dst, inv2) ->
      Some (inv_bin mid Add inv1 inv2, add_mid dst variant)
  | FirstVarPlusInv (variant, inv1), SecondMidMinusInv (dst, inv2) ->
      Some (inv_bin mid Sub inv1 inv2, add_mid dst variant)
  | FirstVarPlusInv (variant, inv1), SecondInvMinusMid (dst, inv2) ->
      Some (inv_bin mid Sub inv2 inv1, sub_mid_from dst variant)
  | FirstVarMinusInv (variant, inv1), SecondMidPlusInv (dst, inv2) ->
      Some (inv_bin mid Sub inv2 inv1, add_mid dst variant)
  | FirstVarMinusInv (variant, inv1), SecondMidMinusInv (dst, inv2) ->
      Some (inv_bin mid Add inv1 inv2, sub_variant_from dst variant)
  | FirstVarMinusInv (variant, inv1), SecondInvMinusMid (dst, inv2) ->
      Some (inv_bin mid Add inv2 inv1, sub_mid_from dst variant)
  | FirstInvMinusVar (inv1, variant), SecondMidPlusInv (dst, inv2) ->
      Some (inv_bin mid Add inv1 inv2, sub_mid_from dst variant)
  | FirstInvMinusVar (inv1, variant), SecondMidMinusInv (dst, inv2) ->
      Some (inv_bin mid Sub inv1 inv2, sub_mid_from dst variant)
  | FirstInvMinusVar (inv1, variant), SecondInvMinusMid (dst, inv2) ->
      Some (inv_bin mid Sub inv2 inv1, add_mid dst variant)

let reassociate_loop_adds_func (f : Cfg.func) =
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let _, def_blocks, def_instrs, multi_defs =
      analyze_temp_defs_of_blocks f.temp_count f.blocks
    in
    let use_counts = temp_use_counts f.blocks in
    let current_blocks = Hashtbl.create (List.length f.blocks) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let get_block = get_block_exn current_blocks in
    let changed = ref false in
    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        let loop_defs = loop_defined_temps loop get_block in
        let loop_stable_phis =
          collect_loop_stable_phis header loop get_block def_blocks multi_defs def_instrs
        in
        let invariant operand =
          operand_loop_invariant
            loop_defs loop_stable_phis multi_defs def_instrs IntSet.empty operand
        in
        List.iter
          (fun (block : Cfg.block) ->
            if LabelSet.mem block.label loop then
              let current = get_block block.label in
              let single_use temp =
                Option.value ~default:0 (Hashtbl.find_opt use_counts temp) = 1
              in
              let try_reassociate first second =
                match classify_reassoc_first invariant first with
                | Some (mid, first_shape) when single_use mid -> (
                    match classify_reassoc_second mid invariant second with
                    | Some second_shape -> build_reassoc_instrs mid first_shape second_shape
                    | None -> None)
                | Some _ | None -> None
              in
              let rec rewrite = function
                | first :: second :: rest -> (
                    match try_reassociate first second with
                    | Some (first', second') ->
                        changed := true;
                        first' :: second' :: rewrite rest
                    | None -> first :: rewrite (second :: rest))
                | body -> body
              in
              Hashtbl.replace current_blocks current.label { current with body = rewrite current.body })
          f.blocks)
      headers;
    if !changed then
      let ordered_labels = List.map (fun (block : Cfg.block) -> block.label) f.blocks in
      let blocks = List.map get_block ordered_labels in
      Cfg.rebuild_edges { f with blocks }
    else f

let unswitch_max_blocks = 16
let unswitch_min_instrs = 12
let unswitch_min_memory_ops = 2
let unswitch_max_instrs = 96

let unswitch_loops_func _summaries _globals (f : Cfg.func) =
  let block_map, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let exception Applied of Cfg.func in
    let _, _, def_instrs, multi_defs =
      analyze_temp_defs_of_blocks f.temp_count f.blocks
    in
    try
      List.iter
        (fun header ->
          let loop = table_find_or_empty loops header LabelSet.empty in
          if is_unswitch_label header || LabelSet.exists is_unswitch_label loop then ()
          else
            let header_block : Cfg.block = Hashtbl.find block_map header in
            let outside_preds = List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds in
            if outside_preds = [] && header <> f.entry then ()
            else
              let loop_blocks =
                f.blocks
                |> List.filter (fun (block : Cfg.block) -> LabelSet.mem block.label loop)
              in
              let total_instrs =
                List.fold_left (fun acc (block : Cfg.block) -> acc + List.length block.body) 0 loop_blocks
              in
              let memory_ops = loop_memory_ops_count loop f.blocks in
              if
                List.length loop_blocks > unswitch_max_blocks
                || total_instrs > unswitch_max_instrs
                || total_instrs < unswitch_min_instrs
                || (memory_ops < unswitch_min_memory_ops && total_instrs < (2 * unswitch_min_instrs))
              then ()
              else
                let loop_defs = loop_defined_temps loop (get_block_exn block_map) in
                match
                  List.find_map
                    (fun (block : Cfg.block) ->
                      match (branch_term_outcomes block.term, rewrite_branch_term_before_loop loop_defs multi_defs def_instrs block.term) with
                      | Some (if_true, if_false), Some dispatch_term
                        when LabelSet.mem if_true loop && LabelSet.mem if_false loop ->
                          Some (block, if_true, if_false, dispatch_term)
                      | _ -> None)
                    loop_blocks
                with
                | None -> ()
                | Some (branch_block, if_true, if_false, dispatch_term) ->
                    let original_labels = List.map (fun (block : Cfg.block) -> block.label) f.blocks in
                    let current_blocks = Hashtbl.create (List.length f.blocks + (2 * List.length loop_blocks) + 1) in
                    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
                    let get_block = get_block_exn current_blocks in
                    let update_block (block : Cfg.block) =
                      Hashtbl.replace current_blocks block.label block
                    in
                    let clone_id = List.length loop_blocks + List.length outside_preds + List.length header_block.succs in
                    let dispatch_label =
                      Printf.sprintf ".L%s_unswitch_dispatch_%s_%d" f.label header clone_id
                    in
                    let true_map =
                      List.mapi
                        (fun index (block : Cfg.block) ->
                          ( block.label,
                            Printf.sprintf ".L%s_unswitch_t_%s_%d_%d" f.label header clone_id index ))
                        loop_blocks
                    in
                    let false_map =
                      List.mapi
                        (fun index (block : Cfg.block) ->
                          ( block.label,
                            Printf.sprintf ".L%s_unswitch_f_%s_%d_%d" f.label header clone_id index ))
                        loop_blocks
                    in
                    let rename label map =
                      match List.assoc_opt label map with
                      | Some renamed -> renamed
                      | None -> label
                    in
                    let true_header = rename header true_map in
                    let false_header = rename header false_map in
                    let dispatch_term = branch_term_with_targets dispatch_term true_header false_header in
                    let dispatch_block =
                      {
                        Cfg.label = dispatch_label;
                        body = [];
                        term = dispatch_term;
                        preds = [];
                        succs = Cfg.successors dispatch_term;
                      }
                    in
                    let clone_block map chosen_target (block : Cfg.block) =
                      let label = rename block.label map in
                      let term =
                        if block.label = branch_block.label then Cfg.Jump (rename chosen_target map)
                        else rewrite_term_labels (fun lbl -> rename lbl map) block.term
                      in
                      { block with label; term; preds = []; succs = Cfg.successors term }
                    in
                    let true_blocks = List.map (clone_block true_map if_true) loop_blocks in
                    let false_blocks = List.map (clone_block false_map if_false) loop_blocks in
                    let redirects = Hashtbl.create (List.length outside_preds) in
                    List.iter
                      (fun pred -> Hashtbl.add redirects (pred, header) dispatch_label)
                      outside_preds;
                    List.iter
                      (fun pred ->
                        let pred_block = get_block pred in
                        let term = redirect_successors pred redirects pred_block.term in
                        update_block { pred_block with term; succs = Cfg.successors term })
                      outside_preds;
                    Hashtbl.add current_blocks dispatch_label dispatch_block;
                    List.iter
                      (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block)
                      true_blocks;
                    List.iter
                      (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block)
                      false_blocks;
                    let new_blocks =
                      dispatch_label
                      :: List.map (fun (block : Cfg.block) -> block.label) true_blocks
                      @ List.map (fun (block : Cfg.block) -> block.label) false_blocks
                    in
                    let entry = if header = f.entry then dispatch_label else f.entry in
                    let blocks =
                      List.map get_block original_labels @ List.map get_block new_blocks
                    in
                    let unswitched = Cfg.rebuild_edges { f with entry; blocks } in
                    let reachable = reachable_labels unswitched.entry unswitched.blocks in
                    let blocks =
                      List.filter
                        (fun (block : Cfg.block) -> LabelSet.mem block.label reachable)
                        unswitched.blocks
                    in
                    raise (Applied (Cfg.rebuild_edges { unswitched with blocks })))
        headers;
      f
    with
    | Applied next -> next

let licm_func summaries globals (f : Cfg.func) =
  let _, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let current_blocks = Hashtbl.create (List.length f.blocks + List.length headers) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let get_block = get_block_exn current_blocks in
    let update_block (block : Cfg.block) =
      Hashtbl.replace current_blocks block.Cfg.label block
    in
    let original_block_labels =
      List.map (fun (block : Cfg.block) -> block.label) f.blocks
    in
    let original_block_set =
      List.fold_left
        (fun acc label -> LabelSet.add label acc)
        LabelSet.empty
        original_block_labels
    in
    let current_block_list () =
      let original_blocks =
        List.filter_map
          (fun label -> Hashtbl.find_opt current_blocks label)
          original_block_labels
      in
      let extra_blocks =
        Hashtbl.fold
          (fun label block acc ->
            if LabelSet.mem label original_block_set then acc
            else block :: acc)
          current_blocks
          []
        |> List.sort
             (fun (a : Cfg.block) (b : Cfg.block) ->
               String.compare a.label b.label)
      in
      original_blocks @ extra_blocks
    in
    let new_blocks_rev = ref [] in
    let preheader_id = ref 0 in
    let fresh_preheader_label () =
      let id = !preheader_id in
      incr preheader_id;
      Printf.sprintf ".L%s_licm_preheader_%d" f.label id
    in
    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        let header_block = get_block header in
        let outside_preds =
          List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds
        in
        if outside_preds <> [] then begin
          let blocks_snapshot = current_block_list () in
          let loop_defs, def_blocks, def_instrs, multi_defs =
            analyze_temp_defs_of_blocks ~loop f.temp_count blocks_snapshot
          in
          let effects = collect_loop_effects summaries globals loop blocks_snapshot in
          let loop_stable_phis =
            collect_loop_stable_phis header loop get_block def_blocks multi_defs def_instrs
          in
          let invariant_keys = ref InstrKeySet.empty in
          let invariant_temps = ref IntSet.empty in
          let changed = ref true in
          while !changed do
            changed := false;
            List.iter
              (fun (block : Cfg.block) ->
                if LabelSet.mem block.label loop then (
                  let current = get_block block.label in
                  List.iteri
                    (fun index instr ->
                      let key = (current.label, index) in
                      if not (InstrKeySet.mem key !invariant_keys) then
                        match
                          licm_invariant_candidate
                            loop_defs
                            loop_stable_phis
                            multi_defs
                            def_instrs
                            !invariant_temps
                            effects
                            instr
                        with
                        | Some dst ->
                            invariant_keys := InstrKeySet.add key !invariant_keys;
                            invariant_temps := IntSet.add dst !invariant_temps;
                            changed := true
                        | None -> ())
                    current.body))
              f.blocks
          done;
          if not (InstrKeySet.is_empty !invariant_keys) then begin
            let scheduled_keys = ref InstrKeySet.empty in
            let ready_temps = ref IntSet.empty in
            let hoisted_rev = ref [] in
            let progress = ref true in
            while !progress do
              progress := false;
              List.iter
                (fun (block : Cfg.block) ->
                  if LabelSet.mem block.label loop then (
                    let current = get_block block.label in
                    List.iteri
                      (fun index instr ->
                        let key = (current.label, index) in
                        if InstrKeySet.mem key !invariant_keys
                           && not (InstrKeySet.mem key !scheduled_keys)
                        then
                          match
                            licm_invariant_candidate
                              loop_defs
                              loop_stable_phis
                              multi_defs
                              def_instrs
                              !ready_temps
                              effects
                              instr
                          with
                          | Some dst ->
                              hoisted_rev := instr :: !hoisted_rev;
                              scheduled_keys := InstrKeySet.add key !scheduled_keys;
                              ready_temps := IntSet.add dst !ready_temps;
                              progress := true
                          | None -> ())
                      current.body))
                f.blocks
            done;
            if not (InstrKeySet.is_empty !scheduled_keys) then begin
              let preheader_label =
                match outside_preds with
                | [ pred ] ->
                    let pred_block = get_block pred in
                    if pred_block.succs = [ header ] then pred else fresh_preheader_label ()
                | _ -> fresh_preheader_label ()
              in
              let created_preheader = not (Hashtbl.mem current_blocks preheader_label) in
              if created_preheader then begin
                let redirects = Hashtbl.create (List.length outside_preds) in
                List.iter
                  (fun pred -> Hashtbl.add redirects (pred, header) preheader_label)
                  outside_preds;
                List.iter
                  (fun pred ->
                    let pred_block = get_block pred in
                    let term = redirect_successors pred redirects pred_block.term in
                    update_block { pred_block with term; succs = Cfg.successors term })
                  outside_preds;
                let preheader =
                  {
                    Cfg.label = preheader_label;
                    body = [];
                    term = Cfg.Jump header;
                    preds = [];
                    succs = [ header ];
                  }
                in
                Hashtbl.add current_blocks preheader_label preheader;
                new_blocks_rev := preheader_label :: !new_blocks_rev
              end;
              let preheader = get_block preheader_label in
              let hoisted = List.rev !hoisted_rev in
              let body = gvn_rewrite_instrs summaries globals (preheader.body @ hoisted) in
              update_block { preheader with body };
              List.iter
                (fun (block : Cfg.block) ->
                  if LabelSet.mem block.label loop then
                    let current = get_block block.label in
                    let body =
                      List.mapi (fun index instr -> ((current.label, index), instr)) current.body
                      |> List.filter (fun (key, _) -> not (InstrKeySet.mem key !scheduled_keys))
                      |> List.map snd
                    in
                    update_block { current with body })
                f.blocks
            end
          end
        end)
      headers;
    let ordered_labels = List.map (fun (block : Cfg.block) -> block.label) f.blocks in
    let blocks =
      List.map get_block ordered_labels
      @ List.rev_map get_block !new_blocks_rev
    in
    Cfg.rebuild_edges { f with blocks }

let rewrite_branch_operand term operand =
  match term with
  | Cfg.BranchZero (Tcg.Temp _, if_zero, if_nonzero) ->
      if if_zero = if_nonzero then Cfg.Jump if_zero
      else Cfg.BranchZero (operand, if_zero, if_nonzero)
  | Cfg.BranchNonZero (Tcg.Temp _, if_nonzero, if_zero) ->
      if if_zero = if_nonzero then Cfg.Jump if_zero
      else Cfg.BranchNonZero (operand, if_nonzero, if_zero)
  | _ -> term

let invert_branch_on_operand term operand =
  match term with
  | Cfg.BranchZero (Tcg.Temp _, if_zero, if_nonzero) ->
      if if_zero = if_nonzero then Cfg.Jump if_zero
      else Cfg.BranchNonZero (operand, if_zero, if_nonzero)
  | Cfg.BranchNonZero (Tcg.Temp _, if_nonzero, if_zero) ->
      if if_zero = if_nonzero then Cfg.Jump if_zero
      else Cfg.BranchZero (operand, if_nonzero, if_zero)
  | _ -> term

let fold_compare_branch_term term op lhs rhs =
  match term with
  | Cfg.BranchZero (Tcg.Temp _, if_zero, if_nonzero)
  | Cfg.BranchNonZero (Tcg.Temp _, if_nonzero, if_zero) ->
      if if_zero = if_nonzero then Cfg.Jump if_zero
      else Cfg.BranchCompare (op, lhs, rhs, if_nonzero, if_zero)
  | _ -> term

let fold_branch_tails_func summaries globals (f : Cfg.func) =
  let live_in_t, _ = compute_liveness summaries globals f in
  let blocks =
    List.map
      (fun (block : Cfg.block) ->
        let live_out = live_out_t live_in_t block in
        match List.rev block.body with
        | Tcg.Move (dst, src) :: rest
          when not (IntSet.mem dst live_out) -> (
            match block.term with
            | Cfg.BranchZero (Tcg.Temp temp, _, _)
            | Cfg.BranchNonZero (Tcg.Temp temp, _, _)
              when temp = dst ->
                let term = rewrite_branch_operand block.term src in
                { block with body = List.rev rest; term; succs = Cfg.successors term }
            | _ -> block)
        | Tcg.Un (dst, UPlus, src) :: rest
          when not (IntSet.mem dst live_out) -> (
            match block.term with
            | Cfg.BranchZero (Tcg.Temp temp, _, _)
            | Cfg.BranchNonZero (Tcg.Temp temp, _, _)
              when temp = dst ->
                let term = rewrite_branch_operand block.term src in
                { block with body = List.rev rest; term; succs = Cfg.successors term }
            | _ -> block)
        | Tcg.Un (dst, UNot, src) :: rest
          when not (IntSet.mem dst live_out) -> (
            match block.term with
            | Cfg.BranchZero (Tcg.Temp temp, _, _)
            | Cfg.BranchNonZero (Tcg.Temp temp, _, _)
              when temp = dst ->
                let term = invert_branch_on_operand block.term src in
                { block with body = List.rev rest; term; succs = Cfg.successors term }
            | _ -> block)
        | Tcg.Bin (dst, op, lhs, rhs) :: rest
          when is_compare_binop op && not (IntSet.mem dst live_out) -> (
            match block.term with
            | Cfg.BranchZero (Tcg.Temp temp, _, _)
            | Cfg.BranchNonZero (Tcg.Temp temp, _, _)
              when temp = dst ->
                let term = fold_compare_branch_term block.term op lhs rhs in
                { block with body = List.rev rest; term; succs = Cfg.successors term }
            | _ -> block)
        | _ -> block)
      f.blocks
  in
  Cfg.rebuild_edges { f with blocks }

let count_calls_in_func (f : Cfg.func) =
  List.fold_left
    (fun count (block : Cfg.block) ->
      List.fold_left
        (fun count instr ->
          match instr with
          | Tcg.Call _ -> count + 1
          | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ -> count)
        count block.body)
    0 f.blocks

let eliminate_dead_code_func ?removable_calls summaries globals return_globals (f : Cfg.func) =
  let calls_before =
    if Sys.getenv_opt "TOYC_DEBUG_DEAD_CALLS" <> None then Some (count_calls_in_func f)
    else None
  in
  let live_in_t, live_in_p =
    compute_liveness_with_return_globals ?removable_calls summaries globals return_globals f
  in
  let count_global_stores blocks =
    List.fold_left
      (fun count (block : Cfg.block) ->
        List.fold_left
          (fun count instr ->
            match instr with
            | Tcg.Store (Tcg.Global _, _) -> count + 1
            | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ ->
                count)
          count block.body)
      0 blocks
  in
  let before_global_stores =
    if Sys.getenv_opt "TOYC_DEBUG_GLOBAL_DSE" <> None then
      Some (count_global_stores f.blocks)
    else None
  in
  let blocks =
    List.map
      (fun (block : Cfg.block) ->
        let live_t_out =
          List.fold_left
            (fun acc succ ->
              IntSet.union acc (table_find_or_empty live_in_t succ IntSet.empty))
            IntSet.empty block.succs
        in
        let live_p_out =
          List.fold_left
            (fun acc succ ->
              PlaceSet.union acc (table_find_or_empty live_in_p succ PlaceSet.empty))
            PlaceSet.empty block.succs
        in
        let block, _, _ =
          scan_block ~return_globals ?removable_calls summaries globals block live_t_out live_p_out
        in
        { block with succs = Cfg.successors block.term })
      f.blocks
  in
  begin
    match before_global_stores with
    | Some before ->
        let after = count_global_stores blocks in
        if before <> after then
          Printf.eprintf
            "global-dse func=%s return_globals=%d/%d global_stores=%d->%d removed=%d\n%!"
            f.name (PlaceSet.cardinal return_globals) (PlaceSet.cardinal globals)
            before after (before - after)
    | None -> ()
  end;
  let result = Cfg.rebuild_edges { f with blocks } in
  begin
    match calls_before with
    | Some before ->
        let after = count_calls_in_func result in
        if after < before then
          Printf.eprintf
            "dead-call-dce func=%s calls=%d->%d removed=%d\n%!"
            f.name before after (before - after)
    | None -> ()
  end;
  result

let simplify_counted_loop_guards_func _summaries _globals (f : Cfg.func) =
  let block_map, loops, headers = discover_natural_loops f in
  let get_block = get_block_exn block_map in
  if headers = [] then f
  else
    let current_blocks = Hashtbl.create (List.length f.blocks) in
    List.iter (fun (block : Cfg.block) -> Hashtbl.add current_blocks block.label block) f.blocks;
    let get_current = get_block_exn current_blocks in
    let def_instrs = temp_def_instrs_map f in
    let changed = ref false in
    Hashtbl.iter
      (fun header loop ->
        let loop_blocks = List.filter (fun (block : Cfg.block) -> LabelSet.mem block.label loop) f.blocks in
        let loop_defs = loop_defined_temps loop get_block in
        let multi_defs = multi_def_temps_of_blocks f.temp_count loop_blocks in
        let loop_stable_phis = collect_header_phi_temps header get_block in
        let _, control =
          analyze_counted_control header loop get_block loop_defs loop_stable_phis multi_defs def_instrs
        in
        match control with
        | None -> ()
        | Some info ->
            LabelSet.iter
              (fun label ->
                if label <> info.control_label then
                  let block : Cfg.block = get_current label in
                let fold_branch op lhs rhs if_true if_false =
                  let try_fold op lhs rhs =
                    match
                      ( iv_bias_of_operand_in_block block multi_defs def_instrs info.control_iv.phi_temp lhs,
                        operand_static_int64 loop_defs multi_defs def_instrs rhs )
                      with
                      | Some bias, Some constant -> (
                          match
                            compare_truth_from_range op (range_of_counted_iv_expr info.kind bias) constant
                          with
                          | Some true -> Some (Cfg.Jump if_true)
                          | Some false -> Some (Cfg.Jump if_false)
                          | None -> None)
                      | _ -> None
                  in
                  match try_fold op lhs rhs with
                  | Some term -> Some term
                  | None -> try_fold (swap_compare op) rhs lhs
                in
                match block.term with
                | Cfg.BranchCompare (op, lhs, rhs, if_true, if_false) -> (
                    match fold_branch op lhs rhs if_true if_false with
                    | Some term ->
                        changed := true;
                        Hashtbl.replace current_blocks label { block with term; succs = Cfg.successors term }
                    | None -> ())
                | Cfg.BranchZero (cond, if_zero, if_nonzero) -> (
                    match resolve_compare_operand_in_block block multi_defs def_instrs cond with
                    | Some (op, lhs, rhs) -> (
                        match fold_branch op lhs rhs if_nonzero if_zero with
                        | Some term ->
                            changed := true;
                            Hashtbl.replace current_blocks label { block with term; succs = Cfg.successors term }
                        | None -> ())
                    | None -> ())
                | Cfg.BranchNonZero (cond, if_nonzero, if_zero) -> (
                    match resolve_compare_operand_in_block block multi_defs def_instrs cond with
                    | Some (op, lhs, rhs) -> (
                        match fold_branch op lhs rhs if_nonzero if_zero with
                        | Some term ->
                            changed := true;
                            Hashtbl.replace current_blocks label { block with term; succs = Cfg.successors term }
                        | None -> ())
                    | None -> ())
                | Cfg.Jump _ | Cfg.Return _ -> ())
              loop)
      loops;
    if not !changed then f
    else
      let ordered_labels = List.map (fun (block : Cfg.block) -> block.label) f.blocks in
       let blocks = List.map get_current ordered_labels in
       Cfg.rebuild_edges { f with blocks }

let split_counted_diamond_loops_func _summaries _globals (f : Cfg.func) =
  let block_map, loops, headers = discover_natural_loops f in
  let next_temp = ref f.temp_count in
  let fresh_temp () =
    let temp = !next_temp in
    incr next_temp;
    temp
  in
  if headers = [] then f
  else
    let exception Applied of Cfg.func in
    let pure_scalar_block (block : Cfg.block) =
      List.for_all
        (function
          | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ -> true
          | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ -> false)
        block.body
    in
    let rec collapse_pure_scalar_connector loop seen label =
      if LabelSet.mem label seen || not (Hashtbl.mem block_map label) then None
      else
        let block : Cfg.block = Hashtbl.find block_map label in
        if not (LabelSet.mem block.label loop) then None
        else if not (pure_scalar_block block) then None
        else
          match block.succs with
          | [] -> Some block.label
           | [ next ] ->
               if transparent_loop_connector block then
                 collapse_pure_scalar_connector loop (LabelSet.add label seen) next
               else Some block.label
           | _ -> Some block.label
    in
    let outer_limit_of_kind loop_defs multi_defs def_instrs = function
      | CountUpLt (bound, bias) -> normalize_limit_operand loop_defs multi_defs def_instrs bound Int64.(neg bias)
      | CountUpLe (bound, bias) -> normalize_limit_operand loop_defs multi_defs def_instrs bound Int64.(sub 1L bias)
      | CountDownGt (bound, bias) -> normalize_limit_operand loop_defs multi_defs def_instrs bound Int64.(neg bias)
      | CountDownGe (bound, bias) -> normalize_limit_operand loop_defs multi_defs def_instrs bound Int64.(neg bias)
      | CountUpLtScaled _
      | CountUpLeScaled _
      | CountDownGtScaled _
      | CountDownGeScaled _ ->
          None
    in
    let normalized_limit_is_entry_invariant loop_defs = function
      | LimitConst _ -> true
      | LimitOperand (operand, _) -> (
          match operand with
          | Tcg.Imm _ -> true
          | Tcg.Temp temp -> not (IntSet.mem temp loop_defs))
    in
    let normalized_limit_is_const = function
      | LimitConst _ -> true
      | LimitOperand _ -> false
    in
    let normalized_limit_equal lhs rhs =
      match (lhs, rhs) with
      | LimitConst a, LimitConst b -> a = b
      | LimitOperand (Tcg.Imm a, delta_a), LimitOperand (Tcg.Imm b, delta_b) ->
          a = b && delta_a = delta_b
      | LimitOperand (Tcg.Temp a, delta_a), LimitOperand (Tcg.Temp b, delta_b) ->
          a = b && delta_a = delta_b
      | _ -> false
    in
    let materialize_adjusted_operand operand delta =
      match operand with
      | Tcg.Imm constant -> ([], Tcg.Imm Int64.(add constant delta))
      | _ when delta = 0L -> ([], operand)
      | _ ->
          let temp = fresh_temp () in
          ([ Tcg.Bin (temp, Add, operand, Tcg.Imm delta) ], Tcg.Temp temp)
    in
    let materialize_limit_operand = function
      | LimitConst bound -> ([], Tcg.Imm bound)
      | LimitOperand (operand, delta) -> materialize_adjusted_operand operand delta
    in
    let branch_with_rhs compare_op iv_temp rhs if_true if_false =
      Cfg.BranchCompare (compare_op, Tcg.Temp iv_temp, rhs, if_true, if_false)
    in
    let build_branch_for_limit compare_op iv_temp limit if_true if_false =
      match limit with
      | LimitConst bound ->
          ([], branch_with_rhs compare_op iv_temp (Tcg.Imm bound) if_true if_false)
      | LimitOperand (operand, delta) ->
          let body, rhs = materialize_adjusted_operand operand delta in
          (body, branch_with_rhs compare_op iv_temp rhs if_true if_false)
    in
    let build_branch_for_shifted_compare compare_op iv_temp operand bias if_true if_false =
      let body, rhs = materialize_adjusted_operand operand Int64.(neg bias) in
      (body, branch_with_rhs compare_op iv_temp rhs if_true if_false)
    in
    let loop_counts_up = function
      | CountUpLt _ | CountUpLe _ | CountUpLtScaled _ | CountUpLeScaled _ -> true
      | CountDownGt _ | CountDownGe _ | CountDownGtScaled _ | CountDownGeScaled _ -> false
    in
    let first_phase_uses_true_branch kind split_op =
      if loop_counts_up kind then
        match split_op with
        | Lt | Le -> true
        | Gt | Ge -> false
        | Eq | Ne | Add | Sub | Mul | Div | Mod | LAnd | LOr -> false
      else
        match split_op with
        | Gt | Ge -> true
        | Lt | Le -> false
        | Eq | Ne | Add | Sub | Mul | Div | Mod | LAnd | LOr -> false
    in
    let prefix_limit_of_split loop_defs multi_defs def_instrs kind split_op operand bias =
      let delta =
        match kind with
        | CountUpLt _ -> (
            match split_op with
            | Lt | Ge -> Int64.neg bias
            | Le | Gt -> Int64.(sub 1L bias)
            | Eq | Ne | Add | Sub | Mul | Div | Mod | LAnd | LOr -> 0L)
        | CountUpLe _ -> (
            match split_op with
            | Lt | Ge -> Int64.(sub (neg bias) 1L)
            | Le | Gt -> Int64.neg bias
            | Eq | Ne | Add | Sub | Mul | Div | Mod | LAnd | LOr -> 0L)
        | CountDownGt _ -> (
            match split_op with
            | Gt | Le -> Int64.neg bias
            | Ge | Lt -> Int64.(sub (neg bias) 1L)
            | Eq | Ne | Add | Sub | Mul | Div | Mod | LAnd | LOr -> 0L)
        | CountDownGe _ -> (
            match split_op with
            | Gt | Le -> Int64.(add (neg bias) 1L)
            | Ge | Lt -> Int64.neg bias
            | Eq | Ne | Add | Sub | Mul | Div | Mod | LAnd | LOr -> 0L)
        | CountUpLtScaled _
        | CountUpLeScaled _
        | CountDownGtScaled _
        | CountDownGeScaled _ ->
            0L
      in
      match (kind, split_op) with
      | ( CountUpLtScaled _
        | CountUpLeScaled _
        | CountDownGtScaled _
        | CountDownGeScaled _ ),
        _ ->
          None
      | _, split_op ->
          (match split_op with
      | Lt | Le | Gt | Ge -> normalize_limit_operand loop_defs multi_defs def_instrs operand delta
      | Eq | Ne | Add | Sub | Mul | Div | Mod | LAnd | LOr -> None)
    in
    let should_split_loop loop_blocks outer_limit prefix_limit =
      let block_count = List.length loop_blocks in
      let instr_count =
        List.fold_left (fun acc (block : Cfg.block) -> acc + List.length block.body) 0 loop_blocks
      in
      let branchy_blocks =
        List.fold_left
          (fun acc (block : Cfg.block) ->
            match block.term with
            | Cfg.BranchZero _ | Cfg.BranchNonZero _ | Cfg.BranchCompare _ -> acc + 1
            | Cfg.Jump _ | Cfg.Return _ -> acc)
          0 loop_blocks
      in
      let const_benefit =
        normalized_limit_is_const outer_limit || normalized_limit_is_const prefix_limit
      in
      block_count <= 10
      && instr_count <= 28
      && branchy_blocks <= 4
      && (const_benefit || instr_count <= 18)
    in
    let relabel_func_prefix prefix (func : Cfg.func) =
      let mapping = Hashtbl.create (List.length func.blocks) in
      let blocks =
        List.mapi
          (fun index (block : Cfg.block) ->
            let label = Printf.sprintf ".L%s_%s_%d" f.label prefix index in
            Hashtbl.add mapping block.label label;
            { block with label })
          func.blocks
      in
      let rename label = Option.value ~default:label (Hashtbl.find_opt mapping label) in
      let blocks =
        List.map
          (fun (block : Cfg.block) ->
            let term = rewrite_term_labels rename block.term in
            { block with term; succs = Cfg.successors term })
          blocks
      in
      { func with entry = rename func.entry; blocks }
    in
    let _, _, def_instrs, multi_defs =
      analyze_temp_defs_of_blocks f.temp_count f.blocks
    in
    try
      List.iter
        (fun header ->
          let loop = table_find_or_empty loops header LabelSet.empty in
          let header_block : Cfg.block = Hashtbl.find block_map header in
          let loop_blocks =
            f.blocks |> List.filter (fun (block : Cfg.block) -> LabelSet.mem block.label loop)
          in
          let loop_defs = loop_defined_temps loop (get_block_exn block_map) in
          let loop_stable_phis = collect_header_phi_temps header (Hashtbl.find block_map) in
          let _, control =
            analyze_counted_control
              header loop (Hashtbl.find block_map) loop_defs loop_stable_phis multi_defs def_instrs
          in
          match control with
          | None -> ()
          | Some info ->
              let control_block : Cfg.block = Hashtbl.find block_map info.control_label in
              let split_block =
                if info.control_label = header then
                  Hashtbl.find block_map info.inside_label
                else control_block
              in
              let header_term_for_limit =
                match info.kind with
                | CountUpLt _ -> Lt
                | CountUpLe _ -> Le
                | CountDownGt _ -> Gt
                | CountDownGe _ -> Ge
                | CountUpLtScaled _ -> Lt
                | CountUpLeScaled _ -> Le
                | CountDownGtScaled _ -> Gt
                | CountDownGeScaled _ -> Ge
              in
              match branch_term_outcomes split_block.term with
                | Some (branch_a, branch_b)
                  when LabelSet.mem branch_a loop && LabelSet.mem branch_b loop -> (
                     let branch_a_block : Cfg.block = Hashtbl.find block_map branch_a in
                     let branch_b_block : Cfg.block = Hashtbl.find block_map branch_b in
                     if
                       not
                         ( pure_scalar_block split_block
                         && pure_scalar_block branch_a_block
                         && pure_scalar_block branch_b_block )
                       || branch_a = branch_b
                     then ()
                     else
                       match
                         ( collapse_pure_scalar_connector loop LabelSet.empty branch_a,
                           collapse_pure_scalar_connector loop LabelSet.empty branch_b,
                           branch_compare_shape_in_block split_block multi_defs def_instrs split_block.term,
                           outer_limit_of_kind loop_defs multi_defs def_instrs info.kind )
                       with
                       | Some join_a, Some join_b, Some (split_op0, lhs, rhs, if_true, if_false), Some outer_limit
                         when join_a = join_b -> (
                           let join_label = join_a in
                           let split_info =
                             match
                               ( iv_bias_of_operand_in_block
                                   split_block
                                   multi_defs
                                   def_instrs
                                   info.control_iv.phi_temp
                                   lhs,
                                 resolve_operand_before_loop loop_defs multi_defs def_instrs rhs )
                             with
                             | Some bias, Some rhs_operand ->
                                 Some (split_op0, rhs_operand, bias, if_true, if_false)
                             | _ -> (
                                 match
                                   ( iv_bias_of_operand_in_block
                                       split_block
                                       multi_defs
                                       def_instrs
                                       info.control_iv.phi_temp
                                       rhs,
                                     resolve_operand_before_loop loop_defs multi_defs def_instrs lhs )
                                 with
                                 | Some bias, Some lhs_operand ->
                                     Some (swap_compare split_op0, lhs_operand, bias, if_true, if_false)
                                 | _ -> None)
                           in
                           match split_info with
                           | Some (split_op, split_operand, split_bias, if_true, if_false) ->
                               begin
                                 match
                                   prefix_limit_of_split
                                     loop_defs
                                     multi_defs
                                     def_instrs
                                     info.kind
                                     split_op
                                     split_operand
                                     split_bias
                                 with
                                 | Some prefix_limit
                                   when normalized_limit_is_entry_invariant loop_defs outer_limit
                                        && normalized_limit_is_entry_invariant loop_defs prefix_limit
                                        && not (normalized_limit_equal outer_limit prefix_limit)
                                        && should_split_loop loop_blocks outer_limit prefix_limit ->
                                   let first_uses_true =
                                     first_phase_uses_true_branch info.kind split_op
                                   in
                                   let first_branch =
                                     if first_uses_true then if_true else if_false
                                   in
                                   let second_branch =
                                     if first_uses_true then if_false else if_true
                                   in
                                   let before_bridge_label =
                                     Printf.sprintf ".L%s_split_bridge_%s" f.label header
                                   in
                                   let entry_dispatch_label =
                                     Printf.sprintf ".L%s_split_entry_%s" f.label header
                                   in
                                   let split_dispatch_label =
                                     Printf.sprintf ".L%s_split_dispatch_%s" f.label header
                                   in
                                   let limit_dispatch_label =
                                     Printf.sprintf ".L%s_split_limit_dispatch_%s" f.label header
                                   in
                                   let limit_take_outer_label =
                                     Printf.sprintf ".L%s_split_limit_outer_%s" f.label header
                                   in
                                   let limit_take_prefix_label =
                                     Printf.sprintf ".L%s_split_limit_prefix_%s" f.label header
                                   in
                                   let pre_limit_temp = fresh_temp () in
                                   let clone_loop prefix header_rhs exit_target split_term_builder =
                                     let blocks =
                                       List.map
                                         (fun (block : Cfg.block) ->
                                           if block.label = header then
                                             let term =
                                               branch_with_rhs
                                                 header_term_for_limit
                                                 info.control_iv.phi_temp
                                                 header_rhs
                                                 info.inside_label
                                                 exit_target
                                             in
                                             {
                                               block with
                                               body = [];
                                               term;
                                               succs = Cfg.successors term;
                                             }
                                           else if block.label = split_block.label then
                                             let body, term =
                                               split_term_builder first_branch second_branch
                                             in
                                             {
                                               block with
                                               body;
                                               term;
                                               succs = Cfg.successors term;
                                             }
                                           else block)
                                         loop_blocks
                                     in
                                     relabel_func_prefix prefix
                                       (Cfg.rebuild_edges { f with entry = header; blocks })
                                   in
                                   let outer_limit_body, outer_limit_rhs =
                                     materialize_limit_operand outer_limit
                                   in
                                   let prefix_limit_body, prefix_limit_rhs =
                                     materialize_limit_operand prefix_limit
                                   in
                                   let before_func =
                                     clone_loop "split_pre" (Tcg.Temp pre_limit_temp) before_bridge_label
                                       (fun first_branch _second_branch ->
                                         ([], Cfg.Jump first_branch))
                                   in
                                   let after_func =
                                     clone_loop "split_post" outer_limit_rhs info.exit_label
                                       (fun _first_branch second_branch ->
                                         ([], Cfg.Jump second_branch))
                                   in
                                   let entry_dispatch_body, entry_dispatch_term =
                                     build_branch_for_limit
                                       header_term_for_limit
                                       info.control_iv.phi_temp
                                       outer_limit
                                       split_dispatch_label
                                       info.exit_label
                                   in
                                   let split_dispatch_body, split_dispatch_term =
                                     if first_uses_true then
                                       build_branch_for_shifted_compare
                                         split_op
                                         info.control_iv.phi_temp
                                         split_operand
                                         split_bias
                                         limit_dispatch_label
                                         after_func.entry
                                     else
                                       build_branch_for_shifted_compare
                                         split_op
                                         info.control_iv.phi_temp
                                         split_operand
                                         split_bias
                                         after_func.entry
                                         limit_dispatch_label
                                   in
                                   let limit_choose_body =
                                     outer_limit_body @ prefix_limit_body
                                   in
                                   let limit_choose_term =
                                     if loop_counts_up info.kind then
                                       Cfg.BranchCompare
                                         (Lt, outer_limit_rhs, prefix_limit_rhs, limit_take_outer_label, limit_take_prefix_label)
                                     else
                                       Cfg.BranchCompare
                                         (Gt, outer_limit_rhs, prefix_limit_rhs, limit_take_outer_label, limit_take_prefix_label)
                                   in
                                   let entry_dispatch_block =
                                     {
                                       Cfg.label = entry_dispatch_label;
                                       body = entry_dispatch_body;
                                       term = entry_dispatch_term;
                                       preds = [];
                                       succs = Cfg.successors entry_dispatch_term;
                                     }
                                   in
                                   let split_dispatch_block =
                                     {
                                       Cfg.label = split_dispatch_label;
                                       body = split_dispatch_body;
                                       term = split_dispatch_term;
                                       preds = [];
                                       succs = Cfg.successors split_dispatch_term;
                                     }
                                   in
                                   let limit_dispatch_block =
                                     {
                                       Cfg.label = limit_dispatch_label;
                                       body = limit_choose_body;
                                       term = limit_choose_term;
                                       preds = [];
                                       succs = Cfg.successors limit_choose_term;
                                     }
                                   in
                                   let limit_take_outer_block =
                                     {
                                       Cfg.label = limit_take_outer_label;
                                       body = [ Tcg.Move (pre_limit_temp, outer_limit_rhs) ];
                                       term = Cfg.Jump before_func.entry;
                                       preds = [];
                                       succs = [ before_func.entry ];
                                     }
                                   in
                                   let limit_take_prefix_block =
                                     {
                                       Cfg.label = limit_take_prefix_label;
                                       body = [ Tcg.Move (pre_limit_temp, prefix_limit_rhs) ];
                                       term = Cfg.Jump before_func.entry;
                                       preds = [];
                                       succs = [ before_func.entry ];
                                     }
                                   in
                                   let bridge_block =
                                     {
                                       Cfg.label = before_bridge_label;
                                       body = [];
                                       term = Cfg.Jump after_func.entry;
                                       preds = [];
                                       succs = [ after_func.entry ];
                                     }
                                   in
                                   let outside_preds =
                                     List.filter (fun pred -> not (LabelSet.mem pred loop)) header_block.preds
                                   in
                                   let redirects = Hashtbl.create (List.length outside_preds) in
                                   List.iter
                                     (fun pred ->
                                       Hashtbl.add redirects (pred, header) entry_dispatch_label)
                                     outside_preds;
                                   let base_blocks =
                                     f.blocks
                                     |> List.filter (fun (block : Cfg.block) ->
                                            not (LabelSet.mem block.label loop))
                                     |> List.map (fun (block : Cfg.block) ->
                                            if
                                              List.exists
                                                (fun pred -> pred = block.label)
                                                outside_preds
                                            then
                                              let term =
                                                redirect_successors block.label redirects block.term
                                              in
                                              { block with term; succs = Cfg.successors term }
                                            else block)
                                   in
                                   let entry =
                                     if header = f.entry then entry_dispatch_label else f.entry
                                   in
                                   if Sys.getenv_opt "TOYC_DEBUG_DIAMOND_SPLIT" <> None then
                                     Printf.eprintf
                                       "diamond-split func=%s header=%s pre=%s post=%s limit=%s bridge=%s\n%!"
                                       f.name header before_func.entry after_func.entry
                                       limit_dispatch_label before_bridge_label;
                                   let blocks =
                                     base_blocks
                                     @ [
                                         entry_dispatch_block;
                                         split_dispatch_block;
                                         limit_dispatch_block;
                                         limit_take_outer_block;
                                         limit_take_prefix_block;
                                         bridge_block;
                                       ]
                                     @ before_func.blocks @ after_func.blocks
                                   in
                                   let _ = join_label in
                                   raise
                                     (Applied
                                        (Cfg.rebuild_edges
                                           {
                                             f with
                                             entry;
                                             temp_count = !next_temp;
                                             blocks;
                                           }))
                                 | Some _ | None -> ()
                               end
                           | None -> ())
                       | _ -> ())
                | Some _ | None -> ())
        headers;
      f
    with
    | Applied next -> next

(* -------------------------------------------------------------------------- *)
(* step112 fix6: late equivalent-diamond folding                              *)
(* -------------------------------------------------------------------------- *)

(* Strength reduction can lower operation latency without reducing the number
   of dynamically executed TCG/RISC-V instructions.  The benchmark harness is
   heavily instruction-count-sensitive, so remove redundant control flow when
   both branch arms have become literally equivalent after late algebra,
   mem2reg and copy coalescing.

   This pass is intentionally conservative:
     - only immediate two-arm diamonds;
     - both arm blocks must have byte-for-byte equal TCG bodies;
     - both arms must be unconditional jumps to the same join.

   Because ToyC PHIs have already been lowered to edge Moves, equality of the
   arm bodies also includes equality of any edge-copy state updates.  Choosing
   either arm is therefore semantics-preserving. *)
let fold_late_equivalent_diamonds_func (f : Cfg.func) =
  let debug = Sys.getenv_opt "TOYC_DEBUG_EQUIV_BRANCH" <> None in
  let bind_temp_pair fwd rev lhs rhs =
    match (IntMap.find_opt lhs fwd, IntMap.find_opt rhs rev) with
    | Some rhs', Some lhs' -> if rhs' = rhs && lhs' = lhs then Some (fwd, rev) else None
    | Some rhs', None ->
        if rhs' = rhs then Some (fwd, IntMap.add rhs lhs rev) else None
    | None, Some lhs' ->
        if lhs' = lhs then Some (IntMap.add lhs rhs fwd, rev) else None
    | None, None ->
        Some (IntMap.add lhs rhs fwd, IntMap.add rhs lhs rev)
  in
  let operand_alpha_equal fwd rev lhs rhs =
    match (lhs, rhs) with
    | Tcg.Imm a, Tcg.Imm b -> a = b
    | Tcg.Temp a, Tcg.Temp b -> (
        match (IntMap.find_opt a fwd, IntMap.find_opt b rev) with
        | Some rhs', Some lhs' -> rhs' = b && lhs' = a
        | Some rhs', None -> rhs' = b
        | None, Some lhs' -> lhs' = a
        | None, None -> a = b)
    | (Tcg.Imm _ | Tcg.Temp _), (Tcg.Imm _ | Tcg.Temp _) -> false
  in
  let scalar_instrs_alpha_equal body_a body_b =
    let rec loop fwd rev xs ys =
      match (xs, ys) with
      | [], [] -> true
      | instr_a :: rest_a, instr_b :: rest_b -> (
          let next_maps =
            match (instr_a, instr_b) with
            | Tcg.Move (dst_a, src_a), Tcg.Move (dst_b, src_b)
            | Tcg.Un (dst_a, UPlus, src_a), Tcg.Un (dst_b, UPlus, src_b)
            | Tcg.Un (dst_a, UMinus, src_a), Tcg.Un (dst_b, UMinus, src_b)
              when operand_alpha_equal fwd rev src_a src_b ->
                bind_temp_pair fwd rev dst_a dst_b
            | Tcg.Bin (dst_a, op_a, lhs_a, rhs_a), Tcg.Bin (dst_b, op_b, lhs_b, rhs_b)
              when op_a = op_b
                   && operand_alpha_equal fwd rev lhs_a lhs_b
                   && operand_alpha_equal fwd rev rhs_a rhs_b ->
                bind_temp_pair fwd rev dst_a dst_b
            | _ ->
                None
          in
          (match next_maps with
           | Some (fwd, rev) -> loop fwd rev rest_a rest_b
           | None -> false))
      | _ -> false
    in
    loop IntMap.empty IntMap.empty body_a body_b
  in
  let rec iterate fuel (current : Cfg.func) =
    if fuel = 0 then current
    else
      let block_map = Hashtbl.create (max 8 (List.length current.blocks)) in
      List.iter
        (fun (block : Cfg.block) ->
          Hashtbl.replace block_map block.label block)
        current.blocks;
      let changed = ref false in
      let blocks =
        List.map
          (fun (block : Cfg.block) ->
            let targets =
              match block.term with
              | Cfg.BranchZero (_, a, b)
              | Cfg.BranchNonZero (_, a, b) ->
                  Some (a, b)
              | Cfg.BranchCompare (_, _, _, a, b) ->
                  Some (a, b)
              | Cfg.Jump _ | Cfg.Return _ ->
                  None
            in
            match targets with
            | Some (a, b) when a <> b -> (
                match
                  (Hashtbl.find_opt block_map a, Hashtbl.find_opt block_map b)
                with
                | Some (arm_a : Cfg.block), Some (arm_b : Cfg.block) -> (
                    match (arm_a.term, arm_b.term) with
                    | Cfg.Jump join_a, Cfg.Jump join_b
                      when join_a = join_b
                           && scalar_instrs_alpha_equal arm_a.body arm_b.body ->
                         changed := true;
                         if debug then
                           Printf.eprintf
                             "equiv-branch-fold func=%s branch=%s arms=%s,%s join=%s body-instrs=%d\n%!"
                            current.name block.label a b join_a
                            (List.length arm_a.body);
                        let term = Cfg.Jump a in
                        { block with term; succs = Cfg.successors term }
                    | _ -> block)
                | _ -> block)
            | Some _ | None -> block)
          current.blocks
      in
      if not !changed then current
      else
        let rebuilt = Cfg.rebuild_edges { current with blocks } in
        let cleaned = thread_and_prune_func rebuilt in
        if cleaned = current then current
        else iterate (fuel - 1) cleaned
  in
  iterate 8 f

(* -------------------------------------------------------------------------- *)
(* step112 fix7: runtime symbolic affine-loop summary                         *)
(* -------------------------------------------------------------------------- *)

(* Late LVE strength reduction can leave the canonical runtime loop:

       acc     = acc + derived
       iv      = iv + step
       derived = derived + delta
       if (iv < bound) goto loop

   where [step], [bound] and [delta] are all runtime loop-invariant values.

   Replacing MUL by ADD does not reduce dynamic instruction count.  For this
   very small side-effect-free shape, summarize the arithmetic progression at
   runtime instead:

       trip = ceil(bound / step)          (the first-entry iv is proven zero)
       acc += trip * derived
              + C(trip, 2) * delta

   Correctness is guarded:
     - the original zero-trip test remains in place;
     - only step > 0 takes the summary path;
     - require trip*step <= INT32_MAX, otherwise fall back to the original
       loop so signed-IV wraparound behaviour is preserved.

   The original loop is deliberately retained as a fallback.  This makes the
   transform profitable for ordinary positive runtime steps without changing
   zero/negative-step or overflow-sensitive behaviour. *)
let summarize_runtime_symbolic_affine_loops_func summaries globals (f : Cfg.func) =
  let debug = Sys.getenv_opt "TOYC_DEBUG_LVE_SUMMARY" <> None in
  let _block_map, loops, headers = discover_natural_loops f in
  if headers = [] then f
  else
    let current_blocks = Hashtbl.create (List.length f.blocks + (3 * List.length headers)) in
    List.iter
      (fun (block : Cfg.block) -> Hashtbl.replace current_blocks block.label block)
      f.blocks;
    let get_block = get_block_exn current_blocks in
    let update_block (block : Cfg.block) =
      Hashtbl.replace current_blocks block.label block
    in
    let doms = compute_dominators f in
    let live_in_t, _ = compute_liveness summaries globals f in
    let operand_available_at_preheader def_blocks multi_defs preheader_label operand =
      lve_operand_available_before_preds
        doms def_blocks multi_defs
        [ preheader_label ] operand
    in
    let next_temp = ref f.temp_count in
    let fresh_temp () =
      let temp = !next_temp in
      incr next_temp;
      temp
    in
    let next_id = ref 0 in
    let fresh_label suffix =
      let id = !next_id in
      incr next_id;
      Printf.sprintf ".L%s_lve_summary_%d_%s" f.label id suffix
    in
    let reject header reason =
      if debug then
        Printf.eprintf
          "lve-runtime-summary-reject func=%s header=%s reason=%s\n%!"
          f.name header reason
    in
    let string_of_binop = function
      | Add -> "add"
      | Sub -> "sub"
      | Mul -> "mul"
      | Div -> "div"
      | Mod -> "mod"
      | Lt -> "lt"
      | Le -> "le"
      | Gt -> "gt"
      | Ge -> "ge"
      | Eq -> "eq"
      | Ne -> "ne"
      | LAnd -> "land"
      | LOr -> "lor"
    in
    let string_of_unop = function
      | UMinus -> "uminus"
      | UNot -> "unot"
      | UPlus -> "uplus"
    in
    let string_of_place = function
      | Tcg.Local id -> Printf.sprintf "local:%d" id
      | Tcg.Global label -> Printf.sprintf "global:%s" label
    in
    let string_of_simple_instr = function
      | Tcg.Move (dst, src) ->
          Printf.sprintf "t%d=move(%s)" dst (string_of_lve_operand src)
      | Tcg.Un (dst, op, src) ->
          Printf.sprintf "t%d=%s(%s)" dst (string_of_unop op) (string_of_lve_operand src)
      | Tcg.Bin (dst, op, lhs, rhs) ->
          Printf.sprintf
            "t%d=%s(%s,%s)" dst (string_of_binop op)
            (string_of_lve_operand lhs)
            (string_of_lve_operand rhs)
      | Tcg.Load (dst, place) ->
          Printf.sprintf "t%d=load(%s)" dst (string_of_place place)
      | Tcg.Store (place, value) ->
          Printf.sprintf "store(%s,%s)"
            (string_of_place place)
            (string_of_lve_operand value)
      | Tcg.Call (dst, name, args) ->
          Printf.sprintf "%s=call(%s;%s)"
            (match dst with
             | None -> "_"
             | Some temp -> Printf.sprintf "t%d" temp)
            name
            (String.concat "," (List.map string_of_lve_operand args))
    in
    let reaching_seed_on_edge ~header ~pred_label temp =
      match
        reaching_move_cases_on_edge
          get_block ~stop_label:header ~pred_label temp
      with
      | None -> None
      | Some cases ->
          let values =
            cases
            |> dedup_reaching_move_cases
            |> List.map (fun case ->
                   resolve_chain_operand
                     case.reaching_chain case.reaching_source)
          in
          (match values with
           | [] -> None
           | first :: rest
             when List.for_all (fun value -> value = first) rest ->
               Some first
           | _ -> None)
    in
    let new_blocks_rev = ref [] in
    let changed = ref false in

    let self_add = function
      | Tcg.Bin (dst, Add, Tcg.Temp lhs, rhs) when dst = lhs ->
          Some (dst, rhs)
      | Tcg.Bin (dst, Add, lhs, Tcg.Temp rhs) when dst = rhs ->
          Some (dst, lhs)
      | Tcg.Move _
      | Tcg.Un _
      | Tcg.Bin _
      | Tcg.Load _
      | Tcg.Store _
      | Tcg.Call _ ->
          None
    in

    let branch_continue_lt_in_loop loop term =
      match term with
      | Cfg.BranchCompare (op, lhs, rhs, yes_label, no_label) ->
          let yes_inside = LabelSet.mem yes_label loop in
          let no_inside = LabelSet.mem no_label loop in
          if yes_inside = no_inside then None
          else if yes_inside then
            Some (op, lhs, rhs, yes_label, no_label)
          else
            Some (invert_compare op, lhs, rhs, no_label, yes_label)
      | Cfg.BranchZero _
      | Cfg.BranchNonZero _
      | Cfg.Jump _
      | Cfg.Return _ ->
          None
    in

    let find_runtime_summary_shape loop =
      let loop_blocks =
        LabelSet.elements loop |> List.map get_block
      in
      let control_candidates =
        List.filter_map
          (fun (candidate : Cfg.block) ->
            Option.map
              (fun branch -> (candidate, branch))
              (branch_continue_lt_in_loop loop candidate.term))
          loop_blocks
      in
      match control_candidates with
      | [ (control_block,
           (branch_op, lhs, rhs, continue_label, exit_label)) ] ->
          let rec trace_body_chain visited labels_rev instrs current_label =
            if current_label = control_block.label then
              Some (visited, List.rev labels_rev, instrs)
            else if
              not (LabelSet.mem current_label loop)
              || LabelSet.mem current_label visited
            then
              None
            else
              let block : Cfg.block = get_block current_label in
              match block.term with
              | Cfg.Jump next_label ->
                  trace_body_chain
                    (LabelSet.add current_label visited)
                    (current_label :: labels_rev)
                    (instrs @ block.body)
                    next_label
              | Cfg.BranchZero _
              | Cfg.BranchNonZero _
              | Cfg.BranchCompare _
              | Cfg.Return _ ->
                  None
          in
          let traced =
            if continue_label = control_block.label then
              Some (LabelSet.empty, [], [])
            else
              trace_body_chain
                LabelSet.empty [] [] continue_label
          in
          (match traced with
           | None ->
               Error
                 (Printf.sprintf
                    "body-chain-not-linear continue=%s control=%s"
                    continue_label control_block.label)
           | Some (visited_body, body_labels, prefix_instrs) ->
               let covered =
                 LabelSet.add control_block.label visited_body
               in
               if not (LabelSet.equal covered loop) then
                 Error
                   (Printf.sprintf
                      "body-chain-does-not-cover-loop covered=%d total=%d"
                      (LabelSet.cardinal covered)
                      (LabelSet.cardinal loop))
               else
                 let body_instrs =
                   prefix_instrs @ control_block.body
                 in
                 let self_add_count =
                   List.fold_left
                     (fun count instr ->
                       if Option.is_some (self_add instr)
                       then count + 1
                       else count)
                     0 body_instrs
                 in
                 let self_add_dsts =
                   List.fold_left
                     (fun dsts instr ->
                       match self_add instr with
                       | Some (dst, _) -> IntSet.add dst dsts
                       | None -> dsts)
                     IntSet.empty body_instrs
                 in
                 let pure_affine_control_instr instr =
                   match instr with
                   | Tcg.Move (dst, _)
                   | Tcg.Un (dst, (UPlus | UMinus), _)
                   | Tcg.Bin (dst, (Add | Sub | Mul), _, _) ->
                       not (IntSet.mem dst self_add_dsts)
                   | Tcg.Un (_, UNot, _)
                   | Tcg.Bin
                       (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
                   | Tcg.Load _
                   | Tcg.Store _
                   | Tcg.Call _ ->
                       false
                 in
                  let extra_instrs =
                    List.filter
                      (fun instr -> Option.is_none (self_add instr))
                      body_instrs
                  in
                  let extra_instr_budget = 6 in
                  let nonpure_extra =
                    List.filter
                      (fun instr -> not (pure_affine_control_instr instr))
                      extra_instrs
                  in
                  if
                    self_add_count < 1
                    || self_add_count > 3
                    || List.length extra_instrs > extra_instr_budget
                    || nonpure_extra <> []
                  then
                    let () =
                      if debug && nonpure_extra <> [] then
                        List.iteri
                          (fun index instr ->
                            Printf.eprintf
                              "lve-runtime-summary-nonpure func=%s control=%s index=%d instr=%s\n%!"
                              f.name control_block.label index (string_of_simple_instr instr))
                          nonpure_extra
                    in
                    Error
                      (Printf.sprintf
                         "affine-body-shape blocks=%d instrs=%d self-adds=%d extras=%d budget=%d nonpure=%d"
                         (List.length body_labels
                          + if control_block.body = [] then 0 else 1)
                         (List.length body_instrs)
                         self_add_count
                         (List.length extra_instrs)
                         extra_instr_budget
                         (List.length nonpure_extra))
                 else
                   Ok
                     ( body_instrs,
                       body_labels,
                       control_block,
                       branch_op,
                       lhs,
                       rhs,
                       exit_label ))
      | _ ->
          Error
            (Printf.sprintf
               "control-candidates blocks=%d control=%d"
               (List.length loop_blocks)
               (List.length control_candidates))
    in

    List.iter
      (fun discovered_header ->
        let loop =
          table_find_or_empty
            loops discovered_header LabelSet.empty
        in
        match find_runtime_summary_shape loop with
        | Error reason ->
            reject discovered_header reason
        | Ok
            ( body_instrs,
              body_labels,
              control_block,
              branch_op,
              lhs,
              rhs,
              exit_label ) ->
            (* Keep CFG entry and recurrence/control program point distinct.

               Rotated loops commonly look like:
                 preheader -> body(header) -> control(latch) -> body/exit

               The natural header is the only correct place for preheader,
               reaching-seed and fallback CFG reasoning.  The unique compare
               block is the correct program point for recovering the logical
               AddRec/control expression. *)
            let header =
              discovered_header
            in
            let recurrence_header =
              control_block.label
            in
            (if
               Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED"
               <> None
               && header <> recurrence_header
             then
               Printf.eprintf
                 "symbolic-trip-domain-control-point domain=%s control-point=%s\n%!"
                 header recurrence_header;
             if debug then
                Printf.eprintf
                  "lve-runtime-summary-shape func=%s header=%s blocks=%d body-blocks=%d control=%s body-instrs=%d path={%s}\n%!"
                  f.name header
                  (LabelSet.cardinal loop)
                  (List.length body_labels)
                  control_block.label
                  (List.length body_instrs)
                  (String.concat "," body_labels);
              if debug then
                List.iteri
                  (fun index instr ->
                    Printf.eprintf
                      "lve-runtime-summary-body func=%s header=%s index=%d instr=%s\n%!"
                      f.name header index (string_of_simple_instr instr))
                  body_instrs);
            let header_block : Cfg.block = get_block header in
            let outside_preds =
              List.filter
                (fun pred -> not (LabelSet.mem pred loop))
                header_block.preds
            in
            match outside_preds with
            | [ preheader_label ] -> (
                let preheader : Cfg.block = get_block preheader_label in
                let current_blocks_snapshot =
                  Hashtbl.fold
                    (fun _ (block : Cfg.block) acc ->
                      block :: acc)
                    current_blocks
                    []
                in
                let loop_defs, def_blocks, def_instrs, multi_defs =
                  analyze_temp_defs_of_blocks
                    ~loop f.temp_count current_blocks_snapshot
                in
                let base_runtime_recurrence_analysis =
                  build_loop_recurrence_analysis
                    header loop get_block
                    loop_defs multi_defs def_instrs
                in
                let rotated_direct_addrecs =
                  let existing_temps =
                    List.fold_left
                      (fun temps (addrec : loop_addrec) ->
                        IntSet.add
                          addrec.addrec_phi_temp temps)
                      IntSet.empty
                      base_runtime_recurrence_analysis
                        .loop_recurrence_addrecs
                  in
                  let internal_preds =
                    header_block.preds
                    |> List.filter
                         (fun pred ->
                           LabelSet.mem pred loop)
                  in
                  let step_of_direct_update = function
                    | Tcg.Bin
                        ( dst,
                          Add,
                          Tcg.Temp lhs,
                          rhs )
                      when dst = lhs ->
                        Option.map
                          normalize_loop_inv_expr
                          (lve_invariant_expr_of_operand
                             loop_defs multi_defs
                             def_instrs rhs)
                    | Tcg.Bin
                        ( dst,
                          Add,
                          lhs,
                          Tcg.Temp rhs )
                      when dst = rhs ->
                        Option.map
                          normalize_loop_inv_expr
                          (lve_invariant_expr_of_operand
                             loop_defs multi_defs
                             def_instrs lhs)
                    | Tcg.Bin
                        ( dst,
                          Sub,
                          Tcg.Temp lhs,
                          rhs )
                      when dst = lhs ->
                        Option.map
                          (fun step ->
                            normalize_loop_inv_expr
                              (LveNeg step))
                          (lve_invariant_expr_of_operand
                             loop_defs multi_defs
                             def_instrs rhs)
                    | Tcg.Move _
                    | Tcg.Un _
                    | Tcg.Bin _
                    | Tcg.Load _
                    | Tcg.Store _
                    | Tcg.Call _ ->
                        None
                  in
                  let candidates =
                    body_instrs
                    |> List.filter_map
                         (fun instr ->
                           match defs_temp instr with
                           | Some dst
                             when
                               not
                                 (IntSet.mem
                                    dst existing_temps) ->
                               Option.map
                                 (fun step ->
                                   (dst, step))
                                 (step_of_direct_update
                                    instr)
                           | Some _
                           | None ->
                               None)
                  in
                  let grouped =
                    List.fold_left
                      (fun table (dst, step) ->
                        let old =
                          Option.value
                            ~default:[]
                            (IntMap.find_opt dst table)
                        in
                        IntMap.add
                          dst (step :: old) table)
                      IntMap.empty
                      candidates
                  in
                  IntMap.bindings grouped
                  |> List.filter_map
                       (fun (dst, steps) ->
                         match steps with
                         | [ step ]
                           when internal_preds <> [] ->
                             let addrec =
                               {
                                 addrec_phi_temp = dst;
                                 addrec_outside_inputs =
                                   [ ( preheader_label,
                                       Tcg.Temp dst ) ];
                                 addrec_backedge_preds =
                                   internal_preds;
                                 addrec_step = step;
                               }
                             in
                             if
                               Sys.getenv_opt
                                 "TOYC_DEBUG_SCEV_UNIFIED"
                               <> None
                             then
                               Printf.eprintf
                                 "scev-rotated-addrec header=%s control-point=%s phi=t%d step=%s backedges=%d\n%!"
                                 header
                                 recurrence_header
                                 dst
                                 (string_of_loop_inv_expr
                                    step)
                                 (List.length
                                    internal_preds);
                             Some addrec
                         | [ _ ]
                         | []
                         | _ :: _ :: _ ->
                             None)
                in
                let runtime_recurrence_analysis =
                  if rotated_direct_addrecs = [] then
                    base_runtime_recurrence_analysis
                  else
                    let combined_addrecs =
                      base_runtime_recurrence_analysis
                        .loop_recurrence_addrecs
                      @ rotated_direct_addrecs
                    in
                    {
                      base_runtime_recurrence_analysis
                      with
                      loop_recurrence_addrecs =
                        combined_addrecs;
                      loop_recurrence_facts =
                        build_recurrence_facts
                          header loop get_block
                          loop_defs multi_defs
                          def_instrs
                          combined_addrecs;
                    }
                in
                let runtime_control_candidate =
                  find_recurrence_loop_control_candidate
                    runtime_recurrence_analysis.loop_recurrence_facts
                    multi_defs def_instrs
                in
                (if
                   Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED"
                   <> None
                 then
                   Printf.eprintf
                     "symbolic-trip-recurrence-domain header=%s control-point=%s addrecs=%d rotated=%d\n%!"
                     header recurrence_header
                     (List.length
                        runtime_recurrence_analysis
                          .loop_recurrence_addrecs)
                     (List.length rotated_direct_addrecs));
                (if
                   Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED"
                   <> None
                 then
                   List.iter
                     (fun (addrec : loop_addrec) ->
                       Printf.eprintf
                         "scev-rotated-phase header=%s control-point=%s phi=t%d entry=%s control-exit=%s\n%!"
                         header recurrence_header
                         addrec.addrec_phi_temp
                         (string_of_recurrence_phase_state
                            (recurrence_phase_at
                               runtime_recurrence_analysis
                                 .loop_recurrence_facts
                               addrec
                               (RecurrenceBlockEntry
                                  header)))
                         (string_of_recurrence_phase_state
                            (recurrence_phase_at
                               runtime_recurrence_analysis
                                 .loop_recurrence_facts
                               addrec
                               (RecurrenceBlockExit
                                  recurrence_header))))
                     rotated_direct_addrecs);
                (if
                   Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED"
                   <> None
                 then
                   match runtime_control_candidate with
                   | Some candidate ->
                       Printf.eprintf
                         "symbolic-trip-domain-control-hit domain=%s control-point=%s control=%s phi=t%d step=%s scale=%s bias=%s bound=%s\n%!"
                         header recurrence_header
                         candidate.recurrence_control_label
                         candidate.recurrence_control_base.addrec_phi_temp
                         (string_of_loop_inv_expr
                            candidate.recurrence_control_base.addrec_step)
                         (string_of_loop_inv_expr
                            candidate.recurrence_control_scale)
                         (string_of_loop_inv_expr
                            candidate.recurrence_control_bias)
                         (string_of_loop_inv_expr
                            candidate.recurrence_control_bound_expr)
                   | None ->
                       Printf.eprintf
                         "symbolic-trip-domain-control-miss domain=%s control-point=%s\n%!"
                         header recurrence_header);
                let effects =
                  collect_loop_effects summaries globals loop f.blocks
                in
                if
                  effects.has_call
                  || not (PlaceSet.is_empty effects.modified_places)
                then
                  reject header
                    (Printf.sprintf
                       "effects call=%b modified=%d"
                       effects.has_call
                       (PlaceSet.cardinal effects.modified_places))
                else
                  let self_adds =
                    body_instrs
                    |> List.mapi (fun index instr ->
                           Option.map
                             (fun (dst, other) -> (index, dst, other))
                             (self_add instr))
                    |> List.filter_map Fun.id
                  in
                  if
                    List.length self_adds < 1
                    || List.length self_adds > 3
                  then
                    reject header
                      (Printf.sprintf
                         "self-add-count=%d"
                         (List.length self_adds))
                  else
                    let body_indexed =
                      List.mapi (fun index instr -> (index, instr)) body_instrs
                    in
                    let body_program_points =
                      let points_of_label label =
                        let block : Cfg.block =
                          get_block label
                        in
                        List.mapi
                          (fun index _ ->
                            RecurrenceBeforeInstr
                              (label, index))
                          block.body
                      in
                      (body_labels
                       |> List.concat_map points_of_label)
                      @
                      (List.mapi
                         (fun index _ ->
                           RecurrenceBeforeInstr
                             (control_block.label, index))
                         control_block.body)
                    in
                    let recurrence_point_of_body_index index =
                      List.nth_opt body_program_points index
                    in
                    if
                      debug
                      && List.length body_program_points
                         <> List.length body_instrs
                    then
                      Printf.eprintf
                        "lve-runtime-point-map-mismatch func=%s header=%s points=%d instrs=%d\n%!"
                        f.name header
                        (List.length body_program_points)
                        (List.length body_instrs);
                    let last_body_def_before use_index temp =
                      let found = ref None in
                      List.iteri
                        (fun index instr ->
                          if index < use_index then
                            match defs_temp instr with
                            | Some dst when dst = temp ->
                                found := Some (index, instr)
                            | Some _ | None -> ())
                        body_instrs;
                      !found
                    in
                    let last_body_def temp =
                      body_indexed
                      |> List.rev
                      |> List.find_map (fun (index, instr) ->
                             match defs_temp instr with
                             | Some dst when dst = temp -> Some (index, instr)
                             | Some _ | None -> None)
                    in
                    let invariant_expr operand =
                      lve_invariant_expr_of_operand
                        loop_defs multi_defs def_instrs operand
                      |> Option.map normalize_loop_inv_expr
                    in
                    let affine_add_invariant (scale, bias) invariant =
                      Some
                        ( normalize_loop_inv_expr scale,
                          normalize_loop_inv_expr
                            (LveAdd (bias, invariant)) )
                    in
                    let affine_sub_invariant (scale, bias) invariant =
                      Some
                        ( normalize_loop_inv_expr scale,
                          normalize_loop_inv_expr
                            (LveAdd (bias, LveNeg invariant)) )
                    in
                    let affine_mul_invariant (scale, bias) invariant =
                      Some
                        ( normalize_loop_inv_expr
                            (LveMul (scale, invariant)),
                          normalize_loop_inv_expr
                            (LveMul (bias, invariant)) )
                    in
                    let affine_invariant_minus invariant (scale, bias) =
                      Some
                        ( normalize_loop_inv_expr
                            (LveNeg scale),
                          normalize_loop_inv_expr
                            (LveAdd (invariant, LveNeg bias)) )
                    in
                    let scev_debug =
                      Sys.getenv_opt "TOYC_DEBUG_SCEV_UNIFIED"
                      <> None
                    in
                    let rec preupdate_affine_of_operand
                        iv_temp use_index seen operand =
                      match operand with
                      | Tcg.Temp temp when temp = iv_temp ->
                          Some (LveConst 1L, LveConst 0L)
                      | Tcg.Imm value ->
                          Some (LveConst 0L, LveConst value)
                      | Tcg.Temp temp as operand -> (
                          match invariant_expr operand with
                          | Some invariant ->
                              Some (LveConst 0L, invariant)
                          | None ->
                              if IntSet.mem temp seen then None
                              else
                                match last_body_def_before use_index temp with
                                | Some (def_index, instr) ->
                                    preupdate_affine_of_instr
                                      iv_temp def_index
                                      (IntSet.add temp seen) instr
                                | None -> None)
                    and preupdate_affine_of_instr
                        iv_temp def_index seen = function
                      | Tcg.Move (_, src)
                      | Tcg.Un (_, UPlus, src) ->
                          preupdate_affine_of_operand
                            iv_temp def_index seen src
                      | Tcg.Un (_, UMinus, src) ->
                          Option.map
                            (fun (scale, bias) ->
                              ( normalize_loop_inv_expr (LveNeg scale),
                                normalize_loop_inv_expr (LveNeg bias) ))
                            (preupdate_affine_of_operand
                               iv_temp def_index seen src)
                      | Tcg.Bin (_, Add, lhs, rhs) -> (
                          match
                            ( preupdate_affine_of_operand
                                iv_temp def_index seen lhs,
                              preupdate_affine_of_operand
                                iv_temp def_index seen rhs )
                          with
                          | Some (lhs_scale, lhs_bias), Some (rhs_scale, rhs_bias) ->
                              Some
                                ( normalize_loop_inv_expr
                                    (LveAdd (lhs_scale, rhs_scale)),
                                  normalize_loop_inv_expr
                                    (LveAdd (lhs_bias, rhs_bias)) )
                          | _ -> None)
                      | Tcg.Bin (_, Sub, lhs, rhs) -> (
                          match
                            ( preupdate_affine_of_operand
                                iv_temp def_index seen lhs,
                              preupdate_affine_of_operand
                                iv_temp def_index seen rhs )
                          with
                          | Some (lhs_scale, lhs_bias), Some (rhs_scale, rhs_bias) ->
                              Some
                                ( normalize_loop_inv_expr
                                    (LveAdd (lhs_scale, LveNeg rhs_scale)),
                                  normalize_loop_inv_expr
                                    (LveAdd (lhs_bias, LveNeg rhs_bias)) )
                          | _ -> None)
                      | Tcg.Bin (_, Mul, lhs, rhs) -> (
                          match
                            ( preupdate_affine_of_operand
                                iv_temp def_index seen lhs,
                              preupdate_affine_of_operand
                                iv_temp def_index seen rhs )
                          with
                          | Some (lhs_scale, lhs_bias), Some (rhs_scale, rhs_bias)
                            when normalize_loop_inv_expr lhs_scale = LveConst 0L ->
                              Some
                                ( normalize_loop_inv_expr
                                    (LveMul (rhs_scale, lhs_bias)),
                                  normalize_loop_inv_expr
                                    (LveMul (rhs_bias, lhs_bias)) )
                          | Some (lhs_scale, lhs_bias), Some (rhs_scale, rhs_bias)
                            when normalize_loop_inv_expr rhs_scale = LveConst 0L ->
                              Some
                                ( normalize_loop_inv_expr
                                    (LveMul (lhs_scale, rhs_bias)),
                                  normalize_loop_inv_expr
                                    (LveMul (lhs_bias, rhs_bias)) )
                          | _ -> None)
                      | Tcg.Un (_, UNot, _)
                      | Tcg.Bin
                          (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
                      | Tcg.Load _
                      | Tcg.Store _
                      | Tcg.Call _ ->
                          None
                    in
                    let rec control_affine_of_operand
                        iv_temp iv_update_index seen operand =
                      match operand with
                      | Tcg.Temp temp when temp = iv_temp ->
                          Some (LveConst 1L, LveConst 0L)
                      | Tcg.Imm _ ->
                          None
                      | Tcg.Temp temp ->
                          if IntSet.mem temp seen then None
                          else
                            match last_body_def temp with
                            | Some (def_index, instr)
                              when def_index > iv_update_index ->
                                control_affine_of_instr
                                  iv_temp iv_update_index
                                  (IntSet.add temp seen) instr
                            | Some (def_index, instr) ->
                                preupdate_affine_of_instr
                                  iv_temp def_index
                                  (IntSet.add temp seen) instr
                            | None ->
                                None
                    and control_affine_of_instr
                        iv_temp iv_update_index seen = function
                      | Tcg.Move (_, src)
                      | Tcg.Un (_, UPlus, src) ->
                          control_affine_of_operand
                            iv_temp iv_update_index seen src
                      | Tcg.Un (_, UMinus, src) ->
                          Option.bind
                            (control_affine_of_operand
                               iv_temp iv_update_index seen src)
                            (fun (scale, bias) ->
                              Some
                                ( normalize_loop_inv_expr
                                    (LveNeg scale),
                                  normalize_loop_inv_expr
                                    (LveNeg bias) ))
                      | Tcg.Bin (_, Add, lhs, rhs) -> (
                          match
                            ( control_affine_of_operand
                                iv_temp iv_update_index seen lhs,
                              control_affine_of_operand
                                iv_temp iv_update_index seen rhs,
                              invariant_expr lhs,
                              invariant_expr rhs )
                          with
                          | Some affine, None, _, Some invariant
                          | None, Some affine, Some invariant, _ ->
                              affine_add_invariant affine invariant
                          | _ -> None)
                      | Tcg.Bin (_, Sub, lhs, rhs) -> (
                          match
                            ( control_affine_of_operand
                                iv_temp iv_update_index seen lhs,
                              control_affine_of_operand
                                iv_temp iv_update_index seen rhs,
                              invariant_expr lhs,
                              invariant_expr rhs )
                          with
                          | Some affine, None, _, Some invariant ->
                              affine_sub_invariant affine invariant
                          | None, Some affine, Some invariant, _ ->
                              affine_invariant_minus invariant affine
                          | _ -> None)
                      | Tcg.Bin (_, Mul, lhs, rhs) -> (
                          match
                            ( control_affine_of_operand
                                iv_temp iv_update_index seen lhs,
                              control_affine_of_operand
                                iv_temp iv_update_index seen rhs,
                              invariant_expr lhs,
                              invariant_expr rhs )
                          with
                          | Some affine, None, _, Some invariant
                          | None, Some affine, Some invariant, _ ->
                              affine_mul_invariant affine invariant
                          | _ -> None)
                      | Tcg.Un (_, UNot, _)
                      | Tcg.Bin
                          (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
                      | Tcg.Load _
                      | Tcg.Store _
                      | Tcg.Call _ ->
                          None
                    in
                    let rec control_update_affine_of_operand
                        iv_temp use_index seen operand =
                      match operand with
                      | Tcg.Temp temp when temp = iv_temp ->
                          Some (LveConst 1L, LveConst 0L)
                      | Tcg.Imm value ->
                          Some (LveConst 0L, LveConst value)
                      | Tcg.Temp temp as operand -> (
                          match
                            lve_invariant_expr_of_operand
                              loop_defs multi_defs def_instrs operand
                          with
                          | Some invariant ->
                              Some (LveConst 0L, normalize_loop_inv_expr invariant)
                          | None ->
                              if IntSet.mem temp seen then None
                              else
                                match last_body_def_before use_index temp with
                                | Some (def_index, instr) ->
                                    control_update_affine_of_instr
                                      iv_temp def_index
                                      (IntSet.add temp seen) instr
                                | None -> None)
                    and control_update_affine_of_instr
                        iv_temp def_index seen = function
                      | Tcg.Move (_, src)
                      | Tcg.Un (_, UPlus, src) ->
                          control_update_affine_of_operand
                            iv_temp def_index seen src
                      | Tcg.Un (_, UMinus, src) ->
                          Option.map
                            (fun (scale, bias) ->
                              ( normalize_loop_inv_expr (LveNeg scale),
                                normalize_loop_inv_expr (LveNeg bias) ))
                            (control_update_affine_of_operand
                               iv_temp def_index seen src)
                      | Tcg.Bin (_, Add, lhs, rhs) -> (
                          match
                            ( control_update_affine_of_operand
                                iv_temp def_index seen lhs,
                              control_update_affine_of_operand
                                iv_temp def_index seen rhs )
                          with
                          | Some (lhs_scale, lhs_bias), Some (rhs_scale, rhs_bias) ->
                              Some
                                ( normalize_loop_inv_expr
                                    (LveAdd (lhs_scale, rhs_scale)),
                                  normalize_loop_inv_expr
                                    (LveAdd (lhs_bias, rhs_bias)) )
                          | _ -> None)
                      | Tcg.Bin (_, Sub, lhs, rhs) -> (
                          match
                            ( control_update_affine_of_operand
                                iv_temp def_index seen lhs,
                              control_update_affine_of_operand
                                iv_temp def_index seen rhs )
                          with
                          | Some (lhs_scale, lhs_bias), Some (rhs_scale, rhs_bias) ->
                              Some
                                ( normalize_loop_inv_expr
                                    (LveAdd (lhs_scale, LveNeg rhs_scale)),
                                  normalize_loop_inv_expr
                                    (LveAdd (lhs_bias, LveNeg rhs_bias)) )
                          | _ -> None)
                      | Tcg.Bin (_, Mul, lhs, rhs) -> (
                          match
                            ( control_update_affine_of_operand
                                iv_temp def_index seen lhs,
                              control_update_affine_of_operand
                                iv_temp def_index seen rhs )
                          with
                          | Some (lhs_scale, lhs_bias), Some (rhs_scale, rhs_bias)
                            when normalize_loop_inv_expr lhs_scale = LveConst 0L ->
                              Some
                                ( normalize_loop_inv_expr
                                    (LveMul (rhs_scale, lhs_bias)),
                                  normalize_loop_inv_expr
                                    (LveMul (rhs_bias, lhs_bias)) )
                          | Some (lhs_scale, lhs_bias), Some (rhs_scale, rhs_bias)
                            when normalize_loop_inv_expr rhs_scale = LveConst 0L ->
                              Some
                                ( normalize_loop_inv_expr
                                    (LveMul (lhs_scale, rhs_bias)),
                                  normalize_loop_inv_expr
                                    (LveMul (lhs_bias, rhs_bias)) )
                          | _ -> None)
                      | Tcg.Un (_, UNot, _)
                      | Tcg.Bin
                          (_, (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne | LAnd | LOr), _, _)
                      | Tcg.Load _
                      | Tcg.Store _
                      | Tcg.Call _ ->
                          None
                    in
                    let find_control_update () =
                      List.find_map
                        (fun (update_index, instr) ->
                          match defs_temp instr with
                          | None -> None
                          | Some dst ->
                              let update_step =
                                Option.bind
                                  (control_update_affine_of_instr
                                     dst update_index IntSet.empty instr)
                                  (fun (update_scale, update_bias) ->
                                    if
                                      loop_inv_expr_equal
                                        (normalize_loop_inv_expr update_scale)
                                        scalar_inv_one
                                    then
                                      Some
                                        (normalize_loop_inv_expr
                                           update_bias)
                                    else
                                      None)
                              in
                          let lhs_affine =
                            control_affine_of_operand
                              dst update_index IntSet.empty lhs
                          in
                          let rhs_affine =
                            control_affine_of_operand
                              dst update_index IntSet.empty rhs
                          in
                          let lhs_invariant =
                            Option.is_some
                              (lve_invariant_expr_of_operand
                                 loop_defs multi_defs def_instrs lhs)
                          in
                          let rhs_invariant =
                            Option.is_some
                              (lve_invariant_expr_of_operand
                                 loop_defs multi_defs def_instrs rhs)
                          in
                          let normalized =
                            match
                              (lhs_affine, rhs_affine,
                               lhs_invariant, rhs_invariant)
                            with
                            | Some (scale, bias), None, _, true ->
                                Some (branch_op, rhs, scale, bias)
                            | None, Some (scale, bias), true, _ ->
                                Some
                                  (swap_compare branch_op,
                                   lhs, scale, bias)
                            | _ -> None
                          in
                          if debug then
                            Printf.eprintf
                              "lve-runtime-control-update-candidate func=%s header=%s dst=t%d index=%d update-step=%b normalized=%b\n%!"
                              f.name header dst update_index
                              (Option.is_some update_step)
                              (Option.is_some normalized);
                          match (normalized, update_step) with
                          | ( Some
                                (normalized_op, bound_operand,
                                 control_scale, control_bias),
                              Some step_expr )
                            when normalized_op = Lt ->
                              let control_scale =
                                normalize_loop_inv_expr control_scale
                              in
                              let control_bias =
                                normalize_loop_inv_expr control_bias
                              in
                              if debug then
                                Printf.eprintf
                                  "lve-runtime-control-affine func=%s header=%s control=%s iv=t%d scale=%s bias=%s step=%s bound=%s\n%!"
                                  f.name header control_block.label dst
                                  (string_of_loop_inv_expr control_scale)
                                  (string_of_loop_inv_expr control_bias)
                                  (string_of_loop_inv_expr step_expr)
                                  (string_of_lve_operand bound_operand);
                              Some
                                ( update_index,
                                  dst,
                                  step_expr,
                                  bound_operand,
                                  control_scale,
                                  control_bias )
                          | _ ->
                              None)
                        body_indexed
                    in
                    let find_candidate_physical_update
                        (candidate : recurrence_control_candidate) =
                      let phi_temp =
                        candidate.recurrence_control_base.addrec_phi_temp
                      in
                      let candidate_step =
                        normalize_loop_inv_expr
                          candidate.recurrence_control_base.addrec_step
                      in
                      let matching_updates =
                        body_indexed
                        |> List.filter_map
                             (fun (update_index, instr) ->
                               match defs_temp instr with
                               | Some dst when dst = phi_temp -> (
                                   match
                                     control_update_affine_of_instr
                                       dst update_index
                                       IntSet.empty instr
                                   with
                                   | Some
                                       ( update_scale,
                                         update_bias )
                                     when
                                       loop_inv_expr_equal
                                         (normalize_loop_inv_expr
                                            update_scale)
                                         scalar_inv_one
                                       && loop_inv_expr_equal
                                            (normalize_loop_inv_expr
                                               update_bias)
                                            candidate_step ->
                                       Some
                                         ( update_index,
                                           dst )
                                   | Some _
                                   | None ->
                                       None)
                               | Some _
                               | None ->
                                   None)
                      in
                      match matching_updates with
                      | [ (update_index, dst) ] ->
                          if scev_debug || debug then
                            Printf.eprintf
                              "scev-runtime-control-direct-bind-hit func=%s header=%s control=%s iv=t%d phi=t%d step=%s scale=%s bias=%s bound=%s\n%!"
                              f.name
                              header
                              candidate.recurrence_control_label
                              dst
                              phi_temp
                              (string_of_loop_inv_expr
                                 candidate_step)
                              (string_of_loop_inv_expr
                                 candidate.recurrence_control_scale)
                              (string_of_loop_inv_expr
                                 candidate.recurrence_control_bias)
                              (string_of_loop_inv_expr
                                 candidate.recurrence_control_bound_expr);
                          Some
                            ( update_index,
                              dst,
                              candidate_step,
                              candidate.recurrence_control_bound_operand,
                              normalize_loop_inv_expr
                                candidate.recurrence_control_scale,
                              normalize_loop_inv_expr
                                candidate.recurrence_control_bias )
                      | [] ->
                          if scev_debug then
                            Printf.eprintf
                              "scev-runtime-control-direct-bind-miss header=%s phi=t%d reason=no-matching-update\n%!"
                              header phi_temp;
                          None
                      | matches ->
                          if scev_debug then
                            Printf.eprintf
                              "scev-runtime-control-direct-bind-miss header=%s phi=t%d reason=ambiguous-updates count=%d\n%!"
                              header phi_temp
                              (List.length matches);
                          None
                    in
                    let candidate_control_update =
                      match runtime_control_candidate with
                      | Some candidate
                        when
                          candidate.recurrence_control_op = Lt ->
                          find_candidate_physical_update candidate
                      | Some _
                      | None ->
                          None
                    in
                    let legacy_control_update =
                      find_control_update ()
                    in
                    let unified_control_update =
                      match
                        ( runtime_control_candidate,
                          legacy_control_update )
                      with
                      | Some candidate,
                        Some
                          ( update_index,
                            iv_temp,
                            legacy_step,
                            bound_operand,
                            legacy_scale,
                            legacy_bias )
                        when
                          candidate.recurrence_control_op = Lt ->
                          let candidate_step =
                            normalize_loop_inv_expr
                              candidate
                                .recurrence_control_base
                                .addrec_step
                          in
                          let candidate_scale =
                            normalize_loop_inv_expr
                              candidate
                                .recurrence_control_scale
                          in
                          let candidate_bias =
                            normalize_loop_inv_expr
                              candidate
                                .recurrence_control_bias
                          in
                          let legacy_step =
                            normalize_loop_inv_expr
                              legacy_step
                          in
                          let legacy_scale =
                            normalize_loop_inv_expr
                              legacy_scale
                          in
                          let legacy_bias =
                            normalize_loop_inv_expr
                              legacy_bias
                          in
                          let bound_expr =
                            invariant_expr bound_operand
                          in
                          let step_agree =
                            loop_inv_expr_equal
                              candidate_step legacy_step
                          in
                          let scale_agree =
                            loop_inv_expr_equal
                              candidate_scale legacy_scale
                          in
                          let bias_agree =
                            loop_inv_expr_equal
                              candidate_bias legacy_bias
                          in
                          if
                            scev_debug
                            && not bias_agree
                          then
                            Printf.eprintf
                              "canonical-scalar-bias-disagree header=%s candidate=%s legacy=%s candidate-key=%s legacy-key=%s\n%!"
                              header
                              (string_of_loop_inv_expr
                                 candidate_bias)
                              (string_of_loop_inv_expr
                                 legacy_bias)
                              (string_of_canonical_scalar_key
                                 (loop_inv_linear_key
                                    candidate_bias))
                              (string_of_canonical_scalar_key
                                 (loop_inv_linear_key
                                    legacy_bias));
                          let bound_agree =
                            match bound_expr with
                            | Some expr ->
                                loop_inv_expr_equal
                                  (normalize_loop_inv_expr expr)
                                  (normalize_loop_inv_expr
                                     candidate
                                       .recurrence_control_bound_expr)
                            | None ->
                                false
                          in
                          if
                            step_agree
                            && scale_agree
                            && bias_agree
                            && bound_agree
                          then begin
                            if scev_debug || debug then
                              Printf.eprintf
                                "scev-runtime-control-hit func=%s header=%s control=%s iv=t%d phi=t%d step=%s scale=%s bias=%s bound=%s\n%!"
                                f.name
                                header
                                control_block.label
                                iv_temp
                                candidate
                                  .recurrence_control_base
                                  .addrec_phi_temp
                                (string_of_loop_inv_expr
                                   candidate_step)
                                (string_of_loop_inv_expr
                                   candidate_scale)
                                (string_of_loop_inv_expr
                                   candidate_bias)
                                (string_of_loop_inv_expr
                                   candidate
                                     .recurrence_control_bound_expr);
                            Some
                              ( update_index,
                                iv_temp,
                                candidate_step,
                                bound_operand,
                                candidate_scale,
                                candidate_bias )
                          end
                          else begin
                            if scev_debug then
                              Printf.eprintf
                                "scev-runtime-control-disagree header=%s iv=t%d phi=t%d step=%b scale=%b bias=%b bound=%b\n%!"
                                header
                                iv_temp
                                candidate
                                  .recurrence_control_base
                                  .addrec_phi_temp
                                step_agree
                                scale_agree
                                bias_agree
                                bound_agree;
                            None
                          end
                      | Some candidate, None ->
                          if scev_debug then
                            Printf.eprintf
                              "scev-runtime-control-miss header=%s reason=no-physical-update phi=t%d\n%!"
                              header
                              candidate
                                .recurrence_control_base
                                .addrec_phi_temp;
                          None
                      | None, Some _ ->
                          if scev_debug then
                            Printf.eprintf
                              "scev-runtime-control-miss header=%s reason=no-candidate\n%!"
                              header;
                          None
                      | None, None ->
                          if scev_debug then
                            Printf.eprintf
                              "scev-runtime-control-miss header=%s reason=no-candidate-or-physical-update\n%!"
                              header;
                          None
                      | Some candidate, Some _ ->
                          if scev_debug then
                            Printf.eprintf
                              "scev-runtime-control-miss header=%s reason=unsupported-op op=%s\n%!"
                              header
                              (string_of_recurrence_compare
                                 candidate.recurrence_control_op);
                          None
                    in
                    let control_update, unified_control_agreed =
                      match candidate_control_update with
                      | Some _ as result ->
                          (result, true)
                      | None -> (
                          match unified_control_update with
                          | Some _ as result ->
                              (result, true)
                          | None ->
                              (legacy_control_update, false))
                    in
                    match control_update with
                    | None ->
                        reject header "no-symbolic-affine-lt-control-update"
                    | Some
                        ( iv_update_index,
                          iv_temp,
                          step_expr,
                          bound_operand,
                          control_scale,
                          control_bias ) ->
                        let symbolic_trip_spec =
                          match runtime_control_candidate with
                          | Some candidate
                            when unified_control_agreed ->
                              symbolic_trip_spec_of_candidate
                                runtime_recurrence_analysis.loop_recurrence_facts
                                candidate
                          | Some _
                          | None ->
                              None
                        in
                        let symbolic_trip_family =
                          Option.bind
                            symbolic_trip_spec
                            classify_symbolic_trip_proof_family
                        in
                        (if scev_debug then
                           match symbolic_trip_spec with
                           | Some spec ->
                               Printf.eprintf
                                 "symbolic-trip-runtime-bridge-hit header=%s start=%s step=%s scale=%s bias=%s bound=%s\n%!"
                                 header
                                 (string_of_loop_inv_expr
                                    spec.symbolic_trip_start)
                                 (string_of_loop_inv_expr
                                    spec.symbolic_trip_step)
                                 (string_of_loop_inv_expr
                                    spec.symbolic_trip_scale)
                                 (string_of_loop_inv_expr
                                    spec.symbolic_trip_bias)
                                 (string_of_loop_inv_expr
                                    spec.symbolic_trip_bound)
                           | None ->
                               ());
                        let initial_iv =
                          reaching_seed_on_edge
                            ~header ~pred_label:preheader_label iv_temp
                        in
                        (if debug then
                           Printf.eprintf
                             "lve-runtime-summary-candidate func=%s header=%s iv=t%d scale=%s bias=%s step=%s bound=%s init=%s\n%!"
                             f.name header iv_temp
                             (string_of_loop_inv_expr control_scale)
                             (string_of_loop_inv_expr control_bias)
                             (string_of_loop_inv_expr step_expr)
                             (string_of_lve_operand bound_operand)
                             (match initial_iv with
                              | Some operand -> string_of_lve_operand operand
                              | None -> "<unknown>"));
                        let initial_iv_expr =
                          Option.bind initial_iv invariant_expr
                        in
                        let initial_zero =
                          match initial_iv_expr with
                          | Some expr ->
                              loop_inv_expr_equal
                                (normalize_loop_inv_expr expr)
                                scalar_inv_zero
                          | None ->
                              false
                        in
                        let semantic_start_agrees =
                          match
                            (symbolic_trip_spec, initial_iv_expr)
                          with
                          | Some spec, Some expr ->
                              loop_inv_expr_equal
                                spec.symbolic_trip_start
                                (normalize_loop_inv_expr expr)
                          | Some _, None ->
                              false
                          | None, _ ->
                              initial_zero
                        in
                        if not semantic_start_agrees then
                          reject header
                            "initial-iv-scev-start-mismatch"
                        else
                          let proof_control_start_expr =
                            match symbolic_trip_spec with
                            | Some spec ->
                                symbolic_trip_control_start spec
                            | None ->
                                control_bias
                          in
                          let control_start_available =
                            lve_expr_available_before_preds
                              doms def_blocks multi_defs
                              [ preheader_label ]
                              proof_control_start_expr
                          in
                          let step_available =
                            lve_expr_available_before_preds
                              doms def_blocks multi_defs
                              [ preheader_label ] step_expr
                          in
                          let bound_available =
                            operand_available_at_preheader
                              def_blocks multi_defs preheader_label
                              bound_operand
                          in
                          let scale_available =
                            lve_expr_available_before_preds
                              doms def_blocks multi_defs
                              [ preheader_label ] control_scale
                          in
                          let bias_available =
                            lve_expr_available_before_preds
                              doms def_blocks multi_defs
                              [ preheader_label ] control_bias
                          in
                          if
                            not control_start_available
                            || not step_available
                            || not bound_available
                            || not scale_available
                            || not bias_available
                          then
                            reject header
                              (Printf.sprintf
                                 "operand-unavailable control-start=%b step=%b bound=%b scale=%b bias=%b"
                                 control_start_available
                                 step_available bound_available
                                 scale_available bias_available)
                          else
                            let step_prep, step_operand =
                              match normalize_loop_inv_expr step_expr with
                              | LveConst value ->
                                  ([], Tcg.Imm value)
                              | LveOperand operand ->
                                  ([], operand)
                              | complex ->
                                  let temp = fresh_temp () in
                                  ( emit_loop_inv_expr
                                      fresh_temp temp complex,
                                    Tcg.Temp temp )
                            in
                            (if scev_debug then
                               match symbolic_trip_spec with
                               | Some spec ->
                                   Printf.eprintf
                                     "symbolic-trip-spec header=%s start=%s step=%s scale=%s bias=%s bound=%s control-start=%s effective-step=%s static-trip=%s\n%!"
                                     header
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_start)
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_step)
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_scale)
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_bias)
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_bound)
                                     (string_of_loop_inv_expr
                                        (symbolic_trip_control_start spec))
                                     (string_of_loop_inv_expr
                                        (symbolic_trip_effective_step spec))
                                     (match
                                        exact_trip_count_of_symbolic_spec spec
                                      with
                                      | Some trip ->
                                          Int64.to_string trip
                                      | None ->
                                          "<runtime-proof>")
                               | None ->
                                   ());
                            (if scev_debug then
                               match
                                 ( symbolic_trip_spec,
                                   symbolic_trip_family )
                               with
                               | Some spec, Some family ->
                                   Printf.eprintf
                                     "symbolic-trip-proof-ready header=%s family=%s start=%s step=%s scale=%s bias=%s bound=%s mode=%s\n%!"
                                     header
                                     (string_of_symbolic_trip_proof_family
                                        family)
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_start)
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_step)
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_scale)
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_bias)
                                     (string_of_loop_inv_expr
                                        spec.symbolic_trip_bound)
                                     (match
                                        exact_trip_count_of_symbolic_spec
                                          spec
                                      with
                                      | Some _ ->
                                          "static-exact"
                                      | None ->
                                          "runtime-guarded")
                               | Some _, None
                               | None, _ ->
                                   ());
                            let non_iv =
                              List.filter
                                (fun (_, dst, _) -> dst <> iv_temp)
                                self_adds
                            in

                            (* Phase-aware direct affine reduction analysis.

                               At the start of source iteration k:

                                 iv_pre(k) = k * step

                               A direct reduction operand is normalized to

                                 delta(k) = scale * iv_pre(k) + bias.

                               A bare use of [iv_temp] before its self-add has
                               phase 0.  A bare use after the self-add has
                               phase 1, represented by adding [step_expr] to
                               the bias.  Snapshot temporaries retain the phase
                               of their defining instruction because recursive
                               analysis uses the definition's instruction
                               index, not the final use index.

                               Only Add/Sub/Mul-by-invariant are accepted. *)
                            let affine_add
                                (lhs_scale, lhs_bias)
                                (rhs_scale, rhs_bias) =
                              ( normalize_loop_inv_expr
                                  (LveAdd (lhs_scale, rhs_scale)),
                                normalize_loop_inv_expr
                                  (LveAdd (lhs_bias, rhs_bias)) )
                            in
                            let affine_neg (scale, bias) =
                              ( normalize_loop_inv_expr (LveNeg scale),
                                normalize_loop_inv_expr (LveNeg bias) )
                            in
                            let affine_sub lhs rhs =
                              affine_add lhs (affine_neg rhs)
                            in
                            let affine_mul_invariant
                                (scale, bias) invariant =
                              ( normalize_loop_inv_expr
                                  (LveMul (scale, invariant)),
                                normalize_loop_inv_expr
                                  (LveMul (bias, invariant)) )
                            in
                            let affine_is_invariant (scale, _) =
                              normalize_loop_inv_expr scale = LveConst 0L
                            in
                            let semantic_delta_affine_at
                                use_index operand =
                              match
                                ( runtime_control_candidate,
                                  recurrence_point_of_body_index
                                    use_index )
                              with
                              | Some candidate, Some point
                                when unified_control_agreed -> (
                                  match
                                    recurrence_at
                                      runtime_recurrence_analysis.loop_recurrence_facts
                                      point operand
                                  with
                                  | Some (ScalarConst value) ->
                                      Some
                                        ( LveConst 0L,
                                          LveConst value )
                                  | Some (ScalarInvariant expr) ->
                                      Some
                                        ( LveConst 0L,
                                          normalize_loop_inv_expr
                                            expr )
                                  | Some
                                      ((ScalarAddRec _
                                       | ScalarAffine _)
                                        as recurrence) -> (
                                      match
                                        scalar_recurrence_scale_bias
                                          recurrence
                                      with
                                      | Some
                                          (base, scale, bias)
                                        when
                                          scalar_same_base
                                            base
                                            candidate.recurrence_control_base ->
                                          Some
                                            ( normalize_loop_inv_expr
                                                scale,
                                              normalize_loop_inv_expr
                                                bias )
                                      | Some _ | None ->
                                          None)
                                  | None ->
                                      None)
                              | Some _, None ->
                                  if scev_debug then
                                    Printf.eprintf
                                      "scev-runtime-delta-miss header=%s index=%d operand=%s reason=no-program-point\n%!"
                                      header
                                      use_index
                                      (string_of_lve_operand operand);
                                  None
                              | None, _ ->
                                  if scev_debug then
                                    Printf.eprintf
                                      "scev-runtime-delta-miss header=%s index=%d operand=%s reason=no-control-candidate\n%!"
                                      header
                                      use_index
                                      (string_of_lve_operand operand);
                                  None
                              | Some _, Some _
                                when not unified_control_agreed ->
                                  if scev_debug then
                                    Printf.eprintf
                                      "scev-runtime-delta-miss header=%s index=%d operand=%s reason=control-not-unified\n%!"
                                      header
                                      use_index
                                      (string_of_lve_operand operand);
                                  None
                              | Some _, Some _ ->
                                  None
                            in
                            let rec direct_delta_affine_of_operand
                                use_index seen operand =
                              match
                                semantic_delta_affine_at
                                  use_index operand
                              with
                              | Some (scale, bias) ->
                                  if
                                    Sys.getenv_opt
                                      "TOYC_DEBUG_SCEV_UNIFIED"
                                    <> None
                                  then
                                    Printf.eprintf
                                      "scev-runtime-delta-hit header=%s index=%d operand=%s scale=%s bias=%s\n%!"
                                      header
                                      use_index
                                      (string_of_lve_operand
                                         operand)
                                      (string_of_loop_inv_expr
                                         scale)
                                      (string_of_loop_inv_expr
                                         bias);
                                  Some (scale, bias)
                              | None ->
                                  direct_delta_affine_of_operand_legacy
                                    use_index seen operand
                            and direct_delta_affine_of_operand_legacy
                                use_index seen operand =
                              match operand with
                              | Tcg.Imm value ->
                                  Some (LveConst 0L, LveConst value)
                              | Tcg.Temp temp when temp = iv_temp ->
                                  let phase_bias =
                                    if use_index > iv_update_index then
                                      step_expr
                                    else
                                      LveConst 0L
                                  in
                                  Some
                                    ( LveConst 1L,
                                      normalize_loop_inv_expr phase_bias )
                              | Tcg.Temp temp as operand ->
                                  (match
                                     lve_runtime_scale_of_operand
                                       loop_defs multi_defs def_instrs
                                       iv_temp operand
                                   with
                                   | Some scale ->
                                       let phase_bias =
                                         if use_index > iv_update_index then
                                           normalize_loop_inv_expr
                                             (LveMul (scale, step_expr))
                                         else
                                           LveConst 0L
                                       in
                                       Some
                                         ( normalize_loop_inv_expr scale,
                                           normalize_loop_inv_expr phase_bias )
                                   | None -> (
                                       match
                                         lve_invariant_expr_of_operand
                                           loop_defs multi_defs def_instrs operand
                                       with
                                       | Some invariant ->
                                           Some
                                             ( LveConst 0L,
                                               normalize_loop_inv_expr invariant )
                                       | None ->
                                           if IntSet.mem temp seen then None
                                           else
                                             match
                                               last_body_def_before
                                                 use_index temp
                                             with
                                             | Some (def_index, instr) ->
                                                 direct_delta_affine_of_instr
                                                   def_index
                                                   (IntSet.add temp seen)
                                                   instr
                                             | None -> None))
                            and direct_delta_affine_of_instr
                                def_index seen = function
                              | Tcg.Move (_, src)
                              | Tcg.Un (_, UPlus, src) ->
                                  direct_delta_affine_of_operand
                                    def_index seen src
                              | Tcg.Un (_, UMinus, src) ->
                                  Option.map
                                    affine_neg
                                    (direct_delta_affine_of_operand
                                       def_index seen src)
                              | Tcg.Bin (_, Add, lhs, rhs) ->
                                  Option.bind
                                    (direct_delta_affine_of_operand
                                       def_index seen lhs)
                                    (fun lhs ->
                                      Option.map
                                        (affine_add lhs)
                                        (direct_delta_affine_of_operand
                                           def_index seen rhs))
                              | Tcg.Bin (_, Sub, lhs, rhs) ->
                                  Option.bind
                                    (direct_delta_affine_of_operand
                                       def_index seen lhs)
                                    (fun lhs ->
                                      Option.map
                                        (affine_sub lhs)
                                        (direct_delta_affine_of_operand
                                           def_index seen rhs))
                              | Tcg.Bin (_, Mul, lhs, rhs) ->
                                  Option.bind
                                    (direct_delta_affine_of_operand
                                       def_index seen lhs)
                                    (fun lhs_affine ->
                                      Option.bind
                                        (direct_delta_affine_of_operand
                                           def_index seen rhs)
                                        (fun rhs_affine ->
                                          if affine_is_invariant lhs_affine then
                                            let _, invariant = lhs_affine in
                                            Some
                                              (affine_mul_invariant
                                                 rhs_affine invariant)
                                          else if
                                            affine_is_invariant rhs_affine
                                          then
                                            let _, invariant = rhs_affine in
                                            Some
                                              (affine_mul_invariant
                                                 lhs_affine invariant)
                                          else
                                            None))
                              | Tcg.Un (_, UNot, _)
                              | Tcg.Bin
                                  (_,
                                   (Div | Mod | Lt | Le | Gt | Ge | Eq | Ne
                                   | LAnd | LOr),
                                   _, _)
                              | Tcg.Load _
                              | Tcg.Store _
                              | Tcg.Call _ ->
                                  None
                            in

                            let match_direct_reduction () =
                              match non_iv with
                              | [ (acc_index, acc_temp, delta_operand) ]
                                when acc_temp <> iv_temp ->
                                  Option.bind
                                    (direct_delta_affine_of_operand
                                       acc_index IntSet.empty delta_operand)
                                    (fun (delta_scale, delta_bias) ->
                                      let delta_scale =
                                        normalize_loop_inv_expr delta_scale
                                      in
                                      let delta_bias =
                                        normalize_loop_inv_expr delta_bias
                                      in
                                      let scale_available =
                                        lve_expr_available_before_preds
                                          doms def_blocks multi_defs
                                          [ preheader_label ] delta_scale
                                      in
                                      let bias_available =
                                        lve_expr_available_before_preds
                                          doms def_blocks multi_defs
                                          [ preheader_label ] delta_bias
                                      in
                                      if scale_available && bias_available then
                                        Some
                                          (`DirectAffine
                                            ( acc_temp,
                                              delta_scale,
                                              delta_bias ))
                                      else
                                        None)
                              | _ ->
                                  None
                            in

                            let match_move_accumulator_carrier () =
                              match non_iv with
                              | [ (_, derived_temp, delta_operand) ]
                                when derived_temp <> iv_temp -> (
                                  let delta_expr =
                                    lve_invariant_expr_of_operand
                                      loop_defs multi_defs def_instrs
                                      delta_operand
                                  in
                                  if
                                    Option.is_none delta_expr
                                    || not
                                         (operand_available_at_preheader
                                            def_blocks multi_defs
                                            preheader_label delta_operand)
                                  then
                                    None
                                  else
                                    body_indexed
                                    |> List.find_map (fun (acc_index, instr) ->
                                           match instr with
                                           | Tcg.Bin (sum_temp, Add, Tcg.Temp lhs, Tcg.Temp rhs) ->
                                               let acc_live =
                                                 if lhs = derived_temp
                                                    && rhs <> derived_temp
                                                    && rhs <> iv_temp
                                                 then
                                                   Some rhs
                                                 else if
                                                   rhs = derived_temp
                                                   && lhs <> derived_temp
                                                   && lhs <> iv_temp
                                                 then
                                                   Some lhs
                                                 else
                                                   None
                                               in
                                               Option.bind acc_live (fun acc_live ->
                                                 body_indexed
                                                 |> List.find_map
                                                      (fun (move_index, move_instr) ->
                                                        if move_index <= acc_index then
                                                          None
                                                        else
                                                          match move_instr with
                                                          | Tcg.Move (dst, Tcg.Temp src)
                                                          | Tcg.Un (dst, UPlus, Tcg.Temp src)
                                                            when src = sum_temp
                                                                 && dst = acc_live ->
                                                              Some
                                                                ( acc_live,
                                                                  derived_temp,
                                                                  delta_operand )
                                                          | Tcg.Move _
                                                          | Tcg.Un _
                                                          | Tcg.Bin _
                                                          | Tcg.Load _
                                                          | Tcg.Store _
                                                          | Tcg.Call _ ->
                                                              None))
                                           | Tcg.Move _
                                           | Tcg.Un _
                                           | Tcg.Bin _
                                           | Tcg.Load _
                                           | Tcg.Store _
                                           | Tcg.Call _ ->
                                               None))
                              | _ ->
                                  None
                            in

                            let match_pair () =
                                      match non_iv with
                                      | [ (i1, dst1, other1);
                                          (i2, dst2, other2) ] ->
                                          let try_pair
                                              (acc_i, acc, acc_other)
                                              (derived_i, derived, delta_operand)
                                            =
                                            match acc_other with
                                            | Tcg.Temp used
                                              when used = derived
                                                   && acc <> derived
                                                   && acc <> iv_temp
                                                   && derived <> iv_temp
                                                   && acc_i < derived_i ->
                                                let delta_expr =
                                                  lve_invariant_expr_of_operand
                                                    loop_defs multi_defs def_instrs
                                                    delta_operand
                                                in
                                                if
                                                  Option.is_some delta_expr
                                                  && operand_available_at_preheader
                                                       def_blocks multi_defs
                                                       preheader_label
                                                       delta_operand
                                                then
                                                  Some
                                                    ( acc,
                                                      derived,
                                                      delta_operand )
                                                else None
                                            | Tcg.Imm _ | Tcg.Temp _ ->
                                                None
                                          in
                                          (match
                                             try_pair
                                               (i1, dst1, other1)
                                               (i2, dst2, other2)
                                           with
                                           | Some _ as found -> found
                                           | None ->
                                               try_pair
                                                 (i2, dst2, other2)
                                                 (i1, dst1, other1))
                                      | _ -> None
                                    in
                            let reduction_shape =
                              match match_move_accumulator_carrier () with
                              | Some (acc_temp, derived_temp, delta_operand) ->
                                  Some
                                    (`Carrier
                                      ( acc_temp,
                                        derived_temp,
                                        delta_operand ))
                              | None ->
                                  (match match_direct_reduction () with
                                   | Some _ as direct ->
                                       direct
                                   | None ->
                                       (match match_pair () with
                                        | Some
                                            (acc_temp, derived_temp, delta_operand) ->
                                            Some
                                              (`Carrier
                                                ( acc_temp,
                                                  derived_temp,
                                                  delta_operand ))
                                        | None ->
                                            None))
                            in
                            match reduction_shape with
                            | None ->
                                reject header
                                  "no-runtime-affine-reduction"
                            | Some reduction_shape ->
                                (match reduction_shape with
                                 | `DirectAffine (acc, scale, bias) when debug ->
                                     Printf.eprintf
                                        "lve-runtime-direct-affine-reduction func=%s header=%s iv=t%d acc=t%d scale=%s bias=%s step=%s\n%!"
                                        f.name header iv_temp acc
                                        (string_of_loop_inv_expr scale)
                                        (string_of_loop_inv_expr bias)
                                        (string_of_lve_operand step_operand)
                                 | `DirectAffine _
                                 | `Carrier _ ->
                                     ());
                                let acc_temp =
                                  match reduction_shape with
                                  | `Carrier (acc, _, _)
                                  | `DirectAffine (acc, _, _) ->
                                      acc
                                in
                                let live_exit =
                                  table_find_or_empty
                                    live_in_t exit_label IntSet.empty
                                in
                                let loop_live_defs =
                                  IntSet.inter loop_defs live_exit
                                in
                                let supported_live_temps =
                                  IntSet.add iv_temp (IntSet.singleton acc_temp)
                                in
                                let supported_live_temps,
                                    reconstruction_order,
                                    reconstruction_exprs
                                  =
                                  collect_reconstructible_live_temps
                                    PlaceSet.empty
                                    loop_defs
                                    get_block
                                    def_blocks
                                    IntSet.empty
                                    multi_defs
                                    def_instrs
                                    supported_live_temps
                                    loop_live_defs
                                in
                                if not (IntSet.subset loop_live_defs supported_live_temps) then
                                  let missing =
                                    IntSet.diff loop_live_defs supported_live_temps
                                  in
                                  reject header
                                    (Printf.sprintf
                                       "bad-liveout missing={%s}"
                                       (String.concat ","
                                          (List.map string_of_int
                                             (IntSet.elements missing))))
                                else
                                            let preheader_reaches_loop =
                                              List.mem header preheader.succs
                                            in
                                            if not preheader_reaches_loop then
                                              reject header "preheader-no-longer-reaches-loop"
                                            else
                                              let materialize_summary_inv_expr
                                                  expr =
                                                match
                                                  normalize_loop_inv_expr expr
                                                with
                                                | LveConst value ->
                                                    ([], Tcg.Imm value)
                                                | LveOperand operand ->
                                                    ([], operand)
                                                | complex ->
                                                    let temp = fresh_temp () in
                                                    ( emit_loop_inv_expr
                                                        fresh_temp temp complex,
                                                      Tcg.Temp temp )
                                              in
                                              let summary_start_expr =
                                                match symbolic_trip_spec with
                                                | Some spec ->
                                                    spec.symbolic_trip_start
                                                | None ->
                                                    scalar_inv_zero
                                              in
                                              let build_reduction_apply_body
                                                  trip =
                                                let summary_trip, trip_prep =
                                                  if
                                                    loop_inv_expr_equal
                                                      control_scale (LveConst 1L)
                                                    && loop_inv_expr_equal
                                                         control_bias step_expr
                                                  then
                                                    let trip_plus_one =
                                                      fresh_temp ()
                                                    in
                                                    ( trip_plus_one,
                                                      [ simplify_simple_instr
                                                          (Tcg.Bin
                                                             ( trip_plus_one,
                                                               Add,
                                                               Tcg.Temp trip,
                                                               Tcg.Imm 1L )) ] )
                                                  else
                                                    (trip, [])
                                                in
                                                let
                                                  start_prep,
                                                  start_operand
                                                =
                                                  materialize_summary_inv_expr
                                                    summary_start_expr
                                                in
                                                let stepped_iv =
                                                  fresh_temp ()
                                                in
                                                let final_iv =
                                                  fresh_temp ()
                                                in
                                                let iv_update_instrs =
                                                  trip_prep
                                                  @ start_prep
                                                  @ [ simplify_simple_instr
                                                        (Tcg.Bin
                                                           ( stepped_iv,
                                                             Mul,
                                                             Tcg.Temp
                                                               summary_trip,
                                                             step_operand ));
                                                      simplify_simple_instr
                                                        (Tcg.Bin
                                                           ( final_iv,
                                                             Add,
                                                             start_operand,
                                                             Tcg.Temp
                                                               stepped_iv ));
                                                      simplify_simple_instr
                                                        (Tcg.Move
                                                           ( iv_temp,
                                                             Tcg.Temp
                                                               final_iv )) ]
                                                in
                                                let reconstruction_instrs =
                                                  build_live_temp_reconstruction_updates
                                                    fresh_temp PlaceMap.empty
                                                    reconstruction_order
                                                    reconstruction_exprs
                                                in
                                                match reduction_shape with
                                                | `Carrier
                                                    ( _,
                                                      derived_temp,
                                                      delta_operand ) ->
                                                    let
                                                      triangle_instrs,
                                                      triangle
                                                    =
                                                      build_triangle_number_instrs
                                                        fresh_temp summary_trip
                                                    in
                                                    let base_delta =
                                                      fresh_temp ()
                                                    in
                                                    let series_delta =
                                                      fresh_temp ()
                                                    in
                                                    let total_delta =
                                                      fresh_temp ()
                                                    in
                                                    iv_update_instrs
                                                    @ triangle_instrs
                                                    @ [ simplify_simple_instr
                                                          (Tcg.Bin
                                                             ( base_delta,
                                                               Mul,
                                                               Tcg.Temp summary_trip,
                                                               Tcg.Temp
                                                                 derived_temp ));
                                                        simplify_simple_instr
                                                          (Tcg.Bin
                                                             ( series_delta,
                                                               Mul,
                                                               Tcg.Temp
                                                                 triangle,
                                                               delta_operand ));
                                                        simplify_simple_instr
                                                          (Tcg.Bin
                                                             ( total_delta,
                                                               Add,
                                                               Tcg.Temp
                                                                 base_delta,
                                                               Tcg.Temp
                                                                 series_delta ));
                                                         simplify_simple_instr
                                                           (Tcg.Bin
                                                              ( acc_temp,
                                                                Add,
                                                                Tcg.Temp
                                                                  acc_temp,
                                                                Tcg.Temp
                                                                  total_delta )) ]
                                                    @ reconstruction_instrs
                                                | `DirectAffine
                                                    ( _,
                                                      delta_scale,
                                                      delta_bias ) ->
                                                    let
                                                      scale_prep,
                                                      scale_operand
                                                    =
                                                      materialize_summary_inv_expr
                                                        delta_scale
                                                    in
                                                    let
                                                      bias_prep,
                                                      bias_operand
                                                    =
                                                      materialize_summary_inv_expr
                                                        delta_bias
                                                    in
                                                    let
                                                      start_prep,
                                                      start_operand
                                                    =
                                                      materialize_summary_inv_expr
                                                        summary_start_expr
                                                    in
                                                    let
                                                      triangle_instrs,
                                                      triangle
                                                    =
                                                      build_triangle_number_instrs
                                                        fresh_temp summary_trip
                                                    in
                                                    let start_scaled =
                                                      fresh_temp ()
                                                    in
                                                    let effective_bias =
                                                      fresh_temp ()
                                                    in
                                                    let step_triangle =
                                                      fresh_temp ()
                                                    in
                                                    let series_delta =
                                                      fresh_temp ()
                                                    in
                                                    let base_delta =
                                                      fresh_temp ()
                                                    in
                                                    let total_delta =
                                                      fresh_temp ()
                                                    in
                                                    iv_update_instrs
                                                    @ scale_prep
                                                    @ bias_prep
                                                    @ start_prep
                                                    @ triangle_instrs
                                                    @ [ simplify_simple_instr
                                                          (Tcg.Bin
                                                             ( start_scaled,
                                                               Mul,
                                                               start_operand,
                                                               scale_operand ));
                                                        simplify_simple_instr
                                                          (Tcg.Bin
                                                             ( effective_bias,
                                                               Add,
                                                               Tcg.Temp
                                                                 start_scaled,
                                                               bias_operand ));
                                                        simplify_simple_instr
                                                          (Tcg.Bin
                                                             ( step_triangle,
                                                               Mul,
                                                               Tcg.Temp
                                                                 triangle,
                                                               step_operand ));
                                                        simplify_simple_instr
                                                          (Tcg.Bin
                                                             ( series_delta,
                                                               Mul,
                                                               Tcg.Temp
                                                                 step_triangle,
                                                               scale_operand ));
                                                        simplify_simple_instr
                                                          (Tcg.Bin
                                                              ( base_delta,
                                                                Mul,
                                                                Tcg.Temp summary_trip,
                                                                Tcg.Temp
                                                                  effective_bias ));
                                                        simplify_simple_instr
                                                          (Tcg.Bin
                                                             ( total_delta,
                                                               Add,
                                                               Tcg.Temp
                                                                 base_delta,
                                                               Tcg.Temp
                                                                 series_delta ));
                                                         simplify_simple_instr
                                                           (Tcg.Bin
                                                              ( acc_temp,
                                                                Add,
                                                                Tcg.Temp
                                                                  acc_temp,
                                                                Tcg.Temp
                                                                  total_delta )) ]
                                                    @ reconstruction_instrs
                                              in
                                              let use_affine_runtime_proof =
                                                match symbolic_trip_family with
                                                | Some
                                                    SymbolicTripPositiveAffineLt ->
                                                    true
                                                | Some SymbolicTripUnitLt ->
                                                    false
                                                | None ->
                                                    not
                                                      (loop_inv_expr_equal
                                                         control_scale
                                                         scalar_inv_one)
                                                    || not
                                                         (loop_inv_expr_equal
                                                            control_bias
                                                            scalar_inv_zero)
                                              in
                                              if use_affine_runtime_proof then begin
                                              (if scev_debug then
                                                 match
                                                   ( symbolic_trip_spec,
                                                     symbolic_trip_family )
                                                 with
                                                 | Some spec,
                                                   Some
                                                     SymbolicTripPositiveAffineLt ->
                                                     Printf.eprintf
                                                       "symbolic-trip-runtime-proof-hit header=%s family=%s start=%s step=%s scale=%s bias=%s bound=%s applied=true\n%!"
                                                       header
                                                       (string_of_symbolic_trip_proof_family
                                                          SymbolicTripPositiveAffineLt)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_start)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_step)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_scale)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_bias)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_bound)
                                                 | Some _, Some SymbolicTripUnitLt
                                                 | Some _, None
                                                 | None, _ ->
                                                     ());
                                              (* Runtime invariant affine-control
                                                 extension:

                                                   control = A * iv + B
                                                   iv += step

                                                 where start/A/B/step are pure
                                                 loop-invariant i32 values.

                                                 We never algebraically solve
                                                 the source comparison.  Instead
                                                 the control value itself is
                                                 treated as an AddRec with

                                                   control_start =
                                                     A * start + B
                                                   control_step = A * step.

                                                 The summary path is guarded by
                                                 runtime proofs that preserve
                                                 signed-i32 no-wrap monotonicity:
                                                   A > 0
                                                   control_start >= 0
                                                   step > 0
                                                   step <= INT32_MAX / A
                                                   bound > control_start
                                                   trip <=
                                                     (INT32_MAX-control_start)
                                                     / (A*step)

                                                 Any failed proof falls back to
                                                 the untouched original loop. *)
                                              let values_label =
                                                fresh_label "affine_values"
                                              in
                                              let scale_guard_label =
                                                fresh_label "affine_scale_guard"
                                              in
                                              let bias_guard_label =
                                                fresh_label "affine_bias_guard"
                                              in
                                              let step_guard_label =
                                                fresh_label "affine_step_guard"
                                              in
                                              let product_guard_label =
                                                fresh_label "affine_product_guard"
                                              in
                                              let bound_guard_label =
                                                fresh_label "affine_bound_guard"
                                              in
                                              let calc_label =
                                                fresh_label "affine_calc"
                                              in
                                              let apply_label =
                                                fresh_label "affine_apply"
                                              in

                                              let redirected_term =
                                                rewrite_term_successor
                                                  preheader.term
                                                  ~from_label:header
                                                  ~to_label:values_label
                                              in
                                              update_block
                                                {
                                                  preheader with
                                                  term = redirected_term;
                                                  succs =
                                                    Cfg.successors redirected_term;
                                                };

                                              let materialize_inv_expr expr =
                                                match
                                                  normalize_loop_inv_expr expr
                                                with
                                                | LveConst value ->
                                                    ([], Tcg.Imm value)
                                                | LveOperand operand ->
                                                    ([], operand)
                                                | complex ->
                                                    let temp = fresh_temp () in
                                                    ( emit_loop_inv_expr
                                                        fresh_temp temp complex,
                                                      Tcg.Temp temp )
                                              in
                                              let scale_prep, scale_operand =
                                                materialize_inv_expr
                                                  control_scale
                                              in
                                              let
                                                control_start_prep,
                                                control_start_operand
                                              =
                                                materialize_inv_expr
                                                  proof_control_start_expr
                                              in
                                              let values_body =
                                                step_prep
                                                @ scale_prep
                                                @ control_start_prep
                                              in
                                              let values_term =
                                                Cfg.BranchCompare
                                                  ( Gt,
                                                    scale_operand,
                                                    Tcg.Imm 0L,
                                                    scale_guard_label,
                                                    header )
                                              in
                                              let values_block =
                                                {
                                                  Cfg.label = values_label;
                                                  body = values_body;
                                                  term = values_term;
                                                  preds = [];
                                                  succs =
                                                    Cfg.successors values_term;
                                                }
                                              in

                                              let scale_guard_term =
                                                Cfg.BranchCompare
                                                  ( Ge,
                                                    control_start_operand,
                                                    Tcg.Imm 0L,
                                                    bias_guard_label,
                                                    header )
                                              in
                                              let scale_guard_block =
                                                {
                                                  Cfg.label = scale_guard_label;
                                                  body = [];
                                                  term = scale_guard_term;
                                                  preds = [];
                                                  succs =
                                                    Cfg.successors
                                                      scale_guard_term;
                                                }
                                              in

                                              let bias_guard_term =
                                                Cfg.BranchCompare
                                                  ( Gt,
                                                    step_operand,
                                                    Tcg.Imm 0L,
                                                    step_guard_label,
                                                    header )
                                              in
                                              let bias_guard_block =
                                                {
                                                  Cfg.label = bias_guard_label;
                                                  body = [];
                                                  term = bias_guard_term;
                                                  preds = [];
                                                  succs =
                                                    Cfg.successors
                                                      bias_guard_term;
                                                }
                                              in

                                              let max_step = fresh_temp () in
                                              let step_guard_body =
                                                [ simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( max_step,
                                                         Div,
                                                         Tcg.Imm 2147483647L,
                                                         scale_operand )) ]
                                              in
                                              let step_guard_term =
                                                Cfg.BranchCompare
                                                  ( Le,
                                                    step_operand,
                                                    Tcg.Temp max_step,
                                                    product_guard_label,
                                                    header )
                                              in
                                              let step_guard_block =
                                                {
                                                  Cfg.label = step_guard_label;
                                                  body = step_guard_body;
                                                  term = step_guard_term;
                                                  preds = [];
                                                  succs =
                                                    Cfg.successors
                                                      step_guard_term;
                                                }
                                              in

                                              let product_guard_term =
                                                Cfg.BranchCompare
                                                  ( Gt,
                                                    bound_operand,
                                                    control_start_operand,
                                                    bound_guard_label,
                                                    header )
                                              in
                                              let product_guard_block =
                                                {
                                                  Cfg.label =
                                                    product_guard_label;
                                                  body = [];
                                                  term = product_guard_term;
                                                  preds = [];
                                                  succs =
                                                    Cfg.successors
                                                      product_guard_term;
                                                }
                                              in

                                              let effective_step =
                                                fresh_temp ()
                                              in
                                              let adjusted_bound =
                                                fresh_temp ()
                                              in
                                              let max_control_delta =
                                                fresh_temp ()
                                              in
                                              let bound_guard_body =
                                                [ simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( effective_step,
                                                         Mul,
                                                         step_operand,
                                                         scale_operand ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( adjusted_bound,
                                                         Sub,
                                                         bound_operand,
                                                         control_start_operand ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( max_control_delta,
                                                         Sub,
                                                         Tcg.Imm 2147483647L,
                                                         control_start_operand )) ]
                                              in
                                              let bound_guard_term =
                                                Cfg.Jump calc_label
                                              in
                                              let bound_guard_block =
                                                {
                                                  Cfg.label = bound_guard_label;
                                                  body = bound_guard_body;
                                                  term = bound_guard_term;
                                                  preds = [];
                                                  succs = [ calc_label ];
                                                }
                                              in

                                              let quotient = fresh_temp () in
                                              let remainder = fresh_temp () in
                                              let has_remainder =
                                                fresh_temp ()
                                              in
                                              let trip = fresh_temp () in
                                              let max_trip = fresh_temp () in
                                              let calc_body =
                                                [ simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( quotient,
                                                         Div,
                                                         Tcg.Temp
                                                           adjusted_bound,
                                                         Tcg.Temp
                                                           effective_step ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( remainder,
                                                         Mod,
                                                         Tcg.Temp
                                                           adjusted_bound,
                                                         Tcg.Temp
                                                           effective_step ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( has_remainder,
                                                         Ne,
                                                         Tcg.Temp remainder,
                                                         Tcg.Imm 0L ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( trip,
                                                         Add,
                                                         Tcg.Temp quotient,
                                                         Tcg.Temp
                                                           has_remainder ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( max_trip,
                                                         Div,
                                                         Tcg.Temp
                                                           max_control_delta,
                                                         Tcg.Temp
                                                           effective_step )) ]
                                              in
                                              let calc_term =
                                                Cfg.BranchCompare
                                                  ( Le,
                                                    Tcg.Temp trip,
                                                    Tcg.Temp max_trip,
                                                    apply_label,
                                                    header )
                                              in
                                              let calc_block =
                                                {
                                                  Cfg.label = calc_label;
                                                  body = calc_body;
                                                  term = calc_term;
                                                  preds = [];
                                                  succs =
                                                    Cfg.successors calc_term;
                                                }
                                              in

                                              let apply_body =
                                                build_reduction_apply_body trip
                                              in
                                              let apply_block =
                                                {
                                                  Cfg.label = apply_label;
                                                  body = apply_body;
                                                  term =
                                                    Cfg.Jump exit_label;
                                                  preds = [];
                                                  succs = [ exit_label ];
                                                }
                                              in

                                              List.iter
                                                (fun
                                                  (new_block : Cfg.block) ->
                                                  Hashtbl.replace
                                                    current_blocks
                                                    new_block.label
                                                    new_block;
                                                  new_blocks_rev :=
                                                    new_block.label
                                                    :: !new_blocks_rev)
                                                [ values_block;
                                                  scale_guard_block;
                                                  bias_guard_block;
                                                  step_guard_block;
                                                  product_guard_block;
                                                  bound_guard_block;
                                                  calc_block;
                                                  apply_block ];

                                              changed := true;
                                              if debug then
                                                Printf.eprintf
                                                  "lve-runtime-invariant-affine-summary func=%s header=%s iv=t%d scale=%s bias=%s control-start=%s acc=t%d reduction=%s step=%s bound=%s fallback=%s\n%!"
                                                  f.name header iv_temp
                                                  (string_of_loop_inv_expr
                                                     control_scale)
                                                  (string_of_loop_inv_expr
                                                     control_bias)
                                                  (string_of_loop_inv_expr
                                                     proof_control_start_expr)
                                                  acc_temp
                                                  (match reduction_shape with
                                                   | `Carrier
                                                       (_, derived, delta) ->
                                                       Printf.sprintf
                                                         "carrier:t%d+=%s"
                                                         derived
                                                         (string_of_lve_operand
                                                            delta)
                                                   | `DirectAffine
                                                        (_, scale, bias) ->
                                                        Printf.sprintf
                                                          "direct-affine:scale=%s,bias=%s"
                                                          (string_of_loop_inv_expr
                                                             scale)
                                                          (string_of_loop_inv_expr
                                                             bias)
                                                  )
                                                   (string_of_lve_operand
                                                      step_operand)
                                                   (string_of_lve_operand
                                                      bound_operand)
                                                  header
                                            end else begin
                                              (if scev_debug then
                                                 match
                                                   ( symbolic_trip_spec,
                                                     symbolic_trip_family )
                                                 with
                                                 | Some spec,
                                                   Some SymbolicTripUnitLt ->
                                                     Printf.eprintf
                                                       "symbolic-trip-runtime-proof-hit header=%s family=%s start=%s step=%s scale=%s bias=%s bound=%s applied=true\n%!"
                                                       header
                                                       (string_of_symbolic_trip_proof_family
                                                          SymbolicTripUnitLt)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_start)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_step)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_scale)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_bias)
                                                       (string_of_loop_inv_expr
                                                          spec.symbolic_trip_bound)
                                                 | Some _,
                                                   Some
                                                     SymbolicTripPositiveAffineLt
                                                 | Some _, None
                                                 | None, _ ->
                                                     ());
                                              let guard_label = fresh_label "guard" in
                                              let calc_label = fresh_label "calc" in
                                              let apply_label = fresh_label "apply" in

                                              let redirected_term =
                                                rewrite_term_successor
                                                  preheader.term
                                                  ~from_label:header
                                                  ~to_label:guard_label
                                              in
                                              update_block
                                                {
                                                  preheader with
                                                  term = redirected_term;
                                                  succs =
                                                    Cfg.successors redirected_term;
                                                };

                                              let guard_term =
                                                Cfg.BranchCompare
                                                  ( Gt,
                                                    step_operand,
                                                    Tcg.Imm 0L,
                                                    calc_label,
                                                    header )
                                              in
                                              let guard_block =
                                                {
                                                  Cfg.label = guard_label;
                                                  body = step_prep;
                                                  term = guard_term;
                                                  preds = [];
                                                  succs =
                                                    Cfg.successors guard_term;
                                                }
                                              in

                                              (* The original first-entry guard
                                                 already proved 0 < bound. *)
                                              let quotient = fresh_temp () in
                                              let remainder = fresh_temp () in
                                              let has_remainder = fresh_temp () in
                                              let trip = fresh_temp () in
                                              let max_trip = fresh_temp () in
                                              let calc_body =
                                                [ simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( quotient,
                                                         Div,
                                                         bound_operand,
                                                         step_operand ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( remainder,
                                                         Mod,
                                                         bound_operand,
                                                         step_operand ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( has_remainder,
                                                         Ne,
                                                         Tcg.Temp remainder,
                                                         Tcg.Imm 0L ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( trip,
                                                         Add,
                                                         Tcg.Temp quotient,
                                                         Tcg.Temp has_remainder ));
                                                  simplify_simple_instr
                                                    (Tcg.Bin
                                                       ( max_trip,
                                                         Div,
                                                         Tcg.Imm 2147483647L,
                                                         step_operand )) ]
                                              in
                                              let calc_term =
                                                Cfg.BranchCompare
                                                  ( Le,
                                                    Tcg.Temp trip,
                                                    Tcg.Temp max_trip,
                                                    apply_label,
                                                    header )
                                              in
                                              let calc_block =
                                                {
                                                  Cfg.label = calc_label;
                                                  body = calc_body;
                                                  term = calc_term;
                                                  preds = [];
                                                  succs =
                                                    Cfg.successors calc_term;
                                                }
                                              in

                                              let apply_body =
                                                build_reduction_apply_body trip
                                              in
                                              let apply_block =
                                                {
                                                  Cfg.label = apply_label;
                                                  body = apply_body;
                                                  term = Cfg.Jump exit_label;
                                                  preds = [];
                                                  succs = [ exit_label ];
                                                }
                                              in

                                              List.iter
                                                (fun (new_block : Cfg.block) ->
                                                  Hashtbl.replace
                                                    current_blocks
                                                    new_block.label
                                                    new_block;
                                                  new_blocks_rev :=
                                                    new_block.label
                                                    :: !new_blocks_rev)
                                                [ guard_block;
                                                  calc_block;
                                                  apply_block ];

                                              changed := true;
                                              if debug then
                                                Printf.eprintf
                                                  "lve-runtime-summary func=%s header=%s blocks=%d iv=t%d acc=t%d reduction=%s step=%s bound=%s fallback=%s\n%!"
                                                  f.name header
                                                  (LabelSet.cardinal loop)
                                                  iv_temp
                                                  acc_temp
                                                  (match reduction_shape with
                                                   | `Carrier
                                                       (_, derived, delta) ->
                                                       Printf.sprintf
                                                         "carrier:t%d+=%s"
                                                         derived
                                                         (string_of_lve_operand
                                                            delta)
                                                   | `DirectAffine
                                                        (_, scale, bias) ->
                                                        Printf.sprintf
                                                          "direct-affine:scale=%s,bias=%s"
                                                          (string_of_loop_inv_expr
                                                             scale)
                                                          (string_of_loop_inv_expr
                                                             bias)
                                                  )
                                                   (string_of_lve_operand step_operand)
                                                   (string_of_lve_operand bound_operand)
                                                   header
                                             end)
      | _ -> reject header "outside-predecessor-count")
      headers;

    if !changed then
      let original_labels =
        List.map (fun (block : Cfg.block) -> block.label) f.blocks
      in
      let blocks =
        List.map get_block original_labels
        @ List.rev_map get_block !new_blocks_rev
      in
      Cfg.rebuild_edges
        { f with temp_count = !next_temp; blocks }
    else f

type func_metrics = {
  block_count : int;
  instr_count : int;
  temp_count : int;
}

type opt_profile = {
  name : string;
  max_rounds : int;
}

let metrics_of_func (f : Cfg.func) =
  let instr_count =
    List.fold_left (fun acc (block : Cfg.block) -> acc + List.length block.body) 0 f.blocks
  in
  { block_count = List.length f.blocks; instr_count; temp_count = f.temp_count }

let format_metrics { block_count; instr_count; temp_count } =
  Printf.sprintf "blocks=%d instrs=%d temps=%d" block_count instr_count temp_count

let choose_opt_profile metrics =
  if
    metrics.block_count >= 96
    || metrics.instr_count >= 480
    || metrics.temp_count >= 256
  then
    {
      name = "huge";
      max_rounds = 5;
    }
  else if
    metrics.block_count >= 48
    || metrics.instr_count >= 240
    || metrics.temp_count >= 128
  then
    {
      name = "large";
      max_rounds = 5;
    }
  else if
    metrics.block_count >= 24
    || metrics.instr_count >= 120
    || metrics.temp_count >= 64
  then
    {
      name = "medium";
      max_rounds = 5;
    }
  else
    {
      name = "full";
      max_rounds = 8;
    }

let stage_round_enabled profile round stage =
  match profile.name with
  | "huge" -> (
      match stage with
      | "split_reductions" | "unswitch" -> round <= 2
      | "diamond_split" | "full_unroll" | "unroll2" | "rotate" | "gvn2" -> round <= 1
      | _ -> true)
  | "large" -> (
      match stage with
      | "split_reductions" | "unswitch" -> round <= 3
      | "diamond_split" -> round <= 2
      | "full_unroll" | "unroll2" | "rotate" | "gvn2" -> round <= 4
      | _ -> true)
  | "medium" -> (
      match stage with
      | "split_reductions" | "unswitch" -> round <= 2
      | "diamond_split" -> round <= 2
      | "full_unroll" | "unroll2" | "rotate" -> round <= 3
      | _ -> true)
  | _ -> (
      match stage with
      | "diamond_split" -> round <= 2
      | _ -> true)

let optimize_func global_init summaries globals return_globals removable_calls (f : Cfg.func) =
  let debug_lcssa_stage stage (current : Cfg.func) =
    if Sys.getenv_opt "TOYC_DEBUG_LCSSA_LITE" <> None then begin
      Printf.eprintf
        "lcssa-lite-stage func=%s stage=%s blocks=%d temps=%d\n%!"
        current.name stage
        (List.length current.blocks)
        current.temp_count;
      debug_lcssa_lite_report summaries globals current
    end
  in
  let early_mem2reg =
    if Sys.getenv_opt "TOYC_DISABLE_EARLY_OPTIMISTIC_MEM2REG" <> None then
      mem2reg_func f
    else
      mem2reg_func ~optimistic_loop_phi:true f
  in
  let promoted =
    early_mem2reg |> promote_globals_func summaries globals
  in
  let () = debug_lcssa_stage "promoted" promoted in
  let canonical =
    loop_canonicalize_func summaries globals promoted
  in
  let () = debug_lcssa_stage "canonical" canonical in
  let base_metrics = metrics_of_func f in
  let promoted_metrics = metrics_of_func promoted in
  let profile = choose_opt_profile base_metrics in
  let debug_stop_after = Sys.getenv_opt "TOYC_DEBUG_STOP_AFTER" in
  let debug_pass_times = Sys.getenv_opt "TOYC_DEBUG_PASS_TIMES" <> None in
  let debug_opt_profile = debug_pass_times || Sys.getenv_opt "TOYC_DEBUG_OPT_PROFILE" <> None in
  let exception StopPass of Cfg.func in
  let stop_after stage current =
    match debug_stop_after with
    | Some target when target = stage -> raise (StopPass current)
    | Some _ | None -> current
  in
  let run_stage round ?(enabled = true) stage pass current =
    let debug_child_summary_boundary when_ current =
      if
        Sys.getenv_opt "TOYC_DEBUG_LCSSA_LITE" <> None
        &&
        (stage = "split_reductions"
         || stage = "counted_loops")
      then
        debug_lcssa_stage
          (Printf.sprintf
             "round%d-%s-%s"
             round when_ stage)
          current
    in
    let () =
      debug_child_summary_boundary "pre" current
    in
    if not enabled then begin
      if debug_pass_times then
        Printf.eprintf "pass-time func=%s round=%d stage=%s skipped profile=%s\n%!"
          promoted.name round stage profile.name;
      stop_after stage current
    end else
      let before_metrics = if debug_pass_times then Some (metrics_of_func current) else None in
      let start_time = if debug_pass_times then Sys.time () else 0.0 in
      let candidate =
        try pass current with
        | Failure message when has_prefix "internal missing block: " message ->
            if debug_pass_times then
              Printf.eprintf
                "pass-time func=%s round=%d stage=%s recovered_missing_block=%s\n%!"
                promoted.name round stage message;
            current
      in
      (* Stage-local CFG correctness guard.
         A loop/CFG transform must never be allowed to poison all later stages.
         If one pass creates a terminator whose target block no longer exists,
         discard only that pass and continue from the last valid CFG. *)
      let next =
        if cfg_targets_valid candidate then candidate
        else begin
          debug_cfg_validation
            (Printf.sprintf "round=%d:%s" round stage)
            candidate;
          if Sys.getenv_opt "TOYC_DEBUG_CFG_VALIDATE" <> None then
            Printf.eprintf
              "cfg-stage-reject func=%s round=%d stage=%s\n%!"
              promoted.name round stage;
          current
        end
      in
      let () =
        debug_child_summary_boundary "post" next
      in
      if debug_pass_times then begin
        let elapsed_ms = (Sys.time () -. start_time) *. 1000.0 in
        let before_metrics =
          match before_metrics with
          | Some metrics -> metrics
          | None -> metrics_of_func current
        in
        let after_metrics = metrics_of_func next in
        Printf.eprintf
          "pass-time func=%s round=%d stage=%s changed=%b ms=%.3f %s -> %s\n%!"
          promoted.name round stage (next <> current) elapsed_ms
          (format_metrics before_metrics) (format_metrics after_metrics)
      end;
      stop_after stage next
  in
  if debug_opt_profile then
    Printf.eprintf
      "opt-profile func=%s profile=%s rounds=%d base=(%s) promoted=(%s)\n%!"
      promoted.name profile.name profile.max_rounds
      (format_metrics base_metrics) (format_metrics promoted_metrics);
  let step round func =
    try
      let after_canon =
        run_stage round "canonicalize"
          (loop_canonicalize_func summaries globals)
          func
      in
      let after_simplify0 = run_stage round "simplify0" simplify_cfg_func after_canon in
      let after_const1 =
        run_stage round "const1"
          (const_propagate_func global_init summaries globals)
          after_simplify0
      in
      let after_algebra1 =
        run_stage round "algebra1" algebra_canonicalize_func after_const1
      in
      let after_linear1 =
        run_stage round "linear1" general_linear_canonicalize_func after_algebra1
      in
      let after_factor1 =
        run_stage round "factor_mul1" factor_common_mul_func after_linear1
      in
      let after_sr = run_stage round "sr" strength_reduce_func after_factor1 in
      let after_gvn1 = run_stage round "gvn1" (gvn_func summaries globals) after_sr in
      let after_dce1 =
        run_stage round "dce1" (eliminate_dead_code_func ~removable_calls summaries globals return_globals) after_gvn1
      in
      let after_reassoc = run_stage round "reassoc" reassociate_loop_adds_func after_dce1 in
      let after_licm = run_stage round "licm" (licm_func summaries globals) after_reassoc in

      (* LICM can expose algebraic opportunities that were syntactically hidden
         by repeated local loads.  In particular, after hoisting invariant
         locals, expressions such as

             ((iv + a) * b) - (iv * b)

         have both products referring to the same invariant [b] temp.  Run a
         small algebra cleanup before LVE/SR so factoring can turn this into

             b * ((iv + a) - iv)  ==>  a * b

         instead of letting LVE first strength-reduce [iv * b] into a
         loop-carried recurrence, which destroys the cancellation shape. *)
      let after_licm_factor =
        run_stage round "post_licm_factor" factor_common_mul_func after_licm
      in
      let after_licm_linear =
        run_stage round "post_licm_linear"
          general_linear_canonicalize_func after_licm_factor
      in
      let after_licm_algebra =
        run_stage round "post_licm_algebra"
          algebra_canonicalize_func after_licm_linear
      in
       let after_licm_dce =
         run_stage round "post_licm_dce"
           (eliminate_dead_code_func ~removable_calls summaries globals return_globals)
           after_licm_algebra
       in
       let after_runtime_summary =
         run_stage round "runtime_summary"
           (summarize_runtime_symbolic_affine_loops_func summaries globals)
           after_licm_dce
       in
       let after_lve_sr =
         run_stage round "lve_sr" loop_evolution_strength_reduce_func after_runtime_summary
       in
      let after_unswitch =
        run_stage round
          ~enabled:(stage_round_enabled profile round "unswitch")
          "unswitch"
          (unswitch_loops_func summaries globals)
          after_lve_sr
      in
      let after_const2 =
        run_stage round "const2"
          (const_propagate_func global_init summaries globals)
          after_unswitch
      in
      let after_algebra2 =
        run_stage round "algebra2" algebra_canonicalize_func after_const2
      in
      let after_linear2 =
        run_stage round "linear2" general_linear_canonicalize_func after_algebra2
      in
      let after_factor2 =
        run_stage round "factor_mul2" factor_common_mul_func after_linear2
      in
      let after_gvn2 =
        run_stage round "gvn2"
          (gvn_func summaries globals)
          after_factor2
      in
      let after_dce2 =
        run_stage round "dce2" (eliminate_dead_code_func ~removable_calls summaries globals return_globals) after_gvn2
      in
      let after_dead_loops =
        run_stage round "dead_loops" (eliminate_dead_loops_func summaries globals) after_dce2
      in
      let after_fold =
        run_stage round "fold" (fold_branch_tails_func summaries globals) after_dead_loops
      in
      let after_thread1 = run_stage round "thread1" thread_and_prune_func after_fold in
      let after_canon2 =
        run_stage round "canonicalize2"
          (loop_canonicalize_func summaries globals)
          after_thread1
      in
      let after_simplify2 = run_stage round "simplify2" simplify_cfg_func after_canon2 in
      let after_loop_guards =
        run_stage round "loop_guards"
          (simplify_counted_loop_guards_func summaries globals)
          after_simplify2
      in
      let after_const3 =
        run_stage round "const3"
          (const_propagate_func global_init summaries globals)
          after_loop_guards
      in
      let after_dce3 =
        run_stage round "dce3" (eliminate_dead_code_func ~removable_calls summaries globals return_globals) after_const3
      in
      let after_fold4 =
        run_stage round "fold4" (fold_branch_tails_func summaries globals) after_dce3
      in
      let after_thread4 = run_stage round "thread4" thread_and_prune_func after_fold4 in
      let after_canon3 =
        run_stage round "canonicalize3"
          (loop_canonicalize_func summaries globals)
          after_thread4
      in
      let after_simplify3 = run_stage round "simplify3" simplify_cfg_func after_canon3 in
      let after_diamond_split =
        run_stage round
          ~enabled:(stage_round_enabled profile round "diamond_split")
          "diamond_split"
          (split_counted_diamond_loops_func summaries globals)
          after_simplify3
      in
      let after_split =
        run_stage round
          ~enabled:(stage_round_enabled profile round "split_reductions")
          "split_reductions"
          (extract_counted_reductions_func summaries globals)
          after_diamond_split
      in
      let after_counted =
        run_stage round "counted_loops"
          (eliminate_counted_loops_func global_init summaries globals)
          after_split
      in
      let after_full_unroll =
        run_stage round
          ~enabled:(stage_round_enabled profile round "full_unroll")
          "full_unroll"
          (full_unroll_counted_loops_func summaries globals)
          after_counted
      in
      let after_effect_full_unroll =
        run_stage round
          ~enabled:(round <= 1)
          "effect_full_unroll"
          (full_unroll_effectful_counted_loops_func summaries globals)
          after_full_unroll
      in
      let after_unroll =
        run_stage round
          ~enabled:(stage_round_enabled profile round "unroll2")
          "unroll2"
          (unroll_counted_loops_x2_func summaries globals)
          after_effect_full_unroll
      in
      let after_thread2 = run_stage round "thread2" thread_and_prune_func after_unroll in
      let after_fold2 =
        run_stage round "fold2" (fold_branch_tails_func summaries globals) after_thread2
      in
      let after_rotate =
        run_stage round
          ~enabled:(stage_round_enabled profile round "rotate")
          "rotate"
          loop_rotate_func after_fold2
      in
      let after_thread3 = run_stage round "thread3" thread_and_prune_func after_rotate in
      let after_fold3 =
        run_stage round "fold3" (fold_branch_tails_func summaries globals) after_thread3
      in
      after_fold3
    with
    | StopPass current -> current
  in
  let rec loop round fuel current =
    if fuel = 0 then current
    else
      let next = step round current in
      if next = current then current else loop (round + 1) (fuel - 1) next
  in
  match debug_stop_after with
  | Some "mem2reg" -> promoted
  | Some _ -> loop 1 profile.max_rounds canonical
  | None ->
      let optimized =
        loop 1 profile.max_rounds canonical
      in
      let () =
        debug_lcssa_stage "post-rounds" optimized
      in
      (* Keep the early mem2reg conservative so downstream CFG/loop transforms
         see the same stable shape as step24.  After all iterative transforms
         have settled, run a final optimistic loop-phi mem2reg: provisional
         loop-header phis can now bootstrap loop-carried locals without feeding
         the new phi/edge-copy CFG back into rotate/split/unroll passes. *)
      let late_promoted = mem2reg_func ~optimistic_loop_phi:true optimized in
      if Sys.getenv_opt "TOYC_DEBUG_LATE_MEM2REG" <> None then begin
        let count_local_accesses (func : Cfg.func) =
          List.fold_left
            (fun count (block : Cfg.block) ->
              List.fold_left
                (fun count instr ->
                  match instr with
                  | Tcg.Load (_, Tcg.Local _) | Tcg.Store (Tcg.Local _, _) -> count + 1
                  | _ -> count)
                count block.body)
            0 func.blocks
        in
        let before_locals = count_local_accesses optimized in
        let after_locals = count_local_accesses late_promoted in
        if before_locals <> after_locals || optimized.temp_count <> late_promoted.temp_count then
          Printf.eprintf
            "late-mem2reg func=%s local-accesses=%d->%d temps=%d->%d\n%!"
            optimized.name before_locals after_locals optimized.temp_count
            late_promoted.temp_count
      end;
      let () =
        debug_lcssa_stage "late-mem2reg" late_promoted
      in
      (* IMPORTANT: run late algebra BEFORE copy coalescing.  Late mem2reg
         deliberately creates fresh, mostly single-definition/single-use temp
         chains.  [algebra_canonicalize_func] can safely follow those chains,
         but coalescing first can merge unrelated definitions onto one temp and
         make the canonicalizer reject them as multi-def/use-heavy. *)
      let late_algebra = algebra_canonicalize_func late_promoted in
      let late_linear = general_linear_canonicalize_func late_algebra in
      let late_factor = factor_common_mul_func late_linear in
      let late_pre_summary_input =
        late_factor
        |> eliminate_dead_code_func
             ~removable_calls summaries globals return_globals
        |> copy_coalesce_func summaries globals
      in
      let () =
        debug_lcssa_stage
          "pre-runtime-summary"
          late_pre_summary_input
      in
      let late_pre_runtime_summarized =
        summarize_runtime_symbolic_affine_loops_func
          summaries globals late_pre_summary_input
      in
      let () =
        debug_lcssa_stage
          "post-runtime-summary"
          late_pre_runtime_summarized
      in
      let late_pre_runtime_cleaned =
        late_pre_runtime_summarized
        |> eliminate_dead_code_func
             ~removable_calls summaries globals return_globals
        |> copy_coalesce_func summaries globals
      in
      let late_lve_sr =
        loop_evolution_strength_reduce_func late_pre_runtime_cleaned
      in
      let late_dce =
        eliminate_dead_code_func ~removable_calls summaries globals return_globals late_lve_sr
      in
      let late_coalesced = copy_coalesce_func summaries globals late_dce in
      let late_equiv_branches =
        fold_late_equivalent_diamonds_func late_coalesced
      in
      let late_equiv_cleaned =
        late_equiv_branches
        |> eliminate_dead_code_func
             ~removable_calls summaries globals return_globals
        |> copy_coalesce_func summaries globals
      in
      let late_equiv_recanon =
        late_equiv_cleaned
        |> algebra_canonicalize_func
        |> general_linear_canonicalize_func
        |> factor_common_mul_func
        |> eliminate_dead_code_func
             ~removable_calls summaries globals return_globals
        |> copy_coalesce_func summaries globals
      in
      let late_runtime_summarized =
        summarize_runtime_symbolic_affine_loops_func
          summaries globals late_equiv_recanon
      in
      let late_runtime_cleaned =
        late_runtime_summarized
        |> eliminate_dead_code_func
             ~removable_calls summaries globals return_globals
        |> copy_coalesce_func summaries globals
      in
      if Sys.getenv_opt "TOYC_DEBUG_LATE_ALGEBRA" <> None then begin
        let before = metrics_of_func late_promoted in
        let after_algebra = metrics_of_func late_algebra in
        let after_dce = metrics_of_func late_coalesced in
        if late_coalesced <> late_promoted then
          Printf.eprintf
            "late-algebra func=%s instrs=%d->%d->%d temps=%d->%d\n%!"
            late_promoted.name before.instr_count after_algebra.instr_count
            after_dce.instr_count before.temp_count after_dce.temp_count
      end;
      let () =
        debug_lcssa_stage
          "late-runtime-cleaned"
          late_runtime_cleaned
      in
      let with_hoisted_loop_bounds =
        hoist_unrolled_loop_branch_immediates_func summaries globals late_runtime_cleaned
      in
      let final_candidate =
        final_linear_merge_func with_hoisted_loop_bounds
      in
      if cfg_targets_valid final_candidate then final_candidate
      else begin
        debug_cfg_validation "final-candidate" final_candidate;
        (* Correctness guard: never hand codegen a CFG containing a terminator
           whose target block was removed by a late transform.  Prefer the
           closest valid pre-final form so successful loop-phi promotion is
           retained whenever possible. *)
        let fallbacks =
          [
            ("pre-final-merge", with_hoisted_loop_bounds);
            ("late-runtime-cleaned", late_runtime_cleaned);
            ("late-equiv-recanon", late_equiv_recanon);
            ("late-equiv-cleaned", late_equiv_cleaned);
            ("late-coalesced", late_coalesced);
            ("pre-late-mem2reg", optimized);
            ("canonical", canonical);
            ("promoted", promoted);
            ("original", f);
          ]
        in
        let rec choose = function
          | [] -> f
          | (stage, candidate) :: rest ->
              if cfg_targets_valid candidate then begin
                if Sys.getenv_opt "TOYC_DEBUG_CFG_VALIDATE" <> None then
                  Printf.eprintf "cfg-fallback func=%s stage=%s\n%!"
                    f.name stage;
                candidate
              end else begin
                debug_cfg_validation stage candidate;
                choose rest
              end
        in
        choose fallbacks
      end


(* -------------------------------------------------------------------------- *)
(* Safe dead pure-call elimination                                            *)
(* -------------------------------------------------------------------------- *)

let func_has_direct_divmod (f : Cfg.func) =
  List.exists
    (fun (block : Cfg.block) ->
      List.exists
        (function
          | Tcg.Bin (_, (Div | Mod), _, _) -> true
          | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ | Tcg.Call _ ->
              false)
        block.body)
    f.blocks

let direct_callee_labels (f : Cfg.func) =
  List.fold_left
    (fun acc (block : Cfg.block) ->
      List.fold_left
        (fun acc instr ->
          match instr with
          | Tcg.Call (_, callee, _) -> LabelSet.add callee acc
          | Tcg.Move _ | Tcg.Un _ | Tcg.Bin _ | Tcg.Load _ | Tcg.Store _ -> acc)
        acc block.body)
    LabelSet.empty f.blocks

let strict_unit_counted_control = function
  | Some (info : counted_loop_info) -> (
      match info.kind with
      | CountUpLt (_, bias) ->
          info.control_iv.step = 1L && bias = 0L
      | CountDownGt (_, bias) ->
          info.control_iv.step = -1L && bias = 0L
      | CountUpLe _
      | CountDownGe _
      | CountUpLtScaled _
      | CountUpLeScaled _
      | CountDownGtScaled _
      | CountDownGeScaled _ ->
          false)
  | None -> false

let cfg_acyclic_ignoring_edges (f : Cfg.func) ignored =
  let block_map = Hashtbl.create (List.length f.blocks) in
  List.iter
    (fun (block : Cfg.block) -> Hashtbl.replace block_map block.label block)
    f.blocks;
  let color = Hashtbl.create (List.length f.blocks) in
  let rec visit label =
    match Hashtbl.find_opt color label with
    | Some 1 -> false
    | Some 2 -> true
    | Some _ | None ->
        Hashtbl.replace color label 1;
        let ok =
          match Hashtbl.find_opt block_map label with
          | None -> false
          | Some (block : Cfg.block) ->
              List.for_all
                (fun succ ->
                  if Hashtbl.mem ignored (label, succ) then true
                  else visit succ)
                block.succs
        in
        if ok then Hashtbl.replace color label 2;
        ok
  in
  visit f.entry

let func_cycles_provably_terminate summaries globals (f : Cfg.func) =
  (* Analysis-only SSA view.  It is never emitted and never enters the normal
     loop-transform pipeline; it merely exposes loop-carried induction vars. *)
  let view =
    f
    |> mem2reg_func ~optimistic_loop_phi:true
    |> loop_canonicalize_func summaries globals
  in
  if not (cfg_targets_valid view) then false
  else
    let block_map, loops, headers = discover_natural_loops view in
    let get_block = get_block_exn block_map in
    let safe_headers = Hashtbl.create (max 8 (List.length headers)) in
    List.iter
      (fun header ->
        let loop = table_find_or_empty loops header LabelSet.empty in
        let _, _, _, _, _, _, control =
          analyze_counted_loop header loop get_block view.temp_count view.blocks
        in
        Hashtbl.replace safe_headers header (strict_unit_counted_control control))
      headers;

    let doms = compute_dominators view in
    let ignored_backedges = Hashtbl.create 16 in
    let every_backedge_safe =
      List.for_all
        (fun (block : Cfg.block) ->
          List.for_all
            (fun succ ->
              if LabelSet.mem succ (table_find_or_empty doms block.label LabelSet.empty) then
                match Hashtbl.find_opt safe_headers succ with
                | Some true ->
                    Hashtbl.replace ignored_backedges (block.label, succ) true;
                    true
                | Some false | None -> false
              else true)
            block.succs)
        view.blocks
    in
    every_backedge_safe && cfg_acyclic_ignoring_edges view ignored_backedges

let compute_provably_terminating_funcs summaries globals funcs =
  let structural = Hashtbl.create (max 8 (List.length funcs)) in
  let known_funcs = Hashtbl.create (max 8 (List.length funcs)) in
  List.iter (fun (f : Cfg.func) -> Hashtbl.replace known_funcs f.label true) funcs;

  List.iter
    (fun (f : Cfg.func) ->
      let direct_calls_known =
        LabelSet.for_all (fun callee -> Hashtbl.mem known_funcs callee) (direct_callee_labels f)
      in
      let base =
        direct_calls_known
        && not (func_has_direct_divmod f)
        && func_cycles_provably_terminate summaries globals f
      in
      Hashtbl.replace structural f.label base)
    funcs;

  (* Least fixed point: recursion is therefore rejected unless it has already
     been removed by tail-recursion elimination into a provably counted loop. *)
  let terminating = Hashtbl.create (max 8 (List.length funcs)) in
  List.iter (fun (f : Cfg.func) -> Hashtbl.replace terminating f.label false) funcs;
  let changed = ref true in
  while !changed do
    changed := false;
    List.iter
      (fun (f : Cfg.func) ->
        let base =
          match Hashtbl.find_opt structural f.label with
          | Some value -> value
          | None -> false
        in
        let callees_ok =
          LabelSet.for_all
            (fun callee ->
              match Hashtbl.find_opt terminating callee with
              | Some true -> true
              | Some false | None -> false)
            (direct_callee_labels f)
        in
        let next = base && callees_ok in
        let prev =
          match Hashtbl.find_opt terminating f.label with
          | Some value -> value
          | None -> false
        in
        if next <> prev then begin
          Hashtbl.replace terminating f.label next;
          changed := true
        end)
      funcs
  done;
  terminating

let compute_dead_call_removable_funcs summaries globals funcs =
  let terminating = compute_provably_terminating_funcs summaries globals funcs in
  let removable = Hashtbl.create (max 8 (List.length funcs)) in
  List.iter
    (fun (f : Cfg.func) ->
      let terminates =
        match Hashtbl.find_opt terminating f.label with
        | Some value -> value
        | None -> false
      in
      let writes_globals = call_written_globals summaries globals f.label in
      let can_remove = terminates && PlaceSet.is_empty writes_globals in
      Hashtbl.replace removable f.label can_remove;
      if Sys.getenv_opt "TOYC_DEBUG_DEAD_CALLS" <> None then
        Printf.eprintf
          "dead-call-summary func=%s terminates=%b writes_globals=%d removable=%b\n%!"
          f.name terminates (PlaceSet.cardinal writes_globals) can_remove)
    funcs;
  removable


(* -------------------------------------------------------------------------- *)
(* Whole-program constant-parameter specialization                            *)
(*                                                                            *)
(* ToyC has only direct calls and no function pointers.  For every non-main    *)
(* function, if a formal parameter receives the SAME immediate at every        *)
(* remaining direct call site, and the callee never stores to that formal,     *)
(* then the formal's initial value is a whole-program constant.                 *)
(*                                                                            *)
(* Replace Loads of that read-only formal by Moves from the immediate and rerun *)
(* the normal per-function optimizer.  This deliberately keeps the ABI and     *)
(* function signature unchanged; it is therefore semantics-preserving even     *)
(* before later trivial-call folding removes the now-redundant call.            *)
(*                                                                            *)
(* This is especially useful for loops such as                                 *)
(*                                                                            *)
(*   walk(n, step) ... i = i + step;                                           *)
(*   main() { return walk(21, 3); }                                            *)
(*                                                                            *)
(* where the intraprocedural counted-loop analysis intentionally models only   *)
(* constant IV steps.  Specialization turns [step] into 3 before rerunning the *)
(* existing loop machinery, without teaching every trip-count formula about    *)
(* symbolic divisors.                                                          *)
(* -------------------------------------------------------------------------- *)

type const_param_state =
  | ConstParamUnset
  | ConstParamValue of int64
  | ConstParamConflict

type const_param_observation = {
  mutable const_param_calls : int;
  const_param_states : const_param_state array;
}

let merge_const_param_state state operand =
  match (state, operand) with
  | ConstParamConflict, _ -> ConstParamConflict
  | ConstParamUnset, Tcg.Imm value -> ConstParamValue value
  | ConstParamValue old, Tcg.Imm value when Int64.equal old value ->
      ConstParamValue old
  | ConstParamUnset, Tcg.Temp _
  | ConstParamValue _, Tcg.Temp _
  | ConstParamValue _, Tcg.Imm _ ->
      ConstParamConflict

let observe_constant_call_arguments (funcs : Cfg.func list) =
  let observations :
      (string, const_param_observation) Hashtbl.t =
    Hashtbl.create (max 8 (List.length funcs))
  in
  List.iter
    (fun (f : Cfg.func) ->
      if f.name <> "main" && f.params <> [] then
        Hashtbl.replace observations f.label
          {
            const_param_calls = 0;
            const_param_states =
              Array.make (List.length f.params) ConstParamUnset;
          })
    funcs;
  List.iter
    (fun (caller : Cfg.func) ->
      List.iter
        (fun (block : Cfg.block) ->
          List.iter
            (function
              | Tcg.Call (_, callee, args) -> (
                  match Hashtbl.find_opt observations callee with
                  | Some observation ->
                      observation.const_param_calls <-
                        observation.const_param_calls + 1;
                      if
                        List.length args
                        = Array.length observation.const_param_states
                      then
                        List.iteri
                          (fun index arg ->
                            observation.const_param_states.(index) <-
                              merge_const_param_state
                                observation.const_param_states.(index)
                                arg)
                          args
                      else
                        Array.fill
                          observation.const_param_states
                          0
                          (Array.length observation.const_param_states)
                          ConstParamConflict
                  | None -> ())
              | Tcg.Move _
              | Tcg.Un _
              | Tcg.Bin _
              | Tcg.Load _
              | Tcg.Store _ ->
                  ())
            block.body)
        caller.blocks)
    funcs;
  observations

let stored_local_ids_of_func (f : Cfg.func) =
  List.fold_left
    (fun stored (block : Cfg.block) ->
      List.fold_left
        (fun stored -> function
          | Tcg.Store (Tcg.Local id, _) -> IntSet.add id stored
          | Tcg.Move _
          | Tcg.Un _
          | Tcg.Bin _
          | Tcg.Load _
          | Tcg.Store (Tcg.Global _, _)
          | Tcg.Call _ ->
              stored)
        stored block.body)
    IntSet.empty f.blocks

let specialize_constant_params_func
    observations
    (f : Cfg.func) =
  match Hashtbl.find_opt observations f.label with
  | None -> (f, 0)
  | Some observation when observation.const_param_calls = 0 -> (f, 0)
  | Some observation ->
      let stored = stored_local_ids_of_func f in
      let constants = Hashtbl.create (max 4 (List.length f.params)) in
      List.iteri
        (fun index (param : Tcg.var) ->
          if not (IntSet.mem param.id stored) then
            match observation.const_param_states.(index) with
            | ConstParamValue value ->
                Hashtbl.replace constants param.id value
            | ConstParamUnset
            | ConstParamConflict ->
                ())
        f.params;
      if Hashtbl.length constants = 0 then (f, 0)
      else
        let replaced = ref 0 in
        let blocks =
          List.map
            (fun (block : Cfg.block) ->
              let body =
                List.map
                  (function
                    | Tcg.Load (dst, Tcg.Local id) as instr -> (
                        match Hashtbl.find_opt constants id with
                        | Some value ->
                            incr replaced;
                            simplify_simple_instr
                              (Tcg.Move (dst, Tcg.Imm value))
                        | None -> instr)
                    | instr -> instr)
                  block.body
              in
              { block with body })
            f.blocks
        in
        if !replaced = 0 then (f, 0)
        else
          let specialized = Cfg.rebuild_edges { f with blocks } in
          if Sys.getenv_opt "TOYC_DEBUG_CONST_PARAMS" <> None then begin
            let params =
              List.filter_map
                (fun (param : Tcg.var) ->
                  match Hashtbl.find_opt constants param.id with
                  | Some value ->
                      Some
                        (Printf.sprintf "%s=%Ld" param.name value)
                  | None -> None)
                f.params
              |> String.concat ","
            in
            Printf.eprintf
              "const-param-specialize func=%s calls=%d params=[%s] loads=%d\n%!"
              f.name observation.const_param_calls params !replaced
          end;
          (specialized, !replaced)

(* Constant-parameter specialization deliberately reruns the full
   intraprocedural optimizer.  That is powerful, but on already transformed
   nonlinear/nested loop CFGs it can re-enter loop splitting/unswitching shapes
   that were not designed to be optimized a second time.

   Keep this late specialization transactional:
   - loop-free functions are safe to try;
   - for functions with loops, every natural loop must contain at most ONE
     conditional block (normally the loop guard).  An internal if, nested loop,
     split pre/post loop, etc. therefore rejects the specialization attempt;
   - after optimizing the specialized candidate, if a function that originally
     had loops STILL has a loop, discard the candidate and keep the original.

   The last rule also makes the pass performance-monotone on the cases that
   motivated it: we only retain loop specialization when it completely removes
   the loop, e.g. sum_to(10) / sum_two(6). *)
let constant_param_simple_loop_shape (f : Cfg.func) =
  let block_map, loops, headers = discover_natural_loops f in
  let get_block label =
    match Hashtbl.find_opt block_map label with
    | Some block -> block
    | None -> failwith ("missing block in constant-param shape check: " ^ label)
  in
  List.for_all
    (fun header ->
      let loop = table_find_or_empty loops header LabelSet.empty in
      let conditional_blocks =
        LabelSet.fold
          (fun label count ->
            let block : Cfg.block = get_block label in
            match branch_term_outcomes block.term with
            | Some _ -> count + 1
            | None -> count)
          loop 0
      in
      conditional_blocks <= 1)
    headers

(* Source-based constant-parameter re-specialization for one exact
   nonlinear loop shape.

   The initial CFG can contain transparent blocks introduced by lowering, e.g.

       guard -> dead_0 -> body
       body  -> dead_1 -> then

   where [dead_0]/[dead_1] have an empty body and an unconditional jump.
   Those blocks do not change the loop's semantics, but requiring the natural
   loop to contain literally five blocks rejects the source threshold diamond.

   Recognize the shape only after collapsing chains of such transparent blocks:

       guard
        |
       body (threshold branch)
      /    \
    then  else
      \    /
       join
        |
       guard

   Safety rules:
   - exactly one natural-loop header;
   - every non-core loop block must be an empty unconditional-jump block;
   - collapsed control flow must be exactly the five core blocks above;
   - one guard successor must leave the loop;
   - both threshold arms must reconverge at one join;
   - the join must return to the guard after transparent-edge collapsing.

   Once observed call arguments are constant, specialization is applied to
   this original CFG and optimized from scratch.  The existing transaction
   still accepts it only if the loop is completely eliminated. *)
(* A second source-based specialization shape for the common case where
   the loop is structurally simple but its induction step/bound is a formal
   parameter.

   The old late-simple path is kept as the first choice.  This source shape is
   only used as a fallback when late specialization finds zero parameter Loads
   to replace (typically because mem2reg has already converted those Loads into
   long-lived temps).

   Require one natural loop with exactly one conditional block.  That
   conditional must be the loop guard: exactly one of its successors stays in
   the natural loop and the other exits it.  Every other loop block must end
   in an unconditional jump, so there is no hidden internal branch. *)
let constant_param_source_simple_counted_loop_shape (f : Cfg.func) =
  let block_map, loops, headers = discover_natural_loops f in
  let find_block label =
    Hashtbl.find_opt block_map label
  in
  match headers with
  | [ header ] ->
      let loop =
        table_find_or_empty loops header LabelSet.empty
      in
      let conditional_labels =
        LabelSet.fold
          (fun label acc ->
            match find_block label with
            | Some (block : Cfg.block) ->
                begin
                  match branch_term_outcomes block.term with
                  | Some _ -> label :: acc
                  | None -> acc
                end
            | None ->
                acc)
          loop []
      in
      begin
        match conditional_labels with
        | [ guard ] ->
            let non_guard_terms_are_jumps =
              LabelSet.for_all
                (fun label ->
                  if label = guard then
                    true
                  else
                    match find_block label with
                    | Some (block : Cfg.block) ->
                        begin
                          match block.term with
                          | Cfg.Jump _ -> true
                          | Cfg.BranchZero _
                          | Cfg.BranchNonZero _
                          | Cfg.BranchCompare _
                          | Cfg.Return _ ->
                              false
                        end
                    | None ->
                        false)
                loop
            in
            if not non_guard_terms_are_jumps then
              false
            else
              begin
                match find_block guard with
                | Some (block : Cfg.block) ->
                    begin
                      match branch_term_outcomes block.term with
                      | Some (succ1, succ2) ->
                          let succ1_inside =
                            LabelSet.mem succ1 loop
                          in
                          let succ2_inside =
                            LabelSet.mem succ2 loop
                          in
                          succ1_inside <> succ2_inside
                      | None ->
                          false
                    end
                | None ->
                    false
              end
        | []
        | _ :: _ :: _ ->
            false
      end
  | []
  | _ :: _ :: _ ->
      false

let constant_param_source_threshold_diamond_shape (f : Cfg.func) =
  let block_map, loops, headers = discover_natural_loops f in

  let find_block label =
    Hashtbl.find_opt block_map label
  in

  let is_transparent_jump label =
    match find_block label with
    | Some (block : Cfg.block) ->
        begin
          match (block.body, block.term) with
          | [], Cfg.Jump target ->
              Some target
          | _ ->
              None
        end
    | None ->
        None
  in

  let rec collapse_target loop seen label =
    if LabelSet.mem label seen then
      None
    else
      match is_transparent_jump label with
      | Some target when LabelSet.mem label loop ->
          collapse_target
            loop
            (LabelSet.add label seen)
            target
      | Some _
      | None ->
          Some label
  in

  let collapsed_branch_outcomes loop label =
    match find_block label with
    | Some (block : Cfg.block) ->
        begin
          match branch_term_outcomes block.term with
          | Some (yes_label, no_label) ->
              begin
                match
                  ( collapse_target loop LabelSet.empty yes_label,
                    collapse_target loop LabelSet.empty no_label )
                with
                | Some yes_label, Some no_label ->
                    Some (yes_label, no_label)
                | Some _, None
                | None, Some _
                | None, None ->
                    None
              end
          | None ->
              None
        end
    | None ->
        None
  in

  let collapsed_jump_target loop label =
    match find_block label with
    | Some (block : Cfg.block) ->
        begin
          match block.term with
          | Cfg.Jump target ->
              collapse_target loop LabelSet.empty target
          | Cfg.BranchZero _
          | Cfg.BranchNonZero _
          | Cfg.BranchCompare _
          | Cfg.Return _ ->
              None
        end
    | None ->
        None
  in

  let all_extra_blocks_transparent loop core =
    LabelSet.for_all
      (fun label ->
        if LabelSet.mem label core then
          true
        else
          match is_transparent_jump label with
          | Some _ -> true
          | None -> false)
      loop
  in

  match headers with
  | [ header ] ->
      let loop =
        table_find_or_empty loops header LabelSet.empty
      in
      begin
        match collapsed_branch_outcomes loop header with
        | None ->
            false
        | Some (succ1, succ2) ->
            let succ1_inside = LabelSet.mem succ1 loop in
            let succ2_inside = LabelSet.mem succ2 loop in
            if succ1_inside = succ2_inside then
              false
            else
              let body_label =
                if succ1_inside then succ1 else succ2
              in
              let exit_label =
                if succ1_inside then succ2 else succ1
              in
              if LabelSet.mem exit_label loop then
                false
              else begin
                match collapsed_branch_outcomes loop body_label with
                | None ->
                    false
                | Some (arm1, arm2) ->
                    if
                      arm1 = arm2
                      || not (LabelSet.mem arm1 loop)
                      || not (LabelSet.mem arm2 loop)
                    then
                      false
                    else begin
                      match
                        ( collapsed_jump_target loop arm1,
                          collapsed_jump_target loop arm2 )
                      with
                      | Some join1, Some join2
                        when join1 = join2
                             && LabelSet.mem join1 loop
                             && join1 <> header
                             && join1 <> body_label
                             && join1 <> arm1
                             && join1 <> arm2 ->
                          begin
                            match collapsed_jump_target loop join1 with
                            | Some back when back = header ->
                                let core =
                                  List.fold_left
                                    (fun set label ->
                                      LabelSet.add label set)
                                    LabelSet.empty
                                    [ header;
                                      body_label;
                                      arm1;
                                      arm2;
                                      join1 ]
                                in
                                LabelSet.cardinal core = 5
                                && all_extra_blocks_transparent loop core
                            | Some _
                            | None ->
                                false
                          end
                      | Some _, Some _
                      | Some _, None
                      | None, Some _
                      | None, None ->
                          false
                    end
              end
      end
  | []
  | _ :: _ :: _ ->
      false

let function_has_natural_loop (f : Cfg.func) =
  let _, _, headers = discover_natural_loops f in
  headers <> []

let specialize_constant_params_program_once
    source_funcs
    global_init summaries globals return_global_demands removable_calls
    (funcs : Cfg.func list) =
  let observations = observe_constant_call_arguments funcs in
  let source_by_label =
    Hashtbl.create (max 8 (List.length source_funcs))
  in
  List.iter
    (fun (source : Cfg.func) ->
      Hashtbl.replace source_by_label source.label source)
    source_funcs;
  let changed = ref false in
  let funcs =
    List.map
      (fun (f : Cfg.func) ->
        let had_loop =
          function_has_natural_loop f
        in
        let late_simple =
          constant_param_simple_loop_shape f
        in
        let return_globals =
          match Hashtbl.find_opt return_global_demands f.label with
          | Some return_globals ->
              return_globals
          | None ->
              globals
        in

        let optimize_specialized_candidate mode specialized replacements =
          if replacements = 0 then
            None
          else begin
            if
              mode <> "late-simple"
              && Sys.getenv_opt "TOYC_DEBUG_CONST_PARAMS" <> None
            then
              Printf.eprintf
                "const-param-respecialize func=%s base=%s\n%!"
                f.name mode;
            let cleaned =
              optimize_func
                global_init summaries globals return_globals removable_calls
                specialized
            in
            debug_cfg_validation
              "const-param-specialize-cleanup" cleaned;
            let still_has_loop =
              function_has_natural_loop cleaned
            in
            Some (mode, cleaned, still_has_loop)
          end
        in

        (* First preserve the old late-simple route.  If it completely removes
           the loop, keep exactly that result.  If it sees the constants but
           leaves a loop behind, do NOT immediately roll back: the late CFG may
           already have mem2reg loop-carried temps that hide an otherwise
           ordinary source-level reduction. *)
        let late_result =
          if late_simple then
            let specialized, replacements =
              specialize_constant_params_func observations f
            in
            optimize_specialized_candidate
              "late-simple" specialized replacements
          else
            None
        in

        match late_result with
        | Some (mode, cleaned, false) ->
            if cleaned <> f then
              changed := true;
            if Sys.getenv_opt "TOYC_DEBUG_CONST_PARAMS" <> None then
              Printf.eprintf
                "const-param-accept func=%s mode=%s had_loop=%b loop_after=false\n%!"
                f.name mode had_loop;
            cleaned

        | Some ("late-simple", _, true)
        | None ->
            (* Either late specialization could not see useful parameter Loads,
               or it did see them but the optimized late CFG still contains a
               loop.  In both cases, retry from the pristine source CFG when it
               has one of the exact safe shapes we know how to re-optimize. *)
            let source_candidate =
              if not had_loop then
                None
              else
                match Hashtbl.find_opt source_by_label f.label with
                | Some source
                  when constant_param_source_simple_counted_loop_shape source ->
                    Some (source, "source-simple-counted-loop")
                | Some source
                  when constant_param_source_threshold_diamond_shape source ->
                    Some (source, "source-threshold-diamond")
                | Some _
                | None ->
                    None
            in
            begin
              match source_candidate with
              | None ->
                  if Sys.getenv_opt "TOYC_DEBUG_CONST_PARAMS" <> None then begin
                    match late_result with
                    | Some (mode, _, true) ->
                        Printf.eprintf
                          "const-param-rollback func=%s mode=%s reason=loop_remains-no-source-fallback\n%!"
                          f.name mode
                    | Some (_, _, false) ->
                        ()
                    | None ->
                        Printf.eprintf
                          "const-param-skip func=%s reason=no-specializable-source\n%!"
                          f.name
                  end;
                  f

              | Some (source, source_mode) ->
                  let source_specialized, source_replacements =
                    specialize_constant_params_func observations source
                  in
                  begin
                    match
                      optimize_specialized_candidate
                        source_mode
                        source_specialized
                        source_replacements
                    with
                    | Some (mode, cleaned, false) ->
                        if cleaned <> f then
                          changed := true;
                        if Sys.getenv_opt "TOYC_DEBUG_CONST_PARAMS" <> None then
                          Printf.eprintf
                            "const-param-accept func=%s mode=%s had_loop=%b loop_after=false\n%!"
                            f.name mode had_loop;
                        cleaned

                    | Some (mode, _, true) ->
                        if Sys.getenv_opt "TOYC_DEBUG_CONST_PARAMS" <> None then
                          Printf.eprintf
                            "const-param-rollback func=%s mode=%s reason=loop_remains\n%!"
                            f.name mode;
                        f

                    | None ->
                        if Sys.getenv_opt "TOYC_DEBUG_CONST_PARAMS" <> None then
                          Printf.eprintf
                            "const-param-rollback func=%s mode=%s reason=no-replacements\n%!"
                            f.name source_mode;
                        f
                  end
            end

        | Some (mode, _, true) ->
            (* Future-proofing: currently only late-simple can reach the
               pre-source retry arm above. *)
            if Sys.getenv_opt "TOYC_DEBUG_CONST_PARAMS" <> None then
              Printf.eprintf
                "const-param-rollback func=%s mode=%s reason=loop_remains\n%!"
                f.name mode;
            f)
      funcs
  in
  (funcs, !changed)

let specialize_constant_params_program
    source_funcs
    global_init summaries globals return_global_demands removable_calls
    (funcs : Cfg.func list) =
  let rec iterate fuel current =
    if fuel = 0 then current
    else
      let next, changed =
        specialize_constant_params_program_once
          source_funcs
          global_init summaries globals return_global_demands removable_calls
          current
      in
      if changed then iterate (fuel - 1) next else next
  in
  (* A few rounds allow constants exposed by one specialized caller to reach a
     downstream callee, while keeping compile time tightly bounded. *)
  iterate 3 funcs


(* -------------------------------------------------------------------------- *)
(* Small hot-loop leaf CFG inlining                                           *)
(*                                                                            *)
(* The AST expression inliner intentionally rejects runtime-controlled [if]    *)
(* bodies.  That leaves small pure helpers such as                             *)
(*                                                                            *)
(*   adjust(x, bias, limit) { if (...) ...; return ...; }                     *)
(*                                                                            *)
(* as real calls even when they execute on every loop iteration.  By the time *)
(* we reach this late program pass, each function has already been optimized, *)
(* so we can clone a very small callee CFG directly into a hot caller block.   *)
(*                                                                            *)
(* Keep the first version deliberately conservative:                          *)
(*   - only call sites already inside a natural loop;                          *)
(*   - TInt leaf callees, 2..4 reachable blocks, <= 20 scalar instructions;   *)
(*   - acyclic CFG;                                                            *)
(*   - no Call, Store, global Load, or Div/Mod;                                *)
(*   - the only remaining local Loads may read formal parameters;              *)
(*   - every return carries an integer value.                                 *)
(*                                                                            *)
(* Argument operands have already been evaluated at the original call site.   *)
(* Parameter Loads in the clone are therefore replaced by Moves from those     *)
(* operands, preserving call-by-value while giving const/algebra/DCE another   *)
(* chance after the function boundary disappears.                             *)
(* -------------------------------------------------------------------------- *)

let small_hot_inline_max_blocks = 4
let small_hot_inline_max_instrs = 20
let small_hot_inline_max_sites_per_func = 4

let hot_loop_labels_of_func (f : Cfg.func) =
  let _, loops, headers = discover_natural_loops f in
  List.fold_left
    (fun acc header ->
      LabelSet.union acc (table_find_or_empty loops header LabelSet.empty))
    LabelSet.empty headers

let small_leaf_inline_candidate (f : Cfg.func) : Cfg.func option =
  if f.ret <> TInt then None
  else
    let view =
      f
      |> thread_and_prune_func
      |> simplify_cfg_func
      |> final_linear_merge_func
      |> thread_and_prune_func
    in
    if not (cfg_targets_valid view) then None
    else
      let reachable = reachable_labels view.entry view.blocks in
      let blocks =
        List.filter
          (fun (block : Cfg.block) -> LabelSet.mem block.label reachable)
          view.blocks
      in
      let block_count = List.length blocks in
      let instr_count =
        List.fold_left
          (fun acc (block : Cfg.block) -> acc + List.length block.body)
          0 blocks
      in
      let param_ids =
        List.fold_left
          (fun acc (param : Tcg.var) -> IntSet.add param.id acc)
          IntSet.empty f.params
      in
      let instr_safe = function
        | Tcg.Move _ | Tcg.Un _ -> true
        | Tcg.Bin (_, (Div | Mod), _, _) -> false
        | Tcg.Bin _ -> true
        | Tcg.Load (_, Tcg.Local id) -> IntSet.mem id param_ids
        | Tcg.Load (_, Tcg.Global _) -> false
        | Tcg.Store _ | Tcg.Call _ -> false
      in
      let term_safe = function
        | Cfg.Return (Some _) -> true
        | Cfg.Jump _
        | Cfg.BranchZero _
        | Cfg.BranchNonZero _
        | Cfg.BranchCompare _ ->
            true
        | Cfg.Return None -> false
      in
      let has_value_return =
        List.exists
          (fun (block : Cfg.block) ->
            match block.term with
            | Cfg.Return (Some _) -> true
            | Cfg.Jump _
            | Cfg.BranchZero _
            | Cfg.BranchNonZero _
            | Cfg.BranchCompare _
            | Cfg.Return None ->
                false)
          blocks
      in
      let ignored = Hashtbl.create 1 in
      if
        block_count >= 2
        && block_count <= small_hot_inline_max_blocks
        && instr_count <= small_hot_inline_max_instrs
        && f.temp_count <= 48
        && has_value_return
        && List.for_all
             (fun (block : Cfg.block) ->
               List.for_all instr_safe block.body && term_safe block.term)
             blocks
        && cfg_acyclic_ignoring_edges view ignored
      then Some { view with blocks }
      else None

type small_hot_inline_site =
  Tcg.label
  * Tcg.simple_instr list
  * Tcg.temp
  * string
  * Tcg.operand list
  * Tcg.simple_instr list
  * Cfg.func

let build_small_hot_inline_table (funcs : Cfg.func list) :
    (string, Cfg.func) Hashtbl.t =
  let table : (string, Cfg.func) Hashtbl.t =
    Hashtbl.create (max 8 (List.length funcs))
  in
  List.iter
    (fun (f : Cfg.func) ->
      match small_leaf_inline_candidate f with
      | None -> ()
      | Some (candidate : Cfg.func) ->
          Hashtbl.replace table f.label candidate;
          if Sys.getenv_opt "TOYC_DEBUG_CFG_INLINE" <> None then begin
            let metrics = metrics_of_func candidate in
            Printf.eprintf
              "cfg-inline-candidate func=%s %s params=%d\n%!"
              f.name (format_metrics metrics) (List.length f.params)
          end)
    funcs;
  table

let find_hot_inline_site
    (table : (string, Cfg.func) Hashtbl.t)
    (f : Cfg.func) : small_hot_inline_site option =
  let hot_labels = hot_loop_labels_of_func f in
  if LabelSet.is_empty hot_labels then None
  else
    let rec find_in_body block_label rev_prefix = function
      | [] -> None
      | Tcg.Call (Some dst, callee, args) :: rest -> (
          match Hashtbl.find_opt table callee with
          | Some (candidate : Cfg.func)
            when callee <> f.label
                 && List.length args = List.length candidate.params ->
              Some
                ( block_label,
                  List.rev rev_prefix,
                  dst,
                  callee,
                  args,
                  rest,
                  candidate )
          | Some _ | None ->
              find_in_body block_label
                (Tcg.Call (Some dst, callee, args) :: rev_prefix)
                rest)
      | (Tcg.Call (None, _, _) as instr) :: rest ->
          find_in_body block_label (instr :: rev_prefix) rest
      | instr :: rest ->
          find_in_body block_label (instr :: rev_prefix) rest
    in
    let rec find = function
      | [] -> None
      | (block : Cfg.block) :: rest ->
          if LabelSet.mem block.label hot_labels then
            match find_in_body block.label [] block.body with
            | Some _ as site -> site
            | None -> find rest
          else find rest
    in
    find f.blocks

let inline_one_small_hot_call serial
    (f : Cfg.func)
    ((site_label, prefix, call_dst, callee_label, args, suffix, callee)
      : small_hot_inline_site) =
  let temp_base = f.temp_count in
  let rename_temp temp = temp_base + temp in
  let rename_operand = rewrite_operand_temp rename_temp in
  let param_args = Hashtbl.create (max 4 (List.length callee.params)) in
  List.iter2
    (fun (param : Tcg.var) arg -> Hashtbl.replace param_args param.id arg)
    callee.params args;

  let used_labels =
    List.fold_left
      (fun acc (block : Cfg.block) -> LabelSet.add block.label acc)
      LabelSet.empty f.blocks
    |> ref
  in
  let fresh_label base =
    let rec choose attempt =
      let label =
        if attempt = 0 then base else Printf.sprintf "%s_%d" base attempt
      in
      if LabelSet.mem label !used_labels then choose (attempt + 1)
      else begin
        used_labels := LabelSet.add label !used_labels;
        label
      end
    in
    choose 0
  in
  let continuation_label =
    fresh_label
      (Printf.sprintf ".L%s_cfg_inline_cont_%d" f.label serial)
  in
  let label_map = Hashtbl.create (List.length callee.blocks) in
  List.iteri
    (fun index (block : Cfg.block) ->
      let label =
        fresh_label
          (Printf.sprintf ".L%s_cfg_inline_%d_%d" f.label serial index)
      in
      Hashtbl.replace label_map block.label label)
    callee.blocks;
  let rename_label label =
    match Hashtbl.find_opt label_map label with
    | Some renamed -> renamed
    | None -> label
  in
  let clone_instr = function
    | Tcg.Load (dst, Tcg.Local id) -> (
        match Hashtbl.find_opt param_args id with
        | Some arg -> simplify_simple_instr (Tcg.Move (rename_temp dst, arg))
        | None ->
            (* Candidate construction excludes this case.  Keep the shape
               total here so a future relaxation cannot silently capture a
               caller-local id. *)
            Tcg.Load (rename_temp dst, Tcg.Local id))
    | instr -> rewrite_instr_temps rename_temp instr
  in
  let clone_block (block : Cfg.block) =
    let body = List.map clone_instr block.body in
    let body, term =
      match block.term with
      | Cfg.Return (Some value) ->
          ( body
            @ [
                simplify_simple_instr
                  (Tcg.Move (call_dst, rename_operand value));
              ],
            Cfg.Jump continuation_label )
      | Cfg.Return None ->
          (* Rejected by [small_leaf_inline_candidate]. *)
          (body, Cfg.Jump continuation_label)
      | term ->
          (body, rewrite_term rename_label rename_operand term)
    in
    {
      Cfg.label = rename_label block.label;
      body;
      term;
      preds = [];
      succs = Cfg.successors term;
    }
  in
  let cloned_blocks = List.map clone_block callee.blocks in
  let cloned_entry = rename_label callee.entry in
  let blocks =
    List.concat_map
      (fun (block : Cfg.block) ->
        if block.label <> site_label then [ block ]
        else
          let before =
            {
              block with
              body = prefix;
              term = Cfg.Jump cloned_entry;
              succs = [ cloned_entry ];
            }
          in
          let continuation =
            {
              Cfg.label = continuation_label;
              body = suffix;
              term = block.term;
              preds = [];
              succs = Cfg.successors block.term;
            }
          in
          before :: cloned_blocks @ [ continuation ])
      f.blocks
  in
  let candidate =
    Cfg.rebuild_edges
      { f with temp_count = temp_base + callee.temp_count; blocks }
  in
  if cfg_targets_valid candidate then begin
    if Sys.getenv_opt "TOYC_DEBUG_CFG_INLINE" <> None then
      Printf.eprintf
        "cfg-inline caller=%s callee=%s site=%s clone_blocks=%d temps=%d->%d\n%!"
        f.name callee.name site_label (List.length cloned_blocks)
        f.temp_count candidate.temp_count;
    Some candidate
  end else begin
    debug_cfg_validation
      (Printf.sprintf "cfg-inline:%s->%s" f.name callee_label)
      candidate;
    None
  end

let inline_small_hot_calls_func
    (table : (string, Cfg.func) Hashtbl.t)
    (f : Cfg.func) : Cfg.func * int =
  let rec apply serial fuel count (current : Cfg.func) : Cfg.func * int =
    if fuel = 0 then (current, count)
    else
      match find_hot_inline_site table current with
      | None -> (current, count)
      | Some (site : small_hot_inline_site) -> (
          match inline_one_small_hot_call serial current site with
          | None -> (current, count)
          | Some (next : Cfg.func) ->
              apply (serial + 1) (fuel - 1) (count + 1) next)
  in
  apply 0 small_hot_inline_max_sites_per_func 0 f

let inline_small_hot_calls_program
    global_init summaries globals return_global_demands removable_calls
    (funcs : Cfg.func list) =
  let table : (string, Cfg.func) Hashtbl.t =
    build_small_hot_inline_table funcs
  in
  if Hashtbl.length table = 0 then funcs
  else
    List.map
      (fun (f : Cfg.func) ->
        let inlined, count = inline_small_hot_calls_func table f in
        if count = 0 then f
        else
          let return_globals =
            match Hashtbl.find_opt return_global_demands f.label with
            | Some return_globals -> return_globals
            | None -> globals
          in
          let before = metrics_of_func f in
          let expanded = metrics_of_func inlined in
          let cleaned =
            optimize_func
              global_init summaries globals return_globals removable_calls
              inlined
          in
          if cfg_targets_valid cleaned then begin
            if Sys.getenv_opt "TOYC_DEBUG_CFG_INLINE" <> None then
              Printf.eprintf
                "cfg-inline-cleanup func=%s sites=%d %s -> expanded(%s) -> %s\n%!"
                f.name count (format_metrics before)
                (format_metrics expanded)
                (format_metrics (metrics_of_func cleaned));
            cleaned
          end else begin
            debug_cfg_validation "cfg-inline-cleanup" cleaned;
            f
          end)
      funcs





(* -------------------------------------------------------------------------- *)
(* Late small acyclic pure-CFG call expansion                                 *)
(*                                                                            *)
(* Step131 handles helpers that have collapsed to one straight-line block.     *)
(* A second common case remains: after optimization a helper is still a tiny   *)
(* branch diamond / short acyclic CFG.  The early AST inliner is already past, *)
(* and the existing CFG inliner requires the call site to be inside a natural  *)
(* loop.  Inline these small pure scalar CFGs at ordinary call sites too, then  *)
(* feed the caller back through [optimize_func].                                *)
(*                                                                            *)
(* Keep the candidate deliberately conservative:                               *)
(*   - TInt leaf helper, 2..6 reachable blocks, <= 32 instructions;            *)
(*   - acyclic CFG; every return carries a value;                               *)
(*   - Move/Un/non-trapping Bin, parameter loads, and global loads only;        *)
(*   - no Store, nested Call, Div, or Mod;                                      *)
(*   - at most four sites per caller per wave.                                  *)
(*                                                                            *)
(* We reuse [inline_one_small_hot_call], whose cloning logic already preserves *)
(* call-by-value parameter operands and joins every callee return at a fresh    *)
(* continuation block.                                                         *)
(* -------------------------------------------------------------------------- *)

let late_branch_inline_max_blocks = 6
let late_branch_inline_max_instrs = 32
let late_branch_inline_max_temps = 64
let late_branch_inline_max_sites_per_func = 4

let late_branch_inline_candidate (f : Cfg.func) : Cfg.func option =
  if f.ret <> TInt then None
  else
    let view =
      f
      |> thread_and_prune_func
      |> simplify_cfg_func
      |> final_linear_merge_func
      |> thread_and_prune_func
    in
    if not (cfg_targets_valid view) then None
    else
      let reachable = reachable_labels view.entry view.blocks in
      let blocks =
        List.filter
          (fun (block : Cfg.block) -> LabelSet.mem block.label reachable)
          view.blocks
      in
      let block_count = List.length blocks in
      let instr_count =
        List.fold_left
          (fun acc (block : Cfg.block) -> acc + List.length block.body)
          0 blocks
      in
      let param_ids =
        List.fold_left
          (fun acc (param : Tcg.var) -> IntSet.add param.id acc)
          IntSet.empty view.params
      in
      let instr_safe = function
        | Tcg.Move _ | Tcg.Un _ -> true
        | Tcg.Bin (_, (Div | Mod), _, _) -> false
        | Tcg.Bin _ -> true
        | Tcg.Load (_, Tcg.Local id) -> IntSet.mem id param_ids
        | Tcg.Load (_, Tcg.Global _) -> true
        | Tcg.Store _ | Tcg.Call _ -> false
      in
      let term_safe = function
        | Cfg.Return (Some _) -> true
        | Cfg.Jump _
        | Cfg.BranchZero _
        | Cfg.BranchNonZero _
        | Cfg.BranchCompare _ ->
            true
        | Cfg.Return None -> false
      in
      let all_returns_have_values =
        List.for_all
          (fun (block : Cfg.block) ->
            match block.term with
            | Cfg.Return None -> false
            | Cfg.Return (Some _)
            | Cfg.Jump _
            | Cfg.BranchZero _
            | Cfg.BranchNonZero _
            | Cfg.BranchCompare _ ->
                true)
          blocks
      in
      let has_value_return =
        List.exists
          (fun (block : Cfg.block) ->
            match block.term with
            | Cfg.Return (Some _) -> true
            | Cfg.Return None
            | Cfg.Jump _
            | Cfg.BranchZero _
            | Cfg.BranchNonZero _
            | Cfg.BranchCompare _ ->
                false)
          blocks
      in
      let ignored = Hashtbl.create 1 in
      if
        block_count >= 2
        && block_count <= late_branch_inline_max_blocks
        && instr_count <= late_branch_inline_max_instrs
        && view.temp_count <= late_branch_inline_max_temps
        && has_value_return
        && all_returns_have_values
        && List.for_all
             (fun (block : Cfg.block) ->
               List.for_all instr_safe block.body && term_safe block.term)
             blocks
        && cfg_acyclic_ignoring_edges view ignored
      then Some { view with blocks }
      else None

let build_late_branch_inline_table (funcs : Cfg.func list) :
    (string, Cfg.func) Hashtbl.t =
  let table = Hashtbl.create (max 8 (List.length funcs)) in
  List.iter
    (fun (f : Cfg.func) ->
      match late_branch_inline_candidate f with
      | None -> ()
      | Some candidate ->
          Hashtbl.replace table f.label candidate;
          if Sys.getenv_opt "TOYC_DEBUG_LATE_BRANCH_INLINE" <> None then
            Printf.eprintf
              "late-branch-candidate func=%s blocks=%d instrs=%d temps=%d params=%d\n%!"
              f.name (List.length candidate.blocks)
              (List.fold_left
                 (fun acc (block : Cfg.block) ->
                   acc + List.length block.body)
                 0 candidate.blocks)
              candidate.temp_count (List.length candidate.params))
    funcs;
  table

let find_late_branch_inline_site
    (table : (string, Cfg.func) Hashtbl.t)
    (f : Cfg.func) : small_hot_inline_site option =
  let rec find_in_body block_label rev_prefix = function
    | [] -> None
    | Tcg.Call (Some dst, callee, args) :: rest -> (
        match Hashtbl.find_opt table callee with
        | Some (candidate : Cfg.func)
          when callee <> f.label
               && List.length args = List.length candidate.params ->
            Some
              ( block_label,
                List.rev rev_prefix,
                dst,
                callee,
                args,
                rest,
                candidate )
        | Some _ | None ->
            find_in_body block_label
              (Tcg.Call (Some dst, callee, args) :: rev_prefix)
              rest)
    | instr :: rest ->
        find_in_body block_label (instr :: rev_prefix) rest
  in
  let rec find = function
    | [] -> None
    | (block : Cfg.block) :: rest -> (
        match find_in_body block.label [] block.body with
        | Some _ as site -> site
        | None -> find rest)
  in
  find f.blocks

let inline_late_branch_calls_func
    (table : (string, Cfg.func) Hashtbl.t)
    (f : Cfg.func) =
  let rec apply serial fuel count current =
    if fuel = 0 then (current, count)
    else
      match find_late_branch_inline_site table current with
      | None -> (current, count)
      | Some site -> (
          match inline_one_small_hot_call serial current site with
          | None -> (current, count)
          | Some next ->
              apply (serial + 1) (fuel - 1) (count + 1) next)
  in
  apply 0 late_branch_inline_max_sites_per_func 0 f

let inline_late_branch_calls_program
    global_init summaries globals return_global_demands removable_calls
    (funcs : Cfg.func list) =
  let rec iterate fuel current =
    if fuel = 0 then current
    else
      let table = build_late_branch_inline_table current in
      if Hashtbl.length table = 0 then current
      else
        let changed = ref false in
        let next =
          List.map
            (fun (f : Cfg.func) ->
              let inlined, count =
                inline_late_branch_calls_func table f
              in
              if count = 0 then f
              else begin
                changed := true;
                let return_globals =
                  match Hashtbl.find_opt return_global_demands f.label with
                  | Some return_globals -> return_globals
                  | None -> globals
                in
                let before = metrics_of_func f in
                let expanded = metrics_of_func inlined in
                let cleaned =
                  optimize_func
                    global_init summaries globals return_globals removable_calls
                    inlined
                in
                if cfg_targets_valid cleaned then begin
                  if Sys.getenv_opt "TOYC_DEBUG_LATE_BRANCH_INLINE" <> None then
                    Printf.eprintf
                      "late-branch-inline caller=%s sites=%d %s -> expanded(%s) -> %s\n%!"
                      f.name count (format_metrics before)
                      (format_metrics expanded)
                      (format_metrics (metrics_of_func cleaned));
                  cleaned
                end else begin
                  debug_cfg_validation "late-branch-inline-cleanup" cleaned;
                  f
                end
              end)
            current
        in
        if !changed then iterate (fuel - 1) next else current
  in
  iterate 2 funcs

(* -------------------------------------------------------------------------- *)
(* Late straight-line pure-call expansion                                     *)
(*                                                                            *)
(* The AST inliner runs before CFG optimization, so it cannot benefit when a   *)
(* helper only BECOMES simple after constant propagation, specialization, DCE, *)
(* branch folding, etc.  Likewise, the hot CFG inliner only sees calls inside  *)
(* natural loops.  Recover the remaining simple scalar cases here.              *)
(*                                                                            *)
(* Candidate requirements are deliberately strict:                             *)
(*   - TInt result; exactly one reachable entry block;                          *)
(*   - <= 32 simple instructions and <= 64 temps;                               *)
(*   - only Move/Un/non-trapping Bin, parameter loads, and global loads;        *)
(*   - no Store, nested Call, Div, or Mod;                                      *)
(*   - direct value return.                                                     *)
(*                                                                            *)
(* Expansion happens at the exact call site, so ordinary global loads preserve *)
(* their relative ordering.  After expansion, run the full intraprocedural      *)
(* optimizer so algebra/GVN/LICM/LVE can exploit the newly visible expression.  *)
(* -------------------------------------------------------------------------- *)

let late_scalar_inline_max_instrs = 32
let late_scalar_inline_max_temps = 64
let late_scalar_inline_max_sites_per_func = 8

type late_scalar_inline_candidate = {
  scalar_func : Cfg.func;
  scalar_block : Cfg.block;
  scalar_return : Tcg.operand;
}

let late_scalar_inline_candidate_of_func (f : Cfg.func) =
  if f.ret <> TInt then None
  else
    let view =
      f
      |> thread_and_prune_func
      |> simplify_cfg_func
      |> final_linear_merge_func
      |> thread_and_prune_func
    in
    if not (cfg_targets_valid view) then None
    else
      let reachable = reachable_labels view.entry view.blocks in
      let blocks =
        List.filter
          (fun (block : Cfg.block) -> LabelSet.mem block.label reachable)
          view.blocks
      in
      match blocks with
      | [ (block : Cfg.block) ] when block.label = view.entry ->
          let param_ids =
            List.fold_left
              (fun acc (param : Tcg.var) -> IntSet.add param.id acc)
              IntSet.empty view.params
          in
          let instr_safe = function
            | Tcg.Move _ | Tcg.Un _ -> true
            | Tcg.Bin (_, (Div | Mod), _, _) -> false
            | Tcg.Bin _ -> true
            | Tcg.Load (_, Tcg.Local id) -> IntSet.mem id param_ids
            | Tcg.Load (_, Tcg.Global _) -> true
            | Tcg.Store _ | Tcg.Call _ -> false
          in
          if List.length block.body > late_scalar_inline_max_instrs
             || view.temp_count > late_scalar_inline_max_temps
             || not (List.for_all instr_safe block.body)
          then None
          else
            begin
              match block.term with
              | Cfg.Return (Some operand) ->
                  Some
                    {
                      scalar_func = view;
                      scalar_block = block;
                      scalar_return = operand;
                    }
              | Cfg.Return None
              | Cfg.Jump _
              | Cfg.BranchZero _
              | Cfg.BranchNonZero _
              | Cfg.BranchCompare _ ->
                  None
            end
      | _ -> None

let build_late_scalar_inline_table funcs =
  let table = Hashtbl.create (max 8 (List.length funcs)) in
  List.iter
    (fun (f : Cfg.func) ->
      match late_scalar_inline_candidate_of_func f with
      | None -> ()
      | Some candidate ->
          Hashtbl.replace table f.label candidate;
          if Sys.getenv_opt "TOYC_DEBUG_LATE_SCALAR_INLINE" <> None then
            Printf.eprintf
              "late-scalar-candidate func=%s instrs=%d temps=%d params=%d\n%!"
              f.name (List.length candidate.scalar_block.body)
              candidate.scalar_func.temp_count
              (List.length candidate.scalar_func.params))
    funcs;
  table

let rewrite_late_scalar_calls_func
    (table : (string, late_scalar_inline_candidate) Hashtbl.t)
    (f : Cfg.func) =
  let next_temp = ref f.temp_count in
  let sites_left = ref late_scalar_inline_max_sites_per_func in
  let replaced = ref 0 in

  let expand_call dst args (candidate : late_scalar_inline_candidate) =
    let callee = candidate.scalar_func in
    if List.length args <> List.length callee.params then None
    else
      let temp_base = !next_temp in
      next_temp := temp_base + callee.temp_count;
      let rename_temp temp = temp_base + temp in
      let rename_operand = rewrite_operand_temp rename_temp in
      let param_args = Hashtbl.create (max 4 (List.length callee.params)) in
      List.iter2
        (fun (param : Tcg.var) arg -> Hashtbl.replace param_args param.id arg)
        callee.params args;
      let clone_instr = function
        | Tcg.Load (temp, Tcg.Local id) -> (
            match Hashtbl.find_opt param_args id with
            | Some arg ->
                simplify_simple_instr
                  (Tcg.Move (rename_temp temp, arg))
            | None ->
                failwith "internal late scalar inline non-parameter local load")
        | instr ->
            rewrite_instr_temps rename_temp instr
      in
      let body = List.map clone_instr candidate.scalar_block.body in
      let ret =
        simplify_simple_instr
          (Tcg.Move (dst, rename_operand candidate.scalar_return))
      in
      Some (body @ [ ret ])
  in

  let rewrite_body body =
    let rec loop rev_acc = function
      | [] -> List.rev rev_acc
      | Tcg.Call (Some dst, callee, args) as instr :: rest
        when !sites_left > 0 -> (
          match Hashtbl.find_opt table callee with
          | Some candidate when callee <> f.label -> (
              match expand_call dst args candidate with
              | Some expanded ->
                  decr sites_left;
                  incr replaced;
                  loop (List.rev_append expanded rev_acc) rest
              | None ->
                  loop (instr :: rev_acc) rest)
          | Some _ | None ->
              loop (instr :: rev_acc) rest)
      | instr :: rest ->
          loop (instr :: rev_acc) rest
    in
    loop [] body
  in

  let blocks =
    List.map
      (fun (block : Cfg.block) ->
        { block with body = rewrite_body block.body })
      f.blocks
  in
  if !replaced = 0 then (f, 0)
  else begin
    let rewritten =
      Cfg.rebuild_edges { f with temp_count = !next_temp; blocks }
    in
    if Sys.getenv_opt "TOYC_DEBUG_LATE_SCALAR_INLINE" <> None then
      Printf.eprintf
        "late-scalar-inline caller=%s replaced=%d temps=%d->%d\n%!"
        f.name !replaced f.temp_count rewritten.temp_count;
    (rewritten, !replaced)
  end

let inline_late_scalar_calls_program
    global_init summaries globals return_global_demands removable_calls
    (funcs : Cfg.func list) =
  let rec iterate fuel current =
    if fuel = 0 then current
    else
      let table = build_late_scalar_inline_table current in
      if Hashtbl.length table = 0 then current
      else
        let changed = ref false in
        let next =
          List.map
            (fun (f : Cfg.func) ->
              let rewritten, count =
                rewrite_late_scalar_calls_func table f
              in
              if count = 0 then f
              else begin
                changed := true;
                let return_globals =
                  match Hashtbl.find_opt return_global_demands f.label with
                  | Some return_globals -> return_globals
                  | None -> globals
                in
                let cleaned =
                  optimize_func
                    global_init summaries globals return_globals removable_calls
                    rewritten
                in
                debug_cfg_validation "late-scalar-inline-cleanup" cleaned;
                cleaned
              end)
            current
        in
        if !changed then iterate (fuel - 1) next else current
  in
  iterate 3 funcs

(* -------------------------------------------------------------------------- *)
(* Late trivial-call folding                                                  *)
(*                                                                            *)
(* DCE can turn a formerly complicated helper into a side-effect-free          *)
(* straight-line function that merely returns a constant or one of its         *)
(* arguments.  AST inlining has already happened by then, so without a late    *)
(* interprocedural cleanup the caller still pays the full call/RA-frame cost.  *)
(*                                                                            *)
(* Recognize only extremely safe callees: after jump-threading/final merging    *)
(* there must be exactly one reachable block, no Store/Call/global Load, no     *)
(* Div/Mod, and the return must symbolically reduce to a constant or parameter. *)
(* -------------------------------------------------------------------------- *)

type trivial_return_summary =
  | TrivialConst of int64
  | TrivialArg of int

type trivial_value =
  | TvConst of int64
  | TvArg of int

let trivial_value_of_operand env = function
  | Tcg.Imm value -> Some (TvConst (i32 value))
  | Tcg.Temp temp -> IntMap.find_opt temp env

let trivial_return_summary_of_func (f : Cfg.func) =
  let analysis_view =
    f
    |> thread_and_prune_func
    |> simplify_cfg_func
    |> final_linear_merge_func
    |> thread_and_prune_func
  in
  let reachable = reachable_labels analysis_view.entry analysis_view.blocks in
  let blocks =
    List.filter
      (fun (block : Cfg.block) -> LabelSet.mem block.label reachable)
      analysis_view.blocks
  in
  match blocks with
  | [ (block : Cfg.block) ] when block.label = analysis_view.entry ->
      let param_index_by_local = Hashtbl.create (List.length f.params) in
      List.iteri
        (fun index (param : Tcg.var) ->
          Hashtbl.replace param_index_by_local param.id index)
        f.params;
      let rec scan env = function
        | [] -> Some env
        | instr :: rest -> (
            match instr with
            | Tcg.Move (dst, src) -> (
                match trivial_value_of_operand env src with
                | Some value -> scan (IntMap.add dst value env) rest
                | None -> None)
            | Tcg.Un (dst, op, src) -> (
                match trivial_value_of_operand env src with
                | Some (TvConst value) -> (
                    match fold_unop op value with
                    | Some value -> scan (IntMap.add dst (TvConst value) env) rest
                    | None -> None)
                | Some (TvArg _) | None -> None)
            | Tcg.Bin (_, (Div | Mod), _, _) ->
                (* Even if constant-foldable, keep the proof deliberately
                   conservative around potentially trapping operators. *)
                None
            | Tcg.Bin (dst, op, lhs, rhs) -> (
                match
                  (trivial_value_of_operand env lhs, trivial_value_of_operand env rhs)
                with
                | Some (TvConst lhs), Some (TvConst rhs) -> (
                    match fold_binop op lhs rhs with
                    | Some value -> scan (IntMap.add dst (TvConst value) env) rest
                    | None -> None)
                | _ -> None)
            | Tcg.Load (dst, Tcg.Local local) -> (
                match Hashtbl.find_opt param_index_by_local local with
                | Some index -> scan (IntMap.add dst (TvArg index) env) rest
                | None -> None)
            | Tcg.Load (_, Tcg.Global _)
            | Tcg.Store _
            | Tcg.Call _ ->
                None)
      in
      begin
        match scan IntMap.empty block.body with
        | None -> None
        | Some env -> (
            match block.term with
            | Cfg.Return (Some operand) -> (
                match trivial_value_of_operand env operand with
                | Some (TvConst value) -> Some (TrivialConst value)
                | Some (TvArg index) -> Some (TrivialArg index)
                | None -> None)
            | Cfg.Return None
            | Cfg.Jump _
            | Cfg.BranchZero _
            | Cfg.BranchNonZero _
            | Cfg.BranchCompare _ ->
                None)
      end
  | _ -> None

let build_trivial_return_table funcs =
  let table = Hashtbl.create (max 8 (List.length funcs)) in
  List.iter
    (fun (f : Cfg.func) ->
      match trivial_return_summary_of_func f with
      | None -> ()
      | Some summary ->
          Hashtbl.replace table f.label summary;
          if Sys.getenv_opt "TOYC_DEBUG_TRIVIAL_CALLS" <> None then
            let summary_text =
              match summary with
              | TrivialConst value -> Printf.sprintf "const:%Ld" value
              | TrivialArg index -> Printf.sprintf "arg:%d" index
            in
            Printf.eprintf
              "trivial-call-summary func=%s summary=%s\n%!"
              f.name summary_text)
    funcs;
  table

let rewrite_trivial_calls_func table (f : Cfg.func) =
  let changed = ref false in
  let replaced = ref 0 in
  let rewrite_instr = function
    | Tcg.Call (dst, callee, args) as instr -> (
        match Hashtbl.find_opt table callee with
        | None -> Some instr
        | Some summary -> (
            match dst with
            | None ->
                changed := true;
                incr replaced;
                None
            | Some dst -> (
                let replacement =
                  match summary with
                  | TrivialConst value ->
                      Some (Tcg.Move (dst, Tcg.Imm value))
                  | TrivialArg index -> (
                      match List.nth_opt args index with
                      | Some operand -> Some (Tcg.Move (dst, operand))
                      | None -> None)
                in
                match replacement with
                | Some instr ->
                    changed := true;
                    incr replaced;
                    Some (simplify_simple_instr instr)
                | None -> Some instr)))
    | instr -> Some instr
  in
  let blocks =
    List.map
      (fun (block : Cfg.block) ->
        { block with body = List.filter_map rewrite_instr block.body })
      f.blocks
  in
  let result =
    if !changed then Cfg.rebuild_edges { f with blocks }
    else f
  in
  if !changed && Sys.getenv_opt "TOYC_DEBUG_TRIVIAL_CALLS" <> None then
    Printf.eprintf
      "trivial-call-fold func=%s replaced=%d\n%!"
      f.name !replaced;
  result

let cleanup_after_trivial_call_fold
    global_init summaries globals return_globals removable_calls
    (f : Cfg.func) =
  let candidate =
    f
    |> const_propagate_func global_init summaries globals
    |> algebra_canonicalize_func
    |> eliminate_dead_code_func ~removable_calls summaries globals return_globals
    |> fold_branch_tails_func summaries globals
    |> thread_and_prune_func
    |> simplify_cfg_func
    |> final_linear_merge_func
  in
  if cfg_targets_valid candidate then candidate
  else begin
    debug_cfg_validation "late-trivial-call-cleanup" candidate;
    f
  end

let fold_trivial_calls_program
    global_init summaries globals return_global_demands removable_calls
    (funcs : Cfg.func list) =
  let rec iterate fuel current =
    if fuel = 0 then current
    else
      let table = build_trivial_return_table current in
      if Hashtbl.length table = 0 then current
      else
        let changed = ref false in
        let next =
          List.map
            (fun (f : Cfg.func) ->
              let rewritten = rewrite_trivial_calls_func table f in
              if rewritten <> f then changed := true;
              if rewritten = f then f
              else
                let return_globals =
                  match Hashtbl.find_opt return_global_demands f.label with
                  | Some return_globals -> return_globals
                  | None -> globals
                in
                cleanup_after_trivial_call_fold
                  global_init summaries globals return_globals removable_calls
                  rewritten)
            current
        in
        if not !changed || next = current then current
        else iterate (fuel - 1) next
  in
  (* A few waves are enough for chains such as main -> f -> g, where g becomes
     trivial first and f becomes trivial only after its call is folded. *)
  iterate 4 funcs

(* -------------------------------------------------------------------------- *)
(* Bounded constant evaluation for direct calls                               *)
(*                                                                            *)
(* If a direct call supplies only immediate arguments, execute the callee's    *)
(* CFG at compile time when the actually executed path is local-only:           *)
(* - local loads/stores are allowed;                                            *)
(* - arithmetic/branches/loops are allowed;                                     *)
(* - global loads/stores and nested calls reject the evaluation;                *)
(* - division/modulo by zero rejects the evaluation;                            *)
(* - a hard execution budget prevents compile-time nontermination.              *)
(*                                                                            *)
(* This handles parameterized pure loops that are awkward for symbolic loop     *)
(* analysis, e.g. walk(21, 3), without weakening any loop correctness gates.    *)
(* -------------------------------------------------------------------------- *)

let constant_eval_call_budget = 100_000

let constant_eval_func
    (f : Cfg.func)
    (args : int64 list) =
  if List.length args <> List.length f.params then None
  else
    let blocks = Hashtbl.create (max 8 (List.length f.blocks)) in
    List.iter
      (fun (block : Cfg.block) ->
        Hashtbl.replace blocks block.label block)
      f.blocks;

    let temps : (int, int64) Hashtbl.t =
      Hashtbl.create (max 16 f.temp_count)
    in
    let locals : (int, int64) Hashtbl.t =
      Hashtbl.create (max 8 (List.length f.params))
    in
    List.iter2
      (fun (param : Tcg.var) value ->
        Hashtbl.replace locals param.id (i32 value))
      f.params args;

    let budget = ref constant_eval_call_budget in
    let consume () =
      decr budget;
      !budget >= 0
    in
    let eval_operand = function
      | Tcg.Imm value -> Some (i32 value)
      | Tcg.Temp temp -> Hashtbl.find_opt temps temp
    in
    let set_temp temp value =
      Hashtbl.replace temps temp (i32 value)
    in

    let exec_instr = function
      | Tcg.Move (dst, src) -> (
          match eval_operand src with
          | Some value ->
              set_temp dst value;
              true
          | None -> false)
      | Tcg.Un (dst, op, src) -> (
          match eval_operand src with
          | Some value -> (
              match fold_unop op value with
              | Some result ->
                  set_temp dst result;
                  true
              | None -> false)
          | None -> false)
      | Tcg.Bin (dst, op, lhs, rhs) -> (
          match (eval_operand lhs, eval_operand rhs) with
          | Some lhs, Some rhs -> (
              match fold_binop op lhs rhs with
              | Some result ->
                  set_temp dst result;
                  true
              | None -> false)
          | _ -> false)
      | Tcg.Load (dst, Tcg.Local id) -> (
          match Hashtbl.find_opt locals id with
          | Some value ->
              set_temp dst value;
              true
          | None -> false)
      | Tcg.Store (Tcg.Local id, src) -> (
          match eval_operand src with
          | Some value ->
              Hashtbl.replace locals id (i32 value);
              true
          | None -> false)
      | Tcg.Load (_, Tcg.Global _)
      | Tcg.Store (Tcg.Global _, _)
      | Tcg.Call _ ->
          false
    in

    let rec exec_body = function
      | [] -> true
      | instr :: rest ->
          if consume () && exec_instr instr then
            exec_body rest
          else false
    in

    let rec run label =
      if not (consume ()) then None
      else
        match Hashtbl.find_opt blocks label with
        | None -> None
        | Some (block : Cfg.block) ->
            if not (exec_body block.body) then None
            else
              match block.term with
              | Cfg.Jump next ->
                  run next
              | Cfg.BranchZero (cond, if_zero, if_nonzero) -> (
                  match eval_operand cond with
                  | Some value ->
                      run
                        (if i32 value = 0L
                         then if_zero
                         else if_nonzero)
                  | None -> None)
              | Cfg.BranchNonZero (cond, if_nonzero, if_zero) -> (
                  match eval_operand cond with
                  | Some value ->
                      run
                        (if i32 value <> 0L
                         then if_nonzero
                         else if_zero)
                  | None -> None)
              | Cfg.BranchCompare
                  (op, lhs, rhs, if_true, if_false) -> (
                  match (eval_operand lhs, eval_operand rhs) with
                  | Some lhs, Some rhs -> (
                      match fold_binop op lhs rhs with
                      | Some result ->
                          run
                            (if truth result
                             then if_true
                             else if_false)
                      | None -> None)
                  | _ -> None)
              | Cfg.Return (Some value) ->
                  Option.map i32 (eval_operand value)
              | Cfg.Return None ->
                  None
    in
    run f.entry

let fold_constant_calls_program
    global_init summaries globals return_global_demands removable_calls
    (funcs : Cfg.func list) =
  let debug =
    Sys.getenv_opt "TOYC_DEBUG_CONST_EVAL" <> None
  in
  let rec iterate fuel current =
    if fuel = 0 then current
    else
      let func_by_label =
        Hashtbl.create (max 8 (List.length current))
      in
      List.iter
        (fun (f : Cfg.func) ->
          Hashtbl.replace func_by_label f.label f)
        current;

      let memo : (string, int64 option) Hashtbl.t =
        Hashtbl.create 32
      in
      let eval_call callee args =
        let key =
          callee
          ^ "("
          ^ String.concat "," (List.map Int64.to_string args)
          ^ ")"
        in
        match Hashtbl.find_opt memo key with
        | Some result -> result
        | None ->
            let result =
              match Hashtbl.find_opt func_by_label callee with
              | Some callee_func ->
                  constant_eval_func callee_func args
              | None -> None
            in
            Hashtbl.replace memo key result;
            result
      in

      let changed_any = ref false in
      let next =
        List.map
          (fun (f : Cfg.func) ->
            let replacements = ref 0 in
            let blocks =
              List.map
                (fun (block : Cfg.block) ->
                  let body =
                    List.map
                      (function
                        | Tcg.Call
                            (Some dst, callee, call_args) as instr ->
                            let const_args =
                              let rec collect acc = function
                                | [] -> Some (List.rev acc)
                                | Tcg.Imm value :: rest ->
                                    collect (i32 value :: acc) rest
                                | Tcg.Temp _ :: _ ->
                                    None
                              in
                              collect [] call_args
                            in
                            (match const_args with
                            | Some args -> (
                                match eval_call callee args with
                                | Some value ->
                                    incr replacements;
                                    Tcg.Move
                                      (dst, Tcg.Imm (i32 value))
                                | None -> instr)
                            | None -> instr)
                        | instr -> instr)
                      block.body
                  in
                  { block with body })
                f.blocks
            in
            if !replacements = 0 then f
            else begin
              changed_any := true;
              if debug then
                Printf.eprintf
                  "const-eval-fold caller=%s replaced=%d\n%!"
                  f.name !replacements;
              let rewritten =
                Cfg.rebuild_edges { f with blocks }
              in
              let return_globals =
                match
                  Hashtbl.find_opt return_global_demands f.label
                with
                | Some return_globals -> return_globals
                | None -> globals
              in
              let cleaned =
                optimize_func
                  global_init summaries globals
                  return_globals removable_calls rewritten
              in
              debug_cfg_validation
                "const-eval-cleanup" cleaned;
              cleaned
            end)
          current
      in
      if !changed_any then iterate (fuel - 1) next
      else next
  in
  iterate 4 funcs

let late_whole_program_constantization_enabled () =
  Sys.getenv_opt "TOYC_ENABLE_LATE_CONST_WHOLE_PROGRAM" <> None

let optimize_cfg (analysis : Semant.analysis) (cfg : Cfg.program) =
  incr analysis_cache_generation;
  last_liveness_cache := None;
  last_dominator_cache := None;
  let cfg = { Cfg.funcs = List.map tailrec_elim_func cfg.funcs } in
  let source_funcs = cfg.funcs in
  let global_init, globals =
    List.fold_left
      (fun (init, set) (g : Semant.global_decl) ->
        let place = Tcg.Global g.label in
        (PlaceMap.add place (CpConst g.init) init, PlaceSet.add place set))
      (PlaceMap.empty, PlaceSet.empty) analysis.globals
  in
  let summaries = compute_func_summaries globals cfg.funcs in
  let removable_calls =
    compute_dead_call_removable_funcs summaries globals cfg.funcs
  in
  let return_global_demands =
    compute_return_global_demands summaries globals cfg.funcs
  in
  let funcs_rev =
    List.fold_left
      (fun acc (f : Cfg.func) ->
        let return_globals =
          match Hashtbl.find_opt return_global_demands f.label with
          | Some return_globals -> return_globals
          | None -> globals
        in
        let optimized =
          optimize_func global_init summaries globals return_globals removable_calls f
        in
        optimized :: acc)
      [] cfg.funcs
  in
  let optimized_funcs = List.rev funcs_rev in
  let optimized_funcs =
    if late_whole_program_constantization_enabled () then
      fold_constant_calls_program
        global_init summaries globals return_global_demands removable_calls
        optimized_funcs
    else
      optimized_funcs
  in
  let optimized_funcs =
    if late_whole_program_constantization_enabled () then
      specialize_constant_params_program
        source_funcs
        global_init summaries globals return_global_demands removable_calls
        optimized_funcs
    else
      optimized_funcs
  in
  let optimized_funcs =
    inline_late_scalar_calls_program
      global_init summaries globals return_global_demands removable_calls
      optimized_funcs
  in
  let optimized_funcs =
    inline_late_branch_calls_program
      global_init summaries globals return_global_demands removable_calls
      optimized_funcs
  in
  let optimized_funcs =
    inline_small_hot_calls_program
      global_init summaries globals return_global_demands removable_calls
      optimized_funcs
  in
  let optimized_funcs =
    fold_trivial_calls_program
      global_init summaries globals return_global_demands removable_calls
      optimized_funcs
  in
  { Cfg.funcs = optimized_funcs }
